            Context.Response.Cookies.Add(FinacialYearDefaultID);
            return "done";
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void ChangeUserPassword()
        {
            CommanResponse comman = new CommanResponse();
            JavaScriptSerializer js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };

            try
            {
                var request = HttpContext.Current.Request;
                string oldPassword = request.Params["OldPassword"] ?? "";
                string newPassword = request.Params["NewPassword"] ?? "";
                string confirmPassword = request.Params["ConfirmPassword"] ?? "";

                if (string.IsNullOrWhiteSpace(oldPassword) || string.IsNullOrWhiteSpace(newPassword))
                {
                    comman.Code = 400;
                    comman.Message = "Please enter both current and new password.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                if (newPassword != confirmPassword)
                {
                    comman.Code = 400;
                    comman.Message = "New password and Confirm password do not match.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                if (newPassword.Length < 4)
                {
                    comman.Code = 400;
                    comman.Message = "New password must be at least 4 characters long.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                int userId = 0;
                if (Context.Request.Cookies["UserIDs"] != null)
                {
                    string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                    if (cookieVal.Contains("=")) cookieVal = cookieVal.Split('=')[1];
                    int.TryParse(cookieVal, out userId);
                }

                if (userId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Session expired. Please log in again.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string hashedOldPassword = getMd5Hash(oldPassword);
                string hashedNewPassword = getMd5Hash(newPassword);

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    string checkSql = "SELECT UserAccountName, UserAccountPassword FROM UserAccountMaster WHERE UserAccountId = @UserID";
                    string currentDbPassword = "";
                    string username = "";

                    using (SqlCommand cmdCheck = new SqlCommand(checkSql, con))
                    {
                        cmdCheck.Parameters.AddWithValue("@UserID", userId);
                        using (SqlDataReader rdr = cmdCheck.ExecuteReader())
                        {
                            if (rdr.Read())
                            {
                                username = rdr["UserAccountName"].ToString();
                                currentDbPassword = rdr["UserAccountPassword"].ToString();
                            }
                        }
                    }

                    if (string.IsNullOrEmpty(username))
                    {
                        comman.Code = 404;
                        comman.Message = "User account not found.";
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }

                    if (!string.Equals(currentDbPassword, hashedOldPassword, StringComparison.OrdinalIgnoreCase))
                    {
                        comman.Code = 400;
                        comman.Message = "Current password is incorrect.";
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }

                    string updateSql = "UPDATE UserAccountMaster SET UserAccountPassword = @NewPassword WHERE UserAccountId = @UserID";
                    using (SqlCommand cmdUpdate = new SqlCommand(updateSql, con))
                    {
                        cmdUpdate.Parameters.AddWithValue("@NewPassword", hashedNewPassword);
                        cmdUpdate.Parameters.AddWithValue("@UserID", userId);
                        int rows = cmdUpdate.ExecuteNonQuery();

                        if (rows > 0)
                        {
                            AuditLogHelper.Log(
                                module: "User Security",
                                action: "PASSWORD_CHANGE",
                                tableName: "UserAccountMaster",
                                recordId: userId.ToString(),
                                description: $"User '{username}' (ID #{userId}) successfully changed their password."
                            );

                            comman.Code = 200;
                            comman.Message = "Password changed successfully!";
                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "Failed to update password. Please try again.";
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("User Security", "ChangeUserPassword", ex);
                comman.Code = 500;
                comman.Message = "An error occurred while changing password: " + ex.Message;
            }

            Context.Response.Write(js.Serialize(comman));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void AdminChangeUserPassword()
        {
            CommanResponse comman = new CommanResponse();
            JavaScriptSerializer js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };

            try
            {
                var request = HttpContext.Current.Request;
                int targetUserId = 0;
                int.TryParse(request.Params["TargetUserId"], out targetUserId);
                string newPassword = request.Params["NewPassword"] ?? "";

                if (targetUserId <= 0 || string.IsNullOrWhiteSpace(newPassword))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid user ID or empty new password.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                if (newPassword.Length < 4)
                {
                    comman.Code = 400;
                    comman.Message = "New password must be at least 4 characters long.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string hashedNewPassword = getMd5Hash(newPassword);

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    string getUserSql = "SELECT UserAccountName FROM UserAccountMaster WHERE UserAccountId = @UserID";
                    string username = "";
                    using (SqlCommand cmdGet = new SqlCommand(getUserSql, con))
                    {
                        cmdGet.Parameters.AddWithValue("@UserID", targetUserId);
                        object res = cmdGet.ExecuteScalar();
                        if (res != null) username = res.ToString();
                    }

                    if (string.IsNullOrEmpty(username))
                    {
                        comman.Code = 404;
                        comman.Message = "User account not found.";
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }

                    string updateSql = "UPDATE UserAccountMaster SET UserAccountPassword = @NewPassword WHERE UserAccountId = @UserID";
                    using (SqlCommand cmdUpdate = new SqlCommand(updateSql, con))
                    {
                        cmdUpdate.Parameters.AddWithValue("@NewPassword", hashedNewPassword);
                        cmdUpdate.Parameters.AddWithValue("@UserID", targetUserId);
                        int rows = cmdUpdate.ExecuteNonQuery();

                        if (rows > 0)
                        {
                            AuditLogHelper.Log(
                                module: "User Security",
                                action: "ADMIN_PASSWORD_RESET",
                                tableName: "UserAccountMaster",
                                recordId: targetUserId.ToString(),
                                description: $"Password reset for user '{username}' (ID #{targetUserId}) by administrator."
                            );

                            comman.Code = 200;
                            comman.Message = $"Password for user '{username}' reset successfully!";
                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "Failed to reset password. Please try again.";
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("User Security", "AdminChangeUserPassword", ex);
                comman.Code = 500;
                comman.Message = "An error occurred while resetting password: " + ex.Message;
            }

            Context.Response.Write(js.Serialize(comman));
        }
        [WebMethod]
        [System.Web.Script.Services.ScriptMethod]
        public string getLoginDetails(string username, string password)
        {
            string msg = "incorrect";

            try
            {
                if (string.IsNullOrWhiteSpace(username) || string.IsNullOrEmpty(password))
                    return msg;

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                string sql = @"
            SELECT
                UA.UserAccountId,
                UA.UserAccountName,
                UA.UserRole,
                UA.UserAccountMobileNo,
                UA.UserAccountProfile,
                UA.AllowLogin,
                CM.CompanyId,
                CM.CompanyName,
                CM.State,
                FY.FinancialYearID
            FROM UserAccountMaster UA
            INNER JOIN CompanyMaster CM
                ON UA.CompanyId = CM.CompanyId
               AND CM.is_default = 1
            LEFT JOIN FinancialYearMaster FY
                ON FY.IsDefault = 1
            WHERE
                (UA.UserAccountEmail = @username
                 OR UA.UserAccountMobileNo = @username)
                AND UA.UserAccountPassword = @password;";

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.Parameters.Add("@username", SqlDbType.NVarChar, 100).Value = username;
                    cmd.Parameters.Add("@password", SqlDbType.NVarChar, 100).Value =
                        getMd5Hash(password);

                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        if (!rdr.Read())
                        {
                            try
                            {
                                AuditLogHelper.LogLogin(null, username, "Failed", "Invalid Credentials");
                            }
                            catch (Exception ex)
                            {
                                System.Diagnostics.Trace.TraceError("Login audit failed: " + ex);
                            }

                            return "incorrect";
                        }

                        string userID = rdr["UserAccountId"] == DBNull.Value
                            ? ""
                            : rdr["UserAccountId"].ToString();

                        string accountName = rdr["UserAccountName"] == DBNull.Value
                            ? username
                            : rdr["UserAccountName"].ToString();

                        string allowLogin = rdr["AllowLogin"] == DBNull.Value
                            ? ""
                            : rdr["AllowLogin"].ToString();

                        if (string.IsNullOrWhiteSpace(userID))
                        {
                            try
                            {
                                AuditLogHelper.LogLogin(null, username, "Failed", "Invalid User Account ID");
                            }
                            catch (Exception ex)
                            {
                                System.Diagnostics.Trace.TraceError("Login audit failed: " + ex);
                            }

                            return "incorrect";
                        }

                        int? parsedUid = int.TryParse(userID, out int uid)
                            ? (int?)uid
                            : null;

                        if (allowLogin != "1")
                        {
                            try
                            {
                                AuditLogHelper.LogLogin(parsedUid, accountName, "Failed", "Account Deactivated");
                            }
                            catch (Exception ex)
                            {
                                System.Diagnostics.Trace.TraceError("Login audit failed: " + ex);
                            }

                            return "deactivate";
                        }

                        string companyID = rdr["CompanyId"] == DBNull.Value
                            ? ""
                            : rdr["CompanyId"].ToString();

                        string companyName = rdr["CompanyName"] == DBNull.Value
                            ? ""
                            : rdr["CompanyName"].ToString();

                        string companyState = rdr["State"] == DBNull.Value
                            ? ""
                            : rdr["State"].ToString();

                        string financialYearID = rdr["FinancialYearID"] == DBNull.Value
                            ? ""
                            : rdr["FinancialYearID"].ToString();

                        bool isSecure = Context.Request.IsSecureConnection;

                        Action<string, string> addCookie = (cookieName, cookieValue) =>
                        {
                            HttpCookie cookie = new HttpCookie(cookieName);
                            cookie.Values[cookieName] = cookieValue ?? "";
                            cookie.Expires = DateTime.Now.AddDays(30);
                            cookie.HttpOnly = true;
                            cookie.Secure = isSecure;
                            cookie.Path = "/";
                            Context.Response.Cookies.Add(cookie);
                        };

                        addCookie("UserIDs", userID);
                        addCookie("UserName", accountName);
                        addCookie("CompanyID", companyID);
                        addCookie("CompanyName", companyName);
                        addCookie("CompanyState", companyState);
                        addCookie("FinacialYearDefaultID", financialYearID);

                        try
                        {
                            AuditLogHelper.LogLogin(parsedUid, accountName, "Success");
                        }
                        catch (Exception ex)
                        {
                            System.Diagnostics.Trace.TraceError("Login audit failed: " + ex);
                        }

                        msg = "done";
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.TraceError("getLoginDetails failed: " + ex);
                msg = "incorrect";
            }

            return msg;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string getItemUnit()
        {
            DataTable dt = new DataTable();
            JavaScriptSerializer jsSerializer =
                new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue };

            List<Dictionary<string, object>> parentRow =
                new List<Dictionary<string, object>>();

            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(
                    "SELECT * FROM dbo.UnitMaster ORDER BY Unit", con))
                using (SqlDataAdapter dad = new SqlDataAdapter(cmd))
                {
                    dad.Fill(dt);
                }

                foreach (DataRow row in dt.Rows)
                {
                    Dictionary<string, object> childRow =
                        new Dictionary<string, object>();

                    foreach (DataColumn col in dt.Columns)
                    {
                        childRow.Add(
                            col.ColumnName,
                            row[col] == DBNull.Value ? null : row[col]
                        );
                    }

                    parentRow.Add(childRow);
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Master Data", "getItemUnit", ex);
            }

            return jsSerializer.Serialize(parentRow);
        }
