        #region Company Master (CompanyMaster.cshtml)
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getCompanyMasterById(string id)
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<CompanyMaster> listUser = new List<CompanyMaster>();
            CompanyMasterResponse response = new CompanyMasterResponse();

            try
            {
                int companyId;

                if (!int.TryParse(id, out companyId) || companyId <= 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid company id.";
                    response.listCompanyMaster = listUser;
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                string sql = @"
            SELECT
                CM.*,
                POS.StateTitle
            FROM dbo.CompanyMaster CM
            LEFT JOIN dbo.PlaceOfSupplyMaster POS
                ON CM.State = POS.GSTStateCode
            WHERE CM.CompanyId = @CompanyId;";

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;

                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            CompanyMaster condition = new CompanyMaster();

                            condition.CompanyId = Convert.ToInt32(rdr["CompanyId"]);
                            condition.CompanyName = rdr["CompanyName"] == DBNull.Value ? "" : rdr["CompanyName"].ToString();
                            condition.MobileNo = rdr["MobileNo"] == DBNull.Value ? "" : rdr["MobileNo"].ToString();
                            condition.AlterMobileNo = rdr["AlterMobileNo"] == DBNull.Value ? "" : rdr["AlterMobileNo"].ToString();
                            condition.Email = rdr["Email"] == DBNull.Value ? "" : rdr["Email"].ToString();
                            condition.BusinessAddress = rdr["BusinessAddress"] == DBNull.Value ? "" : rdr["BusinessAddress"].ToString();
                            condition.GSTIN = rdr["GSTIN"] == DBNull.Value ? "" : rdr["GSTIN"].ToString();
                            condition.State = rdr["State"] == DBNull.Value ? "" : rdr["State"].ToString();
                            condition.StateTitle = rdr["StateTitle"] == DBNull.Value ? "" : rdr["StateTitle"].ToString();
                            condition.BusinessType = rdr["BusinessType"] == DBNull.Value ? "" : rdr["BusinessType"].ToString();
                            condition.BusinessCategory = rdr["BusinessCategory"] == DBNull.Value ? "" : rdr["BusinessCategory"].ToString();
                            condition.BusinessDescription = rdr["BusinessDescription"] == DBNull.Value ? "" : rdr["BusinessDescription"].ToString();
                            condition.BankName = rdr["BankName"] == DBNull.Value ? "" : rdr["BankName"].ToString();
                            condition.ACNo = rdr["ACNo"] == DBNull.Value ? "" : rdr["ACNo"].ToString();
                            condition.IFSC = rdr["IFSC"] == DBNull.Value ? "" : rdr["IFSC"].ToString();
                            condition.CompanyLogo = rdr["CompanyLogo"] == DBNull.Value ? "" : rdr["CompanyLogo"].ToString();
                            condition.Sign = rdr["Sign"] == DBNull.Value ? "" : rdr["Sign"].ToString();
                            condition.is_default = rdr["is_default"] == DBNull.Value ? "" : rdr["is_default"].ToString();
                            condition.SupportNumber = rdr["SupportNumber"] == DBNull.Value ? "" : rdr["SupportNumber"].ToString();

                            listUser.Add(condition);
                        }
                    }
                }

                response.Code = 200;
                response.Message = listUser.Count > 0 ? "Success" : "Company not found.";
                response.listCompanyMaster = listUser;
            }
            catch (Exception ex)
            {
                try
                {
                    AuditLogHelper.LogError("Company Master", "getCompanyMasterById", ex);
                }
                catch
                {
                    System.Diagnostics.Trace.TraceError(ex.ToString());
                }

                response.Code = 500;
                response.Message = "An error occurred while retrieving company details.";
                response.listCompanyMaster = new List<CompanyMaster>();
            }

            Context.Response.Write(js.Serialize(response));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void editCompanyMaster()
        {
            CommanResponse comman = new CommanResponse();
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            HttpRequest request = HttpContext.Current.Request;

            string newLogo = "";
            string newSign = "";
            string oldLogo = "";
            string oldSign = "";

            try
            {
                int companyId;
                if (!int.TryParse(request.Params["CompanyIds"], out companyId) || companyId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid company id.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string companyName = request.Params["CompanyNames"] ?? "";
                string email = request.Params["Email"] ?? "";
                string mobileNo = request.Params["MobileNo"] ?? "";
                string alterMobileNo = request.Params["AlterMobileNo"] ?? "";
                string isDefault = request.Params["is_default"] ?? "";
                string state = request.Params["State"] ?? "";
                string businessAddress = request.Params["BusinessAddress"] ?? "";
                string gstin = request.Params["GSTIN"] ?? "";
                string bankName = request.Params["BankName"] ?? "";
                string acNo = request.Params["ACNo"] ?? "";
                string ifsc = request.Params["IFSC"] ?? "";
                string supportNumber = request.Params["SupportNumber"] ?? "";

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction = con.BeginTransaction())
                    {
                        try
                        {
                            string selectSql = @"
                        SELECT CompanyLogo, Sign
                        FROM dbo.CompanyMaster WITH (UPDLOCK, ROWLOCK)
                        WHERE CompanyId = @CompanyId;";

                            using (SqlCommand selectCmd = new SqlCommand(selectSql, con, transaction))
                            {
                                selectCmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;

                                using (SqlDataReader rdr = selectCmd.ExecuteReader())
                                {
                                    if (!rdr.Read())
                                    {
                                        transaction.Rollback();
                                        comman.Code = 404;
                                        comman.Message = "Company not found.";
                                        Context.Response.Write(js.Serialize(comman));
                                        return;
                                    }

                                    oldLogo = rdr["CompanyLogo"] == DBNull.Value ? "" : rdr["CompanyLogo"].ToString();
                                    oldSign = rdr["Sign"] == DBNull.Value ? "" : rdr["Sign"].ToString();
                                }
                            }

                            HttpPostedFile logoFile = request.Files["CompanyLogo"];
                            HttpPostedFile signFile = request.Files["Sign"];

                            if (logoFile != null && logoFile.ContentLength > 0)
                            {
                                newLogo = "CompanyPictures/" + RandomString(6, true) + Path.GetFileName(logoFile.FileName);
                                string logoPath = Server.MapPath("~/" + newLogo);

                                Directory.CreateDirectory(Path.GetDirectoryName(logoPath));
                                GenerateThumbnails(0.2, logoFile.InputStream, logoPath);
                            }

                            if (signFile != null && signFile.ContentLength > 0)
                            {
                                newSign = "CompanyPictures/" + RandomString(6, true) + Path.GetFileName(signFile.FileName);
                                string signPath = Server.MapPath("~/" + newSign);

                                Directory.CreateDirectory(Path.GetDirectoryName(signPath));
                                GenerateThumbnails(0.2, signFile.InputStream, signPath);
                            }

                            bool clearLogo = logoFile == null &&
                                request.Params["CompanyLogo"] != null &&
                                request.Params["CompanyLogo"] == "";

                            bool clearSign = signFile == null &&
                                request.Params["Sign"] != null &&
                                request.Params["Sign"] == "";

                            if (isDefault == "1")
                            {
                                using (SqlCommand defaultCmd = new SqlCommand(
                                    @"UPDATE dbo.CompanyMaster
                              SET is_default = '0'
                              WHERE UserAccountId = (
                                  SELECT UserAccountId
                                  FROM dbo.CompanyMaster
                                  WHERE CompanyId = @CompanyId
                              )", con, transaction))
                                {
                                    defaultCmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;
                                    defaultCmd.ExecuteNonQuery();
                                }
                            }

                            string updateSql = @"
                        UPDATE dbo.CompanyMaster
                        SET
                            CompanyName = @CompanyName,
                            Email = @Email,
                            MobileNo = @MobileNo,
                            AlterMobileNo = @AlterMobileNo,
                            is_default = CASE WHEN @IsDefault = '' THEN is_default ELSE @IsDefault END,
                            State = @State,
                            BusinessAddress = @BusinessAddress,
                            GSTIN = @GSTIN,
                            BankName = @BankName,
                            ACNo = @ACNo,
                            IFSC = @IFSC,
                            SupportNumber = @SupportNumber,
                            CompanyLogo = CASE
                                WHEN @NewLogo <> '' THEN @NewLogo
                                WHEN @ClearLogo = 1 THEN ''
                                ELSE CompanyLogo
                            END,
                            Sign = CASE
                                WHEN @NewSign <> '' THEN @NewSign
                                WHEN @ClearSign = 1 THEN ''
                                ELSE Sign
                            END
                        WHERE CompanyId = @CompanyId;";

                            using (SqlCommand cmd = new SqlCommand(updateSql, con, transaction))
                            {
                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;
                                cmd.Parameters.Add("@CompanyName", SqlDbType.NVarChar).Value = companyName;
                                cmd.Parameters.Add("@Email", SqlDbType.NVarChar).Value = email;
                                cmd.Parameters.Add("@MobileNo", SqlDbType.NVarChar).Value = mobileNo;
                                cmd.Parameters.Add("@AlterMobileNo", SqlDbType.NVarChar).Value = alterMobileNo;
                                cmd.Parameters.Add("@IsDefault", SqlDbType.NVarChar).Value = isDefault;
                                cmd.Parameters.Add("@State", SqlDbType.NVarChar).Value = state;
                                cmd.Parameters.Add("@BusinessAddress", SqlDbType.NVarChar).Value = businessAddress;
                                cmd.Parameters.Add("@GSTIN", SqlDbType.NVarChar).Value = gstin;
                                cmd.Parameters.Add("@BankName", SqlDbType.NVarChar).Value = bankName;
                                cmd.Parameters.Add("@ACNo", SqlDbType.NVarChar).Value = acNo;
                                cmd.Parameters.Add("@IFSC", SqlDbType.NVarChar).Value = ifsc;
                                cmd.Parameters.Add("@SupportNumber", SqlDbType.NVarChar).Value = supportNumber;
                                cmd.Parameters.Add("@NewLogo", SqlDbType.NVarChar).Value = newLogo;
                                cmd.Parameters.Add("@NewSign", SqlDbType.NVarChar).Value = newSign;
                                cmd.Parameters.Add("@ClearLogo", SqlDbType.Bit).Value = clearLogo;
                                cmd.Parameters.Add("@ClearSign", SqlDbType.Bit).Value = clearSign;

                                int affectedRows = cmd.ExecuteNonQuery();

                                if (affectedRows <= 0)
                                {
                                    transaction.Rollback();
                                    comman.Code = 410;
                                    comman.Message = "Problem has been occurred while submitting your data.";
                                    Context.Response.Write(js.Serialize(comman));
                                    return;
                                }
                            }

                            transaction.Commit();

                            comman.Code = 201;
                            comman.Message = "Record has been updated successfully.";
                        }
                        catch
                        {
                            transaction.Rollback();
                            throw;
                        }
                    }
                }

                // Delete old files only after the database update succeeds.
                if (!string.IsNullOrEmpty(newLogo) && !string.IsNullOrEmpty(oldLogo))
                {
                    string oldPath = Server.MapPath("~/" + oldLogo.TrimStart('/'));
                    if (File.Exists(oldPath))
                    {
                        try { File.Delete(oldPath); } catch { }
                    }
                }

                if (!string.IsNullOrEmpty(newSign) && !string.IsNullOrEmpty(oldSign))
                {
                    string oldPath = Server.MapPath("~/" + oldSign.TrimStart('/'));
                    if (File.Exists(oldPath))
                    {
                        try { File.Delete(oldPath); } catch { }
                    }
                }

                if (request.Params["CompanyLogo"] == "" && !string.IsNullOrEmpty(oldLogo))
                {
                    string oldPath = Server.MapPath("~/" + oldLogo.TrimStart('/'));
                    if (File.Exists(oldPath))
                    {
                        try { File.Delete(oldPath); } catch { }
                    }
                }

                if (request.Params["Sign"] == "" && !string.IsNullOrEmpty(oldSign))
                {
                    string oldPath = Server.MapPath("~/" + oldSign.TrimStart('/'));
                    if (File.Exists(oldPath))
                    {
                        try { File.Delete(oldPath); } catch { }
                    }
                }
            }
            catch (SqlException ex)
            {
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }

                try { AuditLogHelper.LogError("Company Master", "editCompanyMaster", ex); }
                catch { System.Diagnostics.Trace.TraceError(ex.ToString()); }
            }
            catch (Exception ex)
            {
                comman.Code = 410;
                comman.Message = "Problem has been occurred while submitting your data.";

                try { AuditLogHelper.LogError("Company Master", "editCompanyMaster", ex); }
                catch { System.Diagnostics.Trace.TraceError(ex.ToString()); }
            }

            Context.Response.Write(js.Serialize(comman));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertCompanyMaster()
        {
            CommanResponse comman = new CommanResponse();
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            HttpRequest request = HttpContext.Current.Request;

            string imagePath = "";
            string signaturePath = "";
            bool isSaved = false;

            try
            {
                string companyName = request.Params["CompanyNames"] ?? "";
                string mobileNo = request.Params["MobileNo"] ?? "";
                string alterMobileNo = request.Params["AlterMobileNo"] ?? "";
                string email = request.Params["Email"] ?? "";
                string businessAddress = request.Params["BusinessAddress"] ?? "";
                string gstin = request.Params["GSTIN"] ?? "";
                string state = request.Params["State"] ?? "";
                string businessType = request.Params["BusinessType"] ?? "";
                string businessCategory = request.Params["BusinessCategory"] ?? "";
                string businessDescription = request.Params["BusinessDescription"] ?? "";
                string bankName = request.Params["BankName"] ?? "";
                string acNo = request.Params["ACNo"] ?? "";
                string ifsc = request.Params["IFSC"] ?? "";
                string isDefault = request.Params["is_default"] ?? "0";

                string rawUserId = request.Cookies["UserIDs"]?.Value ?? "";

                int userId;
                if (!int.TryParse(rawUserId.Split('=').Last(), out userId) || userId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user session.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                HttpPostedFile photo = request.Files["CompanyLogo"];
                if (photo != null && photo.ContentLength > 0)
                {
                    imagePath = "CompanyPictures/" + RandomString(6, true) +
                                Path.GetFileName(photo.FileName);

                    string targetPath = Server.MapPath("~/" + imagePath);
                    Directory.CreateDirectory(Path.GetDirectoryName(targetPath));

                    GenerateThumbnails(0.2, photo.InputStream, targetPath);
                }

                HttpPostedFile photoSign = request.Files["Sign"];
                if (photoSign != null && photoSign.ContentLength > 0)
                {
                    signaturePath = "CompanyPictures/" + RandomString(6, true) +
                                    Path.GetFileName(photoSign.FileName);

                    string targetSignPath = Server.MapPath("~/" + signaturePath);
                    Directory.CreateDirectory(Path.GetDirectoryName(targetSignPath));

                    GenerateThumbnails(0.2, photoSign.InputStream, targetSignPath);
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction = con.BeginTransaction())
                    {
                        try
                        {
                            if (isDefault == "1")
                            {
                                string defaultSql = @"
                            UPDATE dbo.CompanyMaster
                            SET is_default = '0'
                            WHERE UserAccountId = @UserAccountId;";

                                using (SqlCommand defaultCmd = new SqlCommand(defaultSql, con, transaction))
                                {
                                    defaultCmd.Parameters.Add("@UserAccountId", SqlDbType.Int).Value = userId;
                                    defaultCmd.ExecuteNonQuery();
                                }
                            }

                            string insertSql = @"
                        INSERT INTO dbo.CompanyMaster
                        (
                            CompanyName,
                            MobileNo,
                            AlterMobileNo,
                            Email,
                            BusinessAddress,
                            GSTIN,
                            State,
                            BusinessType,
                            BusinessCategory,
                            BusinessDescription,
                            BankName,
                            ACNo,
                            IFSC,
                            CompanyLogo,
                            Sign,
                            is_default,
                            UserAccountId
                        )
                        VALUES
                        (
                            @CompanyName,
                            @MobileNo,
                            @AlterMobileNo,
                            @Email,
                            @BusinessAddress,
                            @GSTIN,
                            @State,
                            @BusinessType,
                            @BusinessCategory,
                            @BusinessDescription,
                            @BankName,
                            @ACNo,
                            @IFSC,
                            @CompanyLogo,
                            @Sign,
                            @IsDefault,
                            @UserAccountId
                        );";

                            using (SqlCommand cmd = new SqlCommand(insertSql, con, transaction))
                            {
                                cmd.Parameters.Add("@CompanyName", SqlDbType.NVarChar).Value = companyName;
                                cmd.Parameters.Add("@MobileNo", SqlDbType.NVarChar).Value = mobileNo;
                                cmd.Parameters.Add("@AlterMobileNo", SqlDbType.NVarChar).Value = alterMobileNo;
                                cmd.Parameters.Add("@Email", SqlDbType.NVarChar).Value = email;
                                cmd.Parameters.Add("@BusinessAddress", SqlDbType.NVarChar).Value = businessAddress;
                                cmd.Parameters.Add("@GSTIN", SqlDbType.NVarChar).Value = gstin;
                                cmd.Parameters.Add("@State", SqlDbType.NVarChar).Value = state;
                                cmd.Parameters.Add("@BusinessType", SqlDbType.NVarChar).Value = businessType;
                                cmd.Parameters.Add("@BusinessCategory", SqlDbType.NVarChar).Value = businessCategory;
                                cmd.Parameters.Add("@BusinessDescription", SqlDbType.NVarChar).Value = businessDescription;
                                cmd.Parameters.Add("@BankName", SqlDbType.NVarChar).Value = bankName;
                                cmd.Parameters.Add("@ACNo", SqlDbType.NVarChar).Value = acNo;
                                cmd.Parameters.Add("@IFSC", SqlDbType.NVarChar).Value = ifsc;
                                cmd.Parameters.Add("@CompanyLogo", SqlDbType.NVarChar).Value = imagePath;
                                cmd.Parameters.Add("@Sign", SqlDbType.NVarChar).Value = signaturePath;
                                cmd.Parameters.Add("@IsDefault", SqlDbType.NVarChar).Value = isDefault;
                                cmd.Parameters.Add("@UserAccountId", SqlDbType.Int).Value = userId;

                                int rows = cmd.ExecuteNonQuery();

                                if (rows <= 0)
                                {
                                    throw new Exception("Company record was not inserted.");
                                }
                            }

                            transaction.Commit();
                            isSaved = true;

                            comman.Code = 201;
                            comman.Message = "Record has been saved successfully.";
                        }
                        catch
                        {
                            transaction.Rollback();
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }

                try { AuditLogHelper.LogError("Company Master", "insertCompanyMaster", ex); }
                catch { System.Diagnostics.Trace.TraceError(ex.ToString()); }
            }
            catch (Exception ex)
            {
                comman.Code = 410;
                comman.Message = "Problem has been occurred while submitting your data.";

                try { AuditLogHelper.LogError("Company Master", "insertCompanyMaster", ex); }
                catch { System.Diagnostics.Trace.TraceError(ex.ToString()); }
            }
            finally
            {
                // Remove newly uploaded files if database save failed.
                if (!isSaved)
                {
                    if (!string.IsNullOrEmpty(imagePath))
                    {
                        string path = Server.MapPath("~/" + imagePath);
                        try { if (File.Exists(path)) File.Delete(path); } catch { }
                    }

                    if (!string.IsNullOrEmpty(signaturePath))
                    {
                        string path = Server.MapPath("~/" + signaturePath);
                        try { if (File.Exists(path)) File.Delete(path); } catch { }
                    }
                }
            }

            Context.Response.Write(js.Serialize(comman));
        }

