            string companyName = "";
            bool isDefault = false;

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();

                using (SqlTransaction tran = con.BeginTransaction())
                {
                    try
                    {
                        // 1. Fetch company record
                        using (SqlCommand cmdFetch = new SqlCommand(
                            @"SELECT is_default, CompanyName, CompanyLogo, Sign
                      FROM dbo.CompanyMaster WITH (UPDLOCK, ROWLOCK)
                      WHERE CompanyId = @CompanyId",
                            con, tran))
                        {
                            cmdFetch.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                            using (SqlDataReader rdr = cmdFetch.ExecuteReader())
                            {
                                if (!rdr.Read())
                                {
                                    rdr.Close();
                                    tran.Rollback();

                                    comman.Code = 404;
                                    comman.Message = "Record not found.";
                                    Context.Response.Write(js.Serialize(comman));
                                    return;
                                }

                                isDefault = rdr["is_default"] != DBNull.Value &&
                                            Convert.ToInt32(rdr["is_default"]) == 1;

                                companyName = rdr["CompanyName"] != DBNull.Value
                                    ? rdr["CompanyName"].ToString()
                                    : "";

                                photo = rdr["CompanyLogo"] != DBNull.Value
                                    ? rdr["CompanyLogo"].ToString()
                                    : "";

                                sign = rdr["Sign"] != DBNull.Value
                                    ? rdr["Sign"].ToString()
                                    : "";
                            }
                        }

                        // 2. Protect default company
                        if (isDefault)
                        {
                            tran.Rollback();

                            comman.Code = 400;
                            comman.Message = "Cannot delete the default active company.";
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }

                        // 3. Check all 42 CompanyId dependent tables
                        string depCheckSql = @"
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM [dbo].[BrokerMaster] WHERE CompanyId = @id) THEN 'BrokerMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[ColorGroupMaster] WHERE CompanyId = @id) THEN 'ColorGroupMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[DesignCategoryMaster] WHERE CompanyId = @id) THEN 'DesignCategoryMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[DesignColorMatchingFormMaster] WHERE CompanyId = @id) THEN 'DesignColorMatchingFormMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[DesignEntryFormMaster] WHERE CompanyId = @id) THEN 'DesignEntryFormMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[DesignerMaster] WHERE CompanyId = @id) THEN 'DesignerMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[DesignSpecificationMaster] WHERE CompanyId = @id) THEN 'DesignSpecificationMaster'
    WHEN EXISTS (SELECT 1 FROM [weavelanesoftDB].[DynamicReportMaster] WHERE CompanyId = @id) THEN 'DynamicReportMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[GodownMaster] WHERE CompanyId = @id) THEN 'GodownMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[GSTSLABMaster] WHERE CompanyId = @id) THEN 'GSTSLABMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[ItemMaster] WHERE CompanyId = @id) THEN 'ItemMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[JobberInwardMaster] WHERE CompanyId = @id) THEN 'JobberInwardMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[JobberMaster] WHERE CompanyId = @id) THEN 'JobberMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[JobberOutwardMaster] WHERE CompanyId = @id) THEN 'JobberOutwardMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[LocationMaster] WHERE CompanyId = @id) THEN 'LocationMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[MaterialMaster] WHERE CompanyId = @id) THEN 'MaterialMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[PartyMaster] WHERE CompanyId = @id) THEN 'PartyMaster'
    WHEN EXISTS (SELECT 1 FROM [weavelanesoftDB].[ProcessChallanMaster] WHERE CompanyId = @id) THEN 'ProcessChallanMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[ProcessMaster] WHERE CompanyId = @id) THEN 'ProcessMaster'
    WHEN EXISTS (SELECT 1 FROM [weavelanesoftDB].[ProcessStockLedger] WHERE CompanyId = @id) THEN 'ProcessStockLedger'
    WHEN EXISTS (SELECT 1 FROM [dbo].[ProcessTransactionDetail] WHERE CompanyId = @id) THEN 'ProcessTransactionDetail'
    WHEN EXISTS (SELECT 1 FROM [dbo].[ProcessTransactionHistory] WHERE CompanyId = @id) THEN 'ProcessTransactionHistory'
    WHEN EXISTS (SELECT 1 FROM [dbo].[ProcessTransactionMaster] WHERE CompanyId = @id) THEN 'ProcessTransactionMaster'
    WHEN EXISTS (SELECT 1 FROM [weavelanesoftDB].[ProductionData] WHERE CompanyId = @id) THEN 'ProductionData'
    WHEN EXISTS (SELECT 1 FROM [dbo].[ProductionOrderDetail] WHERE CompanyId = @id) THEN 'ProductionOrderDetail'
    WHEN EXISTS (SELECT 1 FROM [dbo].[ProductionOrderMaster] WHERE CompanyId = @id) THEN 'ProductionOrderMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[ProductionOrderSubDetail] WHERE CompanyId = @id) THEN 'ProductionOrderSubDetail'
    WHEN EXISTS (SELECT 1 FROM [dbo].[SaleOrder] WHERE CompanyId = @id) THEN 'SaleOrder'
    WHEN EXISTS (SELECT 1 FROM [dbo].[SketcherMaster] WHERE CompanyId = @id) THEN 'SketcherMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[TransportMaster] WHERE CompanyId = @id) THEN 'TransportMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[TypeMaster] WHERE CompanyId = @id) THEN 'TypeMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[UserAccountMaster] WHERE CompanyId = @id) THEN 'UserAccountMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[WarpQualityMaster] WHERE CompanyId = @id) THEN 'WarpQualityMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[WeftColorMaster] WHERE CompanyId = @id) THEN 'WeftColorMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[YarnColorMaster] WHERE CompanyId = @id) THEN 'YarnColorMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[YarnInwardMaster] WHERE CompanyId = @id) THEN 'YarnInwardMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[YarnMaterialMaster] WHERE CompanyId = @id) THEN 'YarnMaterialMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[YarnOutwardMaster] WHERE CompanyId = @id) THEN 'YarnOutwardMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[YARNOUTWARDScanMaster] WHERE CompanyId = @id) THEN 'YARNOUTWARDScanMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[YarnPOMaster] WHERE CompanyId = @id) THEN 'YarnPOMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[YarnQualityMaster] WHERE CompanyId = @id) THEN 'YarnQualityMaster'
    WHEN EXISTS (SELECT 1 FROM [dbo].[YarnRequirementMaster] WHERE CompanyId = @id) THEN 'YarnRequirementMaster'
    ELSE NULL
END";

                        using (SqlCommand cmdDep = new SqlCommand(depCheckSql, con, tran))
                        {
                            cmdDep.Parameters.Add("@id", SqlDbType.BigInt).Value = companyId;

                            object depRes = cmdDep.ExecuteScalar();

                            if (depRes != null &&
                                depRes != DBNull.Value &&
                                !string.IsNullOrEmpty(depRes.ToString()))
                            {
                                tran.Rollback();

                                comman.Code = 400;
                                comman.Message =
                                    "This company cannot be deleted because it is already associated with existing transactions or records in "
                                    + depRes.ToString() + ".";

                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }
                        }

                        // 4. Delete company
                        using (SqlCommand cmdDel = new SqlCommand(
                            "DELETE FROM dbo.CompanyMaster WHERE CompanyId = @CompanyId",
                            con, tran))
                        {
                            cmdDel.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                            int rows = cmdDel.ExecuteNonQuery();

                            if (rows <= 0)
                            {
                                tran.Rollback();

                                comman.Code = 410;
                                comman.Message = "Failed to delete record.";
                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }
                        }

                        // 5. Transaction-bound audit logging
                        int? userId = null;

                        if (Context.Request.Cookies["UserIDs"] != null)
                        {
                            string uid = Context.Request.Cookies["UserIDs"].Value;

                            if (uid.Contains("="))
                                uid = uid.Split('=')[1];

                            if (int.TryParse(uid, out int pUid))
                                userId = pUid;
                        }

                        string uName = Context.Request.Cookies["UserName"] != null
                            ? Context.Request.Cookies["UserName"].Value
                            : "User";

                        var oldValObj = new
                        {
                            CompanyId = companyId,
                            CompanyName = companyName,
                            is_default = isDefault ? 1 : 0
                        };

                        string oldValJson = js.Serialize(oldValObj);

                        AuditLogHelper.LogTransactional(
                            con,
                            tran,
                            "Company Master",
                            "DeleteCompanyMaster",
                            "CompanyMaster",
                            companyId.ToString(),
                            "Company " + companyName + " deleted successfully.",
                            oldValJson,
                            null,
                            "Success",
                            null,
                            null,
                            userId,
                            uName
                        );

                        tran.Commit();

                        // 6. Safe post-commit file cleanup
                        try
                        {
                            if (!string.IsNullOrEmpty(photo))
                            {
                                string p = Server.MapPath(photo);
                                if (File.Exists(p))
                                    File.Delete(p);
                            }

                            if (!string.IsNullOrEmpty(sign))
                            {
                                string s = Server.MapPath(sign);
                                if (File.Exists(s))
                                    File.Delete(s);
                            }
                        }
                        catch
                        {
                            // File cleanup failure should not undo committed DB deletion.
                        }

                        comman.Code = 200;
                        comman.Message = "Record Deleted Successfully.";
                    }
                    catch (Exception ex)
                    {
                        try
                        {
                            tran.Rollback();
                        }
                        catch { }

                        comman.Code = 405;
                        comman.Message = "Problem occurred while deleting company: " + ex.Message;
                    }
                }
            }

            Context.Response.Write(js.Serialize(comman));
        }

        // View Company Master
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getCompanyMaster(string startFrom)
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<CompanyMaster> listUser = new List<CompanyMaster>();
            CompanyMasterResponse response = new CompanyMasterResponse();

            int offset = 0;

            if (!int.TryParse(startFrom, out offset) || offset < 0)
            {
                offset = 0;
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            try
            {
                string sql = @"
            SELECT
                CM.*,
                POS.StateTitle,
                CASE
                    WHEN CM.is_default = 1 THEN 'bg-success'
                    ELSE 'bg-danger'
                END AS ActiveOrNotCSS,
                CASE
                    WHEN CM.is_default = 1 THEN 'Yes'
                    ELSE 'No'
                END AS ActiveMessage
            FROM dbo.CompanyMaster CM
            LEFT JOIN dbo.PlaceOfSupplyMaster POS
                ON CM.State = POS.GSTStateCode
            ORDER BY CM.CompanyId DESC
            OFFSET @Offset ROWS
            FETCH NEXT 10 ROWS ONLY";

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.Parameters.Add("@Offset", SqlDbType.Int).Value = offset;

                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            CompanyMaster condition = new CompanyMaster();

                            condition.CompanyId = Convert.ToInt32(rdr["CompanyId"]);

                            condition.CompanyName = rdr["CompanyName"] != DBNull.Value
                                ? rdr["CompanyName"].ToString() : "";

                            condition.MobileNo = rdr["MobileNo"] != DBNull.Value
                                ? rdr["MobileNo"].ToString() : "";

                            condition.CompanyLogo = rdr["CompanyLogo"] != DBNull.Value
                                ? rdr["CompanyLogo"].ToString() : "";

                            condition.Email = rdr["Email"] != DBNull.Value
                                ? rdr["Email"].ToString() : "";

                            condition.BusinessType = rdr["BusinessType"] != DBNull.Value
                                ? rdr["BusinessType"].ToString() : "";

                            condition.BusinessCategory = rdr["BusinessCategory"] != DBNull.Value
                                ? rdr["BusinessCategory"].ToString() : "";

                            condition.is_default = rdr["is_default"] != DBNull.Value
                                ? rdr["is_default"].ToString() : "";

                            condition.State = rdr["State"] != DBNull.Value
                                ? rdr["State"].ToString() : "";

                            condition.StateTitle = rdr["StateTitle"] != DBNull.Value
                                ? rdr["StateTitle"].ToString() : "";

                            listUser.Add(condition);
                        }
                    }
                }

                response.Code = 200;
                response.Message = "Success";
                response.listCompanyMaster = listUser;
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Company Master", "getCompanyMaster", ex);

                response.Code = 500;
                response.Message = "Error while fetching company records.";
                response.listCompanyMaster = listUser;
            }

            Context.Response.Write(js.Serialize(response));
        }

