        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string getStates()
        {
            JavaScriptSerializer jsSerializer = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<Dictionary<string, object>> parentRow =
                new List<Dictionary<string, object>>();

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            try
            {
                string sql = @"
            SELECT StateTitle, GSTStateCode
            FROM dbo.PlaceOfSupplyMaster
            ORDER BY StateTitle";

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            Dictionary<string, object> childRow =
                                new Dictionary<string, object>();

                            for (int i = 0; i < rdr.FieldCount; i++)
                            {
                                childRow.Add(
                                    rdr.GetName(i),
                                    rdr.IsDBNull(i) ? null : rdr.GetValue(i)
                                );
                            }

                            parentRow.Add(childRow);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Company Master", "getStates", ex);
            }

            return jsSerializer.Serialize(parentRow);
        }

