        // View User Master
        // View User Master
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getUserMaster(string startFrom)
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<UserAccountMaster> listUser = new List<UserAccountMaster>();
            UserAccountMasterResponce response = new UserAccountMasterResponce();

            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                string sql = @"
            SELECT
                UAM.UserAccountId,
                UAM.UserAccountDateAndTime,
                CM.CompanyName,
                UAM.UserAccountName,
                CASE
                    WHEN UAM.UserRole = 'Watchman' THEN 'Godown Manager'
                    ELSE UAM.UserRole
                END AS UserRole,
                CASE
                    WHEN UAM.AllowLogin = 1 THEN 'bg-success'
                    ELSE 'bg-danger'
                END AS ActiveOrNotCSS,
                CASE
                    WHEN UAM.AllowLogin = 1 THEN 'Yes'
                    ELSE 'No'
                END AS ActiveMessage,
                UAM.UserAccountEmail,
                UAM.UserAccountMobileNo,
                UAM.UserAccountProfile,
                UAM.AllowLogin
            FROM dbo.UserAccountMaster UAM
            LEFT JOIN dbo.CompanyMaster CM
                ON CM.CompanyId = UAM.CompanyId
            WHERE UAM.UserAccountId <> 48
            ORDER BY UAM.UserAccountId DESC";

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            UserAccountMaster condition = new UserAccountMaster();

                            condition.UserAccountId = Convert.ToInt32(rdr["UserAccountId"]);

                            if (rdr["UserAccountDateAndTime"] != DBNull.Value)
                            {
                                condition.UserAccountDateAndTime =
                                    Convert.ToDateTime(rdr["UserAccountDateAndTime"]);

                                condition.UserAccountDateAndTimes =
                                    condition.UserAccountDateAndTime.ToString("dd-MM-yyyy");
                            }

                            condition.CompanyName =
                                rdr["CompanyName"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["CompanyName"]);

                            condition.UserAccountName =
                                rdr["UserAccountName"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["UserAccountName"]);

                            condition.UserRole =
                                rdr["UserRole"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["UserRole"]);

                            condition.UserAccountEmail =
                                rdr["UserAccountEmail"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["UserAccountEmail"]);

                            condition.UserAccountMobileNo =
                                rdr["UserAccountMobileNo"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["UserAccountMobileNo"]);

                            condition.UserAccountProfile =
                                rdr["UserAccountProfile"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["UserAccountProfile"]);

                            condition.AllowLogin =
                                rdr["AllowLogin"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["AllowLogin"]);

                            listUser.Add(condition);
                        }
                    }
                }

                response.Code = 200;
                response.Message = "Success";
                response.listUserAccountMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine("getUserMaster Error: " + ex.ToString());

                response.Code = 500;
                response.Message = "Unable to retrieve user details.";
                response.listUserAccountMaster = new List<UserAccountMaster>();
            }
            Context.Response.Write(js.Serialize(response));
        }

