            {
                System.Diagnostics.Trace.WriteLine(
                    "getUserMasterById Error: " + ex.ToString()
                );
                response.Code = 500;
                response.Message = "Unable to retrieve user details.";
                response.listUserAccountMaster = new List<UserAccountMaster>();
            }
            Context.Response.Write(js.Serialize(response));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void editUserMaster()
        {
            CommanResponse comman = new CommanResponse();

            string newImagePath = "";
            string oldImagePath = "";

            try
            {
                var request = HttpContext.Current.Request;

                int userId;
                if (!int.TryParse(request.Params["UserAccountId"], out userId) || userId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid user id.";
                    Context.Response.Write(new JavaScriptSerializer().Serialize(comman));
                    return;
                }

                string companyId = request.Params["CompanyIDss"];
                string userName = request.Params["UserAccountName"];
                string userRole = request.Params["UserRole"];
                string email = request.Params["UserAccountEmail"] ?? "";
                string mobile = request.Params["UserAccountMobileNo"] ?? "";
                string allowLogin = request.Params["AllowLogin"];

                if (string.IsNullOrWhiteSpace(companyId) ||
                    string.IsNullOrWhiteSpace(userName) ||
                    string.IsNullOrWhiteSpace(userRole) ||
                    string.IsNullOrWhiteSpace(allowLogin))
                {
                    comman.Code = 400;
                    comman.Message = "Required fields are missing.";
                    Context.Response.Write(new JavaScriptSerializer().Serialize(comman));
                    return;
                }

                int companyIdValue;
                int allowLoginValue;

                if (!int.TryParse(companyId, out companyIdValue) ||
                    !int.TryParse(allowLogin, out allowLoginValue) ||
                    (allowLoginValue != 0 && allowLoginValue != 1))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid company or login status.";
                    Context.Response.Write(new JavaScriptSerializer().Serialize(comman));
                    return;
                }

                DateTime dateTimeIndian =
                    TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    // Get existing profile
                    using (SqlCommand getCmd = new SqlCommand(
                        @"SELECT UserAccountProfile
                  FROM dbo.UserAccountMaster
                  WHERE UserAccountId = @UserAccountId", con))
                    {
                        getCmd.Parameters.Add("@UserAccountId", SqlDbType.Int).Value = userId;

                        object result = getCmd.ExecuteScalar();

                        if (result == null || result == DBNull.Value)
                        {
                            comman.Code = 404;
                            comman.Message = "User record not found.";
                            Context.Response.Write(new JavaScriptSerializer().Serialize(comman));
                            return;
                        }

                        oldImagePath = Convert.ToString(result);
                    }

                    // Upload new profile only when a file is supplied
                    HttpPostedFile photo = request.Files["UserAccountProfile"];

                    if (photo != null && photo.ContentLength > 0)
                    {
                        string extension = Path.GetExtension(photo.FileName).ToLowerInvariant();

                        string[] allowedExtensions = { ".jpg", ".jpeg", ".png", ".gif", ".webp" };

                        if (!allowedExtensions.Contains(extension))
                        {
                            comman.Code = 400;
                            comman.Message = "Invalid profile image format.";
                            Context.Response.Write(new JavaScriptSerializer().Serialize(comman));
                            return;
                        }

                        string folderPath = Server.MapPath("~/UserProfile/");

                        if (!Directory.Exists(folderPath))
                        {
                            Directory.CreateDirectory(folderPath);
                        }

                        string fileName = RandomString(6, true) + Guid.NewGuid().ToString("N") + extension;

                        newImagePath = "UserProfile/" + fileName;

                        photo.SaveAs(Path.Combine(folderPath, fileName));
                    }

                    try
                    {
                        string sql = @"
                    UPDATE dbo.UserAccountMaster
                    SET
                        UserAccountDateAndTime = @DateAndTime,
                        UserAccountName = @UserAccountName,
                        UserRole = @UserRole,
                        UserAccountEmail =
                            CASE WHEN @Email <> '' THEN @Email ELSE UserAccountEmail END,
                        UserAccountMobileNo =
                            CASE WHEN @Mobile <> '' THEN @Mobile ELSE UserAccountMobileNo END,
                        CompanyId = @CompanyId,
                        AllowLogin = @AllowLogin
                        " + (string.IsNullOrEmpty(newImagePath)
                                    ? ""
                                    : ", UserAccountProfile = @UserAccountProfile") + @"
                    WHERE UserAccountId = @UserAccountId";

                        using (SqlCommand cmd = new SqlCommand(sql, con))
                        {
                            cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime).Value = dateTimeIndian;
                            cmd.Parameters.Add("@UserAccountName", SqlDbType.NVarChar).Value = userName;
                            cmd.Parameters.Add("@UserRole", SqlDbType.NVarChar).Value = userRole;
                            cmd.Parameters.Add("@Email", SqlDbType.NVarChar).Value = email;
                            cmd.Parameters.Add("@Mobile", SqlDbType.NVarChar).Value = mobile;
                            cmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyIdValue;
                            cmd.Parameters.Add("@AllowLogin", SqlDbType.Int).Value = allowLoginValue;
                            cmd.Parameters.Add("@UserAccountId", SqlDbType.Int).Value = userId;

                            if (!string.IsNullOrEmpty(newImagePath))
                            {
                                cmd.Parameters.Add("@UserAccountProfile", SqlDbType.NVarChar).Value = newImagePath;
                            }

                            int rows = cmd.ExecuteNonQuery();

                            if (rows > 0)
                            {
                                comman.Code = 201;
                                comman.Message = "Record has been updated successfully.";
                            }
                            else
                            {
                                comman.Code = 410;
                                comman.Message = "Problem has been occurred while submitting your data.";
                            }
                        }
                    }
                    catch
                    {
                        // If database update fails, remove the newly uploaded image.
                        if (!string.IsNullOrEmpty(newImagePath))
                        {
                            string newFile = Server.MapPath("~/" + newImagePath);

                            if (File.Exists(newFile))
                            {
                                File.Delete(newFile);
                            }
                        }

                        throw;
                    }
                }

                // Delete old profile only after successful database update.
                if (comman.Code == 201 && !string.IsNullOrEmpty(newImagePath) &&
                    !string.IsNullOrEmpty(oldImagePath))
                {
                    string oldFile = Server.MapPath("~/" + oldImagePath);

                    if (File.Exists(oldFile))
                    {
                        File.Delete(oldFile);
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine("editUserMaster SQL Error: " + ex);

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine("editUserMaster Error: " + ex);

                comman.Code = 500;
                comman.Message = "Unable to update user details.";
            }

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            Context.Response.Write(js.Serialize(comman));
        }

        // Delete User Master
        // Delete User Master
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteUserMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse comman = new CommanResponse();

            string photo = "";
            string userName = "";

            long userId;

            try
            {
                string userIdValue = HttpContext.Current.Request.Params["UserAccountId"];

                if (!long.TryParse(userIdValue, out userId) || userId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid user id.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                // Prevent logged-in user from deleting their own account.
                string loggedInUserId = Context.Request.Cookies["UserIDs"]?.Value;

                if (string.IsNullOrWhiteSpace(loggedInUserId))
                {
                    loggedInUserId = Context.Request.Cookies["UserID"]?.Value;
                }

                if (!string.IsNullOrWhiteSpace(loggedInUserId))
                {
                    if (loggedInUserId.Contains("="))
                        loggedInUserId = loggedInUserId.Split('=')[1];

                    long currentUserId;

                    if (long.TryParse(loggedInUserId, out currentUserId) &&
                        currentUserId == userId)
                    {
                        comman.Code = 400;
                        comman.Message = "You cannot delete your own account.";
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction())
                    {
                        try
                        {
                            // 1. Get user details with lock.
                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT UserAccountName, UserAccountProfile
                        FROM dbo.UserAccountMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE UserAccountId = @UserAccountId;",
                                con, tran))
                            {
                                cmd.Parameters.Add("@UserAccountId", SqlDbType.BigInt).Value = userId;

                                using (SqlDataReader rdr = cmd.ExecuteReader())
                                {
                                    if (!rdr.Read())
                                    {
                                        tran.Rollback();

                                        comman.Code = 404;
                                        comman.Message = "Record not found.";

                                        Context.Response.Write(js.Serialize(comman));
                                        return;
                                    }

                                    userName = rdr["UserAccountName"] == DBNull.Value
                                        ? ""
                                        : Convert.ToString(rdr["UserAccountName"]);

                                    photo = rdr["UserAccountProfile"] == DBNull.Value
                                        ? ""
                                        : Convert.ToString(rdr["UserAccountProfile"]);
                                }
                            }

                            // 2. Check dependent records.
                            string[] dependencyChecks =
                            {
                        @"SELECT COUNT_BIG(1) FROM dbo.SaleOrder
                          WHERE UserAccountId = @UserAccountId",

                        @"SELECT COUNT_BIG(1) FROM dbo.ProductionOrderMaster
                          WHERE UserAccountId = @UserAccountId",

                        @"SELECT COUNT_BIG(1) FROM dbo.YarnInwardMaster
                          WHERE UserAccountId = @UserAccountId",

                        @"SELECT COUNT_BIG(1) FROM dbo.PartyMaster
                          WHERE UserAccountId = @UserAccountId"
                    };

                            string[] dependencyNames =
                            {
                        "SaleOrder",
                        "ProductionOrderMaster",
                        "YarnInwardMaster",
                        "PartyMaster"
                    };

                            List<string> usedInTables = new List<string>();

                            for (int i = 0; i < dependencyChecks.Length; i++)
                            {
                                using (SqlCommand cmd = new SqlCommand(
                                    dependencyChecks[i], con, tran))
                                {
                                    SqlDbType parameterType =
                                        i == 0 ? SqlDbType.Int : SqlDbType.BigInt;

                                    if (i == 0 && userId > int.MaxValue)
                                    {
                                        continue;
                                    }

                                    cmd.Parameters.Add("@UserAccountId", parameterType).Value =
                                        i == 0 ? (object)(int)userId : userId;

                                    long count = Convert.ToInt64(cmd.ExecuteScalar());

                                    if (count > 0)
                                    {
                                        usedInTables.Add(dependencyNames[i]);
                                    }
                                }
                            }

                            if (usedInTables.Count > 0)
                            {
                                tran.Rollback();

                                comman.Code = 547;
                                comman.Message =
                                    "Cannot delete this user because records exist in: " +
                                    string.Join(", ", usedInTables);

                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }

                            // 3. Delete user record.
                            using (SqlCommand cmd = new SqlCommand(@"
                        DELETE FROM dbo.UserAccountMaster
                        WHERE UserAccountId = @UserAccountId;",
                                con, tran))
                            {
                                cmd.Parameters.Add("@UserAccountId", SqlDbType.BigInt).Value = userId;

                                int rows = cmd.ExecuteNonQuery();

                                if (rows != 1)
                                {
                                    tran.Rollback();

                                    comman.Code = 410;
                                    comman.Message = "Failed to delete record.";

                                    Context.Response.Write(js.Serialize(comman));
                                    return;
                                }
                            }

                            // 4. Transaction-bound audit logging.
                            int? auditUserId = null;
                            string auditUserIdValue =
                                Context.Request.Cookies["UserIDs"]?.Value;

                            if (!string.IsNullOrWhiteSpace(auditUserIdValue))
                            {
                                if (auditUserIdValue.Contains("="))
                                    auditUserIdValue = auditUserIdValue.Split('=')[1];

                                if (int.TryParse(auditUserIdValue, out int parsedUserId))
                                    auditUserId = parsedUserId;
                            }

                            string auditUserName =
                                Context.Request.Cookies["UserName"]?.Value ?? "User";

                            string oldValueJson = js.Serialize(new
                            {
                                UserAccountId = userId,
                                UserAccountName = userName,
                                UserAccountProfile = photo
                            });

                            AuditLogHelper.LogTransactional(
                                con,
                                tran,
                                "User Master",
                                "DeleteUserMaster",
                                "UserAccountMaster",
                                userId.ToString(),
                                "User " + userName + " deleted successfully.",
                                oldValueJson,
                                null,
                                "Success",
                                null,
                                null,
                                auditUserId,
                                auditUserName
                            );

                            // 5. Commit only after successful audit.
                            tran.Commit();

                            comman.Code = 200;
                            comman.Message = "Record Deleted Successfully.";
                        }
                        catch
                        {
                            try
                            {
                                tran.Rollback();
                            }
                            catch
                            {
                                // Ignore rollback failure.
                            }

                            throw;
                        }
                    }
                }

                // 6. Delete profile image only after successful database commit.
                if (comman.Code == 200 && !string.IsNullOrWhiteSpace(photo))
                {
                    try
                    {
                        string normalizedPhoto = photo
                            .Replace("/", "\\")
                            .TrimStart('\\');

                        string fullPath = Server.MapPath("~/" + normalizedPhoto);
                        string profileFolder = Server.MapPath("~/UserProfile/");

                        string safeFolder = Path.GetFullPath(profileFolder);
                        string safeFile = Path.GetFullPath(fullPath);

                        if (safeFile.StartsWith(
                            safeFolder,
                            StringComparison.OrdinalIgnoreCase) &&
                            File.Exists(safeFile))
                        {
                            File.Delete(safeFile);
                        }
                    }
                    catch (Exception fileEx)
                    {
                        System.Diagnostics.Trace.WriteLine(
                            "DeleteUserMaster profile cleanup error: " + fileEx);
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "DeleteUserMaster SQL Error: " + ex);

                comman.Code = ex.Number == 547 ? 547 : 405;
                comman.Message = ex.Number == 547
                    ? "Cannot delete this record because it is being used."
                    : "Problem occurred while deleting your data.";
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "DeleteUserMaster Error: " + ex);

                comman.Code = 500;
                comman.Message = "Unable to delete user details.";
            }

            Context.Response.Write(js.Serialize(comman));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertUserMaster()
        {
            CommanResponse comman = new CommanResponse();
            HttpContext context = HttpContext.Current;
            HttpRequest request = context.Request;

            string imagePath = "";
            string physicalImagePath = "";

            try
            {
                // Input validation
                string companyIdText = request.Params["CompanyIDss"];
                string userName = (request.Params["UserAccountName"] ?? "").Trim();
                string userRole = (request.Params["UserRole"] ?? "").Trim();
                string mobileNo = (request.Params["UserAccountMobileNo"] ?? "").Trim();
                string email = (request.Params["UserAccountEmail"] ?? "").Trim();
                string password = request.Params["UserAccountPassword"] ?? "";
                string allowLoginText = request.Params["AllowLogin"];

                long companyId;
                byte allowLogin;

                if (!long.TryParse(companyIdText, out companyId) || companyId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Please select a valid company.";
                }
                else if (string.IsNullOrWhiteSpace(userName) || userName.Length > 100)
                {
                    comman.Code = 400;
                    comman.Message = "Please enter a valid user name.";
                }
                else if (string.IsNullOrWhiteSpace(userRole) || userRole.Length > 50)
                {
                    comman.Code = 400;
                    comman.Message = "Please enter a valid user role.";
                }
                else if (string.IsNullOrWhiteSpace(mobileNo) || mobileNo.Length > 10)
                {
                    comman.Code = 400;
                    comman.Message = "Please enter a valid mobile number.";
                }
                else if (email.Length > 100)
                {
                    comman.Code = 400;
                    comman.Message = "Email cannot exceed 100 characters.";
                }
                else if (string.IsNullOrWhiteSpace(password) || password.Length > 100)
                {
                    comman.Code = 400;
                    comman.Message = "Please enter a valid password.";
                }
                else if (!byte.TryParse(allowLoginText, out allowLogin))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid login permission.";
                }
                else
                {
                    DateTime indianDateTime = TimeZoneInfo.ConvertTimeFromUtc(
                        DateTime.UtcNow,
                        India_Standard_Time
                    );

                    // Profile image upload
                    if (request.Files.Count > 0)
                    {
                        HttpPostedFile photo = request.Files["UserAccountProfile"];

                        if (photo != null && photo.ContentLength > 0)
                        {
                            string extension = Path.GetExtension(photo.FileName).ToLowerInvariant();

                            string[] allowedExtensions = { ".jpg", ".jpeg", ".png", ".gif", ".webp" };

                            if (!allowedExtensions.Contains(extension))
                            {
                                comman.Code = 400;
                                comman.Message = "Only JPG, JPEG, PNG, GIF and WEBP images are allowed.";
                            }
                            else if (photo.ContentLength > 5 * 1024 * 1024)
                            {
                                comman.Code = 400;
                                comman.Message = "Profile image size cannot exceed 5 MB.";
                            }
                            else
                            {
                                string folderPath = context.Server.MapPath("~/UserProfile/");

                                if (!Directory.Exists(folderPath))
                                {
                                    Directory.CreateDirectory(folderPath);
                                }

                                string fileName = Guid.NewGuid().ToString("N") + extension;

                                imagePath = "UserProfile/" + fileName;
                                physicalImagePath = Path.Combine(folderPath, fileName);

                                photo.SaveAs(physicalImagePath);
                            }
                        }
                    }

                    if (comman.Code != 400)
                    {
                        string cs = ConfigurationManager
                            .ConnectionStrings["sqlconnstr"].ConnectionString;

                        using (SqlConnection con = new SqlConnection(cs))
                        {
                            string sql = @"
                        INSERT INTO dbo.UserAccountMaster
                        (
                            UserAccountDateAndTime,
                            CompanyId,
                            UserAccountName,
                            UserRole,
                            UserAccountMobileNo,
                            UserAccountEmail,
                            UserAccountProfile,
                            UserAccountPassword,
                            AllowLogin
                        )
                        VALUES
                        (
                            @DateAndTime,
                            @CompanyId,
                            @UserName,
                            @UserRole,
                            @MobileNo,
                            @Email,
                            @Profile,
                            @Password,
                            @AllowLogin
                        );";

                            using (SqlCommand cmd = new SqlCommand(sql, con))
                            {
                                cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime).Value =
                                    indianDateTime;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value =
                                    companyId;

                                cmd.Parameters.Add("@UserName", SqlDbType.NVarChar, 100).Value =
                                    userName;

                                cmd.Parameters.Add("@UserRole", SqlDbType.NVarChar, 50).Value =
                                    userRole;

                                cmd.Parameters.Add("@MobileNo", SqlDbType.NVarChar, 10).Value =
                                    mobileNo;

                                cmd.Parameters.Add("@Email", SqlDbType.NVarChar, 100).Value =
                                    string.IsNullOrWhiteSpace(email)
                                        ? (object)DBNull.Value
                                        : email;

                                cmd.Parameters.Add("@Profile", SqlDbType.NVarChar, -1).Value =
                                    string.IsNullOrEmpty(imagePath)
                                        ? (object)DBNull.Value
                                        : imagePath;

                                cmd.Parameters.Add("@Password", SqlDbType.NVarChar, 100).Value =
                                    getMd5Hash(password);

                                cmd.Parameters.Add("@AllowLogin", SqlDbType.TinyInt).Value =
                                    allowLogin;

                                con.Open();

                                int result = cmd.ExecuteNonQuery();

                                if (result > 0)
                                {
                                    comman.Code = 201;
                                    comman.Message = "Record has been saved successfully.";

                                    try
                                    {
                                        AuditLogHelper.Log(
                                            module: "User Master",
                                            action: "CREATE",
                                            tableName: "UserAccountMaster",
                                            description: "Created User: " + userName + " (" + userRole + ")"
                                        );
                                    }
                                    catch (Exception auditEx)
                                    {
                                        System.Diagnostics.Trace.WriteLine(
                                            "insertUserMaster Audit Error: " + auditEx.ToString()
                                        );
                                    }
                                }
                                else
                                {
                                    comman.Code = 410;
                                    comman.Message = "Problem has been occurred while submitting your data.";
                                }
                            }
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertUserMaster SQL Error: " + ex.ToString()
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertUserMaster Error: " + ex.ToString()
                );

                comman.Code = 500;
                comman.Message = "Problem has been occurred while submitting your data.";
            }
            finally
            {
                // Remove uploaded image if insert failed
                if (comman.Code != 201 && !string.IsNullOrEmpty(physicalImagePath))
                {
                    try
                    {
                        if (File.Exists(physicalImagePath))
                        {
                            File.Delete(physicalImagePath);
                        }
                    }
                    catch (Exception fileEx)
                    {
                        System.Diagnostics.Trace.WriteLine(
                            "insertUserMaster Image Cleanup Error: " + fileEx.ToString()
                        );
                    }
                }
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            context.Response.Write(js.Serialize(comman));
        }
