        #region GST Slab Master (GstSlabMaster.cshtml)
        // View GST Slab
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getGstSlab(string startFrom)
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<GstSlabMaster> listUser = new List<GstSlabMaster>();
            GstSlabMasterResponse response = new GstSlabMasterResponse();

            try
            {
                int offset;

                if (!int.TryParse(startFrom, out offset) || offset < 0)
                {
                    offset = 0;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                string sql = @"
            SELECT
                GS.*,
                CM.CompanyName
            FROM dbo.GSTSLABMaster GS
            LEFT JOIN dbo.CompanyMaster CM
                ON GS.CompanyId = CM.CompanyId
            ORDER BY GS.GSTSLABId DESC
            OFFSET @Offset ROWS
            FETCH NEXT 10 ROWS ONLY;";

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.Parameters.Add("@Offset", SqlDbType.Int).Value = offset;

                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            GstSlabMaster condition = new GstSlabMaster();

                            condition.GSTSLABId =
                                rdr["GSTSLABId"] == DBNull.Value
                                    ? 0
                                    : Convert.ToInt32(rdr["GSTSLABId"]);

                            condition.dates =
                                rdr["date"] == DBNull.Value
                                    ? ""
                                    : Convert.ToDateTime(rdr["date"]).ToString("dd-MM-yyyy");

                            condition.CompanyName =
                                rdr["CompanyName"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["CompanyName"]);

                            condition.GSTSLABName =
                                rdr["GSTSLABName"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["GSTSLABName"]);

                            condition.GST =
                                rdr["GST"] == DBNull.Value
                                    ? 0
                                    : Convert.ToDecimal(rdr["GST"]);

                            condition.IGST =
                                rdr["IGST"] == DBNull.Value
                                    ? 0
                                    : Convert.ToDecimal(rdr["IGST"]);

                            condition.CESS =
                                rdr["CESS"] == DBNull.Value
                                    ? 0
                                    : Convert.ToDecimal(rdr["CESS"]);

                            listUser.Add(condition);
                        }
                    }
                }

                response.Code = 200;
                response.Message = "Success";
                response.listGstSlabMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getGstSlab Error: " + ex.ToString()
                );

                response.Code = 500;
                response.Message = "Error while retrieving GST slab records.";
                response.listGstSlabMaster = listUser;
            }

            Context.Response.Write(js.Serialize(response));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getGstSlabById(string id)
        {
            JavaScriptSerializer js = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue };
            List<GstSlabMaster> listUser = new List<GstSlabMaster>();
            GstSlabMasterResponse response = new GstSlabMasterResponse();

            int slabId = 0;
            if (!int.TryParse(id, out slabId))
            {
                response.Code = 400;
                response.Message = "Invalid GST slab id.";
                response.listGstSlabMaster = listUser;
                Context.Response.Write(js.Serialize(response));
                return;
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                string sql = @"SELECT GS.*, CM.CompanyName 
FROM dbo.GSTSLABMaster GS 
LEFT JOIN dbo.CompanyMaster CM ON GS.CompanyId = CM.CompanyId 
WHERE GS.GSTSLABId = @GSTSLABId";

                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.Parameters.Add("@GSTSLABId", SqlDbType.Int).Value = slabId;
                    con.Open();
                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            GstSlabMaster condition = new GstSlabMaster();
                            condition.GSTSLABId = Convert.ToInt32(rdr["GSTSLABId"]);
                            condition.CompanyId = Convert.ToInt32(rdr["CompanyId"]);
                            condition.date = Convert.ToDateTime(rdr["date"]);
                            condition.dates = Convert.ToDateTime(rdr["date"]).ToString("dd-MM-yyyy");
                            condition.GSTSLABName = rdr["GSTSLABName"] != null ? rdr["GSTSLABName"].ToString() : "";
                            condition.IGST = Convert.ToDecimal(rdr["IGST"]);
                            condition.CESS = Convert.ToDecimal(rdr["CESS"]);
                            condition.GST = Convert.ToDecimal(rdr["GST"]);
                            condition.CompanyName = rdr["CompanyName"] != null ? rdr["CompanyName"].ToString() : "";
                            listUser.Add(condition);
                        }
                    }
                }
            }

            response.Code = 200;
            response.Message = "Success";
            response.listGstSlabMaster = listUser;
            Context.Response.Write(js.Serialize(response));
        }

