        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void editGstMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse comman = new CommanResponse();

            try
            {
                var request = HttpContext.Current.Request;

                int gstSlabId;
                long userAccountId;
                decimal gst, igst, cess;

                string slabName = (request.Params["GSTSLABName"] ?? "").Trim();

                if (!int.TryParse(request.Params["GSTSLABId"], out gstSlabId) || gstSlabId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid GST slab id.";
                }
                else if (string.IsNullOrWhiteSpace(slabName) || slabName.Length > 100)
                {
                    comman.Code = 400;
                    comman.Message = "Please enter a valid GST slab name.";
                }
                else if (!decimal.TryParse(request.Params["GST"], out gst) ||
                         !decimal.TryParse(request.Params["IGST"], out igst) ||
                         !decimal.TryParse(request.Params["CESS"], out cess))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid GST, IGST or CESS value.";
                }
                else if (Context.Request.Cookies["UserIDs"] == null ||
                         !long.TryParse(
                             Context.Request.Cookies["UserIDs"].Value.Split('=').Last(),
                             out userAccountId) ||
                         userAccountId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access.";
                }
                else
                {
                    DateTime indianDateTime = TimeZoneInfo.ConvertTimeFromUtc(
                        DateTime.UtcNow,
                        India_Standard_Time
                    );

                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    string sql = @"
                UPDATE dbo.GSTSLABMaster
                SET
                    [date] = @Date,
                    GSTSLABName = @GSTSLABName,
                    GST = @GST,
                    IGST = @IGST,
                    CESS = @CESS,
                    CompanyId = (
                        SELECT CompanyId
                        FROM dbo.CompanyMaster
                        WHERE is_default = 1
                    ),
                    UserAccountId = @UserAccountId
                WHERE GSTSLABId = @GSTSLABId;";

                    using (SqlConnection con = new SqlConnection(cs))
                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@Date", SqlDbType.Date).Value = indianDateTime.Date;

                        cmd.Parameters.Add("@GSTSLABName", SqlDbType.NVarChar, 100).Value =
                            slabName;

                        cmd.Parameters.Add("@GST", SqlDbType.Decimal).Value = gst;
                        cmd.Parameters["@GST"].Precision = 18;
                        cmd.Parameters["@GST"].Scale = 2;

                        cmd.Parameters.Add("@IGST", SqlDbType.Decimal).Value = igst;
                        cmd.Parameters["@IGST"].Precision = 18;
                        cmd.Parameters["@IGST"].Scale = 2;

                        cmd.Parameters.Add("@CESS", SqlDbType.Decimal).Value = cess;
                        cmd.Parameters["@CESS"].Precision = 18;
                        cmd.Parameters["@CESS"].Scale = 2;

                        cmd.Parameters.Add("@UserAccountId", SqlDbType.Int).Value =
                            userAccountId;

                        cmd.Parameters.Add("@GSTSLABId", SqlDbType.BigInt).Value =
                            gstSlabId;

                        con.Open();

                        int result = cmd.ExecuteNonQuery();

                        if (result > 0)
                        {
                            comman.Code = 201;
                            comman.Message = "Record has been updated successfully.";
                        }
                        else
                        {
                            comman.Code = 404;
                            comman.Message = "GST slab record not found.";
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "editGstMaster SQL Error: " + ex.ToString()
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem occurred while updating GST slab.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "editGstMaster Error: " + ex.ToString()
                );

                comman.Code = 500;
                comman.Message = "Problem occurred while updating GST slab.";
            }

            Context.Response.Write(js.Serialize(comman));
        }

