        #region Yarn Quality Master (YarnQuality.cshtml)
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertYarnQualityMaster()
        {
            CommanResponse comman = new CommanResponse();

            try
            {
                HttpRequest request = HttpContext.Current.Request;

                // Validate session cookies
                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                long userAccountId;
                long companyId;

                if (userCookie == null || companyCookie == null ||
                    !long.TryParse(userCookie.Value.Split('=').Last(), out userAccountId) ||
                    !long.TryParse(companyCookie.Value.Split('=').Last(), out companyId) ||
                    userAccountId <= 0 || companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Session cookies missing or invalid.";
                    WriteJsonResponse(comman);
                    return;
                }

                string yarnQuality = (request.Params["YarnQuality"] ?? "").Trim();

                byte isActive;
                if (string.IsNullOrWhiteSpace(yarnQuality) || yarnQuality.Length > 100)
                {
                    comman.Code = 400;
                    comman.Message = "Please enter a valid Yarn Quality.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (!byte.TryParse(request.Params["IsActive"], out isActive))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid IsActive value.";
                    WriteJsonResponse(comman);
                    return;
                }

                DateTime indianDateTime = TimeZoneInfo.ConvertTimeFromUtc(
                    DateTime.UtcNow,
                    India_Standard_Time
                );

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.ReadCommitted))
                    {
                        try
                        {
                            // Check duplicate quality within the same company
                            using (SqlCommand cmdDup = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.YarnQualityMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE YarnQuality = @YarnQuality
                          AND CompanyId = @CompanyId;",
                                con, tran))
                            {
                                cmdDup.Parameters.Add("@YarnQuality", SqlDbType.NVarChar, 100).Value =
                                    yarnQuality;

                                cmdDup.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value =
                                    companyId;

                                int duplicateCount = Convert.ToInt32(cmdDup.ExecuteScalar());

                                if (duplicateCount > 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 410;
                                    comman.Message = "This Yarn Quality already exists.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // Get next position for this company
                            int position = 1;

                            using (SqlCommand cmdPosition = new SqlCommand(@"
                        SELECT ISNULL(MAX(Position), 0) + 1
                        FROM dbo.YarnQualityMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId;",
                                con, tran))
                            {
                                cmdPosition.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value =
                                    companyId;

                                position = Convert.ToInt32(cmdPosition.ExecuteScalar());
                            }

                            // Insert and get new identity
                            int newId;

                            using (SqlCommand cmdInsert = new SqlCommand(@"
                        INSERT INTO dbo.YarnQualityMaster
                        (
                            DateandTime,
                            YarnQuality,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        )
                        OUTPUT INSERTED.YarnQualityID
                        VALUES
                        (
                            @DateAndTime,
                            @YarnQuality,
                            @IsActive,
                            @Position,
                            @CompanyId,
                            @UserAccountId
                        );",
                                con, tran))
                            {
                                cmdInsert.Parameters.Add("@DateAndTime", SqlDbType.DateTime).Value =
                                    indianDateTime;

                                cmdInsert.Parameters.Add("@YarnQuality", SqlDbType.NVarChar, 100).Value =
                                    yarnQuality;

                                cmdInsert.Parameters.Add("@IsActive", SqlDbType.TinyInt).Value =
                                    isActive;

                                cmdInsert.Parameters.Add("@Position", SqlDbType.Int).Value =
                                    position;

                                cmdInsert.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value =
                                    companyId;

                                cmdInsert.Parameters.Add("@UserAccountId", SqlDbType.BigInt).Value =
                                    userAccountId;

                                newId = Convert.ToInt32(cmdInsert.ExecuteScalar());
                            }

                            // Audit log in same transaction
                            YarnQualityMaster auditData = new YarnQualityMaster
                            {
                                YarnQualityID = newId,
                                YarnQuality = yarnQuality,
                                IsActive = isActive,
                                Position = position,
                                CompanyId = Convert.ToInt32(companyId),
                                UserAccountId = Convert.ToInt32(userAccountId),
                                DateandTime = indianDateTime
                            };

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Yarn Quality",
                                action: "INSERT",
                                tableName: "YarnQualityMaster",
                                recordId: newId.ToString(),
                                description: "Inserted Yarn Quality: " + yarnQuality +
                                             " (ID: " + newId + ")",
                                oldValue: null,
                                newValue: auditData,
                                customUserId: userAccountId
                            );

                            tran.Commit();

                            comman.Code = 201;
                            comman.Message = "Yarn Quality has been saved successfully.";
                        }
                        catch
                        {
                            try
                            {
                                tran.Rollback();
                            }
                            catch (Exception rollbackEx)
                            {
                                System.Diagnostics.Trace.WriteLine(
                                    "insertYarnQualityMaster Rollback Error: " +
                                    rollbackEx.ToString()
                                );
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertYarnQualityMaster SQL Error: " + ex.ToString()
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertYarnQualityMaster Error: " + ex.ToString()
                );

                comman.Code = 500;
                comman.Message = "Problem occurred while submitting your data.";
            }

            WriteJsonResponse(comman);
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnQualityMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<YarnQualityMaster> listUser = new List<YarnQualityMaster>();
            YarnQualityMasterResponse response = new YarnQualityMasterResponse();

            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                string sql = @"
            SELECT
                YarnQualityID,
                IsActive,
                Position,
                DateandTime,
                YarnQuality
            FROM dbo.YarnQualityMaster
            ORDER BY Position ASC;";

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            YarnQualityMaster condition = new YarnQualityMaster();

                            condition.YarnQualityID =
                                rdr["YarnQualityID"] == DBNull.Value
                                    ? 0
                                    : Convert.ToInt32(rdr["YarnQualityID"]);

                            condition.IsActive =
                                rdr["IsActive"] == DBNull.Value
                                    ? 0
                                    : Convert.ToInt32(rdr["IsActive"]);

                            condition.Position =
                                rdr["Position"] == DBNull.Value
                                    ? 0
                                    : Convert.ToInt32(rdr["Position"]);

                            condition.DateandTime =
                                rdr["DateandTime"] == DBNull.Value
                                    ? DateTime.MinValue
                                    : Convert.ToDateTime(rdr["DateandTime"]);

                            condition.DateandTimes =
                                rdr["DateandTime"] == DBNull.Value
                                    ? ""
                                    : Convert.ToDateTime(rdr["DateandTime"]).ToString("dd-MM-yyyy");

                            condition.YarnQuality =
                                rdr["YarnQuality"] == DBNull.Value
                                    ? ""
                                    : Convert.ToString(rdr["YarnQuality"]);

                            listUser.Add(condition);
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listYarnQualityMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getYarnQualityMaster Error: " + ex.ToString()
                );

                response.Code = 500;
                response.Message = "Error while retrieving Yarn Quality records.";
                response.listYarnQualityMaster = listUser;
            }

            Context.Response.Write(js.Serialize(response));
        }
