                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Session cookies missing.";
                    WriteJsonResponse(comman);
                    return;
                }

                // Cookie values validation
                string userCookieValue = userCookie.Value;
                string companyCookieValue = companyCookie.Value;

                if (userCookieValue.Contains("="))
                    userCookieValue = userCookieValue.Substring(userCookieValue.LastIndexOf('=') + 1);

                if (companyCookieValue.Contains("="))
                    companyCookieValue = companyCookieValue.Substring(companyCookieValue.LastIndexOf('=') + 1);

                long userId;
                long companyId;
                int yarnQualityId;
                int isActive;

                if (!long.TryParse(userCookieValue, out userId) || userId <= 0 ||
                    !long.TryParse(companyCookieValue, out companyId) || companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Invalid session information.";
                    WriteJsonResponse(comman);
                    return;
                }

