        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_ItemCategoryQueue()
        {
            YarnQualityMasterResponse comman = new YarnQualityMasterResponse();

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Unauthorized access.";
                    WriteYarnQualityResponse(comman);
                    return;
                }

                string userValue = userCookie.Value;
                string companyValue = companyCookie.Value;

                if (userValue.Contains("="))
                    userValue = userValue.Substring(userValue.LastIndexOf('=') + 1);

                if (companyValue.Contains("="))
                    companyValue = companyValue.Substring(companyValue.LastIndexOf('=') + 1);

                long userAccountId;
                long companyId;

                if (!long.TryParse(userValue, out userAccountId) || userAccountId <= 0 ||
                    !long.TryParse(companyValue, out companyId) || companyId <= 0)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Invalid session information.";
                    WriteYarnQualityResponse(comman);
                    return;
                }

                string postQueueStr = Context.Request.Params["PostQueue"];

                if (string.IsNullOrWhiteSpace(postQueueStr))
                {
                    comman.Code = 0;
                    comman.Message = "Error: Invalid queue parameters.";
                    WriteYarnQualityResponse(comman);
                    return;
                }

                string[] postQueue = postQueueStr.Split('|');

                if (postQueue.Length != 2)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Invalid queue parameters.";
                    WriteYarnQualityResponse(comman);
                    return;
                }

                string[] oneParts = postQueue[0].Split(',');
                string[] twoParts = postQueue[1].Split(',');

                int oneId, oneQueue, twoId, twoQueue;

                if (oneParts.Length != 2 || twoParts.Length != 2 ||
                    !int.TryParse(oneParts[0], out oneId) ||
                    !int.TryParse(oneParts[1], out oneQueue) ||
                    !int.TryParse(twoParts[0], out twoId) ||
                    !int.TryParse(twoParts[1], out twoQueue) ||
                    oneId <= 0 || twoId <= 0 ||
                    oneQueue <= 0 || twoQueue <= 0 ||
                    oneId == twoId)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Invalid queue values.";
                    WriteYarnQualityResponse(comman);
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection conn = new SqlConnection(cs))
                {
                    conn.Open();

                    using (SqlTransaction tran = conn.BeginTransaction(IsolationLevel.ReadCommitted))
                    {
                        try
                        {
                            object oldValue = null;

                            // Verify both records belong to current company
                            using (SqlCommand cmdFetch = new SqlCommand(@"
                        SELECT YarnQualityID, Position
                        FROM dbo.YarnQualityMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND YarnQualityID IN (@OneID, @TwoID)", conn, tran))
                            {
                                cmdFetch.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmdFetch.Parameters.Add("@OneID", SqlDbType.Int).Value = oneId;
                                cmdFetch.Parameters.Add("@TwoID", SqlDbType.Int).Value = twoId;

                                Dictionary<int, int> currentPositions = new Dictionary<int, int>();

                                using (SqlDataReader rdr = cmdFetch.ExecuteReader())
                                {
                                    while (rdr.Read())
                                    {
                                        currentPositions.Add(
                                            Convert.ToInt32(rdr["YarnQualityID"]),
                                            Convert.ToInt32(rdr["Position"])
                                        );
                                    }
                                }

                                if (currentPositions.Count != 2)
                                {
                                    tran.Rollback();

                                    comman.Code = 0;
                                    comman.Message = "Error: Yarn Quality record not found.";

                                    WriteYarnQualityResponse(comman);
                                    return;
                                }

                                oldValue = new
                                {
                                    Item1 = oneId,
                                    OldPosition1 = currentPositions[oneId],
                                    Item2 = twoId,
                                    OldPosition2 = currentPositions[twoId]
                                };

                                // Prevent applying stale queue positions
                                if (currentPositions[oneId] != oneQueue ||
                                    currentPositions[twoId] != twoQueue)
                                {
                                    tran.Rollback();

                                    comman.Code = 0;
                                    comman.Message = "Error: Queue has changed. Please refresh and try again.";

                                    WriteYarnQualityResponse(comman);
                                    return;
                                }
                            }

                            // Swap positions
                            using (SqlCommand cmd1 = new SqlCommand(@"
                        UPDATE dbo.YarnQualityMaster
                        SET Position = @Position
                        WHERE YarnQualityID = @ID
                          AND CompanyId = @CompanyId", conn, tran))
                            {
                                cmd1.Parameters.Add("@Position", SqlDbType.Int).Value = twoQueue;
                                cmd1.Parameters.Add("@ID", SqlDbType.Int).Value = oneId;
                                cmd1.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                                if (cmd1.ExecuteNonQuery() != 1)
                                    throw new Exception("Unable to update first queue position.");
                            }

                            using (SqlCommand cmd2 = new SqlCommand(@"
                        UPDATE dbo.YarnQualityMaster
                        SET Position = @Position
                        WHERE YarnQualityID = @ID
                          AND CompanyId = @CompanyId", conn, tran))
                            {
                                cmd2.Parameters.Add("@Position", SqlDbType.Int).Value = oneQueue;
                                cmd2.Parameters.Add("@ID", SqlDbType.Int).Value = twoId;
                                cmd2.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                                if (cmd2.ExecuteNonQuery() != 1)
                                    throw new Exception("Unable to update second queue position.");
                            }

                            AuditLogHelper.LogTransactional(
                                conn: conn,
                                tran: tran,
                                module: "Yarn Quality",
                                action: "UPDATE",
                                tableName: "YarnQualityMaster",
                                recordId: oneId.ToString(),
                                description: "Reordered Yarn Quality Queue: ID " +
                                             oneId + " -> Pos " + twoQueue +
                                             ", ID " + twoId + " -> Pos " + oneQueue,
                                oldValue: oldValue,
                                newValue: new
                                {
                                    Item1 = oneId,
                                    Pos1 = twoQueue,
                                    Item2 = twoId,
                                    Pos2 = oneQueue
                                },
                                customUserId: userAccountId
                            );

                            tran.Commit();

                            comman.Code = 1;
                            comman.Message = "Success";
                        }
                        catch
                        {
                            try
                            {
                                tran.Rollback();
                            }
                            catch { }

                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "UpdateTbl_ItemCategoryQueue Error: " + ex.ToString()
                );

                comman.Code = 0;
                comman.Message = "Error";
            }

            WriteYarnQualityResponse(comman);
        }

        private void WriteYarnQualityResponse(YarnQualityMasterResponse responseObj)
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(responseObj));
        }
