        public void insertYarnColorMaster()
        {
            CommanResponse comman = new CommanResponse();

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Session cookies missing.";
                    WriteJsonResponse(comman);
                    return;
                }

                string userValue = userCookie.Value;
                string companyValue = companyCookie.Value;

                if (userValue.Contains("="))
                    userValue = userValue.Substring(userValue.LastIndexOf('=') + 1);

                if (companyValue.Contains("="))
                    companyValue = companyValue.Substring(companyValue.LastIndexOf('=') + 1);

                long userAccountId;
                long companyId;
                int isActive;

                if (!long.TryParse(userValue, out userAccountId) || userAccountId <= 0 ||
                    !long.TryParse(companyValue, out companyId) || companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Invalid session information.";
                    WriteJsonResponse(comman);
                    return;
                }

                string yarnColor = Context.Request.Params["YarnColor"]?.Trim().ToUpperInvariant();
                string yarnColorCode = Context.Request.Params["YarnColorCode"]?.Trim().ToUpperInvariant();

                if (string.IsNullOrWhiteSpace(yarnColor))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Yarn Color.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (yarnColor.Length > 100)
                {
                    comman.Code = 410;
                    comman.Message = "Yarn Color cannot exceed 100 characters.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (!string.IsNullOrEmpty(yarnColorCode) && yarnColorCode.Length > 50)
                {
                    comman.Code = 410;
                    comman.Message = "Yarn Color Code cannot exceed 50 characters.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (!int.TryParse(Context.Request.Params["IsActive"], out isActive) ||
                    isActive < 0 || isActive > 255)
                {
                    comman.Code = 410;
                    comman.Message = "Invalid IsActive value.";
                    WriteJsonResponse(comman);
                    return;
                }

                DateTime dateTimeIndian = TimeZoneInfo.ConvertTimeFromUtc(
                    DateTime.UtcNow,
                    India_Standard_Time
                );

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // Duplicate check within current company
                            using (SqlCommand cmdDup = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.YarnColorMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND (
                                YarnColor = @YarnColor
                                OR (
                                    @YarnColorCode IS NOT NULL
                                    AND @YarnColorCode <> ''
                                    AND YarnColorCode = @YarnColorCode
                                )
                              )", con, tran))
                            {
                                cmdDup.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmdDup.Parameters.Add("@YarnColor", SqlDbType.NVarChar, 100).Value = yarnColor;
                                cmdDup.Parameters.Add("@YarnColorCode", SqlDbType.NVarChar, 50).Value =
                                    string.IsNullOrWhiteSpace(yarnColorCode)
                                        ? (object)DBNull.Value
                                        : yarnColorCode;

                                int duplicateCount = Convert.ToInt32(cmdDup.ExecuteScalar());

                                if (duplicateCount > 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 410;
                                    comman.Message = "This Yarn Color is already Exists.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // Get next position for current company
                            int position = 1;

                            using (SqlCommand cmdPos = new SqlCommand(@"
                        SELECT ISNULL(MAX(Position), 0) + 1
                        FROM dbo.YarnColorMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId", con, tran))
                            {
                                cmdPos.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                                position = Convert.ToInt32(cmdPos.ExecuteScalar());
                            }

                            int newId;

                            using (SqlCommand cmd = new SqlCommand(@"
                        INSERT INTO dbo.YarnColorMaster
                        (
                            DateandTime,
                            YarnColor,
                            YarnColorCode,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        )
                        OUTPUT INSERTED.YarnColorID
                        VALUES
                        (
                            @DateAndTime,
                            @YarnColor,
                            @YarnColorCode,
                            @IsActive,
                            @Position,
                            @CompanyId,
                            @UserAccountId
                        )", con, tran))
                            {
                                cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime).Value = dateTimeIndian;
                                cmd.Parameters.Add("@YarnColor", SqlDbType.NVarChar, 100).Value = yarnColor;
                                cmd.Parameters.Add("@YarnColorCode", SqlDbType.NVarChar, 50).Value =
                                    string.IsNullOrWhiteSpace(yarnColorCode)
                                        ? (object)DBNull.Value
                                        : yarnColorCode;
                                cmd.Parameters.Add("@IsActive", SqlDbType.TinyInt).Value = (byte)isActive;
                                cmd.Parameters.Add("@Position", SqlDbType.Int).Value = position;
                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmd.Parameters.Add("@UserAccountId", SqlDbType.BigInt).Value = userAccountId;

                                newId = Convert.ToInt32(cmd.ExecuteScalar());
                            }

                            YarnColorMaster ilist = new YarnColorMaster
                            {
                                YarnColorID = newId,
                                YarnColor = yarnColor,
                                YarnColorCode = yarnColorCode,
                                IsActive = isActive,
                                Position = position
                            };

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Yarn Color",
                                action: "INSERT",
                                tableName: "YarnColorMaster",
                                recordId: newId.ToString(),
                                description: "Inserted Yarn Color: " + yarnColor +
                                             " (Code: " + yarnColorCode + ") (ID: " + newId + ")",
                                oldValue: null,
                                newValue: ilist,
                                customUserId: userAccountId
                            );

                            tran.Commit();

                            comman.Code = 201;
                            comman.Message = "Yarn Color has been saved successfully.";
                        }
                        catch
                        {
                            try
                            {
                                tran.Rollback();
                            }
                            catch { }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertYarnColorMaster SQL Error: " + ex.ToString()
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem occurred while saving Yarn Color.";
                }
