                    return;
                }

                string companyValue = companyCookie.Value;

                if (companyValue.Contains("="))
                    companyValue = companyValue.Substring(companyValue.LastIndexOf('=') + 1);

                long companyId;

                if (!long.TryParse(companyValue, out companyId) || companyId <= 0)
                {
                    response.Code = 401;
                    response.Message = "Invalid company session information.";
                    response.listYarnColorMaster = listUser;
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string searchYarnColor =
                    (Context.Request.Params["SearchYarnColor"] ?? "").Trim();

                int startFrom = 0;

                if (!int.TryParse(Context.Request.Params["startFrom"], out startFrom) ||
                    startFrom < 0)
                {
                    startFrom = 0;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    string sql = @"
                SELECT
                    YarnColorID,
                    IsActive,
                    Position,
                    DateandTime,
                    YarnColor,
                    YarnColorCode
                FROM dbo.YarnColorMaster
                WHERE CompanyId = @CompanyId
                AND
                (
                    @Search = ''
                    OR YarnColor LIKE @SearchPattern
                )
                ORDER BY Position DESC, YarnColorID DESC
                OFFSET @StartFrom ROWS
                FETCH NEXT 10 ROWS ONLY;";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                            .Value = companyId;

                        cmd.Parameters.Add("@Search", SqlDbType.NVarChar, 100)
                            .Value = searchYarnColor;

                        cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar, 202)
                            .Value = "%" + searchYarnColor + "%";

                        cmd.Parameters.Add("@StartFrom", SqlDbType.Int)
                            .Value = startFrom;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                YarnColorMaster condition = new YarnColorMaster();

                                condition.YarnColorID =
                                    rdr["YarnColorID"] == DBNull.Value
                                        ? 0
                                        : Convert.ToInt32(rdr["YarnColorID"]);

                                condition.IsActive =
                                    rdr["IsActive"] == DBNull.Value
                                        ? 0
                                        : Convert.ToInt32(rdr["IsActive"]);

                                condition.Position =
                                    rdr["Position"] == DBNull.Value
                                        ? 0
                                        : Convert.ToInt32(rdr["Position"]);

                                condition.DateandTime =
                                    rdr["DateandTime"] == DBNull.Value
                                        ? DateTime.MinValue
                                        : Convert.ToDateTime(rdr["DateandTime"]);

                                condition.DateandTimes =
                                    rdr["DateandTime"] == DBNull.Value
                                        ? ""
                                        : Convert.ToDateTime(rdr["DateandTime"])
                                            .ToString("dd-MM-yyyy");

                                condition.YarnColor =
                                    rdr["YarnColor"] == DBNull.Value
                                        ? ""
                                        : rdr["YarnColor"].ToString().ToUpperInvariant();

                                condition.YarnColorCode =
                                    rdr["YarnColorCode"] == DBNull.Value
                                        ? ""
                                        : rdr["YarnColorCode"].ToString().ToUpperInvariant();

                                listUser.Add(condition);
                            }
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listYarnColorMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getYarnColorMaster Error: " + ex.ToString()
                );

                response.Code = 0;
                response.Message = "Something went wrong.";
                response.listYarnColorMaster = listUser;
            }

            Context.Response.Write(js.Serialize(response));
        }


