        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditYarnColorMaster()
        {
            CommanResponse comman = new CommanResponse();

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                long userId;
                long companyId;

                if (userCookie == null || companyCookie == null ||
                    !long.TryParse(userCookie.Value.Split('=').Last(), out userId) ||
                    !long.TryParse(companyCookie.Value.Split('=').Last(), out companyId) ||
                    userId <= 0 || companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Invalid session.";
                    WriteJsonResponse(comman);
                    return;
                }

                int yarnColorId;
                int isActive;

                if (!int.TryParse(
                    HttpContext.Current.Request.Params["YarnColorID"],
                    out yarnColorId) || yarnColorId <= 0)
                {
                    comman.Code = 410;
                    comman.Message = "Invalid Yarn Color ID.";
                    WriteJsonResponse(comman);
                    return;
                }

                string yarnColor =
                    (HttpContext.Current.Request.Params["YarnColor"] ?? "").Trim().ToUpperInvariant();

                string yarnColorCode =
                    (HttpContext.Current.Request.Params["YarnColorCode"] ?? "").Trim().ToUpperInvariant();

                if (string.IsNullOrWhiteSpace(yarnColor))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Yarn Color.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (yarnColor.Length > 100 || yarnColorCode.Length > 50)
                {
                    comman.Code = 410;
                    comman.Message = "Yarn Color or Yarn Color Code length is invalid.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (!int.TryParse(
                    HttpContext.Current.Request.Params["IsActive"],
                    out isActive) || isActive < 0 || isActive > 255)
                {
                    comman.Code = 410;
                    comman.Message = "Invalid IsActive value.";
                    WriteJsonResponse(comman);
                    return;
                }

                YarnColorMaster ilist = new YarnColorMaster
                {
                    YarnColorID = yarnColorId,
                    YarnColor = yarnColor,
                    YarnColorCode = yarnColorCode,
                    IsActive = isActive,
                    UserAccountId = checked((int)userId),
                    CompanyId = checked((int)companyId)
                };

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            object oldValue = null;

                            // Fetch existing Yarn Color record.
                            using (SqlCommand cmdFetch = new SqlCommand(@"
                        SELECT
                            YarnColorID,
                            DateandTime,
                            YarnColor,
                            YarnColorCode,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        FROM dbo.YarnColorMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE YarnColorID = @YarnColorID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdFetch.Parameters.Add("@YarnColorID", SqlDbType.Int)
                                    .Value = yarnColorId;

                                cmdFetch.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                using (SqlDataReader rdr = cmdFetch.ExecuteReader())
                                {
                                    if (rdr.Read())
                                    {
                                        oldValue = new
                                        {
                                            YarnColorID = Convert.ToInt32(rdr["YarnColorID"]),
                                            DateandTime = Convert.ToDateTime(rdr["DateandTime"]),
                                            YarnColor = Convert.ToString(rdr["YarnColor"]),
                                            YarnColorCode = rdr["YarnColorCode"] == DBNull.Value
                                                ? ""
                                                : Convert.ToString(rdr["YarnColorCode"]),
                                            IsActive = Convert.ToInt32(rdr["IsActive"]),
                                            Position = Convert.ToInt32(rdr["Position"]),
                                            CompanyId = Convert.ToInt64(rdr["CompanyId"]),
                                            UserAccountId = Convert.ToInt64(rdr["UserAccountId"])
                                        };
                                    }
                                }
                            }

                            if (oldValue == null)
                            {
                                tran.Rollback();

                                comman.Code = 404;
                                comman.Message = "Yarn Color record not found.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // Check whether this Yarn Color is already used.
                            string dependencyMessage = "";

                            using (SqlCommand cmdCheck = new SqlCommand(@"
                        SELECT TableName, TotalRecords
                        FROM
                        (
                            SELECT
                                'YarnPODetails' AS TableName,
                                COUNT(1) AS TotalRecords
                            FROM dbo.YarnPODetails WITH (UPDLOCK, HOLDLOCK)
                            WHERE YarnColorID = @ID

                            UNION ALL

                            SELECT
                                'YarnRequirementDetail',
                                COUNT(1)
                            FROM dbo.YarnRequirementDetail WITH (UPDLOCK, HOLDLOCK)
                            WHERE YarnColorID = @ID

                            UNION ALL

                            SELECT
                                'YarnInwardMaster',
                                COUNT(1)
                            FROM dbo.YarnInwardMaster WITH (UPDLOCK, HOLDLOCK)
                            WHERE YarnColorID = @ID

                            UNION ALL

                            SELECT
                                'YarnOutwardDetail',
                                COUNT(1)
                            FROM dbo.YarnOutwardDetail WITH (UPDLOCK, HOLDLOCK)
                            WHERE YarnColorID = @ID

                            UNION ALL

                            SELECT
                                'JobberOutwardDetail',
                                COUNT(1)
                            FROM dbo.JobberOutwardDetail WITH (UPDLOCK, HOLDLOCK)
                            WHERE YarnColorID = @ID

                            UNION ALL

                            SELECT
                                'YarnInterchangeMaster',
                                COUNT(1)
                            FROM dbo.YarnInterchangeMaster WITH (UPDLOCK, HOLDLOCK)
                            WHERE YarnColorID = @ID

                            UNION ALL

                            SELECT
                                'DesignColorMatchingFormMaster',
                                COUNT(1)
                            FROM dbo.DesignColorMatchingFormMaster WITH (UPDLOCK, HOLDLOCK)
                            WHERE CHARINDEX(
                                '|' + CAST(@ID AS NVARCHAR(20)) + '|',
                                '|' + ISNULL(ColorArray, '') + '|'
                            ) > 0
                        ) AS DependencyCheck
                        WHERE TotalRecords > 0",
                                con, tran))
                            {
                                cmdCheck.Parameters.Add("@ID", SqlDbType.Int)
                                    .Value = yarnColorId;

                                using (SqlDataReader rdr = cmdCheck.ExecuteReader())
                                {
                                    while (rdr.Read())
                                    {
                                        string tableName = Convert.ToString(rdr["TableName"]);
                                        long totalRecords = Convert.ToInt64(rdr["TotalRecords"]);

                                        if (!string.IsNullOrEmpty(dependencyMessage))
                                        {
                                            dependencyMessage += ", ";
                                        }

                                        dependencyMessage +=
                                            tableName + " (" + totalRecords + " records)";
                                    }
                                }
                            }

                            // Block update if Yarn Color is already in use.
                            if (!string.IsNullOrEmpty(dependencyMessage))
                            {
                                tran.Rollback();

                                comman.Code = 400;
                                comman.Message =
                                    "This Yarn Color cannot be updated because  it is currently in use." +
                                    ". Please remove or change these references first.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // Check duplicate Yarn Color / Code.
                            using (SqlCommand cmdDup = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.YarnColorMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND YarnColorID <> @YarnColorID
                          AND
                          (
                              YarnColor = @YarnColor
                              OR
                              (
                                  @YarnColorCode <> ''
                                  AND YarnColorCode = @YarnColorCode
                              )
                          )",
                                con, tran))
                            {
                                cmdDup.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                cmdDup.Parameters.Add("@YarnColorID", SqlDbType.Int)
                                    .Value = yarnColorId;

                                cmdDup.Parameters.Add("@YarnColor", SqlDbType.NVarChar, 100)
                                    .Value = yarnColor;

                                cmdDup.Parameters.Add("@YarnColorCode", SqlDbType.NVarChar, 50)
                                    .Value = yarnColorCode;

                                int duplicateCount =
                                    Convert.ToInt32(cmdDup.ExecuteScalar());

                                if (duplicateCount > 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 405;
                                    comman.Message = "Yarn Color already exists.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // Update Yarn Color.
                            int rowsAffected;

                            using (SqlCommand cmdUpdate = new SqlCommand(@"
                        UPDATE dbo.YarnColorMaster
                        SET
                            YarnColor = @YarnColor,
                            YarnColorCode = @YarnColorCode,
                            IsActive = @IsActive,
                            UserAccountId = @UserAccountId
                        WHERE YarnColorID = @YarnColorID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdUpdate.Parameters.Add("@YarnColor", SqlDbType.NVarChar, 100)
                                    .Value = yarnColor;

                                cmdUpdate.Parameters.Add("@YarnColorCode", SqlDbType.NVarChar, 50)
                                    .Value = yarnColorCode;

                                cmdUpdate.Parameters.Add("@IsActive", SqlDbType.TinyInt)
                                    .Value = (byte)isActive;

                                cmdUpdate.Parameters.Add("@UserAccountId", SqlDbType.BigInt)
                                    .Value = userId;

                                cmdUpdate.Parameters.Add("@YarnColorID", SqlDbType.Int)
                                    .Value = yarnColorId;

                                cmdUpdate.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                rowsAffected = cmdUpdate.ExecuteNonQuery();
                            }

                            if (rowsAffected != 1)
                            {
                                tran.Rollback();

                                comman.Code = 409;
                                comman.Message = "Yarn Color record could not be updated.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Yarn Color",
                                action: "UPDATE",
                                tableName: "YarnColorMaster",
                                recordId: yarnColorId.ToString(),
                                description: "Updated Yarn Color: " + yarnColor +
                                             " (Code: " + yarnColorCode +
                                             ") (ID: " + yarnColorId + ")",
                                oldValue: oldValue,
                                newValue: ilist,
                                customUserId: userId
                            );

                            tran.Commit();

                            comman.Code = 201;
                            comman.Message = "Yarn Color has been updated successfully.";
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "EditYarnColorMaster SQL Error: " + ex.ToString()
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Yarn Color already exists.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem occurred while updating Yarn Color.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "EditYarnColorMaster Error: " + ex.ToString()
                );

                comman.Code = 500;
                comman.Message = "Problem occurred while updating Yarn Color.";
            }

            WriteJsonResponse(comman);
        }


