        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_YarnColorQueue()
        {
            YarnColorMasterResponse comman = new YarnColorMasterResponse();

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                long userAccountId;
                long companyId;

                if (userCookie == null || companyCookie == null ||
                    !long.TryParse(userCookie.Value.Split('=').Last(), out userAccountId) ||
                    !long.TryParse(companyCookie.Value.Split('=').Last(), out companyId) ||
                    userAccountId <= 0 || companyId <= 0)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Unauthorized access.";
                    WriteYarnColorResponse(comman);
                    return;
                }

                string postQueueStr =
                    (HttpContext.Current.Request.Params["PostQueue"] ?? "").Trim();

                string[] postQueue = postQueueStr.Split('|');

                if (postQueue.Length != 2)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Invalid queue parameters.";
                    WriteYarnColorResponse(comman);
                    return;
                }

                string[] oneParts = postQueue[0].Split(',');
                string[] twoParts = postQueue[1].Split(',');

                int oneId, oneQueue, twoId, twoQueue;

                if (oneParts.Length != 2 || twoParts.Length != 2 ||
                    !int.TryParse(oneParts[0], out oneId) ||
                    !int.TryParse(oneParts[1], out oneQueue) ||
                    !int.TryParse(twoParts[0], out twoId) ||
                    !int.TryParse(twoParts[1], out twoQueue) ||
                    oneId <= 0 || twoId <= 0 ||
                    oneQueue <= 0 || twoQueue <= 0 ||
                    oneId == twoId)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Invalid queue values.";
                    WriteYarnColorResponse(comman);
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection conn = new SqlConnection(cs))
                {
                    conn.Open();

                    using (SqlTransaction tran =
                        conn.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // Verify both records and their current positions.
                            using (SqlCommand cmdCheck = new SqlCommand(@"
                        SELECT YarnColorID, Position
                        FROM dbo.YarnColorMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND YarnColorID IN (@OneID, @TwoID)",
                                conn, tran))
                            {
                                cmdCheck.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                cmdCheck.Parameters.Add("@OneID", SqlDbType.Int)
                                    .Value = oneId;

                                cmdCheck.Parameters.Add("@TwoID", SqlDbType.Int)
                                    .Value = twoId;

                                Dictionary<int, int> currentPositions =
                                    new Dictionary<int, int>();

                                using (SqlDataReader rdr = cmdCheck.ExecuteReader())
                                {
                                    while (rdr.Read())
                                    {
                                        currentPositions[Convert.ToInt32(rdr["YarnColorID"])] =
                                            Convert.ToInt32(rdr["Position"]);
                                    }
                                }

                                if (currentPositions.Count != 2 ||
                                    !currentPositions.ContainsKey(oneId) ||
                                    !currentPositions.ContainsKey(twoId) ||
                                    currentPositions[oneId] != oneQueue ||
                                    currentPositions[twoId] != twoQueue)
                                {
                                    tran.Rollback();

                                    comman.Code = 0;
                                    comman.Message =
                                        "Error: Queue data changed. Refresh and try again.";

                                    WriteYarnColorResponse(comman);
                                    return;
                                }
                            }

                            int firstRows;
                            int secondRows;

                            using (SqlCommand cmd1 = new SqlCommand(@"
                        UPDATE dbo.YarnColorMaster
                        SET Position = @Position
                        WHERE YarnColorID = @ID
                          AND CompanyId = @CompanyId",
                                conn, tran))
                            {
                                cmd1.Parameters.Add("@Position", SqlDbType.Int)
                                    .Value = twoQueue;

                                cmd1.Parameters.Add("@ID", SqlDbType.Int)
                                    .Value = oneId;

                                cmd1.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                firstRows = cmd1.ExecuteNonQuery();
                            }

                            using (SqlCommand cmd2 = new SqlCommand(@"
                        UPDATE dbo.YarnColorMaster
                        SET Position = @Position
                        WHERE YarnColorID = @ID
                          AND CompanyId = @CompanyId",
                                conn, tran))
                            {
                                cmd2.Parameters.Add("@Position", SqlDbType.Int)
                                    .Value = oneQueue;

                                cmd2.Parameters.Add("@ID", SqlDbType.Int)
                                    .Value = twoId;

                                cmd2.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                secondRows = cmd2.ExecuteNonQuery();
                            }

                            if (firstRows != 1 || secondRows != 1)
                            {
                                tran.Rollback();

                                comman.Code = 0;
                                comman.Message = "Error: Queue update failed.";

                                WriteYarnColorResponse(comman);
                                return;
                            }

                            AuditLogHelper.LogTransactional(
                                conn: conn,
                                tran: tran,
                                module: "Yarn Color",
                                action: "UPDATE",
                                tableName: "YarnColorMaster",
                                recordId: oneId.ToString(),
                                description:
                                    "Reordered YarnColor Queue: ID " + oneId +
                                    " -> Pos " + twoQueue +
                                    ", ID " + twoId + " -> Pos " + oneQueue,
                                oldValue: new
                                {
                                    Item1 = oneId,
                                    Pos1 = oneQueue,
                                    Item2 = twoId,
                                    Pos2 = twoQueue
                                },
                                newValue: new
                                {
                                    Item1 = oneId,
                                    Pos1 = twoQueue,
                                    Item2 = twoId,
                                    Pos2 = oneQueue
                                },
                                customUserId: userAccountId
                            );

                            tran.Commit();

                            comman.Code = 1;
                            comman.Message = "Success";
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "UpdateTbl_YarnColorQueue Error: " + ex.ToString()
                );

                comman.Code = 0;
                comman.Message = "Error";
            }

            WriteYarnColorResponse(comman);
        }
