        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertWeftColorMaster()
        {
            CommanResponse comman = new CommanResponse();

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                long userId;
                long companyId;

                if (userCookie == null || companyCookie == null ||
                    !long.TryParse(userCookie.Value.Split('=').Last(), out userId) ||
                    !long.TryParse(companyCookie.Value.Split('=').Last(), out companyId) ||
                    userId <= 0 || companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Invalid session.";
                    WriteJsonResponse(comman);
                    return;
                }

                string weftColor =
                    (HttpContext.Current.Request.Params["WeftColor"] ?? "")
                    .Trim().ToUpperInvariant();

                int isActive;

                if (string.IsNullOrWhiteSpace(weftColor))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Weft Color.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (weftColor.Length > 100)
                {
                    comman.Code = 410;
                    comman.Message = "Weft Color cannot exceed 100 characters.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (!int.TryParse(
                    HttpContext.Current.Request.Params["IsActive"],
                    out isActive) || isActive < 0 || isActive > 255)
                {
                    comman.Code = 410;
                    comman.Message = "Invalid IsActive value.";
                    WriteJsonResponse(comman);
                    return;
                }

                WeftColorMaster ilist = new WeftColorMaster
                {
                    WeftColor = weftColor,
                    IsActive = isActive,
                    UserAccountId = checked((int)userId),
                    CompanyId = checked((int)companyId)
                };

                DateTime dateTimeIndian =
                    TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            using (SqlCommand cmdDup = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.WeftColorMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE WeftColor = @WeftColor
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdDup.Parameters.Add("@WeftColor", SqlDbType.NVarChar, 100)
                                    .Value = weftColor;

                                cmdDup.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                if (Convert.ToInt32(cmdDup.ExecuteScalar()) > 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 410;
                                    comman.Message = "This Weft Color already Exists.";
                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            int position = 1;

                            using (SqlCommand cmdPos = new SqlCommand(@"
                        SELECT ISNULL(MAX(Position), 0) + 1
                        FROM dbo.WeftColorMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdPos.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                position = Convert.ToInt32(cmdPos.ExecuteScalar());
                            }

                            int newId;

                            using (SqlCommand cmdInsert = new SqlCommand(@"
                        INSERT INTO dbo.WeftColorMaster
                        (
                            DateandTime,
                            WeftColor,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        )
                        OUTPUT INSERTED.WeftColorID
                        VALUES
                        (
                            @DateandTime,
                            @WeftColor,
                            @IsActive,
                            @Position,
                            @CompanyId,
                            @UserAccountId
                        )",
                                con, tran))
                            {
                                cmdInsert.Parameters.Add("@DateandTime", SqlDbType.DateTime)
                                    .Value = dateTimeIndian;

                                cmdInsert.Parameters.Add("@WeftColor", SqlDbType.NVarChar, 100)
                                    .Value = weftColor;

                                cmdInsert.Parameters.Add("@IsActive", SqlDbType.TinyInt)
                                    .Value = (byte)isActive;

                                cmdInsert.Parameters.Add("@Position", SqlDbType.Int)
                                    .Value = position;

                                cmdInsert.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                cmdInsert.Parameters.Add("@UserAccountId", SqlDbType.BigInt)
                                    .Value = userId;

                                newId = Convert.ToInt32(cmdInsert.ExecuteScalar());
                            }

                            if (newId <= 0)
                            {
                                tran.Rollback();

                                comman.Code = 500;
                                comman.Message = "Problem occurred while saving Weft Color.";
                                WriteJsonResponse(comman);
                                return;
                            }

                            ilist.WeftColorID = newId;

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Weft Color",
                                action: "INSERT",
                                tableName: "WeftColorMaster",
                                recordId: newId.ToString(),
                                description: "Inserted Weft Color: " + weftColor +
                                             " (ID: " + newId + ")",
                                oldValue: null,
                                newValue: ilist,
                                customUserId: userId
                            );

                            tran.Commit();

                            comman.Code = 201;
                            comman.Message = "Weft Color has been saved successfully.";
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertWeftColorMaster SQL Error: " + ex.ToString()
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "This Weft Color already Exists.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem occurred while saving Weft Color.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertWeftColorMaster Error: " + ex.ToString()
                );

                comman.Code = 500;
                comman.Message = "Problem occurred while saving Weft Color.";
            }

            WriteJsonResponse(comman);
        }
