        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditWeftColorMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);
            CommanResponse comman = new CommanResponse();

            try
            {
                if (Context.Request.Cookies["UserIDs"] == null || Context.Request.Cookies["CompanyID"] == null)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Session cookies missing.";
                    WriteJsonResponse(comman);
                    return;
                }

                WeftColorMaster ilist = new WeftColorMaster();
                int wcId = 0;
                int.TryParse(HttpContext.Current.Request.Params["WeftColorID"], out wcId);
                ilist.WeftColorID = wcId;
                ilist.WeftColor = HttpContext.Current.Request.Params["WeftColor"]?.Trim().ToUpper();
                int isActive = 0;
                int.TryParse(HttpContext.Current.Request.Params["IsActive"], out isActive);
                ilist.IsActive = isActive;
                ilist.UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
                ilist.CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);

                if (ilist.WeftColorID <= 0)
                {
                    comman.Code = 410;
                    comman.Message = "Invalid Weft Color ID.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (string.IsNullOrWhiteSpace(ilist.WeftColor))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Weft Color.";
                    WriteJsonResponse(comman);
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();
                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.ReadCommitted))
                    {
                        try
                        {
                            // Fetch old value with concurrency lock
                            object oldValue = null;
                            using (SqlCommand cmdFetch = new SqlCommand(@"
                                SELECT WeftColorID, DateandTime, WeftColor, IsActive, Position, CompanyId, UserAccountId
                                FROM WeftColorMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE WeftColorID = @WeftColorID AND CompanyId = @CompanyId", con, tran))
                            {
                                cmdFetch.Parameters.Add("@WeftColorID", SqlDbType.Int).Value = ilist.WeftColorID;
                                cmdFetch.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = ilist.CompanyId;
                                using (SqlDataReader rdr = cmdFetch.ExecuteReader())
                                {
                                    if (rdr.Read())
                                    {
                                        oldValue = new
                                        {
                                            WeftColorID = Convert.ToInt32(rdr["WeftColorID"]),
                                            DateandTime = Convert.ToDateTime(rdr["DateandTime"]),
                                            WeftColor = rdr["WeftColor"].ToString(),
                                            IsActive = Convert.ToInt32(rdr["IsActive"]),
                                            Position = Convert.ToInt32(rdr["Position"]),
                                            CompanyId = Convert.ToInt64(rdr["CompanyId"]),
                                            UserAccountId = Convert.ToInt64(rdr["UserAccountId"])
                                        };
                                    }
                                }
                            }

                            if (oldValue == null)
                            {
                                tran.Rollback();
                                comman.Code = 410;
                                comman.Message = "Record not found or already modified.";
                                WriteJsonResponse(comman);
                                return;
                            }

                            // Concurrency duplicate check scoped by CompanyId
                            using (SqlCommand cmdDup = new SqlCommand(@"
                                SELECT COUNT(1) FROM WeftColorMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE WeftColor = @WeftColor AND CompanyId = @CompanyId AND WeftColorID <> @WeftColorID", con, tran))
                            {
                                cmdDup.Parameters.Add("@WeftColor", SqlDbType.NVarChar, 100).Value = ilist.WeftColor;
                                cmdDup.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = ilist.CompanyId;
                                cmdDup.Parameters.Add("@WeftColorID", SqlDbType.Int).Value = ilist.WeftColorID;
                                int dupCount = Convert.ToInt32(cmdDup.ExecuteScalar());
                                if (dupCount > 0)
                                {
                                    tran.Rollback();
                                    comman.Code = 410;
                                    comman.Message = "Weft Color already Exists.";
                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // Parameterized UPDATE (ID immutable in WHERE clause, CompanyId preserved)
                            int rowsAffected = 0;
                            using (SqlCommand cmd = new SqlCommand(@"
                                UPDATE WeftColorMaster
                                SET WeftColor = @WeftColor, IsActive = @IsActive, UserAccountId = @UserAccountId
                                WHERE WeftColorID = @WeftColorID AND CompanyId = @CompanyId", con, tran))
                            {
                                cmd.Parameters.Add("@WeftColor", SqlDbType.NVarChar, 100).Value = ilist.WeftColor;
                                cmd.Parameters.Add("@IsActive", SqlDbType.TinyInt).Value = (byte)ilist.IsActive;
                                cmd.Parameters.Add("@UserAccountId", SqlDbType.BigInt).Value = ilist.UserAccountId;
                                cmd.Parameters.Add("@WeftColorID", SqlDbType.Int).Value = ilist.WeftColorID;
                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = ilist.CompanyId;

                                rowsAffected = cmd.ExecuteNonQuery();
                            }

                            if (rowsAffected > 0)
                            {
                                AuditLogHelper.LogTransactional(
                                    conn: con,
                                    tran: tran,
                                    module: "Weft Color",
                                    action: "UPDATE",
                                    tableName: "WeftColorMaster",
                                    recordId: ilist.WeftColorID.ToString(),
                                    description: $"Updated Weft Color: {ilist.WeftColor} (ID: {ilist.WeftColorID})",
                                    oldValue: oldValue,
                                    newValue: ilist,
                                    customUserId: (long)ilist.UserAccountId
                                );

                                tran.Commit();
                                comman.Code = 201;
                                comman.Message = "Weft Color has been updated successfully.";
                            }
                            else
                            {
                                tran.Rollback();
                                comman.Code = 410;
                                comman.Message = "Weft Color already Exists.";
                            }
                        }
                        catch (SqlException ex)
                        {
                            try { tran.Rollback(); } catch { }
                            if (ex.Number == 2601 || ex.Number == 2627)
                            {
                                comman.Code = 405;
                                comman.Message = "Cannot insert duplicate values..";
                            }
                            else
                            {
                                comman.Code = 410;
                                comman.Message = "Problem has been occurred while submitting your data.";
                            }
                        }
                        catch (Exception)
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                comman.Code = 500;
                comman.Message = "Problem has been occurred while submitting your data: " + ex.Message;
            }

            WriteJsonResponse(comman);
        }
