                long companyId;
                long userAccountId;

                string idValue = Context.Request.Params["WeftColorID"];

                if (!int.TryParse(idValue, out wcId) || wcId <= 0)
                {
                    comman.Code = 410;
                    comman.Message = "Invalid Weft Color ID.";
                    WriteJsonResponse(comman);
                    return;
                }

                string companyValue = companyCookie.Value.Split('=')[1];
                string userValue = userCookie.Value.Split('=')[1];

                if (!long.TryParse(companyValue, out companyId) || companyId <= 0 ||
                    !long.TryParse(userValue, out userAccountId) || userAccountId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Invalid session information.";
                    WriteJsonResponse(comman);
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.ReadCommitted))
                    {
                        try
                        {
                            object oldValue = null;

                            using (SqlCommand cmdFetch = new SqlCommand(@"
                        SELECT WeftColorID, DateandTime, WeftColor, IsActive,
                               Position, CompanyId, UserAccountId
                        FROM dbo.WeftColorMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE WeftColorID = @WeftColorID
                          AND CompanyId = @CompanyId", con, tran))
                            {
                                cmdFetch.Parameters.Add("@WeftColorID", SqlDbType.Int).Value = wcId;
                                cmdFetch.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                                using (SqlDataReader rdr = cmdFetch.ExecuteReader())
                                {
                                    if (rdr.Read())
                                    {
                                        oldValue = new
                                        {
                                            WeftColorID = Convert.ToInt32(rdr["WeftColorID"]),
                                            DateandTime = rdr["DateandTime"] == DBNull.Value
                                                ? (DateTime?)null
                                                : Convert.ToDateTime(rdr["DateandTime"]),
                                            WeftColor = rdr["WeftColor"] == DBNull.Value
                                                ? ""
                                                : rdr["WeftColor"].ToString(),
                                            IsActive = Convert.ToInt32(rdr["IsActive"]),
                                            Position = Convert.ToInt32(rdr["Position"]),
                                            CompanyId = Convert.ToInt64(rdr["CompanyId"]),
                                            UserAccountId = Convert.ToInt64(rdr["UserAccountId"])
                                        };
                                    }
                                }
                            }

                            if (oldValue == null)
                            {
                                tran.Rollback();
                                comman.Code = 410;
                                comman.Message = "Record not found or already deleted.";
                                WriteJsonResponse(comman);
                                return;
                            }

                            int rowsAffected;

                            using (SqlCommand cmdDel = new SqlCommand(@"
                        DELETE FROM dbo.WeftColorMaster
                        WHERE WeftColorID = @WeftColorID
                          AND CompanyId = @CompanyId", con, tran))
                            {
                                cmdDel.Parameters.Add("@WeftColorID", SqlDbType.Int).Value = wcId;
                                cmdDel.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                                rowsAffected = cmdDel.ExecuteNonQuery();
                            }

                            if (rowsAffected <= 0)
                            {
                                tran.Rollback();
                                comman.Code = 410;
                                comman.Message = "Failed to delete record.";
                                WriteJsonResponse(comman);
                                return;
                            }

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Weft Color",
                                action: "DELETE",
                                tableName: "WeftColorMaster",
                                recordId: wcId.ToString(),
                                description: "Deleted Weft Color ID: " + wcId,
                                oldValue: oldValue,
                                newValue: null,
                                customUserId: userAccountId
                            );

                            tran.Commit();

                            comman.Code = 200;
                            comman.Message = "Record Deleted Successfully.";
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine("DeleteWeftColorMaster Error: " + ex);
                comman.Code = 500;
                comman.Message = "Problem has been occurred while deleting your data.";
            }

            WriteJsonResponse(comman);
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_WeftColorQueue()
        {
            WeftColorMasterResponse comman = new WeftColorMasterResponse();

            try
            {
                if (Context.Request.Cookies["UserIDs"] == null || Context.Request.Cookies["CompanyID"] == null)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Unauthorized access.";
                    WriteWeftColorResponse(comman);
                    return;
                }

                int userAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
                int companyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);

                string postQueueStr = HttpContext.Current.Request.Params["PostQueue"];
                if (string.IsNullOrWhiteSpace(postQueueStr) || !postQueueStr.Contains("|"))
                {
                    comman.Code = 0;
                    comman.Message = "Error: Invalid queue parameters.";
                    WriteWeftColorResponse(comman);
                    return;
                }

                string[] postQueue = postQueueStr.Split('|');
                var oneParts = postQueue[0].Split(',');
                var twoParts = postQueue[1].Split(',');

                int oneId = Convert.ToInt32(oneParts[0]);
                int oneQueue = Convert.ToInt32(oneParts[1]);

                int twoId = Convert.ToInt32(twoParts[0]);
                int twoQueue = Convert.ToInt32(twoParts[1]);

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection conn = new SqlConnection(cs))
                {
                    conn.Open();
                    using (SqlTransaction tran = conn.BeginTransaction(IsolationLevel.ReadCommitted))
                    {
                        try
                        {
                            using (SqlCommand cmd1 = new SqlCommand(
                                "UPDATE WeftColorMaster SET Position = @Position WHERE WeftColorID = @ID AND CompanyId = @CompanyId", conn, tran))
                            {
                                cmd1.Parameters.Add("@Position", SqlDbType.Int).Value = twoQueue;
                                cmd1.Parameters.Add("@ID", SqlDbType.Int).Value = oneId;
                                cmd1.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmd1.ExecuteNonQuery();
                            }

                            using (SqlCommand cmd2 = new SqlCommand(
                                "UPDATE WeftColorMaster SET Position = @Position WHERE WeftColorID = @ID AND CompanyId = @CompanyId", conn, tran))
                            {
                                cmd2.Parameters.Add("@Position", SqlDbType.Int).Value = oneQueue;
                                cmd2.Parameters.Add("@ID", SqlDbType.Int).Value = twoId;
                                cmd2.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmd2.ExecuteNonQuery();
                            }

                            AuditLogHelper.LogTransactional(
                                conn: conn,
                                tran: tran,
                                module: "Weft Color",
                                action: "UPDATE",
                                tableName: "WeftColorMaster",
                                recordId: oneId.ToString(),
                                description: $"Reordered WeftColor Queue: ID {oneId} -> Pos {twoQueue}, ID {twoId} -> Pos {oneQueue}",
                                oldValue: null,
                                newValue: new { Item1 = oneId, Pos1 = twoQueue, Item2 = twoId, Pos2 = oneQueue },
                                customUserId: (long)userAccountId
                            );

                            tran.Commit();
                            comman.Code = 1;
                            comman.Message = "Success";
                        }
                        catch (Exception)
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception)
            {
                comman.Code = 0;
                comman.Message = "Error";
            }

            WriteWeftColorResponse(comman);
        }

        private void WriteWeftColorResponse(WeftColorMasterResponse responseObj)
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(responseObj));
        }
