        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertDesignerMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);
            CommanResponse comman = new CommanResponse();
            DesignerMaster ilist = new DesignerMaster();

            string designerCode = "";
            string designerName = "";

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Session cookies missing.";
                    WriteJsonResponse(comman);
                    return;
                }

                string userValue = userCookie.Value;
                string companyValue = companyCookie.Value;

                if (userValue.Contains("="))
                    userValue = userValue.Substring(userValue.LastIndexOf('=') + 1);

                if (companyValue.Contains("="))
                    companyValue = companyValue.Substring(companyValue.LastIndexOf('=') + 1);

                long userId;
                long companyId;

                if (!long.TryParse(userValue, out userId) || !long.TryParse(companyValue, out companyId) ||
                    userId <= 0 || companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Invalid session values.";
                    WriteJsonResponse(comman);
                    return;
                }

                var request = HttpContext.Current.Request;

                designerCode = (request.Params["DesignerCode"] ?? "").Trim();
                designerName = (request.Params["DesignerName"] ?? "").Trim();
                string address = (request.Params["Address"] ?? "").Trim();
                string bankName = (request.Params["BankName"] ?? "").Trim();
                string bankAcNo = (request.Params["BankAcNo"] ?? "").Trim();
                string ifscCode = (request.Params["IFSCCode"] ?? "").Trim();

                int isActive = 1;
                int.TryParse(request.Params["IsActive"], out isActive);

                if (string.IsNullOrWhiteSpace(designerCode))
                {
                    AuditLogHelper.LogValidationError("Designer", "DesignerMaster", null, "Please Mention Designer Code.", "DesignerCode is empty");
                    comman.Code = 410;
                    comman.Message = "Please Mention Designer Code.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (string.IsNullOrWhiteSpace(designerName))
                {
                    AuditLogHelper.LogValidationError("Designer", "DesignerMaster", null, "Please Mention Designer Name.", "DesignerName is empty");
                    comman.Code = 410;
                    comman.Message = "Please Mention Designer Name.";
                    WriteJsonResponse(comman);
                    return;
                }

                HttpPostedFile photo1 = null;
                string aadharUpload = "";

                if (request.Files.Count > 0 && request.Files["AadharUpload"] != null && request.Files["AadharUpload"].ContentLength > 0)
                {
                    photo1 = request.Files["AadharUpload"];
                    aadharUpload = "AadharUpload/" + RandomString(6, true) + Path.GetFileName(photo1.FileName);
                }

                ilist.DesignerCode = designerCode.ToUpper();
                ilist.DesignerName = designerName.ToUpper();
                ilist.Address = string.IsNullOrEmpty(address) ? "" : address.ToUpper();
                ilist.BankName = string.IsNullOrEmpty(bankName) ? "" : bankName.ToUpper();
                ilist.BankAcNo = bankAcNo;
                ilist.IFSCCode = string.IsNullOrEmpty(ifscCode) ? "" : ifscCode.ToUpper();
                ilist.AadharUpload = aadharUpload;
                ilist.IsActive = isActive;
                ilist.CompanyId = checked((int)companyId);
                ilist.UserAccountId = checked((int)userId);

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            using (SqlCommand cmdDup = new SqlCommand(@"
                                SELECT COUNT(1)
                                FROM dbo.DesignerMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE DesignerCode = @DesignerCode
                                  AND CompanyId = @CompanyId", con, tran))
                            {
                                cmdDup.Parameters.Add("@DesignerCode", SqlDbType.NVarChar, 20).Value = designerCode.ToUpper();
                                cmdDup.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                                if (Convert.ToInt32(cmdDup.ExecuteScalar()) > 0)
                                {
                                    tran.Rollback();
                                    AuditLogHelper.LogDuplicateError("Designer", "DesignerMaster", "DesignerCode", designerCode, "This Designer is already Exists.", ilist);
                                    comman.Code = 410;
                                    comman.Message = "This Designer is already Exists.";
                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            int position = 1;
                            using (SqlCommand cmdPos = new SqlCommand(@"
                                SELECT ISNULL(MAX(Position), 0) + 1
                                FROM dbo.DesignerMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE CompanyId = @CompanyId", con, tran))
                            {
                                cmdPos.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                position = Convert.ToInt32(cmdPos.ExecuteScalar());
                            }

                            int newId;
                            using (SqlCommand cmdInsert = new SqlCommand(@"
                                INSERT INTO dbo.DesignerMaster
                                (
                                    DateAndTime,
                                    DesignerCode,
                                    DesignerName,
                                    Address,
                                    BankName,
                                    BankAcNo,
                                    IFSCCode,
                                    AadharUpload,
                                    IsActive,
                                    Position,
                                    CompanyId,
                                    UserAccountId
                                )
                                OUTPUT INSERTED.DesignerID
                                VALUES
                                (
                                    @DateAndTime,
                                    @DesignerCode,
                                    @DesignerName,
                                    @Address,
                                    @BankName,
                                    @BankAcNo,
                                    @IFSCCode,
                                    @AadharUpload,
                                    @IsActive,
                                    @Position,
                                    @CompanyId,
                                    @UserAccountId
                                )", con, tran))
                            {
                                cmdInsert.Parameters.Add("@DateAndTime", SqlDbType.DateTime).Value = dateTime_Indian;
                                cmdInsert.Parameters.Add("@DesignerCode", SqlDbType.NVarChar, 20).Value = designerCode.ToUpper();
                                cmdInsert.Parameters.Add("@DesignerName", SqlDbType.NVarChar, 100).Value = designerName.ToUpper();
                                cmdInsert.Parameters.Add("@Address", SqlDbType.NChar, 100).Value = string.IsNullOrEmpty(address) ? (object)DBNull.Value : address.ToUpper();
                                cmdInsert.Parameters.Add("@BankName", SqlDbType.NVarChar, 100).Value = string.IsNullOrEmpty(bankName) ? (object)DBNull.Value : bankName.ToUpper();
                                cmdInsert.Parameters.Add("@BankAcNo", SqlDbType.NVarChar, 50).Value = string.IsNullOrEmpty(bankAcNo) ? (object)DBNull.Value : bankAcNo;
                                cmdInsert.Parameters.Add("@IFSCCode", SqlDbType.NVarChar, 50).Value = string.IsNullOrEmpty(ifscCode) ? (object)DBNull.Value : ifscCode.ToUpper();
                                cmdInsert.Parameters.Add("@AadharUpload", SqlDbType.NVarChar, -1).Value = string.IsNullOrEmpty(aadharUpload) ? (object)DBNull.Value : aadharUpload;
                                cmdInsert.Parameters.Add("@IsActive", SqlDbType.TinyInt).Value = (byte)isActive;
                                cmdInsert.Parameters.Add("@Position", SqlDbType.Int).Value = position;
                                cmdInsert.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmdInsert.Parameters.Add("@UserAccountId", SqlDbType.BigInt).Value = userId;

                                newId = Convert.ToInt32(cmdInsert.ExecuteScalar());
                            }

                            if (newId <= 0)
                            {
                                tran.Rollback();
                                comman.Code = 500;
                                comman.Message = "Problem has been occurred while submitting your data.";
                                WriteJsonResponse(comman);
                                return;
                            }

                            ilist.DesignerID = newId;
                            ilist.Position = position;

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Designer",
                                action: "CREATE",
                                tableName: "DesignerMaster",
                                recordId: newId.ToString(),
                                description: $"Created Designer '{designerName.ToUpper()}' (Code: {designerCode.ToUpper()}) (ID: {newId})",
                                oldValue: null,
                                newValue: ilist,
                                customUserId: userId
                            );

                            tran.Commit();

                            if (photo1 != null && !string.IsNullOrEmpty(aadharUpload))
                            {
                                try
                                {
                                    string fullPath = HttpContext.Current.Server.MapPath("~/" + aadharUpload);
                                    string dir = Path.GetDirectoryName(fullPath);
                                    if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
                                    photo1.SaveAs(fullPath);
                                }
                                catch (Exception fileEx)
                                {
                                    System.Diagnostics.Trace.WriteLine("Failed to save AadharUpload file: " + fileEx.Message);
                                }
                            }

                            comman.Code = 201;
                            comman.Message = "Designer has been saved successfully.";
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError("Designer", "insertDesignerMaster", ex, $"Code: {designerCode}, Name: {designerName}");

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    AuditLogHelper.LogDuplicateError("Designer", "DesignerMaster", "DesignerCode", designerCode, "Cannot insert duplicate values..", ilist);
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Designer", "insertDesignerMaster", ex, $"Code: {designerCode}, Name: {designerName}");
                comman.Code = 500;
                comman.Message = "Problem has been occurred while submitting your data.";
            }

            WriteJsonResponse(comman);
        }
