        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignerMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<DesignerMaster> listUser = new List<DesignerMaster>();
            DesignerMasterResponse response = new DesignerMasterResponse();

            try
            {
                string searchDesigner =
                    HttpContext.Current.Request.Params["searchDesigner"] ?? "";

                int startFrom = 0;

                if (!int.TryParse(
                    HttpContext.Current.Request.Params["startFrom"],
                    out startFrom) || startFrom < 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid pagination value.";
                    response.listDesignerMaster = listUser;
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    string sql = @"
                SELECT *
                FROM dbo.DesignerMaster
                WHERE
                (
                    @Search = ''
                    OR DesignerCode LIKE @SearchPattern
                    OR DesignerName LIKE @SearchPattern
                    OR Address LIKE @SearchPattern
                    OR BankName LIKE @SearchPattern
                    OR BankAcNo LIKE @SearchPattern
                    OR IFSCCode LIKE @SearchPattern
                )
                ORDER BY Position DESC
                OFFSET @StartFrom ROWS FETCH NEXT 10 ROWS ONLY";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@Search", SqlDbType.NVarChar, 200)
                            .Value = searchDesigner.Trim();

                        cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar, 402)
                            .Value = "%" + searchDesigner.Trim() + "%";

                        cmd.Parameters.Add("@StartFrom", SqlDbType.Int)
                            .Value = startFrom;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                DesignerMaster condition = new DesignerMaster();

                                condition.DesignerID = Convert.ToInt32(rdr["DesignerID"]);
                                condition.IsActive = Convert.ToInt32(rdr["IsActive"]);
                                condition.Position = Convert.ToInt32(rdr["Position"]);

                                condition.DateandTime = rdr["DateandTime"] == DBNull.Value
                                    ? DateTime.MinValue
                                    : Convert.ToDateTime(rdr["DateandTime"]);

                                condition.DateandTimes = rdr["DateandTime"] == DBNull.Value
                                    ? ""
                                    : Convert.ToDateTime(rdr["DateandTime"]).ToString("dd-MM-yyyy");

                                condition.DesignerCode = rdr["DesignerCode"] == DBNull.Value
                                    ? ""
                                    : rdr["DesignerCode"].ToString().ToUpper();

                                condition.DesignerName = rdr["DesignerName"] == DBNull.Value
                                    ? ""
                                    : rdr["DesignerName"].ToString().ToUpper();

                                condition.Address = rdr["Address"] == DBNull.Value
                                    ? ""
                                    : rdr["Address"].ToString().ToUpper();

                                condition.BankName = rdr["BankName"] == DBNull.Value
                                    ? ""
                                    : rdr["BankName"].ToString().ToUpper();

                                condition.BankAcNo = rdr["BankAcNo"] == DBNull.Value
                                    ? ""
                                    : rdr["BankAcNo"].ToString().ToUpper();

                                condition.IFSCCode = rdr["IFSCCode"] == DBNull.Value
                                    ? ""
                                    : rdr["IFSCCode"].ToString().ToUpper();

                                condition.AadharUpload = rdr["AadharUpload"] == DBNull.Value
                                    ? ""
                                    : rdr["AadharUpload"].ToString();

                                listUser.Add(condition);
                            }
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listDesignerMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getDesignerMaster Error: " + ex);

                response.Code = 500;
                response.Message = "Unable to retrieve Designer Master data.";
                response.listDesignerMaster = new List<DesignerMaster>();
            }

            Context.Response.Write(js.Serialize(response));
        }
        // Get Edit Party Category Master 
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignerMasterById(string id)
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<DesignerMaster> listUser = new List<DesignerMaster>();
            DesignerMasterResponse response = new DesignerMasterResponse();

            try
            {
                int designerID;

                if (!int.TryParse(id, out designerID) || designerID <= 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid Designer ID.";
                    response.listDesignerMaster = listUser;

                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    string sql = @"
                SELECT *
                FROM dbo.DesignerMaster
                WHERE DesignerID = @DesignerID";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@DesignerID", SqlDbType.Int).Value = designerID;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                DesignerMaster condition = new DesignerMaster();

                                condition.DesignerID = Convert.ToInt32(rdr["DesignerID"]);

                                condition.DesignerCode = rdr["DesignerCode"] == DBNull.Value
                                    ? ""
                                    : rdr["DesignerCode"].ToString().ToUpper();

                                condition.DesignerName = rdr["DesignerName"] == DBNull.Value
                                    ? ""
                                    : rdr["DesignerName"].ToString().ToUpper();

                                condition.Address = rdr["Address"] == DBNull.Value
                                    ? ""
                                    : rdr["Address"].ToString().ToUpper();

                                condition.BankName = rdr["BankName"] == DBNull.Value
                                    ? ""
                                    : rdr["BankName"].ToString().ToUpper();

                                condition.BankAcNo = rdr["BankAcNo"] == DBNull.Value
                                    ? ""
                                    : rdr["BankAcNo"].ToString().ToUpper();

                                condition.IFSCCode = rdr["IFSCCode"] == DBNull.Value
                                    ? ""
                                    : rdr["IFSCCode"].ToString().ToUpper();

                                condition.AadharUpload = rdr["AadharUpload"] == DBNull.Value
                                    ? ""
                                    : rdr["AadharUpload"].ToString();

                                condition.IsActive = rdr["IsActive"] == DBNull.Value
                                    ? 0
                                    : Convert.ToInt32(rdr["IsActive"]);

                                listUser.Add(condition);
                            }
                        }
                    }
                }

                response.Code = 200;
                response.Message = "Success";
                response.listDesignerMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getDesignerMasterById Error: " + ex);

                response.Code = 500;
                response.Message = "Unable to retrieve Designer Master data.";
                response.listDesignerMaster = new List<DesignerMaster>();
            }

            Context.Response.Write(js.Serialize(response));
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditDesignerMaster()
        {
            DateTime dateTime_Indian =
                TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            CommanResponse comman = new CommanResponse();
            DesignerMaster ilist = new DesignerMaster();

            // Declare outside try so catch can also access it
            int designerID = 0;

            string designerCode = "";
            string designerName = "";
            string oldImagePath = "";
            string newImagePath = "";

            HttpPostedFile photo1 = null;

            try
            {
                // 1. Validate session cookies
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Session cookies missing.";
                    WriteJsonResponse(comman);
                    return;
                }

                string userCookieValue = userCookie.Value;
                string companyCookieValue = companyCookie.Value;

                if (userCookieValue.Contains("="))
                    userCookieValue = userCookieValue.Substring(
                        userCookieValue.LastIndexOf('=') + 1);

                if (companyCookieValue.Contains("="))
                    companyCookieValue = companyCookieValue.Substring(
                        companyCookieValue.LastIndexOf('=') + 1);

                long userId;
                long companyId;

                if (!long.TryParse(userCookieValue, out userId) || userId <= 0 ||
                    !long.TryParse(companyCookieValue, out companyId) || companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Invalid session information.";
                    WriteJsonResponse(comman);
                    return;
                }

                // 2. Validate request
                var request = HttpContext.Current.Request;

                if (!int.TryParse(request.Params["DesignerID"], out designerID) ||
                    designerID <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Designer ID.";
                    WriteJsonResponse(comman);
                    return;
                }

                designerCode = (request.Params["DesignerCode"] ?? "").Trim();
                designerName = (request.Params["DesignerName"] ?? "").Trim();

                string address = (request.Params["Address"] ?? "").Trim();
                string bankName = (request.Params["BankName"] ?? "").Trim();
                string bankAcNo = (request.Params["BankAcNo"] ?? "").Trim();
                string ifscCode = (request.Params["IFSCCode"] ?? "").Trim();

                if (string.IsNullOrWhiteSpace(designerCode))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Designer Code.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (string.IsNullOrWhiteSpace(designerName))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Designer Name.";
                    WriteJsonResponse(comman);
                    return;
                }

                int isActive = 0;

                if (!int.TryParse(request.Params["IsActive"], out isActive) ||
                    isActive < 0 || isActive > 255)
                {
                    comman.Code = 410;
                    comman.Message = "Invalid IsActive value.";
                    WriteJsonResponse(comman);
                    return;
                }

                // 3. Optional Aadhar upload
                if (request.Files["AadharUpload"] != null &&
                    request.Files["AadharUpload"].ContentLength > 0)
                {
                    photo1 = request.Files["AadharUpload"];

                    newImagePath = "AadharUpload/" +
                        RandomString(6, true) +
                        Path.GetFileName(photo1.FileName);
                }

                // 4. Prepare model
                ilist.DesignerID = designerID;
                ilist.DesignerCode = designerCode.ToUpper();
                ilist.DesignerName = designerName.ToUpper();
                ilist.Address = string.IsNullOrEmpty(address) ? "" : address.ToUpper();
                ilist.BankName = string.IsNullOrEmpty(bankName) ? "" : bankName.ToUpper();
                ilist.BankAcNo = bankAcNo;
                ilist.IFSCCode = string.IsNullOrEmpty(ifscCode) ? "" : ifscCode.ToUpper();
                ilist.IsActive = isActive;
                ilist.CompanyId = checked((int)companyId);
                ilist.UserAccountId = checked((int)userId);

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            object oldValue = null;
                            string existingDesignerCode = "";

                            // 5. Fetch existing Designer record
                            using (SqlCommand cmdFetch = new SqlCommand(@"
                        SELECT
                            DesignerID,
                            DateandTime,
                            DesignerCode,
                            DesignerName,
                            Address,
                            BankName,
                            BankAcNo,
                            IFSCCode,
                            AadharUpload,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        FROM dbo.DesignerMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE DesignerID = @DesignerID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdFetch.Parameters.Add("@DesignerID", SqlDbType.Int)
                                    .Value = designerID;

                                cmdFetch.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                using (SqlDataReader rdr = cmdFetch.ExecuteReader())
                                {
                                    if (rdr.Read())
                                    {
                                        existingDesignerCode =
                                            rdr["DesignerCode"] == DBNull.Value
                                                ? ""
                                                : rdr["DesignerCode"].ToString().Trim();

                                        oldImagePath =
                                            rdr["AadharUpload"] == DBNull.Value
                                                ? ""
                                                : rdr["AadharUpload"].ToString();

                                        oldValue = new
                                        {
                                            DesignerID = Convert.ToInt32(rdr["DesignerID"]),

                                            DateandTime = rdr["DateandTime"] == DBNull.Value
                                                ? DateTime.MinValue
                                                : Convert.ToDateTime(rdr["DateandTime"]),

                                            DesignerCode = existingDesignerCode,

                                            DesignerName = rdr["DesignerName"] == DBNull.Value
                                                ? ""
                                                : rdr["DesignerName"].ToString(),

                                            Address = rdr["Address"] == DBNull.Value
                                                ? ""
                                                : rdr["Address"].ToString(),

                                            BankName = rdr["BankName"] == DBNull.Value
                                                ? ""
                                                : rdr["BankName"].ToString(),

                                            BankAcNo = rdr["BankAcNo"] == DBNull.Value
                                                ? ""
                                                : rdr["BankAcNo"].ToString(),

                                            IFSCCode = rdr["IFSCCode"] == DBNull.Value
                                                ? ""
                                                : rdr["IFSCCode"].ToString(),

                                            AadharUpload = oldImagePath,

                                            IsActive = rdr["IsActive"] == DBNull.Value
                                                ? 0
                                                : Convert.ToInt32(rdr["IsActive"]),

                                            Position = rdr["Position"] == DBNull.Value
                                                ? 0
                                                : Convert.ToInt32(rdr["Position"]),

                                            CompanyId = rdr["CompanyId"] == DBNull.Value
                                                ? 0L
                                                : Convert.ToInt64(rdr["CompanyId"]),

                                            UserAccountId = rdr["UserAccountId"] == DBNull.Value
                                                ? 0L
                                                : Convert.ToInt64(rdr["UserAccountId"])
                                        };
                                    }
                                }
                            }

                            // 6. Designer record not found
                            if (oldValue == null)
                            {
                                tran.Rollback();

                                comman.Code = 404;
                                comman.Message = "Designer record not found.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // 7. Check dependency before changing DesignerCode
                            bool designerCodeChanged =
                                !string.Equals(
                                    existingDesignerCode,
                                    designerCode,
                                    StringComparison.OrdinalIgnoreCase);

                            if (designerCodeChanged)
                            {
                                using (SqlCommand cmdCheck = new SqlCommand(@"
                            SELECT TOP 1
                                DesignerID,
                                DesignerCode,
                                DesignNo
                            FROM dbo.DesignEntryFormMaster WITH (UPDLOCK, HOLDLOCK)
                            WHERE DesignerID = @DesignerID
                            ORDER BY DesignNo",
                                    con, tran))
                                {
                                    cmdCheck.Parameters.Add("@DesignerID", SqlDbType.Int)
                                        .Value = designerID;

                                    using (SqlDataReader depReader =
                                        cmdCheck.ExecuteReader())
                                    {
                                        if (depReader.Read())
                                        {
                                            string linkedDesignerCode =
                                                depReader["DesignerCode"] == DBNull.Value
                                                    ? ""
                                                    : depReader["DesignerCode"].ToString();

                                            string designNo =
                                                depReader["DesignNo"] == DBNull.Value
                                                    ? ""
                                                    : depReader["DesignNo"].ToString();

                                            depReader.Close();

                                            tran.Rollback();

                                            comman.Code = 400;
                                            comman.Message = "This Designer cannot be deleted because it is already used in Design Entry records. ";
                                            WriteJsonResponse(comman);
                                            return;
                                        }
                                    }
                                }
                            }

                            // 8. Check duplicate Designer Code
                            using (SqlCommand cmdDup = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignerMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE DesignerCode = @DesignerCode
                          AND CompanyId = @CompanyId
                          AND DesignerID <> @DesignerID",
                                con, tran))
                            {
                                cmdDup.Parameters.Add("@DesignerCode", SqlDbType.NVarChar, 20)
                                    .Value = designerCode.ToUpper();

                                cmdDup.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                cmdDup.Parameters.Add("@DesignerID", SqlDbType.Int)
                                    .Value = designerID;

                                if (Convert.ToInt32(cmdDup.ExecuteScalar()) > 0)
                                {
                                    tran.Rollback();

                                    AuditLogHelper.LogDuplicateError(
                                        "Designer",
                                        "DesignerMaster",
                                        "DesignerCode",
                                        designerCode,
                                        "This Designer is already Exists.",
                                        ilist
                                    );

                                    comman.Code = 409;
                                    comman.Message =
                                        "Designer Code '" + designerCode +
                                        "' already exists. Please use another code.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 9. Keep old image if no new image uploaded
                            string effectiveImagePath =
                                string.IsNullOrEmpty(newImagePath)
                                    ? oldImagePath
                                    : newImagePath;

                            ilist.AadharUpload = effectiveImagePath;

                            // 10. Update Designer record
                            string updateSql = @"
                        UPDATE dbo.DesignerMaster
                        SET
                            DateandTime = @DateandTime,
                            DesignerCode = @DesignerCode,
                            DesignerName = @DesignerName,
                            Address = @Address,
                            BankName = @BankName,
                            BankAcNo = @BankAcNo,
                            IFSCCode = @IFSCCode,
                            AadharUpload = @AadharUpload,
                            IsActive = @IsActive,
                            UserAccountId = @UserAccountId
                        WHERE DesignerID = @DesignerID
                          AND CompanyId = @CompanyId";

                            int rowsAffected = 0;

                            using (SqlCommand cmdUpdate =
                                new SqlCommand(updateSql, con, tran))
                            {
                                cmdUpdate.Parameters.Add("@DateandTime", SqlDbType.DateTime)
                                    .Value = dateTime_Indian;

                                cmdUpdate.Parameters.Add("@DesignerCode", SqlDbType.NVarChar, 20)
                                    .Value = designerCode.ToUpper();

                                cmdUpdate.Parameters.Add("@DesignerName", SqlDbType.NVarChar, 100)
                                    .Value = designerName.ToUpper();

                                cmdUpdate.Parameters.Add("@Address", SqlDbType.NChar, 100)
                                    .Value = string.IsNullOrEmpty(address)
                                        ? (object)DBNull.Value
                                        : address.ToUpper();

                                cmdUpdate.Parameters.Add("@BankName", SqlDbType.NVarChar, 100)
                                    .Value = string.IsNullOrEmpty(bankName)
                                        ? (object)DBNull.Value
                                        : bankName.ToUpper();

                                cmdUpdate.Parameters.Add("@BankAcNo", SqlDbType.NVarChar, 50)
                                    .Value = string.IsNullOrEmpty(bankAcNo)
                                        ? (object)DBNull.Value
                                        : bankAcNo;

                                cmdUpdate.Parameters.Add("@IFSCCode", SqlDbType.NVarChar, 50)
                                    .Value = string.IsNullOrEmpty(ifscCode)
                                        ? (object)DBNull.Value
                                        : ifscCode.ToUpper();

                                cmdUpdate.Parameters.Add("@AadharUpload", SqlDbType.NVarChar, -1)
                                    .Value = string.IsNullOrEmpty(effectiveImagePath)
                                        ? (object)DBNull.Value
                                        : effectiveImagePath;

                                cmdUpdate.Parameters.Add("@IsActive", SqlDbType.TinyInt)
                                    .Value = (byte)isActive;

                                cmdUpdate.Parameters.Add("@UserAccountId", SqlDbType.BigInt)
                                    .Value = userId;

                                cmdUpdate.Parameters.Add("@DesignerID", SqlDbType.Int)
                                    .Value = designerID;

                                cmdUpdate.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                rowsAffected = cmdUpdate.ExecuteNonQuery();
                            }

                            if (rowsAffected != 1)
                            {
                                tran.Rollback();

                                comman.Code = 410;
                                comman.Message =
                                    "Designer record could not be updated.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // 11. Audit log
                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Designer",
                                action: "UPDATE",
                                tableName: "DesignerMaster",
                                recordId: designerID.ToString(),
                                description:
                                    "Updated Designer '" + designerName.ToUpper() +
                                    "' (Code: " + designerCode.ToUpper() +
                                    ") (ID: " + designerID + ")",
                                oldValue: oldValue,
                                newValue: ilist,
                                customUserId: userId
                            );

                            // 12. Commit
                            tran.Commit();

                            // 13. Save new image after successful database update
                            if (photo1 != null && !string.IsNullOrEmpty(newImagePath))
                            {
                                try
                                {
                                    string fullNewPath =
                                        Server.MapPath("~/" + newImagePath);

                                    string dir = Path.GetDirectoryName(fullNewPath);

                                    if (!Directory.Exists(dir))
                                        Directory.CreateDirectory(dir);

                                    photo1.SaveAs(fullNewPath);

                                    // Delete old image only after new image is saved
                                    if (!string.IsNullOrEmpty(oldImagePath))
                                    {
                                        string fullOldPath = Server.MapPath(
                                            "~/" + oldImagePath.TrimStart('~', '/'));

                                        if (File.Exists(fullOldPath))
                                            File.Delete(fullOldPath);
                                    }
                                }
                                catch (Exception fileEx)
                                {
                                    AuditLogHelper.LogError(
                                        "Designer",
                                        "EditDesignerMaster_FileOps",
                                        fileEx,
                                        "DesignerID: " + designerID +
                                        ", NewImage: " + newImagePath
                                    );
                                }
                            }

                            comman.Code = 201;
                            comman.Message =
                                "Designer '" + designerName +
                                "' has been updated successfully.";
                        }
                        catch
                        {
                            try
                            {
                                tran.Rollback();
                            }
                            catch { }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Designer",
                    "EditDesignerMaster",
                    ex,
                    "DesignerID: " + designerID +
                    ", Code: " + designerCode +
                    ", Name: " + designerName
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    AuditLogHelper.LogDuplicateError(
                        "Designer",
                        "DesignerMaster",
                        "DesignerCode",
                        designerCode,
                        "Cannot insert duplicate values.",
                        ilist
                    );

                    comman.Code = 409;
                    comman.Message =
                        "Designer Code already exists. Please use another code.";
                }
                else if (ex.Number == 547)
                {
                    comman.Code = 400;
                    comman.Message =
                        "This Designer cannot be updated because it is used in other records.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message =
                        "Database error occurred while updating Designer.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Designer",
                    "EditDesignerMaster",
                    ex,
                    "DesignerID: " + designerID +
                    ", Code: " + designerCode +
                    ", Name: " + designerName
                );

                comman.Code = 500;
                comman.Message =
                    "Unable to update Designer. Please try again.";
            }

            WriteJsonResponse(comman);
        }
        // Delete User Master
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteDesignerMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse comman = new CommanResponse();

            int designerID = 0;
            string photo = "";

            try
            {
                // 1. Validate session cookies
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    comman.Code = 401;
                    comman.Message = "Your session has expired. Please login again.";
                    WriteJsonResponse(comman);
                    return;
                }

                string userValue = userCookie.Value;
                string companyValue = companyCookie.Value;

                if (userValue.Contains("="))
                    userValue = userValue.Substring(userValue.LastIndexOf('=') + 1);

                if (companyValue.Contains("="))
                    companyValue = companyValue.Substring(companyValue.LastIndexOf('=') + 1);

                long userAccountId;
                long companyId;

                if (!long.TryParse(userValue, out userAccountId) ||
                    userAccountId <= 0 ||
                    !long.TryParse(companyValue, out companyId) ||
                    companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Invalid session information. Please login again.";
                    WriteJsonResponse(comman);
                    return;
                }

                // 2. Validate Designer ID
                if (!int.TryParse(
                    HttpContext.Current.Request.Params["DesignerID"],out designerID) || designerID <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Designer ID. Please select a valid Designer.";
                    WriteJsonResponse(comman);
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    // 3. Start transaction
                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            object oldValue = null;

                            // 4. Fetch Designer record
                            using (SqlCommand cmdFetch = new SqlCommand(@"
                        SELECT
                            DesignerID,
                            DateandTime,
                            DesignerCode,
                            DesignerName,
                            Address,
                            BankName,
                            BankAcNo,
                            IFSCCode,
                            AadharUpload,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        FROM dbo.DesignerMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE DesignerID = @DesignerID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdFetch.Parameters.Add("@DesignerID", SqlDbType.Int)
                                    .Value = designerID;

                                cmdFetch.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                using (SqlDataReader rdr = cmdFetch.ExecuteReader())
                                {
                                    if (rdr.Read())
                                    {
                                        photo = rdr["AadharUpload"] == DBNull.Value
                                            ? ""
                                            : rdr["AadharUpload"].ToString();

                                        oldValue = new
                                        {
                                            DesignerID = Convert.ToInt32(rdr["DesignerID"]),

                                            DateandTime = rdr["DateandTime"] == DBNull.Value
                                                ? DateTime.MinValue
                                                : Convert.ToDateTime(rdr["DateandTime"]),

                                            DesignerCode = rdr["DesignerCode"] == DBNull.Value
                                                ? "" : rdr["DesignerCode"].ToString(),

                                            DesignerName = rdr["DesignerName"] == DBNull.Value
                                                ? "" : rdr["DesignerName"].ToString(),

                                            Address = rdr["Address"] == DBNull.Value
                                                ? "" : rdr["Address"].ToString(),

                                            BankName = rdr["BankName"] == DBNull.Value
                                                ? "" : rdr["BankName"].ToString(),

                                            BankAcNo = rdr["BankAcNo"] == DBNull.Value
                                                ? "" : rdr["BankAcNo"].ToString(),

                                            IFSCCode = rdr["IFSCCode"] == DBNull.Value
                                                ? "" : rdr["IFSCCode"].ToString(),

                                            AadharUpload = photo,

                                            IsActive = rdr["IsActive"] == DBNull.Value
                                                ? 0 : Convert.ToInt32(rdr["IsActive"]),

                                            Position = rdr["Position"] == DBNull.Value
                                                ? 0 : Convert.ToInt32(rdr["Position"]),

                                            CompanyId = rdr["CompanyId"] == DBNull.Value
                                                ? 0L : Convert.ToInt64(rdr["CompanyId"]),

                                            UserAccountId = rdr["UserAccountId"] == DBNull.Value
                                                ? 0L : Convert.ToInt64(rdr["UserAccountId"])
                                        };
                                    }
                                }
                            }

                            // 5. Check Designer exists
                            if (oldValue == null)
                            {
                                tran.Rollback();

                                comman.Code = 404;
                                comman.Message =
                                    "Designer record not found. It may have already been deleted or does not belong to your company.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // 6. Check dependency in DesignEntryMaster
                            using (SqlCommand cmdCheck = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignEntryFormMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE DesignerID = @DesignerID",
                                con, tran))
                            {
                                cmdCheck.Parameters.Add("@DesignerID", SqlDbType.Int)
                                    .Value = designerID;

                                int depCount = Convert.ToInt32(
                                    cmdCheck.ExecuteScalar());

                                if (depCount > 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 400;
                                    comman.Message =
                                        "This Designer cannot be deleted because it is already used in Design Entry records.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 7. Delete Designer record
                            int rowsAffected;

                            using (SqlCommand cmdDelete = new SqlCommand(@"
                        DELETE FROM DesignerMaster
                        WHERE DesignerID = @DesignerID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdDelete.Parameters.Add("@DesignerID", SqlDbType.Int)
                                    .Value = designerID;

                                cmdDelete.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                rowsAffected = cmdDelete.ExecuteNonQuery();
                            }

                            if (rowsAffected != 1)
                            {
                                tran.Rollback();

                                comman.Code = 409;
                                comman.Message =
                                    "Designer record could not be deleted. Please refresh and try again.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // 8. Transactional audit log
                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Designer",
                                action: "DELETE",
                                tableName: "DesignerMaster",
                                recordId: designerID.ToString(),
                                description: "Deleted Designer ID: " + designerID,
                                oldValue: oldValue,
                                newValue: null,
                                customUserId: userAccountId
                            );

                            // 9. Commit transaction
                            tran.Commit();
                        }
                        catch
                        {
                            try
                            {
                                tran.Rollback();
                            }
                            catch { }

                            throw;
                        }
                    }
                }

                // 10. Delete Aadhar image after successful DB deletion
                if (!string.IsNullOrWhiteSpace(photo))
                {
                    try
                    {
                        string relativePath = photo.TrimStart('~', '/');

                        string physicalPath =
                            Server.MapPath("~/" + relativePath);

                        if (File.Exists(physicalPath))
                            File.Delete(physicalPath);
                    }
                    catch (Exception fileEx)
                    {
                        AuditLogHelper.LogError(
                            "Designer",
                            "DeleteDesignerMaster_FileOps",
                            fileEx,
                            "DesignerID: " + designerID +
                            ", Photo: " + photo
                        );
                    }
                }

                comman.Code = 200;
                comman.Message = "Designer deleted successfully.";

            }
            catch (SqlException ex)
            {
