        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_DesignerQueue()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            DesignerMasterResponse response = new DesignerMasterResponse();

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    response.Code = 0;
                    response.Message = "Error: Unauthorized access.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string userValue = userCookie.Value;
                string companyValue = companyCookie.Value;

                if (userValue.Contains("="))
                    userValue = userValue.Substring(userValue.LastIndexOf('=') + 1);

                if (companyValue.Contains("="))
                    companyValue = companyValue.Substring(companyValue.LastIndexOf('=') + 1);

                long userAccountId;
                long companyId;

                if (!long.TryParse(userValue, out userAccountId) || userAccountId <= 0 ||
                    !long.TryParse(companyValue, out companyId) || companyId <= 0)
                {
                    response.Code = 0;
                    response.Message = "Error: Invalid session information.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string postQueue = HttpContext.Current.Request.Params["PostQueue"];

                if (string.IsNullOrWhiteSpace(postQueue))
                {
                    response.Code = 400;
                    response.Message = "Invalid queue data.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string[] queueItems = postQueue.Split('|');

                if (queueItems.Length != 2)
                {
                    response.Code = 400;
                    response.Message = "Invalid queue format.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string[] firstItem = queueItems[0].Split(',');
                string[] secondItem = queueItems[1].Split(',');

                int firstID, firstPosition, secondID, secondPosition;

                if (firstItem.Length != 2 ||
                    secondItem.Length != 2 ||
                    !int.TryParse(firstItem[0], out firstID) ||
                    !int.TryParse(firstItem[1], out firstPosition) ||
                    !int.TryParse(secondItem[0], out secondID) ||
                    !int.TryParse(secondItem[1], out secondPosition) ||
                    firstID <= 0 ||
                    secondID <= 0 ||
                    firstID == secondID ||
                    firstPosition < 0 ||
                    secondPosition < 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid queue values.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection conn = new SqlConnection(cs))
                {
                    conn.Open();

                    using (SqlTransaction transaction = conn.BeginTransaction(IsolationLevel.ReadCommitted))
                    {
                        try
                        {
                            object oldValue = null;

                            // Verify both records exist and belong to the company
                            using (SqlCommand cmdCheck = new SqlCommand(@"
                                SELECT COUNT(1)
                                FROM dbo.DesignerMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE CompanyId = @CompanyId
                                  AND DesignerID IN (@FirstID, @SecondID)",
                                conn, transaction))
                            {
                                cmdCheck.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmdCheck.Parameters.Add("@FirstID", SqlDbType.Int).Value = firstID;
                                cmdCheck.Parameters.Add("@SecondID", SqlDbType.Int).Value = secondID;

                                int count = Convert.ToInt32(cmdCheck.ExecuteScalar());

                                if (count != 2)
                                {
                                    transaction.Rollback();
                                    response.Code = 400;
                                    response.Message = "Designer record not found.";
                                    Context.Response.Write(js.Serialize(response));
                                    return;
                                }
                            }

                            // Verify current positions to prevent stale queue updates
                            using (SqlCommand cmdCheckPosition = new SqlCommand(@"
                                SELECT DesignerID, Position
                                FROM dbo.DesignerMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE CompanyId = @CompanyId
                                  AND DesignerID IN (@FirstID, @SecondID)",
                                conn, transaction))
                            {
                                cmdCheckPosition.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmdCheckPosition.Parameters.Add("@FirstID", SqlDbType.Int).Value = firstID;
                                cmdCheckPosition.Parameters.Add("@SecondID", SqlDbType.Int).Value = secondID;

                                Dictionary<int, int> currentPositions = new Dictionary<int, int>();

                                using (SqlDataReader rdr = cmdCheckPosition.ExecuteReader())
                                {
                                    while (rdr.Read())
                                    {
                                        int id = Convert.ToInt32(rdr["DesignerID"]);
                                        int position = Convert.ToInt32(rdr["Position"]);
                                        currentPositions[id] = position;

                                        if ((id == firstID && position != firstPosition) ||
                                            (id == secondID && position != secondPosition))
                                        {
                                            rdr.Close();
                                            transaction.Rollback();
                                            response.Code = 400;
                                            response.Message = "Queue data is outdated. Please refresh and try again.";
                                            Context.Response.Write(js.Serialize(response));
                                            return;
                                        }
                                    }
                                }

                                oldValue = new
                                {
                                    Item1 = firstID,
                                    OldPosition1 = currentPositions.ContainsKey(firstID) ? currentPositions[firstID] : firstPosition,
                                    Item2 = secondID,
                                    OldPosition2 = currentPositions.ContainsKey(secondID) ? currentPositions[secondID] : secondPosition
                                };
                            }

                            // Swap positions
                            using (SqlCommand cmdUpdate = new SqlCommand(@"
                                UPDATE dbo.DesignerMaster
                                SET Position = CASE
                                    WHEN DesignerID = @FirstID THEN @SecondPosition
                                    WHEN DesignerID = @SecondID THEN @FirstPosition
                                END
                                WHERE CompanyId = @CompanyId
                                  AND DesignerID IN (@FirstID, @SecondID)",
                                conn, transaction))
                            {
                                cmdUpdate.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmdUpdate.Parameters.Add("@FirstID", SqlDbType.Int).Value = firstID;
                                cmdUpdate.Parameters.Add("@SecondID", SqlDbType.Int).Value = secondID;
                                cmdUpdate.Parameters.Add("@FirstPosition", SqlDbType.Int).Value = firstPosition;
                                cmdUpdate.Parameters.Add("@SecondPosition", SqlDbType.Int).Value = secondPosition;

                                int rowsAffected = cmdUpdate.ExecuteNonQuery();

                                if (rowsAffected != 2)
                                {
                                    transaction.Rollback();
                                    response.Code = 0;
                                    response.Message = "Unable to update queue.";
                                    Context.Response.Write(js.Serialize(response));
                                    return;
                                }
                            }

                            AuditLogHelper.LogTransactional(
                                conn: conn,
                                tran: transaction,
                                module: "Designer",
                                action: "UPDATE",
                                tableName: "DesignerMaster",
                                recordId: $"{firstID},{secondID}",
                                description: $"Updated Designer Queue positions: ID {firstID} to {secondPosition}, ID {secondID} to {firstPosition}",
                                oldValue: oldValue,
                                newValue: new { Item1 = firstID, NewPosition1 = secondPosition, Item2 = secondID, NewPosition2 = firstPosition },
                                customUserId: userAccountId
                            );

                            transaction.Commit();

                            response.Code = 1;
                            response.Message = "Success";
                        }
                        catch
                        {
                            try { transaction.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Designer", "UpdateTbl_DesignerQueue", ex, $"PostQueue: {HttpContext.Current.Request.Params["PostQueue"]}");
                response.Code = 500;
                response.Message = "Unable to update Designer queue.";
            }

            Context.Response.Write(js.Serialize(response));
        }
