        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertSketcherMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(
                DateTime.UtcNow, India_Standard_Time);

            CommanResponse comman = new CommanResponse();
            SketcherMaster ilist = new SketcherMaster();

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Session cookies missing.";
                    WriteJsonResponse(comman);
                    return;
                }

                string userCookieValue = userCookie.Value;
                string companyCookieValue = companyCookie.Value;

                if (userCookieValue.Contains("="))
                    userCookieValue = userCookieValue.Substring(
                        userCookieValue.LastIndexOf('=') + 1);

                if (companyCookieValue.Contains("="))
                    companyCookieValue = companyCookieValue.Substring(
                        companyCookieValue.LastIndexOf('=') + 1);

                if (!long.TryParse(userCookieValue, out long userId) || userId <= 0 ||
                    !long.TryParse(companyCookieValue, out long companyId) || companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Invalid session information.";
                    WriteJsonResponse(comman);
                    return;
                }

                var request = HttpContext.Current.Request;

                string sketcher = (request.Params["Sketcher"] ?? "")
                    .Trim()
                    .ToUpperInvariant();

                if (string.IsNullOrWhiteSpace(sketcher))
                {
                    comman.Code = 400;
                    comman.Message = "Please Mention Sketcher.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (sketcher.Length > 100)
                {
                    comman.Code = 400;
                    comman.Message = "Sketcher cannot exceed 100 characters.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (!int.TryParse(request.Params["IsActive"], out int isActive) ||
                    (isActive != 0 && isActive != 1))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid IsActive value.";
                    WriteJsonResponse(comman);
                    return;
                }

                ilist.Sketcher = sketcher;
                ilist.IsActive = isActive;
                ilist.UserAccountId = checked((int)userId);
                ilist.CompanyId = checked((int)companyId);

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // Duplicate Check - Company Wise
                            string duplicateSql = @"
                        SELECT TOP 1 SketcherID
                        FROM dbo.SketcherMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE UPPER(LTRIM(RTRIM(Sketcher))) = @Sketcher
                          AND CompanyId = @CompanyId";

                            using (SqlCommand cmdDup = new SqlCommand(
                                duplicateSql, con, transaction))
                            {
                                cmdDup.Parameters.Add("@Sketcher", SqlDbType.NVarChar, 100)
                                    .Value = ilist.Sketcher;

                                cmdDup.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                object duplicateId = cmdDup.ExecuteScalar();

                                if (duplicateId != null && duplicateId != DBNull.Value)
                                {
                                    transaction.Rollback();

                                    AuditLogHelper.LogDuplicateError(
                                        "Sketcher",
                                        "SketcherMaster",
                                        "Sketcher",
                                        ilist.Sketcher,
                                        "Sketcher is already exists.",
                                        ilist
                                    );

                                    comman.Code = 409;
                                    comman.Message = "Sketcher already exists. Please enter a different Sketcher.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // Company Wise Position
                            int position;

                            using (SqlCommand cmdPosition = new SqlCommand(@"
                        SELECT ISNULL(MAX(Position), 0) + 1
                        FROM dbo.SketcherMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmdPosition.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                position = Convert.ToInt32(cmdPosition.ExecuteScalar());
                            }

                            // Insert Record
                            string insertSql = @"
                        INSERT INTO dbo.SketcherMaster
                        (
                            DateAndTime,
                            Sketcher,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        )
                        OUTPUT INSERTED.SketcherID
                        VALUES
                        (
                            @DateAndTime,
                            @Sketcher,
                            @IsActive,
                            @Position,
                            @CompanyId,
                            @UserAccountId
                        )";

                            int newId;

                            using (SqlCommand cmd = new SqlCommand(
                                insertSql, con, transaction))
                            {
                                cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime)
                                    .Value = dateTime_Indian;

                                cmd.Parameters.Add("@Sketcher", SqlDbType.NVarChar, 100)
                                    .Value = ilist.Sketcher;

                                cmd.Parameters.Add("@IsActive", SqlDbType.TinyInt)
                                    .Value = (byte)ilist.IsActive;

                                cmd.Parameters.Add("@Position", SqlDbType.Int)
                                    .Value = position;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                cmd.Parameters.Add("@UserAccountId", SqlDbType.BigInt)
                                    .Value = userId;

                                newId = Convert.ToInt32(cmd.ExecuteScalar());
                            }

                            if (newId <= 0)
                            {
                                transaction.Rollback();

                                comman.Code = 500;
                                comman.Message = "Unable to save Sketcher.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            ilist.SketcherID = newId;
                            ilist.DateandTime = dateTime_Indian;
                            ilist.Position = position;

                            // Transactional Audit Log
                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: transaction,
                                module: "Sketcher",
                                action: "CREATE",
                                tableName: "SketcherMaster",
                                recordId: newId.ToString(),
                                description: $"Created Sketcher '{ilist.Sketcher}' (ID: {newId})",
                                oldValue: null,
                                newValue: ilist,
                                customUserId: userId
                            );

                            transaction.Commit();

                            comman.Code = 201;
                            comman.Message = "Sketcher has been saved successfully.";
                        }
                        catch
                        {
                            try
                            {
                                transaction.Rollback();
                            }
                            catch { }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Sketcher",
                    "insertSketcherMaster",
                    ex,
                    $"Sketcher: {ilist.Sketcher}"
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    AuditLogHelper.LogDuplicateError(
                        "Sketcher",
                        "SketcherMaster",
                        "Sketcher",
                        ilist.Sketcher,
                        "Cannot insert duplicate values.",
                        ilist
                    );

                    comman.Code = 409;
                    comman.Message = "Sketcher already exists.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem has occurred while saving Sketcher.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Sketcher",
                    "insertSketcherMaster",
                    ex,
                    $"Sketcher: {ilist.Sketcher}"
                );

                comman.Code = 500;
                comman.Message = "Problem has occurred while saving Sketcher.";
            }

            WriteJsonResponse(comman);
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getSketcherMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<SketcherMaster> listUser = new List<SketcherMaster>();
            SketcherMasterResponse response = new SketcherMasterResponse();

            try
            {
                string searchSketcher = HttpContext.Current.Request.Params["searchSketcher"] ?? "";

                int startFrom;
                if (!int.TryParse(HttpContext.Current.Request.Params["startFrom"], out startFrom) || startFrom < 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid pagination value.";
                    response.listSketcherMaster = listUser;
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                searchSketcher = searchSketcher.Trim();
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    string sql = @"
                        SELECT *
                        FROM dbo.SketcherMaster
                        WHERE
                        (
                            @Search = ''
                            OR Sketcher LIKE @SearchPattern
                        )
                        ORDER BY Position DESC
                        OFFSET @StartFrom ROWS
                        FETCH NEXT 10 ROWS ONLY";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@Search", SqlDbType.NVarChar, 200).Value = searchSketcher;
                        cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar, 402).Value = "%" + searchSketcher + "%";
                        cmd.Parameters.Add("@StartFrom", SqlDbType.Int).Value = startFrom;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                SketcherMaster condition = new SketcherMaster();
                                condition.SketcherID = Convert.ToInt32(rdr["SketcherID"]);
                                condition.IsActive = Convert.ToInt32(rdr["IsActive"]);
                                condition.Position = Convert.ToInt32(rdr["Position"]);
                                condition.DateandTime = rdr["DateandTime"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(rdr["DateandTime"]);
                                condition.DateandTimes = rdr["DateandTime"] == DBNull.Value ? "" : Convert.ToDateTime(rdr["DateandTime"]).ToString("dd-MM-yyyy");
                                condition.Sketcher = rdr["Sketcher"] == DBNull.Value ? "" : rdr["Sketcher"].ToString().ToUpper();
                                listUser.Add(condition);
                            }
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listSketcherMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine("getSketcherMaster Error: " + ex);
                response.Code = 500;
                response.Message = "Unable to retrieve Sketcher Master data.";
                response.listSketcherMaster = new List<SketcherMaster>();
            }

            Context.Response.Write(js.Serialize(response));
        }

