                                            UserAccountId = rdr["UserAccountId"] == DBNull.Value
                                                ? 0L
                                                : Convert.ToInt64(rdr["UserAccountId"])
                                        };
                                    }
                                }
                            }

                            if (oldValue == null)
                            {
                                transaction.Rollback();

                                comman.Code = 404;
                                comman.Message = "Sketcher record not found.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // Duplicate Check - Company Wise
                            using (SqlCommand cmdDup = new SqlCommand(@"
                        SELECT TOP 1 SketcherID
                        FROM dbo.SketcherMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE UPPER(LTRIM(RTRIM(Sketcher))) = @Sketcher
                          AND CompanyId = @CompanyId
                          AND SketcherID <> @SketcherID",
                                con, transaction))
                            {
                                cmdDup.Parameters.Add("@Sketcher", SqlDbType.NVarChar, 100)
                                    .Value = ilist.Sketcher;

                                cmdDup.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                cmdDup.Parameters.Add("@SketcherID", SqlDbType.Int)
                                    .Value = sketcherId;

                                object duplicateId = cmdDup.ExecuteScalar();

                                if (duplicateId != null && duplicateId != DBNull.Value)
                                {
                                    transaction.Rollback();

                                    AuditLogHelper.LogDuplicateError(
                                        "Sketcher",
                                        "SketcherMaster",
                                        "Sketcher",
                                        ilist.Sketcher,
                                        "Sketcher already exists.",
                                        ilist
                                    );

                                    comman.Code = 409;
                                    comman.Message =
                                        "Sketcher already exists. Please enter a different name.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // Dependency Check - Always Check Before Update
                            // If dependency exists, neither Sketcher nor IsActive will update.

                            string dependencySql = @"
                        SELECT TOP 1
                            DesignEntryFormID,
                            DesignNo
                        FROM dbo.DesignEntryFormMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE SketcherID = @SketcherID
                        ORDER BY DesignEntryFormID";

                            using (SqlCommand cmdDependency = new SqlCommand(
                                dependencySql, con, transaction))
                            {
                                cmdDependency.Parameters.Add("@SketcherID", SqlDbType.Int)
                                    .Value = sketcherId;

                                using (SqlDataReader reader = cmdDependency.ExecuteReader())
                                {
                                    if (reader.Read())
                                    {
                                        string designNo = reader["DesignNo"] == DBNull.Value
                                            ? "N/A"
                                            : reader["DesignNo"].ToString();

                                        int designEntryFormID = Convert.ToInt32(
                                            reader["DesignEntryFormID"]);

                                        reader.Close();

                                        transaction.Rollback();

                                        comman.Code = 409;
                                        comman.Message =
                                            "Cannot update this Sketcher because it is already used in Design Entry." +
                                            Environment.NewLine +
                                            "Design No: " + designNo +
                                            Environment.NewLine +
                                            "Design Entry ID: " + designEntryFormID;

                                        WriteJsonResponse(comman);
                                        return;
                                    }
                                }
                            }

                            // Update Record - Only When No Duplicate And No Dependency
                            int rowsAffected = 0;

                            using (SqlCommand cmdUpdate = new SqlCommand(@"
                        UPDATE dbo.SketcherMaster
                        SET
                            Sketcher = @Sketcher,
                            IsActive = @IsActive,
                            UserAccountId = @UserAccountId
                        WHERE SketcherID = @SketcherID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmdUpdate.Parameters.Add("@Sketcher", SqlDbType.NVarChar, 100)
                                    .Value = ilist.Sketcher;

                                cmdUpdate.Parameters.Add("@IsActive", SqlDbType.TinyInt)
                                    .Value = (byte)ilist.IsActive;

                                cmdUpdate.Parameters.Add("@UserAccountId", SqlDbType.BigInt)
                                    .Value = userId;

                                cmdUpdate.Parameters.Add("@SketcherID", SqlDbType.Int)
                                    .Value = sketcherId;

                                cmdUpdate.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                rowsAffected = cmdUpdate.ExecuteNonQuery();
                            }

                            if (rowsAffected != 1)
                            {
                                transaction.Rollback();

                                comman.Code = 410;
                                comman.Message = "Sketcher record could not be updated.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // Transactional Audit Log
                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: transaction,
                                module: "Sketcher",
                                action: "UPDATE",
                                tableName: "SketcherMaster",
                                recordId: sketcherId.ToString(),
                                description: $"Updated Sketcher #{sketcherId} '{ilist.Sketcher}'",
                                oldValue: oldValue,
                                newValue: ilist,
                                customUserId: userId
                            );

                            transaction.Commit();

                            comman.Code = 201;
                            comman.Message = "Sketcher has been updated successfully.";
                        }
                        catch
                        {
                            try { transaction.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Sketcher",
                    "EditSketcherMaster",
                    ex,
                    $"ID: {ilist.SketcherID}, Sketcher: {ilist.Sketcher}"
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    AuditLogHelper.LogDuplicateError(
                        "Sketcher",
                        "SketcherMaster",
                        "Sketcher",
                        ilist.Sketcher,
                        "Cannot insert duplicate values.",
                        ilist
                    );

                    comman.Code = 409;
                    comman.Message = "Sketcher already exists.";
                }
                else if (ex.Number == 547)
                {
                    comman.Code = 409;
                    comman.Message =
                        "Cannot update this Sketcher because it is used in another record.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message =
                        "Problem has occurred while updating Sketcher.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Sketcher",
                    "EditSketcherMaster",
                    ex,
                    $"ID: {ilist.SketcherID}, Sketcher: {ilist.Sketcher}"
                );

                comman.Code = 500;
                comman.Message =
                    "Problem has occurred while updating Sketcher.";
            }

            WriteJsonResponse(comman);
        }



        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteSketcherMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse comman = new CommanResponse();

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    comman.Code = 401;
                    comman.Message = "Unauthorized access. Session cookies missing.";
                    WriteJsonResponse(comman);
                    return;
                }

                string userValue = userCookie.Value;
                string companyValue = companyCookie.Value;

                if (userValue.Contains("="))
                    userValue = userValue.Substring(userValue.LastIndexOf('=') + 1);

                if (companyValue.Contains("="))
                    companyValue = companyValue.Substring(companyValue.LastIndexOf('=') + 1);

                if (!long.TryParse(userValue, out long userAccountId) || userAccountId <= 0 ||
                    !long.TryParse(companyValue, out long companyId) || companyId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Invalid session information.";
                    WriteJsonResponse(comman);
                    return;
                }

                if (!int.TryParse(
                    HttpContext.Current.Request.Params["SketcherID"],
                    out int sketcherId) || sketcherId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Sketcher ID.";
                    WriteJsonResponse(comman);
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            object oldValue = null;

                            // Fetch Existing Record
                            using (SqlCommand cmdFetch = new SqlCommand(@"
                        SELECT
                            SketcherID,
                            DateandTime,
                            Sketcher,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        FROM dbo.SketcherMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE SketcherID = @SketcherID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmdFetch.Parameters.Add("@SketcherID", SqlDbType.Int)
                                    .Value = sketcherId;

                                cmdFetch.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                using (SqlDataReader rdr = cmdFetch.ExecuteReader())
                                {
                                    if (rdr.Read())
                                    {
                                        oldValue = new
                                        {
                                            SketcherID = Convert.ToInt32(rdr["SketcherID"]),
                                            DateandTime = rdr["DateandTime"] == DBNull.Value
                                                ? DateTime.MinValue
                                                : Convert.ToDateTime(rdr["DateandTime"]),
                                            Sketcher = rdr["Sketcher"] == DBNull.Value
                                                ? ""
                                                : rdr["Sketcher"].ToString(),
                                            IsActive = rdr["IsActive"] == DBNull.Value
                                                ? 0
                                                : Convert.ToInt32(rdr["IsActive"]),
                                            Position = rdr["Position"] == DBNull.Value
                                                ? 0
                                                : Convert.ToInt32(rdr["Position"]),
                                            CompanyId = rdr["CompanyId"] == DBNull.Value
                                                ? 0L
                                                : Convert.ToInt64(rdr["CompanyId"]),
                                            UserAccountId = rdr["UserAccountId"] == DBNull.Value
                                                ? 0L
                                                : Convert.ToInt64(rdr["UserAccountId"])
                                        };
                                    }
                                }
                            }

                            if (oldValue == null)
                            {
                                transaction.Rollback();

                                comman.Code = 404;
                                comman.Message = "Sketcher record not found.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // Actual Dependency Check - DesignEntryFormMaster
                            string dependencySql = @"
                        SELECT TOP 1
                            DesignEntryFormID,
                            DesignNo
                        FROM dbo.DesignEntryFormMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE SketcherID = @SketcherID
                        ORDER BY DesignEntryFormID";

                            using (SqlCommand cmdCheck = new SqlCommand(
                                dependencySql, con, transaction))
                            {
                                cmdCheck.Parameters.Add("@SketcherID", SqlDbType.Int)
                                    .Value = sketcherId;

                                using (SqlDataReader reader = cmdCheck.ExecuteReader())
                                {
                                    if (reader.Read())
                                    {
                                        string designNo = reader["DesignNo"] == DBNull.Value
                                            ? "N/A"
                                            : reader["DesignNo"].ToString();

                                        int designEntryFormID = Convert.ToInt32(
                                            reader["DesignEntryFormID"]);

                                        reader.Close();

                                        transaction.Rollback();

                                        comman.Code = 409;
                                        comman.Message =
                                            "Cannot delete this Sketcher because it is already used in Design Entry.";
                                        WriteJsonResponse(comman);
                                        return;
                                    }
                                }
                            }

                            // Delete Record
                            int rowsAffected = 0;

                            using (SqlCommand cmd = new SqlCommand(@"
                        DELETE FROM dbo.SketcherMaster
                        WHERE SketcherID = @SketcherID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@SketcherID", SqlDbType.Int)
                                    .Value = sketcherId;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                rowsAffected = cmd.ExecuteNonQuery();
                            }

                            if (rowsAffected != 1)
                            {
                                transaction.Rollback();

                                comman.Code = 410;
                                comman.Message = "Failed to delete record.";

                                WriteJsonResponse(comman);
                                return;
                            }

                            // Transactional Audit Log
                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: transaction,
                                module: "Sketcher",
                                action: "DELETE",
                                tableName: "SketcherMaster",
                                recordId: sketcherId.ToString(),
                                description: "Deleted Sketcher ID: " + sketcherId,
                                oldValue: oldValue,
                                newValue: null,
                                customUserId: userAccountId
                            );

                            transaction.Commit();

                            comman.Code = 200;
                            comman.Message = "Record Deleted Successfully.";
                        }
                        catch
                        {
                            try { transaction.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Sketcher",
                    "DeleteSketcherMaster",
                    ex,
                    $"SketcherID: {HttpContext.Current.Request.Params["SketcherID"]}"
                );

                if (ex.Number == 547)
                {
                    comman.Code = 409;
                    comman.Message =
                        "Cannot delete this Sketcher because it is used in another record.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message =
                        "Problem occurred while deleting Sketcher.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Sketcher",
                    "DeleteSketcherMaster",
                    ex,
                    $"SketcherID: {HttpContext.Current.Request.Params["SketcherID"]}"
                );

                comman.Code = 500;
                comman.Message = "Unable to delete Sketcher.";
            }

            WriteJsonResponse(comman);
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_SketcherQueue()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            SketcherMasterResponse comman = new SketcherMasterResponse();

            try
            {
                HttpCookie userCookie = Context.Request.Cookies["UserIDs"];
                HttpCookie companyCookie = Context.Request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Unauthorized access.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string userValue = userCookie.Value;
                string companyValue = companyCookie.Value;

                if (userValue.Contains("="))
                    userValue = userValue.Substring(userValue.LastIndexOf('=') + 1);

                if (companyValue.Contains("="))
                    companyValue = companyValue.Substring(companyValue.LastIndexOf('=') + 1);

                long userAccountId;
                long companyId;

                if (!long.TryParse(userValue, out userAccountId) || userAccountId <= 0 ||
                    !long.TryParse(companyValue, out companyId) || companyId <= 0)
                {
                    comman.Code = 0;
                    comman.Message = "Error: Invalid session information.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string postQueue = HttpContext.Current.Request.Params["PostQueue"] ?? "";

                if (string.IsNullOrWhiteSpace(postQueue))
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue data.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string[] queueItems = postQueue.Split('|');

                if (queueItems.Length != 2)
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue data.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string[] firstItem = queueItems[0].Split(',');
                string[] secondItem = queueItems[1].Split(',');

                int firstId, firstPosition, secondId, secondPosition;

                if (firstItem.Length != 2 ||
                    secondItem.Length != 2 ||
                    !int.TryParse(firstItem[0], out firstId) ||
                    !int.TryParse(firstItem[1], out firstPosition) ||
                    !int.TryParse(secondItem[0], out secondId) ||
                    !int.TryParse(secondItem[1], out secondPosition) ||
                    firstId <= 0 || secondId <= 0 ||
                    firstId == secondId ||
                    firstPosition < 0 || secondPosition < 0)
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue values.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection conn = new SqlConnection(cs))
                {
                    conn.Open();

                    using (SqlTransaction transaction = conn.BeginTransaction(IsolationLevel.ReadCommitted))
                    {
                        try
                        {
                            object oldValue = null;

                            using (SqlCommand cmdCheck = new SqlCommand(@"
                                SELECT SketcherID, Position
                                FROM dbo.SketcherMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE CompanyId = @CompanyId
                                  AND SketcherID IN (@FirstID, @SecondID)", conn, transaction))
                            {
                                cmdCheck.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmdCheck.Parameters.Add("@FirstID", SqlDbType.Int).Value = firstId;
                                cmdCheck.Parameters.Add("@SecondID", SqlDbType.Int).Value = secondId;

                                Dictionary<int, int> currentPositions = new Dictionary<int, int>();

                                using (SqlDataReader rdr = cmdCheck.ExecuteReader())
                                {
                                    while (rdr.Read())
                                    {
                                        int id = Convert.ToInt32(rdr["SketcherID"]);
                                        int position = Convert.ToInt32(rdr["Position"]);
                                        currentPositions[id] = position;

                                        if ((id == firstId && position != firstPosition) ||
                                            (id == secondId && position != secondPosition))
                                        {
                                            rdr.Close();
                                            transaction.Rollback();
                                            comman.Code = 0;
                                            comman.Message = "Queue data is outdated. Please refresh and try again.";
                                            Context.Response.Write(js.Serialize(comman));
                                            return;
                                        }
                                    }
                                }

                                if (currentPositions.Count != 2)
                                {
                                    transaction.Rollback();
                                    comman.Code = 0;
                                    comman.Message = "Sketcher record not found.";
                                    Context.Response.Write(js.Serialize(comman));
                                    return;
                                }

                                oldValue = new
                                {
                                    Item1 = firstId,
                                    OldPosition1 = currentPositions.ContainsKey(firstId) ? currentPositions[firstId] : firstPosition,
                                    Item2 = secondId,
                                    OldPosition2 = currentPositions.ContainsKey(secondId) ? currentPositions[secondId] : secondPosition
                                };
                            }

                            string sql = @"
                                UPDATE dbo.SketcherMaster
                                SET Position = CASE
                                    WHEN SketcherID = @FirstID THEN @SecondPosition
                                    WHEN SketcherID = @SecondID THEN @FirstPosition
                                END
                                WHERE CompanyId = @CompanyId
                                  AND SketcherID IN (@FirstID, @SecondID)";

                            int rowsAffected = 0;
                            using (SqlCommand cmd = new SqlCommand(sql, conn, transaction))
                            {
                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmd.Parameters.Add("@FirstID", SqlDbType.Int).Value = firstId;
                                cmd.Parameters.Add("@SecondID", SqlDbType.Int).Value = secondId;
                                cmd.Parameters.Add("@FirstPosition", SqlDbType.Int).Value = firstPosition;
                                cmd.Parameters.Add("@SecondPosition", SqlDbType.Int).Value = secondPosition;

                                rowsAffected = cmd.ExecuteNonQuery();
                            }

                            if (rowsAffected != 2)
                            {
                                transaction.Rollback();
                                comman.Code = 0;
                                comman.Message = "Unable to update queue.";
                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }

                            AuditLogHelper.LogTransactional(
                                conn: conn,
                                tran: transaction,
                                module: "Sketcher",
                                action: "UPDATE",
                                tableName: "SketcherMaster",
                                recordId: $"{firstId},{secondId}",
                                description: $"Updated Sketcher Queue positions: ID {firstId} to {secondPosition}, ID {secondId} to {firstPosition}",
                                oldValue: oldValue,
                                newValue: new { Item1 = firstId, NewPosition1 = secondPosition, Item2 = secondId, NewPosition2 = firstPosition },
                                customUserId: userAccountId
                            );

                            transaction.Commit();

                            comman.Code = 1;
                            comman.Message = "Success";
                        }
                        catch
                        {
                            try { transaction.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Sketcher", "UpdateTbl_SketcherQueue", ex, $"PostQueue: {HttpContext.Current.Request.Params["PostQueue"]}");
                comman.Code = 0;
                comman.Message = "Unable to update Sketcher queue.";
            }

            Context.Response.Write(js.Serialize(comman));
        }
