        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getWarpQualityMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<WarpQualityMaster> listUser = new List<WarpQualityMaster>();
            WarpQualityMasterResponse response = new WarpQualityMasterResponse();

            try
            {
                string searchWarpQuality =
                    HttpContext.Current.Request.Params["searchWarpQuality"] ?? "";

                int startFrom;

                if (!int.TryParse(
                    HttpContext.Current.Request.Params["startFrom"],
                    out startFrom) || startFrom < 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid pagination value.";
                    response.listWarpQualityMaster = listUser;

                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                searchWarpQuality = searchWarpQuality.Trim();

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    string sql = @"
                SELECT *
                FROM dbo.WarpQualityMaster
                WHERE
                (
                    @Search = ''
                    OR WarpQuality LIKE @SearchPattern
                )
                ORDER BY Position DESC
                OFFSET @StartFrom ROWS
                FETCH NEXT 10 ROWS ONLY";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@Search", SqlDbType.NVarChar, 200)
                            .Value = searchWarpQuality;

                        cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar, 402)
                            .Value = "%" + searchWarpQuality + "%";

                        cmd.Parameters.Add("@StartFrom", SqlDbType.Int)
                            .Value = startFrom;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                WarpQualityMaster condition = new WarpQualityMaster();

                                condition.WarpQualityID =
                                    Convert.ToInt32(rdr["WarpQualityID"]);

                                condition.IsActive =
                                    Convert.ToInt32(rdr["IsActive"]);

                                condition.Position =
                                    Convert.ToInt32(rdr["Position"]);

                                condition.DateandTime =
                                    Convert.ToDateTime(rdr["DateandTime"]);

                                condition.DateandTimes =
                                    condition.DateandTime.ToString("dd-MM-yyyy");

                                condition.WarpQuality =
                                    rdr["WarpQuality"].ToString().ToUpper();

                                listUser.Add(condition);
                            }
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listWarpQualityMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getWarpQualityMaster Error: " + ex);

                response.Code = 500;
                response.Message = "Unable to retrieve Warp Quality data.";
                response.listWarpQualityMaster = new List<WarpQualityMaster>();
            }

            Context.Response.Write(js.Serialize(response));
        }
