        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditWarpQualityMaster()
        {
            CommanResponse comman = new CommanResponse();

            int warpQualityId = 0;
            int isActive = 0;
            int userAccountId = 0;
            int companyId = 0;

            string warpQuality = "";

            try
            {
                var request = HttpContext.Current.Request;

                warpQuality = (request.Params["WarpQuality"] ?? "").Trim().ToUpper();

                // Validate input
                if (!int.TryParse(request.Params["WarpQualityID"], out warpQualityId) ||
                    warpQualityId <= 0 ||
                    string.IsNullOrWhiteSpace(warpQuality) ||
                    warpQuality.Length > 100 ||
                    !int.TryParse(request.Params["IsActive"], out isActive) ||
                    (isActive != 0 && isActive != 1))
                {
                    comman.Code = 400;
                    comman.Message = "Please enter valid Warp Quality details.";
                    WriteJsonResponse(comman);
                    return;
                }

                // Cookie validation - Existing project cookie format
                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null ||
                    string.IsNullOrEmpty(userCookie.Value) ||
                    string.IsNullOrEmpty(companyCookie.Value))
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user or company session.";
                    WriteJsonResponse(comman);
                    return;
                }

                string[] userParts = userCookie.Value.Split('=');
                string[] companyParts = companyCookie.Value.Split('=');

                if (userParts.Length < 2 ||
                    companyParts.Length < 2 ||
                    !int.TryParse(userParts[1], out userAccountId) ||
                    !int.TryParse(companyParts[1], out companyId))
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user or company session.";
                    WriteJsonResponse(comman);
                    return;
                }

                WarpQualityMaster ilist = new WarpQualityMaster
                {
                    WarpQualityID = warpQualityId,
                    WarpQuality = warpQuality,
                    IsActive = isActive,
                    UserAccountId = userAccountId,
                    CompanyId = companyId
                };

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // 1. Check record exists in current company
                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.WarpQualityMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE WarpQualityID = @WarpQualityID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@WarpQualityID", SqlDbType.Int)
                                    .Value = warpQualityId;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                if (Convert.ToInt32(cmd.ExecuteScalar()) == 0)
                                {
                                    transaction.Rollback();

                                    comman.Code = 404;
                                    comman.Message = "Warp Quality record not found.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 2. Dependency check - DesignEntryFormMaster
                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignEntryFormMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE WarpQualityID = @WarpQualityID",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@WarpQualityID", SqlDbType.Int)
                                    .Value = warpQualityId;

                                int dependencyCount =
                                    Convert.ToInt32(cmd.ExecuteScalar());

                                if (dependencyCount > 0)
                                {
                                    transaction.Rollback();

                                    comman.Code = 409;
                                    comman.Message =
                                        "This Warp Quality cannot be edited because it is already associated with existing Design Entry records.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 3. Duplicate check - Same company, excluding current record
                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.WarpQualityMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND WarpQualityID <> @WarpQualityID
                          AND UPPER(LTRIM(RTRIM(WarpQuality))) = @WarpQuality",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                cmd.Parameters.Add("@WarpQualityID", SqlDbType.Int)
                                    .Value = warpQualityId;

                                cmd.Parameters.Add("@WarpQuality", SqlDbType.NVarChar, 100)
                                    .Value = warpQuality;

                                if (Convert.ToInt32(cmd.ExecuteScalar()) > 0)
                                {
                                    transaction.Rollback();

                                    AuditLogHelper.LogDuplicateError(
                                        module: "Warp Quality",
                                        tableName: "WarpQualityMaster",
                                        recordId: warpQualityId.ToString(),
                                        description: $"Duplicate Warp Quality: {ilist.WarpQuality}",
                                        errorMessage: "This Warp Quality already exists.",
                                        requestData: ilist
                                    );

                                    comman.Code = 409;
                                    comman.Message = "This Warp Quality already exists.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 4. Get old value for audit
                            object oldValue = AuditLogHelper.FetchOldValue(
                                "WarpQualityMaster",
                                warpQualityId.ToString(),
                                con
                            );

                            // 5. Update record - Only if all checks pass
                            int rowsAffected;

                            using (SqlCommand cmd = new SqlCommand(@"
                        UPDATE dbo.WarpQualityMaster
                        SET
                            WarpQuality = @WarpQuality,
                            IsActive = @IsActive,
                            UserAccountId = @UserAccountId
                        WHERE WarpQualityID = @WarpQualityID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@WarpQuality", SqlDbType.NVarChar, 100)
                                    .Value = warpQuality;

                                cmd.Parameters.Add("@IsActive", SqlDbType.TinyInt)
                                    .Value = isActive;

                                cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                    .Value = userAccountId;

                                cmd.Parameters.Add("@WarpQualityID", SqlDbType.Int)
                                    .Value = warpQualityId;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                rowsAffected = cmd.ExecuteNonQuery();
                            }

                            if (rowsAffected > 0)
                            {
                                // 6. Audit log
                                AuditLogHelper.LogTransactional(
                                    con,
                                    transaction,
                                    module: "Warp Quality",
                                    action: "UPDATE",
                                    tableName: "WarpQualityMaster",
                                    description: $"Updated Warp Quality #{warpQualityId} '{warpQuality}'",
                                    oldValue: oldValue,
                                    newValue: ilist,
                                    customUserId: userAccountId
                                );

                                transaction.Commit();

                                comman.Code = 201;
                                comman.Message =
                                    "Warp Quality has been updated successfully.";
                            }
                            else
                            {
                                transaction.Rollback();

                                comman.Code = 410;
                                comman.Message =
                                    "Warp Quality record was not updated.";
                            }
                        }
                        catch
                        {
                            if (transaction.Connection != null)
                            {
                                try
                                {
                                    transaction.Rollback();
                                }
                                catch
                                {
                                    // Transaction may already be completed.
                                }
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Warp Quality",
                    "EditWarpQualityMaster",
                    ex,
                    "WarpQuality: " + warpQuality
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 409;
                    comman.Message = "This Warp Quality already exists.";
                }
                else if (ex.Number == 547)
                {
                    comman.Code = 409;
                    comman.Message =
                        "This Warp Quality cannot be edited because it is linked with other records.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message =
                        "Problem occurred while updating Warp Quality.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Warp Quality",
                    "EditWarpQualityMaster",
                    ex,
                    "Unable to update Warp Quality."
                );

                comman.Code = 500;
                comman.Message = "Unable to update Warp Quality.";
            }

            WriteJsonResponse(comman);
        }



