        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertTypeMaster()
        {
            CommanResponse comman = new CommanResponse();

            TypeMaster ilist = new TypeMaster();

            int isActive = 0;
            int unitId = 0;
            int userAccountId = 0;
            int companyId = 0;

            try
            {
                var request = HttpContext.Current.Request;

                ilist.Type = (request.Params["Type"] ?? "").Trim().ToUpper();

                string unitValue = request.Params["UnitId"];

                // 1. Validate input
                if (string.IsNullOrWhiteSpace(ilist.Type) ||
                    ilist.Type.Length > 100 ||
                    !int.TryParse(request.Params["IsActive"], out isActive) ||
                    (isActive != 0 && isActive != 1))
                {
                    comman.Code = 400;
                    comman.Message = "Please enter valid Type details.";
                    WriteJsonResponse(comman);
                    return;
                }

                // UnitId is optional
                if (!string.IsNullOrWhiteSpace(unitValue) &&
                    !int.TryParse(unitValue, out unitId))
                {
                    comman.Code = 400;
                    comman.Message = "Please select a valid Unit.";
                    WriteJsonResponse(comman);
                    return;
                }

                // 2. Cookie validation - Existing project cookie format
                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null ||
                    string.IsNullOrEmpty(userCookie.Value) ||
                    string.IsNullOrEmpty(companyCookie.Value))
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user or company session.";
                    WriteJsonResponse(comman);
                    return;
                }

                string[] userParts = userCookie.Value.Split('=');
                string[] companyParts = companyCookie.Value.Split('=');

                if (userParts.Length < 2 ||
                    companyParts.Length < 2 ||
                    !int.TryParse(userParts[1], out userAccountId) ||
                    !int.TryParse(companyParts[1], out companyId))
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user or company session.";
                    WriteJsonResponse(comman);
                    return;
                }

                // 3. Prepare model
                ilist.IsActive = isActive;
                ilist.UnitId = unitId;
                ilist.UserAccountId = userAccountId;
                ilist.CompanyId = companyId;

                DateTime dateTimeIndian =
                    TimeZoneInfo.ConvertTimeFromUtc(
                        DateTime.UtcNow,
                        India_Standard_Time
                    );

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // 4. Duplicate check - Same company
                            using (SqlCommand cmdCheck = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.TypeMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND UPPER(LTRIM(RTRIM(Type))) = @Type",
                                con, transaction))
                            {
                                cmdCheck.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                cmdCheck.Parameters.Add("@Type", SqlDbType.NVarChar, 100)
                                    .Value = ilist.Type;

                                if (Convert.ToInt32(cmdCheck.ExecuteScalar()) > 0)
                                {
                                    transaction.Rollback();

                                    AuditLogHelper.LogDuplicateError(
                                        module: "Type Master",
                                        tableName: "TypeMaster",
                                        recordId: null,
                                        description: $"Duplicate Type: {ilist.Type}",
                                        errorMessage: "This Type already exists.",
                                        requestData: ilist
                                    );

                                    comman.Code = 409;
                                    comman.Message = "This Type already exists.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 5. Generate company-wise Position
                            int position;

                            using (SqlCommand positionCmd = new SqlCommand(@"
                        SELECT ISNULL(MAX(Position), 0) + 1
                        FROM dbo.TypeMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId",
                                con, transaction))
                            {
                                positionCmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                position = Convert.ToInt32(
                                    positionCmd.ExecuteScalar()
                                );
                            }

                            // 6. Insert record
                            int rowsAffected;

                            using (SqlCommand cmd = new SqlCommand(@"
                        INSERT INTO dbo.TypeMaster
                        (
                            DateAndTime,
                            Type,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId,
                            UnitId
                        )
                        VALUES
                        (
                            @DateAndTime,
                            @Type,
                            @IsActive,
                            @Position,
                            @CompanyId,
                            @UserAccountId,
                            @UnitId
                        )",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime)
                                    .Value = dateTimeIndian;

                                cmd.Parameters.Add("@Type", SqlDbType.NVarChar, 100)
                                    .Value = ilist.Type;

                                cmd.Parameters.Add("@IsActive", SqlDbType.TinyInt)
                                    .Value = isActive;

                                cmd.Parameters.Add("@Position", SqlDbType.Int)
                                    .Value = position;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                    .Value = userAccountId;

                                cmd.Parameters.Add("@UnitId", SqlDbType.Int)
                                    .Value = string.IsNullOrWhiteSpace(unitValue)
                                        ? (object)DBNull.Value
                                        : unitId;

                                rowsAffected = cmd.ExecuteNonQuery();
                            }

                            if (rowsAffected > 0)
                            {
                                // 7. Audit log
                                AuditLogHelper.LogTransactional(
                                    con,
                                    transaction,
                                    module: "Type Master",
                                    action: "CREATE",
                                    tableName: "TypeMaster",
                                    description: "Created Type '" + ilist.Type + "'",
                                    oldValue: null,
                                    newValue: ilist,
                                    customUserId: userAccountId
                                );

                                transaction.Commit();

                                comman.Code = 201;
                                comman.Message = "Type has been saved successfully.";
                            }
                            else
                            {
                                transaction.Rollback();

                                comman.Code = 410;
                                comman.Message = "Unable to save Type.";
                            }
                        }
                        catch
                        {
                            if (transaction.Connection != null)
                            {
                                try
                                {
                                    transaction.Rollback();
                                }
                                catch
                                {
                                    // Transaction may already be completed.
                                }
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Type Master",
                    "insertTypeMaster",
                    ex,
                    "Type: " + ilist.Type
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 409;
                    comman.Message = "This Type already exists.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem occurred while saving Type.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Type Master",
                    "insertTypeMaster",
                    ex,
                    "Unable to save Type."
                );

                comman.Code = 500;
                comman.Message = "Unable to save Type.";
            }

            WriteJsonResponse(comman);
        }

