        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getTypeMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<TypeMaster> listUser = new List<TypeMaster>();
            TypeMasterResponse response = new TypeMasterResponse();

            try
            {
                var request = HttpContext.Current.Request;

                string searchType = (request.Params["searchTyre"] ?? "").Trim();
                string startFromValue = request.Params["startFrom"];

                int startFrom;

                if (!int.TryParse(startFromValue, out startFrom) || startFrom < 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid pagination value.";
                    response.listTypeMaster = listUser;

                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    string sql = @"
                SELECT
                    TypeID,
                    IsActive,
                    Position,
                    DateandTime,
                    Type
                FROM dbo.TypeMaster
                WHERE (@Search = '' OR Type LIKE @SearchPattern)
                ORDER BY Position DESC
                OFFSET @StartFrom ROWS
                FETCH NEXT 10 ROWS ONLY";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@Search", SqlDbType.NVarChar, 200)
                            .Value = searchType;

                        cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar, 402)
                            .Value = "%" + searchType + "%";

                        cmd.Parameters.Add("@StartFrom", SqlDbType.Int)
                            .Value = startFrom;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                TypeMaster condition = new TypeMaster();

                                condition.TypeID = Convert.ToInt32(rdr["TypeID"]);
                                condition.IsActive = Convert.ToInt32(rdr["IsActive"]);
                                condition.Position = Convert.ToInt32(rdr["Position"]);

                                if (rdr["DateandTime"] != DBNull.Value)
                                {
                                    condition.DateandTime =
                                        Convert.ToDateTime(rdr["DateandTime"]);

                                    condition.DateandTimes =
                                        condition.DateandTime.ToString("dd-MM-yyyy");
                                }

                                condition.Type = rdr["Type"] == DBNull.Value
                                    ? ""
                                    : rdr["Type"].ToString().ToUpper();

                                listUser.Add(condition);
                            }
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listTypeMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getTypeMaster Error: " + ex
                );

                response.Code = 500;
                response.Message = "Unable to retrieve Type Master records.";
                response.listTypeMaster = new List<TypeMaster>();
            }

            Context.Response.Write(js.Serialize(response));
        }
