        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getTypeMasterById(string id)
        {
            JavaScriptSerializer js;
            List<TypeMaster> listUser = new List<TypeMaster>();
            TypeMasterResponse response = new TypeMasterResponse();

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = "select * from TypeMaster where TypeID = " + id;
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        TypeMaster typeMaster = new TypeMaster
                        {
                            TypeID = rdr["TypeID"] != DBNull.Value
                                ? Convert.ToInt32(rdr["TypeID"])
                                : 0,

                            Type = rdr["Type"] != DBNull.Value
                                ? rdr["Type"].ToString().Trim().ToUpper()
                                : string.Empty,

                            IsActive = rdr["IsActive"] != DBNull.Value
                                ? Convert.ToInt32(rdr["IsActive"])
                                : 0,

                            UnitId = rdr["UnitId"] != DBNull.Value
                                ? Convert.ToInt32(rdr["UnitId"])
                                : 0
                        };

                        listUser.Add(typeMaster);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 200;
            response.Message = "Success";
            response.listTypeMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditTypeMaster()
        {
            CommanResponse comman = new CommanResponse();

            int typeId = 0;
            int isActive = 0;
            int userAccountId = 0;
            int companyId = 0;
            int unitId = 0;

            string type = "";

            try
            {
                var request = HttpContext.Current.Request;

                type = (request.Params["Type"] ?? "").Trim().ToUpper();

                // Validate input
                if (!int.TryParse(request.Params["TypeID"], out typeId) ||
                    typeId <= 0 ||
                    string.IsNullOrWhiteSpace(type) ||
                    !int.TryParse(request.Params["IsActive"], out isActive) ||
                    (isActive != 0 && isActive != 1))
                {
                    comman.Code = 400;
                    comman.Message = "Please enter valid Type details.";
                    WriteJsonResponse(comman);
                    return;
                }

                // UnitId is optional because TypeMaster.UnitId allows NULL
                string unitValue = request.Params["UnitId"];

                if (!string.IsNullOrWhiteSpace(unitValue) &&
                    !int.TryParse(unitValue, out unitId))
                {
                    comman.Code = 400;
                    comman.Message = "Please select a valid Unit.";
                    WriteJsonResponse(comman);
                    return;
                }

                // Existing project cookie format
                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null ||
                    string.IsNullOrEmpty(userCookie.Value) ||
                    string.IsNullOrEmpty(companyCookie.Value))
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user or company session.";
                    WriteJsonResponse(comman);
                    return;
                }

                string[] userParts = userCookie.Value.Split('=');
                string[] companyParts = companyCookie.Value.Split('=');

                if (userParts.Length < 2 ||
                    companyParts.Length < 2 ||
                    !int.TryParse(userParts[1], out userAccountId) ||
                    !int.TryParse(companyParts[1], out companyId))
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user or company session.";
                    WriteJsonResponse(comman);
                    return;
                }

                TypeMaster ilist = new TypeMaster
                {
                    TypeID = typeId,
                    Type = type,
                    IsActive = isActive,
                    UserAccountId = userAccountId,
                    CompanyId = companyId,
                    UnitId = unitId
                };

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // 1. Check record exists in current company
                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.TypeMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE TypeID = @TypeID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@TypeID", SqlDbType.Int).Value = typeId;
                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;

                                if (Convert.ToInt32(cmd.ExecuteScalar()) == 0)
                                {
                                    transaction.Rollback();

                                    comman.Code = 404;
                                    comman.Message = "Type record not found.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 2. Dependency check - DesignEntryFormMaster
                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignEntryFormMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE TypeID = @TypeID",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@TypeID", SqlDbType.Int).Value = typeId;

                                int dependencyCount =
                                    Convert.ToInt32(cmd.ExecuteScalar());

                                if (dependencyCount > 0)
                                {
                                    transaction.Rollback();

                                    comman.Code = 409;
                                    comman.Message =
                                        "This Type cannot be edited because it is already associated with existing Design Entry records.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 3. Duplicate check - Same company, excluding current record
                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.TypeMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND TypeID <> @TypeID
                          AND UPPER(LTRIM(RTRIM(Type))) = @Type",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;
                                cmd.Parameters.Add("@TypeID", SqlDbType.Int).Value = typeId;
                                cmd.Parameters.Add("@Type", SqlDbType.NVarChar, 100).Value = type;

                                if (Convert.ToInt32(cmd.ExecuteScalar()) > 0)
                                {
                                    transaction.Rollback();

                                    AuditLogHelper.LogDuplicateError(
                                        module: "Type Master",
                                        tableName: "TypeMaster",
                                        recordId: typeId.ToString(),
                                        description: $"Duplicate Type: {type}",
                                        errorMessage: "This Type already exists.",
                                        requestData: ilist
                                    );

                                    comman.Code = 409;
                                    comman.Message = "This Type already exists.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 4. Get old value for audit
                            object oldValue = AuditLogHelper.FetchOldValue(
                                "TypeMaster",
                                typeId.ToString(),
                                con
                            );

                            // 5. Update only after both checks pass
                            int rowsAffected;

                            using (SqlCommand cmd = new SqlCommand(@"
                        UPDATE dbo.TypeMaster
                        SET
                            Type = @Type,
                            UnitId = @UnitId,
                            IsActive = @IsActive,
                            UserAccountId = @UserAccountId
                        WHERE TypeID = @TypeID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@Type", SqlDbType.NVarChar, 100)
                                    .Value = type;

                                cmd.Parameters.Add("@UnitId", SqlDbType.Int)
                                    .Value = string.IsNullOrWhiteSpace(unitValue)
                                        ? (object)DBNull.Value
                                        : unitId;

                                cmd.Parameters.Add("@IsActive", SqlDbType.TinyInt)
                                    .Value = isActive;

                                cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                    .Value = userAccountId;

                                cmd.Parameters.Add("@TypeID", SqlDbType.Int)
                                    .Value = typeId;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                rowsAffected = cmd.ExecuteNonQuery();
                            }

                            if (rowsAffected > 0)
                            {
                                // 6. Audit log
                                AuditLogHelper.LogTransactional(
                                    con,
                                    transaction,
                                    module: "Type Master",
                                    action: "UPDATE",
                                    tableName: "TypeMaster",
                                    description: $"Updated Type #{typeId} '{type}'",
                                    oldValue: oldValue,
                                    newValue: ilist,
                                    customUserId: userAccountId
                                );

                                transaction.Commit();

                                comman.Code = 201;
                                comman.Message = "Type has been updated successfully.";
                            }
                            else
                            {
                                transaction.Rollback();

                                comman.Code = 410;
                                comman.Message = "Type record was not updated.";
                            }
                        }
                        catch
                        {
                            if (transaction.Connection != null)
                            {
                                try
                                {
                                    transaction.Rollback();
                                }
                                catch
                                {
                                    // Transaction may already be completed.
                                }
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Type Master",
                    "EditTypeMaster",
                    ex,
                    $"ID: {typeId}, Type: {type}"
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 409;
                    comman.Message = "This Type already exists.";
                }
                else if (ex.Number == 547)
                {
                    comman.Code = 409;
                    comman.Message =
                        "This Type cannot be edited because it is linked with other records.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message =
                        "Problem occurred while updating Type.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Type Master",
                    "EditTypeMaster",
                    ex,
                    "Unable to update Type."
                );

                comman.Code = 500;
                comman.Message = "Unable to update Type.";
            }

            WriteJsonResponse(comman);
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteTypeMaster()
        {
            CommanResponse comman = new CommanResponse();

            int typeId = 0;
            int userAccountId = 0;
            int companyId = 0;

            try
            {
                var request = HttpContext.Current.Request;

                // 1. Validate TypeID
                if (!int.TryParse(request.Params["TypeID"], out typeId) ||
                    typeId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Type ID.";
                    WriteJsonResponse(comman);
                    return;
                }

                // 2. Cookie validation - Existing project cookie format
                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null ||
                    string.IsNullOrEmpty(userCookie.Value) ||
                    string.IsNullOrEmpty(companyCookie.Value))
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user or company session.";
                    WriteJsonResponse(comman);
                    return;
                }

                string[] userParts = userCookie.Value.Split('=');
                string[] companyParts = companyCookie.Value.Split('=');

                if (userParts.Length < 2 ||
                    companyParts.Length < 2 ||
                    !int.TryParse(userParts[1], out userAccountId) ||
                    !int.TryParse(companyParts[1], out companyId))
