                                }
                            }

                            // 4. Dependency check - DesignEntryFormMaster
                            using (SqlCommand cmdCheck = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignEntryFormMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE TypeID = @TypeID",
                                con, transaction))
                            {
                                cmdCheck.Parameters.Add("@TypeID", SqlDbType.Int)
                                    .Value = typeId;

                                int dependencyCount =
                                    Convert.ToInt32(cmdCheck.ExecuteScalar());

                                if (dependencyCount > 0)
                                {
                                    transaction.Rollback();

                                    comman.Code = 409;
                                    comman.Message =
                                        "This Type cannot be deleted because it is already associated with existing Design Entry records.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 5. Get old value for audit
                            object oldValue = AuditLogHelper.FetchOldValue(
                                "TypeMaster",
                                typeId.ToString(),
                                con
                            );

                            // 6. Delete record
                            int rowsAffected;

                            using (SqlCommand cmdDelete = new SqlCommand(@"
                        DELETE FROM dbo.TypeMaster
                        WHERE TypeID = @TypeID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmdDelete.Parameters.Add("@TypeID", SqlDbType.Int)
                                    .Value = typeId;

                                cmdDelete.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                rowsAffected = cmdDelete.ExecuteNonQuery();
                            }

                            if (rowsAffected > 0)
                            {
                                // 7. Audit log
                                AuditLogHelper.LogTransactional(
                                    con,
                                    transaction,
                                    module: "Type Master",
                                    action: "DELETE",
                                    tableName: "TypeMaster",
                                    description: "Deleted Type ID #" + typeId,
                                    oldValue: oldValue,
                                    newValue: null,
                                    customUserId: userAccountId
                                );

                                transaction.Commit();

                                comman.Code = 200;
                                comman.Message = "Type deleted successfully.";
                            }
                            else
                            {
                                transaction.Rollback();

                                comman.Code = 410;
                                comman.Message = "Failed to delete Type record.";
                            }
                        }
                        catch
                        {
                            if (transaction.Connection != null)
                            {
                                try
                                {
                                    transaction.Rollback();
                                }
                                catch
                                {
                                    // Transaction may already be completed.
                                }
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Type Master",
                    "DeleteTypeMaster",
                    ex,
                    "TypeID: " + typeId
                );

                if (ex.Number == 547)
                {
                    comman.Code = 409;
                    comman.Message =
                        "This Type cannot be deleted because it is linked with other records.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem occurred while deleting Type.";
                }
