            {
                AuditLogHelper.LogError(
                    "Type Master",
                    "DeleteTypeMaster",
                    ex,
                    "TypeID: " + typeId
                );

                comman.Code = 500;
                comman.Message = "Unable to delete Type.";
            }

            WriteJsonResponse(comman);
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_TypeQueue()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            TypeMasterResponse response = new TypeMasterResponse();

            try
            {
                string postQueue = HttpContext.Current.Request.Params["PostQueue"];

                if (string.IsNullOrWhiteSpace(postQueue))
                {
                    response.Code = 0;
                    response.Message = "Invalid queue data.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string[] records = postQueue.Split('|');

                if (records.Length != 2)
                {
                    response.Code = 0;
                    response.Message = "Invalid queue data.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string[] first = records[0].Split(',');
                string[] second = records[1].Split(',');

                int firstId, firstPosition, secondId, secondPosition;

                if (first.Length != 2 || second.Length != 2 ||
                    !int.TryParse(first[0], out firstId) || firstId <= 0 ||
                    !int.TryParse(first[1], out firstPosition) || firstPosition < 0 ||
                    !int.TryParse(second[0], out secondId) || secondId <= 0 ||
                    !int.TryParse(second[1], out secondPosition) || secondPosition < 0 ||
                    firstId == secondId)
                {
                    response.Code = 0;
                    response.Message = "Invalid queue values.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection conn = new SqlConnection(cs))
                {
                    conn.Open();

                    using (SqlTransaction transaction =
                        conn.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            string sql = @"
                        UPDATE dbo.TypeMaster
                        SET Position = CASE
                            WHEN TypeID = @FirstID THEN @SecondPosition
                            WHEN TypeID = @SecondID THEN @FirstPosition
                        END
                        WHERE TypeID IN (@FirstID, @SecondID)
                          AND (
                              (TypeID = @FirstID AND Position = @FirstPosition)
                              OR
                              (TypeID = @SecondID AND Position = @SecondPosition)
                          )";

                            using (SqlCommand cmd = new SqlCommand(sql, conn, transaction))
                            {
                                cmd.Parameters.Add("@FirstID", SqlDbType.Int).Value = firstId;
                                cmd.Parameters.Add("@FirstPosition", SqlDbType.Int).Value = firstPosition;
                                cmd.Parameters.Add("@SecondID", SqlDbType.Int).Value = secondId;
                                cmd.Parameters.Add("@SecondPosition", SqlDbType.Int).Value = secondPosition;

                                int rowsAffected = cmd.ExecuteNonQuery();

                                if (rowsAffected == 2)
                                {
                                    transaction.Commit();

                                    response.Code = 1;
                                    response.Message = "Success";
                                }
                                else
                                {
                                    transaction.Rollback();

                                    response.Code = 0;
                                    response.Message = "Queue records changed or not found. Please refresh and try again.";
                                }
                            }
                        }
                        catch
                        {
                            try
                            {
                                transaction.Rollback();
                            }
                            catch { }

                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "UpdateTbl_TypeQueue Error: " + ex
                );

                response.Code = 0;
                response.Message = "Error while updating Type queue.";
            }

            Context.Response.Write(js.Serialize(response));
        }
        #endregion

        #region Godown Master (GodownMaster.cshtml)

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertGodownMaster()
        {
            DateTime dateTimeIndian = TimeZoneInfo.ConvertTimeFromUtc(
                DateTime.UtcNow, India_Standard_Time);

            CommanResponse comman = new CommanResponse();
            GodownMaster ilist = new GodownMaster();

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            ilist.DateAndTime = dateTimeIndian;

            string userAccountId = "";
            string companyId = "";
            string financialYearID = "";

            if (Context.Request.Cookies["UserIDs"] != null)
            {
                string value = Context.Request.Cookies["UserIDs"].Value ?? "";
                userAccountId = value.Contains("=") ? value.Split('=')[1] : value;
            }

            if (Context.Request.Cookies["CompanyID"] != null)
            {
                string value = Context.Request.Cookies["CompanyID"].Value ?? "";
                companyId = value.Contains("=") ? value.Split('=')[1] : value;
            }

            if (Context.Request.Cookies["FinacialYearDefaultID"] != null)
            {
                string value = Context.Request.Cookies["FinacialYearDefaultID"].Value ?? "";
                financialYearID = value.Contains("=") ? value.Split('=')[1] : value;
            }

            long companyIdVal;
            long userAccountIdVal;

            if (!Int64.TryParse(companyId, out companyIdVal) || companyIdVal <= 0 ||
                !Int64.TryParse(userAccountId, out userAccountIdVal) || userAccountIdVal <= 0 ||
                string.IsNullOrWhiteSpace(financialYearID))
            {
                comman.Code = 500;
                comman.Message = "Please Re-Login your Account.";
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            ilist.GodownArray = HttpContext.Current.Request.Params["GodownArray"];

            if (string.IsNullOrWhiteSpace(ilist.GodownArray))
            {
                comman.Code = 500;
                comman.Message = "Invalid Godown Data.";
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            GodownMaster myDetails;

            try
            {
                myDetails = JsonConvert.DeserializeObject<GodownMaster>(
                    ilist.GodownArray);
            }
            catch
            {
                myDetails = null;
            }

            if (myDetails == null)
            {
                comman.Code = 500;
                comman.Message = "Invalid Godown Data.";
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            string godownTitle = (myDetails.GodownTitle ?? "").Trim().ToUpper();
            string godownAddress = (myDetails.GodownAddress ?? "").Trim().ToUpper();
            string gstin = (myDetails.GSTIN ?? "").Trim().ToUpper();

            long partyIdVal = 0;

            if (!Int64.TryParse(Convert.ToString(myDetails.PartyId), out partyIdVal))
            {
                comman.Code = 500;
                comman.Message = "Invalid Party.";
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            if (string.IsNullOrWhiteSpace(godownTitle))
            {
                comman.Code = 500;
                comman.Message = "Please enter Godown Title.";
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            if ((myDetails.IsActive != 0 && myDetails.IsActive != 1) ||
                (myDetails.IsDefault != 0 && myDetails.IsDefault != 1))
            {
                comman.Code = 500;
                comman.Message = "Invalid Godown Status.";
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction = con.BeginTransaction())
                    {
                        try
                        {
                            string checkSql = @"
                        SELECT COUNT(1)
                        FROM GodownMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND UPPER(LTRIM(RTRIM(GodownTitle))) = @GodownTitle";

                            using (SqlCommand checkCmd = new SqlCommand(checkSql, con, transaction))
                            {
                                checkCmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyIdVal;
                                checkCmd.Parameters.Add("@GodownTitle", SqlDbType.NVarChar, 200).Value = godownTitle;

                                int exists = Convert.ToInt32(checkCmd.ExecuteScalar());

                                if (exists > 0)
                                {
                                    transaction.Rollback();

                                    comman.Code = 500;
                                    comman.Message = "This Godown Title ALready Exists.";
                                    Context.Response.Write(js.Serialize(comman));
                                    return;
                                }
                            }

                            if (myDetails.IsDefault == 1)
                            {
                                string updateDefaultSql = @"
                            UPDATE GodownMaster
                            SET IsDefault = 0
                            WHERE CompanyId = @CompanyId";

                                using (SqlCommand updateDefaultCmd =
                                    new SqlCommand(updateDefaultSql, con, transaction))
                                {
                                    updateDefaultCmd.Parameters.Add(
                                        "@CompanyId", SqlDbType.BigInt).Value = companyIdVal;

                                    updateDefaultCmd.ExecuteNonQuery();
                                }
                            }

                            // GodownID is handled as INT, consistent with existing model usage.
                            int newGodownId = 0;

                            string insertMasterSql = @"
                        INSERT INTO GodownMaster
                        (
                            DateAndTime,
                            GodownTitle,
                            GodownAddress,
                            IsActive,
                            IsDefault,
                            CompanyId,
                            UserAccountId,
                            GSTIN,
                            PartyId
                        )
                        OUTPUT INSERTED.GodownID
                        VALUES
                        (
                            @DateAndTime,
                            @GodownTitle,
                            @GodownAddress,
                            @IsActive,
                            @IsDefault,
                            @CompanyId,
                            @UserAccountId,
                            @GSTIN,
                            @PartyId
                        )";

                            using (SqlCommand insertMasterCmd =
                                new SqlCommand(insertMasterSql, con, transaction))
                            {
                                insertMasterCmd.Parameters.Add(
                                    "@DateAndTime", SqlDbType.DateTime).Value = dateTimeIndian;

                                insertMasterCmd.Parameters.Add(
                                    "@GodownTitle", SqlDbType.NVarChar, 200).Value = godownTitle;

                                insertMasterCmd.Parameters.Add(
                                    "@GodownAddress", SqlDbType.NVarChar, 1000).Value = godownAddress;

                                insertMasterCmd.Parameters.Add(
                                    "@IsActive", SqlDbType.TinyInt).Value = (byte)myDetails.IsActive;

                                insertMasterCmd.Parameters.Add(
                                    "@IsDefault", SqlDbType.TinyInt).Value = (byte)myDetails.IsDefault;

                                insertMasterCmd.Parameters.Add(
                                    "@CompanyId", SqlDbType.BigInt).Value = companyIdVal;

                                insertMasterCmd.Parameters.Add(
                                    "@UserAccountId", SqlDbType.BigInt).Value = userAccountIdVal;

                                insertMasterCmd.Parameters.Add(
                                    "@GSTIN", SqlDbType.NVarChar, 50).Value = gstin;

                                insertMasterCmd.Parameters.Add(
                                    "@PartyId", SqlDbType.BigInt).Value = partyIdVal;

                                object insertedObj = insertMasterCmd.ExecuteScalar();

                                if (insertedObj != null && insertedObj != DBNull.Value)
                                {
                                    newGodownId = Convert.ToInt32(insertedObj);
                                }
                            }

                            if (newGodownId <= 0)
                            {
                                throw new Exception("Godown record could not be created.");
                            }

                            if (myDetails.listGodownLocationMaster != null &&
                                myDetails.listGodownLocationMaster.Count > 0)
                            {
                                int srNo = 1;

                                foreach (GodownLocationMaster each in myDetails.listGodownLocationMaster)
                                {
                                    if (each == null)
                                        continue;

                                    string locationTitle = (each.LocationTitle ?? "").Trim().ToUpper();

                                    if (string.IsNullOrWhiteSpace(locationTitle))
                                        continue;

                                    string insertLocSql = @"
                                INSERT INTO GodownLocationMaster
                                (
                                    DateandTime,
                                    SrNo,
                                    LocationTitle,
                                    GodownID
                                )
                                VALUES
                                (
                                    @DateAndTime,
                                    @SrNo,
                                    @LocationTitle,
                                    @GodownID
                                )";

                                    using (SqlCommand insertLocCmd =
                                        new SqlCommand(insertLocSql, con, transaction))
                                    {
                                        insertLocCmd.Parameters.Add(
                                            "@DateAndTime", SqlDbType.DateTime).Value = dateTimeIndian;

                                        insertLocCmd.Parameters.Add(
                                            "@SrNo", SqlDbType.Int).Value =
                                            each.SrNo > 0 ? each.SrNo : srNo;

                                        insertLocCmd.Parameters.Add(
                                            "@LocationTitle", SqlDbType.NVarChar, 200).Value = locationTitle;

                                        insertLocCmd.Parameters.Add(
                                            "@GodownID", SqlDbType.Int).Value = newGodownId;

                                        int locRows = insertLocCmd.ExecuteNonQuery();

                                        if (locRows <= 0)
                                        {
                                            throw new Exception(
                                                "Failed to insert Godown Location record.");
                                        }
                                    }

                                    srNo++;
                                }
                            }

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: transaction,
                                module: "Godown Master",
                                action: "CREATE",
                                tableName: "GodownMaster",
                                recordId: newGodownId.ToString(),
                                description: "Created Godown #" + newGodownId +
                                             " '" + godownTitle + "'",
                                oldValue: null,
                                newValue: myDetails,
                                status: "Success",
                                customUserId: userAccountIdVal,
                                customUserName: null
                            );

                            transaction.Commit();

                            comman.id = newGodownId;
                            comman.Code = 200;
                            comman.Message = "Record has been saved successfully";
                        }
                        catch
                        {
                            try
                            {
                                transaction.Rollback();
                            }
                            catch
                            {
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Godown Master", "insertGodownMaster", ex, ilist.GodownArray);

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "This Godown or Location already exists.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Godown Master", "insertGodownMaster", ex, ilist.GodownArray);

                comman.Code = 410;
                comman.Message = "Problem has been occurred while submitting your data.";
            }

            Context.Response.Write(js.Serialize(comman));
        }

