        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getGodownMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            GodownMasterResponse response = new GodownMasterResponse();
            List<GodownMaster> listUser = new List<GodownMaster>();

            try
            {
                int partyId = GetPartyId();

                string searchGodown = Convert.ToString(
                    HttpContext.Current.Request.Params["searchGodown"]);

                string startFromValue = Convert.ToString(
                    HttpContext.Current.Request.Params["startFrom"]);

                int startFrom = 0;

                if (!string.IsNullOrWhiteSpace(startFromValue) &&
                    (!Int32.TryParse(startFromValue, out startFrom) || startFrom < 0))
                {
                    response.Code = 0;
                    response.Message = "Invalid pagination value.";
                    response.listGodownMaster = listUser;

                    Context.Response.Clear();
                    Context.Response.ContentType = "application/json";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string whereClause = "";

                if (partyId > 0)
                {
                    whereClause += " WHERE GM.PartyId = @PartyId ";
                }

                if (!string.IsNullOrWhiteSpace(searchGodown))
                {
                    whereClause += string.IsNullOrEmpty(whereClause)
                        ? " WHERE "
                        : " AND ";

                    whereClause += @"
                (
                    GM.GodownTitle LIKE @SearchText
                    OR GM.GodownAddress LIKE @SearchText
                )";
                }

                string query = @"
            SELECT
                GM.*,
                ISNULL(PM.PartyName, '') AS PartyName,
                CASE
                    WHEN PM.SundryParty = 1 THEN 'Sundry Creditors'
                    WHEN PM.SundryParty = 2 THEN 'Sundry Debtors'
                    WHEN PM.SundryParty = 3 THEN 'Job Work'
                    ELSE ''
                END AS PartyType
            FROM GodownMaster GM
            LEFT JOIN PartyMaster PM
                ON PM.PartyId = GM.PartyId
            " + whereClause + @"
            ORDER BY GM.GodownID DESC
            OFFSET @StartFrom ROWS
            FETCH NEXT 10 ROWS ONLY";

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    if (partyId > 0)
                    {
                        cmd.Parameters.Add("@PartyId", SqlDbType.Int).Value = partyId;
                    }

                    if (!string.IsNullOrWhiteSpace(searchGodown))
                    {
                        cmd.Parameters.Add("@SearchText", SqlDbType.NVarChar, 4000)
                            .Value = "%" + searchGodown.Trim() + "%";
                    }

                    cmd.Parameters.Add("@StartFrom", SqlDbType.Int).Value = startFrom;

                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            GodownMaster condition = new GodownMaster();

                            condition.GodownID = Convert.ToInt32(rdr["GodownID"]);
                            condition.IsDefault = Convert.ToInt32(rdr["IsDefault"]);
                            condition.IsActive = Convert.ToInt32(rdr["IsActive"]);

                            condition.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"]);
                            condition.DateAndTimes = condition.DateAndTime.ToString("dd-MM-yyyy");

                            condition.GodownTitle = Convert.ToString(rdr["GodownTitle"]);
                            condition.GodownAddress = Convert.ToString(rdr["GodownAddress"]);
                            condition.PartyType = Convert.ToString(rdr["PartyType"]);

                            if (rdr["PartyId"] != DBNull.Value)
                            {
                                condition.PartyId = Convert.ToInt32(rdr["PartyId"]);
                            }

                            listUser.Add(condition);
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listGodownMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getGodownMaster Error: " + ex);

                response.Code = 0;
                response.Message = "Error while fetching Godown records.";
                response.listGodownMaster = new List<GodownMaster>();
            }

            Context.Response.Clear();
            Context.Response.ContentType = "application/json";
            Context.Response.Write(js.Serialize(response));
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getGodownMasterById()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            GodownMasterResponse response = new GodownMasterResponse();
            List<GodownMaster> listGodownMaster = new List<GodownMaster>();

            try
            {
                string encryptedId = Convert.ToString(
                    HttpContext.Current.Request.Params["GodownID"]);

                if (string.IsNullOrWhiteSpace(encryptedId))
                {
                    response.Code = 105;
                    response.Message = "Invalid Godown ID.";
                    response.listGodownMaster = listGodownMaster;

                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string invoiceId = encryptedId.Trim();

                if (!invoiceId.EndsWith("%3d%3d",
                    StringComparison.OrdinalIgnoreCase))
                {
                    invoiceId = invoiceId.Replace("==", "") + "%3d%3d";
                }

                int godownId;

                try
                {
                    string decryptedId = Decrypt(HttpUtility.UrlDecode(invoiceId));

                    if (!Int32.TryParse(decryptedId, out godownId) || godownId <= 0)
                    {
                        throw new Exception("Invalid Godown ID.");
                    }
                }
                catch
                {
                    response.Code = 105;
                    response.Message = "Invalid Godown ID.";
                    response.listGodownMaster = listGodownMaster;

                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    GodownMaster condition = null;

                    string masterSql = @"
                SELECT *
                FROM GodownMaster
                WHERE GodownID = @GodownID";

                    using (SqlCommand cmd = new SqlCommand(masterSql, con))
                    {
                        cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = godownId;

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            if (rdr.Read())
                            {
                                condition = new GodownMaster();

                                condition.GodownID = Convert.ToInt32(rdr["GodownID"]);
                                condition.GSTIN = Convert.ToString(rdr["GSTIN"]);
                                condition.GodownTitle = Convert.ToString(rdr["GodownTitle"]);
                                condition.GodownAddress = Convert.ToString(rdr["GodownAddress"]);
                                condition.IsActive = Convert.ToInt32(rdr["IsActive"]);
                            }
                        }
                    }

                    if (condition == null)
                    {
                        response.Code = 105;
                        response.Message = "Godown Not Exist.";
                        response.listGodownMaster = listGodownMaster;
                    }
                    else
                    {
                        List<GodownLocationMaster> locations =
                            new List<GodownLocationMaster>();

                        string locationSql = @"
                    SELECT
                        GodownLocationID,
                        SrNo,
                        LocationTitle
                    FROM GodownLocationMaster
                    WHERE GodownID = @GodownID
                    ORDER BY SrNo";

                        using (SqlCommand cmd = new SqlCommand(locationSql, con))
                        {
                            cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = godownId;

                            using (SqlDataReader rdr = cmd.ExecuteReader())
                            {
                                while (rdr.Read())
                                {
                                    GodownLocationMaster location =
                                        new GodownLocationMaster();

                                    location.GodownLocationID =
                                        Convert.ToInt32(rdr["GodownLocationID"]);

                                    location.SrNo = Convert.ToInt32(rdr["SrNo"]);
                                    location.LocationTitle =
                                        Convert.ToString(rdr["LocationTitle"]);

                                    locations.Add(location);
                                }
                            }
                        }

                        condition.listGodownLocationMaster = locations;
                        listGodownMaster.Add(condition);

                        response.Code = 200;
                        response.Message = "Success";
                        response.listGodownMaster = listGodownMaster;
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getGodownMasterById Error: " + ex);

                response.Code = 0;
                response.Message = "Error while fetching Godown details.";
                response.listGodownMaster = new List<GodownMaster>();
            }

            Context.Response.Write(js.Serialize(response));
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditGodownMaster()
        {
            DateTime dateTimeIndian = TimeZoneInfo.ConvertTimeFromUtc(
                DateTime.UtcNow, India_Standard_Time);

            CommanResponse comman = new CommanResponse();
            GodownMaster ilist = new GodownMaster();

            try
            {
                var request = HttpContext.Current.Request;

                string userCookie = request.Cookies["UserIDs"]?.Value ?? "";
                string companyCookie = request.Cookies["CompanyID"]?.Value ?? "";
                string financialCookie = request.Cookies["FinacialYearDefaultID"]?.Value ?? "";

                string userValue = userCookie.Contains("=")
                    ? userCookie.Substring(userCookie.LastIndexOf('=') + 1) : userCookie;

                string companyValue = companyCookie.Contains("=")
                    ? companyCookie.Substring(companyCookie.LastIndexOf('=') + 1) : companyCookie;

                string financialValue = financialCookie.Contains("=")
                    ? financialCookie.Substring(financialCookie.LastIndexOf('=') + 1) : financialCookie;

                if (!Int64.TryParse(userValue, out long userAccountId) || userAccountId <= 0 ||
                    !Int64.TryParse(companyValue, out long companyId) || companyId <= 0 ||
                    string.IsNullOrWhiteSpace(financialValue))
                {
                    comman.Code = 401;
                    comman.Message = "Please Re-Login your Account.";
                    WriteGodownResponse(comman);
                    return;
                }

                ilist.GodownArray = request.Params["GodownArray"];

                if (string.IsNullOrWhiteSpace(ilist.GodownArray))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Godown Data.";
                    WriteGodownResponse(comman);
                    return;
                }

                GodownMaster myDetails;

                try
                {
                    myDetails = JsonConvert.DeserializeObject<GodownMaster>(
                        ilist.GodownArray);
                }
                catch
                {
                    myDetails = null;
                }

                if (myDetails == null || myDetails.GodownID <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Godown ID.";
                    WriteGodownResponse(comman);
                    return;
                }

                string godownTitle = (myDetails.GodownTitle ?? "").Trim().ToUpperInvariant();
                string godownAddress = (myDetails.GodownAddress ?? "").Trim().ToUpperInvariant();
                string gstin = (myDetails.GSTIN ?? "").Trim().ToUpperInvariant();

                if (string.IsNullOrWhiteSpace(godownTitle))
                {
                    comman.Code = 400;
                    comman.Message = "Please enter Godown Title.";
                    WriteGodownResponse(comman);
                    return;
                }

                if (myDetails.IsActive != 0 && myDetails.IsActive != 1)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Godown Status.";
                    WriteGodownResponse(comman);
                    return;
                }

                if (myDetails.IsDefault != 0 && myDetails.IsDefault != 1)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Default Status.";
                    WriteGodownResponse(comman);
                    return;
                }

                if (myDetails.IsManual != 0 && myDetails.IsManual != 1)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Manual Status.";
                    WriteGodownResponse(comman);
                    return;
                }

                if (myDetails.listGodownLocationMaster == null ||
                    myDetails.listGodownLocationMaster.Count == 0)
                {
                    comman.Code = 400;
                    comman.Message = "Please provide at least one valid Godown Location.";
                    WriteGodownResponse(comman);
                    return;
                }

                if (!Int64.TryParse(Convert.ToString(myDetails.PartyId), out long partyId) ||
                    partyId < 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Party.";
                    WriteGodownResponse(comman);
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // 1. Verify Godown ownership.
                            string verifySql = @"
                        SELECT COUNT(1)
                        FROM dbo.GodownMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE GodownID = @GodownID
                          AND CompanyId = @CompanyId";

                            using (SqlCommand cmd = new SqlCommand(verifySql, con, transaction))
                            {
                                cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value =
                                    myDetails.GodownID;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value =
                                    companyId;

                                if (Convert.ToInt32(cmd.ExecuteScalar()) == 0)
                                {
                                    throw new Exception("Godown record not found.");
                                }
                            }

                            // 2. Duplicate Godown Title check.
                            string duplicateGodownSql = @"
                        SELECT COUNT(1)
                        FROM dbo.GodownMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND GodownID <> @GodownID
                          AND UPPER(LTRIM(RTRIM(GodownTitle))) = @GodownTitle";

                            using (SqlCommand cmd = new SqlCommand(
                                duplicateGodownSql, con, transaction))
                            {
                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;
                                cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = myDetails.GodownID;
                                cmd.Parameters.Add("@GodownTitle", SqlDbType.NVarChar, 200).Value = godownTitle;

                                if (Convert.ToInt32(cmd.ExecuteScalar()) > 0)
                                {
                                    AuditLogHelper.LogDuplicateError(
                                        module: "Godown Master",
                                        tableName: "GodownMaster",
                                        recordId: myDetails.GodownID.ToString(),
                                        description: "Duplicate Godown Title: " + godownTitle,
                                        errorMessage: "This Godown Title Already Exists.",
                                        requestData: myDetails,
                                        conn: con,
                                        tran: transaction
                                    );

                                    transaction.Rollback();

                                    comman.Code = 409;
                                    comman.Message = "This Godown Title Already Exists.";
                                    WriteGodownResponse(comman);
                                    return;
                                }
                            }

                            // 3. Delete selected locations after dependency checking.
                            string deleteLocationArray =
                                (myDetails.DeleteGodownArray ?? "").Trim();

                            if (!string.IsNullOrWhiteSpace(deleteLocationArray))
                            {
                                List<int> deleteIds = new List<int>();

                                foreach (string value in deleteLocationArray.Split(','))
                                {
                                    if (!Int32.TryParse(value.Trim(), out int locationId) ||
                                        locationId <= 0)
                                    {
                                        throw new Exception("Invalid Godown Location ID.");
                                    }

                                    if (!deleteIds.Contains(locationId))
                                        deleteIds.Add(locationId);
                                }

                                foreach (int locationId in deleteIds)
                                {
                                    // Verify location belongs to this Godown.
                                    using (SqlCommand cmd = new SqlCommand(@"
                                SELECT COUNT(1)
                                FROM dbo.GodownLocationMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE GodownLocationID = @ID
                                  AND GodownID = @GodownID",
                                        con, transaction))
                                    {
                                        cmd.Parameters.Add("@ID", SqlDbType.Int).Value = locationId;
                                        cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value =
                                            myDetails.GodownID;

                                        if (Convert.ToInt32(cmd.ExecuteScalar()) == 0)
                                            throw new Exception("Godown Location not found.");
                                    }

                                    // Dependency: YarnInwardDetail.
                                    int inwardCount;

                                    using (SqlCommand cmd = new SqlCommand(@"
                                SELECT COUNT(1)
                                FROM dbo.YarnInwardDetail WITH (UPDLOCK, HOLDLOCK)
                                WHERE GodownLocationID = @ID",
                                        con, transaction))
                                    {
                                        cmd.Parameters.Add("@ID", SqlDbType.Int).Value = locationId;
                                        inwardCount = Convert.ToInt32(cmd.ExecuteScalar());
                                    }

                                    // Dependency: YarnInterchangeMaster.
                                    int interchangeCount;

                                    using (SqlCommand cmd = new SqlCommand(@"
                                SELECT COUNT(1)
                                FROM dbo.YarnInterchangeMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE GodownLocationID = @ID",
                                        con, transaction))
                                    {
                                        cmd.Parameters.Add("@ID", SqlDbType.Int).Value = locationId;
                                        interchangeCount = Convert.ToInt32(cmd.ExecuteScalar());
                                    }

                                    if (inwardCount > 0 || interchangeCount > 0)
                                    {
                                        string errorMessage =
                                            "This Godown Location cannot be deleted because it is linked with existing Yarn Inward or Yarn Interchange records.";

                                        AuditLogHelper.LogError(
                                            "Godown Master",
                                            "EditGodownMaster",
                                            new InvalidOperationException(errorMessage),
                                            "GodownLocationID: " + locationId
                                        );

                                        transaction.Rollback();

                                        comman.Code = 409;
                                        comman.Message = errorMessage;
                                        WriteGodownResponse(comman);
                                        return;
                                    }

                                    using (SqlCommand cmd = new SqlCommand(@"
                                DELETE FROM dbo.GodownLocationMaster
                                WHERE GodownLocationID = @ID
                                  AND GodownID = @GodownID",
                                        con, transaction))
                                    {
                                        cmd.Parameters.Add("@ID", SqlDbType.Int).Value = locationId;
                                        cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value =
                                            myDetails.GodownID;

                                        cmd.ExecuteNonQuery();
                                    }
                                }
                            }

                            // 4. Update Godown Master.
                            using (SqlCommand cmd = new SqlCommand(@"
                        UPDATE dbo.GodownMaster
                        SET GodownTitle = @GodownTitle,
                            GodownAddress = @GodownAddress,
                            IsActive = @IsActive,
                            IsDefault = @IsDefault,
                            IsManual = @IsManual,
                            UserAccountId = @UserAccountId,
                            GSTIN = @GSTIN,
                            PartyId = @PartyId
                        WHERE GodownID = @GodownID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@GodownTitle", SqlDbType.NVarChar, 200).Value = godownTitle;
                                cmd.Parameters.Add("@GodownAddress", SqlDbType.NVarChar, 1000).Value = godownAddress;
                                cmd.Parameters.Add("@IsActive", SqlDbType.TinyInt).Value = (byte)myDetails.IsActive;
                                cmd.Parameters.Add("@IsDefault", SqlDbType.TinyInt).Value = (byte)myDetails.IsDefault;
                                cmd.Parameters.Add("@IsManual", SqlDbType.TinyInt).Value = (byte)myDetails.IsManual;
                                cmd.Parameters.Add("@UserAccountId", SqlDbType.BigInt).Value = userAccountId;
                                cmd.Parameters.Add("@GSTIN", SqlDbType.NVarChar, 50).Value = gstin;
                                cmd.Parameters.Add("@PartyId", SqlDbType.BigInt).Value = partyId;
                                cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = myDetails.GodownID;
                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                                if (cmd.ExecuteNonQuery() <= 0)
                                    throw new Exception("Godown record not found.");
                            }

                            // 5. Insert or update locations.
                            int srNo = 1;
                            HashSet<int> submittedLocationIds = new HashSet<int>();
                            HashSet<string> submittedLocationTitles =
                                new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                            foreach (GodownLocationMaster location in myDetails.listGodownLocationMaster)
                            {
                                if (location == null)
                                    continue;

                                string locationTitle =
                                    (location.LocationTitle ?? "").Trim().ToUpperInvariant();

                                if (string.IsNullOrWhiteSpace(locationTitle))
                                    continue;

                                if (!submittedLocationTitles.Add(locationTitle))
                                {
                                    throw new InvalidOperationException(
                                        "Duplicate Location '" + locationTitle +
                                        "' in the submitted Godown.");
                                }

                                if (!Int32.TryParse(
                                    Convert.ToString(location.GodownLocationID),
                                    out int locationId) || locationId < 0)
                                {
                                    throw new Exception("Invalid Godown Location ID.");
                                }

                                // Check duplicate location title within the same Godown.
                                using (SqlCommand cmd = new SqlCommand(@"
                            SELECT COUNT(1)
                            FROM dbo.GodownLocationMaster WITH (UPDLOCK, HOLDLOCK)
                            WHERE GodownID = @GodownID
                              AND GodownLocationID <> @LocationID
                              AND UPPER(LTRIM(RTRIM(LocationTitle))) = @LocationTitle",
                                    con, transaction))
                                {
                                    cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = myDetails.GodownID;
                                    cmd.Parameters.Add("@LocationID", SqlDbType.Int).Value = locationId;
                                    cmd.Parameters.Add("@LocationTitle", SqlDbType.NVarChar, 200).Value =
                                        locationTitle;

                                    if (Convert.ToInt32(cmd.ExecuteScalar()) > 0)
                                    {
                                        AuditLogHelper.LogDuplicateError(
                                            module: "Godown Master",
                                            tableName: "GodownLocationMaster",
                                            recordId: locationId.ToString(),
                                            description: "Duplicate Godown Location: " + locationTitle,
                                            errorMessage: "Location '" + locationTitle +
                                                          "' already exists in this Godown.",
                                            requestData: location,
                                            conn: con,
                                            tran: transaction
                                        );

                                        transaction.Rollback();

                                        comman.Code = 409;
                                        comman.Message = "Location '" + locationTitle +
                                                         "' already exists in this Godown.";
                                        WriteGodownResponse(comman);
                                        return;
                                    }
                                }

                                if (locationId > 0)
                                {
                                    // Existing location must belong to this Godown.
                                    using (SqlCommand cmd = new SqlCommand(@"
                                UPDATE dbo.GodownLocationMaster
                                SET DateandTime = @DateAndTime,
                                    SrNo = @SrNo,
                                    LocationTitle = @LocationTitle
                                WHERE GodownLocationID = @LocationID
                                  AND GodownID = @GodownID",
                                        con, transaction))
                                    {
                                        cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime).Value = dateTimeIndian;
                                        cmd.Parameters.Add("@SrNo", SqlDbType.Int).Value = srNo;
                                        cmd.Parameters.Add("@LocationTitle", SqlDbType.NVarChar, 200).Value = locationTitle;
                                        cmd.Parameters.Add("@LocationID", SqlDbType.Int).Value = locationId;
                                        cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = myDetails.GodownID;

                                        if (cmd.ExecuteNonQuery() <= 0)
                                            throw new Exception("Godown Location record not found.");
                                    }

                                    submittedLocationIds.Add(locationId);
                                }
                                else
                                {
                                    using (SqlCommand cmd = new SqlCommand(@"
                                INSERT INTO dbo.GodownLocationMaster
                                (DateandTime, SrNo, LocationTitle, GodownID)
                                VALUES
                                (@DateAndTime, @SrNo, @LocationTitle, @GodownID)",
                                        con, transaction))
                                    {
                                        cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime).Value = dateTimeIndian;
                                        cmd.Parameters.Add("@SrNo", SqlDbType.Int).Value = srNo;
                                        cmd.Parameters.Add("@LocationTitle", SqlDbType.NVarChar, 200).Value = locationTitle;
                                        cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = myDetails.GodownID;

                                        cmd.ExecuteNonQuery();
                                    }
                                }

                                srNo++;
                            }

                            // 6. Transactional audit.
                            AuditLogHelper.Log(
                                module: "Godown Master",
                                action: "UPDATE",
                                tableName: "GodownMaster",
                                recordId: myDetails.GodownID.ToString(),
                                description: "Updated Godown #" + myDetails.GodownID +
                                             " '" + godownTitle + "'",
                                newValue: myDetails,
                                existingConn: con,
                                existingTran: transaction
                            );

                            transaction.Commit();

                            comman.id = myDetails.GodownID;
                            comman.Code = 200;
                            comman.Message = "Record has been updated successfully.";
                        }
                        catch
                        {
                            try { transaction.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine("EditGodownMaster SQL Error: " + ex);

                try
                {
                    AuditLogHelper.LogError(
                        "Godown Master", "EditGodownMaster", ex);
                }
                catch { }

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 409;
                    comman.Message = "This Godown or Location already exists.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem occurred while updating your data.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine("EditGodownMaster Error: " + ex);

                try
                {
                    AuditLogHelper.LogError(
                        "Godown Master", "EditGodownMaster", ex);
                }
                catch { }

                comman.Code = 500;
                comman.Message = ex.Message;
            }

            WriteGodownResponse(comman);
        }



        // =============================================================
        // COMMON JSON RESPONSE
        // =============================================================

        private void WriteGodownResponse(CommanResponse comman)
        {
            JavaScriptSerializer js =
                new JavaScriptSerializer();

            js.MaxJsonLength = Int32.MaxValue;

            Context.Response.Write(
                js.Serialize(comman)
            );
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteGodownMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse comman = new CommanResponse();

            try
            {
                var request = HttpContext.Current.Request;

                if (!Int32.TryParse(request.Params["GodownID"], out int godownId) ||
                    godownId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Godown ID.";
                    WriteGodownResponse(comman);
                    return;
                }

                string companyCookie = request.Cookies["CompanyID"]?.Value ?? "";
                string userCookie = request.Cookies["UserIDs"]?.Value ?? "";

                string companyValue = companyCookie.Contains("=")
                    ? companyCookie.Substring(companyCookie.LastIndexOf('=') + 1)
                    : companyCookie;

                string userValue = userCookie.Contains("=")
                    ? userCookie.Substring(userCookie.LastIndexOf('=') + 1)
                    : userCookie;

                if (!Int64.TryParse(companyValue, out long companyId) || companyId <= 0 ||
                    !Int64.TryParse(userValue, out long userAccountId) || userAccountId <= 0)
                {
                    comman.Code = 401;
                    comman.Message = "Please Re-Login your Account.";
                    WriteGodownResponse(comman);
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction transaction =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // 1. Verify Godown ownership.
                            object oldValue = null;

                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT *
                        FROM dbo.GodownMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE GodownID = @GodownID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = godownId;
                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                                using (SqlDataReader rdr = cmd.ExecuteReader())
                                {
                                    if (rdr.Read())
                                    {
                                        Dictionary<string, object> oldData =
                                            new Dictionary<string, object>();

                                        for (int i = 0; i < rdr.FieldCount; i++)
                                        {
                                            oldData[rdr.GetName(i)] =
                                                rdr.IsDBNull(i) ? null : rdr.GetValue(i);
                                        }

                                        oldValue = oldData;
                                    }
                                }
                            }

                            if (oldValue == null)
                            {
                                transaction.Rollback();
                                comman.Code = 404;
                                comman.Message = "Godown record not found.";
                                WriteGodownResponse(comman);
                                return;
                            }

                            // 2. Dependency check: YarnPO.
                            int yarnPOCount;

                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.YarnPO WITH (UPDLOCK, HOLDLOCK)
                        WHERE GodownID = @GodownID",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = godownId;
                                yarnPOCount = Convert.ToInt32(cmd.ExecuteScalar());
                            }

                            // 3. Dependency check: YarnInterchangeMaster.
                            int interchangeCount;

                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.YarnInterchangeMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE GodownID = @GodownID",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = godownId;
                                interchangeCount = Convert.ToInt32(cmd.ExecuteScalar());
                            }

                            if (yarnPOCount > 0 || interchangeCount > 0)
                            {
                                string errorMessage =
                                    "This Godown cannot be deleted because it is linked with existing Yarn Purchase Order or Yarn Interchange records.";

                                try
                                {
                                    AuditLogHelper.LogError(
                                        "Godown Master",
                                        "DeleteGodownMaster",
                                        new InvalidOperationException(errorMessage),
                                        "GodownID: " + godownId
                                    );
                                }
                                catch { }

                                transaction.Rollback();

                                comman.Code = 409;
                                comman.Message = errorMessage;
                                WriteGodownResponse(comman);
                                return;
                            }

                            // 4. Check all child locations before deleting.
                            List<int> locationIds = new List<int>();

                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT GodownLocationID
                        FROM dbo.GodownLocationMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE GodownID = @GodownID",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = godownId;

                                using (SqlDataReader rdr = cmd.ExecuteReader())
                                {
                                    while (rdr.Read())
                                        locationIds.Add(Convert.ToInt32(rdr["GodownLocationID"]));
                                }
                            }

                            foreach (int locationId in locationIds)
                            {
                                int inwardCount;
                                int locationInterchangeCount;

                                // YarnInwardDetail dependency.
                                using (SqlCommand cmd = new SqlCommand(@"
                            SELECT COUNT(1)
                            FROM dbo.YarnInwardDetail WITH (UPDLOCK, HOLDLOCK)
                            WHERE GodownLocationID = @LocationID",
                                    con, transaction))
                                {
                                    cmd.Parameters.Add("@LocationID", SqlDbType.Int).Value = locationId;
                                    inwardCount = Convert.ToInt32(cmd.ExecuteScalar());
                                }

                                // YarnInterchangeMaster location dependency.
                                using (SqlCommand cmd = new SqlCommand(@"
                            SELECT COUNT(1)
                            FROM dbo.YarnInterchangeMaster WITH (UPDLOCK, HOLDLOCK)
                            WHERE GodownLocationID = @LocationID",
                                    con, transaction))
                                {
                                    cmd.Parameters.Add("@LocationID", SqlDbType.Int).Value = locationId;
                                    locationInterchangeCount = Convert.ToInt32(cmd.ExecuteScalar());
                                }

                                if (inwardCount > 0 || locationInterchangeCount > 0)
                                {
                                    string errorMessage =
                                        "Godown cannot be deleted because Location ID " +
                                        locationId +
                                        " is linked with existing Yarn Inward or Yarn Interchange records.";

                                    try
                                    {
                                        AuditLogHelper.LogError(
                                            "Godown Master",
                                            "DeleteGodownMaster",
                                            new InvalidOperationException(errorMessage),
                                            "GodownID: " + godownId +
                                            ", GodownLocationID: " + locationId
                                        );
                                    }
                                    catch { }

                                    transaction.Rollback();

                                    comman.Code = 409;
                                    comman.Message = errorMessage;
                                    WriteGodownResponse(comman);
                                    return;
                                }
                            }

                            // 5. Delete child locations.
                            using (SqlCommand cmd = new SqlCommand(@"
                        DELETE FROM dbo.GodownLocationMaster
                        WHERE GodownID = @GodownID",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = godownId;
                                cmd.ExecuteNonQuery();
                            }

                            // 6. Delete Godown master.
                            using (SqlCommand cmd = new SqlCommand(@"
                        DELETE FROM dbo.GodownMaster
                        WHERE GodownID = @GodownID
                          AND CompanyId = @CompanyId",
                                con, transaction))
                            {
                                cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = godownId;
                                cmd.Parameters.Add("@CompanyId", SqlDbType.BigInt).Value = companyId;

                                if (cmd.ExecuteNonQuery() != 1)
                                    throw new Exception("Godown record could not be deleted.");
                            }

                            // 7. Transactional audit log.
                            AuditLogHelper.Log(
                                module: "Godown Master",
                                action: "DELETE",
                                tableName: "GodownMaster",
                                recordId: godownId.ToString(),
                                description: "Deleted Godown ID #" + godownId +
                                             " and " + locationIds.Count +
                                             " location record(s).",
                                oldValue: oldValue,
                                existingConn: con,
                                existingTran: transaction
                            );

                            transaction.Commit();

                            comman.Code = 200;
                            comman.Message = "Record Deleted Successfully.";
                        }
                        catch
                        {
                            try { transaction.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine("DeleteGodownMaster SQL Error: " + ex);

                try
                {
                    AuditLogHelper.LogError(
                        "Godown Master", "DeleteGodownMaster", ex);
                }
                catch { }

                comman.Code = 500;
                comman.Message = "Unable to delete Godown. It may be linked with other records.";
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine("DeleteGodownMaster Error: " + ex);

                try
                {
                    AuditLogHelper.LogError(
                        "Godown Master", "DeleteGodownMaster", ex);
                }
                catch { }

                comman.Code = 500;
                comman.Message = "Failed to delete record.";
            }

            WriteGodownResponse(comman);
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void CheckGodownLocationDependency()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse response = new CommanResponse();

            try
            {
                if (!Int32.TryParse(
                    HttpContext.Current.Request.Params["GodownLocationID"],
                    out int locationId) || locationId <= 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid Godown Location ID.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    string sql = @"
                SELECT
                    (SELECT COUNT(1)
                     FROM dbo.YarnInwardDetail
                     WHERE GodownLocationID = @LocationID)
                    +
                    (SELECT COUNT(1)
                     FROM dbo.YarnInterchangeMaster
                     WHERE GodownLocationID = @LocationID)
                ";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@LocationID", SqlDbType.Int)
                            .Value = locationId;

                        int dependencyCount = Convert.ToInt32(
                            cmd.ExecuteScalar()
                        );

                        if (dependencyCount > 0)
                        {
                            response.Code = 409;
                            response.Message =
                                "This Godown Location cannot be deleted because it is already used in Yarn Inward or Yarn Interchange records.";
                        }
                        else
                        {
                            response.Code = 200;
                            response.Message = "Godown Location can be deleted.";
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "CheckGodownLocationDependency SQL Error: " + ex
                );

                try
                {
                    AuditLogHelper.LogError(
                        "Godown Master",
                        "CheckGodownLocationDependency",
                        ex
                    );
                }
                catch { }

                response.Code = 500;
                response.Message = "Error checking Godown Location dependency.";
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "CheckGodownLocationDependency Error: " + ex
                );

                try
                {
                    AuditLogHelper.LogError(
                        "Godown Master",
                        "CheckGodownLocationDependency",
                        ex
                    );
                }
                catch { }

                response.Code = 500;
                response.Message = "Unable to check Godown Location dependency.";
            }

            Context.Response.Write(js.Serialize(response));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void ActiveFGodownMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse comman = new CommanResponse();

            try
            {
                int godownId;
                string godownIdValue =
                    Convert.ToString(HttpContext.Current.Request.Params["GodownID"]);

                if (!Int32.TryParse(godownIdValue, out godownId) || godownId <= 0)
                {
                    comman.Code = 0;
                    comman.Message = "Invalid Godown ID.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string companyCookie = Context.Request.Cookies["CompanyID"] != null
                    ? Context.Request.Cookies["CompanyID"].Value ?? ""
                    : "";

                string userCookie = Context.Request.Cookies["UserIDs"] != null
                    ? Context.Request.Cookies["UserIDs"].Value ?? ""
                    : "";

                string companyValue = companyCookie.Contains("=")
                    ? companyCookie.Substring(companyCookie.LastIndexOf('=') + 1)
                    : companyCookie;

                string userValue = userCookie.Contains("=")
                    ? userCookie.Substring(userCookie.LastIndexOf('=') + 1)
                    : userCookie;

                long companyId;
                long userAccountId;

                if (!Int64.TryParse(companyValue, out companyId) || companyId <= 0 ||
                    !Int64.TryParse(userValue, out userAccountId) || userAccountId <= 0)
                {
                    comman.Code = 0;
                    comman.Message = "Please Re-Login your Account.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            List<int> previousDefaultIds = new List<int>();

                            string selectSql = @"
                        SELECT GodownID
                        FROM GodownMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND IsDefault = 1";

                            using (SqlCommand selectCmd =
                                new SqlCommand(selectSql, con, tran))
                            {
                                selectCmd.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                using (SqlDataReader reader = selectCmd.ExecuteReader())
                                {
                                    while (reader.Read())
                                    {
                                        previousDefaultIds.Add(
                                            Convert.ToInt32(reader["GodownID"])
                                        );
                                    }
                                }
                            }

                            string verifySql = @"
                        SELECT COUNT(1)
                        FROM GodownMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE GodownID = @GodownID
                          AND CompanyId = @CompanyId";

                            using (SqlCommand verifyCmd =
                                new SqlCommand(verifySql, con, tran))
                            {
                                verifyCmd.Parameters.Add("@GodownID", SqlDbType.Int)
                                    .Value = godownId;

                                verifyCmd.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                if (Convert.ToInt32(verifyCmd.ExecuteScalar()) <= 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 0;
                                    comman.Message = "Godown record not found.";

                                    Context.Response.Write(js.Serialize(comman));
                                    return;
                                }
                            }

                            string resetSql = @"
                        UPDATE GodownMaster
                        SET IsDefault = 0
                        WHERE CompanyId = @CompanyId
                          AND IsDefault = 1";

                            using (SqlCommand resetCmd =
                                new SqlCommand(resetSql, con, tran))
                            {
                                resetCmd.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                resetCmd.ExecuteNonQuery();
                            }

                            string updateSql = @"
                        UPDATE GodownMaster
                        SET IsDefault = 1
                        WHERE GodownID = @GodownID
                          AND CompanyId = @CompanyId";

                            int rowsAffected;

                            using (SqlCommand updateCmd =
                                new SqlCommand(updateSql, con, tran))
                            {
                                updateCmd.Parameters.Add("@GodownID", SqlDbType.Int)
                                    .Value = godownId;

                                updateCmd.Parameters.Add("@CompanyId", SqlDbType.BigInt)
                                    .Value = companyId;

                                rowsAffected = updateCmd.ExecuteNonQuery();
                            }

                            if (rowsAffected != 1)
                            {
                                throw new Exception("Unable to set default Godown.");
                            }

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Godown Master",
                                action: "UPDATE",
                                tableName: "GodownMaster",
                                recordId: godownId.ToString(),
                                description: "Changed default Godown to ID #" + godownId,
                                oldValue: js.Serialize(new
                                {
                                    CompanyId = companyId,
                                    PreviousDefaultGodownIDs = previousDefaultIds
                                }),
                                newValue: js.Serialize(new
                                {
                                    CompanyId = companyId,
                                    DefaultGodownID = godownId
                                }),
                                customUserId: userAccountId
                            );

                            tran.Commit();

                            comman.Code = 1;
                            comman.Message = "Success";
                        }
                        catch
                        {
                            try
                            {
                                tran.Rollback();
                            }
                            catch
                            {
                            }

                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "ActiveFGodownMaster Error: " + ex);

                comman.Code = 0;
                comman.Message = "FAILED";
            }

            Context.Response.Write(js.Serialize(comman));
        }

