        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertLocationMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse comman = new CommanResponse();

            try
            {
                var request = HttpContext.Current.Request;

                LocationMaster ilist = new LocationMaster
                {
                    LocationTitle = request.Params["LocationTitle"],
                    LocationAddress = request.Params["LocationAddress"]
                };

                int isActive;
                if (!Int32.TryParse(request.Params["IsActive"], out isActive))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Active Status.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                ilist.IsActive = isActive;

                string companyCookie = Context.Request.Cookies["CompanyID"] != null
                    ? Context.Request.Cookies["CompanyID"].Value ?? ""
                    : "";

                string userCookie = Context.Request.Cookies["UserIDs"] != null
                    ? Context.Request.Cookies["UserIDs"].Value ?? ""
                    : "";

                string companyValue = companyCookie.Contains("=")
                    ? companyCookie.Substring(companyCookie.LastIndexOf('=') + 1)
                    : companyCookie;

                string userValue = userCookie.Contains("=")
                    ? userCookie.Substring(userCookie.LastIndexOf('=') + 1)
                    : userCookie;

                int companyId;
                int userAccountId;

                if (!Int32.TryParse(companyValue, out companyId) || companyId <= 0 ||
                    !Int32.TryParse(userValue, out userAccountId) || userAccountId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Please Re-Login your Account.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                ilist.CompanyId = companyId;
                ilist.UserAccountId = userAccountId;

                if (String.IsNullOrWhiteSpace(ilist.LocationTitle))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Location Title.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                DateTime dateTimeIndian =
                    TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            string insertSql = @"
                        INSERT INTO LocationMaster
                        (
                            DateAndTime,
                            LocationTitle,
                            LocationAddress,
                            IsActive,
                            CompanyId,
                            UserAccountId
                        )
                        VALUES
                        (
                            @DateAndTime,
                            @LocationTitle,
                            @LocationAddress,
                            @IsActive,
                            @CompanyId,
                            @UserAccountId
                        );

                        SELECT CAST(SCOPE_IDENTITY() AS INT);";

                            int newLocationId;

                            using (SqlCommand cmd =
                                new SqlCommand(insertSql, con, tran))
                            {
                                cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime)
                                    .Value = dateTimeIndian;

                                cmd.Parameters.Add("@LocationTitle", SqlDbType.NVarChar)
                                    .Value = ilist.LocationTitle.Trim();

                                cmd.Parameters.Add("@LocationAddress", SqlDbType.NVarChar)
                                    .Value = (object)ilist.LocationAddress ?? DBNull.Value;

                                cmd.Parameters.Add("@IsActive", SqlDbType.Int)
                                    .Value = ilist.IsActive;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = ilist.CompanyId;

                                cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                    .Value = ilist.UserAccountId;

                                object result = cmd.ExecuteScalar();

                                if (result == null || result == DBNull.Value)
                                {
                                    throw new Exception("Location ID was not generated.");
                                }

                                newLocationId = Convert.ToInt32(result);
                            }

                            ilist.LocationID = newLocationId;
                            ilist.DateAndTime = dateTimeIndian;

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Location Master",
                                action: "CREATE",
                                tableName: "LocationMaster",
                                recordId: newLocationId.ToString(),
                                description: "Created Location '" +
                                             ilist.LocationTitle + "'",
                                newValue: ilist,
                                customUserId: userAccountId
                            );

                            tran.Commit();

                            comman.Code = 201;
                            comman.Message = "Location has been saved successfully.";
                        }
                        catch
                        {
                            try
                            {
                                tran.Rollback();
                            }
                            catch
                            {
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Location Master",
                    "insertLocationMaster",
                    ex,
                    "Location insertion failed."
                );

                System.Diagnostics.Trace.WriteLine(
                    "insertLocationMaster SQL Error: " + ex);

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertLocationMaster Error: " + ex);

                comman.Code = 410;
                comman.Message = "Problem has been occurred while submitting your data.";
            }

            Context.Response.Write(js.Serialize(comman));
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getLocationMaster(string startFrom)
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<LocationMaster> listUser = new List<LocationMaster>();
            LocationMasterResponse response = new LocationMasterResponse();

            try
            {
                int offset;

                if (!Int32.TryParse(startFrom, out offset) || offset < 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid pagination value.";
                    response.listLocationMaster = listUser;

                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    string sql = @"
                SELECT *
                FROM LocationMaster
                ORDER BY LocationID DESC
                OFFSET @StartFrom ROWS
                FETCH NEXT 10 ROWS ONLY";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@StartFrom", SqlDbType.Int).Value = offset;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                LocationMaster condition = new LocationMaster();

                                condition.LocationID =
                                    Convert.ToInt32(rdr["LocationID"]);

                                condition.IsActive =
                                    Convert.ToInt32(rdr["IsActive"]);

                                condition.DateAndTime =
                                    Convert.ToDateTime(rdr["DateAndTime"]);

                                condition.DateAndTimes =
                                    condition.DateAndTime.ToString("dd-MM-yyyy");

                                condition.LocationTitle =
                                    rdr["LocationTitle"] == DBNull.Value
                                        ? ""
                                        : rdr["LocationTitle"].ToString();

                                condition.LocationAddress =
                                    rdr["LocationAddress"] == DBNull.Value
                                        ? ""
                                        : rdr["LocationAddress"].ToString();

                                listUser.Add(condition);
                            }
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listLocationMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getLocationMaster Error: " + ex);

                response.Code = 0;
                response.Message = "Unable to retrieve Location records.";
                response.listLocationMaster = listUser;
            }

            Context.Response.Write(js.Serialize(response));
        }

