        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditLocationMaster()
        {
            CommanResponse comman = new CommanResponse();

            try
            {
                var request = HttpContext.Current.Request;

                LocationMaster ilist = new LocationMaster();

                if (!Int32.TryParse(request.Params["LocationID"], out int locationId) || locationId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Location ID.";
                }
                else if (String.IsNullOrWhiteSpace(request.Params["LocationTitle"]))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Location Title.";
                }
                else if (!Int32.TryParse(request.Params["IsActive"], out int isActive) ||
                         (isActive != 0 && isActive != 1))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Active Status.";
                }
                else
                {
                    HttpCookie userCookie = request.Cookies["UserIDs"];
                    HttpCookie companyCookie = request.Cookies["CompanyID"];

                    string userValue = userCookie != null ? userCookie.Value : null;
                    string companyValue = companyCookie != null ? companyCookie.Value : null;

                    if (!String.IsNullOrEmpty(userValue) && userValue.Contains("="))
                        userValue = userValue.Substring(userValue.LastIndexOf('=') + 1);

                    if (!String.IsNullOrEmpty(companyValue) && companyValue.Contains("="))
                        companyValue = companyValue.Substring(companyValue.LastIndexOf('=') + 1);

                    if (!Int32.TryParse(userValue, out int userId) ||
                        !Int32.TryParse(companyValue, out int companyId))
                    {
                        comman.Code = 400;
                        comman.Message = "Invalid user or company information.";
                    }
                    else
                    {
                        ilist.LocationID = locationId;
                        ilist.LocationTitle = request.Params["LocationTitle"].Trim();
                        ilist.LocationAddress = request.Params["LocationAddress"] ?? "";
                        ilist.IsActive = isActive;
                        ilist.UserAccountId = userId;
                        ilist.CompanyId = companyId;

                        string cs = ConfigurationManager
                            .ConnectionStrings["sqlconnstr"].ConnectionString;

                        using (SqlConnection con = new SqlConnection(cs))
                        {
                            con.Open();

                            using (SqlTransaction tran = con.BeginTransaction())
                            {
                                try
                                {
                                    object oldValue = AuditLogHelper.FetchOldValue(
                                        "LocationMaster",
                                        ilist.LocationID.ToString(),
                                        con
                                    );

                                    string sql = @"
                                UPDATE LocationMaster
                                SET
                                    LocationTitle = @LocationTitle,
                                    LocationAddress = @LocationAddress,
                                    IsActive = @IsActive,
                                    UserAccountId = @UserAccountId,
                                    CompanyId = @CompanyId
                                WHERE LocationID = @LocationID";

                                    int rowsAffected;

                                    using (SqlCommand cmd = new SqlCommand(sql, con, tran))
                                    {
                                        cmd.Parameters.Add("@LocationTitle", SqlDbType.NVarChar)
                                            .Value = ilist.LocationTitle;

                                        cmd.Parameters.Add("@LocationAddress", SqlDbType.NVarChar)
                                            .Value = ilist.LocationAddress;

                                        cmd.Parameters.Add("@IsActive", SqlDbType.Int)
                                            .Value = ilist.IsActive;

                                        cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                            .Value = ilist.UserAccountId;

                                        cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                            .Value = ilist.CompanyId;

                                        cmd.Parameters.Add("@LocationID", SqlDbType.Int)
                                            .Value = ilist.LocationID;

                                        rowsAffected = cmd.ExecuteNonQuery();
                                    }

                                    if (rowsAffected > 0)
                                    {
                                        AuditLogHelper.LogTransactional(
                                            conn: con,
                                            tran: tran,
                                            module: "Location Master",
                                            action: "UPDATE",
                                            tableName: "LocationMaster",
                                            recordId: ilist.LocationID.ToString(),
                                            description: $"Updated Location #{ilist.LocationID} '{ilist.LocationTitle}'",
                                            oldValue: oldValue,
                                            newValue: ilist,
                                            customUserId: (long)ilist.UserAccountId
                                        );

                                        tran.Commit();

                                        comman.Code = 201;
                                        comman.Message = "Location has been updated successfully.";
                                    }
                                    else
                                    {
                                        tran.Rollback();

                                        comman.Code = 410;
                                        comman.Message = "Location record not found.";
                                    }
                                }
                                catch
                                {
                                    try { tran.Rollback(); } catch { }
                                    throw;
                                }
                            }
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Location Master",
                    "EditLocationMaster",
                    ex,
                    "Location update failed."
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "EditLocationMaster Error: " + ex
                );

                comman.Code = 410;
                comman.Message = "Problem has been occurred while submitting your data.";
            }

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            Context.Response.Write(js.Serialize(comman));
        }


