                            con.Open();

                            using (SqlTransaction tran =
                                con.BeginTransaction(IsolationLevel.Serializable))
                            {
                                try
                                {
                                    // 4. Check duplicate Design Specification
                                    string duplicateSql = @"
                                SELECT TOP 1 DesignSpecificationID
                                FROM dbo.DesignSpecificationMaster
                                     WITH (UPDLOCK, HOLDLOCK)
                                WHERE UPPER(LTRIM(RTRIM(DesignSpecification)))
                                      = @DesignSpecification
                                  AND CompanyId = @CompanyId";

                                    object duplicateID = null;

                                    using (SqlCommand duplicateCmd =
                                        new SqlCommand(duplicateSql, con, tran))
                                    {
                                        duplicateCmd.Parameters.Add(
                                            "@DesignSpecification",
                                            SqlDbType.NVarChar
                                        ).Value = ilist.DesignSpecification;

                                        duplicateCmd.Parameters.Add(
                                            "@CompanyId",
                                            SqlDbType.Int
                                        ).Value = companyId;

                                        duplicateID =
                                            duplicateCmd.ExecuteScalar();
                                    }

                                    if (duplicateID != null &&
                                        duplicateID != DBNull.Value)
                                    {
                                        tran.Rollback();

                                        comman.Code = 409;
                                        comman.Message =
                                            "Design Specification '" +
                                            ilist.DesignSpecification +
                                            "' already exists. Please enter a different Design Specification.";
                                    }
                                    else
                                    {
                                        // 5. Generate next Position
                                        int position;

                                        string positionSql = @"
                                    SELECT ISNULL(MAX(Position), 0) + 1
                                    FROM dbo.DesignSpecificationMaster
                                         WITH (UPDLOCK, HOLDLOCK)";

                                        using (SqlCommand positionCmd =
                                            new SqlCommand(positionSql, con, tran))
                                        {
                                            position = Convert.ToInt32(
                                                positionCmd.ExecuteScalar()
                                            );
                                        }

                                        // 6. Insert Design Specification
                                        string insertSql = @"
                                    INSERT INTO dbo.DesignSpecificationMaster
                                    (
                                        DateAndTime,
                                        DesignSpecification,
                                        IsActive,
                                        Position,
                                        CompanyId,
                                        UserAccountId
                                    )
                                    VALUES
                                    (
                                        @DateAndTime,
                                        @DesignSpecification,
                                        @IsActive,
                                        @Position,
                                        @CompanyId,
                                        @UserAccountId
                                    )";

                                        using (SqlCommand cmd =
                                            new SqlCommand(insertSql, con, tran))
                                        {
                                            cmd.Parameters.Add(
                                                "@DateAndTime",
                                                SqlDbType.DateTime
                                            ).Value = dateTimeIndian;

                                            cmd.Parameters.Add(
                                                "@DesignSpecification",
                                                SqlDbType.NVarChar
                                            ).Value = ilist.DesignSpecification;

                                            cmd.Parameters.Add(
                                                "@IsActive",
                                                SqlDbType.Int
                                            ).Value = ilist.IsActive;

                                            cmd.Parameters.Add(
                                                "@Position",
                                                SqlDbType.Int
                                            ).Value = position;

                                            cmd.Parameters.Add(
                                                "@CompanyId",
                                                SqlDbType.Int
                                            ).Value = ilist.CompanyId;

                                            cmd.Parameters.Add(
                                                "@UserAccountId",
                                                SqlDbType.Int
                                            ).Value = ilist.UserAccountId;

                                            cmd.ExecuteNonQuery();
                                        }

                                        // 7. Audit Log
                                        AuditLogHelper.LogTransactional(
                                            conn: con,
                                            tran: tran,
                                            module: "Design Specification",
                                            action: "CREATE",
                                            tableName: "DesignSpecificationMaster",
                                            description:
                                                "Created Design Specification '" +
                                                ilist.DesignSpecification + "'",
                                            newValue: ilist,
                                            customUserId: (long)ilist.UserAccountId
                                        );

                                        // 8. Commit transaction
                                        tran.Commit();

                                        comman.Code = 201;
                                        comman.Message =
                                            "Design Specification '" +
                                            ilist.DesignSpecification +
                                            "' has been saved successfully.";
                                    }
                                }
                                catch
                                {
                                    try
                                    {
                                        tran.Rollback();
                                    }
                                    catch { }

                                    throw;
                                }
                            }
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Design Specification",
                    "insertDesignSpecificationMaster",
                    ex,
                    "Specification: " + ilist.DesignSpecification
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 409;
                    comman.Message =
                        "This Design Specification already exists. Please enter a different name.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message =
                        "A database error occurred while saving Design Specification. Please try again.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Design Specification",
                    "insertDesignSpecificationMaster",
                    ex,
                    "Specification: " + ilist.DesignSpecification
                );

                comman.Code = 500;
                comman.Message =
                    "Unable to save Design Specification. Please try again.";
            }

            // 9. Return JSON response
            Context.Response.ContentType = "application/json";
            Context.Response.Write(js.Serialize(comman));
        }


