        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignSpecificationMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<DesignSpecificationMaster> listUser =
                new List<DesignSpecificationMaster>();

            DesignSpecificationMasterResponse response =
                new DesignSpecificationMasterResponse();

            try
            {
                var request = HttpContext.Current.Request;

                string searchText = request.Params["searchDesignSpecification"] ?? "";
                string startFrom = request.Params["startFrom"];

                if (!Int32.TryParse(startFrom, out int offset) || offset < 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid pagination value.";
                    response.listDesignSpecificationMaster = listUser;

                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string sql = @"
            SELECT
                DesignSpecificationID,
                IsActive,
                Position,
                DateAndTime,
                DesignSpecification
            FROM DesignSpecificationMaster
            WHERE
                (@Search = '' OR DesignSpecification LIKE @SearchPattern)
            ORDER BY Position DESC
            OFFSET @StartFrom ROWS
            FETCH NEXT 10 ROWS ONLY";

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@Search", SqlDbType.NVarChar, 4000)
                            .Value = searchText.Trim();

                        cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar, 4000)
                            .Value = "%" + searchText.Trim() + "%";

                        cmd.Parameters.Add("@StartFrom", SqlDbType.Int)
                            .Value = offset;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                DesignSpecificationMaster condition =
                                    new DesignSpecificationMaster();

                                condition.DesignSpecificationID =
                                    Convert.ToInt32(rdr["DesignSpecificationID"]);

                                condition.IsActive =
                                    Convert.ToInt32(rdr["IsActive"]);

                                condition.Position =
                                    Convert.ToInt32(rdr["Position"]);

                                if (rdr["DateAndTime"] != DBNull.Value)
                                {
                                    condition.DateandTime =
                                        Convert.ToDateTime(rdr["DateAndTime"]);

                                    condition.DateandTimes =
                                        condition.DateandTime.ToString("dd-MM-yyyy");
                                }

                                condition.DesignSpecification =
                                    rdr["DesignSpecification"] == DBNull.Value
                                        ? ""
                                        : rdr["DesignSpecification"].ToString().ToUpper();

                                listUser.Add(condition);
                            }
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listDesignSpecificationMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getDesignSpecificationMaster Error: " + ex
                );

                response.Code = 0;
                response.Message = "Unable to retrieve Design Specification records.";
                response.listDesignSpecificationMaster = listUser;
            }

            Context.Response.Write(js.Serialize(response));
        }

