        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignSpecificationMasterById(string id)
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<DesignSpecificationMaster> listUser =
                new List<DesignSpecificationMaster>();

            DesignSpecificationMasterResponse response =
                new DesignSpecificationMasterResponse();

            try
            {
                if (!Int32.TryParse(id, out int specificationId) ||
                    specificationId <= 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid Design Specification ID.";
                    response.listDesignSpecificationMaster = listUser;

                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                string sql = @"
            SELECT
                DesignSpecificationID,
                DesignSpecification,
                IsActive
            FROM DesignSpecificationMaster
            WHERE DesignSpecificationID = @DesignSpecificationID";

                using (SqlConnection con = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@DesignSpecificationID", SqlDbType.Int)
                            .Value = specificationId;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                DesignSpecificationMaster condition =
                                    new DesignSpecificationMaster();

                                condition.DesignSpecificationID =
                                    Convert.ToInt32(rdr["DesignSpecificationID"]);

                                condition.DesignSpecification =
                                    rdr["DesignSpecification"] == DBNull.Value
                                        ? ""
                                        : rdr["DesignSpecification"].ToString().ToUpper();

                                condition.IsActive =
                                    Convert.ToInt32(rdr["IsActive"]);

                                listUser.Add(condition);
                            }
                        }
                    }
                }

                response.Code = 200;
                response.Message = "Success";
                response.listDesignSpecificationMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getDesignSpecificationMasterById Error: " + ex
                );

                response.Code = 500;
                response.Message = "Unable to retrieve Design Specification details.";
                response.listDesignSpecificationMaster = listUser;
            }

            Context.Response.Write(js.Serialize(response));
        }



        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditDesignSpecificationMaster()
        {
            CommanResponse comman = new CommanResponse();

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            DesignSpecificationMaster ilist = new DesignSpecificationMaster();

            try
            {
                var request = HttpContext.Current.Request;

                // 1. Validate Design Specification ID
                int specificationId;

                if (!Int32.TryParse(
                        request.Params["DesignSpecificationID"],
                        out specificationId) ||
                    specificationId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Design Specification ID.";
                }
                else if (String.IsNullOrWhiteSpace(
                             request.Params["DesignSpecification"]))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Design Specification.";
                }
                else
                {
                    // 2. Validate IsActive
                    int isActive;

                    if (!Int32.TryParse(
                            request.Params["IsActive"],
                            out isActive) ||
                        (isActive != 0 && isActive != 1))
                    {
                        comman.Code = 400;
                        comman.Message = "Invalid Active Status.";
                    }
                    else
                    {
                        // 3. Validate cookies
                        HttpCookie userCookie = request.Cookies["UserIDs"];
                        HttpCookie companyCookie = request.Cookies["CompanyID"];

                        string userValue =
                            userCookie != null ? userCookie.Value : null;

                        string companyValue =
                            companyCookie != null ? companyCookie.Value : null;

                        if (!String.IsNullOrEmpty(userValue) &&
                            userValue.Contains("="))
                        {
                            userValue = userValue.Substring(
                                userValue.LastIndexOf('=') + 1);
                        }

                        if (!String.IsNullOrEmpty(companyValue) &&
                            companyValue.Contains("="))
                        {
                            companyValue = companyValue.Substring(
                                companyValue.LastIndexOf('=') + 1);
                        }

                        int userId;
                        int companyId;

                        if (!Int32.TryParse(userValue, out userId) ||
                            userId <= 0 ||
                            !Int32.TryParse(companyValue, out companyId) ||
                            companyId <= 0)
                        {
                            comman.Code = 400;
                            comman.Message =
                                "Invalid user or company information.";
                        }
                        else
                        {
                            // 4. Prepare model
                            ilist.DesignSpecificationID = specificationId;

                            ilist.DesignSpecification =
                                request.Params["DesignSpecification"]
                                    .Trim()
                                    .ToUpperInvariant();

                            ilist.IsActive = isActive;
                            ilist.UserAccountId = userId;
                            ilist.CompanyId = companyId;

                            string cs = ConfigurationManager
                                .ConnectionStrings["sqlconnstr"].ConnectionString;

                            using (SqlConnection con = new SqlConnection(cs))
                            {
                                con.Open();

                                using (SqlTransaction tran =
                                    con.BeginTransaction(IsolationLevel.Serializable))
                                {
                                    try
                                    {
                                        // 5. Fetch existing record
                                        string oldSpecification = null;
                                        object oldValue = null;

                                        string fetchSql = @"
                                    SELECT
                                        DesignSpecificationID,
                                        DesignSpecification,
                                        IsActive,
                                        CompanyId
                                    FROM dbo.DesignSpecificationMaster
                                         WITH (UPDLOCK, HOLDLOCK)
                                    WHERE DesignSpecificationID = @ID
                                      AND CompanyId = @CompanyId";

                                        using (SqlCommand cmdFetch =
                                            new SqlCommand(fetchSql, con, tran))
                                        {
                                            cmdFetch.Parameters.Add(
                                                "@ID", SqlDbType.Int
                                            ).Value = specificationId;

                                            cmdFetch.Parameters.Add(
                                                "@CompanyId", SqlDbType.Int
                                            ).Value = companyId;

                                            using (SqlDataReader reader =
                                                cmdFetch.ExecuteReader())
                                            {
                                                if (reader.Read())
                                                {
                                                    oldSpecification =
                                                        reader["DesignSpecification"]
                                                            .ToString();

                                                    oldValue = new
                                                    {
                                                        DesignSpecificationID =
                                                            Convert.ToInt32(
                                                                reader["DesignSpecificationID"]),

                                                        DesignSpecification =
                                                            oldSpecification,

                                                        IsActive =
                                                            Convert.ToInt32(
                                                                reader["IsActive"]),

                                                        CompanyId =
                                                            Convert.ToInt32(
                                                                reader["CompanyId"])
                                                    };
                                                }
                                            }
                                        }

                                        // 6. Check record exists
                                        if (oldValue == null)
                                        {
                                            tran.Rollback();

                                            comman.Code = 404;
                                            comman.Message =
                                                "Design Specification record not found.";

                                        }
                                        else
                                        {
                                            bool specificationChanged =
                                                !String.Equals(
                                                    oldSpecification.Trim(),
                                                    ilist.DesignSpecification.Trim(),
                                                    StringComparison.OrdinalIgnoreCase
                                                );

                                            // 7. Duplicate Design Specification check
                                            string duplicateSql = @"
                                        SELECT COUNT(1)
                                        FROM dbo.DesignSpecificationMaster
                                             WITH (UPDLOCK, HOLDLOCK)
                                        WHERE UPPER(LTRIM(RTRIM(DesignSpecification)))
                                              = @DesignSpecification
                                          AND CompanyId = @CompanyId
                                          AND DesignSpecificationID <> @ID";

                                            int duplicateCount = 0;

                                            using (SqlCommand cmdDuplicate =
                                                new SqlCommand(duplicateSql, con, tran))
                                            {
                                                cmdDuplicate.Parameters.Add(
                                                    "@DesignSpecification",
                                                    SqlDbType.NVarChar
                                                ).Value = ilist.DesignSpecification;

                                                cmdDuplicate.Parameters.Add(
                                                    "@CompanyId",
                                                    SqlDbType.Int
                                                ).Value = companyId;

                                                cmdDuplicate.Parameters.Add(
                                                    "@ID",
                                                    SqlDbType.Int
                                                ).Value = specificationId;

                                                duplicateCount = Convert.ToInt32(
                                                    cmdDuplicate.ExecuteScalar());
                                            }

                                            if (duplicateCount > 0)
                                            {
                                                tran.Rollback();

                                                comman.Code = 409;
                                                comman.Message =
                                                    "Design Specification '" +
                                                    ilist.DesignSpecification +
                                                    "' already exists. Please enter a different name.";
                                            }
                                            else
                                            {
                                                // 8. Actual dependency check
                                                // Check only when specification name changes
                                                if (specificationChanged)
                                                {
                                                    string dependencySql = @"
                                                SELECT TOP 1
                                                    D.DesignEntryWeftID,
                                                    D.DesignEntryFormID,
                                                    E.DesignNo,
                                                    D.DesignSpecificationID
                                                FROM dbo.DesignEntryWeftData D
                                                LEFT JOIN dbo.DesignEntryFormMaster E
                                                    ON E.DesignEntryFormID =
                                                       D.DesignEntryFormID
                                                WHERE D.DesignSpecificationID = @ID
                                                ORDER BY D.DesignEntryWeftID";

                                                    using (SqlCommand cmdDependency =
                                                        new SqlCommand(
                                                            dependencySql,
                                                            con,
                                                            tran))
                                                    {
                                                        cmdDependency.Parameters.Add(
                                                            "@ID",
                                                            SqlDbType.Int
                                                        ).Value = specificationId;

                                                        using (SqlDataReader depReader =
                                                            cmdDependency.ExecuteReader())
                                                        {
                                                            if (depReader.Read())
                                                            {
                                                                string designNo =
                                                                    depReader["DesignNo"] ==
                                                                    DBNull.Value
                                                                        ? "N/A"
                                                                        : depReader["DesignNo"].ToString();

                                                                long weftID =
                                                                    Convert.ToInt64(
                                                                        depReader["DesignEntryWeftID"]);

                                                                depReader.Close();

                                                                tran.Rollback();

                                                                comman.Code = 409;
                                                                comman.Message =
                                                                    "Design Specification cannot be changed because it is already used in Design Entry Weft Data. " +                                                     
                                                                    ". Please use a new Design Specification instead.";

                                                            }
                                                            else
                                                            {
                                                                // No dependency found.
                                                                // Continue update below.
                                                            }
                                                        }
                                                    }
                                                }

                                                // 9. Update only if no validation error
                                                if (comman.Code != 409)
                                                {
                                                    string updateSql = @"
                                                UPDATE dbo.DesignSpecificationMaster
                                                SET
                                                    DesignSpecification = @DesignSpecification,
                                                    IsActive = @IsActive,
                                                    UserAccountId = @UserAccountId
                                                WHERE DesignSpecificationID = @ID
                                                  AND CompanyId = @CompanyId";

                                                    int rowsAffected;

                                                    using (SqlCommand cmdUpdate =
                                                        new SqlCommand(
                                                            updateSql,
                                                            con,
                                                            tran))
                                                    {
                                                        cmdUpdate.Parameters.Add(
                                                            "@DesignSpecification",
                                                            SqlDbType.NVarChar
                                                        ).Value = ilist.DesignSpecification;

                                                        cmdUpdate.Parameters.Add(
                                                            "@IsActive",
                                                            SqlDbType.Int
                                                        ).Value = ilist.IsActive;

                                                        cmdUpdate.Parameters.Add(
                                                            "@UserAccountId",
                                                            SqlDbType.Int
                                                        ).Value = ilist.UserAccountId;

                                                        cmdUpdate.Parameters.Add(
                                                            "@ID",
                                                            SqlDbType.Int
                                                        ).Value = specificationId;

                                                        cmdUpdate.Parameters.Add(
                                                            "@CompanyId",
                                                            SqlDbType.Int
                                                        ).Value = companyId;

                                                        rowsAffected =
                                                            cmdUpdate.ExecuteNonQuery();
                                                    }

                                                    if (rowsAffected > 0)
                                                    {
                                                        AuditLogHelper.LogTransactional(
                                                            conn: con,
                                                            tran: tran,
                                                            module: "Design Specification",
                                                            action: "UPDATE",
                                                            tableName: "DesignSpecificationMaster",
                                                            recordId: specificationId.ToString(),
                                                            description:
                                                                "Updated Design Specification #" +
                                                                specificationId +
                                                                " '" +
                                                                ilist.DesignSpecification +
                                                                "'",
                                                            oldValue: oldValue,
                                                            newValue: ilist,
                                                            customUserId: (long)userId
                                                        );

                                                        tran.Commit();

                                                        comman.Code = 201;
                                                        comman.Message =
                                                            "Design Specification '" +
                                                            ilist.DesignSpecification +
                                                            "' has been updated successfully.";
                                                    }
                                                    else
                                                    {
                                                        tran.Rollback();

                                                        comman.Code = 404;
                                                        comman.Message =
                                                            "Design Specification record not found.";
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    catch
                                    {
                                        try
                                        {
                                            tran.Rollback();
                                        }
                                        catch { }

                                        throw;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Design Specification",
                    "EditDesignSpecificationMaster",
                    ex,
                    "ID: " + ilist.DesignSpecificationID +
                    ", Specification: " + ilist.DesignSpecification
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 409;
                    comman.Message =
                        "This Design Specification already exists. Please enter a different name.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message =
                        "Database error occurred while updating Design Specification.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Design Specification",
                    "EditDesignSpecificationMaster",
                    ex,
                    "ID: " + ilist.DesignSpecificationID +
                    ", Specification: " + ilist.DesignSpecification
                );

                comman.Code = 500;
                comman.Message =
                    "Unable to update Design Specification. Please try again.";
            }

            Context.Response.ContentType = "application/json";
            Context.Response.Write(js.Serialize(comman));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteDesignSpecificationMaster()
        {
            CommanResponse comman = new CommanResponse();

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            try
            {
                string idValue = HttpContext.Current.Request.Params["DesignSpecificationID"];

                if (!Int32.TryParse(idValue, out int specificationId) ||
                    specificationId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Design Specification ID.";

                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction(
                        IsolationLevel.Serializable))
                    {
                        try
                        {
                            // Check whether record exists
                            string checkRecordSql = @"
                        SELECT DesignSpecificationID
                        FROM DesignSpecificationMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE DesignSpecificationID = @DesignSpecificationID";

                            using (SqlCommand cmd = new SqlCommand(
                                checkRecordSql, con, tran))
                            {
                                cmd.Parameters.Add("@DesignSpecificationID", SqlDbType.Int)
                                    .Value = specificationId;

                                if (cmd.ExecuteScalar() == null)
                                {
                                    tran.Rollback();

                                    comman.Code = 404;
                                    comman.Message = "Design Specification record not found.";

                                    Context.Response.Write(js.Serialize(comman));
                                    return;
                                }
                            }

                            // Check actual dependency in DesignEntryWeftData
                            string dependencySql = @"
                        SELECT TOP 1
                            D.DesignEntryWeftID,
                            D.DesignEntryFormID,
                            E.DesignNo
                        FROM dbo.DesignEntryWeftData D WITH (UPDLOCK, HOLDLOCK)
                        LEFT JOIN dbo.DesignEntryFormMaster E
                            ON E.DesignEntryFormID = D.DesignEntryFormID
                        WHERE D.DesignSpecificationID = @DesignSpecificationID
                        ORDER BY D.DesignEntryWeftID";

                            using (SqlCommand cmd = new SqlCommand(
                                dependencySql, con, tran))
                            {
                                cmd.Parameters.Add("@DesignSpecificationID", SqlDbType.Int)
                                    .Value = specificationId;

                                using (SqlDataReader reader = cmd.ExecuteReader())
                                {
                                    if (reader.Read())
                                    {
                                        string designNo = reader["DesignNo"] == DBNull.Value
                                            ? "N/A"
                                            : reader["DesignNo"].ToString();

                                        long weftRecordID = Convert.ToInt64(
                                            reader["DesignEntryWeftID"]);

                                        reader.Close();

                                        tran.Rollback();

                                        comman.Code = 409;
                                        comman.Message =
                                            "Cannot delete this Design Specification because it is already used in Design Entry.";
                                        Context.Response.Write(js.Serialize(comman));
                                        return;
                                    }
                                }
                            }

                            // Fetch old value for audit
                            object oldValue = AuditLogHelper.FetchOldValue(
                                "DesignSpecificationMaster",
                                specificationId.ToString(),
                                con
                            );

                            // Delete record
                            string deleteSql = @"
                        DELETE FROM DesignSpecificationMaster
                        WHERE DesignSpecificationID = @DesignSpecificationID";

                            int rowsAffected;

                            using (SqlCommand cmd = new SqlCommand(
                                deleteSql, con, tran))
                            {
                                cmd.Parameters.Add("@DesignSpecificationID", SqlDbType.Int)
                                    .Value = specificationId;

                                rowsAffected = cmd.ExecuteNonQuery();
                            }

                            if (rowsAffected > 0)
                            {
                                AuditLogHelper.LogTransactional(
                                    conn: con,
                                    tran: tran,
                                    module: "Design Specification",
                                    action: "DELETE",
                                    tableName: "DesignSpecificationMaster",
                                    recordId: specificationId.ToString(),
                                    description: $"Deleted Design Specification ID #{specificationId}",
                                    oldValue: oldValue
                                );

                                tran.Commit();

                                comman.Code = 200;
                                comman.Message = "Record Deleted Successfully.";
                            }
                            else
                            {
                                tran.Rollback();

                                comman.Code = 410;
                                comman.Message = "Failed to delete record.";
                            }
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Design Specification",
                    "DeleteDesignSpecificationMaster",
                    ex,
                    "Design Specification deletion failed."
                );

                comman.Code = 405;
                comman.Message =
                    "Problem has been occurred while deleting your data.";
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "DeleteDesignSpecificationMaster Error: " + ex
                );

                comman.Code = 410;
                comman.Message = "Unable to delete Design Specification record.";
            }

            Context.Response.Write(js.Serialize(comman));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_DesignSpecificationQueue()
        {
            DesignSpecificationMasterResponse comman =
                new DesignSpecificationMasterResponse();

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            try
            {
                string postQueue = HttpContext.Current.Request.Params["PostQueue"];

                if (string.IsNullOrWhiteSpace(postQueue))
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue data.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string[] queueItems = postQueue.Split('|');

                if (queueItems.Length != 2)
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue format.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string[] firstItem = queueItems[0].Split(',');
                string[] secondItem = queueItems[1].Split(',');

                int firstId, firstPosition, secondId, secondPosition;

                if (firstItem.Length != 2 ||
                    secondItem.Length != 2 ||
                    !Int32.TryParse(firstItem[0].Trim(), out firstId) ||
                    !Int32.TryParse(firstItem[1].Trim(), out firstPosition) ||
                    !Int32.TryParse(secondItem[0].Trim(), out secondId) ||
                    !Int32.TryParse(secondItem[1].Trim(), out secondPosition) ||
                    firstId <= 0 ||
                    secondId <= 0 ||
                    firstId == secondId)
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue values.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection conn = new SqlConnection(cs))
                {
                    conn.Open();

                    using (SqlTransaction tran = conn.BeginTransaction())
                    {
                        try
                        {
                            string updateQuery = @"
                        UPDATE DesignSpecificationMaster
                        SET Position = @Position
                        WHERE DesignSpecificationID = @DesignSpecificationID";

                            int firstUpdated;
                            int secondUpdated;

                            using (SqlCommand cmd = new SqlCommand(updateQuery, conn, tran))
                            {
                                cmd.Parameters.Add("@Position", SqlDbType.Int);
                                cmd.Parameters.Add("@DesignSpecificationID", SqlDbType.Int);

                                cmd.Parameters["@Position"].Value = secondPosition;
                                cmd.Parameters["@DesignSpecificationID"].Value = firstId;

                                firstUpdated = cmd.ExecuteNonQuery();

                                cmd.Parameters["@Position"].Value = firstPosition;
                                cmd.Parameters["@DesignSpecificationID"].Value = secondId;

                                secondUpdated = cmd.ExecuteNonQuery();
                            }

                            if (firstUpdated > 0 && secondUpdated > 0)
                            {
                                tran.Commit();

                                comman.Code = 1;
                                comman.Message = "Success";
                            }
                            else
                            {
                                tran.Rollback();

                                comman.Code = 0;
                                comman.Message = "Error";
                            }
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "UpdateTbl_DesignSpecificationQueue Error: " + ex
                );

                comman.Code = 0;
                comman.Message = "Error";
            }

            Context.Response.Write(js.Serialize(comman));
        }

