        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertColorGroupMaster()
        {
            CommanResponse comman = new CommanResponse();

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            string colorGroup = null;
            int userAccountId = 0;
            int companyId = 0;
      
            try
            {
                var request = HttpContext.Current?.Request;

                if (request == null)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid request.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                colorGroup = (request.Params["ColorGroup"] ?? "").Trim();

                if (string.IsNullOrWhiteSpace(colorGroup))
                {
                    comman.Code = 400;
                    comman.Message = "Please enter Color Group.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                if (!Int32.TryParse(request.Params["IsActive"], out int isActive) ||
                    (isActive != 0 && isActive != 1))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid active status.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string userCookie = request.Cookies["UserIDs"]?.Value;
                string companyCookie = request.Cookies["CompanyID"]?.Value;

                if (string.IsNullOrWhiteSpace(userCookie) ||
                    string.IsNullOrWhiteSpace(companyCookie))
                {
                    comman.Code = 400;
                    comman.Message = "User or Company information is missing.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                userCookie = userCookie.Contains("=")
                    ? userCookie.Substring(userCookie.LastIndexOf('=') + 1)
                    : userCookie;

                companyCookie = companyCookie.Contains("=")
                    ? companyCookie.Substring(companyCookie.LastIndexOf('=') + 1)
                    : companyCookie;

                if (!Int32.TryParse(userCookie, out userAccountId) ||
                    !Int32.TryParse(companyCookie, out companyId) ||
                    userAccountId <= 0 || companyId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid User or Company information.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                colorGroup = colorGroup.ToUpperInvariant();

                DateTime dateTimeIndian = TimeZoneInfo.ConvertTimeFromUtc(
                    DateTime.UtcNow,
                    India_Standard_Time
                );

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]?.ConnectionString;

                if (string.IsNullOrWhiteSpace(cs))
                {
                    throw new Exception("Database connection string is missing.");
                }

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // Duplicate check: Same Company
                            string duplicateQuery = @"
                        SELECT COUNT(1)
                        FROM ColorGroupMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE UPPER(LTRIM(RTRIM(ColorGroup))) = @ColorGroup
                          AND CompanyId = @CompanyId";

                            using (SqlCommand duplicateCmd =
                                new SqlCommand(duplicateQuery, con, tran))
                            {
                                duplicateCmd.Parameters.Add("@ColorGroup", SqlDbType.NVarChar)
                                    .Value = colorGroup;

                                duplicateCmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                int duplicateCount = Convert.ToInt32(
                                    duplicateCmd.ExecuteScalar()
                                );

                                if (duplicateCount > 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 405;
                                    comman.Message = "This Color Group already exists.";

                                    Context.Response.Write(js.Serialize(comman));
                                    return;
                                }
                            }

                            // Generate next Position: Same Company
                            int position;
                            
                            string positionQuery = @"
                        SELECT ISNULL(MAX(Position), 0) + 1
                        FROM ColorGroupMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId";

                            using (SqlCommand positionCmd =
                                new SqlCommand(positionQuery, con, tran))
                            {
                                positionCmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                position = Convert.ToInt32(
                                    positionCmd.ExecuteScalar()
                                );
                            }

                            // Insert Color Group
                            string insertQuery = @"
                        INSERT INTO ColorGroupMaster
                        (
                            DateAndTime,
                            ColorGroup,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        )
                        VALUES
                        (
                            @DateAndTime,
                            @ColorGroup,
                            @IsActive,
                            @Position,
                            @CompanyId,
                            @UserAccountId
                        );

                        SELECT CAST(SCOPE_IDENTITY() AS INT);";

                            int newId;

                            using (SqlCommand cmd = new SqlCommand(insertQuery, con, tran))
                            {
                                cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime)
                                    .Value = dateTimeIndian;

                                cmd.Parameters.Add("@ColorGroup", SqlDbType.NVarChar)
                                    .Value = colorGroup;

                                cmd.Parameters.Add("@IsActive", SqlDbType.Int)
                                    .Value = isActive;

                                cmd.Parameters.Add("@Position", SqlDbType.Int)
                                    .Value = position;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                    .Value = userAccountId;

                                newId = Convert.ToInt32(cmd.ExecuteScalar());
                            }

                            ColorGroupMaster newRecord = new ColorGroupMaster
                            {
                                ColorGroup = colorGroup,
                                IsActive = isActive,
                                Position = position,
                                CompanyId = companyId,
                                UserAccountId = userAccountId
                            };

                            // Transactional Audit Log
                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Color Group",
                                action: "CREATE",
                                tableName: "ColorGroupMaster",
                                recordId: newId.ToString(),
                                description: $"Created Color Group '{colorGroup}'",
                                newValue: newRecord,
                                customUserId: userAccountId
                            );

                            tran.Commit();

                            comman.Code = 201;
                            comman.Message = "Color Group has been saved successfully.";
                        }
                        catch
                        {
                            try
                            {
                                if (tran.Connection != null)
                                    tran.Rollback();
                            }
                            catch { }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Color Group",
                    "insertColorGroupMaster",
                    ex,
                    $"Group: {colorGroup}, CompanyId: {companyId}"
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "This Color Group already exists.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem occurred while saving Color Group.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertColorGroupMaster Error: " + ex
                );

                comman.Code = 410;
                comman.Message = "Problem occurred while saving Color Group.";
            }

            Context.Response.Write(js.Serialize(comman));
        }


