        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getColorGroupMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<ColorGroupMaster> listUser = new List<ColorGroupMaster>();
            ColorGroupMasterResponse response = new ColorGroupMasterResponse();

            try
            {
                var request = HttpContext.Current.Request;

                string searchColorGroup =
                    (request.Params["SearchColorGroup"] ?? "").Trim();

                if (!Int32.TryParse(request.Params["startFrom"], out int startFrom) ||
                    startFrom < 0)
                {
                    startFrom = 0;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                string sql = @"
            SELECT *
            FROM ColorGroupMaster
            WHERE (@SearchColorGroup = ''
                   OR ColorGroup LIKE @SearchPattern)
            ORDER BY Position DESC
            OFFSET @StartFrom ROWS
            FETCH NEXT 10 ROWS ONLY";

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.Parameters.Add("@SearchColorGroup", SqlDbType.NVarChar)
                        .Value = searchColorGroup;

                    cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar)
                        .Value = "%" + searchColorGroup + "%";

                    cmd.Parameters.Add("@StartFrom", SqlDbType.Int)
                        .Value = startFrom;

                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            ColorGroupMaster condition = new ColorGroupMaster();

                            condition.ColorGroupID =
                                Convert.ToInt32(rdr["ColorGroupID"]);

                            condition.IsActive =
                                Convert.ToInt32(rdr["IsActive"]);

                            condition.Position =
                                Convert.ToInt32(rdr["Position"]);

                            condition.DateandTime =
                                Convert.ToDateTime(rdr["DateandTime"]);

                            condition.DateandTimes =
                                condition.DateandTime.ToString("dd-MM-yyyy");

                            condition.ColorGroup =
                                rdr["ColorGroup"].ToString().ToUpper();

                            listUser.Add(condition);
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listColorGroupMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getColorGroupMaster Error: " + ex
                );

                response.Code = 0;
                response.Message = "Error while fetching Color Group records.";
                response.listColorGroupMaster = listUser;
            }

            Context.Response.Write(js.Serialize(response));
        }

