        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteColorGroupMaster()
        {
            CommanResponse comman = new CommanResponse();

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            int colorGroupId = 0;
            int userAccountId = 0;
            int companyId = 0;

            try
            {
                var request = HttpContext.Current?.Request;

                if (request == null)
                    throw new Exception("Invalid request.");

                if (!Int32.TryParse(request.Params["ColorGroupID"], out colorGroupId) ||
                    colorGroupId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Color Group ID.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string userCookie = request.Cookies["UserIDs"]?.Value;
                string companyCookie = request.Cookies["CompanyID"]?.Value;

                if (string.IsNullOrWhiteSpace(userCookie) ||
                    string.IsNullOrWhiteSpace(companyCookie))
                {
                    comman.Code = 400;
                    comman.Message = "User or Company information is missing.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                userCookie = userCookie.Contains("=")
                    ? userCookie.Substring(userCookie.LastIndexOf('=') + 1)
                    : userCookie;

                companyCookie = companyCookie.Contains("=")
                    ? companyCookie.Substring(companyCookie.LastIndexOf('=') + 1)
                    : companyCookie;

                if (!Int32.TryParse(userCookie, out userAccountId) ||
                    !Int32.TryParse(companyCookie, out companyId) ||
                    userAccountId <= 0 || companyId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid User or Company information.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]?.ConnectionString;

                if (string.IsNullOrWhiteSpace(cs))
                    throw new Exception("Database connection string is missing.");

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // Verify Color Group belongs to current company
                            string checkRecordQuery = @"
                        SELECT COUNT(1)
                        FROM ColorGroupMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE ColorGroupID = @ColorGroupID
                          AND CompanyId = @CompanyId";

                            using (SqlCommand cmd =
                                new SqlCommand(checkRecordQuery, con, tran))
                            {
                                cmd.Parameters.Add("@ColorGroupID", SqlDbType.Int)
                                    .Value = colorGroupId;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                if (Convert.ToInt32(cmd.ExecuteScalar()) == 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 404;
                                    comman.Message = "Color Group record not found.";

                                    Context.Response.Write(js.Serialize(comman));
                                    return;
                                }
                            }

                            // Dependency Check
                            string dependencyQuery = @"
                        SELECT COUNT(1)
                        FROM DesignColorMatchingDetails WITH (UPDLOCK, HOLDLOCK)
                        WHERE ColorGroupID = @ColorGroupID";

                            int dependencyCount;

                            using (SqlCommand cmd =
                                new SqlCommand(dependencyQuery, con, tran))
                            {
                                cmd.Parameters.Add("@ColorGroupID", SqlDbType.Int)
                                    .Value = colorGroupId;

                                dependencyCount = Convert.ToInt32(cmd.ExecuteScalar());
                            }

                            if (dependencyCount > 0)
                            {
                                tran.Rollback();

                                comman.Code = 400;
                                comman.Message =
                                    "Color Group cannot be deleted because it is already used in DesignColorMatchingDetails (" +
                                    dependencyCount +
                                    " records). Please remove or change these references first.";

                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }

                            object oldValue = AuditLogHelper.FetchOldValue(
                                "ColorGroupMaster",
                                colorGroupId.ToString(),
                                con
                            );

                            string deleteQuery = @"
                        DELETE FROM ColorGroupMaster
                        WHERE ColorGroupID = @ColorGroupID
                          AND CompanyId = @CompanyId";

                            int rowsAffected;

                            using (SqlCommand cmd =
                                new SqlCommand(deleteQuery, con, tran))
                            {
                                cmd.Parameters.Add("@ColorGroupID", SqlDbType.Int)
                                    .Value = colorGroupId;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                rowsAffected = cmd.ExecuteNonQuery();
                            }

                            if (rowsAffected <= 0)
                            {
                                tran.Rollback();

                                comman.Code = 404;
                                comman.Message = "Color Group record not found.";

                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }

                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Color Group",
                                action: "DELETE",
                                tableName: "ColorGroupMaster",
                                recordId: colorGroupId.ToString(),
                                description: $"Deleted Color Group ID #{colorGroupId}",
                                oldValue: oldValue,
                                customUserId: userAccountId
                            );

                            tran.Commit();

                            comman.Code = 200;
                            comman.Message = "Color Group deleted successfully.";
                        }
                        catch
                        {
                            try
                            {
                                if (tran.Connection != null)
                                    tran.Rollback();
                            }
                            catch { }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Color Group",
                    "DeleteColorGroupMaster",
                    ex,
                    $"ColorGroupID: {colorGroupId}, CompanyId: {companyId}"
                );

                if (ex.Number == 547)
                {
                    comman.Code = 400;
                    comman.Message =
                        "Color Group cannot be deleted because it is referenced in another record.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem occurred while deleting Color Group.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "DeleteColorGroupMaster Error: " + ex
                );

                comman.Code = 410;
                comman.Message = "Unable to delete Color Group record.";
            }

            Context.Response.Write(js.Serialize(comman));
        }



        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_ColorGroupQueue()
        {
            ColorGroupMasterResponse comman = new ColorGroupMasterResponse();

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            try
            {
                string postQueue =
                    HttpContext.Current.Request.Params["PostQueue"];

                if (string.IsNullOrWhiteSpace(postQueue))
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue data.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string[] queueItems = postQueue.Split('|');

                if (queueItems.Length != 2)
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue format.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string[] firstItem = queueItems[0].Split(',');
                string[] secondItem = queueItems[1].Split(',');

                int firstId, firstPosition, secondId, secondPosition;

                if (firstItem.Length != 2 ||
                    secondItem.Length != 2 ||
                    !Int32.TryParse(firstItem[0].Trim(), out firstId) ||
                    !Int32.TryParse(firstItem[1].Trim(), out firstPosition) ||
                    !Int32.TryParse(secondItem[0].Trim(), out secondId) ||
                    !Int32.TryParse(secondItem[1].Trim(), out secondPosition) ||
                    firstId <= 0 ||
                    secondId <= 0 ||
                    firstId == secondId)
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue values.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection conn = new SqlConnection(cs))
                {
                    conn.Open();

                    using (SqlTransaction tran = conn.BeginTransaction())
                    {
                        try
                        {
                            string updateQuery = @"
                        UPDATE ColorGroupMaster
                        SET Position = @Position
                        WHERE ColorGroupID = @ColorGroupID";

                            int firstUpdated;
                            int secondUpdated;

                            using (SqlCommand cmd =
                                new SqlCommand(updateQuery, conn, tran))
                            {
                                cmd.Parameters.Add("@Position", SqlDbType.Int);
                                cmd.Parameters.Add("@ColorGroupID", SqlDbType.Int);

                                cmd.Parameters["@Position"].Value = secondPosition;
                                cmd.Parameters["@ColorGroupID"].Value = firstId;

                                firstUpdated = cmd.ExecuteNonQuery();

                                cmd.Parameters["@Position"].Value = firstPosition;
                                cmd.Parameters["@ColorGroupID"].Value = secondId;

                                secondUpdated = cmd.ExecuteNonQuery();
                            }

                            if (firstUpdated > 0 && secondUpdated > 0)
                            {
                                tran.Commit();

                                comman.Code = 1;
                                comman.Message = "Success";
                            }
                            else
                            {
                                tran.Rollback();

                                comman.Code = 0;
                                comman.Message = "Error";
                            }
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "UpdateTbl_ColorGroupQueue Error: " + ex
                );

                comman.Code = 0;
                comman.Message = "Error";
            }

            Context.Response.Write(js.Serialize(comman));
        }

