        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertMaterialMaster()
        {
            CommanResponse comman = new CommanResponse();

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            MaterialMaster ilist = new MaterialMaster();

            try
            {
                var request = HttpContext.Current.Request;

                ilist.Material = (request.Params["Material"] ?? "").Trim();

                int isActive;
                int userAccountId;
                int companyId;

                if (string.IsNullOrWhiteSpace(ilist.Material) ||
                    !Int32.TryParse(request.Params["IsActive"], out isActive) ||
                    !Int32.TryParse(request.Cookies["UserIDs"]?.Value, out userAccountId) ||
                    !Int32.TryParse(request.Cookies["CompanyID"]?.Value, out companyId) ||
                    userAccountId <= 0 ||
                    companyId <= 0)
                {
                    comman.Code = 410;
                    comman.Message = "Invalid input data.";
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

                ilist.IsActive = isActive;
                ilist.UserAccountId = userAccountId;
                ilist.CompanyId = companyId;

                DateTime dateTimeIndian =
                    TimeZoneInfo.ConvertTimeFromUtc(
                        DateTime.UtcNow,
                        India_Standard_Time
                    );

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            int position;

                            using (SqlCommand positionCmd = new SqlCommand(
                                @"SELECT ISNULL(MAX(Position), 0) + 1
                          FROM MaterialMaster WITH (UPDLOCK, HOLDLOCK)",
                                con,
                                tran))
                            {
                                position = Convert.ToInt32(
                                    positionCmd.ExecuteScalar()
                                );
                            }

                            string query = @"
                        INSERT INTO MaterialMaster
                        (
                            DateAndTime,
                            Material,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        )
                        VALUES
                        (
                            @DateAndTime,
                            @Material,
                            @IsActive,
                            @Position,
                            @CompanyId,
                            @UserAccountId
                        )";

                            int affectedRows;

                            using (SqlCommand cmd =
                                new SqlCommand(query, con, tran))
                            {
                                cmd.Parameters.Add(
                                    "@DateAndTime",
                                    SqlDbType.DateTime
                                ).Value = dateTimeIndian;

                                cmd.Parameters.Add(
                                    "@Material",
                                    SqlDbType.NVarChar
                                ).Value = ilist.Material;

                                cmd.Parameters.Add(
                                    "@IsActive",
                                    SqlDbType.Int
                                ).Value = ilist.IsActive;

                                cmd.Parameters.Add(
                                    "@Position",
                                    SqlDbType.Int
                                ).Value = position;

                                cmd.Parameters.Add(
                                    "@CompanyId",
                                    SqlDbType.Int
                                ).Value = ilist.CompanyId;

                                cmd.Parameters.Add(
                                    "@UserAccountId",
                                    SqlDbType.Int
                                ).Value = ilist.UserAccountId;

                                affectedRows = cmd.ExecuteNonQuery();
                            }

                            if (affectedRows > 0)
                            {
                                tran.Commit();

                                AuditLogHelper.Log(
                                    module: "Material Master",
                                    action: "CREATE",
                                    tableName: "MaterialMaster",
                                    description: $"Created Material '{ilist.Material}'",
                                    newValue: ilist
                                );

                                comman.Code = 201;
                                comman.Message =
                                    "Material has been saved successfully.";
                            }
                            else
                            {
                                tran.Rollback();

                                comman.Code = 410;
                                comman.Message =
                                    "Problem has been occurred while submitting your data.";
                            }
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Material Master",
                    "insertMaterialMaster",
                    ex,
                    $"Material: {ilist.Material}"
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message =
                        "Problem has been occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "insertMaterialMaster Error: " + ex
                );

                comman.Code = 410;
                comman.Message =
                    "Problem has been occurred while submitting your data.";
            }

            Context.Response.Write(js.Serialize(comman));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getMaterialMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<MaterialMaster> listUser = new List<MaterialMaster>();
            MaterialMasterResponse response = new MaterialMasterResponse();

            try
            {
                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(@"
            SELECT
                MaterialID,
                IsActive,
                Position,
                DateandTime,
                Material
            FROM MaterialMaster
            ORDER BY Position, MaterialID", con))
                {
                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            MaterialMaster condition = new MaterialMaster();

                            condition.MaterialID = Convert.ToInt32(rdr["MaterialID"]);

                            condition.IsActive = rdr["IsActive"] == DBNull.Value
                                ? 0
                                : Convert.ToInt32(rdr["IsActive"]);

                            condition.Position = rdr["Position"] == DBNull.Value
                                ? 0
                                : Convert.ToInt32(rdr["Position"]);

                            if (rdr["DateandTime"] != DBNull.Value)
                            {
                                condition.DateandTime =
                                    Convert.ToDateTime(rdr["DateandTime"]);

                                condition.DateandTimes =
                                    condition.DateandTime.ToString("dd-MM-yyyy");
                            }

                            condition.Material =
                                rdr["Material"] == DBNull.Value
                                    ? string.Empty
                                    : rdr["Material"].ToString();

                            listUser.Add(condition);
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
                response.listMaterialMaster = listUser;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Trace.WriteLine(
                    "getMaterialMaster Error: " + ex
                );

                response.Code = 0;
                response.Message = "Problem occurred while retrieving Material Master data.";
                response.listMaterialMaster = listUser;
            }

            Context.Response.Write(js.Serialize(response));
        }

