        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditMaterialMaster()
        {
            CommanResponse comman = new CommanResponse();

            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            MaterialMaster ilist = new MaterialMaster();

            try
            {
                var request = HttpContext.Current.Request;

                int materialId;
                int isActive;
                int userId;
                int companyId;

                string material = request.Params["Material"];

                if (!Int32.TryParse(request.Params["MaterialID"], out materialId) ||
                    materialId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Material ID.";
                }
                else if (String.IsNullOrWhiteSpace(material))
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Material.";
                }
                else if (!Int32.TryParse(request.Params["IsActive"], out isActive))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Active Status.";
                }
                else if (!Int32.TryParse(
                    Context.Request.Cookies["UserIDs"]?.Value, out userId) ||
                    !Int32.TryParse(
                    Context.Request.Cookies["CompanyID"]?.Value, out companyId))
                {
                    comman.Code = 400;
                    comman.Message = "Invalid user or company information.";
                }
                else
                {
                    ilist.MaterialID = materialId;
                    ilist.Material = material.Trim();
                    ilist.IsActive = isActive;
                    ilist.UserAccountId = userId;
                    ilist.CompanyId = companyId;

                    string cs = ConfigurationManager
                        .ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        con.Open();

                        using (SqlTransaction tran =
                            con.BeginTransaction(IsolationLevel.ReadCommitted))
                        {
                            try
                            {
                                object oldValue = AuditLogHelper.FetchOldValue(
                                    "MaterialMaster",
                                    materialId.ToString(),
                                    con
                                );

                                if (oldValue == null || oldValue == DBNull.Value)
                                {
                                    tran.Rollback();

                                    comman.Code = 404;
                                    comman.Message = "Material not found.";
                                }
                                else
                                {
                                    int rowsAffected;

                                    using (SqlCommand cmd = new SqlCommand(@"
                                UPDATE MaterialMaster
                                SET
                                    Material = @Material,
                                    IsActive = @IsActive,
                                    UserAccountId = @UserAccountId,
                                    CompanyId = @CompanyId
                                WHERE MaterialID = @MaterialID",
                                        con, tran))
                                    {
                                        cmd.Parameters.Add("@Material",
                                            SqlDbType.NVarChar).Value = ilist.Material;

                                        cmd.Parameters.Add("@IsActive",
                                            SqlDbType.Int).Value = ilist.IsActive;

                                        cmd.Parameters.Add("@UserAccountId",
                                            SqlDbType.Int).Value = ilist.UserAccountId;

                                        cmd.Parameters.Add("@CompanyId",
                                            SqlDbType.Int).Value = ilist.CompanyId;

                                        cmd.Parameters.Add("@MaterialID",
                                            SqlDbType.Int).Value = ilist.MaterialID;

                                        rowsAffected = cmd.ExecuteNonQuery();
                                    }

                                    if (rowsAffected > 0)
                                    {
                                        AuditLogHelper.LogTransactional(
                                            conn: con,
                                            tran: tran,
                                            module: "Material Master",
                                            action: "UPDATE",
                                            tableName: "MaterialMaster",
                                            recordId: ilist.MaterialID.ToString(),
                                            description: $"Updated Material #{ilist.MaterialID} '{ilist.Material}'",
                                            oldValue: oldValue,
                                            newValue: ilist,
                                            customUserId: ilist.UserAccountId
                                        );

                                        tran.Commit();

                                        comman.Code = 201;
                                        comman.Message =
                                            "Material has been updated successfully.";
                                    }
                                    else
                                    {
                                        tran.Rollback();

                                        comman.Code = 404;
                                        comman.Message = "Material not found.";
                                    }
                                }
                            }
                            catch
                            {
                                try
                                {
                                    tran.Rollback();
                                }
                                catch
                                {
                                    // Transaction may already be rolled back.
                                }

                                throw;
                            }
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Material Master",
                    "EditMaterialMaster",
                    ex,
                    $"ID: {ilist.MaterialID}, Material: {ilist.Material}"
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message =
                        "Problem has been occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Material Master",
                    "EditMaterialMaster",
                    ex,
                    $"ID: {ilist.MaterialID}, Material: {ilist.Material}"
                );

                comman.Code = 500;
                comman.Message =
                    "Problem has been occurred while submitting your data.";
            }

            Context.Response.Write(js.Serialize(comman));
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteMaterialMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse comman = new CommanResponse();

            try
            {
                int materialId;

                if (!Int32.TryParse(
                    HttpContext.Current.Request.Params["MaterialID"],
                    out materialId) || materialId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Material ID.";
                }
                else
                {
                    string cs = ConfigurationManager
                        .ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        con.Open();

                        using (SqlTransaction tran =
                            con.BeginTransaction(IsolationLevel.ReadCommitted))
                        {
                            try
                            {
                                object oldValue = AuditLogHelper.FetchOldValue(
                                    "MaterialMaster",
                                    materialId.ToString(),
                                    con
                                );

                                if (oldValue == null || oldValue == DBNull.Value)
                                {
                                    tran.Rollback();

                                    comman.Code = 404;
                                    comman.Message = "Material not found.";
                                }
                                else
                                {
                                    int rowsAffected;

                                    using (SqlCommand cmd = new SqlCommand(@"
                                DELETE FROM MaterialMaster
                                WHERE MaterialID = @MaterialID",
                                        con, tran))
                                    {
                                        cmd.Parameters.Add(
                                            "@MaterialID",
                                            SqlDbType.Int
                                        ).Value = materialId;

                                        rowsAffected = cmd.ExecuteNonQuery();
                                    }

                                    if (rowsAffected > 0)
                                    {
                                        AuditLogHelper.LogTransactional(
                                            conn: con,
                                            tran: tran,
                                            module: "Material Master",
                                            action: "DELETE",
                                            tableName: "MaterialMaster",
                                            recordId: materialId.ToString(),
                                            description: $"Deleted Material ID #{materialId}",
                                            oldValue: oldValue
                                        );

                                        tran.Commit();

                                        comman.Code = 200;
                                        comman.Message =
                                            "Record Deleted Successfully.";
                                    }
                                    else
                                    {
                                        tran.Rollback();

                                        comman.Code = 404;
                                        comman.Message = "Material not found.";
                                    }
                                }
                            }
                            catch
                            {
                                try
                                {
                                    tran.Rollback();
                                }
                                catch
                                {
                                    // Transaction may already be rolled back.
                                }

                                throw;
                            }
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Material Master",
                    "DeleteMaterialMaster",
                    ex,
                    "MaterialID: " +
                    HttpContext.Current.Request.Params["MaterialID"]
                );

                if (ex.Number == 547)
                {
                    comman.Code = 405;
                    comman.Message =
                        "This Material is already used in other records. Cannot delete.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message =
                        "Problem occurred while deleting your data.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Material Master",
                    "DeleteMaterialMaster",
                    ex,
                    "MaterialID: " +
                    HttpContext.Current.Request.Params["MaterialID"]
                );

                comman.Code = 500;
                comman.Message =
                    "Problem occurred while deleting your data.";
            }

            Context.Response.Write(js.Serialize(comman));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_MaterialQueue()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            MaterialMasterResponse response = new MaterialMasterResponse();

            try
            {
                string postQueue = HttpContext.Current.Request.Params["PostQueue"];

                string[] items = (postQueue ?? "").Split('|');

                if (items.Length != 2)
                {
                    response.Code = 400;
                    response.Message = "Invalid queue data.";
                }
                else
                {
                    string[] first = items[0].Split(',');
                    string[] second = items[1].Split(',');

                    int firstId, firstPosition, secondId, secondPosition;

                    if (first.Length != 2 || second.Length != 2 ||
                        !Int32.TryParse(first[0], out firstId) ||
                        !Int32.TryParse(first[1], out firstPosition) ||
                        !Int32.TryParse(second[0], out secondId) ||
                        !Int32.TryParse(second[1], out secondPosition) ||
                        firstId <= 0 || secondId <= 0 || firstId == secondId ||
                        firstPosition < 0 || secondPosition < 0)
                    {
                        response.Code = 400;
                        response.Message = "Invalid queue values.";
                    }
                    else
                    {
                        string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                        using (SqlConnection conn = new SqlConnection(cs))
                        {
                            conn.Open();

                            using (SqlTransaction tran = conn.BeginTransaction())
                            {
                                try
                                {
                                    int firstRows;
                                    using (SqlCommand cmd = new SqlCommand(@"
                                UPDATE MaterialMaster
                                SET Position = @Position
                                WHERE MaterialID = @MaterialID", conn, tran))
                                    {
                                        cmd.Parameters.Add("@Position", SqlDbType.Int).Value = secondPosition;
                                        cmd.Parameters.Add("@MaterialID", SqlDbType.Int).Value = firstId;
                                        firstRows = cmd.ExecuteNonQuery();
                                    }

                                    int secondRows = 0;

                                    if (firstRows > 0)
                                    {
                                        using (SqlCommand cmd = new SqlCommand(@"
                                    UPDATE MaterialMaster
                                    SET Position = @Position
                                    WHERE MaterialID = @MaterialID", conn, tran))
                                        {
                                            cmd.Parameters.Add("@Position", SqlDbType.Int).Value = firstPosition;
                                            cmd.Parameters.Add("@MaterialID", SqlDbType.Int).Value = secondId;
                                            secondRows = cmd.ExecuteNonQuery();
                                        }
                                    }

                                    if (firstRows > 0 && secondRows > 0)
                                    {
                                        tran.Commit();
                                        response.Code = 1;
                                        response.Message = "Success";
                                    }
                                    else
                                    {
                                        tran.Rollback();
                                        response.Code = 0;
                                        response.Message = "Unable to update queue positions.";
                                    }
                                }
                                catch
                                {
                                    try { tran.Rollback(); } catch { }
                                    throw;
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Material Master", "UpdateTbl_MaterialQueue", ex);
                response.Code = 0;
                response.Message = "Problem occurred while updating queue.";
            }

            Context.Response.Write(js.Serialize(response));
        }

