        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertDesignCategoryMaster()
        {
            CommanResponse response = new CommanResponse();
            DesignCategoryMaster ilist = new DesignCategoryMaster();

            int isActive = 0;
            int userId = 0;
            int companyId = 0;

            try
            {
                var request = HttpContext.Current.Request;

                ilist.DesignCategory =
                    (request.Params["DesignCategory"] ?? "").Trim().ToUpperInvariant();

                // 1. Validate input
                if (string.IsNullOrWhiteSpace(ilist.DesignCategory) ||
                    !int.TryParse(request.Params["IsActive"], out isActive) ||
                    (isActive != 0 && isActive != 1))
                {
                    response.Code = 400;
                    response.Message = "Please enter valid Design Category details.";
                    WriteJsonResponse(response);
                    return;
                }

                // 2. Cookie validation - Existing project cookie format
                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null ||
                    string.IsNullOrEmpty(userCookie.Value) ||
                    string.IsNullOrEmpty(companyCookie.Value))
                {
                    response.Code = 401;
                    response.Message = "Invalid user or company session.";
                    WriteJsonResponse(response);
                    return;
                }

                string[] userParts = userCookie.Value.Split('=');
                string[] companyParts = companyCookie.Value.Split('=');

                if (userParts.Length < 2 ||
                    companyParts.Length < 2 ||
                    !int.TryParse(userParts[1], out userId) ||
                    !int.TryParse(companyParts[1], out companyId))
                {
                    response.Code = 401;
                    response.Message = "Invalid user or company session.";
                    WriteJsonResponse(response);
                    return;
                }

                ilist.IsActive = isActive;
                ilist.UserAccountId = userId;
                ilist.CompanyId = companyId;

                DateTime dateTimeIndian =
                    TimeZoneInfo.ConvertTimeFromUtc(
                        DateTime.UtcNow,
                        India_Standard_Time
                    );

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // 3. Duplicate check - Same company
                            using (SqlCommand cmdCheck = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignCategoryMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND UPPER(LTRIM(RTRIM(DesignCategory))) = @DesignCategory",
                                con, tran))
                            {
                                cmdCheck.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                cmdCheck.Parameters.Add("@DesignCategory", SqlDbType.NVarChar)
                                    .Value = ilist.DesignCategory;

                                if (Convert.ToInt32(cmdCheck.ExecuteScalar()) > 0)
                                {
                                    tran.Rollback();

                                    AuditLogHelper.LogDuplicateError(
                                        module: "Design Category",
                                        tableName: "DesignCategoryMaster",
                                        recordId: null,
                                        description: $"Duplicate Design Category: {ilist.DesignCategory}",
                                        errorMessage: "This Design Category already exists.",
                                        requestData: ilist
                                    );

                                    response.Code = 409;
                                    response.Message = "This Design Category already exists.";

                                    WriteJsonResponse(response);
                                    return;
                                }
                            }

                            // 4. Generate company-wise Position
                            int position;

                            using (SqlCommand cmdPosition = new SqlCommand(@"
                        SELECT ISNULL(MAX(Position), 0) + 1
                        FROM dbo.DesignCategoryMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdPosition.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                position = Convert.ToInt32(cmdPosition.ExecuteScalar());
                            }

                            // 5. Insert Design Category
                            int newId;

                            using (SqlCommand cmd = new SqlCommand(@"
                        INSERT INTO dbo.DesignCategoryMaster
                        (
                            DateAndTime,
                            DesignCategory,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        )
                        VALUES
                        (
                            @DateAndTime,
                            @DesignCategory,
                            @IsActive,
                            @Position,
                            @CompanyId,
                            @UserAccountId
                        );

                        SELECT CAST(SCOPE_IDENTITY() AS INT);",
                                con, tran))
                            {
                                cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime)
                                    .Value = dateTimeIndian;

                                cmd.Parameters.Add("@DesignCategory", SqlDbType.NVarChar)
                                    .Value = ilist.DesignCategory;

                                cmd.Parameters.Add("@IsActive", SqlDbType.Int)
                                    .Value = isActive;

                                cmd.Parameters.Add("@Position", SqlDbType.Int)
                                    .Value = position;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                    .Value = userId;

                                newId = Convert.ToInt32(cmd.ExecuteScalar());
                            }

                            // 6. Audit log inside transaction
                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Design Category",
                                action: "CREATE",
                                tableName: "DesignCategoryMaster",
                                recordId: newId.ToString(),
                                description: $"Created Design Category '{ilist.DesignCategory}'",
                                oldValue: null,
                                newValue: ilist,
                                customUserId: userId
                            );

                            tran.Commit();

                            response.Code = 201;
                            response.Message = "Design Category has been saved successfully.";
                        }
                        catch
                        {
                            if (tran.Connection != null)
                            {
                                try
                                {
                                    tran.Rollback();
                                }
                                catch
                                {
                                    // Transaction may already be completed.
                                }
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Design Category",
                    "insertDesignCategoryMaster",
                    ex,
                    "Category: " + ilist.DesignCategory
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    response.Code = 409;
                    response.Message = "This Design Category already exists.";
                }
                else
                {
                    response.Code = 500;
                    response.Message = "Problem occurred while saving Design Category.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Design Category",
                    "insertDesignCategoryMaster",
                    ex,
                    "Unable to save Design Category."
                );

                response.Code = 500;
                response.Message = "Unable to save Design Category.";
            }

            WriteJsonResponse(response);
        }


