        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignCategoryMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            List<DesignCategoryMaster> listUser = new List<DesignCategoryMaster>();
            DesignCategoryMasterResponse response = new DesignCategoryMasterResponse();

            try
            {
                string search = HttpContext.Current.Request.Params["searchDesignCategory"] ?? "";
                int startFrom;

                if (!Int32.TryParse(HttpContext.Current.Request.Params["startFrom"], out startFrom) ||
                    startFrom < 0)
                {
                    startFrom = 0;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(@"
            SELECT *
            FROM DesignCategoryMaster
            WHERE (@Search = '' OR DesignCategory LIKE @SearchPattern)
            ORDER BY Position DESC
            OFFSET @StartFrom ROWS FETCH NEXT 10 ROWS ONLY", con))
                {
                    cmd.Parameters.Add("@Search", SqlDbType.NVarChar).Value = search.Trim();
                    cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar).Value =
                        "%" + search.Trim() + "%";
                    cmd.Parameters.Add("@StartFrom", SqlDbType.Int).Value = startFrom;

                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            DesignCategoryMaster item = new DesignCategoryMaster();

                            item.DesignCategoryID = Convert.ToInt32(rdr["DesignCategoryID"]);
                            item.IsActive = rdr["IsActive"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["IsActive"]);
                            item.Position = rdr["Position"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["Position"]);

                            if (rdr["DateandTime"] != DBNull.Value)
                            {
                                item.DateandTime = Convert.ToDateTime(rdr["DateandTime"]);
                                item.DateandTimes = item.DateandTime.ToString("dd-MM-yyyy");
                            }

                            item.DesignCategory = rdr["DesignCategory"] == DBNull.Value
                                ? string.Empty
                                : rdr["DesignCategory"].ToString().ToUpperInvariant();

                            listUser.Add(item);
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Design Category", "getDesignCategoryMaster", ex);
                response.Code = 0;
                response.Message = "Problem occurred while retrieving Design Category.";
            }

            response.listDesignCategoryMaster = listUser;
            Context.Response.Write(js.Serialize(response));
        }

