        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditDesignCategoryMaster()
        {
            CommanResponse response = new CommanResponse();

            DesignCategoryMaster ilist = new DesignCategoryMaster();

            try
            {
                var request = HttpContext.Current.Request;

                int categoryId;
                int isActive;
                int userId;
                int companyId;

                string category =
                    (request.Params["DesignCategory"] ?? "").Trim().ToUpperInvariant();

                // 1. Validate input
                if (!int.TryParse(request.Params["DesignCategoryID"], out categoryId) ||
                    categoryId <= 0 ||
                    string.IsNullOrWhiteSpace(category) ||
                    !int.TryParse(request.Params["IsActive"], out isActive) ||
                    (isActive != 0 && isActive != 1))
                {
                    response.Code = 400;
                    response.Message = "Please enter valid Design Category details.";
                    WriteJsonResponse(response);
                    return;
                }

                // 2. Cookie validation - Existing project cookie format
                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null ||
                    string.IsNullOrEmpty(userCookie.Value) ||
                    string.IsNullOrEmpty(companyCookie.Value))
                {
                    response.Code = 401;
                    response.Message = "Invalid user or company session.";
                    WriteJsonResponse(response);
                    return;
                }

                string[] userParts = userCookie.Value.Split('=');
                string[] companyParts = companyCookie.Value.Split('=');

                if (userParts.Length < 2 ||
                    companyParts.Length < 2 ||
                    !int.TryParse(userParts[1], out userId) ||
                    !int.TryParse(companyParts[1], out companyId))
                {
                    response.Code = 401;
                    response.Message = "Invalid user or company session.";
                    WriteJsonResponse(response);
                    return;
                }

                ilist.DesignCategoryID = categoryId;
                ilist.DesignCategory = category;
                ilist.IsActive = isActive;
                ilist.UserAccountId = userId;
                ilist.CompanyId = companyId;

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // 3. Check record exists in current company
                            object oldValue = AuditLogHelper.FetchOldValue(
                                "DesignCategoryMaster",
                                categoryId.ToString(),
                                con
                            );

                            using (SqlCommand cmdCheck = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignCategoryMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE DesignCategoryID = @ID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdCheck.Parameters.Add("@ID", SqlDbType.Int).Value = categoryId;
                                cmdCheck.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;

                                if (Convert.ToInt32(cmdCheck.ExecuteScalar()) == 0)
                                {
                                    tran.Rollback();

                                    response.Code = 404;
                                    response.Message = "Design Category not found.";
                                    WriteJsonResponse(response);
                                    return;
                                }
                            }

                            // 4. Dependency check - DesignEntryFormMaster
                            using (SqlCommand cmdDependency = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignEntryFormMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE DesignCategoryID = @DesignCategoryID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdDependency.Parameters.Add("@DesignCategoryID", SqlDbType.Int)
                                    .Value = categoryId;

                                cmdDependency.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                int dependencyCount =
                                    Convert.ToInt32(cmdDependency.ExecuteScalar());

                                if (dependencyCount > 0)
                                {
                                    tran.Rollback();

                                    response.Code = 409;
                                    response.Message =
                                        "This Design Category cannot be updated because it is already associated with existing designs or related records.";

                                    WriteJsonResponse(response);
                                    return;
                                }
                            }

                            // 5. Duplicate check - Same company, excluding current record
                            using (SqlCommand cmdDuplicate = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignCategoryMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND DesignCategoryID <> @DesignCategoryID
                          AND UPPER(LTRIM(RTRIM(DesignCategory))) = @DesignCategory",
                                con, tran))
                            {
                                cmdDuplicate.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                cmdDuplicate.Parameters.Add("@DesignCategoryID", SqlDbType.Int)
                                    .Value = categoryId;

                                cmdDuplicate.Parameters.Add("@DesignCategory", SqlDbType.NVarChar)
                                    .Value = category;

                                if (Convert.ToInt32(cmdDuplicate.ExecuteScalar()) > 0)
                                {
                                    tran.Rollback();

                                    AuditLogHelper.LogDuplicateError(
                                        module: "Design Category",
                                        tableName: "DesignCategoryMaster",
                                        recordId: categoryId.ToString(),
                                        description: $"Duplicate Design Category: {category}",
                                        errorMessage: "This Design Category already exists.",
                                        requestData: ilist
                                    );

                                    response.Code = 409;
                                    response.Message = "This Design Category already exists.";

                                    WriteJsonResponse(response);
                                    return;
                                }
                            }

                            // 6. Update record
                            int rowsAffected;

                            using (SqlCommand cmd = new SqlCommand(@"
                        UPDATE dbo.DesignCategoryMaster
                        SET
                            DesignCategory = @DesignCategory,
                            IsActive = @IsActive,
                            UserAccountId = @UserAccountId
                        WHERE DesignCategoryID = @DesignCategoryID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmd.Parameters.Add("@DesignCategory", SqlDbType.NVarChar)
                                    .Value = category;

                                cmd.Parameters.Add("@IsActive", SqlDbType.Int)
                                    .Value = isActive;

                                cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                    .Value = userId;

                                cmd.Parameters.Add("@DesignCategoryID", SqlDbType.Int)
                                    .Value = categoryId;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                rowsAffected = cmd.ExecuteNonQuery();
                            }

                            if (rowsAffected > 0)
                            {
                                // 7. Audit log
                                AuditLogHelper.LogTransactional(
                                    conn: con,
                                    tran: tran,
                                    module: "Design Category",
                                    action: "UPDATE",
                                    tableName: "DesignCategoryMaster",
                                    recordId: categoryId.ToString(),
                                    description: $"Updated Design Category #{categoryId} '{category}'",
                                    oldValue: oldValue,
                                    newValue: ilist,
                                    customUserId: userId
                                );

                                tran.Commit();

                                response.Code = 201;
                                response.Message =
                                    "Design Category has been updated successfully.";
                            }
                            else
                            {
                                tran.Rollback();

                                response.Code = 404;
                                response.Message = "Design Category not found.";
                            }
                        }
                        catch
                        {
                            if (tran.Connection != null)
                            {
                                try { tran.Rollback(); } catch { }
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Design Category",
                    "EditDesignCategoryMaster",
                    ex,
                    $"ID: {ilist.DesignCategoryID}, Category: {ilist.DesignCategory}"
                );

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    response.Code = 409;
                    response.Message = "This Design Category already exists.";
                }
                else
                {
                    response.Code = 500;
                    response.Message = "Problem occurred while updating Design Category.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Design Category",
                    "EditDesignCategoryMaster",
                    ex,
                    "Unable to update Design Category."
                );

                response.Code = 500;
                response.Message = "Unable to update Design Category.";
            }

            WriteJsonResponse(response);
        }



        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteDesignCategoryMaster()
        {
            CommanResponse comman = new CommanResponse();

            try
            {
                var request = HttpContext.Current.Request;

                int categoryId;
                int userId;
                int companyId;

                // 1. Validate ID
                if (!int.TryParse(request.Params["DesignCategoryID"], out categoryId) ||
                    categoryId <= 0)
                {
                    comman.Code = 400;
                    comman.Message = "Invalid Design Category ID.";
                    WriteJsonResponse(comman);
                    return;
                }

                // 2. Cookie validation - Existing project cookie format
                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null ||
                    string.IsNullOrEmpty(userCookie.Value) ||
                    string.IsNullOrEmpty(companyCookie.Value))
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user or company session.";
                    WriteJsonResponse(comman);
                    return;
                }

                string[] userParts = userCookie.Value.Split('=');
                string[] companyParts = companyCookie.Value.Split('=');

                if (userParts.Length < 2 ||
                    companyParts.Length < 2 ||
                    !int.TryParse(userParts[1], out userId) ||
                    !int.TryParse(companyParts[1], out companyId))
                {
                    comman.Code = 401;
                    comman.Message = "Invalid user or company session.";
                    WriteJsonResponse(comman);
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // 3. Check record exists in current company
                            object oldValue = AuditLogHelper.FetchOldValue(
                                "DesignCategoryMaster",
                                categoryId.ToString(),
                                con
                            );

                            using (SqlCommand cmdCheck = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignCategoryMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE DesignCategoryID = @ID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdCheck.Parameters.Add("@ID", SqlDbType.Int).Value = categoryId;
                                cmdCheck.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;

                                if (Convert.ToInt32(cmdCheck.ExecuteScalar()) == 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 404;
                                    comman.Message = "Design Category record not found.";
                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 4. Dependency check - DesignEntryFormMaster
                            using (SqlCommand cmdDependency = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.DesignEntryFormMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE DesignCategoryID = @DesignCategoryID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdDependency.Parameters.Add("@DesignCategoryID", SqlDbType.Int)
                                    .Value = categoryId;

                                cmdDependency.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                int dependencyCount =
                                    Convert.ToInt32(cmdDependency.ExecuteScalar());

                                if (dependencyCount > 0)
                                {
                                    tran.Rollback();

                                    comman.Code = 409;
                                    comman.Message =
                                        "This Design Category cannot be deleted because it is already associated with existing designs or related records.";

                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }

                            // 5. Delete record
                            int rowsAffected;

                            using (SqlCommand cmdDelete = new SqlCommand(@"
                        DELETE FROM dbo.DesignCategoryMaster
                        WHERE DesignCategoryID = @DesignCategoryID
                          AND CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdDelete.Parameters.Add("@DesignCategoryID", SqlDbType.Int)
                                    .Value = categoryId;

                                cmdDelete.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                rowsAffected = cmdDelete.ExecuteNonQuery();
                            }

                            if (rowsAffected > 0)
                            {
                                // 6. Audit log
                                AuditLogHelper.LogTransactional(
                                    conn: con,
                                    tran: tran,
                                    module: "Design Category",
                                    action: "DELETE",
                                    tableName: "DesignCategoryMaster",
                                    recordId: categoryId.ToString(),
                                    description: $"Deleted Design Category ID #{categoryId}",
                                    oldValue: oldValue,
                                    newValue: null,
                                    customUserId: userId
                                );

                                tran.Commit();

                                comman.Code = 200;
                                comman.Message = "Design Category deleted successfully.";
                            }
                            else
                            {
                                tran.Rollback();

                                comman.Code = 404;
                                comman.Message = "Design Category record not found.";
                            }
                        }
                        catch
                        {
                            if (tran.Connection != null)
                            {
                                try { tran.Rollback(); } catch { }
                            }

                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Design Category",
                    "DeleteDesignCategoryMaster",
                    ex,
                    "DesignCategoryID: " + HttpContext.Current.Request.Params["DesignCategoryID"]
                );

                if (ex.Number == 547)
                {
                    comman.Code = 409;
                    comman.Message =
                        "This Design Category cannot be deleted because related records exist.";
                }
                else
                {
                    comman.Code = 500;
                    comman.Message = "Problem occurred while deleting Design Category.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Design Category",
                    "DeleteDesignCategoryMaster",
                    ex,
                    "Unable to delete Design Category."
                );

                comman.Code = 500;
                comman.Message = "Unable to delete Design Category.";
            }

            WriteJsonResponse(comman);
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_DesignCategoryQueue()
        {
            JavaScriptSerializer js;

            DesignCategoryMaster ilist = new DesignCategoryMaster();

            DesignCategoryMasterResponse comman = new DesignCategoryMasterResponse();

            ilist.ProductSrNo = HttpContext.Current.Request.Params["PostQueue"];
            //ilist.image_isActive = HttpContext.Current.Request.Params["image_isActive"];


            string[] PostQueue = ilist.ProductSrNo.Split('|');

            var Onepost_type_id = PostQueue[0].Split(',')[0];
            var OneQueue = PostQueue[0].Split(',')[1];

            var Twopost_type_id = PostQueue[1].Split(',')[0];
            var TwoQueue = PostQueue[1].Split(',')[1];

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection conn = new SqlConnection(cs))
            {

                SqlCommand cmd = new SqlCommand();

                cmd.Connection = conn;
                cmd.CommandText = "update DesignCategoryMaster set Position = " + TwoQueue + " where DesignCategoryID = " + Onepost_type_id + "";
                conn.Open();
                int i = cmd.ExecuteNonQuery();
                conn.Close();
                if (i > 0)
                {

                    cmd.Connection = conn;
                    cmd.CommandText = "update DesignCategoryMaster set Position = " + OneQueue + " where DesignCategoryID = " + Twopost_type_id + "";
                    conn.Open();
                    int j = cmd.ExecuteNonQuery();
                    conn.Close();

                    if (j > 0)
                    {
                        comman.Code = 1;
                        comman.Message = "Success";
                        js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                    else
                    {
                        comman.Code = 0;
                        comman.Message = "Error";
                        js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }

                }
                else
                {
                    comman.Code = 0;
                    comman.Message = "Error";
                    js = new JavaScriptSerializer();
                    js.MaxJsonLength = Int32.MaxValue;
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }

            }


        }
