        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertYarnMaterialMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse response = new CommanResponse();
            YarnMaterialMaster item = new YarnMaterialMaster();

            try
            {
                var request = HttpContext.Current.Request;

                item.YarnMaterial = (request.Params["YarnMaterial"] ?? "").Trim();
                item.Denier = request.Params["Denier"];
                item.HSNCode = request.Params["HSNCode"];

                int unitId;
                int gstId;
                int isActive;
                int userId;
                int companyId;

                // 1. Validate input
                if (string.IsNullOrWhiteSpace(item.YarnMaterial) ||
                    !int.TryParse(request.Params["UnitId"], out unitId) ||
                    unitId <= 0 ||
                    !int.TryParse(request.Params["GSTSLABId"], out gstId) ||
                    gstId <= 0 ||
                    !int.TryParse(request.Params["IsActive"], out isActive) ||
                    (isActive != 0 && isActive != 1))
                {
                    response.Code = 400;
                    response.Message = "Please enter valid Yarn Material details.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                // 2. Cookie validation - Existing project cookie format
                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                if (userCookie == null || companyCookie == null ||
                    string.IsNullOrEmpty(userCookie.Value) ||
                    string.IsNullOrEmpty(companyCookie.Value))
                {
                    response.Code = 401;
                    response.Message = "Invalid user or company session.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                string[] userParts = userCookie.Value.Split('=');
                string[] companyParts = companyCookie.Value.Split('=');

                if (userParts.Length < 2 ||
                    companyParts.Length < 2 ||
                    !int.TryParse(userParts[1], out userId) ||
                    !int.TryParse(companyParts[1], out companyId))
                {
                    response.Code = 401;
                    response.Message = "Invalid user or company session.";
                    Context.Response.Write(js.Serialize(response));
                    return;
                }

                item.YarnMaterial = item.YarnMaterial.ToUpperInvariant();
                item.UnitId = unitId;
                item.GSTSLABId = gstId;
                item.IsActive = isActive;
                item.UserAccountId = userId;
                item.CompanyId = companyId;

                DateTime dateTimeIndian =
                    TimeZoneInfo.ConvertTimeFromUtc(
                        DateTime.UtcNow,
                        India_Standard_Time
                    );

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran =
                        con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // 3. Duplicate check - Same company
                            using (SqlCommand cmdDuplicate = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM dbo.YarnMaterialMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId
                          AND UPPER(LTRIM(RTRIM(YarnMaterial))) = @YarnMaterial",
                                con, tran))
                            {
                                cmdDuplicate.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                cmdDuplicate.Parameters.Add("@YarnMaterial", SqlDbType.NVarChar)
                                    .Value = item.YarnMaterial;

                                if (Convert.ToInt32(cmdDuplicate.ExecuteScalar()) > 0)
                                {
                                    tran.Rollback();

                                    AuditLogHelper.LogDuplicateError(
                                        module: "Yarn Material",
                                        tableName: "YarnMaterialMaster",
                                        recordId: null,
                                        description: $"Duplicate Yarn Material: {item.YarnMaterial}",
                                        errorMessage: "This Yarn Material already exists.",
                                        requestData: item
                                    );

                                    response.Code = 409;
                                    response.Message = "This Yarn Material already exists.";

                                    Context.Response.Write(js.Serialize(response));
                                    return;
                                }
                            }

                            // 4. Company-wise Position
                            int position;

                            using (SqlCommand cmdPosition = new SqlCommand(@"
                        SELECT ISNULL(MAX(Position), 0) + 1
                        FROM dbo.YarnMaterialMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE CompanyId = @CompanyId",
                                con, tran))
                            {
                                cmdPosition.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = companyId;

                                position = Convert.ToInt32(cmdPosition.ExecuteScalar());
                            }

                            // 5. Insert record
                            int newId;

                            using (SqlCommand cmd = new SqlCommand(@"
                        INSERT INTO dbo.YarnMaterialMaster
                        (
                            DateAndTime,
                            YarnMaterial,
                            Denier,
                            UnitId,
                            HSNCode,
                            GSTSLABId,
                            IsActive,
                            Position,
                            CompanyId,
                            UserAccountId
                        )
                        VALUES
                        (
                            @DateAndTime,
                            @YarnMaterial,
                            @Denier,
                            @UnitId,
                            @HSNCode,
                            @GSTSLABId,
                            @IsActive,
                            @Position,
                            @CompanyId,
                            @UserAccountId
                        );

                        SELECT CAST(SCOPE_IDENTITY() AS INT);",
                                con, tran))
                            {
                                cmd.Parameters.Add("@DateAndTime", SqlDbType.DateTime)
                                    .Value = dateTimeIndian;

                                cmd.Parameters.Add("@YarnMaterial", SqlDbType.NVarChar)
                                    .Value = item.YarnMaterial;

                                cmd.Parameters.Add("@Denier", SqlDbType.NVarChar)
                                    .Value = string.IsNullOrWhiteSpace(item.Denier)
                                        ? (object)DBNull.Value
                                        : item.Denier;

                                cmd.Parameters.Add("@UnitId", SqlDbType.Int)
                                    .Value = item.UnitId;

                                cmd.Parameters.Add("@HSNCode", SqlDbType.NVarChar)
                                    .Value = string.IsNullOrWhiteSpace(item.HSNCode)
                                        ? (object)DBNull.Value
                                        : item.HSNCode;

                                cmd.Parameters.Add("@GSTSLABId", SqlDbType.Int)
                                    .Value = item.GSTSLABId;

                                cmd.Parameters.Add("@IsActive", SqlDbType.Int)
                                    .Value = item.IsActive;

                                cmd.Parameters.Add("@Position", SqlDbType.Int)
                                    .Value = position;

                                cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                    .Value = item.CompanyId;

                                cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                    .Value = item.UserAccountId;

                                newId = Convert.ToInt32(cmd.ExecuteScalar());
                            }

                            // 6. Audit log inside transaction
                            AuditLogHelper.LogTransactional(
                                conn: con,
                                tran: tran,
                                module: "Yarn Material",
                                action: "CREATE",
                                tableName: "YarnMaterialMaster",
                                recordId: newId.ToString(),
                                description: "Created Yarn Material '" + item.YarnMaterial + "'",
                                newValue: item,
                                customUserId: item.UserAccountId
                            );

                            tran.Commit();

                            response.Code = 201;
                            response.Message = "Yarn Material has been saved successfully.";
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                try
                {
                    AuditLogHelper.LogError(
                        "Yarn Material",
                        "insertYarnMaterialMaster",
                        ex,
                        "Yarn Material: " + item.YarnMaterial
                    );
                }
                catch { }

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    response.Code = 409;
                    response.Message = "This Yarn Material already exists.";
                }
                else
                {
                    response.Code = 500;
                    response.Message = "Problem occurred while saving Yarn Material.";
                }
            }
            catch (Exception ex)
            {
                try
                {
                    AuditLogHelper.LogError(
                        "Yarn Material",
                        "insertYarnMaterialMaster",
                        ex,
                        "Unable to save Yarn Material."
                    );
                }
                catch { }

                response.Code = 500;
                response.Message = "Unable to save Yarn Material.";
            }

            Context.Response.Write(js.Serialize(response));
        }


