        // View Design Entry Form

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnMaterialMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue };
            List<YarnMaterialMaster> listUser = new List<YarnMaterialMaster>();
            YarnMaterialMasterResponse response = new YarnMaterialMasterResponse();

            try
            {
                string search = HttpContext.Current.Request.Params["SearchYarnMaterial"] ?? "";
                int startFrom;

                if (!Int32.TryParse(HttpContext.Current.Request.Params["startFrom"], out startFrom) ||
                    startFrom < 0)
                    startFrom = 0;

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(@"
            SELECT YMM.*, UM.Unit, GSM.GSTSLABName
            FROM YarnMaterialMaster YMM
            LEFT JOIN UnitMaster UM ON UM.UnitId = YMM.UnitId
            LEFT JOIN GSTSLABMaster GSM ON GSM.GSTSLABId = YMM.GSTSLABId
            WHERE (@Search = '' OR YMM.YarnMaterial LIKE @SearchPattern)
            ORDER BY YMM.Position DESC
            OFFSET @StartFrom ROWS FETCH NEXT 10 ROWS ONLY", con))
                {
                    cmd.Parameters.Add("@Search", SqlDbType.NVarChar).Value = search.Trim();
                    cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar).Value =
                        "%" + search.Trim() + "%";
                    cmd.Parameters.Add("@StartFrom", SqlDbType.Int).Value = startFrom;

                    con.Open();

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            YarnMaterialMaster item = new YarnMaterialMaster();

                            item.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"]);
                            item.IsActive = rdr["IsActive"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["IsActive"]);
                            item.Position = rdr["Position"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["Position"]);

                            if (rdr["DateandTime"] != DBNull.Value)
                            {
                                item.DateandTime = Convert.ToDateTime(rdr["DateandTime"]);
                                item.DateandTimes = item.DateandTime.ToString("dd-MM-yyyy");
                            }

                            item.YarnMaterial = Convert.ToString(rdr["YarnMaterial"]);
                            item.Denier = Convert.ToString(rdr["Denier"]);
                            item.UnitId = rdr["UnitId"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["UnitId"]);
                            item.Unit = Convert.ToString(rdr["Unit"]);
                            item.GSTSLABId = rdr["GSTSLABId"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["GSTSLABId"]);
                            item.GSTSLABName = Convert.ToString(rdr["GSTSLABName"]);
                            item.HSNCode = Convert.ToString(rdr["HSNCode"]);

                            listUser.Add(item);
                        }
                    }
                }

                response.Code = 1;
                response.Message = "Success";
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Yarn Material", "getYarnMaterialMaster", ex);
                response.Code = 0;
                response.Message = "Problem occurred while retrieving Yarn Material.";
            }

            response.listYarnMaterialMaster = listUser;
            Context.Response.Write(js.Serialize(response));
        }

