        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnMaterialMasterById(string id)
        {
            JavaScriptSerializer js = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue };
            List<YarnMaterialMaster> listUser = new List<YarnMaterialMaster>();
            YarnMaterialMasterResponse response = new YarnMaterialMasterResponse();

            try
            {
                if (!Int32.TryParse(id, out int materialId) || materialId <= 0)
                {
                    response.Code = 400;
                    response.Message = "Invalid Yarn Material ID.";
                }
                else
                {
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    using (SqlCommand cmd = new SqlCommand(@"
                SELECT YMM.*, UM.Unit, GSM.GSTSLABName
                FROM YarnMaterialMaster YMM
                LEFT JOIN UnitMaster UM ON UM.UnitId = YMM.UnitId
                LEFT JOIN GSTSLABMaster GSM ON GSM.GSTSLABId = YMM.GSTSLABId
                WHERE YMM.YarnMaterialID = @ID", con))
                    {
                        cmd.Parameters.Add("@ID", SqlDbType.Int).Value = materialId;
                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                YarnMaterialMaster item = new YarnMaterialMaster();

                                item.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"]);
                                item.YarnMaterial = Convert.ToString(rdr["YarnMaterial"]);
                                item.Denier = Convert.ToString(rdr["Denier"]);
                                item.HSNCode = Convert.ToString(rdr["HSNCode"]);
                                item.Unit = Convert.ToString(rdr["Unit"]);
                                item.GSTSLABName = Convert.ToString(rdr["GSTSLABName"]);
                                item.UnitId = rdr["UnitId"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["UnitId"]);
                                item.GSTSLABId = rdr["GSTSLABId"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["GSTSLABId"]);
                                item.IsActive = rdr["IsActive"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["IsActive"]);

                                listUser.Add(item);
                            }
                        }
                    }

                    response.Code = 200;
                    response.Message = "Success";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Yarn Material", "getYarnMaterialMasterById", ex);
                response.Code = 500;
                response.Message = "Problem occurred while retrieving Yarn Material.";
            }

            response.listYarnMaterialMaster = listUser;
            Context.Response.Write(js.Serialize(response));
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditYarnMaterialMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer
            {
                MaxJsonLength = Int32.MaxValue
            };

            CommanResponse response = new CommanResponse();
            YarnMaterialMaster item = new YarnMaterialMaster();

            try
            {
                var request = HttpContext.Current.Request;

                int materialId, unitId, gstId, isActive;
                int userId, companyId;

                HttpCookie userCookie = request.Cookies["UserIDs"];
                HttpCookie companyCookie = request.Cookies["CompanyID"];

                if (!int.TryParse(request.Params["YarnMaterialID"], out materialId) || materialId <= 0 ||
                    !int.TryParse(request.Params["UnitId"], out unitId) ||
                    !int.TryParse(request.Params["GSTSLABId"], out gstId) ||
                    !int.TryParse(request.Params["IsActive"], out isActive) ||
                    userCookie == null || companyCookie == null ||
                    string.IsNullOrEmpty(userCookie.Value) ||
                    string.IsNullOrEmpty(companyCookie.Value))
                {
                    response.Code = 400;
                    response.Message = "Invalid input or user information.";
                }
                else
                {
                    string[] userParts = userCookie.Value.Split('=');
                    string[] companyParts = companyCookie.Value.Split('=');

                    if (userParts.Length < 2 || companyParts.Length < 2 ||
                        !int.TryParse(userParts[1], out userId) ||
                        !int.TryParse(companyParts[1], out companyId))
                    {
                        response.Code = 401;
                        response.Message = "Invalid user or company session.";
                    }
                    else if (string.IsNullOrWhiteSpace(request.Params["YarnMaterial"]))
                    {
                        response.Code = 410;
                        response.Message = "Please Mention Yarn Material.";
                    }
                    else if (isActive != 0 && isActive != 1)
                    {
                        response.Code = 400;
                        response.Message = "Invalid Active status.";
                    }
                    else
                    {
                        item.YarnMaterialID = materialId;
                        item.YarnMaterial = request.Params["YarnMaterial"].Trim();
                        item.Denier = request.Params["Denier"];
                        item.HSNCode = request.Params["HSNCode"];
                        item.UnitId = unitId;
                        item.GSTSLABId = gstId;
                        item.IsActive = isActive;
                        item.UserAccountId = userId;
                        item.CompanyId = companyId;

                        string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                        using (SqlConnection con = new SqlConnection(cs))
                        {
                            con.Open();

                            using (SqlTransaction tran =
                                con.BeginTransaction(IsolationLevel.Serializable))
                            {
                                try
                                {
                                    object oldValue = null;

                                    // Check record and company ownership.
                                    using (SqlCommand cmd = new SqlCommand(@"
                                SELECT *
                                FROM dbo.YarnMaterialMaster WITH (UPDLOCK, HOLDLOCK)
                                WHERE YarnMaterialID = @ID
                                  AND CompanyId = @CompanyId",
                                        con, tran))
                                    {
                                        cmd.Parameters.Add("@ID", SqlDbType.Int).Value = materialId;
                                        cmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;

                                        using (SqlDataReader rdr = cmd.ExecuteReader())
                                        {
                                            if (rdr.Read())
                                            {
                                                Dictionary<string, object> oldData =
                                                    new Dictionary<string, object>();

                                                for (int i = 0; i < rdr.FieldCount; i++)
                                                    oldData[rdr.GetName(i)] =
                                                        rdr.IsDBNull(i) ? null : rdr.GetValue(i);

                                                oldValue = oldData;
                                            }
                                        }
                                    }

                                    if (oldValue == null)
                                    {
                                        tran.Rollback();
                                        response.Code = 404;
                                        response.Message = "Yarn Material not found.";
                                    }
                                    else
                                    {
                                        // Duplicate check within same company.
                                        string duplicateSql = @"
                                    SELECT COUNT(1)
                                    FROM dbo.YarnMaterialMaster WITH (UPDLOCK, HOLDLOCK)
                                    WHERE UPPER(LTRIM(RTRIM(YarnMaterial))) =
                                          UPPER(LTRIM(RTRIM(@YarnMaterial)))
                                      AND CompanyId = @CompanyId
                                      AND YarnMaterialID <> @ID";

                                        int duplicateCount;

                                        using (SqlCommand cmd =
                                            new SqlCommand(duplicateSql, con, tran))
                                        {
                                            cmd.Parameters.Add("@YarnMaterial", SqlDbType.NVarChar)
                                                .Value = item.YarnMaterial;
                                            cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                                .Value = companyId;
                                            cmd.Parameters.Add("@ID", SqlDbType.Int)
                                                .Value = materialId;

                                            duplicateCount = Convert.ToInt32(cmd.ExecuteScalar());
                                        }

                                        if (duplicateCount > 0)
                                        {
                                            tran.Rollback();
                                            response.Code = 409;
                                            response.Message = "This Yarn Material already exists.";
                                        }
                                        else
                                        {
                                            // Dependency check.
                                            string dependencySql = @"
                                        SELECT
                                            (SELECT COUNT(1)
                                             FROM dbo.YarnRequirementDetail WITH (UPDLOCK, HOLDLOCK)
                                             WHERE YarnMaterialID = @ID)
                                            +
                                            (SELECT COUNT(1)
                                             FROM dbo.YarnPODetails WITH (UPDLOCK, HOLDLOCK)
                                             WHERE YarnMaterialID = @ID)";

                                            int dependencyCount;

                                            using (SqlCommand cmd =
                                                new SqlCommand(dependencySql, con, tran))
                                            {
                                                cmd.Parameters.Add("@ID", SqlDbType.Int)
                                                    .Value = materialId;

                                                dependencyCount =
                                                    Convert.ToInt32(cmd.ExecuteScalar());
                                            }

                                            if (dependencyCount > 0)
                                            {
                                                tran.Rollback();
                                                response.Code = 409;
                                                response.Message =
                                                    "This Yarn Material cannot be updated because it is already associated with existing transactions or related records.";
                                            }
                                            else
                                            {
                                                string updateSql = @"
                                            UPDATE dbo.YarnMaterialMaster
                                            SET YarnMaterial = @YarnMaterial,
                                                Denier = @Denier,
                                                UnitId = @UnitId,
                                                HSNCode = @HSNCode,
                                                GSTSLABId = @GSTSLABId,
                                                IsActive = @IsActive,
                                                UserAccountId = @UserAccountId
                                            WHERE YarnMaterialID = @YarnMaterialID
                                              AND CompanyId = @CompanyId";

                                                int rows;

                                                using (SqlCommand cmd =
                                                    new SqlCommand(updateSql, con, tran))
                                                {
                                                    cmd.Parameters.Add("@YarnMaterial", SqlDbType.NVarChar)
                                                        .Value = item.YarnMaterial;

                                                    cmd.Parameters.Add("@Denier", SqlDbType.NVarChar)
                                                        .Value = (object)item.Denier ?? DBNull.Value;

                                                    cmd.Parameters.Add("@UnitId", SqlDbType.Int)
                                                        .Value = item.UnitId;

                                                    cmd.Parameters.Add("@HSNCode", SqlDbType.NVarChar)
                                                        .Value = (object)item.HSNCode ?? DBNull.Value;

                                                    cmd.Parameters.Add("@GSTSLABId", SqlDbType.Int)
                                                        .Value = item.GSTSLABId;

                                                    cmd.Parameters.Add("@IsActive", SqlDbType.Int)
                                                        .Value = item.IsActive;

                                                    cmd.Parameters.Add("@UserAccountId", SqlDbType.Int)
                                                        .Value = item.UserAccountId;

                                                    cmd.Parameters.Add("@YarnMaterialID", SqlDbType.Int)
                                                        .Value = materialId;

                                                    cmd.Parameters.Add("@CompanyId", SqlDbType.Int)
                                                        .Value = companyId;

                                                    rows = cmd.ExecuteNonQuery();
                                                }

                                                if (rows > 0)
                                                {
                                                    AuditLogHelper.LogTransactional(
                                                        conn: con,
                                                        tran: tran,
                                                        module: "Yarn Material",
                                                        action: "UPDATE",
                                                        tableName: "YarnMaterialMaster",
                                                        recordId: materialId.ToString(),
                                                        description: "Updated Yarn Material #" + materialId,
                                                        oldValue: oldValue,
                                                        newValue: item,
                                                        customUserId: userId
                                                    );

                                                    tran.Commit();

                                                    response.Code = 201;
                                                    response.Message =
                                                        "Yarn Material has been updated successfully.";
                                                }
                                                else
                                                {
                                                    tran.Rollback();
                                                    response.Code = 404;
                                                    response.Message = "Yarn Material not found.";
                                                }
                                            }
                                        }
                                    }
                                }
                                catch
                                {
                                    try { tran.Rollback(); } catch { }
                                    throw;
                                }
                            }
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError(
                    "Yarn Material",
                    "EditYarnMaterialMaster",
                    ex
                );

                response.Code = (ex.Number == 2601 || ex.Number == 2627) ? 409 : 500;
                response.Message = (ex.Number == 2601 || ex.Number == 2627)
                    ? "This Yarn Material already exists."
                    : "Problem occurred while updating Yarn Material.";
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError(
                    "Yarn Material",
                    "EditYarnMaterialMaster",
                    ex
                );

                response.Code = 500;
                response.Message = "Problem occurred while updating Yarn Material.";
            }

            Context.Response.Write(js.Serialize(response));
        }



