        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateTbl_YarnMaterialQueue()
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            YarnMaterialMasterResponse comman = new YarnMaterialMasterResponse();

            try
            {
                string postQueue = HttpContext.Current.Request.Params["PostQueue"];

                if (string.IsNullOrWhiteSpace(postQueue))
                {
                    comman.Code = 0;
                    comman.Message = "Invalid queue data.";
                }
                else
                {
                    string[] queueItems = postQueue.Split('|');

                    if (queueItems.Length != 2)
                    {
                        comman.Code = 0;
                        comman.Message = "Invalid queue format.";
                    }
                    else
                    {
                        string[] first = queueItems[0].Split(',');
                        string[] second = queueItems[1].Split(',');

                        int firstId, firstPosition, secondId, secondPosition;

                        if (first.Length != 2 || second.Length != 2 ||
                            !int.TryParse(first[0], out firstId) ||
                            !int.TryParse(first[1], out firstPosition) ||
                            !int.TryParse(second[0], out secondId) ||
                            !int.TryParse(second[1], out secondPosition) ||
                            firstId <= 0 || secondId <= 0 ||
                            firstId == secondId)
                        {
                            comman.Code = 0;
                            comman.Message = "Invalid queue values.";
                        }
                        else
                        {
                            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                            using (SqlConnection conn = new SqlConnection(cs))
                            {
                                conn.Open();

                                using (SqlTransaction tran = conn.BeginTransaction())
                                {
                                    try
                                    {
                                        using (SqlCommand cmd = new SqlCommand(
                                            @"UPDATE YarnMaterialMaster
                                      SET Position = @Position
                                      WHERE YarnMaterialID = @ID",
                                            conn, tran))
                                        {
                                            cmd.Parameters.Add("@Position", SqlDbType.Int).Value = firstPosition;
                                            cmd.Parameters.Add("@ID", SqlDbType.Int).Value = secondId;

                                            if (cmd.ExecuteNonQuery() <= 0)
                                                throw new Exception("First queue update failed.");

                                            cmd.Parameters["@Position"].Value = secondPosition;
                                            cmd.Parameters["@ID"].Value = firstId;

                                            if (cmd.ExecuteNonQuery() <= 0)
                                                throw new Exception("Second queue update failed.");
                                        }

                                        tran.Commit();

                                        comman.Code = 1;
                                        comman.Message = "Success";
                                    }
                                    catch
                                    {
                                        tran.Rollback();
                                        throw;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Yarn Material", "UpdateTbl_YarnMaterialQueue", ex);

                comman.Code = 0;
                comman.Message = "Error while updating queue.";
            }

            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
