        [WebMethod]
        [System.Web.Script.Services.ScriptMethod]
        public string checkValidYearRange(string yearRange)
        {
            if (string.IsNullOrWhiteSpace(yearRange))
                return "false";

            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(
                    "SELECT COUNT(1) FROM FinancialYearMaster WHERE FinancialYear = @FinancialYear",
                    con))
                {
                    cmd.Parameters.Add("@FinancialYear", SqlDbType.NVarChar).Value = yearRange.Trim();

                    con.Open();

                    int count = Convert.ToInt32(cmd.ExecuteScalar());

                    return count > 0 ? "true" : "false";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Financial Year", "checkValidYearRange", ex);
                return "false";
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertFinancialYearMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            CommanResponse comman = new CommanResponse();

            try
            {
                var request = HttpContext.Current.Request;

                string financialYear = request.Params["FinancialYear"];
                string assessmentYear = request.Params["AssessmentYear"];
                string startDateValue = request.Params["StartDate"];
                string endDateValue = request.Params["EndDate"];
                string isDefaultValue = request.Params["IsDefault"];

                DateTime startDate, endDate;
                int isDefault;

                if (string.IsNullOrWhiteSpace(financialYear) ||
                    string.IsNullOrWhiteSpace(assessmentYear) ||
                    !DateTime.TryParse(startDateValue, out startDate) ||
                    !DateTime.TryParse(endDateValue, out endDate) ||
                    !int.TryParse(isDefaultValue, out isDefault) ||
                    (isDefault != 0 && isDefault != 1))
                {
                    comman.Code = 0;
                    comman.Message = "Please provide valid financial year details.";
                }
                else if (endDate < startDate)
                {
                    comman.Code = 0;
                    comman.Message = "End Date cannot be earlier than Start Date.";
                }
                else
                {
                    FinancialYearMaster ilist = new FinancialYearMaster();
                    ilist.FinancialYear = financialYear.Trim();
                    ilist.AssessmentYear = assessmentYear.Trim();
                    ilist.StartDate = startDate;
                    ilist.EndDate = endDate;
                    ilist.IsDefault = isDefault;

                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        con.Open();

                        using (SqlTransaction tran = con.BeginTransaction())
                        {
                            try
                            {
                                using (SqlCommand cmd = new SqlCommand(
                                    @"SELECT COUNT(1)
                              FROM FinancialYearMaster
                              WHERE FinancialYear = @FinancialYear",
                                    con, tran))
                                {
                                    cmd.Parameters.Add("@FinancialYear", SqlDbType.NVarChar).Value =
                                        ilist.FinancialYear;

                                    if (Convert.ToInt32(cmd.ExecuteScalar()) > 0)
                                    {
                                        tran.Rollback();

                                        comman.Code = 500;
                                        comman.Message = "Can't submit this year because this year already exists.";
                                    }
                                    else
                                    {
                                        if (ilist.IsDefault == 1)
                                        {
                                            using (SqlCommand updateCmd = new SqlCommand(
                                                "UPDATE FinancialYearMaster SET IsDefault = 0",
                                                con, tran))
                                            {
                                                updateCmd.ExecuteNonQuery();
                                            }
                                        }

                                        using (SqlCommand insertCmd = new SqlCommand(
                                            @"INSERT INTO FinancialYearMaster
                                      (FinancialYear, AssessmentYear, StartDate, EndDate, IsDefault)
                                      VALUES
                                      (@FinancialYear, @AssessmentYear, @StartDate, @EndDate, @IsDefault)",
                                            con, tran))
                                        {
                                            insertCmd.Parameters.Add("@FinancialYear", SqlDbType.NVarChar).Value =
                                                ilist.FinancialYear;

                                            insertCmd.Parameters.Add("@AssessmentYear", SqlDbType.NVarChar).Value =
                                                ilist.AssessmentYear;

                                            insertCmd.Parameters.Add("@StartDate", SqlDbType.DateTime).Value =
                                                ilist.StartDate;

                                            insertCmd.Parameters.Add("@EndDate", SqlDbType.DateTime).Value =
                                                ilist.EndDate;

                                            insertCmd.Parameters.Add("@IsDefault", SqlDbType.Int).Value =
                                                ilist.IsDefault;

                                            int result = insertCmd.ExecuteNonQuery();

                                            if (result <= 0)
                                                throw new Exception("Financial year insert failed.");
                                        }

                                        tran.Commit();

                                        AuditLogHelper.Log(
                                            module: "Financial Year",
                                            action: "CREATE",
                                            tableName: "FinancialYearMaster",
                                            description: $"Created Financial Year '{ilist.FinancialYear}' ({ilist.AssessmentYear})",
                                            newValue: ilist
                                        );

                                        comman.Code = 201;
                                        comman.Message = "Record has been saved successfully.";
                                    }
                                }
                            }
                            catch
                            {
                                if (tran.Connection != null)
                                    tran.Rollback();

                                throw;
                            }
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError("Financial Year", "insertFinancialYearMaster", ex);

                comman.Code = 0;
                comman.Message = (ex.Number == 2601 || ex.Number == 2627)
                    ? "Cannot insert duplicate values.."
                    : "Problem has been occurred while submitting your data.";
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Financial Year", "insertFinancialYearMaster", ex);

                comman.Code = 0;
                comman.Message = "Problem has been occurred while submitting your data.";
            }

            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getFinancialYearMaster(string startFrom)
        {
            JavaScriptSerializer js = new JavaScriptSerializer();

            List<FinancialYearMaster> listUser = new List<FinancialYearMaster>();
            FinancialYearMasterResponce response = new FinancialYearMasterResponce();

            try
            {
                int offset;

                if (!int.TryParse(startFrom, out offset) || offset < 0)
                {
                    response.Code = 0;
                    response.Message = "Invalid page number.";
                }
                else
                {
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    using (SqlCommand cmd = new SqlCommand(
                        @"SELECT *,
                    CASE WHEN IsDefault = 1 THEN 'badge bg-success'
                         ELSE 'badge bg-danger' END AS IsDefaultCss,
                    CASE WHEN IsDefault = 1 THEN 'Active'
                         ELSE 'Inactive' END AS IsDefaults
                  FROM FinancialYearMaster
                  ORDER BY FinancialYearID DESC
                  OFFSET @StartFrom ROWS FETCH NEXT 10 ROWS ONLY",
                        con))
                    {
                        cmd.Parameters.Add("@StartFrom", SqlDbType.Int).Value = offset;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                FinancialYearMaster condition = new FinancialYearMaster();

                                condition.FinancialYearID = Convert.ToInt32(rdr["FinancialYearID"]);
                                condition.FinancialYear = rdr["FinancialYear"].ToString();
                                condition.AssessmentYear = rdr["AssessmentYear"].ToString();
                                condition.StartDates = Convert.ToDateTime(rdr["StartDate"]).ToString("dd-MM-yyyy");
                                condition.EndDates = Convert.ToDateTime(rdr["EndDate"]).ToString("dd-MM-yyyy");
                                condition.IsDefaultCss = rdr["IsDefaultCss"].ToString();
                                condition.IsDefaults = rdr["IsDefaults"].ToString();

                                listUser.Add(condition);
                            }
                        }
                    }

                    response.Code = 1;
                    response.Message = "Success";
                    response.listFinancialYearMaster = listUser;
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Financial Year", "getFinancialYearMaster", ex);

                response.Code = 0;
                response.Message = "Unable to fetch financial year records.";
                response.listFinancialYearMaster = listUser;
            }

            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void ActiveFinancialYearMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            CommanResponse comman = new CommanResponse();

            int financialYearId;

            if (!int.TryParse(
                HttpContext.Current.Request.Params["FinancialYearIDs"],
                out financialYearId) || financialYearId <= 0)
            {
                comman.Code = 0;
                comman.Message = "Invalid Financial Year ID.";
            }
            else
            {
                try
                {
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        con.Open();

                        using (SqlTransaction tran = con.BeginTransaction())
                        {
                            try
                            {
                                object oldValue = AuditLogHelper.FetchOldValue(
                                    "FinancialYearMaster",
                                    financialYearId.ToString(),
                                    con
                                );

                                using (SqlCommand checkCmd = new SqlCommand(
                                    @"SELECT COUNT(1)
                              FROM FinancialYearMaster
                              WHERE FinancialYearID = @FinancialYearID",
                                    con, tran))
                                {
                                    checkCmd.Parameters.Add("@FinancialYearID", SqlDbType.Int).Value =
                                        financialYearId;

                                    if (Convert.ToInt32(checkCmd.ExecuteScalar()) == 0)
                                        throw new Exception("Financial year record not found.");
                                }

                                using (SqlCommand resetCmd = new SqlCommand(
                                    "UPDATE FinancialYearMaster SET IsDefault = 0",
                                    con, tran))
                                {
                                    resetCmd.ExecuteNonQuery();
                                }

                                using (SqlCommand activeCmd = new SqlCommand(
                                    @"UPDATE FinancialYearMaster
                              SET IsDefault = 1
                              WHERE FinancialYearID = @FinancialYearID",
                                    con, tran))
                                {
                                    activeCmd.Parameters.Add("@FinancialYearID", SqlDbType.Int).Value =
                                        financialYearId;

                                    if (activeCmd.ExecuteNonQuery() <= 0)
                                        throw new Exception("Unable to activate financial year.");
                                }

                                tran.Commit();

                                AuditLogHelper.Log(
                                    module: "Financial Year",
                                    action: "UPDATE",
                                    tableName: "FinancialYearMaster",
                                    recordId: financialYearId.ToString(),
                                    description: $"Set Financial Year ID #{financialYearId} as Default Year",
                                    oldValue: oldValue,
                                    newValue: new { FinancialYearID = financialYearId, IsDefault = 1 }
                                );

                                comman.Code = 1;
                                comman.Message = "Success";
                            }
                            catch
                            {
                                if (tran.Connection != null)
                                    tran.Rollback();

                                throw;
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    AuditLogHelper.LogError("Financial Year", "ActiveFinancialYearMaster", ex);

                    comman.Code = 0;
                    comman.Message = "FAILED";
                }
            }

            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteFinancialYearMaster()
        {
            CommanResponse comman = new CommanResponse();
            JavaScriptSerializer js = new JavaScriptSerializer();

            try
            {
                int financialYearId;

                if (!int.TryParse(HttpContext.Current.Request.Params["FinancialYearIDs"], out financialYearId)
                    || financialYearId <= 0)
                {
                    comman.Code = 0;
                    comman.Message = "FAILED";
                }
                else
                {
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        con.Open();

                        using (SqlTransaction tran = con.BeginTransaction())
                        {
                            try
                            {
                                object oldValue = AuditLogHelper.FetchOldValue(
                                    "FinancialYearMaster",
                                    financialYearId.ToString(),
                                    con
                                );

                                int affectedRows;

                                using (SqlCommand cmd = new SqlCommand(
                                    "DELETE FROM FinancialYearMaster WHERE FinancialYearID = @FinancialYearID",
                                    con,
                                    tran))
                                {
                                    cmd.Parameters.Add("@FinancialYearID", SqlDbType.Int).Value = financialYearId;
                                    affectedRows = cmd.ExecuteNonQuery();
                                }

                                if (affectedRows > 0)
                                {
                                    AuditLogHelper.Log(
                                        module: "Financial Year",
                                        action: "DELETE",
                                        tableName: "FinancialYearMaster",
                                        recordId: financialYearId.ToString(),
                                        description: $"Deleted Financial Year ID #{financialYearId}",
                                        oldValue: oldValue
                                    );

                                    tran.Commit();

                                    comman.Code = 1;
                                    comman.Message = "Success";
                                }
                                else
                                {
                                    tran.Rollback();
                                    comman.Code = 0;
                                    comman.Message = "FAILED";
                                }
                            }
                            catch
                            {
                                if (tran.Connection != null)
                                    tran.Rollback();

                                throw;
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Financial Year", "DeleteFinancialYearMaster", ex);
                comman.Code = 0;
                comman.Message = "FAILED";
            }

            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
