        // View Design Entry Form
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignEntryFormMaster()
        {
            JavaScriptSerializer js;
            List<DesignEntryForm> listUser = new List<DesignEntryForm>();
            DesignEntryFormResponse response = new DesignEntryFormResponse();

            var request = HttpContext.Current.Request;
            DesignEntryForm ilist = new DesignEntryForm();

            ilist.SearchDesignNo = HttpContext.Current.Request.Params["SearchDesignNo"];
            ilist.startFrom = HttpContext.Current.Request.Params["startFrom"];


            if (ilist.SearchDesignNo != "")
            {
                ilist.SearchDesignNo = " and (DEFM.DesignNo LIKE '%" + HttpContext.Current.Request.Params["SearchDesignNo"] + "%') OR  ((CAST(DEFM.DesignerCode as nvarchar(50)) + CAST(DEFM.DesignNo as nvarchar(50))) LIKE '%" + HttpContext.Current.Request.Params["SearchDesignNo"] + "%') ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                //cmd.CommandText = "select PM.* from PartyMaster PM LEFT JOIN CompanyMaster CM ON PM.CompanyId = CM.CompanyId where CM.is_default = '1' and PM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " and PM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1) order by PM.PartyId desc OFFSET " + ilist.startFrom.ToString() + " ROWS FETCH NEXT 10 ROWS ONLY";
                cmd.CommandText = "SELECT * FROM  ( " +
                    " select ROW_NUMBER() OVER (ORDER BY DEFM.DesignEntryFormID desc ) row_num, DEFM.*,  " +
                    " WQM.WarpQuality, DM.DesignerName, SM.Sketcher, TM.Type, DCM.DesignCategory " +
                    " from DesignEntryFormMaster DEFM" +
                    " LEFT JOIN WarpQualityMaster WQM ON WQM.WarpQualityID = DEFM.WarpQualityID" +
                    " LEFT JOIN DesignerMaster DM ON DM.DesignerID = DEFM.DesignerID" +
                    " LEFT JOIN SketcherMaster SM ON SM.SketcherID = DEFM.SketcherID" +
                    " LEFT JOIN TypeMaster TM ON TM.TypeID = DEFM.TypeID" +
                    " LEFT JOIN DesignCategoryMaster DCM ON DCM.DesignCategoryID = DEFM.DesignCategoryID" +
                    " where DEFM.CompanyId = " + Context.Request.Cookies["CompanyID"].Value.Split('=')[1] + " and DEFM.FinancialYearID = " + Context.Request.Cookies["FinacialYearDefaultID"].Value.Split('=')[1] + " " +
                    " " + ilist.SearchDesignNo + " " +
                    " ) as t1  WHERE t1.row_num between " + (Convert.ToInt32(ilist.startFrom) + 1) + " and " + (Convert.ToInt32(ilist.startFrom) + 30) + "  order by t1.DesignEntryFormID desc   ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();



                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        DesignEntryForm condition = new DesignEntryForm();
                        condition.DesignEntryFormID = Convert.ToInt32(rdr["DesignEntryFormID"].ToString());
                        condition.DateandTime = Convert.ToDateTime(rdr["DateandTime"].ToString());
                        condition.DateandTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                        condition.PhotoOfDesign = rdr["PhotoOfDesign"].ToString();
                        condition.PhotoOfSketch = rdr["PhotoOfSketch"].ToString();
                        condition.WarpQualityID = Convert.ToInt32(rdr["WarpQualityID"].ToString());
                        condition.WarpQuality = rdr["WarpQuality"].ToString().ToUpper();
                        condition.DesignDate = Convert.ToDateTime(rdr["DesignDate"].ToString());
                        condition.DesignDates = Convert.ToDateTime(rdr["DesignDate"].ToString()).ToString("dd-MM-yyyy");
                        condition.DesignerID = Convert.ToInt32(rdr["DesignerID"].ToString());
                        condition.DesignerCode = rdr["DesignerCode"].ToString().ToUpper();
                        condition.DesignerName = rdr["DesignerName"].ToString().ToUpper();
                        condition.DesignNo = rdr["DesignNo"].ToString().ToUpper();
                        condition.SketcherID = Convert.ToInt32(rdr["SketcherID"].ToString());
                        condition.Sketcher = rdr["Sketcher"].ToString().ToUpper();
                        condition.Remark = rdr["Remark"].ToString().ToUpper();
                        condition.PickOnLoom = (rdr["PickOnLoom"].ToString());
                        condition.TotalCard = Convert.ToDecimal(rdr["TotalCard"].ToString());
                        condition.AveragePic = Convert.ToDecimal(rdr["AveragePic"].ToString());
                        condition.ReedOnLoom = rdr["ReedOnLoom"].ToString().ToUpper();
                        condition.TypeID = Convert.ToInt32(rdr["TypeID"].ToString());
                        condition.Type = rdr["Type"].ToString().ToUpper();
                        condition.DesignCategoryID = Convert.ToInt32(rdr["DesignCategoryID"].ToString());
                        condition.DesignCategory = rdr["DesignCategory"].ToString().ToUpper();
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 200;
            response.Message = "Success";
            response.listDesignEntryForm = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignEntryFormPaggination()
        {
            List<PagginationMaster> listUser = new List<PagginationMaster>();
            PagginationMasterResponse response = new PagginationMasterResponse();

            try
            {
                string search = HttpContext.Current.Request.Params["SearchString"] ?? "";

                int companyId;
                int financialYearId;

                if (!int.TryParse(HttpContext.Current.Request.Cookies["CompanyID"]?.Value, out companyId) ||
                    !int.TryParse(HttpContext.Current.Request.Cookies["FinacialYearDefaultID"]?.Value, out financialYearId))
                {
                    response.Code = 0;
                    response.Message = "Please Re-Login your Account.";
                }
                else
                {
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    using (SqlCommand cmd = new SqlCommand(@"
                SELECT
                    COUNT(*) AS Total,
                    CAST(
                        CEILING(
                            CAST(COUNT(*) AS DECIMAL(18,2)) / 30
                        ) AS INT
                    ) AS Paggination
                FROM DesignEntryFormMaster
                WHERE CompanyId = @CompanyId
                  AND FinancialYearID = @FinancialYearID
                  AND
                  (
                      @Search = ''
                      OR DesignNo LIKE @SearchPattern
                      OR (CAST(DesignerCode AS NVARCHAR(50)) +
                          CAST(DesignNo AS NVARCHAR(50))) LIKE @SearchPattern
                  )",
                        con))
                    {
                        cmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;
                        cmd.Parameters.Add("@FinancialYearID", SqlDbType.Int).Value = financialYearId;
                        cmd.Parameters.Add("@Search", SqlDbType.NVarChar, 200).Value = search;
                        cmd.Parameters.Add("@SearchPattern", SqlDbType.NVarChar, 402).Value = "%" + search + "%";

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            if (rdr.Read())
                            {
                                PagginationMaster item = new PagginationMaster();
                                item.Total = Convert.ToInt32(rdr["Total"]);
                                item.Paggination = Convert.ToInt32(rdr["Paggination"]);
                                listUser.Add(item);
                            }
                        }
                    }

                    response.Code = 1;
                    response.Message = "Success";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Design Entry", "getDesignEntryFormPaggination", ex);
                response.Code = 0;
                response.Message = "FAILED";
            }

            response.listPagginationMaster = listUser;

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignEntryFormDetails()
        {
            var request = HttpContext.Current.Request;
            DesignEntryFormResponse response = new DesignEntryFormResponse();
            List<DesignEntryForm> listDesignEntryForm = new List<DesignEntryForm>();

            try
            {
                string encryptedId = request.Params["DesignEntryFormID"];

                if (string.IsNullOrWhiteSpace(encryptedId))
                {
                    response.Code = 105;
                    response.Message = "Opps! Purchase Order Not Exist.";
                }
                else
                {
                    string decodedId = HttpUtility.UrlDecode(encryptedId);
                    string decryptedId;

                    if (!decodedId.EndsWith("%3d%3d", StringComparison.OrdinalIgnoreCase))
                        decodedId = decodedId.Replace("==", "") + "%3d%3d";

                    decryptedId = Decrypt(HttpUtility.UrlDecode(decodedId));

                    int designEntryFormId;
                    if (!int.TryParse(decryptedId, out designEntryFormId) || designEntryFormId <= 0)
                        throw new Exception("Invalid DesignEntryFormID.");

                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        con.Open();

                        using (SqlCommand cmd = new SqlCommand(@"
                    SELECT DEFM.*, WQM.WarpQuality, DM.DesignerName,
                           SM.Sketcher, TM.Type, DCM.DesignCategory
                    FROM DesignEntryFormMaster DEFM
                    LEFT JOIN WarpQualityMaster WQM ON WQM.WarpQualityID = DEFM.WarpQualityID
                    LEFT JOIN DesignerMaster DM ON DM.DesignerID = DEFM.DesignerID
                    LEFT JOIN SketcherMaster SM ON SM.SketcherID = DEFM.SketcherID
                    LEFT JOIN TypeMaster TM ON TM.TypeID = DEFM.TypeID
                    LEFT JOIN DesignCategoryMaster DCM ON DCM.DesignCategoryID = DEFM.DesignCategoryID
                    WHERE DEFM.DesignEntryFormID = @DesignEntryFormID",
                            con))
                        {
                            cmd.Parameters.Add("@DesignEntryFormID", SqlDbType.Int).Value = designEntryFormId;

                            using (SqlDataReader rdr = cmd.ExecuteReader())
                            {
                                while (rdr.Read())
                                {
                                    DesignEntryForm item = new DesignEntryForm();

                                    item.DesignEntryFormID = Convert.ToInt32(rdr["DesignEntryFormID"]);
                                    item.DateandTime = Convert.ToDateTime(rdr["DateandTime"]);
                                    item.DateandTimes = Convert.ToDateTime(rdr["DateandTime"]).ToString("dd-MM-yyyy");
                                    item.DesignDate = Convert.ToDateTime(rdr["DesignDate"]);
                                    item.DesignDates = Convert.ToDateTime(rdr["DesignDate"]).ToString("yyyy-MM-dd");
                                    item.PhotoOfDesign = Convert.ToString(rdr["PhotoOfDesign"]).ToUpper();
                                    item.PhotoOfSketch = Convert.ToString(rdr["PhotoOfSketch"]).ToUpper();
                                    item.WarpQualityID = Convert.ToInt32(rdr["WarpQualityID"]);
                                    item.WarpQuality = Convert.ToString(rdr["WarpQuality"]).ToUpper();
                                    item.DesignerID = Convert.ToInt32(rdr["DesignerID"]);
                                    item.DesignerName = Convert.ToString(rdr["DesignerName"]).ToUpper();
                                    item.DesignerCode = Convert.ToString(rdr["DesignerCode"]).ToUpper();
                                    item.DesignNo = Convert.ToString(rdr["DesignNo"]).ToUpper();
                                    item.Remark = Convert.ToString(rdr["Remark"]).ToUpper();
                                    item.PickOnLoom = Convert.ToString(rdr["PickOnLoom"]);
                                    item.TotalCard = Convert.ToDecimal(rdr["TotalCard"]);
                                    item.AveragePic = Convert.ToDecimal(rdr["AveragePic"]);
                                    item.ReedOnLoom = Convert.ToString(rdr["ReedOnLoom"]).ToUpper();
                                    item.TypeID = Convert.ToInt32(rdr["TypeID"]);
                                    item.Type = Convert.ToString(rdr["Type"]).ToUpper();
                                    item.DesignCategoryID = Convert.ToInt32(rdr["DesignCategoryID"]);
                                    item.DesignCategory = Convert.ToString(rdr["DesignCategory"]).ToUpper();
                                    item.SketcherID = Convert.ToInt32(rdr["SketcherID"]);
                                    item.Sketcher = Convert.ToString(rdr["Sketcher"]).ToUpper();
                                    item.DesignCut = Convert.ToString(rdr["DesignCut"]).ToUpper();
                                    item.SaleRate = Convert.ToDecimal(rdr["SaleRate"]);
                                    item.HSNCode = Convert.ToString(rdr["HSNCode"]);
                                    item.BarcodeNo = Convert.ToString(rdr["BarcodeNo"]).ToUpper();

                                    listDesignEntryForm.Add(item);
                                }
                            }
                        }

                        if (listDesignEntryForm.Count > 0)
                        {
                            DesignEntryForm item = listDesignEntryForm[0];

                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT DEWD.*, YMM.YarnMaterial, DSM.DesignSpecification
                        FROM DesignEntryWeftData DEWD
                        LEFT JOIN YarnMaterialMaster YMM ON YMM.YarnMaterialID = DEWD.YarnMaterialID
                        LEFT JOIN DesignSpecificationMaster DSM ON DSM.DesignSpecificationID = DEWD.DesignSpecificationID
                        WHERE DEWD.DesignEntryFormID = @DesignEntryFormID",
                                con))
                            {
                                cmd.Parameters.Add("@DesignEntryFormID", SqlDbType.Int).Value = designEntryFormId;

                                using (SqlDataReader rdr = cmd.ExecuteReader())
                                {
                                    List<DesignEntryWeftData> weftList = new List<DesignEntryWeftData>();

                                    while (rdr.Read())
                                    {
                                        DesignEntryWeftData weft = new DesignEntryWeftData();
                                        weft.DesignEntryWeftID = Convert.ToInt32(rdr["DesignEntryWeftID"]);
                                        weft.Card = Convert.ToDecimal(rdr["Card"]);
                                        weft.Pick = Convert.ToDecimal(rdr["Pick"]);
                                        weft.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"]);
                                        weft.DesignSpecificationID = Convert.ToInt32(rdr["DesignSpecificationID"]);
                                        weft.YarnMaterial = Convert.ToString(rdr["YarnMaterial"]).ToUpper();
                                        weft.DesignSpecification = Convert.ToString(rdr["DesignSpecification"]).ToUpper();
                                        weftList.Add(weft);
                                    }

                                    item.listDesignEntryWeftData = weftList;
                                }
                            }

                            using (SqlCommand cmd = new SqlCommand(@"
                        SELECT DFED.*, YMM.YarnMaterial
                        FROM DesignFormWarpData DFED
                        LEFT JOIN YarnMaterialMaster YMM ON YMM.YarnMaterialID = DFED.YarnQualityMaterialID
                        WHERE DFED.DesignEntryFormID = @DesignEntryFormID",
                                con))
                            {
                                cmd.Parameters.Add("@DesignEntryFormID", SqlDbType.Int).Value = designEntryFormId;

                                using (SqlDataReader rdr = cmd.ExecuteReader())
                                {
                                    List<DesignFormWarpData> warpList = new List<DesignFormWarpData>();

                                    while (rdr.Read())
                                    {
                                        DesignFormWarpData warp = new DesignFormWarpData();
                                        warp.DesignEntryWarpID = Convert.ToInt32(rdr["DesignEntryWarpID"]);
                                        warp.YarnQualityMaterialID = Convert.ToInt32(rdr["YarnQualityMaterialID"]);
                                        warp.Tar = Convert.ToInt32(rdr["Tar"]);
                                        warp.YarnMaterial = Convert.ToString(rdr["YarnMaterial"]).ToUpper();
                                        warpList.Add(warp);
                                    }

                                    item.listDesignFormWarpData = warpList;
                                }
                            }

                            response.Code = 200;
                            response.Message = "Success";
                            response.listDesignEntryForm = listDesignEntryForm;
                        }
                        else
                        {
                            response.Code = 105;
                            response.Message = "Opps! Purchase Order Not Exist.";
                            response.listDesignEntryForm = listDesignEntryForm;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Design Entry", "getDesignEntryFormDetails", ex);
                response.Code = 500;
                response.Message = "FAILED";
                response.listDesignEntryForm = listDesignEntryForm;
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }

