        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteDesignEntryFormMaster()
        {
            CommanResponse response = new CommanResponse();
            JavaScriptSerializer js = new JavaScriptSerializer();

            try
            {
                int designEntryFormId;

                if (!int.TryParse(HttpContext.Current.Request.Params["DesignEntryFormID"], out designEntryFormId) ||
                    designEntryFormId <= 0)
                {
                    response.Code = 0;
                    response.Message = "FAILED";
                }
                else
                {
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        con.Open();

                        using (SqlTransaction tran = con.BeginTransaction())
                        {
                            try
                            {
                                object oldValue = AuditLogHelper.FetchOldValue(
                                    "DesignEntryFormMaster",
                                    designEntryFormId.ToString(),
                                    con
                                );

                                int affectedRows;

                                using (SqlCommand cmd = new SqlCommand(
                                    "DELETE FROM DesignEntryFormMaster WHERE DesignEntryFormID = @DesignEntryFormID",
                                    con,
                                    tran))
                                {
                                    cmd.Parameters.Add("@DesignEntryFormID", SqlDbType.Int).Value = designEntryFormId;
                                    affectedRows = cmd.ExecuteNonQuery();
                                }

                                if (affectedRows > 0)
                                {
                                    AuditLogHelper.Log(
                                        module: "Design Entry",
                                        action: "DELETE",
                                        tableName: "DesignEntryFormMaster",
                                        recordId: designEntryFormId.ToString(),
                                        description: $"Deleted Design Entry ID #{designEntryFormId}",
                                        oldValue: oldValue
                                    );

                                    tran.Commit();
                                    response.Code = 200;
                                    response.Message = "Record has been deleted successfully";
                                }
                                else
                                {
                                    tran.Rollback();
                                    response.Code = 0;
                                    response.Message = "FAILED";
                                }
                            }
                            catch
                            {
                                if (tran.Connection != null)
                                    tran.Rollback();

                                throw;
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Design Entry", "DeleteDesignEntryFormMaster", ex);
                response.Code = 0;
                response.Message = "FAILED";
            }

            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateDesignEntryFormMaster()
        {
            CommanResponse comman = new CommanResponse();

            try
            {
                HttpRequest request = HttpContext.Current.Request;

                string json = request.Params["DesignEntryForm"];
                string userCookie = request.Cookies["UserIDs"]?.Value.Split('=')[1];
                string companyCookie = request.Cookies["CompanyID"]?.Value.Split('=')[1];
                string financialYearCookie = request.Cookies["FinacialYearDefaultID"]?.Value.Split('=')[1];

                int userId, companyId, financialYearId;       

                if (!int.TryParse(userCookie, out userId) ||
                    !int.TryParse(companyCookie, out companyId) ||
                    !int.TryParse(financialYearCookie, out financialYearId))
                {
                    comman.Code = 500;
                    comman.Message = "Please Re-Login your Account.";
                }
                else if (string.IsNullOrWhiteSpace(json))
                {
                    comman.Code = 500;
                    comman.Message = "Something is missing, while submitting your data.";
                }
                else
                {
                    DesignEntryForm myDetails =
                        JsonConvert.DeserializeObject<DesignEntryForm>(json);

                    if (myDetails == null || myDetails.DesignEntryFormID <= 0)
                        throw new Exception("Invalid Design Entry data.");

                    DateTime indianDateTime =
                        TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

                    DateTime designDate;
                    if (!DateTime.TryParseExact(
                        myDetails.DesignDates,
                        "dd/MM/yyyy",
                        CultureInfo.InvariantCulture,
                        DateTimeStyles.None,
                        out designDate))
                    {
                        comman.Code = 500;
                        comman.Message = "Invalid Design Date.";
                    }
                    else
                    {
                        string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                        using (SqlConnection con = new SqlConnection(cs))
                        {
                            con.Open();

                            using (SqlTransaction tran = con.BeginTransaction())
                            {
                                try
                                {
                                    object oldDesignEntry;

                                    using (SqlCommand oldCmd = new SqlCommand(@"
                                SELECT *
                                FROM DesignEntryFormMaster
                                WHERE DesignEntryFormID = @ID",
                                        con, tran))
                                    {
                                        oldCmd.Parameters.Add("@ID", SqlDbType.Int).Value =
                                            myDetails.DesignEntryFormID;

                                        using (SqlDataReader rdr = oldCmd.ExecuteReader())
                                        {
                                            if (!rdr.Read())
                                                throw new Exception("Design Entry record not found.");

                                            oldDesignEntry = new
                                            {
                                                DesignEntryFormID = myDetails.DesignEntryFormID,
                                                DesignerCode = rdr["DesignerCode"],
                                                DesignNo = rdr["DesignNo"],
                                                WarpQualityID = rdr["WarpQualityID"],
                                                DesignerID = rdr["DesignerID"],
                                                SketcherID = rdr["SketcherID"],
                                                TypeID = rdr["TypeID"],
                                                DesignCategoryID = rdr["DesignCategoryID"],
                                                TotalCard = rdr["TotalCard"],
                                                AveragePic = rdr["AveragePic"],
                                                DesignCut = rdr["DesignCut"],
                                                SaleRate = rdr["SaleRate"],
                                                HSNCode = rdr["HSNCode"],
                                                BarcodeNo = rdr["BarcodeNo"]
                                            };

                                            myDetails.PhotoOfDesign = Convert.ToString(rdr["PhotoOfDesign"]);
                                            myDetails.PhotoOfSketch = Convert.ToString(rdr["PhotoOfSketch"]);
                                        }
                                    }

                                    using (SqlCommand duplicateCmd = new SqlCommand(@"
                                SELECT COUNT(1)
                                FROM DesignEntryFormMaster
                                WHERE DesignerCode = @DesignerCode
                                  AND DesignNo = @DesignNo
                                  AND CompanyId = @CompanyId
                                  AND FinancialYearID = @FinancialYearID
                                  AND DesignEntryFormID <> @ID",
                                        con, tran))
                                    {
                                        duplicateCmd.Parameters.Add("@DesignerCode", SqlDbType.NVarChar, 50).Value =
                                            (object)myDetails.DesignerCode ?? DBNull.Value;
                                        duplicateCmd.Parameters.Add("@DesignNo", SqlDbType.NVarChar, 50).Value =
                                            (object)myDetails.DesignNo ?? DBNull.Value;
                                        duplicateCmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;
                                        duplicateCmd.Parameters.Add("@FinancialYearID", SqlDbType.Int).Value = financialYearId;
                                        duplicateCmd.Parameters.Add("@ID", SqlDbType.Int).Value =
                                            myDetails.DesignEntryFormID;

                                        if (Convert.ToInt32(duplicateCmd.ExecuteScalar()) > 0)
                                        {
                                            tran.Rollback();
                                            comman.Code = 405;
                                            comman.Message = "This Entry is already exists.";
                                            JavaScriptSerializer jsDup = new JavaScriptSerializer();
                                            jsDup.MaxJsonLength = Int32.MaxValue;
                                            Context.Response.Write(jsDup.Serialize(comman));
                                            return;
                                        }
                                    }

                                    string designImage = myDetails.PhotoOfDesign;
                                    string sketchImage = myDetails.PhotoOfSketch;

                                    if (request.Files["PhotoOfDesign"] != null &&
                                        request.Files["PhotoOfDesign"].ContentLength > 0 &&
                                        string.IsNullOrEmpty(myDetails.tempPhotoOfDesign))
                                    {
                                        HttpPostedFile file = request.Files["PhotoOfDesign"];
                                        string folder = HttpContext.Current.Server.MapPath("~/PhotoOfDesign/");

                                        if (!Directory.Exists(folder))
                                            Directory.CreateDirectory(folder);

                                        designImage = "PhotoOfDesign/" +
                                            RandomString(6, true) + Path.GetFileName(file.FileName);

                                        file.SaveAs(Path.Combine(folder, Path.GetFileName(designImage)));
                                    }
                                    else if (!string.IsNullOrEmpty(myDetails.tempPhotoOfDesign))
                                    {
                                        designImage = myDetails.tempPhotoOfDesign;
                                    }

                                    if (request.Files["PhotoOfSketch"] != null &&
                                        request.Files["PhotoOfSketch"].ContentLength > 0 &&
                                        string.IsNullOrEmpty(myDetails.tempPhotoOfSketch))
                                    {
                                        HttpPostedFile file = request.Files["PhotoOfSketch"];
                                        string folder = HttpContext.Current.Server.MapPath("~/PhotoOfSketch/");

                                        if (!Directory.Exists(folder))
                                            Directory.CreateDirectory(folder);

                                        sketchImage = "PhotoOfSketch/" +
                                            RandomString(6, true) + Path.GetFileName(file.FileName);

                                        file.SaveAs(Path.Combine(folder, Path.GetFileName(sketchImage)));
                                    }
                                    else if (!string.IsNullOrEmpty(myDetails.tempPhotoOfSketch))
                                    {
                                        sketchImage = myDetails.tempPhotoOfSketch;
                                    }
                                    else if (request.Files["PhotoOfSketch"] != null &&
                                             request.Files["PhotoOfSketch"].ContentLength == 0)
                                    {
                                        sketchImage = "";
                                    }

                                    using (SqlCommand cmd = new SqlCommand(@"
                                UPDATE DesignEntryFormMaster
                                SET DateandTime = @DateandTime,
                                    UserAccountId = @UserAccountId,
                                    CompanyId = @CompanyId,
                                    PhotoOfDesign = @PhotoOfDesign,
                                    PhotoOfSketch = @PhotoOfSketch,
                                    WarpQualityID = @WarpQualityID,
                                    DesignDate = @DesignDate,
                                    DesignerID = @DesignerID,
                                    SketcherID = @SketcherID,
                                    DesignerCode = @DesignerCode,
                                    DesignNo = @DesignNo,
                                    Remark = @Remark,
                                    PickOnLoom = @PickOnLoom,
                                    TotalCard = @TotalCard,
                                    AveragePic = @AveragePic,
                                    ReedOnLoom = @ReedOnLoom,
                                    TypeID = @TypeID,
                                    DesignCategoryID = @DesignCategoryID,
                                    DesignCut = @DesignCut,
                                    SaleRate = @SaleRate,
                                    HSNCode = @HSNCode,
                                    BarcodeNo = @BarcodeNo
                                WHERE DesignEntryFormID = @ID",
                                        con, tran))
                                    {
                                        cmd.Parameters.Add("@DateandTime", SqlDbType.DateTime).Value = indianDateTime;
                                        cmd.Parameters.Add("@UserAccountId", SqlDbType.Int).Value = userId;
                                        cmd.Parameters.Add("@CompanyId", SqlDbType.Int).Value = companyId;
                                        cmd.Parameters.Add("@PhotoOfDesign", SqlDbType.NVarChar, 500).Value =
                                            (object)designImage ?? DBNull.Value;
                                        cmd.Parameters.Add("@PhotoOfSketch", SqlDbType.NVarChar, 500).Value =
                                            (object)sketchImage ?? DBNull.Value;
                                        cmd.Parameters.Add("@WarpQualityID", SqlDbType.Int).Value = myDetails.WarpQualityID;
                                        cmd.Parameters.Add("@DesignDate", SqlDbType.Date).Value = designDate;
                                        cmd.Parameters.Add("@DesignerID", SqlDbType.Int).Value = myDetails.DesignerID;
                                        cmd.Parameters.Add("@SketcherID", SqlDbType.Int).Value = myDetails.SketcherID;
                                        cmd.Parameters.Add("@DesignerCode", SqlDbType.NVarChar, 50).Value =
                                            (object)myDetails.DesignerCode ?? DBNull.Value;
                                        cmd.Parameters.Add("@DesignNo", SqlDbType.NVarChar, 50).Value =
                                            (object)myDetails.DesignNo ?? DBNull.Value;
                                        cmd.Parameters.Add("@Remark", SqlDbType.NVarChar, -1).Value =
                                            (object)myDetails.Remark ?? DBNull.Value;
                                        cmd.Parameters.Add("@PickOnLoom", SqlDbType.NVarChar, 100).Value =
                                            (object)myDetails.PickOnLoom ?? "0";
                                        cmd.Parameters.Add("@TotalCard", SqlDbType.Decimal).Value = myDetails.TotalCard;
                                        cmd.Parameters.Add("@AveragePic", SqlDbType.Decimal).Value = myDetails.AveragePic;
                                        cmd.Parameters.Add("@ReedOnLoom", SqlDbType.NVarChar, 100).Value =
                                            (object)myDetails.ReedOnLoom ?? DBNull.Value;
                                        cmd.Parameters.Add("@TypeID", SqlDbType.Int).Value = myDetails.TypeID;
                                        cmd.Parameters.Add("@DesignCategoryID", SqlDbType.Int).Value = myDetails.DesignCategoryID;
                                        cmd.Parameters.Add("@DesignCut", SqlDbType.Decimal).Value = myDetails.DesignCut;
                                        cmd.Parameters.Add("@SaleRate", SqlDbType.Decimal).Value = myDetails.SaleRate;
                                        cmd.Parameters.Add("@HSNCode", SqlDbType.NVarChar, 50).Value =
                                            (object)myDetails.HSNCode ?? DBNull.Value;
                                        cmd.Parameters.Add("@BarcodeNo", SqlDbType.NVarChar, 100).Value =
                                            (object)myDetails.BarcodeNo ?? DBNull.Value;
                                        cmd.Parameters.Add("@ID", SqlDbType.Int).Value = myDetails.DesignEntryFormID;

                                        if (cmd.ExecuteNonQuery() <= 0)
                                            throw new Exception("Design Entry update failed.");
                                    }

                                    if (myDetails.listDesignEntryWeftData != null)
                                    {
                                        using (SqlCommand deleteCmd = new SqlCommand(
                                            "DELETE FROM DesignEntryWeftData WHERE DesignEntryFormID = @ID",
                                            con, tran))
                                        {
                                            deleteCmd.Parameters.Add("@ID", SqlDbType.Int).Value =
                                                myDetails.DesignEntryFormID;
                                            deleteCmd.ExecuteNonQuery();
                                        }

                                        foreach (DesignEntryWeftData each in myDetails.listDesignEntryWeftData)
                                        {
                                            using (SqlCommand cmd = new SqlCommand(@"
                                        INSERT INTO DesignEntryWeftData
                                        (DesignEntryFormID, Card, Pick, YarnMaterialID, DesignSpecificationID)
                                        VALUES
                                        (@ID, @Card, @Pick, @YarnMaterialID, @DesignSpecificationID)",
                                                con, tran))
                                            {
                                                cmd.Parameters.Add("@ID", SqlDbType.Int).Value = myDetails.DesignEntryFormID;
                                                cmd.Parameters.Add("@Card", SqlDbType.Decimal).Value = each.Card;
                                                cmd.Parameters.Add("@Pick", SqlDbType.Decimal).Value = each.Pick;
                                                cmd.Parameters.Add("@YarnMaterialID", SqlDbType.Int).Value = each.YarnMaterialID;
                                                cmd.Parameters.Add("@DesignSpecificationID", SqlDbType.Int).Value =
                                                    each.DesignSpecification;

                                                cmd.ExecuteNonQuery();
                                            }
                                        }
                                    }

                                    if (myDetails.listDesignFormWarpData != null)
                                    {
                                        using (SqlCommand deleteCmd = new SqlCommand(
                                            "DELETE FROM DesignFormWarpData WHERE DesignEntryFormID = @ID",
                                            con, tran))
                                        {
                                            deleteCmd.Parameters.Add("@ID", SqlDbType.Int).Value =
                                                myDetails.DesignEntryFormID;
                                            deleteCmd.ExecuteNonQuery();
                                        }

                                        foreach (DesignFormWarpData each in myDetails.listDesignFormWarpData)
                                        {
                                            using (SqlCommand cmd = new SqlCommand(@"
                                        INSERT INTO DesignFormWarpData
                                        (DesignEntryFormID, YarnQualityMaterialID, Tar)
                                        VALUES
                                        (@ID, @YarnQualityMaterialID, @Tar)",
                                                con, tran))
                                            {
                                                cmd.Parameters.Add("@ID", SqlDbType.Int).Value = myDetails.DesignEntryFormID;
                                                cmd.Parameters.Add("@YarnQualityMaterialID", SqlDbType.Int).Value =
                                                    each.YarnQualityID;
                                                cmd.Parameters.Add("@Tar", SqlDbType.Int).Value = each.Tar;
                                                cmd.ExecuteNonQuery();
                                            }
                                        }
                                    }

                                    AuditLogHelper.Log(
                                        module: "Design Entry",
                                        action: "UPDATE",
                                        tableName: "DesignEntryFormMaster",
                                        recordId: myDetails.DesignEntryFormID.ToString(),
                                        description: $"Updated Design Entry ID #{myDetails.DesignEntryFormID}: DesignerCode={myDetails.DesignerCode}, DesignNo={myDetails.DesignNo}",
                                        oldValue: oldDesignEntry,
                                        newValue: new
                                        {
                                            myDetails.DesignEntryFormID,
                                            myDetails.DesignerCode,
                                            myDetails.DesignNo,
                                            myDetails.WarpQualityID,
                                            myDetails.DesignerID,
                                            myDetails.SketcherID,
                                            myDetails.TypeID,
                                            myDetails.DesignCategoryID,
                                            myDetails.TotalCard,
                                            myDetails.AveragePic,
                                            myDetails.DesignCut,
                                            myDetails.SaleRate,
                                            myDetails.HSNCode,
                                            myDetails.BarcodeNo
                                        },
                                        existingConn: con
                                    );

                                    tran.Commit();

                                    comman.id = Convert.ToInt32(myDetails.DesignEntryFormID);
                                    comman.Code = 200;
                                    comman.Message = "Record has been updated successfully";
                                }
                                catch (Exception ex)
                                {
                                    if (tran.Connection != null)
                                        tran.Rollback();

                                    throw;
                                }
                            }
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError("Design Entry", "UpdateDesignEntryFormMaster", ex);

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "This Entry is already exists.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Design Entry", "UpdateDesignEntryFormMaster", ex);
                comman.Code = 500;
                comman.Message = "Problem has been occurred while submitting your data.";
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
