        #region Create Design Color Matching (CreateDesignColorMatching.cshtml)
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignNoForm()
        {
            var request = HttpContext.Current.Request;

            List<DesignEntryForm> listDesignerMaster = new List<DesignEntryForm>();
            DesignEntryFormResponse response = new DesignEntryFormResponse();

            try
            {
                string matchingCookie =
                    Context.Request.Cookies["DesignColorMatchingFormIDs"]?.Value;

                int designColorMatchingFormId = 0;

                if (!string.IsNullOrEmpty(matchingCookie) &&
                    !int.TryParse(matchingCookie, out designColorMatchingFormId))
                {
                    response.Code = 400;
                    response.Message = "Invalid Design Color Matching ID.";
                }
                else
                {
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                    using (SqlConnection con = new SqlConnection(cs))
                    using (SqlCommand cmd = new SqlCommand(@"
                SELECT DEFM.*,
                       ISNULL(DCMFM.DesignColorMatchingFormID, 0) AS DesignColorMatchingFormID
                FROM DesignEntryFormMaster DEFM
                LEFT JOIN DesignColorMatchingFormMaster DCMFM
                    ON DCMFM.DesignEntryFormID = DEFM.DesignEntryFormID
                WHERE NOT EXISTS
                (
                    SELECT 1
                    FROM DesignColorMatchingFormMaster DCM
                    WHERE DCM.DesignEntryFormID = DEFM.DesignEntryFormID
                )
                ORDER BY DEFM.DesignEntryFormID DESC",
                        con))
                    {
                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                DesignEntryForm item = new DesignEntryForm();

                                item.DesignEntryFormID = Convert.ToInt32(rdr["DesignEntryFormID"]);
                                item.DesignColorMatchingFormID =
                                    Convert.ToInt32(rdr["DesignColorMatchingFormID"]);
                                item.DesignColorMatchingFormIDs = designColorMatchingFormId;
                                item.DesignNo = Convert.ToString(rdr["DesignNo"]).ToUpper();
                                item.DesignerCode = Convert.ToString(rdr["DesignerCode"]).ToUpper();

                                listDesignerMaster.Add(item);
                            }
                        }
                    }

                    response.Code = 200;
                    response.Message = "Success";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Design Entry", "getDesignNoForm", ex);
                response.Code = 500;
                response.Message = "FAILED";
            }

            response.listDesignEntryForm = listDesignerMaster;

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }
