                                        tableName: "PartyMaster",
                                        recordId: PartyId.ToString(),
                                        description: $"Created Party: {ilist.PartyName}",
                                        newValue: ilist,
                                        conn: con,
                                        tran: trans
                                    );

                                    trans.Commit();

                                    comman.Code = 201;
                                    comman.Message = "Record has been saved successfully.";
                                    comman.id = Convert.ToInt32(PartyId);
                                    WriteJsonResponse(comman);
                                    return;
                                }
                                else
                                {
                                    trans.Rollback();
                                    comman.Code = 410;
                                    comman.Message = "Problem has occurred while submitting your data.";
                                    AuditLogHelper.LogValidationError("Party Master", "PartyMaster", null, "Failed to insert Party Master record (PartyId <= 0)", errorMessage: comman.Message, requestData: ilist);
                                    WriteJsonResponse(comman);
                                    return;
                                }
                            }
                        }
                        catch
