        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getPartyMasterPaggination()
        {
            JavaScriptSerializer js;
            List<PagginationMaster> listUser = new List<PagginationMaster>();
            PagginationMasterResponce response = new PagginationMasterResponce();

            string SearchString = HttpContext.Current.Request.Params["PartyName"] ?? "";

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();

                int UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
                int CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);

                int PartyId = 0;

                // Get PartyId
                SqlCommand cmdParty = new SqlCommand(
                    "SELECT ISNULL(PartyId,0) FROM UserAccountMaster WHERE UserAccountId=@UserAccountId",
                    con);

                cmdParty.Parameters.AddWithValue("@UserAccountId", UserAccountId);

                object obj = cmdParty.ExecuteScalar();

                if (obj != null)
                    PartyId = Convert.ToInt32(obj);

                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;

                string SearchCondition = "";
                string PartyFilter = "";

                if (!string.IsNullOrWhiteSpace(SearchString))
                {
                    SearchCondition = @"
            AND (
                    PartyName LIKE @SearchText
                 OR GSTIN LIKE @SearchText
                 OR MobileNo LIKE @SearchText
                )";

                    cmd.Parameters.AddWithValue("@SearchText", "%" + SearchString + "%");
                }

                // If Job Work User
                if (PartyId > 0)
                {
                    PartyFilter = " AND PartyId = @PartyId ";
                    cmd.Parameters.AddWithValue("@PartyId", PartyId);
                }

                cmd.Parameters.AddWithValue("@CompanyId", CompanyId);

                cmd.CommandText = @"
        SELECT
            COUNT(*) AS Total,
            CEILING(COUNT(*) / 10.0) AS Paggination
        FROM PartyMaster
        WHERE CompanyId = @CompanyId
        " + PartyFilter + SearchCondition;

                SqlDataReader rdr = cmd.ExecuteReader();

                while (rdr.Read())
                {
                    listUser.Add(new PagginationMaster
                    {
                        Total = Convert.ToInt32(rdr["Total"]),
                        Paggination = Convert.ToInt32(rdr["Paggination"])
                    });
                }

                rdr.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listPagginationMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }
        // View Party Master
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getPartyMaster()
        {
            JavaScriptSerializer js;
            List<PartyMaster> listUser = new List<PartyMaster>();
            PartyMasterResponse response = new PartyMasterResponse();

            try
            {
                var request = HttpContext.Current.Request;

                PartyMaster ilist = new PartyMaster();

                ilist.PartyName = request.Params["searchpartyname"] ?? "";
                ilist.startFrom = request.Params["startFrom"] ?? "0";

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    int UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
                    int CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);

                    int PartyId = 0;
                    string UserRole = "";

                    #region Get User PartyId & UserRole

                    using (SqlCommand cmdUser = new SqlCommand())
                    {
                        cmdUser.Connection = con;
                        cmdUser.CommandType = CommandType.Text;
                        cmdUser.CommandText = @"
                    SELECT 
                        ISNULL(PartyId,0) AS PartyId,
                        ISNULL(UserRole,'') AS UserRole
                    FROM UserAccountMaster
                    WHERE UserAccountId = @UserAccountId";

                        cmdUser.Parameters.AddWithValue("@UserAccountId", UserAccountId);

                        SqlDataReader drUser = cmdUser.ExecuteReader();

                        if (drUser.Read())
                        {
                            PartyId = Convert.ToInt32(drUser["PartyId"]);
                            UserRole = drUser["UserRole"].ToString();
                        }

                        drUser.Close();
                    }

                    #endregion

                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.CommandType = CommandType.Text;

                    string searchCondition = "";
                    string partyCondition = "";

                    #region Search Filter

                    if (!string.IsNullOrWhiteSpace(ilist.PartyName))
                    {
                        searchCondition = @"
                    AND (
                        PartyName LIKE @SearchText
                        OR MobileNo LIKE @SearchText
                        OR GSTIN LIKE @SearchText
                    )";

                        cmd.Parameters.AddWithValue("@SearchText", "%" + ilist.PartyName.Trim() + "%");
                    }

                    #endregion

                    #region Job Work Party Restriction

                    if (UserRole.ToUpper() == "JOB WORK" && PartyId > 0)
                    {
                        partyCondition = " AND PartyId = @PartyId ";
                        cmd.Parameters.AddWithValue("@PartyId", PartyId);
                    }

                    #endregion

                    int startRow = Convert.ToInt32(ilist.startFrom) + 1;
                    int endRow = Convert.ToInt32(ilist.startFrom) + 10;

                    cmd.Parameters.AddWithValue("@CompanyId", CompanyId);
                    cmd.Parameters.AddWithValue("@StartRow", startRow);
                    cmd.Parameters.AddWithValue("@EndRow", endRow);

                    cmd.CommandText = @"
                SELECT *
                FROM
                (
                    SELECT
                        ROW_NUMBER() OVER (ORDER BY PartyId DESC) AS row_num,
                        PartyId,
                        DateandTime,
                        PartyName,
                        MobileNo,
                        AlterMobileNo,
                        BillingAddress,
                        ShippingAddress,
                        IsSameAddress,
                        GSTIN,
                        PAN,
                        State,
                        City,
                        Pincode,
                        BankHolderName,
                        BankAccountNo,
                        BankIFSCCode,
                        BankName,
                        BankBranch,
                        SundryParty,
                        IsActiveParty
                    FROM PartyMaster
                    WHERE CompanyId = @CompanyId
                    " + partyCondition + @"
                    " + searchCondition + @"
                ) t1
                WHERE t1.row_num BETWEEN @StartRow AND @EndRow
                ORDER BY PartyId DESC";

                    SqlDataReader rdr = cmd.ExecuteReader();

                    while (rdr.Read())
                    {
                        PartyMaster condition = new PartyMaster();

                        condition.PartyId = Convert.ToInt32(rdr["PartyId"]);
                        condition.DateandTime = Convert.ToDateTime(rdr["DateandTime"]);
                        condition.DateandTimes = Convert.ToDateTime(rdr["DateandTime"]).ToString("dd-MM-yyyy");

                        condition.PartyName = rdr["PartyName"].ToString().ToUpper();
                        condition.MobileNo = rdr["MobileNo"].ToString().ToUpper();
                        condition.AlterMobileNo = rdr["AlterMobileNo"].ToString().ToUpper();

                        condition.BillingAddress = rdr["BillingAddress"].ToString().ToUpper();
                        condition.ShippingAddress = rdr["ShippingAddress"].ToString().ToUpper();

                        condition.IsSameAddress = Convert.ToInt32(rdr["IsSameAddress"]);

                        condition.GSTIN = rdr["GSTIN"].ToString().ToUpper();
                        condition.PanNo = rdr["PAN"].ToString().ToUpper();

                        condition.State = rdr["State"].ToString().ToUpper();
                        condition.City = rdr["City"].ToString().ToUpper();
                        condition.Pincode = rdr["Pincode"].ToString().ToUpper();

                        condition.BankHolderName = rdr["BankHolderName"].ToString().ToUpper();
                        condition.BankAccountNo = rdr["BankAccountNo"].ToString().ToUpper();
                        condition.BankIFSCCode = rdr["BankIFSCCode"].ToString().ToUpper();

                        condition.BankName = rdr["BankName"].ToString().ToUpper();
                        condition.BankBranch = rdr["BankBranch"].ToString().ToUpper();

                        condition.SundryParty = rdr["SundryParty"].ToString().ToUpper();

                        condition.IsActiveParty = Convert.ToInt32(rdr["IsActiveParty"]);

                        listUser.Add(condition);
                    }

                    rdr.Close();
                    cmd.Dispose();
                }

                response.Code = 200;
                response.Message = "Success";
                response.listPartyMaster = listUser;
            }
            catch (Exception ex)
            {
                response.Code = 500;
                response.Message = ex.Message;
                response.listPartyMaster = new List<PartyMaster>();
            }

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;

            Context.Response.Write(js.Serialize(response));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getPartyMasterById(string id)
        {
            JavaScriptSerializer js;
            List<PartyMaster> listUser = new List<PartyMaster>();
            PartyMasterResponse response = new PartyMasterResponse();

            // Safety guard to check cookie presence before processing substring operations
            int CompanyId = 0;
            if (Context.Request.Cookies["CompanyID"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["CompanyID"].Value))
            {
                string cookieVal = Context.Request.Cookies["CompanyID"].Value;
                CompanyId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;

                // FIX: Secure Parameterized SQL string pattern instead of string concatenations
                cmd.CommandText = "SELECT * FROM PartyMaster WHERE CompanyId = @CompanyId AND PartyId = @PartyId";

                cmd.Parameters.AddWithValue("@CompanyId", CompanyId);
                cmd.Parameters.AddWithValue("@PartyId", Convert.ToInt64(id));

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        PartyMaster condition = new PartyMaster();
                        condition.PartyId = Convert.ToInt32(rdr["PartyId"].ToString());
                        condition.PartyName = rdr["PartyName"].ToString().ToUpper();
                        condition.MobileNo = rdr["MobileNo"].ToString().ToUpper();
                        condition.AlterMobileNo = rdr["AlterMobileNo"].ToString().ToUpper();
                        condition.Email = rdr["Email"].ToString().ToUpper();
                        condition.State = rdr["State"].ToString().ToUpper();
                        condition.City = rdr["City"].ToString().ToUpper();
                        condition.Pincode = rdr["Pincode"].ToString().ToUpper();
                        condition.BillingAddress = rdr["BillingAddress"].ToString().ToUpper();
                        condition.ShippingAddress = rdr["ShippingAddress"].ToString().ToUpper();
                        condition.IsSameAddress = Convert.ToInt32(rdr["IsSameAddress"].ToString());
                        condition.GSTIN = rdr["GSTIN"].ToString().ToUpper();
                        condition.PanNo = rdr["PAN"].ToString().ToUpper();
                        condition.CompanyId = Convert.ToInt32(rdr["CompanyId"].ToString());
                        condition.BankHolderName = rdr["BankHolderName"].ToString().ToUpper();
                        condition.BankAccountNo = rdr["BankAccountNo"].ToString().ToUpper();
                        condition.BankIFSCCode = rdr["BankIFSCCode"].ToString().ToUpper();
                        condition.BankName = rdr["BankName"].ToString().ToUpper();
                        condition.BankBranch = rdr["BankBranch"].ToString().ToUpper();
                        condition.SundryParty = rdr["SundryParty"].ToString().ToUpper();
                        condition.IsActiveParty = Convert.ToInt32(rdr["IsActiveParty"].ToString());

                        // FIX: Extract and map the PartyPrefix field value safely
                        condition.prefixInput = rdr["PartyPrefix"] != DBNull.Value ? rdr["PartyPrefix"].ToString().ToUpper() : "";

                        listUser.Add(condition);
                    }
                }
                cmd.Dispose();
                con.Close();
            }

            response.Code = 200;
            response.Message = "Success";
            response.listPartyMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void editPartyMaster()
        {
            TimeZoneInfo India_Standard_Time = TimeZoneInfo.FindSystemTimeZoneById("India Standard Time");
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            CommanResponse comman = new CommanResponse();
            PartyMaster ilist = new PartyMaster();

            ilist.PartyId = Convert.ToInt32(HttpContext.Current.Request.Params["PartyId"] ?? "0");
            ilist.PartyName = HttpContext.Current.Request.Params["PartyName"];
            ilist.MobileNo = HttpContext.Current.Request.Params["MobileNo"];
            ilist.tempMobileNo = HttpContext.Current.Request.Params["MobileNotemp"];
            ilist.AlterMobileNo = HttpContext.Current.Request.Params["AlterMobileNo"];
            ilist.BillingAddress = HttpContext.Current.Request.Params["BillingAddress"];
            ilist.ShippingAddress = HttpContext.Current.Request.Params["ShippingAddress"];
            ilist.GSTIN = HttpContext.Current.Request.Params["GSTIN"];
            ilist.tempGSTIN = HttpContext.Current.Request.Params["GSTINtemp"];
            ilist.PanNo = HttpContext.Current.Request.Params["PanNo"];
            ilist.tempPanNo = HttpContext.Current.Request.Params["PanNotemp"];
            ilist.State = HttpContext.Current.Request.Params["State"];
            ilist.City = HttpContext.Current.Request.Params["City"];
            ilist.Pincode = HttpContext.Current.Request.Params["Pincode"];
            ilist.Email = HttpContext.Current.Request.Params["Email"];
            ilist.IsSameAddress = Convert.ToInt32(HttpContext.Current.Request.Params["IsSameAddress"] ?? "0");

            ilist.UserAccountId = Context.Request.Cookies["UserIDs"] != null ? Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]) : 0;
            ilist.CompanyId = Context.Request.Cookies["CompanyID"] != null ? Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]) : 0;

            ilist.BankHolderName = HttpContext.Current.Request.Params["BankHolderName"];
            ilist.BankAccountNo = HttpContext.Current.Request.Params["BankAccountNo"];
            ilist.BankIFSCCode = HttpContext.Current.Request.Params["BankIFSCCode"];
            ilist.BankName = HttpContext.Current.Request.Params["BankName"];
            ilist.BankBranch = HttpContext.Current.Request.Params["BankBranch"];
            ilist.SundryParty = HttpContext.Current.Request.Params["SundryParty"];
            ilist.IsActiveParty = Convert.ToInt32(HttpContext.Current.Request.Params["IsActiveParty"] ?? "1");
            ilist.prefixInput = HttpContext.Current.Request.Params["prefixInput"];

            if (ilist.PartyId <= 0)
            {
                comman.Code = 400;
                comman.Message = "Invalid Party ID provided for update.";
                AuditLogHelper.LogValidationError("Party Master", "PartyMaster", ilist.PartyId.ToString(), "Validation failed: Invalid Party ID.", errorMessage: comman.Message, requestData: ilist);
                WriteJsonResponse(comman);
                return;
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            try
            {
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();
                    using (SqlTransaction trans = con.BeginTransaction())
                    {
                        try
                        {
                            using (SqlCommand cmd = new SqlCommand("", con, trans))
                            {
                                // 1. Check GSTIN
                                if (!string.IsNullOrWhiteSpace(ilist.GSTIN))
                                {
                                    cmd.CommandText = "SELECT 1 FROM PartyMaster WHERE GSTIN = @GSTIN AND GSTIN != @tempGSTIN AND SundryParty = @SundryParty";
                                    cmd.Parameters.Clear();
                                    cmd.Parameters.AddWithValue("@GSTIN", ilist.GSTIN);
                                    cmd.Parameters.AddWithValue("@tempGSTIN", ilist.tempGSTIN ?? (object)DBNull.Value);
                                    cmd.Parameters.AddWithValue("@SundryParty", ilist.SundryParty ?? (object)DBNull.Value);
                                    using (SqlDataReader rdr = cmd.ExecuteReader())
                                    {
                                        if (rdr.Read())
                                        {
                                            trans.Rollback();
                                            comman.Code = 410;
                                            comman.Message = $"This GSTIN {ilist.GSTIN} already exists.";
                                            AuditLogHelper.LogDuplicateError("Party Master", "PartyMaster", ilist.PartyId.ToString(), $"Duplicate check failed: GSTIN {ilist.GSTIN} already exists.", errorMessage: comman.Message, requestData: ilist);
                                            WriteJsonResponse(comman);
                                            return;
                                        }
                                    }
                                }

                                // 2. Check PAN
                                if (!string.IsNullOrWhiteSpace(ilist.PanNo))
                                {
                                    cmd.CommandText = "SELECT 1 FROM PartyMaster WHERE PAN = @PAN AND PAN != @tempPAN AND SundryParty = @SundryParty";
                                    cmd.Parameters.Clear();
                                    cmd.Parameters.AddWithValue("@PAN", ilist.PanNo);
                                    cmd.Parameters.AddWithValue("@tempPAN", ilist.tempPanNo ?? (object)DBNull.Value);
                                    cmd.Parameters.AddWithValue("@SundryParty", ilist.SundryParty ?? (object)DBNull.Value);
                                    using (SqlDataReader rdr = cmd.ExecuteReader())
                                    {
                                        if (rdr.Read())
                                        {
                                            trans.Rollback();
                                            comman.Code = 410;
                                            comman.Message = $"This PAN no {ilist.PanNo} already exists.";
                                            AuditLogHelper.LogDuplicateError("Party Master", "PartyMaster", ilist.PartyId.ToString(), $"Duplicate check failed: PAN {ilist.PanNo} already exists.", errorMessage: comman.Message, requestData: ilist);
                                            WriteJsonResponse(comman);
                                            return;
                                        }
                                    }
                                }

                                // 3. Check MobileNo
                                if (!string.IsNullOrWhiteSpace(ilist.MobileNo))
                                {
                                    cmd.CommandText = "SELECT 1 FROM PartyMaster WHERE MobileNo = @MobileNo AND MobileNo != @tempMobileNo AND SundryParty = @SundryParty";
                                    cmd.Parameters.Clear();
                                    cmd.Parameters.AddWithValue("@MobileNo", ilist.MobileNo);
                                    cmd.Parameters.AddWithValue("@tempMobileNo", ilist.tempMobileNo ?? (object)DBNull.Value);
                                    cmd.Parameters.AddWithValue("@SundryParty", ilist.SundryParty ?? (object)DBNull.Value);
                                    using (SqlDataReader rdr = cmd.ExecuteReader())
                                    {
                                        if (rdr.Read())
                                        {
                                            trans.Rollback();
                                            comman.Code = 410;
                                            comman.Message = $"This Mobile No {ilist.MobileNo} already exists.";
                                            AuditLogHelper.LogDuplicateError("Party Master", "PartyMaster", ilist.PartyId.ToString(), $"Duplicate check failed: Mobile No {ilist.MobileNo} already exists.", errorMessage: comman.Message, requestData: ilist);
                                            WriteJsonResponse(comman);
                                            return;
                                        }
                                    }
                                }

                                object oldParty = AuditLogHelper.FetchOldValue("PartyMaster", ilist.PartyId.ToString(), con, trans);

                                string sql = @"UPDATE PartyMaster SET 
                                        UserAccountId = @UserAccountId, 
                                        DateAndTime = @DateAndTime, 
                                        SundryParty = @SundryParty, 
                                        PartyName = @PartyName, 
                                        MobileNo = @MobileNo, 
                                        AlterMobileNo = @AlterMobileNo,
                                        Email = @Email, 
                                        BillingAddress = @BillingAddress, 
                                        ShippingAddress = @ShippingAddress, 
                                        IsSameAddress = @IsSameAddress, 
                                        GSTIN = @GSTIN, 
                                        PAN = @PAN, 
                                        State = @State, 
                                        City = @City, 
                                        Pincode = @Pincode, 
                                        BankHolderName = @BankHolderName, 
                                        BankAccountNo = @BankAccountNo, 
                                        BankIFSCCode = @BankIFSCCode, 
                                        BankName = @BankName, 
                                        BankBranch = @BankBranch, 
                                        IsActiveParty = @IsActiveParty,
                                        PartyPrefix = @PartyPrefix 
                                       WHERE PartyId = @PartyId";

                                cmd.CommandText = sql;
                                cmd.Parameters.Clear();
                                cmd.Parameters.AddWithValue("@UserAccountId", ilist.UserAccountId);
                                cmd.Parameters.AddWithValue("@DateAndTime", dateTime_Indian);
                                cmd.Parameters.AddWithValue("@SundryParty", ilist.SundryParty ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@PartyName", ilist.PartyName ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@MobileNo", ilist.MobileNo ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@AlterMobileNo", ilist.AlterMobileNo ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@Email", ilist.Email ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@BillingAddress", ilist.BillingAddress ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@ShippingAddress", ilist.ShippingAddress ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@IsSameAddress", ilist.IsSameAddress);
                                cmd.Parameters.AddWithValue("@GSTIN", ilist.GSTIN ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@PAN", ilist.PanNo ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@State", ilist.State ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@City", ilist.City ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@Pincode", ilist.Pincode ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@BankHolderName", ilist.BankHolderName ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@BankAccountNo", ilist.BankAccountNo ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@BankIFSCCode", ilist.BankIFSCCode ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@BankName", ilist.BankName ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@BankBranch", ilist.BankBranch ?? (object)DBNull.Value);
                                cmd.Parameters.AddWithValue("@IsActiveParty", ilist.IsActiveParty);
                                cmd.Parameters.AddWithValue("@PartyId", ilist.PartyId);

                                if (ilist.SundryParty == "3" && !string.IsNullOrEmpty(ilist.prefixInput))
                                {
                                    cmd.Parameters.AddWithValue("@PartyPrefix", ilist.prefixInput.Trim().ToUpper());
                                }
                                else
                                {
                                    cmd.Parameters.AddWithValue("@PartyPrefix", DBNull.Value);
                                }

                                int rowsAffected = cmd.ExecuteNonQuery();

                                if (rowsAffected > 0)
                                {
                                    AuditLogHelper.LogUpdate(
                                        module: "Party Master",
                                        tableName: "PartyMaster",
                                        recordId: ilist.PartyId.ToString(),
                                        description: $"Updated Party: {ilist.PartyName}",
                                        oldValue: oldParty,
                                        newValue: ilist,
                                        conn: con,
                                        tran: trans
                                    );

                                    trans.Commit();

                                    comman.Code = 201;
                                    comman.Message = "Record has been updated successfully.";
                                }
                                else
                                {
                                    trans.Rollback();
                                    comman.Code = 410;
                                    comman.Message = "Problem has occurred while submitting your data.";
                                    AuditLogHelper.LogValidationError("Party Master", "PartyMaster", ilist.PartyId.ToString(), "Failed to update Party Master record (0 rows updated)", errorMessage: comman.Message, requestData: ilist);
                                }
                                WriteJsonResponse(comman);
                            }
                        }
                        catch
                        {
                            try { trans.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                    AuditLogHelper.LogDuplicateError("Party Master", "PartyMaster", ilist.PartyId.ToString(), "SQL duplicate error on update", errorMessage: ex.Message, requestData: ilist);
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has occurred while submitting your data: " + ex.Message;
                    AuditLogHelper.LogError("Party Master", "editPartyMaster", ex, JsonConvert.SerializeObject(ilist));
                }
                WriteJsonResponse(comman);
            }
            catch (Exception ex)
            {
                comman.Code = 500;
                comman.Message = "An unexpected error occurred: " + ex.Message;
                AuditLogHelper.LogError("Party Master", "editPartyMaster", ex, JsonConvert.SerializeObject(ilist));
                WriteJsonResponse(comman);
            }
        }
        // Delete Party Master
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeletePartyMaster()
        {
            JavaScriptSerializer js;
            PartyMaster ilist = new PartyMaster();
            CommanResponse comman = new CommanResponse();

            int partyId = 0;
            int.TryParse(HttpContext.Current.Request.Params["PartyId"], out partyId);
            ilist.PartyId = partyId;

            // CASE 3 — INVALID PARTY ID
            if (ilist.PartyId <= 0)
            {
                comman.Code = 400;
                comman.Message = "Unable to delete the party because the selected party ID is invalid.";
                AuditLogHelper.LogValidationError("Party Master", "PartyMaster", partyId.ToString(), "Validation failed: Invalid Party ID provided for delete.", errorMessage: comman.Message);
                js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();
                using (SqlTransaction trans = con.BeginTransaction())
                {
                    try
                    {
                        // CASE 1 — PRE-FLIGHT SERVER-SIDE DEPENDENCY CHECKS
                        // Verified Table & Column Names from Project Codebase:
                        // 1. SaleOrder -> PartyID
                        // 2. YarnPOMaster -> SupplierPartyID, CompanyPartyID, BillToPartyID, ShippedToPartyID
                        // 3. YarnOutwardMaster -> PartyId
                        // 4. YarnRequirementMaster -> PartyId
                        // 5. GodownMaster -> PartyId
                        // 6. UserAccountMaster -> PartyId
                        string checkSql = @"
                            SELECT 
                                (SELECT COUNT(1) FROM SaleOrder WHERE PartyID = @PartyId) +
                                (SELECT COUNT(1) FROM YarnPOMaster WHERE SupplierPartyID = @PartyId OR CompanyPartyID = @PartyId OR BillToPartyID = @PartyId OR ShippedToPartyID = @PartyId) +
                                (SELECT COUNT(1) FROM YarnOutwardMaster WHERE PartyId = @PartyId) +
                                (SELECT COUNT(1) FROM YarnRequirementMaster WHERE PartyId = @PartyId) +
                                (SELECT COUNT(1) FROM GodownMaster WHERE PartyId = @PartyId) +
                                (SELECT COUNT(1) FROM UserAccountMaster WHERE PartyId = @PartyId);";

                        using (SqlCommand cmdCheck = new SqlCommand(checkSql, con, trans))
                        {
                            cmdCheck.Parameters.Add("@PartyId", SqlDbType.Int).Value = ilist.PartyId;
                            int totalReferences = Convert.ToInt32(cmdCheck.ExecuteScalar());

                            if (totalReferences > 0)
                            {
                                trans.Rollback();
                                comman.Code = 547;
                                comman.Message = "Unable to delete this party because it is already associated with existing transactions or related records. Please complete or remove the related records before deleting this party.";
                                AuditLogHelper.LogDependencyError("Party Master", "PartyMaster", ilist.PartyId.ToString(), "Dependency check failed: Party is referenced in other transactions.", errorMessage: comman.Message);
                                js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }
                        }

                        // Read Old Record for Audit Log & Verify Existence
                        object oldParty = null;
                        using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM PartyMaster WHERE PartyId = @PartyId", con, trans))
                        {
                            cmdOld.Parameters.Add("@PartyId", SqlDbType.Int).Value = ilist.PartyId;
                            using (SqlDataReader rdrOld = cmdOld.ExecuteReader())
                            {
                                if (rdrOld.Read())
                                {
                                    oldParty = new
                                    {
                                        PartyId = rdrOld["PartyId"],
                                        PartyName = rdrOld["PartyName"],
                                        MobileNo = rdrOld["MobileNo"],
                                        GSTIN = rdrOld["GSTIN"],
                                        PAN = rdrOld["PAN"],
                                        State = rdrOld["State"],
                                        City = rdrOld["City"],
                                        BillingAddress = rdrOld["BillingAddress"]
                                    };
                                }
                            }
                        }

                        // CASE 2 — PARTY DOES NOT EXIST
                        if (oldParty == null)
                        {
                            trans.Rollback();
                            comman.Code = 404;
                            comman.Message = "The selected party could not be found. It may have already been deleted or is no longer available.";
                            AuditLogHelper.LogValidationError("Party Master", "PartyMaster", ilist.PartyId.ToString(), "Record not found for delete.", errorMessage: comman.Message);
                            js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }

                        // Execute Delete with Parameterized Command
                        int i = 0;
                        using (SqlCommand cmd = new SqlCommand("DELETE FROM PartyMaster WHERE PartyId = @PartyId", con, trans))
                        {
                            cmd.Parameters.Add("@PartyId", SqlDbType.Int).Value = ilist.PartyId;
                            i = cmd.ExecuteNonQuery();
                        }

                        // CASE 4 — SUCCESS
                        if (i > 0)
                        {
                            AuditLogHelper.Log(
                                module: "Party Master",
                                action: "DELETE",
                                tableName: "PartyMaster",
                                recordId: ilist.PartyId.ToString(),
                                description: $"Deleted Party ID #{ilist.PartyId}",
                                oldValue: oldParty,
                                existingConn: con,
                                existingTran: trans
                            );

                            trans.Commit();

                            comman.Code = 200;
                            comman.Message = "Party deleted successfully.";
                            js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }
                        else
                        {
                            trans.Rollback();
                            comman.Code = 404;
                            comman.Message = "The selected party could not be found. It may have already been deleted or is no longer available.";
                            js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }
                    }
                    catch (SqlException ex)
                    {
                        try { trans.Rollback(); } catch { }

                        // Internal Audit Exception Logging
                        try
                        {
                            AuditLogHelper.Log(
                                module: "Party Master",
                                action: "DELETE_ERROR",
                                tableName: "PartyMaster",
                                recordId: ilist.PartyId.ToString(),
                                description: $"Failed to delete Party ID #{ilist.PartyId}. Exception: {ex.Message}",
                                status: "Error",
                                errorMessage: ex.Message,
                                ex: ex
                            );
                        }
                        catch { }

                        // CASE 1 & CASE 5 — DATABASE / UNEXPECTED ERROR
                        if (ex.Number == 547)
                        {
                            comman.Code = 547;
                            comman.Message = "Unable to delete this party because it is already associated with existing transactions or related records. Please complete or remove the related records before deleting this party.";
                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "We couldn't delete this party due to an unexpected system error. Please try again. If the problem persists, contact the administrator.";
                        }

                        js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                }
            }
        }
