        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertGodownManagerMaster()
        {

            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);
            //Int64 EmployeeId, CourierDetailId;
            var request = HttpContext.Current.Request;

            //List<CustomerClass> listCustomer = new List<CustomerClass>();
            CommanResponse comman = new CommanResponse();
            GodownManager ilist = new GodownManager();
            ilist.GodownManagerName = HttpContext.Current.Request.Params["GodownManagerName"];
            ilist.MobileNo = HttpContext.Current.Request.Params["MobileNo"];
            ilist.AlterMobileNo = HttpContext.Current.Request.Params["AlterMobileNo"];
            ilist.ManagerAddress = HttpContext.Current.Request.Params["ManagerAddress"];
            ilist.Email = HttpContext.Current.Request.Params["Email"];
            ilist.IsActiveManager = Convert.ToInt32(HttpContext.Current.Request.Params["IsActiveManager"]);
            ilist.UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);

            try
            {

                int i = 0;
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;

                    cmd.CommandType = System.Data.CommandType.Text;
                    con.Open();

                    // Check MobileNo
                    cmd.CommandText = "SELECT 1 FROM GodownManager WHERE MobileNo = @MobileNo and CompanyId = (select CompanyId from companymaster where is_default = 1)";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@MobileNo", ilist.MobileNo);
                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        if (rdr.Read())
                        {
                            comman.Code = 410;
                            comman.Message = $"This Mobile No {ilist.MobileNo} already exists.";
                            JavaScriptSerializer js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;  // stop here if Mobile exists
                        }
                    }




                    cmd.CommandType = System.Data.CommandType.Text;

                    string sql = String.Format("Insert Into GodownManager (CompanyId, UserAccountId, DateAndTime, GodownManagerName, MobileNo, AlterMobileNo, Email, ManagerAddress, IsActiveManager) OUTPUT INSERTED.GodownManagerID Values " +
                                    " ((select CompanyId from companymaster where is_default = 1), '" + ilist.UserAccountId + "', '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', @GodownManagerName , '" + ilist.MobileNo + "', '" + ilist.AlterMobileNo + "', '" + ilist.Email + "', @ManagerAddress" +
                                    "   ,'" + ilist.IsActiveManager + "')");

                    cmd.CommandText = sql;
                    cmd.Parameters.Add("@GodownManagerName", SqlDbType.NVarChar).Value = ilist.GodownManagerName;
                    cmd.Parameters.Add("@ManagerAddress", SqlDbType.NVarChar).Value = ilist.ManagerAddress;



                    Int64 GodownManagerID = Convert.ToInt64(cmd.ExecuteScalar());

                    cmd.Dispose();
                    con.Close();

                    if (GodownManagerID > 0)
                    {
                        ilist.GodownManagerID = Convert.ToInt32(GodownManagerID);
                        AuditLogHelper.Log(
                            module: "Godown Manager",
                            action: "CREATE",
                            tableName: "GodownManager",
                            recordId: GodownManagerID.ToString(),
                            description: $"Created Godown Manager '{ilist.GodownManagerName}'",
                            newValue: ilist
                        );

                        comman.Code = 201;
                        comman.Message = "Record has been saved successfully.";
                        JavaScriptSerializer js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;



                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";
                        JavaScriptSerializer js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }

                }


            }
            catch (SqlException ex)
            {

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    js.MaxJsonLength = Int32.MaxValue;
