        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getAllDesignEntryYarnReqForm()
        {
            var request = HttpContext.Current.Request;

            Int64 customer_id = 0;

            if (!string.IsNullOrEmpty(request.Form["CustomerId"]))
            {
                customer_id = Convert.ToInt64(request.Form["CustomerId"]);
            }
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);
            string dateVal = dateTime_Indian.ToString("yyyy-MM-dd");
            List<YarnColorMaster> listYarnColorMaster = new List<YarnColorMaster>();
            List<YarnMaterialMaster> listYarnMaterialMaster = new List<YarnMaterialMaster>();
            List<YarnRequirementMaster> listYarnRequirementMaster = new List<YarnRequirementMaster>();
            DesignEntryFormResponse DesignEntryForm = new DesignEntryFormResponse();

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            int IsJobWork = 0;

            try
            {
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    int UserAccountId = 0;
                    if (Context.Request.Cookies["UserIDs"] != null)
                    {
                        string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                        if (cookieVal.Contains("="))
                        {
                            int.TryParse(cookieVal.Split('=')[1], out UserAccountId);
                        }
                        else
                        {
                            int.TryParse(cookieVal, out UserAccountId);
                        }
                    }

                    using (SqlCommand cmdCheck = new SqlCommand(@"
                        SELECT COUNT(*)
                        FROM UserAccountMaster
                        WHERE UserRole = 'Job Work'
                        AND UserAccountId = @UserId
                    ", con))
                    {
                        cmdCheck.Parameters.AddWithValue("@UserId", UserAccountId);
                        IsJobWork = Convert.ToInt32(cmdCheck.ExecuteScalar());
                    }

                    SqlCommand cmd;
                    SqlDataReader rdr;

                    if (IsJobWork > 0)
                    {
                        // JOB WORK
                        // Material + Color relationship required
                        cmd = new SqlCommand(@"
                          SELECT DISTINCT
                                YPD.YarnMaterialID,
                                YPD.YarnColorID,
                                YCM.YarnColor,
                                YCM.YarnColorCode,
                                YPD.CompanyCode,
                                YPM.CompanyPartyID,
                                PM.PartyName
                            FROM YarnPODetails YPD

                            LEFT JOIN YarnPOMaster YPM
                                ON YPM.YarnPOID = YPD.YarnPOID

                            LEFT JOIN YarnColorMaster YCM
                                ON YCM.YarnColorID = YPD.YarnColorID

                            LEFT JOIN PartyMaster PM
                                ON PM.PartyId = YPM.CompanyPartyID

                            WHERE EXISTS
                            (
                                SELECT 1
                                FROM YarnInwardMaster YIM
                                INNER JOIN YarnInwardDetail YID
                                    ON YID.YarnInwardID = YIM.YarnInwardID
                                WHERE YIM.YarnMaterialID = YPD.YarnMaterialID
                                  AND YIM.YarnColorID = YPD.YarnColorID
                                  AND NOT EXISTS
                                  (
                                      SELECT 1
                                      FROM YarnOutwardScanMasterDetails YSD
                                      WHERE YSD.YarnInwardDetailID = YID.YarnInwardDetailID
                                  )
                            )

                            ORDER BY
                                YPD.YarnMaterialID,
                                YPD.YarnColorID;
                        ", con);
                    }
                    else
                    {
                        // NORMAL USER
                        // Material ID is not used for filtering
                        cmd = new SqlCommand(@"
                            SELECT DISTINCT 
                                YPD.YarnMaterialID,
                                YPD.YarnColorID,
                                YCM.YarnColor,
                                YCM.YarnColorCode,
                                YPD.CompanyCode,
                                YPM.CompanyPartyID,
                                PM.PartyName 
                            FROM YarnPODetails YPD
                            LEFT JOIN YarnPOMaster YPM ON YPM.YarnPOID = YPD.YarnPOID
                            LEFT JOIN YarnColorMaster YCM ON YCM.YarnColorID = YPD.YarnColorID
                            LEFT JOIN PartyMaster PM ON PM.PartyId = YPM.CompanyPartyID 
                        ", con);
                    }

                    rdr = cmd.ExecuteReader();

                    while (rdr.Read())
                    {
                        YarnColorMaster YarnColorM = new YarnColorMaster();

                        YarnColorM.YarnMaterialID = rdr["YarnMaterialID"] != DBNull.Value
                            ? Convert.ToInt32(rdr["YarnMaterialID"])
                            : 0;

                        YarnColorM.YarnColorID = rdr["YarnColorID"] != DBNull.Value
                            ? Convert.ToInt32(rdr["YarnColorID"])
                            : 0;

                        YarnColorM.YarnColor = rdr["YarnColor"] != DBNull.Value
                            ? rdr["YarnColor"].ToString().Trim().ToUpper()
                            : "";

                        YarnColorM.YarnColorCode = rdr["YarnColorCode"] != DBNull.Value
                            ? rdr["YarnColorCode"].ToString().Trim().ToUpper()
                            : "";

                        YarnColorM.CompanyCode = rdr["CompanyCode"] != DBNull.Value
                            ? rdr["CompanyCode"].ToString().Trim().ToUpper()
                            : "";

                        YarnColorM.CompanyId = rdr["CompanyPartyID"] != DBNull.Value
                            ? Convert.ToInt32(rdr["CompanyPartyID"])
                            : 0;

                        YarnColorM.CompanyName = rdr["PartyName"] != DBNull.Value
                            ? rdr["PartyName"].ToString().Trim().ToUpper()
                            : "";

                        listYarnColorMaster.Add(YarnColorM);
                    }

                    rdr.Close();
                    cmd.Dispose();

                    if (IsJobWork > 0)
                    {
                        cmd = new SqlCommand(@"
                            SELECT DISTINCT
                                YMM.YarnMaterialID,
                                YMM.YarnMaterial
                            FROM YarnInwardDetail YID
                            INNER JOIN YarnInwardMaster YIM
                                ON YIM.YarnInwardID = YID.YarnInwardID
                            INNER JOIN YarnMaterialMaster YMM
                                ON YMM.YarnMaterialID = YIM.YarnMaterialID
                            INNER JOIN YarnColorMaster YCM
                                ON YCM.YarnColorID = YIM.YarnColorID
                            WHERE NOT EXISTS
                            (
                                SELECT 1
                                FROM YarnOutwardScanMasterDetails YSD
                                WHERE YSD.YarnInwardDetailID = YID.YarnInwardDetailID
                            )
                            ORDER BY
                                YMM.YarnMaterial
                        ", con);
                    }
                    else
                    {
                        cmd = new SqlCommand(@"
                            SELECT
                                YarnMaterialID,
                                YarnMaterial
                            FROM YarnMaterialMaster
                            WHERE IsActive = 1
                            ORDER BY YarnMaterial
                        ", con);
                    }

                    rdr = cmd.ExecuteReader();

                    while (rdr.Read())
                    {
                        YarnMaterialMaster YarnMaterialM = new YarnMaterialMaster();

                        YarnMaterialM.YarnMaterialID = rdr["YarnMaterialID"] != DBNull.Value
                            ? Convert.ToInt32(rdr["YarnMaterialID"])
                            : 0;

                        YarnMaterialM.YarnMaterial = rdr["YarnMaterial"] != DBNull.Value
                            ? rdr["YarnMaterial"].ToString().Trim().ToUpper()
                            : "";

                        listYarnMaterialMaster.Add(YarnMaterialM);
                    }

                    rdr.Close();
                    cmd.Dispose();

                    cmd = new SqlCommand(@"
                        SELECT
                            COALESCE(MAX(RequirementNo), 0) + 1 AS RequirementNo
                        FROM YarnRequirementMaster
                        WHERE FinancialYearID =
                        (
                            SELECT FinancialYearID
                            FROM FinancialYearMaster
                            WHERE IsDefault = 1
                        )
                        AND CompanyId =
                        (
                            SELECT CompanyId
                            FROM CompanyMaster
                            WHERE is_default = 1
                        )
                    ", con);

                    rdr = cmd.ExecuteReader();

                    while (rdr.Read())
                    {
                        YarnRequirementMaster YarnRequirementM = new YarnRequirementMaster();

                        YarnRequirementM.RequirementNo = rdr["RequirementNo"] != DBNull.Value
                            ? Convert.ToInt32(rdr["RequirementNo"])
                            : 1;

                        listYarnRequirementMaster.Add(YarnRequirementM);
                    }

                    rdr.Close();
                    cmd.Dispose();
                }

                DesignEntryForm.Code = 200;
                DesignEntryForm.Message = "Success";
                DesignEntryForm.IsJobWork = IsJobWork;
                DesignEntryForm.listYarnColorMaster = listYarnColorMaster;
                DesignEntryForm.listYarnMaterialMaster = listYarnMaterialMaster;
                DesignEntryForm.listYarnRequirementMaster = listYarnRequirementMaster;
            }
            catch (Exception ex)
            {
                DesignEntryForm.Code = 500;
                DesignEntryForm.Message = ex.Message;
                DesignEntryForm.IsJobWork = IsJobWork;
                DesignEntryForm.listYarnColorMaster = listYarnColorMaster;
                DesignEntryForm.listYarnMaterialMaster = listYarnMaterialMaster;
                DesignEntryForm.listYarnRequirementMaster = listYarnRequirementMaster;
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            Context.Response.Write(js.Serialize(DesignEntryForm));
        }

