            ilist.ShippingAddress = HttpContext.Current.Request.Params["ShippingAddress"];
            ilist.GSTIN = HttpContext.Current.Request.Params["GSTIN"];
            ilist.PanNo = HttpContext.Current.Request.Params["PanNo"];
            ilist.State = HttpContext.Current.Request.Params["State"];
            ilist.City = HttpContext.Current.Request.Params["City"];
            ilist.Pincode = HttpContext.Current.Request.Params["Pincode"];
            ilist.Email = HttpContext.Current.Request.Params["Email"];
            ilist.IsSameAddress = Convert.ToInt32(HttpContext.Current.Request.Params["IsSameAddress"]);
            ilist.UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
            ilist.CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);
            ilist.BankHolderName = HttpContext.Current.Request.Params["BankHolderName"];
            ilist.BankAccountNo = HttpContext.Current.Request.Params["BankAccountNo"];
            ilist.BankIFSCCode = HttpContext.Current.Request.Params["BankIFSCCode"];
            ilist.BankName = HttpContext.Current.Request.Params["BankName"];
            ilist.BankBranch = HttpContext.Current.Request.Params["BankBranch"];
            ilist.IsActiveParty = Convert.ToInt32(HttpContext.Current.Request.Params["IsActiveParty"]);

            try
            {

                int i = 0;
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;



                    cmd.Connection = con;
                    cmd.CommandType = System.Data.CommandType.Text;
                    con.Open();

                    // Check GSTIN
                    cmd.CommandText = "SELECT 1 FROM PartyMaster WHERE GSTIN = @GSTIN";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@GSTIN", ilist.GSTIN);
                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        if (rdr.Read())
                        {
                            comman.Code = 410;
                            comman.Message = $"This GSTIN {ilist.GSTIN} already exists.";
                            JavaScriptSerializer js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;  // stop here if GSTIN exists
                        }
                    }

                    // Check PAN
                    cmd.CommandText = "SELECT 1 FROM PartyMaster WHERE PAN = @PAN";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@PAN", ilist.PanNo);
                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        if (rdr.Read())
                        {
                            comman.Code = 410;
                            comman.Message = $"This PAN no {ilist.PanNo} already exists.";
                            JavaScriptSerializer js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;  // stop here if PAN exists
                        }
                    }

                    // Check MobileNo
                    cmd.CommandText = "SELECT 1 FROM PartyMaster WHERE MobileNo = @MobileNo";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@MobileNo", ilist.MobileNo);
                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        if (rdr.Read())
                        {
                            comman.Code = 410;
                            comman.Message = $"This Mobile No {ilist.MobileNo} already exists.";
                            JavaScriptSerializer js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;  // stop here if Mobile exists
                        }
                    }




                    cmd.CommandType = System.Data.CommandType.Text;

                    string sql = String.Format("Insert Into PartyMaster (CompanyId, UserAccountId, DateAndTime, PartyName, MobileNo, AlterMobileNo, Email, BillingAddress, ShippingAddress, IsSameAddress, GSTIN, PAN, State, City, Pincode, BankHolderName, BankAccountNo, BankIFSCCode, BankName, BankBranch, IsActiveParty) OUTPUT INSERTED.PartyId Values " +
                                    " ((select CompanyId from companymaster where is_default = 1), '" + ilist.UserAccountId + "', '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', @PartyName , '" + ilist.MobileNo + "', '" + ilist.AlterMobileNo + "', '" + ilist.Email + "', @BillingAddress, @ShippingAddress, '" + ilist.IsSameAddress + "', '" + ilist.GSTIN + "', '" + ilist.PanNo + "', '" + ilist.State + "', '" + ilist.City + "', '" + ilist.Pincode + "',   " +
                                    "   @BankHolderName, '" + ilist.BankAccountNo + "', '" + ilist.BankIFSCCode + "', @BankName, @BankBranch, '" + ilist.IsActiveParty + "')");

                    cmd.CommandText = sql;
                    cmd.Parameters.Add("@PartyName", SqlDbType.NVarChar).Value = ilist.PartyName;
                    cmd.Parameters.Add("@BillingAddress", SqlDbType.NVarChar).Value = ilist.BillingAddress;
                    cmd.Parameters.Add("@ShippingAddress", SqlDbType.NVarChar).Value = ilist.ShippingAddress;
                    cmd.Parameters.Add("@BankHolderName", SqlDbType.NVarChar).Value = ilist.BankHolderName;
                    cmd.Parameters.Add("@BankName", SqlDbType.NVarChar).Value = ilist.BankName;
                    cmd.Parameters.Add("@BankBranch", SqlDbType.NVarChar).Value = ilist.BankBranch;


                    int PartyId = Convert.ToInt32(cmd.ExecuteScalar());

                    cmd.Dispose();
                    con.Close();

                    if (PartyId > 0)
                    {
                        comman.id = PartyId;
                        comman.Code = 201;
                        comman.Message = "Record has been saved successfully.";
                        JavaScriptSerializer js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;



                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";
                        JavaScriptSerializer js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }

                }


            }
            catch (SqlException ex)
            {

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    js.MaxJsonLength = Int32.MaxValue;
                    Context.Response.Write(js.Serialize(comman));
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    js.MaxJsonLength = Int32.MaxValue;
                    Context.Response.Write(js.Serialize(comman));
                }

            }



        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getPartyDetails()
        {
            try
            {
                List<PartyMaster> listPartyMaster = new List<PartyMaster>();
                PartyMasterResponse PartyMasterForm = new PartyMasterResponse();

                string cs = ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    int UserAccountId = Convert.ToInt32(
                        Context.Request.Cookies["UserIDs"].Value.Split('=')[1]
                    );

                    int PartyId = 0;
                    string UserRole = "";

                    // Get User PartyId and UserRole
                    using (SqlCommand cmdUser = new SqlCommand(@"
                        SELECT 
                            ISNULL(PartyId, 0) AS PartyId,
                            ISNULL(UserRole, '') AS UserRole
                        FROM UserAccountMaster
                        WHERE UserAccountId = @UserAccountId
                    ", con))
                    {
                        cmdUser.Parameters.AddWithValue(
                            "@UserAccountId",
                            UserAccountId
                        );

                        using (SqlDataReader dr = cmdUser.ExecuteReader())
                        {
                            if (dr.Read())
                            {
                                PartyId = Convert.ToInt32(dr["PartyId"]);
                                UserRole = dr["UserRole"].ToString().Trim();
                            }
                        }
                    }

                    // Normal active party list
                    string query = @"
                SELECT *
                FROM PartyMaster
                WHERE CompanyId = (
                    SELECT TOP 1 CompanyId
                    FROM CompanyMaster
                    WHERE is_default = 1
                )
                AND IsActiveParty = 1
            ";

                    /*
                     * Job Work User:
                     * Only mapped Party should be available.
                     */
                    if (UserRole.Equals(
                            "Job Work",
                            StringComparison.OrdinalIgnoreCase)
                        && PartyId > 0)
                    {
                        query += " AND PartyId = @PartyId";
                    }

                    query += " ORDER BY PartyName";

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        if (UserRole.Equals(
                                "Job Work",
                                StringComparison.OrdinalIgnoreCase)
                            && PartyId > 0)
                        {
                            cmd.Parameters.AddWithValue(
                                "@PartyId",
                                PartyId
                            );
                        }

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                PartyMaster condition = new PartyMaster();

                                condition.PartyId =
                                    Convert.ToInt32(rdr["PartyId"]);

                                condition.PartyName =
                                    rdr["PartyName"].ToString().ToUpper();

                                condition.MobileNo =
                                    rdr["MobileNo"].ToString();

                                condition.AlterMobileNo =
                                    rdr["AlterMobileNo"].ToString();

                                condition.Email =
                                    rdr["Email"].ToString();

                                condition.State =
                                    rdr["State"].ToString();

                                condition.City =
                                    rdr["City"].ToString();

                                condition.Pincode =
                                    rdr["Pincode"].ToString();

                                condition.BillingAddress =
                                    rdr["BillingAddress"].ToString();

                                condition.ShippingAddress =
                                    rdr["ShippingAddress"].ToString();

                                condition.IsSameAddress =
                                    Convert.ToInt32(rdr["IsSameAddress"]);

                                condition.GSTIN =
                                    rdr["GSTIN"].ToString();

                                condition.PanNo =
                                    rdr["PAN"].ToString();

                                condition.CompanyId =
                                    Convert.ToInt32(rdr["CompanyId"]);

                                condition.BankHolderName =
                                    rdr["BankHolderName"].ToString();

                                condition.BankAccountNo =
                                    rdr["BankAccountNo"].ToString();

                                condition.BankIFSCCode =
                                    rdr["BankIFSCCode"].ToString();

                                condition.BankName =
                                    rdr["BankName"].ToString();

                                condition.BankBranch =
                                    rdr["BankBranch"].ToString();

                                condition.IsActiveParty =
                                    Convert.ToInt32(rdr["IsActiveParty"]);

                                listPartyMaster.Add(condition);
                            }
                        }
                    }
                }

                PartyMasterForm.Code = 200;
                PartyMasterForm.Message = "Success";
                PartyMasterForm.listPartyMaster = listPartyMaster;

                JavaScriptSerializer js = new JavaScriptSerializer();

                Context.Response.Write(
                    js.Serialize(PartyMasterForm)
                );
            }
            catch (Exception ex)
            {
                PartyMasterResponse response =
                    new PartyMasterResponse();

                response.Code = 500;
                response.Message = ex.Message;

                JavaScriptSerializer js =
                    new JavaScriptSerializer();

                Context.Response.Write(
                    js.Serialize(response)
                );
            }
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getJobberDetailsForYarnRequirement()
        {
            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                List<JobberViewModel> listJobber = new List<JobberViewModel>();
                bool isAdmin = false;
                bool isJobber = false;
                long loggedInJobberId = 0;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    var secContext = GetLoggedInUserSecurityContext(con);

                    if (secContext.IsAdmin)
                    {
                        isAdmin = true;
                        isJobber = false;
                        loggedInJobberId = 0;
                    }
                    else
                    {
                        if (secContext.LoggedInJobberID > 0)
                        {
                            isJobber = true;
                            isAdmin = false;
                            loggedInJobberId = secContext.LoggedInJobberID;
                        }
                        else if (secContext.UserAccountId > 0)
                        {
                            using (SqlCommand cmdMob = new SqlCommand(@"
                                SELECT TOP 1 JM.Id
                                FROM JobberMaster JM
                                INNER JOIN UserAccountMaster UA ON UA.UserAccountMobileNo = JM.MobileNumber
                                WHERE UA.UserAccountId = @UserAccountId", con))
                            {
                                cmdMob.Parameters.AddWithValue("@UserAccountId", secContext.UserAccountId);
                                object res = cmdMob.ExecuteScalar();
                                if (res != null && res != DBNull.Value)
                                {
                                    isJobber = true;
                                    isAdmin = false;
                                    loggedInJobberId = Convert.ToInt64(res);
                                }
                            }
                        }

                        if (loggedInJobberId <= 0 && !isJobber)
                        {
                            isAdmin = true;
                        }
                    }

                    string query = "SELECT * FROM JobberMaster";
                    if (isJobber && loggedInJobberId > 0)
                    {
                        query += " WHERE Id = @JobberId";
                    }
                    else
                    {
                        query += " WHERE ISNULL(IsActiveParty, 1) = 1";
                    }
                    query += " ORDER BY PartyName ASC";

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        if (isJobber && loggedInJobberId > 0)
                        {
                            cmd.Parameters.AddWithValue("@JobberId", loggedInJobberId);
                        }

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                JobberViewModel jobber = new JobberViewModel
                                {
                                    Id = Convert.ToInt32(rdr["Id"]),
                                    JobberType = rdr["JobberType"] != DBNull.Value ? rdr["JobberType"].ToString() : "",
                                    Gstin = rdr["Gstin"] != DBNull.Value ? rdr["Gstin"].ToString() : "",
                                    PanNo = rdr["PanNo"] != DBNull.Value ? rdr["PanNo"].ToString() : "",
                                    PartyName = rdr["PartyName"] != DBNull.Value ? rdr["PartyName"].ToString().ToUpper() : "",
                                    Prefix = rdr["Prefix"] != DBNull.Value ? rdr["Prefix"].ToString() : "",
                                    MobileNumber = rdr["MobileNumber"] != DBNull.Value ? rdr["MobileNumber"].ToString() : "",
                                    AlternateNumber = rdr["AlternateNumber"] != DBNull.Value ? rdr["AlternateNumber"].ToString() : "",
                                    Email = rdr["Email"] != DBNull.Value ? rdr["Email"].ToString() : "",
                                    PlaceOfSupply = rdr["PlaceOfSupply"] != DBNull.Value ? rdr["PlaceOfSupply"].ToString() : "",
                                    Pincode = rdr["Pincode"] != DBNull.Value ? rdr["Pincode"].ToString() : "",
                                    City = rdr["City"] != DBNull.Value ? rdr["City"].ToString() : "",
                                    BillingAddress = rdr["BillingAddress"] != DBNull.Value ? rdr["BillingAddress"].ToString() : "",
                                    IsActiveParty = rdr["IsActiveParty"] != DBNull.Value ? Convert.ToByte(rdr["IsActiveParty"]) : (byte)1
                                };
                                listJobber.Add(jobber);
                            }
                        }
                    }
                }

                var responseObj = new
                {
                    Code = 200,
                    Message = "Success",
                    IsAdmin = isAdmin,
                    IsJobber = isJobber,
                    LoggedInJobberId = loggedInJobberId,
                    listJobber = listJobber
                };

                JavaScriptSerializer js = new JavaScriptSerializer();
                Context.Response.Write(js.Serialize(responseObj));
            }
            catch (Exception ex)
            {
                var response = new
                {
                    Code = 500,
                    Message = ex.Message,
                    IsAdmin = false,
                    IsJobber = false,
                    LoggedInJobberId = 0,
                    listJobber = new List<JobberViewModel>()
                };
                JavaScriptSerializer js = new JavaScriptSerializer();
                Context.Response.Write(js.Serialize(response));
            }
        }

