                                module: "Yarn Requirement",
                                action: "CREATE",
                                tableName: "YarnRequirementMaster",
                                recordId: id.ToString(),
                                description: $"Created Yarn Requirement #{myDetails.RequirementNo}",
                                newValue: myDetails,
                                existingConn: con
                            );

                            con.Close();

                            comman.id = Convert.ToInt32(id);
                            comman.Code = 200;
                            comman.Message = "Record has been saved successfully";

                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "Problem has been occurred while submitting your data.";

                        }
                        cmd.Dispose();
                        con.Close();

                    }
                }
                catch (SqlException ex)
                {
                    AuditLogHelper.LogError("Yarn Requirement", "insertYarnRequirementMasterMaster", ex, ilist.YarnRequirementArray);

                    if (ex.Number == 2601 || ex.Number == 2627)
