        // View Design Entry Form
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnRequirementMaster()
        {
            JavaScriptSerializer js;
            List<YarnRequirementMaster> listUser = new List<YarnRequirementMaster>();
            YarnRequirementMasterResponse response = new YarnRequirementMasterResponse();
            var request = HttpContext.Current.Request;
            YarnRequirementMaster ilist = new YarnRequirementMaster();
            ilist.SearchRequirementNo = HttpContext.Current.Request.Params["SearchRequirementNo"];
            ilist.startFrom = HttpContext.Current.Request.Params["startFrom"];
            if (ilist.SearchRequirementNo != "")
            {
                ilist.SearchRequirementNo = " and (YRM.RequirementNo LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or PM.PartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%') ";
            }
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                int UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
                int PartyId = 0;
                con.Open();
                // Get PartyId from UserAccountMaster
                using (SqlCommand cmdParty = new SqlCommand())
                {
                    cmdParty.Connection = con;
                    cmdParty.CommandType = CommandType.Text;
                    cmdParty.CommandText = @"SELECT ISNULL(PartyId,0) FROM UserAccountMaster WHERE UserAccountId = @UserAccountId";
                    cmdParty.Parameters.AddWithValue("@UserAccountId", UserAccountId);
                    object result = cmdParty.ExecuteScalar();
                    if (result != null && result != DBNull.Value) PartyId = Convert.ToInt32(result);
                }

                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = CommandType.Text;

                string PartyFilter = "";

                if (PartyId > 0)
                {
                    PartyFilter = " AND YRM.PartyId = @PartyId ";
                    cmd.Parameters.AddWithValue("@PartyId", PartyId);
                }

                cmd.CommandText = @" SELECT * FROM
                    ( SELECT ROW_NUMBER() OVER (ORDER BY YRM.YarnRequirementID DESC) AS row_num,
                YRM.*,
                ISNULL(PM.PartyName, JM.PartyName) AS PartyName,
                ISNULL(PM.MobileNo, JM.MobileNumber) AS MobileNo,
                ISNULL(PM.AlterMobileNo, JM.AlternateNumber) AS AlterMobileNo,
                ISNULL(PM.Email, JM.Email) AS Email,
                ISNULL(PM.BillingAddress, JM.BillingAddress) AS BillingAddress,
                ISNULL(PM.ShippingAddress, JM.BillingAddress) AS ShippingAddress,
                ISNULL(PM.GSTIN, JM.Gstin) AS GSTIN,
                ISNULL(PM.PAN, JM.PanNo) AS PAN,
                ISNULL(PM.State, JM.PlaceOfSupply) AS State,
                ISNULL(PM.City, JM.City) AS City,
                ISNULL(PM.Pincode, JM.Pincode) AS Pincode,
                PM.BankHolderName,PM.BankAccountNo,PM.BankIFSCCode,
                PM.BankName,PM.BankBranch FROM YarnRequirementMaster YRM
            LEFT JOIN PartyMaster PM
                ON PM.PartyId = YRM.PartyId
            LEFT JOIN JobberMaster JM
                ON JM.Id = YRM.PartyId
            WHERE
                YRM.CompanyId =
                (
                    SELECT CompanyId
                    FROM CompanyMaster
                    WHERE is_default = 1
                )
                AND YRM.FinancialYearID =
                (
                    SELECT FinancialYearID
                    FROM FinancialYearMaster
                    WHERE IsDefault = 1
                )
                " + PartyFilter + @"
                " + ilist.SearchRequirementNo + @"
                    ) t1
                    WHERE t1.row_num BETWEEN @StartRow AND @EndRow
                    ORDER BY t1.YarnRequirementID DESC";

                cmd.Parameters.AddWithValue("@StartRow", Convert.ToInt32(ilist.startFrom) + 1);
                cmd.Parameters.AddWithValue("@EndRow", Convert.ToInt32(ilist.startFrom) + 30);

                using (SqlDataReader rdr = cmd.ExecuteReader())
                {
                    while (rdr.Read())
                    {
                        YarnRequirementMaster condition = new YarnRequirementMaster();

                        condition.YarnRequirementID = Convert.ToInt32(rdr["YarnRequirementID"]);

                        if (rdr["DateandTime"] != DBNull.Value)
                        {
                            condition.DateandTime = Convert.ToDateTime(rdr["DateandTime"]);
                            condition.DateandTimes = condition.DateandTime.ToString("dd-MM-yyyy");
                        }

                        if (rdr["RequirementDate"] != DBNull.Value)
                        {
                            condition.RequirementDate = Convert.ToDateTime(rdr["RequirementDate"]);
                            condition.RequirementDates = condition.RequirementDate.ToString("dd-MM-yyyy");
                        }

                        condition.RequirementNo = Convert.ToInt32(rdr["RequirementNo"]);
                        condition.PartyId = Convert.ToInt32(rdr["PartyId"]);

                        condition.PartyName = Convert.ToString(rdr["PartyName"]).ToUpper();
                        condition.MobileNo = Convert.ToString(rdr["MobileNo"]).ToUpper();
                        condition.AlterMobileNo = Convert.ToString(rdr["AlterMobileNo"]).ToUpper();

                        condition.BillingAddress = Convert.ToString(rdr["BillingAddress"]).ToUpper();
                        condition.ShippingAddress = Convert.ToString(rdr["ShippingAddress"]).ToUpper();

                        condition.GSTIN = Convert.ToString(rdr["GSTIN"]).ToUpper();
                        condition.PanNo = Convert.ToString(rdr["PAN"]).ToUpper();

                        condition.State = Convert.ToString(rdr["State"]).ToUpper();
                        condition.City = Convert.ToString(rdr["City"]).ToUpper();
                        condition.Pincode = Convert.ToString(rdr["Pincode"]).ToUpper();

                        condition.BankHolderName = Convert.ToString(rdr["BankHolderName"]).ToUpper();
                        condition.BankAccountNo = Convert.ToString(rdr["BankAccountNo"]).ToUpper();
                        condition.BankIFSCCode = Convert.ToString(rdr["BankIFSCCode"]).ToUpper();
                        condition.BankName = Convert.ToString(rdr["BankName"]).ToUpper();
                        condition.BankBranch = Convert.ToString(rdr["BankBranch"]).ToUpper();

                        listUser.Add(condition);
                    }
                }
            }


            System.Web.HttpCookie nameCookie = new System.Web.HttpCookie("DesignColorMatchingFormIDs");
            nameCookie.Expires = DateTime.Now.AddDays(-1);
            Context.Response.Cookies.Add(nameCookie);

            response.Code = 200;
            response.Message = "Success";
            response.listYarnRequirementMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnRequirementMasterPaggination()
        {
            JavaScriptSerializer js;
            List<PagginationMaster> listUser = new List<PagginationMaster>();
            PagginationMasterResponse response = new PagginationMasterResponse();

            try
            {
                string searchText = HttpContext.Current.Request.Params["SearchRequirementNo"] ?? "";

                int CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.CommandType = CommandType.Text;

                    string SearchCondition = "";

                    if (!string.IsNullOrWhiteSpace(searchText))
                    {
                        SearchCondition = @"
                    AND (
                        YRM.RequirementNo LIKE @SearchText
                        OR PM.PartyName LIKE @SearchText
                        OR JM.PartyName LIKE @SearchText
                    )";

                        cmd.Parameters.AddWithValue("@SearchText", "%" + searchText.Trim() + "%");
                    }

                    cmd.Parameters.AddWithValue("@CompanyId", CompanyId);

                    cmd.CommandText = @"
                SELECT
                    COUNT(*) AS Total,
                    CEILING(COUNT(*) / 30.0) AS Paggination
                FROM YarnRequirementMaster YRM
                LEFT JOIN PartyMaster PM ON PM.PartyId = YRM.PartyId
                LEFT JOIN JobberMaster JM ON JM.Id = YRM.PartyId
                WHERE YRM.CompanyId = @CompanyId
                AND YRM.FinancialYearID =
                (
                    SELECT TOP 1 FinancialYearID
                    FROM FinancialYearMaster
                    WHERE IsDefault = 1
                )
                " + SearchCondition;

                    con.Open();

                    SqlDataReader rdr = cmd.ExecuteReader();

                    while (rdr.Read())
                    {
                        PagginationMaster condition = new PagginationMaster();

                        condition.Total = Convert.ToInt32(rdr["Total"]);
                        condition.Paggination = Convert.ToInt32(rdr["Paggination"]);

                        listUser.Add(condition);
                    }

                    rdr.Close();
                }

                response.Code = 1;
                response.Message = "Success";
                response.listPagginationMaster = listUser;
            }
            catch (Exception ex)
            {
                response.Code = 0;
                response.Message = ex.Message;
                response.listPagginationMaster = new List<PagginationMaster>();
            }

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }

