        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]

        public void getYarnRequirementDetails()
        {
            var request = HttpContext.Current.Request;

            YarnRequirementMasterResponse response =
                new YarnRequirementMasterResponse();

            List<YarnRequirementMaster> masterList =
                new List<YarnRequirementMaster>();

            try
            {
                // =====================================================
                // YARN REQUIREMENT ID
                // =====================================================

                string encryptedId = request.Params["YarnRequirementID"];

                if (string.IsNullOrEmpty(encryptedId))
                {
                    response.Code = 101;
                    response.Message = "Invalid Yarn Requirement ID";
                    WriteResponse(response);
                    return;
                }

                string lastCharacter =
                    encryptedId.Substring(encryptedId.Length - 6);

                int yarnRequirementID;

                if (lastCharacter != "%3d%3d")
                {
                    string tempId =
                        encryptedId.Replace("==", "") + "%3d%3d";

                    yarnRequirementID =
                        Convert.ToInt32(
                            Decrypt(
                                HttpUtility.UrlDecode(tempId)
                            )
                        );
                }
                else
                {
                    yarnRequirementID =
                        Convert.ToInt32(
                            Decrypt(
                                HttpUtility.UrlDecode(encryptedId)
                            )
                        );
                }


                // =====================================================
                // CONNECTION
                // =====================================================

                string cs =
                    ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;


                // =====================================================
                // LOGGED-IN USER
                // =====================================================

                int loggedInUserAccountId = 0;
                int currentUserPartyId = 0;
                string currentUserRole = "";


                if (HttpContext.Current.Request.Cookies["UserIDs"] != null)
                {
                    string userAccountIdStr =
                        HttpContext.Current.Request
                            .Cookies["UserIDs"]
                            .Value
                            .Split('=')[1];

                    if (!string.IsNullOrEmpty(userAccountIdStr))
                    {
                        loggedInUserAccountId =
                            Convert.ToInt32(userAccountIdStr);
                    }
                }


                // =====================================================
                // GET USER ROLE + PARTY ID
                // =====================================================

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    string userQuery = @"
                SELECT
                    UserRole,
                    ISNULL(PartyId, 0) AS PartyId
                FROM UserAccountMaster
                WHERE UserAccountId = @UserAccountId";


                    using (SqlCommand userCmd =
                        new SqlCommand(userQuery, con))
                    {
                        userCmd.Parameters.Add(
                            "@UserAccountId",
                            SqlDbType.Int
                        ).Value = loggedInUserAccountId;


                        using (SqlDataReader userReader =
                            userCmd.ExecuteReader())
                        {
                            if (userReader.Read())
                            {
                                currentUserRole =
                                    Convert.ToString(
                                        userReader["UserRole"]
                                    ).Trim();

                                currentUserPartyId =
                                    Convert.ToInt32(
                                        userReader["PartyId"]
                                    );
                            }
                        }
                    }
                }


                // =====================================================
                // JOB WORK CHECK
                // =====================================================

                bool isJobWork =
                    string.Equals(
                        currentUserRole,
                        "Job Work",
                        StringComparison.OrdinalIgnoreCase
                    );


                // =====================================================
                // MASTER QUERY
                // =====================================================

                string masterQuery = @"
            SELECT
                ROW_NUMBER() OVER
                (
                    ORDER BY YRM.YarnRequirementID DESC
                ) AS row_num,

                YRM.*,

                ISNULL(PM.PartyName, JM.PartyName) AS PartyName,
                ISNULL(PM.MobileNo, JM.MobileNumber) AS MobileNo,
                ISNULL(PM.AlterMobileNo, JM.AlternateNumber) AS AlterMobileNo,
                ISNULL(PM.Email, JM.Email) AS Email,
                ISNULL(PM.BillingAddress, JM.BillingAddress) AS BillingAddress,
                ISNULL(PM.ShippingAddress, JM.BillingAddress) AS ShippingAddress,
                ISNULL(PM.GSTIN, JM.Gstin) AS GSTIN,
                ISNULL(PM.PAN, JM.PanNo) AS PAN,
                ISNULL(PM.State, JM.PlaceOfSupply) AS State,
                ISNULL(PM.City, JM.City) AS City,
                ISNULL(PM.Pincode, JM.Pincode) AS Pincode,
                PM.BankHolderName,
                PM.BankAccountNo,
                PM.BankIFSCCode,
                PM.BankName,
                PM.BankBranch

            FROM YarnRequirementMaster YRM

            LEFT JOIN PartyMaster PM
                ON PM.PartyId = YRM.PartyId

            LEFT JOIN JobberMaster JM
                ON JM.Id = YRM.PartyId

            WHERE
                YRM.CompanyId =
                (
                    SELECT CompanyId
                    FROM CompanyMaster
                    WHERE is_default = 1
                )

                AND

                YRM.FinancialYearID =
                (
                    SELECT FinancialYearID
                    FROM FinancialYearMaster
                    WHERE IsDefault = 1
                )

                AND

                YRM.YarnRequirementID = @YarnRequirementID
        ";


                // =====================================================
                // ONLY JOB WORK USER => PARTY FILTER
                // =====================================================

                if (isJobWork)
                {
                    masterQuery += @"
                AND YRM.PartyId = @CurrentUserPartyId
            ";
                }


                // =====================================================
                // EXECUTE MASTER QUERY
                // =====================================================

                using (SqlConnection con =
                    new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlCommand cmd =
                        new SqlCommand(masterQuery, con))
                    {
                        cmd.Parameters.Add(
                            "@YarnRequirementID",
                            SqlDbType.Int
                        ).Value = yarnRequirementID;


                        // ---------------------------------------------
                        // PARTY PARAMETER ONLY FOR JOB WORK
                        // ---------------------------------------------

                        if (isJobWork)
                        {
                            cmd.Parameters.Add(
                                "@CurrentUserPartyId",
                                SqlDbType.Int
                            ).Value = currentUserPartyId;
                        }


                        using (SqlDataReader rdr =
                            cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                YarnRequirementMaster master =
                                    new YarnRequirementMaster();


                                // =================================================
                                // MASTER DATA
                                // =================================================

                                master.YarnRequirementID =
                                    Convert.ToInt32(
                                        rdr["YarnRequirementID"]
                                    );


                                master.DateandTime =
                                    Convert.ToDateTime(
                                        rdr["DateandTime"]
                                    );


                                master.RequirementDate =
                                    Convert.ToDateTime(
                                        rdr["RequirementDate"]
                                    );


                                master.DateandTimes =
                                    master.DateandTime
                                    .ToString("dd-MM-yyyy");


                                master.RequirementDates =
                                    master.RequirementDate
                                    .ToString("dd/MM/yyyy");


                                master.RequirementNo =
                                    Convert.ToInt32(
                                        rdr["RequirementNo"]
                                    );


                                master.PartyId =
                                    Convert.ToInt32(
                                        rdr["PartyId"]
                                    );


                                master.PartyName =
                                    Convert.ToString(
                                        rdr["PartyName"]
                                    );


                                master.MobileNo =
                                    Convert.ToString(
                                        rdr["MobileNo"]
                                    );


                                master.AlterMobileNo =
                                    Convert.ToString(
                                        rdr["AlterMobileNo"]
                                    );


                                master.Email =
                                    Convert.ToString(
                                        rdr["Email"]
                                    );


                                master.BillingAddress =
                                    Convert.ToString(
                                        rdr["BillingAddress"]
                                    );


                                master.ShippingAddress =
                                    Convert.ToString(
                                        rdr["ShippingAddress"]
                                    );


                                master.GSTIN =
                                    Convert.ToString(
                                        rdr["GSTIN"]
                                    );


                                master.PanNo =
                                    Convert.ToString(
                                        rdr["PAN"]
                                    );


                                master.State =
                                    Convert.ToString(
                                        rdr["State"]
                                    );


                                master.City =
                                    Convert.ToString(
                                        rdr["City"]
                                    );


                                master.Pincode =
                                    Convert.ToString(
                                        rdr["Pincode"]
                                    );


                                master.BankHolderName =
                                    Convert.ToString(
                                        rdr["BankHolderName"]
                                    );


                                master.BankAccountNo =
                                    Convert.ToString(
                                        rdr["BankAccountNo"]
                                    );


                                master.BankIFSCCode =
                                    Convert.ToString(
                                        rdr["BankIFSCCode"]
                                    );


                                master.BankName =
                                    Convert.ToString(
                                        rdr["BankName"]
                                    );


                                master.BankBranch =
                                    Convert.ToString(
                                        rdr["BankBranch"]
                                    );


                                // =================================================
                                // YARN DETAILS
                                // =================================================

                                master.listYarnRequirementDetail = GetYarnRequirementDetails(yarnRequirementID, cs);


                                masterList.Add(master);
                            }
                        }
                    }
                }


                // =====================================================
                // RESPONSE
                // =====================================================

                if (masterList.Count > 0)
                {
                    response.Code = 200;
                    response.Message = "Success";
                    response.listYarnRequirementMaster = masterList;
                }
                else
                {
                    response.Code = 105;

                    if (isJobWork)
                    {
                        response.Message =
                            "Opps! Requirement Order Not Exist or Access Denied.";
                    }
                    else
                    {
                        response.Message =
                            "Opps! Requirement Order Not Exist.";
                    }

                    response.listYarnRequirementMaster =
                        masterList;
                }
            }
            catch (Exception ex)
            {
                response.Code = 500;
                response.Message = ex.Message;
            }


            WriteResponse(response);
        }

        private List<YarnRequirementDetail> GetYarnRequirementDetails(int yarnRequirementID, string cs)
        {
            List<YarnRequirementDetail> detailList = new List<YarnRequirementDetail>();
            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();

                string query = @"
                             SELECT
                                YRD.*,
                                YMM.YarnMaterial,
                                YCM.YarnColor,
                                YCM.YarnColorCode,
                                ISNULL(PM.PartyName, ISNULL(JM.PartyName, CM.CompanyName)) AS PartyName,
								YRD.CompanyName as companyId
                            FROM YarnRequirementDetail YRD
                            LEFT JOIN YarnMaterialMaster YMM
                                ON YMM.YarnMaterialID = YRD.YarnMaterialID
                            LEFT JOIN YarnColorMaster YCM
                                ON YCM.YarnColorID = YRD.YarnColorID
                            LEFT JOIN PartyMaster PM
                                ON PM.PartyId = YRD.CompanyName
                            LEFT JOIN JobberMaster JM
                                ON JM.Id = YRD.CompanyName
                            LEFT JOIN CompanyMaster CM
                                ON CM.CompanyId = YRD.CompanyName
                            WHERE
                                YRD.YarnRequirementID = @YarnRequirementID";

                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.AddWithValue(
                        "@YarnRequirementID",
                        yarnRequirementID);

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            YarnRequirementDetail item =
                                new YarnRequirementDetail();

                            item.YarnRequirementDetailID =
                                Convert.ToInt32(rdr["YarnRequirementDetailID"]);

                            item.YarnRequirementID =
                                Convert.ToInt32(rdr["YarnRequirementID"]);

                            item.YarnMaterialID =
                                Convert.ToInt32(rdr["YarnMaterialID"]);

                            item.YarnMaterial =
                                Convert.ToString(rdr["YarnMaterial"]);

                            item.YarnColorID =
                                Convert.ToInt32(rdr["YarnColorID"]);

                            item.YarnColor =
                                Convert.ToString(rdr["YarnColor"]);

                            item.YarnColorCode =
                                Convert.ToString(rdr["YarnColorCode"]);

                            item.PartyID =
                                rdr["CompanyName"] == DBNull.Value
                                ? 0
                                : Convert.ToInt32(rdr["CompanyName"]);

                            item.CompanyName =
                                Convert.ToString(rdr["PartyName"]);

                            item.CompanyColourCode =
                                Convert.ToString(rdr["CompanyColourCode"]);
                            item.companyId = Convert.ToInt32(rdr["companyId"]);

                            item.NoofBoxes =
                                rdr["NoofBoxes"] == DBNull.Value
                                ? 0
                                : Convert.ToInt32(rdr["NoofBoxes"]);

                            item.listPartyMaster =
                                GetPartyMasters(
                                    item.YarnMaterialID,
                                    item.YarnColorID,
                                    cs);

                            detailList.Add(item);
                        }
                    }
                }
            }

            return detailList;
        }

        private List<PartyMaster> GetPartyMasters(
            int yarnMaterialID,
            int yarnColorID,
            string cs)
        {
            List<PartyMaster> partyList =
                new List<PartyMaster>();

            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();

                string query = @"
        SELECT DISTINCT
            YPM.PartyId,
            YPM.PartyName
        FROM YarnPODetails YPD
        LEFT JOIN
        (
            SELECT
                YPM.YarnPOID,
                PM.PartyId,
                PM.PartyName
            FROM YarnPOMaster YPM
            LEFT JOIN PartyMaster PM
                ON PM.PartyId = YPM.BillToPartyID
        ) YPM
            ON YPM.YarnPOID = YPD.YarnPOID
        WHERE
            YPD.YarnMaterialID = @YarnMaterialID
        AND
            YPD.YarnColorID = @YarnColorID
        ORDER BY
            YPM.PartyName";

                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.AddWithValue(
                        "@YarnMaterialID",
                        yarnMaterialID);

                    cmd.Parameters.AddWithValue(
                        "@YarnColorID",
                        yarnColorID);

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            partyList.Add(new PartyMaster
                            {
                                PartyId =
                                    Convert.ToInt32(rdr["PartyId"]),
                                PartyName =
                                    Convert.ToString(rdr["PartyName"])
                            });
                        }
                    }
                }
            }

            return partyList;
        }

        private void WriteResponse(object response)
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateYarnRequirementMasterMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);
            //Int64 EmployeeId, CourierDetailId;
            var request = HttpContext.Current.Request;
            string employeeExpenseDate = DateTime.Now.ToString("yyyy-MM-dd");

            CommanResponse comman = new CommanResponse();
            YarnRequirementMaster ilist = new YarnRequirementMaster();

            ilist.DateandTime = Convert.ToDateTime(dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss"));

            string UserAccountId = Context.Request.Cookies["UserIDs"].Value.Split('=')[1];
            string CompanyId = Context.Request.Cookies["CompanyID"].Value.Split('=')[1];
            string FinancialYearID = Context.Request.Cookies["FinacialYearDefaultID"].Value.Split('=')[1];
            ilist.YarnRequirementArray = HttpContext.Current.Request.Params["YarnRequirementArray"];

            if (UserAccountId == "" && CompanyId == "" && FinancialYearID == "")
            {
                comman.Code = 500;
                comman.Message = "Please Re-Login your Account.";
                AuditLogHelper.LogValidationError("Yarn Requirement", "YarnRequirementMaster", null, comman.Message, "UserAccountId, CompanyId, or FinancialYearID is missing");
            }
            else
            {
                var myDetails = JsonConvert.DeserializeObject<YarnRequirementMaster>(ilist.YarnRequirementArray);
                string Tdt = dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss");


                try
                {
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        SqlCommand cmd = new SqlCommand();
                        cmd.Connection = con;
                        cmd.CommandType = System.Data.CommandType.Text;

                        object oldVal = null;
                        using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM YarnRequirementMaster WHERE YarnRequirementID = '" + myDetails.YarnRequirementID + "'", con))
                        {
                            con.Open();
                            using (SqlDataReader rdrOld = cmdOld.ExecuteReader())
                            {
                                if (rdrOld.Read())
                                {
                                    oldVal = new
                                    {
                                        YarnRequirementID = myDetails.YarnRequirementID,
                                        RequirementNo = rdrOld["RequirementNo"] != DBNull.Value ? rdrOld["RequirementNo"].ToString() : null,
                                        RequirementDate = rdrOld["RequirementDate"] != DBNull.Value ? rdrOld["RequirementDate"].ToString() : null,
                                        PartyId = rdrOld["PartyId"] != DBNull.Value ? rdrOld["PartyId"].ToString() : null
                                    };
                                }
                            }
                            con.Close();
                        }

                        string sql = String.Format("Update YarnRequirementMaster set DateandTime = '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', UserAccountId = '" + UserAccountId + "', CompanyId = (select CompanyId from CompanyMaster where is_default = 1), FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)," +
                            "  RequirementDate = '" + DateTime.ParseExact(myDetails.RequirementDates, "dd/MM/yyyy", CultureInfo.InvariantCulture).ToString("yyyy-MM-dd") + "', RequirementNo = '" + myDetails.RequirementNo + "', PartyId = '" + myDetails.PartyId + "' where YarnRequirementID = '" + myDetails.YarnRequirementID + "' ");

                        cmd.CommandText = sql;

                        con.Open();
                        //Int64 id = Convert.ToInt64(cmd.ExecuteScalar());
                        cmd.ExecuteNonQuery();
                        Int64 id = Convert.ToInt64(myDetails.YarnRequirementID);

                        //con.Close();
                        if (id > 0)
                        {



                            if (myDetails.DeleteYarnDetailsArray != "")
                            {
                                string sqld = String.Format("delete from YarnRequirementDetail where YarnRequirementDetailID in (" + myDetails.DeleteYarnDetailsArray + ") ");
                                cmd.CommandText = sqld;
                                cmd.ExecuteNonQuery();
                            }



                            if (myDetails.listYarnRequirementDetail.Count > 0)
                            {
                                foreach (YarnRequirementDetail each in myDetails.listYarnRequirementDetail)
                                {

                                    if (each.YarnRequirementDetailID == 0)
                                    {
                                        string sqls = String.Format("Insert Into YarnRequirementDetail  (DateandTime, UserAccountId, YarnRequirementID, YarnMaterialID, YarnColorID, CompanyName, CompanyColourCode, NoofBoxes) Values  " +
                                          " ( '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', '" + UserAccountId + "', '" + id + "' , '" + each.YarnMaterialID + "', '" + each.YarnColorID + "' , " +
                                          "  '" + each.CompanyName + "', '" + each.CompanyColourCode + "', '" + each.NoofBoxes + "' )");

                                        cmd.CommandText = sqls;
                                        cmd.ExecuteNonQuery();
                                    }
                                    else
                                    {
                                        string sqls = String.Format("update YarnRequirementDetail set DateandTime = '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', UserAccountId = '" + UserAccountId + "', " +
                                            " YarnRequirementID = '" + id + "', YarnMaterialID = '" + each.YarnMaterialID + "', YarnColorID = '" + each.YarnColorID + "', CompanyName = '" + each.CompanyName + "', " +
                                            " CompanyColourCode = '" + each.CompanyColourCode + "', NoofBoxes = '" + each.NoofBoxes + "' where YarnRequirementDetailID = '" + each.YarnRequirementDetailID + "'  ");

                                        cmd.CommandText = sqls;
                                        cmd.ExecuteNonQuery();
                                    }



                                }
                            }


                            AuditLogHelper.Log(
                                module: "Yarn Requirement",
                                action: "UPDATE",
                                tableName: "YarnRequirementMaster",
                                recordId: id.ToString(),
                                description: $"Updated Yarn Requirement #{myDetails.RequirementNo}",
                                oldValue: oldVal,
                                newValue: myDetails,
                                existingConn: con
                            );

                            con.Close();

                            comman.id = Convert.ToInt32(id);
                            comman.Code = 200;
                            comman.Message = "Record has been saved successfully";

                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "Problem has been occurred while submitting your data.";

                        }
                        cmd.Dispose();
                        con.Close();

                    }
                }
                catch (SqlException ex)
                {
                    AuditLogHelper.LogError("Yarn Requirement", "UpdateYarnRequirementMasterMaster", ex, ilist.YarnRequirementArray);

                    if (ex.Number == 2601 || ex.Number == 2627)
                    {
                        AuditLogHelper.LogDuplicateError("Yarn Requirement", "YarnRequirementMaster", "RequirementNo", myDetails.RequirementNo.ToString(), "This Invoice No is already exists.", myDetails);
                        comman.Code = 405;
                        comman.Message = "This Invoice No is already exists.";

                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";

                    }

                }
                catch (Exception ex)
                {
                    AuditLogHelper.LogError("Yarn Requirement", "UpdateYarnRequirementMasterMaster", ex, ilist.YarnRequirementArray);
                    comman.Code = 500;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }





            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
