        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteYarnPOMaster()
        {
            JavaScriptSerializer js;
            CommanResponse comman = new CommanResponse();

            int yarnPOID = 0;
            int.TryParse(HttpContext.Current.Request.Params["YarnPOID"], out yarnPOID);

            if (yarnPOID <= 0)
            {
                AuditLogHelper.LogValidationError("Yarn Purchase Order", "YarnPOMaster", null, "Unable to delete the purchase order because the selected PO ID is invalid.", "yarnPOID <= 0");
                comman.Code = 400;
                comman.Message = "Unable to delete the purchase order because the selected PO ID is invalid.";
                js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();
                using (SqlTransaction trans = con.BeginTransaction())
                {
                    try
                    {
                        // 1. Pre-flight Server-Side Dependency Check against YarnInwardMaster
                        string checkSql = "SELECT COUNT(1) FROM YarnInwardMaster WHERE YarnPOID = @YarnPOID";
                        using (SqlCommand cmdCheck = new SqlCommand(checkSql, con, trans))
                        {
                            cmdCheck.Parameters.Add("@YarnPOID", SqlDbType.Int).Value = yarnPOID;
                            int inwardCount = Convert.ToInt32(cmdCheck.ExecuteScalar());

                            if (inwardCount > 0)
                            {
                                trans.Rollback();
                                AuditLogHelper.LogDependencyError("Yarn Purchase Order", "YarnPOMaster", yarnPOID.ToString(), $"Deletion blocked: Yarn PO #{yarnPOID} has associated Yarn Inward records ({inwardCount} found)", "Associated with existing transactions or related records");
                                comman.Code = 547;
                                comman.Message = "This record cannot be deleted because it is already associated with existing transactions or related records.";
                                js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }
                        }

                        // 2. Read Old Record for Audit Trail & Verify Existence
                        object oldPO = null;
                        using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM YarnPOMaster WHERE YarnPOID = @YarnPOID", con, trans))
                        {
                            cmdOld.Parameters.Add("@YarnPOID", SqlDbType.Int).Value = yarnPOID;
                            using (SqlDataReader rdr = cmdOld.ExecuteReader())
                            {
                                if (rdr.Read())
                                {
                                    oldPO = new
                                    {
                                        YarnPOID = rdr["YarnPOID"],
                                        PONo = rdr["PONo"],
                                        PODate = rdr["PODate"],
                                        SupplierPartyID = rdr["SupplierPartyID"]
                                    };
                                }
                            }
                        }

                        if (oldPO == null)
                        {
                            trans.Rollback();
                            AuditLogHelper.LogValidationError("Yarn Purchase Order", "YarnPOMaster", yarnPOID.ToString(), "The selected purchase order could not be found.", "Record not found");
                            comman.Code = 404;
                            comman.Message = "The selected purchase order could not be found. It may have already been deleted or is no longer available.";
                            js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }

                        // 3. Delete Details
                        using (SqlCommand cmdDetails = new SqlCommand("DELETE FROM YarnPODetails WHERE YarnPOID = @YarnPOID", con, trans))
                        {
                            cmdDetails.Parameters.Add("@YarnPOID", SqlDbType.Int).Value = yarnPOID;
                            cmdDetails.ExecuteNonQuery();
                        }

                        // 4. Delete Master
                        int rowsAffected = 0;
                        using (SqlCommand cmdMaster = new SqlCommand("DELETE FROM YarnPOMaster WHERE YarnPOID = @YarnPOID", con, trans))
                        {
                            cmdMaster.Parameters.Add("@YarnPOID", SqlDbType.Int).Value = yarnPOID;
                            rowsAffected = cmdMaster.ExecuteNonQuery();
                        }

                        if (rowsAffected > 0)
                        {
                            AuditLogHelper.Log(
                                module: "Yarn Purchase Order",
                                action: "DELETE",
                                tableName: "YarnPOMaster",
                                recordId: yarnPOID.ToString(),
                                description: $"Deleted Yarn PO ID #{yarnPOID}",
                                oldValue: oldPO,
                                existingConn: con,
                                existingTran: trans
                            );

                            trans.Commit();
                            comman.Code = 200;
                            comman.Message = "Purchase order deleted successfully.";
                            js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }
                        else
                        {
                            trans.Rollback();
                            comman.Code = 410;
                            comman.Message = "Failed to delete purchase order.";
                            js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }
                    }
                    catch (SqlException ex)
                    {
                        try { trans.Rollback(); } catch { }
                        AuditLogHelper.LogError("Yarn Purchase Order", "DeleteYarnPOMaster", ex, $"YarnPOID={yarnPOID}");

                        if (ex.Number == 547)
                        {
                            AuditLogHelper.LogDependencyError("Yarn Purchase Order", "YarnPOMaster", yarnPOID.ToString(), $"Cannot delete Yarn PO #{yarnPOID} due to foreign key constraints.", "FK constraint violation Number 547");
                            comman.Code = 547;
                            comman.Message = "This record cannot be deleted because it is already associated with existing transactions or related records.";
                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "We couldn't delete this purchase order due to an unexpected system error. Please try again. If the problem persists, contact the administrator.";
                        }

                        js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                    catch (Exception ex)
                    {
                        try { trans.Rollback(); } catch { }
                        AuditLogHelper.LogError("Yarn Purchase Order", "DeleteYarnPOMaster", ex, $"YarnPOID={yarnPOID}");
                        comman.Code = 500;
                        comman.Message = "We couldn't delete this purchase order due to an unexpected system error. Please try again. If the problem persists, contact the administrator.";
                        js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                }
            }
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateYarnPOMasterMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);
            CommanResponse comman = new CommanResponse();

            // Validate cookies exist before reading
            if (Context.Request.Cookies["UserIDs"] == null || Context.Request.Cookies["CompanyID"] == null || Context.Request.Cookies["FinacialYearDefaultID"] == null)
            {
                AuditLogHelper.LogValidationError("Yarn Purchase Order", "YarnPOMaster", null, "Please Re-Login your Account.", "Missing authentication cookies");
                comman.Code = 500;
                comman.Message = "Please Re-Login your Account.";
                SendJsonResponse(comman);
                return;
            }

            string UserAccountId = Context.Request.Cookies["UserIDs"].Value.Split('=')[1];
            string CompanyId = Context.Request.Cookies["CompanyID"].Value.Split('=')[1];
            string FinancialYearID = Context.Request.Cookies["FinacialYearDefaultID"].Value.Split('=')[1];
            string yarnPOArrayJson = HttpContext.Current.Request.Params["YarnPOArray"];

            if (string.IsNullOrEmpty(UserAccountId) || string.IsNullOrEmpty(CompanyId) || string.IsNullOrEmpty(FinancialYearID))
            {
                AuditLogHelper.LogValidationError("Yarn Purchase Order", "YarnPOMaster", null, "Please Re-Login your Account.", "UserAccountId, CompanyId, or FinancialYearID is empty");
                comman.Code = 500;
                comman.Message = "Please Re-Login your Account.";
                SendJsonResponse(comman);
                return;
            }

            var myDetails = JsonConvert.DeserializeObject<YarnPOMaster>(yarnPOArrayJson);

            // 1. SAFELY PARSE THE PO DATE
            string[] expectedDateFormats = { "dd/MM/yyyy", "dd-MM-yyyy", "yyyy-MM-dd", "d/M/yyyy", "d-M-yyyy", "dd/MM/yyyy HH:mm:ss" };
            DateTime parsedPODate;
            if (!DateTime.TryParseExact(myDetails.PODates, expectedDateFormats, CultureInfo.InvariantCulture, DateTimeStyles.None, out parsedPODate))
            {
                parsedPODate = dateTime_Indian; // Fallback or handle error
            }

            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    // Pre-fetch old record before update for audit trail comparison
                    object oldPO = null;
                    using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM YarnPOMaster WHERE YarnPOID = @YarnPOID", con))
                    {
                        cmdOld.Parameters.AddWithValue("@YarnPOID", myDetails.YarnPOID);
                        using (SqlDataReader rdr = cmdOld.ExecuteReader())
                        {
                            if (rdr.Read())
                            {
                                oldPO = new
                                {
                                    YarnPOID = rdr["YarnPOID"],
                                    PONo = rdr["PONo"],
                                    PODate = rdr["PODate"],
                                    SupplierPartyID = rdr["SupplierPartyID"],
                                    TotalQty = rdr["TotalQty"],
                                    TotalAmount = rdr["TotalAmount"]
                                };
                            }
                        }
                    }

                    // 2. UPDATE MASTER USING PARAMETERIZED QUERY (Prevents SQL Injection & Date errors)
                    string sqlMaster = @"UPDATE YarnPOMaster SET 
                                    DateandTime = @DateandTime, UserAccountId = @UserAccountId, CompanyId = @CompanyId, 
                                    FinancialYearID = @FinancialYearID, PODate = @PODate, PONo = @PONo, 
                                    SupplierPartyID = @SupplierPartyID, IsSameAsSupplier = @IsSameAsSupplier, 
                                    BillToPartyID = @BillToPartyID, CompanyPartyID = @CompanyPartyID, 
                                    IsSameAsCompany = @IsSameAsCompany, ShippedToPartyID = @ShippedToPartyID, 
                                    GodownID = @GodownID, TotalQty = @TotalQty, TotalRate = @TotalRate, 
                                    TotalAmount = @TotalAmount, DeliveryTime = @DeliveryTime, 
                                    PaymentCondition = @PaymentCondition, NotesRemarks = @NotesRemarks 
                                 WHERE YarnPOID = @YarnPOID";

                    using (SqlCommand cmd = new SqlCommand(sqlMaster, con))
                    {
                        cmd.Parameters.AddWithValue("@DateandTime", dateTime_Indian);
                        cmd.Parameters.AddWithValue("@UserAccountId", UserAccountId);
                        cmd.Parameters.AddWithValue("@CompanyId", CompanyId);
                        cmd.Parameters.AddWithValue("@FinancialYearID", FinancialYearID);
                        cmd.Parameters.AddWithValue("@PODate", parsedPODate); // SQL Server handles DateTime directly!
                        cmd.Parameters.AddWithValue("@PONo", Convert.ToInt32(myDetails.PONo));
                        cmd.Parameters.AddWithValue("@SupplierPartyID", myDetails.SupplierPartyID);
                        cmd.Parameters.AddWithValue("@IsSameAsSupplier", myDetails.IsSameAsSupplier);
                        cmd.Parameters.AddWithValue("@BillToPartyID", myDetails.BillToPartyID);
                        cmd.Parameters.AddWithValue("@CompanyPartyID", myDetails.CompanyPartyID);
                        cmd.Parameters.AddWithValue("@IsSameAsCompany", myDetails.IsSameAsCompany);
                        cmd.Parameters.AddWithValue("@ShippedToPartyID", myDetails.ShippedToPartyID);
                        cmd.Parameters.AddWithValue("@GodownID", myDetails.GodownID);
                        cmd.Parameters.AddWithValue("@TotalQty", myDetails.TotalQty);
                        cmd.Parameters.AddWithValue("@TotalRate", myDetails.TotalRate);
                        cmd.Parameters.AddWithValue("@TotalAmount", myDetails.TotalAmount);
                        cmd.Parameters.AddWithValue("@DeliveryTime", myDetails.DeliveryTime ?? (object)DBNull.Value);
                        cmd.Parameters.AddWithValue("@PaymentCondition", myDetails.PaymentCondition ?? (object)DBNull.Value);
                        cmd.Parameters.AddWithValue("@NotesRemarks", myDetails.NotesRemarks ?? (object)DBNull.Value);
                        cmd.Parameters.AddWithValue("@YarnPOID", myDetails.YarnPOID);

                        int rowsAffected = cmd.ExecuteNonQuery();

                        if (rowsAffected > 0)
                        {
                            // 3. SAFE DELETE OF CHILD RECORDS
                            if (!string.IsNullOrEmpty(myDetails.DeleteYarnDetailsArray))
                            {
                                // Safely split and parse IDs to integers to strip out any SQL injection attempts
                                var idsToDelete = myDetails.DeleteYarnDetailsArray
                                    .Split(',')
                                    .Select(id => int.TryParse(id.Trim(), out int val) ? val : 0)
                                    .Where(val => val > 0)
                                    .ToList();

                                if (idsToDelete.Any())
                                {
                                    string inClause = string.Join(",", idsToDelete);
                                    string sqlDelete = $"DELETE FROM YarnPODetails WHERE YarnPODetailID IN ({inClause})";
                                    using (SqlCommand cmdDelete = new SqlCommand(sqlDelete, con))
                                    {
                                        cmdDelete.ExecuteNonQuery();
                                    }
                                }
                            }

                            // 4. INSERT / UPDATE CHILD RECORDS
                            if (myDetails.listYarnPODetails != null && myDetails.listYarnPODetails.Count > 0)
                            {
                                foreach (YarnPODetails each in myDetails.listYarnPODetails)
                                {
                                    if (each.YarnPODetailID == 0)
                                    {
                                        string sqlInsertChild = @"INSERT INTO YarnPODetails 
                                                            (DateandTime, UserAccountId, YarnPOID, YarnMaterialID, YarnColorID, CompanyCode, Qty, Rate, GSTSLABId, Amount) 
                                                          VALUES 
                                                            (@DateandTime, @UserAccountId, @YarnPOID, @YarnMaterialID, @YarnColorID, @CompanyCode, @Qty, @Rate, @GSTSLABId, @Amount)";

                                        using (SqlCommand cmdInsert = new SqlCommand(sqlInsertChild, con))
                                        {
                                            cmdInsert.Parameters.AddWithValue("@DateandTime", dateTime_Indian);
                                            cmdInsert.Parameters.AddWithValue("@UserAccountId", UserAccountId);
                                            cmdInsert.Parameters.AddWithValue("@YarnPOID", myDetails.YarnPOID);
                                            cmdInsert.Parameters.AddWithValue("@YarnMaterialID", each.YarnMaterialID);
                                            cmdInsert.Parameters.AddWithValue("@YarnColorID", each.YarnColorID);
                                            cmdInsert.Parameters.AddWithValue("@CompanyCode", each.CompanyCode ?? (object)DBNull.Value);
                                            cmdInsert.Parameters.AddWithValue("@Qty", each.Qty);
                                            cmdInsert.Parameters.AddWithValue("@Rate", each.Rate);
                                            cmdInsert.Parameters.AddWithValue("@GSTSLABId", each.GSTSLABId);
                                            cmdInsert.Parameters.AddWithValue("@Amount", each.Amount);
                                            cmdInsert.ExecuteNonQuery();
                                        }
                                    }
                                    else
                                    {
                                        string sqlUpdateChild = @"UPDATE YarnPODetails SET 
                                                            DateandTime = @DateandTime, UserAccountId = @UserAccountId, YarnPOID = @YarnPOID, 
                                                            YarnMaterialID = @YarnMaterialID, YarnColorID = @YarnColorID, CompanyCode = @CompanyCode, 
                                                            Qty = @Qty, Rate = @Rate, GSTSLABId = @GSTSLABId, Amount = @Amount 
                                                          WHERE YarnPODetailID = @YarnPODetailID";

                                        using (SqlCommand cmdUpdate = new SqlCommand(sqlUpdateChild, con))
                                        {
                                            cmdUpdate.Parameters.AddWithValue("@DateandTime", dateTime_Indian);
                                            cmdUpdate.Parameters.AddWithValue("@UserAccountId", UserAccountId);
                                            cmdUpdate.Parameters.AddWithValue("@YarnPOID", myDetails.YarnPOID);
                                            cmdUpdate.Parameters.AddWithValue("@YarnMaterialID", each.YarnMaterialID);
                                            cmdUpdate.Parameters.AddWithValue("@YarnColorID", each.YarnColorID);
                                            cmdUpdate.Parameters.AddWithValue("@CompanyCode", each.CompanyCode ?? (object)DBNull.Value);
                                            cmdUpdate.Parameters.AddWithValue("@Qty", each.Qty);
                                            cmdUpdate.Parameters.AddWithValue("@Rate", each.Rate);
                                            cmdUpdate.Parameters.AddWithValue("@GSTSLABId", each.GSTSLABId);
                                            cmdUpdate.Parameters.AddWithValue("@Amount", each.Amount);
                                            cmdUpdate.Parameters.AddWithValue("@YarnPODetailID", each.YarnPODetailID);
                                            cmdUpdate.ExecuteNonQuery();
                                        }
                                    }
                                }
                            }

                            AuditLogHelper.Log(
                                module: "Yarn Purchase Order",
                                action: "UPDATE",
                                tableName: "YarnPOMaster",
                                recordId: myDetails.YarnPOID.ToString(),
                                description: $"Updated Yarn PO #{myDetails.PONo}",
                                oldValue: oldPO,
                                newValue: myDetails,
                                existingConn: con
                            );

                            comman.id = Convert.ToInt32(myDetails.YarnPOID);
                            comman.Code = 200;
                            comman.Message = "Record has been updated successfully";
                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "Problem occurred while submitting your data.";
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError("Yarn Purchase Order", "UpdateYarnPOMasterMaster", ex, yarnPOArrayJson);
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    AuditLogHelper.LogDuplicateError("Yarn Purchase Order", "YarnPOMaster", "PONo", myDetails.PONo.ToString(), "This PO No / Invoice No already exists.");
                    comman.Code = 405;
                    comman.Message = "This PO No / Invoice No already exists.";
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem occurred while submitting your data.";
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Yarn Purchase Order", "UpdateYarnPOMasterMaster", ex, yarnPOArrayJson);
                comman.Code = 500;
                comman.Message = "Problem occurred while submitting your data.";
            }

            SendJsonResponse(comman);
        }

        // Helper method to keep response logic DRY
        private void SendJsonResponse(CommanResponse comman)
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.ContentType = "application/json";
            Context.Response.Write(js.Serialize(comman));
        }
