        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnPOinward()
        {
            var request = HttpContext.Current.Request;
            YarnPOMasterResponse response = new YarnPOMasterResponse();
            List<YarnPOMaster> listYarnPO = new List<YarnPOMaster>();

            int yarnPOID = 0;
            int.TryParse(request.Params["YarnPOID"], out yarnPOID);

            int userId = 0;
            if (Context.Request.Cookies["UserIDs"] != null)
            {
                string[] cookieParts = Context.Request.Cookies["UserIDs"].Value.Split('=');
                if (cookieParts.Length > 1)
                {
                    int.TryParse(cookieParts[1], out userId);
                }
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            try
            {
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    string query = @"
            SELECT 
                YPM.*,
                SPPM.PartyName AS ShippedToPartyName,
                SPM.PartyName AS SupplierPartyName,
                BPM.PartyName AS BillToPartyName,
                CPM.PartyName AS CompanyPartyName,
                SPM.MobileNo AS SupplierMobileNo,
                CASE 
                    WHEN SPPM.ShippingAddress IS NULL 
                    THEN SPPM.BillingAddress 
                    ELSE SPPM.ShippingAddress 
                END AS ShippedToBillingAddress,
                GM.GodownTitle,
                GM.GodownAddress
            FROM YarnPOMaster YPM
                LEFT JOIN PartyMaster SPM ON YPM.SupplierPartyID = SPM.PartyId
                LEFT JOIN PartyMaster BPM ON YPM.BillToPartyID = BPM.PartyId
                LEFT JOIN PartyMaster CPM ON YPM.CompanyPartyID = CPM.PartyId
                LEFT JOIN PartyMaster SPPM ON YPM.ShippedToPartyID = SPPM.PartyId
                LEFT JOIN GodownMaster GM ON YPM.GodownID = GM.GodownID
            WHERE YPM.YarnPOID = @YarnPOID";

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.Parameters.AddWithValue("@YarnPOID", yarnPOID);

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                YarnPOMaster item = new YarnPOMaster();

                                item.YarnPOID = Convert.ToInt32(rdr["YarnPOID"]);

                                if (rdr["DateandTime"] != DBNull.Value)
                                {
                                    item.DateandTime = Convert.ToDateTime(rdr["DateandTime"]);
                                    item.DateandTimes = item.DateandTime.ToString("dd-MM-yyyy");
                                }

                                if (rdr["PODate"] != DBNull.Value)
                                {
                                    item.PODate = Convert.ToDateTime(rdr["PODate"]);
                                    item.PODates = item.PODate.ToString("dd/MM/yyyy");
                                }

                                item.PONo = Convert.ToInt32(rdr["PONo"]);

                                item.BillToPartyName = Convert.ToString(rdr["BillToPartyName"]).ToUpper();
                                item.ShippedToPartyName = Convert.ToString(rdr["ShippedToPartyName"]).ToUpper();
                                item.SupplierPartyName = Convert.ToString(rdr["SupplierPartyName"]).ToUpper();
                                item.CompanyPartyName = Convert.ToString(rdr["CompanyPartyName"]).ToUpper();
                                item.SupplierMobileNo = Convert.ToString(rdr["SupplierMobileNo"]).ToUpper();
                                item.ShippedToBillingAddress = Convert.ToString(rdr["ShippedToBillingAddress"]).ToUpper();

                                item.GodownID = rdr["GodownID"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["GodownID"]);
                                item.GodownTitle = Convert.ToString(rdr["GodownTitle"]).ToUpper();
                                item.GodownAddress = Convert.ToString(rdr["GodownAddress"]).ToUpper();

                                item.TotalQty = rdr["TotalQty"] == DBNull.Value ? 0 : Convert.ToDecimal(rdr["TotalQty"]);
                                item.TotalRate = rdr["TotalRate"] == DBNull.Value ? 0 : Convert.ToDecimal(rdr["TotalRate"]);
                                item.TotalAmount = rdr["TotalAmount"] == DBNull.Value ? 0 : Convert.ToDecimal(rdr["TotalAmount"]);

                                item.DeliveryTime = Convert.ToString(rdr["DeliveryTime"]).ToUpper();
                                item.PaymentCondition = Convert.ToString(rdr["PaymentCondition"]).ToUpper();
                                item.NotesRemarks = Convert.ToString(rdr["NotesRemarks"]).ToUpper();

                                listYarnPO.Add(item);
                            }
                        }
                    }

                    foreach (var item in listYarnPO)
                    {
                        string detailQuery = @"
                SELECT DISTINCT
                    YMM.YarnMaterialID,
                    YMM.YarnMaterial
                FROM YarnMaterialMaster YMM
                INNER JOIN
                (
                    SELECT
                        temp.YarnMaterialID
                    FROM
                    (
                        SELECT
                            ypd.*,
                            ISNULL(yim.Received,0) AS Received,
                            ISNULL(yim.IsComplete,0) AS IsComplete,
                            ypd.Qty - ISNULL(yim.Received,0) AS PendingQty
                        FROM YarnPODetails ypd
                        LEFT JOIN
                        (
                            SELECT
                                SUM(TotalWeight) AS Received,
                                YarnMaterialID,
                                YarnPODetailIDCompanyCode,
                                IsComplete
                            FROM YarnInwardMaster
                            WHERE YarnPOID = @YarnPOID
                              AND CompanyId =
                                (SELECT CompanyId
                                 FROM CompanyMaster
                                 WHERE is_default = 1)
                              AND FinancialYearID =
                                (SELECT FinancialYearID
                                 FROM FinancialYearMaster
                                 WHERE IsDefault = 1)
                              AND UserAccountId = @UserId
                            GROUP BY
                                YarnMaterialID,
                                YarnPODetailIDCompanyCode,
                                IsComplete
                        ) yim
                            ON ypd.YarnPODetailID = yim.YarnPODetailIDCompanyCode
                        WHERE ypd.YarnPOID = @YarnPOID
                    ) temp
                    WHERE temp.IsComplete = 0
                      AND temp.PendingQty > 0
                ) T
                ON YMM.YarnMaterialID = T.YarnMaterialID";

                        using (SqlCommand cmdDetail = new SqlCommand(detailQuery, con))
                        {
                            cmdDetail.Parameters.AddWithValue("@YarnPOID", item.YarnPOID);
                            cmdDetail.Parameters.AddWithValue("@UserId", userId);

                            using (SqlDataReader rdrDetail = cmdDetail.ExecuteReader())
                            {
                                List<YarnPODetails> details = new List<YarnPODetails>();

                                while (rdrDetail.Read())
                                {
                                    YarnPODetails detail = new YarnPODetails();

                                    detail.YarnMaterialID =
                                        Convert.ToInt32(rdrDetail["YarnMaterialID"]);

                                    detail.YarnMaterial =
                                        Convert.ToString(rdrDetail["YarnMaterial"]).ToUpper();

                                    details.Add(detail);
                                }

                                item.listYarnPODetails = details;
                            }
                        }
                    }

                    response.Code = listYarnPO.Count > 0 ? 200 : 105;
                    response.Message = listYarnPO.Count > 0
                        ? "Success"
                        : "Opps! Purchase Order Not Exist.";

                    response.listYarnPOMaster = listYarnPO;
                }
            }
            catch (Exception ex)
            {
                response.Code = 500;
                response.Message = ex.Message;
                response.listYarnPOMaster = new List<YarnPOMaster>();
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string getJobberInwardMaster(string OutwardListNo)
        {
            try
            {
                JavaScriptSerializer js = new JavaScriptSerializer();
                js.MaxJsonLength = Int32.MaxValue;
                string conStr = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                string userId = "0";
                string challanNo = "";
                if (HttpContext.Current.Request.Cookies["UserIDs"] != null)
                {
                    userId = HttpContext.Current.Request.Cookies["UserIDs"].Value.Split('=')[1];
                }


                DataSet ds = new DataSet();
                using (SqlConnection con = new SqlConnection(conStr))
                {
                    con.Open();
                    try
                    {
                        using (SqlCommand setIso = new SqlCommand("SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;", con))
                        {
                            setIso.CommandTimeout = 30;
                            setIso.ExecuteNonQuery();
                        }
                    }
                    catch { }

                    string userRole = "";
                    int partyId = 0;

                    using (SqlCommand cmdParty = new SqlCommand("SELECT PartyId FROM UserAccountMaster WITH (NOLOCK) WHERE UserAccountID=@UserAccountID", con))
                    {
                        cmdParty.CommandTimeout = 120;
                        cmdParty.Parameters.AddWithValue("@UserAccountID", userId);

                        object obj = cmdParty.ExecuteScalar();

                        if (obj != null && obj != DBNull.Value)
                        {
                            partyId = Convert.ToInt32(obj);
                        }
                    }
                    string partyQuery = @"
                        SELECT TOP 1
                            X.PartyId,
                            X.UserRole,
                            X.SourceType,
                            X.OutwardListNo
                        FROM
                        (
                            SELECT
                                YOM.YarnOutwardID AS OutwardID,
                                CAST(YOM.YarnOutwardID AS VARCHAR(50)) AS OutwardListNo,
                                YOM.PartyId,
                                U.UserRole,
                                'Admin' AS SourceType
                            FROM YarnOutwardMaster YOM WITH (NOLOCK)
                            INNER JOIN UserAccountMaster U WITH (NOLOCK)
                                ON U.PartyId = YOM.PartyId
                            WHERE YOM.YarnOutwardID = @OutwardListNo

                            UNION ALL

                            SELECT
                                JOM.JobberOutwardID AS OutwardID,
                                CAST(JOM.OutwardListNo AS VARCHAR(50)) AS OutwardListNo,
                                JOM.PartyId,
                                U.UserRole,
                                'JOBBER' AS SourceType
                            FROM JobberOutwardMaster JOM WITH (NOLOCK)
                            INNER JOIN UserAccountMaster U WITH (NOLOCK)
                                ON U.PartyId = JOM.PartyId
                            WHERE JOM.JobberOutwardID = @OutwardListNo
                        ) X";
                    challanNo = GetNextChallanNo(partyId);
                    using (SqlCommand partyCmd = new SqlCommand(partyQuery, con))
                    {
                        partyCmd.CommandTimeout = 120;
                        partyCmd.Parameters.AddWithValue("@OutwardListNo", OutwardListNo);
                        SqlDataReader dr = partyCmd.ExecuteReader();
                        if (dr.Read())
                        {
                            userRole = dr["SourceType"].ToString();
                        }
                        dr.Close();
                    }
                    string query = "";

                    if (userRole == "Admin")
                    {
                        query = @"
        -- =========================================
        -- MASTER: ADMIN OUTWARD
        -- =========================================
        SELECT
            YOM.*,

            CASE
                WHEN YOM.SundryPartyID = 3 THEN JM.PartyName
                ELSE SPM.PartyName
            END AS SupplierPartyName,

            CASE
                WHEN YOM.SundryPartyID = 3 THEN JM.MobileNumber
                ELSE SPM.MobileNo
            END AS SupplierMobileNo,

            CM.CompanyName,
            SPM.PartyPrefix,

            CASE
                WHEN YOM.SundryPartyID = 3
                    THEN JM.BillingAddress
                WHEN ISNULL(SPM.ShippingAddress, '') = ''
                    THEN SPM.BillingAddress
                ELSE SPM.ShippingAddress
            END AS ShippedToBillingAddress,

            GM.GodownTitle,
            GM.GodownAddress

        FROM YarnOutwardMaster YOM WITH (NOLOCK)

        LEFT JOIN CompanyMaster CM WITH (NOLOCK)
            ON CM.CompanyId = YOM.CompanyId

        LEFT JOIN PartyMaster SPM WITH (NOLOCK)
            ON SPM.PartyId = YOM.PartyId
            AND ISNULL(YOM.SundryPartyID, 0) <> 3

        LEFT JOIN JobberMaster JM WITH (NOLOCK)
            ON JM.Id = YOM.PartyId
            AND YOM.SundryPartyID = 3

        LEFT JOIN GodownMaster GM WITH (NOLOCK)
            ON GM.GodownID = YOM.GodownID

        WHERE YOM.YarnOutwardID = @OutwardListNo
          AND YOM.PartyId = @PartyId;


        -- =========================================
        -- DETAIL: ADMIN OUTWARD
        -- =========================================
        SELECT
            YOD.OutwardListNo,
            YOD.OutwardListDate,

            CASE
                WHEN YOD.SundryPartyID = 3 THEN JM.PartyName
                ELSE PM.PartyName
            END AS PartyName,

            YMM.YarnMaterial,
            YCM.YarnColor,
            YOSD.BoxNo,
            YOSD.BarcodeNo,
            YOSD.NetWeight,
            GM.GodownTitle,
            GM.GodownAddress,
            GL.LocationTitle

        FROM YarnOutwardMaster YOD WITH (NOLOCK)

        LEFT JOIN YarnOutwardScanMaster YOSM WITH (NOLOCK)
            ON YOSM.YarnOutwardID = YOD.YarnOutwardID

        LEFT JOIN YarnOutwardScanMasterDetails YOSD WITH (NOLOCK)
            ON YOSD.YarnOutwardScanID = YOSM.YarnOutwardScanID

        LEFT JOIN PartyMaster PM WITH (NOLOCK)
            ON PM.PartyId = YOSD.PartyID
            AND ISNULL(YOD.SundryPartyID, 0) <> 3

        LEFT JOIN JobberMaster JM WITH (NOLOCK)
            ON JM.Id = YOSD.PartyID
            AND YOD.SundryPartyID = 3

        LEFT JOIN YarnMaterialMaster YMM WITH (NOLOCK)
            ON YMM.YarnMaterialID = YOSD.YarnMaterial

        LEFT JOIN YarnColorMaster YCM WITH (NOLOCK)
            ON YCM.YarnColorID = YOSD.YarnColour

        LEFT JOIN GodownLocationMaster GL WITH (NOLOCK)
            ON GL.GodownLocationID = YOSD.GodownLocationID

        LEFT JOIN GodownMaster GM WITH (NOLOCK)
            ON GM.GodownID = GL.GodownID

        WHERE YOD.YarnOutwardID = @OutwardListNo
          AND YOD.PartyId = @PartyId

          AND NOT EXISTS
          (
              SELECT 1
              FROM JobberInwardDetail JD WITH (NOLOCK)

              INNER JOIN JobberInwardMaster JIM WITH (NOLOCK)
                  ON JIM.JobberInwardId = JD.JobberInwardID

              WHERE JIM.ChallanNo = YOD.OutwardListNo
                AND JIM.PartyId = YOD.PartyId
                AND JD.BarcodeNo = YOSD.BarcodeNo
          )

        ORDER BY YOSD.BoxNo;


        -- =========================================
        -- GODOWN LIST
        -- =========================================
        SELECT *
        FROM GodownMaster WITH (NOLOCK)
        WHERE PartyId = @PartyId
        ORDER BY GodownTitle;
    ";
                    }
                    else
                    {
                        query = @"
        -- =========================================
        -- MASTER: JOBBER OUTWARD
        -- =========================================
        SELECT
            JOM.JobberOutwardID AS YarnOutwardID,
            JOM.PartyId,
            JOM.CompanyId,
            JOM.GodownID,
            JOM.FinancialYearID,
            JOM.OutwardListNo,
            JOM.OutwardListDate,

            PM.PartyName AS SupplierPartyName,
            PM.MobileNo AS SupplierMobileNo,
            PM.PartyPrefix,

            CM.CompanyName,

            CASE
                WHEN ISNULL(PM.ShippingAddress, '') = ''
                    THEN PM.BillingAddress
                ELSE PM.ShippingAddress
            END AS ShippedToBillingAddress,

            GM.GodownTitle,
            GM.GodownAddress

        FROM JobberOutwardMaster JOM WITH (NOLOCK)

        LEFT JOIN CompanyMaster CM WITH (NOLOCK)
            ON CM.CompanyId = JOM.CompanyId

        LEFT JOIN PartyMaster PM WITH (NOLOCK)
            ON PM.PartyId = JOM.PartyId

        LEFT JOIN GodownMaster GM WITH (NOLOCK)
            ON GM.GodownID = JOM.GodownID

        WHERE JOM.JobberOutwardID = @OutwardListNo
          AND JOM.PartyId = @PartyId;


        -- =========================================
        -- DETAIL: JOBBER OUTWARD
        -- =========================================
        SELECT
            CAST(JOM.OutwardListNo AS VARCHAR(50)) AS OutwardListNo,
            JOM.OutwardListDate,
            PM.PartyName,
            YMM.YarnMaterial,
            YCM.YarnColor,
            JOD.BoxNo,
            JOD.BarcodeNo,
            JOD.NetWeight,
            GM.GodownTitle,
            GM.GodownAddress,
            GL.LocationTitle

        FROM JobberOutwardMaster JOM WITH (NOLOCK)

        INNER JOIN JobberOutwardDetail JOD WITH (NOLOCK)
            ON JOD.JobberOutwardID = JOM.JobberOutwardID

        LEFT JOIN PartyMaster PM WITH (NOLOCK)
            ON PM.PartyId = JOM.PartyId

        LEFT JOIN YarnMaterialMaster YMM WITH (NOLOCK)
            ON YMM.YarnMaterialID = JOD.YarnMaterialID

        LEFT JOIN YarnColorMaster YCM WITH (NOLOCK)
            ON YCM.YarnColorID = JOD.YarnColorID

        LEFT JOIN GodownLocationMaster GL WITH (NOLOCK)
            ON GL.GodownLocationID = JOM.GodownID

        LEFT JOIN GodownMaster GM WITH (NOLOCK)
            ON GM.GodownID = GL.GodownID

        WHERE JOM.JobberOutwardID = @OutwardListNo
          AND JOM.PartyId = @PartyId

        ORDER BY JOD.BoxNo;


        -- =========================================
        -- GODOWN LIST
        -- =========================================
        SELECT *
        FROM GodownMaster WITH (NOLOCK)
        WHERE PartyId = @PartyId
        ORDER BY GodownTitle;
    ";
                    }

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.CommandTimeout = 120;
                        cmd.Parameters.AddWithValue("@OutwardListNo", OutwardListNo);
                        cmd.Parameters.AddWithValue("@PartyId", partyId);
                        SqlDataAdapter da = new SqlDataAdapter(cmd);
                        da.Fill(ds);
                    }

                }

                // All barcode already inward
                if (ds.Tables.Count < 2 || (ds.Tables[0].Rows.Count == 0 && ds.Tables[1].Rows.Count == 0))
                {

                    var notFoundResponse = new
                    {
                        Status = false,
                        Message = "No detail data found."
                    };
                    return js.Serialize(notFoundResponse);
                }

                if (ds.Tables[0].Rows.Count > 0 && ds.Tables[1].Rows.Count == 0)
                {
                    var alreadyAddedResponse = new
                    {
                        Status = false,
                        Message = "This Challan No already added.",
                        Master = new List<Dictionary<string, object>>(),
                        Detail = new List<Dictionary<string, object>>(),
                        Godown = new List<Dictionary<string, object>>()
                    };


                    return js.Serialize(alreadyAddedResponse);
                }

                var response = new
                {
                    Status = true,
                    Message = "",
                    ChallanNo = challanNo,
                    Master = ds.Tables.Count > 0
                        ? DataTableToList(ds.Tables[0])
                        : new List<Dictionary<string, object>>(),

                    Detail = ds.Tables.Count > 1
                        ? DataTableToList(ds.Tables[1])
                        : new List<Dictionary<string, object>>(),

                    Godown = ds.Tables.Count > 2
                        ? DataTableToList(ds.Tables[2])
                        : new List<Dictionary<string, object>>()
                };

                return js.Serialize(response);
            }
            catch (Exception ex)
            {
                JavaScriptSerializer js = new JavaScriptSerializer();

                return js.Serialize(new
                {
                    Status = false,
                    Message = ex.Message
                });
            }
        }

        [WebMethod]
        public string GetNextChallanNo(int partyId)
        {
            string challanNo = string.Empty;

            string conStr = ConfigurationManager
                .ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(conStr))
            {
                con.Open();

                // Check PartyMaster first, then JobberMaster.
                string query = @"
            DECLARE @Prefix NVARCHAR(50) = 'JOB';
            DECLARE @IsJobber BIT = 0;

            IF EXISTS (
                SELECT 1
                FROM PartyMaster
                WHERE PartyId = @PartyId
                  AND ISNULL(SundryParty, 0) = 3
            )
            BEGIN
                SET @IsJobber = 1;
            END
            ELSE IF NOT EXISTS (
                SELECT 1
                FROM PartyMaster
                WHERE PartyId = @PartyId
            )
            BEGIN
                SET @IsJobber = 1;
            END;

            IF @IsJobber = 1
            BEGIN
                SELECT @Prefix = ISNULL(Prefix, 'JOB')
                FROM JobberMaster
                WHERE Id = @PartyId;
            END
            ELSE
            BEGIN
                SELECT @Prefix = ISNULL(PartyPrefix, 'JOB')
                FROM PartyMaster
                WHERE PartyId = @PartyId;
            END;

            SELECT
                ISNULL(@Prefix, 'JOB') +
                RIGHT(
                    '00' + CAST(
                        ISNULL(
                            MAX(
                                TRY_CAST(
                                    REPLACE(ChallanNo, ISNULL(@Prefix, 'JOB'), '')
                                    AS INT
                                )
                            ), 0
                        ) + 1 AS VARCHAR(20)
                    ), 2
                ) AS ChallanNo
            FROM JobberInwardMaster
            WHERE PartyId = @PartyId
              AND ChallanNo LIKE ISNULL(@Prefix, 'JOB') + '%';
        ";

                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.Add("@PartyId", SqlDbType.Int).Value = partyId;

                    object obj = cmd.ExecuteScalar();

                    if (obj != null && obj != DBNull.Value)
                        challanNo = Convert.ToString(obj);
                }
            }

            return challanNo;
        }


        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string GetJobberInwardList(int IsComplete)
        {
            try
            {
                int PartyId = GetPartyId();

                DataTable dt = new DataTable();

                using (SqlConnection con = new SqlConnection(
                    ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
                {
                    con.Open();
                    try
                    {
                        using (SqlCommand setIso = new SqlCommand("SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;", con))
                        {
                            setIso.CommandTimeout = 30;
                            setIso.ExecuteNonQuery();
                        }
                    }
                    catch { }

                    string query = @"
                        
;WITH LatestJobberInward AS
(
    SELECT *
    FROM
    (
        SELECT *,
               ROW_NUMBER() OVER
               (
                   PARTITION BY JobWorkOutwardId
                   ORDER BY JobberInwardId DESC
               ) AS RN
        FROM JobberInwardMaster WITH (NOLOCK)
    ) X
    WHERE RN = 1
)

--=========================================================
-- ADMIN OUTWARD
--=========================================================
SELECT
    'ADMIN' AS SourceType,

    CAST(ISNULL(UM.UserAccountId, 0) AS VARCHAR(20))
    + '|'
    + CAST(ISNULL(YOM.YarnOutwardID, 0) AS VARCHAR(20))
    + '|'
    + CAST(
        ISNULL(
            CASE
                WHEN YOM.SundryPartyID = 3 THEN JM.Id
                ELSE PM.PartyId
            END, 0
        ) AS VARCHAR(20)
    ) AS GeneratedLink,

    YOM.YarnOutwardID,
    LI.JobberInwardId AS JobberInwardId,

    CAST(YOM.OutwardListNo AS VARCHAR(50)) AS ChallanNo,

    CONVERT(VARCHAR(10), YOSM.ChallanDate, 103) AS AssignDate,
    CONVERT(VARCHAR(10), LI.DateAndTime, 103) AS ReceivedDate,

    CASE
        WHEN YOM.SundryPartyID = 3 THEN JM.PartyName
        ELSE PM.PartyName
    END AS PartyName,

    STRING_AGG(
        ISNULL(YMM.YarnMaterial, ''),
        ', '
    ) AS YarnMaterial,

    STRING_AGG(
        ISNULL(YCM.YarnColor, ''),
        ', '
    ) AS YarnColor,

    STRING_AGG(
        CAST(ISNULL(YOSD.NetWeight, 0) AS VARCHAR(20)),
        ', '
    ) AS NetWeight,

    COUNT(DISTINCT YOSD.BarcodeNo) AS TotalBox,
    SUM(ISNULL(YOSD.NetWeight, 0)) AS TotalWeight,

    ISNULL(LI.PendingWeight, 0) AS PendingWeight,

    ISNULL(LI.TotalWeight, 0)
        - ISNULL(LI.PendingWeight, 0) AS ReceivedWeight,

    CASE
        WHEN LI.JobberInwardId IS NOT NULL
             AND ISNULL(LI.PendingWeight, 0) = 0
        THEN 'Accepted'
        ELSE 'Pending'
    END AS StatusName

FROM YarnOutwardMaster YOM WITH (NOLOCK)

LEFT JOIN PartyMaster PM WITH (NOLOCK)
    ON PM.PartyId = YOM.PartyId
    AND ISNULL(YOM.SundryPartyID, 0) <> 3

LEFT JOIN JobberMaster JM WITH (NOLOCK)
    ON JM.Id = YOM.PartyId
    AND YOM.SundryPartyID = 3

OUTER APPLY (
    SELECT TOP 1 U.UserAccountId
    FROM UserAccountMaster U WITH (NOLOCK)
    WHERE U.PartyId = CASE WHEN YOM.SundryPartyID = 3 THEN JM.Id ELSE PM.PartyId END
) UM

INNER JOIN YarnOutwardScanMaster YOSM WITH (NOLOCK)
    ON YOSM.YarnOutwardID = YOM.YarnOutwardID

INNER JOIN YarnOutwardScanMasterDetails YOSD WITH (NOLOCK)
    ON YOSD.YarnOutwardScanID = YOSM.YarnOutwardScanID

LEFT JOIN YarnMaterialMaster YMM WITH (NOLOCK)
    ON YMM.YarnMaterialID = YOSD.YarnMaterial

LEFT JOIN YarnColorMaster YCM WITH (NOLOCK)
    ON YCM.YarnColorID = YOSD.YarnColour

LEFT JOIN LatestJobberInward LI
    ON LI.JobWorkOutwardId = YOM.YarnOutwardID

WHERE
    (@PartyId = 0 OR YOM.PartyId = @PartyId)

GROUP BY
    UM.UserAccountId,
    PM.PartyId,
    JM.Id,
    YOM.SundryPartyID,
    YOM.YarnOutwardID,
    YOM.OutwardListNo,
    YOSM.ChallanDate,
    LI.DateAndTime,
    PM.PartyName,
    JM.PartyName,
    LI.JobberInwardId,
    LI.TotalWeight,
    LI.PendingWeight

HAVING
(
    @IsComplete = 0
    AND
    (
        LI.JobberInwardId IS NULL
        OR ISNULL(LI.PendingWeight, 0) > 0
    )
)
OR
(
    @IsComplete = 1
    AND LI.JobberInwardId IS NOT NULL
    AND ISNULL(LI.PendingWeight, 0) = 0
)

UNION ALL

--=========================================================
-- JOBBER OUTWARD
-- Existing logic preserved
--=========================================================
SELECT
    'JOBBER' AS SourceType,

    CAST(ISNULL(UM.UserAccountId, 0) AS VARCHAR(20))
    + '|'
    + CAST(ISNULL(JOM.JobberOutwardID, 0) AS VARCHAR(20))
    + '|'
    + CAST(ISNULL(PM.PartyId, 0) AS VARCHAR(20)) AS GeneratedLink,

    JOM.JobberOutwardID AS YarnOutwardID,
    JIM.JobberInwardId AS JobberInwardId,

    CAST(JOM.OutwardListNo AS VARCHAR(50)) AS ChallanNo,

    CONVERT(VARCHAR(10), JOM.OutwardListDate, 103) AS AssignDate,
    CONVERT(VARCHAR(10), JIM.DateAndTime, 103) AS ReceivedDate,

    PM.PartyName,

    STRING_AGG(
        ISNULL(YMM.YarnMaterial, ''),
        ', '
    ) AS YarnMaterial,

    STRING_AGG(
        ISNULL(YCM.YarnColor, ''),
        ', '
    ) AS YarnColor,

    STRING_AGG(
        CAST(ISNULL(JOD.NoOfBox, 0) AS VARCHAR(20)),
        ', '
    ) AS NetWeight,

    SUM(ISNULL(JOD.NoOfBox, 0)) AS TotalBox,
    SUM(ISNULL(JOD.NoOfBox, 0)) AS TotalWeight,

    CASE
        WHEN MAX(
            CASE
                WHEN JIM.PartyId = JOM.PartyId THEN 1
                ELSE 0
            END
        ) = 1
        THEN 0
        ELSE SUM(ISNULL(JOD.NoOfBox, 0))
    END AS PendingWeight,

    CASE
        WHEN MAX(
            CASE
                WHEN JIM.PartyId = JOM.PartyId THEN 1
                ELSE 0
            END
        ) = 1
        THEN SUM(ISNULL(JOD.NoOfBox, 0))
        ELSE 0
    END AS ReceivedWeight,

    CASE
        WHEN MAX(
            CASE
                WHEN JIM.PartyId = JOM.PartyId THEN 1
                ELSE 0
            END
        ) = 1
        THEN 'Accepted'
        ELSE 'Pending'
    END AS StatusName

FROM JobberOutwardMaster JOM WITH (NOLOCK)

INNER JOIN JobberOutwardDetail JOD WITH (NOLOCK)
    ON JOD.JobberOutwardID = JOM.JobberOutwardID

INNER JOIN PartyMaster PM WITH (NOLOCK)
    ON PM.PartyId = JOM.PartyId

OUTER APPLY (
    SELECT TOP 1 U.UserAccountId
    FROM UserAccountMaster U WITH (NOLOCK)
    WHERE U.PartyId = PM.PartyId
) UM

LEFT JOIN YarnMaterialMaster YMM WITH (NOLOCK)
    ON YMM.YarnMaterialID = JOD.YarnMaterialID

LEFT JOIN YarnColorMaster YCM WITH (NOLOCK)
    ON YCM.YarnColorID = JOD.YarnColorID

LEFT JOIN LatestJobberInward JIM
    ON JIM.JobWorkOutwardId = JOM.JobberOutwardID

WHERE
    (@PartyId = 0 OR JOM.PartyId = @PartyId)

GROUP BY
    UM.UserAccountId,
    PM.PartyId,
    JOM.JobberOutwardID,
    JOM.OutwardListNo,
    JOM.OutwardListDate,
    JOM.PartyId,
    PM.PartyName,
    JIM.DateAndTime,
    JIM.JobberInwardId

HAVING
(
    @IsComplete = 0
    AND MAX(
        CASE
            WHEN JIM.PartyId = JOM.PartyId THEN 1
            ELSE 0
        END
    ) = 0
)
OR
(
    @IsComplete = 1
    AND MAX(
        CASE
            WHEN JIM.PartyId = JOM.PartyId THEN 1
            ELSE 0
        END
    ) = 1
);
";

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.CommandTimeout = 120;
                        cmd.Parameters.AddWithValue("@IsComplete", IsComplete);
                        cmd.Parameters.AddWithValue("@PartyId", PartyId);

                        SqlDataAdapter da = new SqlDataAdapter(cmd);

                        da.Fill(dt);

                        // Encrypt GeneratedLink only
                        foreach (DataRow row in dt.Rows)
                        {
                            row["GeneratedLink"] =
                                GetEncryptedLink(
                                    row["GeneratedLink"].ToString()
                                );
                        }
                    }
                }

                return JsonConvert.SerializeObject(dt);
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(new
                {
                    Status = false,
                    Message = ex.Message
                });
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string SaveJobberInward(JobberInwardMasterModel obj)
        {
            if (obj == null || obj.Detail == null || obj.Detail.Count == 0)
            {
                AuditLogHelper.LogValidationError("Jobber Inward", "JobberInwardMaster", null, "Please select at least one box.", "Payload or Details empty", obj);
                return "Please select at least one box.";
            }

            SqlConnection con = null;
            SqlTransaction tran = null;

            try
            {
                string conStr = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                con = new SqlConnection(conStr);
                con.Open();

                tran = con.BeginTransaction();

                long JobberInwardId = 0;

                decimal totalWeight = 0;
                decimal alreadyReceivedWeight = 0;
                decimal currentWeight = 0;
                decimal pendingWeight = 0;

                #region Weight Calculation

                using (SqlCommand cmdWeight = new SqlCommand(@"
            SELECT ISNULL(TotalWeight,0)  FROM YarnOutwardScanMaster WHERE YarnOutwardID = @YarnOutwardID", con, tran))
                {
                    cmdWeight.Parameters.AddWithValue("@YarnOutwardID", obj.JobWorkOutwardId);
                    object result = cmdWeight.ExecuteScalar();
                    if (result != null) totalWeight = Convert.ToDecimal(result);
                }

                using (SqlCommand cmdReceived = new SqlCommand(@"
            SELECT ISNULL(SUM(JID.NetWeight),0)  FROM JobberInwardDetail JID
            INNER JOIN JobberInwardMaster JIM ON JIM.JobberInwardId = JID.JobberInwardId
            WHERE JIM.JobWorkOutwardId = @YarnOutwardID", con, tran))
                {
                    cmdReceived.Parameters.AddWithValue("@YarnOutwardID", obj.JobWorkOutwardId);
                    object received = cmdReceived.ExecuteScalar();
                    if (received != null) alreadyReceivedWeight = Convert.ToDecimal(received);
                }

                currentWeight = obj.Detail.Sum(x => Convert.ToDecimal(x.NetWeight));
                pendingWeight = totalWeight - (alreadyReceivedWeight + currentWeight);

                if (pendingWeight < 0) pendingWeight = 0;

                #endregion

                #region Generate Auto ChallanNo

                // NOTE: Replace 'PartyMaster' with the actual name of the table shown in your screenshot.
                string challanSql = @"
            DECLARE @Prefix NVARCHAR(50);
            
            -- 1. Get the prefix for this specific Party
            SELECT @Prefix = ISNULL(PartyPrefix, 'CH') FROM PartyMaster WHERE PartyId = @PartyId;

            -- 2. Find the last generated ChallanNo for this prefix using UPDLOCK for thread safety
            DECLARE @MaxChallan NVARCHAR(50);
            SELECT TOP 1 @MaxChallan = ChallanNo 
            FROM JobberInwardMaster WITH (UPDLOCK) 
            WHERE ChallanNo LIKE @Prefix + '%' 
            ORDER BY CAST(SUBSTRING(ChallanNo, LEN(@Prefix) + 1, LEN(ChallanNo)) AS INT) DESC;

            -- 3. Increment and pad with zeros
            IF @MaxChallan IS NULL
            BEGIN
                SELECT @Prefix + '01';
            END
            ELSE
            BEGIN
                DECLARE @NextNum INT = CAST(SUBSTRING(@MaxChallan, LEN(@Prefix) + 1, LEN(@MaxChallan)) AS INT) + 1;
                SELECT @Prefix + FORMAT(@NextNum, '00'); -- Ensures output is '01', '02', '10', etc.
            END
        ";

                using (SqlCommand cmdChallan = new SqlCommand(challanSql, con, tran))
                {
                    cmdChallan.Parameters.AddWithValue("@PartyId", obj.PartyId);

                    // Override the ChallanNo from the model with our newly generated one
                    obj.ChallanNo = Convert.ToString(cmdChallan.ExecuteScalar());
                }

                #endregion

                #region Save Master

                string masterQuery = @"
        INSERT INTO JobberInwardMaster
        (
            DateAndTime, JobberId, PartyId, JobWorkOutwardId, ChallanNo, TotalWeight,
            PendingWeight, POPendingWeight, GodownID, PhotoOfInward, CompanyId, IsComplete,
            UserAccountId, FinancialYearID
        )
        VALUES
        (
            @DateAndTime, @JobberId, @PartyId, @JobWorkOutwardId, @ChallanNo, @TotalWeight,
            @PendingWeight, @POPendingWeight, @GodownID, @PhotoOfInward, @CompanyId, @IsComplete,
            @UserAccountId, @FinancialYearID
        );
        SELECT CAST(SCOPE_IDENTITY() AS BIGINT);";

                using (SqlCommand cmd = new SqlCommand(masterQuery, con, tran))
                {
                    DateTime inwardDate = DateTime.ParseExact(obj.DateAndTime, "dd/MM/yyyy", CultureInfo.InvariantCulture);
                    cmd.Parameters.AddWithValue("@DateAndTime", inwardDate);
                    cmd.Parameters.AddWithValue("@JobberId", obj.JobberId);
                    cmd.Parameters.AddWithValue("@PartyId", obj.PartyId);
                    cmd.Parameters.AddWithValue("@JobWorkOutwardId", obj.JobWorkOutwardId);

                    // Uses the dynamically generated ChallanNo here
                    cmd.Parameters.AddWithValue("@ChallanNo", obj.ChallanNo);

                    cmd.Parameters.AddWithValue("@TotalWeight", totalWeight);
                    cmd.Parameters.AddWithValue("@PendingWeight", pendingWeight);
                    cmd.Parameters.AddWithValue("@POPendingWeight", pendingWeight);
                    cmd.Parameters.AddWithValue("@GodownID", obj.GodownID);
                    cmd.Parameters.AddWithValue("@PhotoOfInward", string.IsNullOrEmpty(obj.PhotoOfInward) ? "" : obj.PhotoOfInward);
                    cmd.Parameters.AddWithValue("@CompanyId", Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);
                    cmd.Parameters.AddWithValue("@IsComplete", pendingWeight == 0 ? 1 : 0);
                    cmd.Parameters.AddWithValue("@UserAccountId", Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
                    cmd.Parameters.AddWithValue("@FinancialYearID", obj.FinancialYearID);

                    JobberInwardId = Convert.ToInt64(cmd.ExecuteScalar());
                }

                #endregion

                #region Save Detail

                foreach (var item in obj.Detail)
                {
                    string detailQuery = @"
            INSERT INTO JobberInwardDetail
            (
                DateAndTime, BoxNo, NetWeight, BarcodeNo, GodownLocationID, JobberInwardID,
                UserAccountId, YarnInterchangeID, IsScanStutas, IsScanUpdateDateTime
            )
            VALUES
            (
                GETDATE(), @BoxNo, @NetWeight, @BarcodeNo, @GodownLocationID, @JobberInwardID,
                @UserAccountId, @YarnInterchangeID, @IsScanStutas, GETDATE()
            )";

                    using (SqlCommand cmd = new SqlCommand(detailQuery, con, tran))
                    {
                        cmd.Parameters.AddWithValue("@BoxNo", item.BoxNo);
                        cmd.Parameters.AddWithValue("@NetWeight", item.NetWeight);
                        cmd.Parameters.AddWithValue("@BarcodeNo", item.BarcodeNo);
                        cmd.Parameters.AddWithValue("@GodownLocationID", item.GodownLocationID);
                        cmd.Parameters.AddWithValue("@JobberInwardID", JobberInwardId);
                        cmd.Parameters.AddWithValue("@UserAccountId", Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
                        cmd.Parameters.AddWithValue("@YarnInterchangeID", item.YarnInterchangeID);
                        cmd.Parameters.AddWithValue("@IsScanStutas", item.IsScanStutas);
                        cmd.ExecuteNonQuery();
                    }
                }

                #endregion

                AuditLogHelper.Log(
                    module: "Jobber Inward",
                    action: "CREATE",
                    tableName: "JobberInwardMaster",
                    recordId: JobberInwardId.ToString(),
                    description: $"Created Jobber Inward Challan #{obj.ChallanNo} (Total Weight: {totalWeight})",
                    newValue: obj,
                    existingConn: con,
                    existingTran: tran
                );

                tran.Commit();
                return "Success";
            }
            catch (Exception ex)
            {
                if (tran != null) tran.Rollback();
                AuditLogHelper.LogError("Jobber Inward", "SaveJobberInward", ex, JsonConvert.SerializeObject(obj));
                return ex.Message;
            }
            finally
            {
                if (con != null)
                {
                    if (con.State == ConnectionState.Open) con.Close();
                    con.Dispose();
                }
            }
        }
