        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnInwardMasterPaggination()
        {
            JavaScriptSerializer js;
            List<PagginationMaster> listUser = new List<PagginationMaster>();
            PagginationMasterResponse response = new PagginationMasterResponse();

            var request = HttpContext.Current.Request;
            PagginationMaster ilist = new PagginationMaster();

            ilist.SearchString = HttpContext.Current.Request.Params["SearchRequirementNo"];


            string SearchString = "";
            if (ilist.SearchString != "")
            {
                SearchString = " and (YIM.ChallanNo LIKE'%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or YPO.SupplierPartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%'  ) ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = " select COUNT(*) as Total, CAST(ceiling(CAST(COUNT(*) AS DECIMAL(7,2) ) / CAST(30 AS DECIMAL(7,2) )) AS DECIMAL(7,0)) as Paggination " +
                    " from YarnInwardMaster YIM " +
                    " LEFT JOIN (select YPM.YarnPOID, SPPM.PartyName as 'ShippedToPartyName', SPM.PartyName as 'SupplierPartyName', " +
                    " CPM.PartyName as 'CompanyPartyName', SPM.MobileNo as 'SupplierMobileNo', " +
                    " CASE WHEN SPPM.ShippingAddress IS NULL THEN SPPM.BillingAddress ELSE SPPM.ShippingAddress END as 'ShippedToBillingAddress'" +
                    " from YarnPOMaster YPM" +
                    "  LEFT JOIN PartyMaster SPM ON YPM.SupplierPartyID = SPM.PartyId " +
                    "  LEFT JOIN PartyMaster BPM ON YPM.BillToPartyID = BPM.PartyId" +
                    " LEFT JOIN PartyMaster CPM ON YPM.CompanyPartyID = CPM.PartyId" +
                    " LEFT JOIN PartyMaster SPPM ON YPM.ShippedToPartyID = SPPM.PartyId) as YPO ON YIM.YarnPOID = YPO.YarnPOID" +
                    " where YIM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)" +
                    "  AND YIM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)" +
                    "  AND YIM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " " + SearchString + "";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        PagginationMaster condition = new PagginationMaster();
                        condition.Total = Convert.ToInt32(rdr["Total"].ToString());
                        condition.Paggination = Convert.ToInt32(rdr["Paggination"].ToString());
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listPagginationMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteYarnInwardMaster()
        {
            JavaScriptSerializer js;
            CommanResponse comman = new CommanResponse();

            int yarnInwardID = 0;
            int.TryParse(HttpContext.Current.Request.Params["YarnInwardID"], out yarnInwardID);

            if (yarnInwardID <= 0)
            {
                AuditLogHelper.LogValidationError("Yarn Inward", "YarnInwardMaster", null, "Unable to delete the inward receipt because the selected ID is invalid.", "Invalid YarnInwardID <= 0");
                comman.Code = 400;
                comman.Message = "Unable to delete the inward receipt because the selected ID is invalid.";
                js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();
                using (SqlTransaction trans = con.BeginTransaction())
                {
                    try
                    {
                        // 1. Pre-flight Dependency Check against YarnOutwardDetail
                        string checkSql = @"
                            SELECT COUNT(1) 
                            FROM YarnOutwardDetail YOD 
                            INNER JOIN YarnInwardDetail YID ON YOD.YarnInwardDetailID = YID.YarnInwardDetailID 
                            WHERE YID.YarnInwardID = @YarnInwardID;";

                        using (SqlCommand cmdCheck = new SqlCommand(checkSql, con, trans))
                        {
                            cmdCheck.Parameters.Add("@YarnInwardID", SqlDbType.Int).Value = yarnInwardID;
                            int outwardCount = Convert.ToInt32(cmdCheck.ExecuteScalar());

                            if (outwardCount > 0)
                            {
                                trans.Rollback();
                                AuditLogHelper.LogDependencyError("Yarn Inward", "YarnInwardMaster", yarnInwardID.ToString(), $"Deletion blocked: Yarn Inward #{yarnInwardID} has associated Yarn Outward records ({outwardCount} found)", "Associated with existing Yarn Outward transactions");
                                comman.Code = 547;
                                comman.Message = "This record cannot be deleted because it is already associated with existing transactions or related records.";
                                js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }
                        }

                        // 2. Read Old Record for Audit Log & Photo Path Retrieval
                        string photoOfInward = "";
                        object oldInward = null;
                        using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM YarnInwardMaster WHERE YarnInwardID = @YarnInwardID", con, trans))
                        {
                            cmdOld.Parameters.Add("@YarnInwardID", SqlDbType.Int).Value = yarnInwardID;
                            using (SqlDataReader rdr = cmdOld.ExecuteReader())
                            {
                                if (rdr.Read())
                                {
                                    photoOfInward = rdr["PhotoOfInward"] != DBNull.Value ? rdr["PhotoOfInward"].ToString() : "";
                                    oldInward = new
                                    {
                                        YarnInwardID = rdr["YarnInwardID"],
                                        ChallanNo = rdr["ChallanNo"],
                                        YarnInwardDate = rdr["YarnInwardDate"],
                                        YarnPOID = rdr["YarnPOID"]
                                    };
                                }
                            }
                        }

                        if (oldInward == null)
                        {
                            trans.Rollback();
                            AuditLogHelper.LogValidationError("Yarn Inward", "YarnInwardMaster", yarnInwardID.ToString(), "The selected yarn inward receipt could not be found.", "Record not found");
                            comman.Code = 404;
                            comman.Message = "The selected yarn inward receipt could not be found. It may have already been deleted or is no longer available.";
                            js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }

                        // 3. Delete Details
                        using (SqlCommand cmdDetails = new SqlCommand("DELETE FROM YarnInwardDetail WHERE YarnInwardID = @YarnInwardID", con, trans))
                        {
                            cmdDetails.Parameters.Add("@YarnInwardID", SqlDbType.Int).Value = yarnInwardID;
                            cmdDetails.ExecuteNonQuery();
                        }

                        // 4. Delete Master
                        int rowsAffected = 0;
                        using (SqlCommand cmdMaster = new SqlCommand("DELETE FROM YarnInwardMaster WHERE YarnInwardID = @YarnInwardID", con, trans))
                        {
                            cmdMaster.Parameters.Add("@YarnInwardID", SqlDbType.Int).Value = yarnInwardID;
                            rowsAffected = cmdMaster.ExecuteNonQuery();
                        }

                        if (rowsAffected > 0)
                        {
                            AuditLogHelper.Log(
                                module: "Yarn Inward Receipt",
                                action: "DELETE",
                                tableName: "YarnInwardMaster",
                                recordId: yarnInwardID.ToString(),
                                description: $"Deleted Yarn Inward Receipt ID #{yarnInwardID}",
                                oldValue: oldInward,
                                existingConn: con,
                                existingTran: trans
                            );

                            trans.Commit();

                            // Safe deferred file deletion after successful database commit
                            if (!string.IsNullOrEmpty(photoOfInward))
                            {
                                try
                                {
                                    string path = Server.MapPath(@"" + photoOfInward);
                                    FileInfo fileInfo = new FileInfo(path);
                                    if (fileInfo.Exists)
                                    {
                                        fileInfo.Delete();
                                    }
                                }
                                catch { }
                            }

                            comman.Code = 200;
                            comman.Message = "Yarn inward receipt deleted successfully.";
                            js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }
                        else
                        {
                            trans.Rollback();
                            comman.Code = 410;
                            comman.Message = "Failed to delete inward receipt.";
                            js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }
                    }
                    catch (SqlException ex)
                    {
                        try { trans.Rollback(); } catch { }
                        AuditLogHelper.LogError("Yarn Inward", "DeleteYarnInwardMaster", ex, $"YarnInwardID={yarnInwardID}");

                        if (ex.Number == 547)
                        {
                            comman.Code = 547;
                            comman.Message = "This record cannot be deleted because it is already associated with existing transactions or related records.";
                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "We couldn't delete this inward receipt due to an unexpected system error. Please try again. If the problem persists, contact the administrator.";
                        }

                        js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                    catch (Exception ex)
                    {
                        try { trans.Rollback(); } catch { }
                        AuditLogHelper.LogError("Yarn Inward", "DeleteYarnInwardMaster", ex, $"YarnInwardID={yarnInwardID}");
                        comman.Code = 500;
                        comman.Message = "We couldn't delete this inward receipt due to an unexpected system error. Please try again. If the problem persists, contact the administrator.";
                        js = new JavaScriptSerializer { MaxJsonLength = int.MaxValue };
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                }
            }

        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnInwardDetails()
        {

            var request = HttpContext.Current.Request;
            YarnInwardMasterResponce listYarnInwardMasterR = new YarnInwardMasterResponce();

            List<YarnInwardMaster> listYarnInwardMaster = new List<YarnInwardMaster>();
            //SalesOrderResponseClass salesOrderResponseData = new SalesOrderResponseClass();

            YarnInwardMaster ilist = new YarnInwardMaster();
            string abc = HttpContext.Current.Request.Params["YarnInwardID"];
            //ilist.DesignEntryFormID = Convert.ToInt32(HttpContext.Current.Request.Params["DesignEntryFormID"]);
            string lastCharacter = abc.Substring(abc.Length - 6);

            if (lastCharacter != "%3d%3d")
            {
                string InvoiceId = HttpContext.Current.Request.Params["YarnInwardID"].Replace("==", "") + "%3d%3d";
                ilist.YarnInwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                ilist.YarnInwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(HttpContext.Current.Request.Params["YarnInwardID"])));
            }

            //Upload Cate Master
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText =
                    " select  " +
                    "  YIM.*, YPO.ShippedToPartyName, YPO.SupplierPartyName, YPO.BillToPartyName, YPO.CompanyPartyName, YPO.SupplierMobileNo, YPO.ShippedToBillingAddress," +
                    " YMM.YarnMaterial, YCM.YarnColor, YPD.CompanyCode, GM.GodownTitle, GM.GodownAddress, YPM.PONo" +
                    " from YarnInwardMaster YIM" +
                    " LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID" +
                    " LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID =  YCM.YarnColorID " +
                    " LEFT JOIN YarnPODetails YPD ON YIM.YarnPODetailIDCompanyCode =  YPD.YarnPODetailID " +
                    " LEFT JOIN GodownMaster GM ON YIM.GodownID = GM.GodownID" +
                    " LEFT JOIN YarnPOMaster YPM ON YPM.YarnPOID = YIM.YarnPOID" +
                    " LEFT JOIN (select YPM.YarnPOID, SPPM.PartyName as 'ShippedToPartyName', SPM.PartyName as 'SupplierPartyName', BPM.PartyName as 'BillToPartyName'," +
                    " CPM.PartyName as 'CompanyPartyName', SPM.MobileNo as 'SupplierMobileNo'," +
                    "CASE WHEN SPPM.ShippingAddress IS NULL THEN SPPM.BillingAddress ELSE SPPM.ShippingAddress END as 'ShippedToBillingAddress'" +
                    " from YarnPOMaster YPM" +
                    " LEFT JOIN PartyMaster SPM ON YPM.SupplierPartyID = SPM.PartyId" +
                    " LEFT JOIN PartyMaster BPM ON YPM.BillToPartyID = BPM.PartyId" +
                    " LEFT JOIN PartyMaster CPM ON YPM.CompanyPartyID = CPM.PartyId" +
                    " LEFT JOIN PartyMaster SPPM ON YPM.ShippedToPartyID = SPPM.PartyId) as YPO ON YIM.YarnPOID = YPO.YarnPOID" +
                    " where YIM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)" +
                    " AND YIM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)" +
                    " AND YIM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " " +
                    " AND YIM.YarnInwardID = '" + ilist.YarnInwardID + "'  ";

                SqlDataReader rdr = cmd.ExecuteReader();
                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnInwardMaster condition = new YarnInwardMaster();
                        condition.YarnInwardID = Convert.ToInt32(rdr["YarnInwardID"].ToString());
                        condition.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"].ToString());
                        condition.YarnInwardDate = Convert.ToDateTime(rdr["YarnInwardDate"].ToString());
                        condition.ChallanDate = Convert.ToDateTime(rdr["ChallanDate"].ToString());
                        condition.DateAndTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                        condition.YarnInwardDates = Convert.ToDateTime(rdr["YarnInwardDate"].ToString()).ToString("dd-MM-yyyy");
                        condition.ChallanDates = Convert.ToDateTime(rdr["ChallanDate"].ToString()).ToString("dd-MM-yyyy");
                        condition.ChallanNo = Convert.ToInt32(rdr["ChallanNo"].ToString());
                        condition.PartyChallanNo = rdr["PartyChallanNo"].ToString().ToUpper();
                        condition.YarnPOID = Convert.ToInt32(rdr["YarnPOID"].ToString());
                        condition.YarnPoNo = Convert.ToInt32(rdr["PONo"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnPODetailIDCompanyCode = Convert.ToInt32(rdr["YarnPODetailIDCompanyCode"].ToString());
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.ColourCode = rdr["CompanyCode"].ToString().ToUpper();
                        condition.LotNo = rdr["LotNo"].ToString().ToUpper();
                        condition.TotalWeight = Convert.ToDecimal(rdr["TotalWeight"].ToString());
                        condition.PendingWeight = Convert.ToDecimal(rdr["PendingWeight"].ToString());
                        condition.POPendingWeight = Convert.ToDecimal(rdr["POPendingWeight"].ToString());
                        condition.GodownID = Convert.ToInt32(rdr["GodownID"].ToString());
                        condition.GodownTitle = rdr["GodownTitle"].ToString().ToUpper();
                        condition.GodownAddress = rdr["GodownAddress"].ToString().ToUpper();
                        condition.ShippedToName = rdr["ShippedToPartyName"].ToString().ToUpper();
                        condition.SupplierName = rdr["SupplierPartyName"].ToString().ToUpper();
                        condition.BillToPartyName = rdr["BillToPartyName"].ToString().ToUpper();
                        condition.CompanyName = rdr["CompanyPartyName"].ToString().ToUpper();
                        condition.MobileNo = rdr["SupplierMobileNo"].ToString().ToUpper();
                        condition.ShippedtoAddress = rdr["ShippedToBillingAddress"].ToString().ToUpper();
                        condition.PhotoOfInward = rdr["PhotoOfInward"].ToString().ToUpper();

                        SqlCommand cmd1 = new SqlCommand(@"select YID.*,GLM.LocationTitle from YarnInwardDetail YID
                                    LEFT JOIN GodownLocationMaster GLM ON GLM.GodownLocationID = YID.GodownLocationID  where YID.YarnInwardID=@YarnInwardID", con);
                        cmd1.Parameters.AddWithValue("@YarnInwardID", condition.YarnInwardID);

                        SqlDataReader rdr1 = cmd1.ExecuteReader();
                        List<YarnInwardDetail> YarnInwardDetail = new List<YarnInwardDetail>();
                        if (rdr1.HasRows)
                        {
                            while (rdr1.Read())
                            {
                                YarnInwardDetail YarnPOD = new YarnInwardDetail();
                                YarnPOD.YarnInwardDetailID = Convert.ToInt32(rdr1["YarnInwardDetailID"]);
                                //YarnPOD.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"].ToString());
                                //YarnPOD.DateAndTimes = Convert.ToDateTime(rdr["DateAndTime"].ToString()).ToString("dd-MM-yyyy");
                                YarnPOD.BoxNo = rdr1["BoxNo"].ToString().ToUpper();
                                YarnPOD.BarcodeNo = rdr1["BarcodeNo"].ToString().ToUpper();
                                YarnPOD.NetWeight = Convert.ToDecimal(rdr1["NetWeight"]);
                                YarnPOD.GodownLocationID = Convert.ToInt32(rdr1["GodownLocationID"]);
                                YarnPOD.LocationTitle = rdr1["LocationTitle"].ToString().ToUpper();

                                YarnInwardDetail.Add(YarnPOD);
                            }
                            condition.listYarnInwardDetail = YarnInwardDetail;
                        }

                        rdr1.Close();
                        cmd1.Dispose();

                        listYarnInwardMaster.Add(condition);

                    }

                    listYarnInwardMasterR.Code = 200;
                    listYarnInwardMasterR.Message = "Success";
                    listYarnInwardMasterR.listYarnInwardMaster = listYarnInwardMaster;
                }
                else
                {
                    listYarnInwardMasterR.Code = 105;
                    listYarnInwardMasterR.Message = "Opps! Purchase Order Not Exist.";
                    listYarnInwardMasterR.listYarnInwardMaster = listYarnInwardMaster;
                }
                con.Close();
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnInwardMasterR));
            return;


        }

