        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getLocationDetails()
        {
            var request = HttpContext.Current.Request;
            Int64 customer_id = 0;

            GodownMaster ilist = new GodownMaster();
            ilist.GodownID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownID"]);

            if (!string.IsNullOrEmpty(request.Form["CustomerId"]))
            {
                customer_id = Convert.ToInt64(request.Form["CustomerId"]);
            }

            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);
            string dateVal = dateTime_Indian.ToString("yyyy-MM-dd");
            List<GodownMaster> listPartyMaster = new List<GodownMaster>();
            GodownMasterResponse PartyMasterForm = new GodownMasterResponse();

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd;
                SqlDataReader rdr;
                cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = " select * from GodownLocationMaster where GodownID = '" + ilist.GodownID + "' ";
                con.Open();
                rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        GodownMaster condition = new GodownMaster();
                        condition.GodownLocationID = Convert.ToInt32(rdr["GodownLocationID"]);
                        condition.LocationTitle = rdr["LocationTitle"].ToString().ToUpper();
                        listPartyMaster.Add(condition);
                    }
                }
                rdr.Close();
                cmd.Dispose();
                con.Close();

            }
            PartyMasterForm.Code = 200;
            PartyMasterForm.Message = "Success";
            PartyMasterForm.listGodownMaster = listPartyMaster;

            JavaScriptSerializer js = new JavaScriptSerializer();
            Context.Response.Write(js.Serialize(PartyMasterForm));

            return;
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnMateraColorSupplier()
        {

            var request = HttpContext.Current.Request;
            YarnInterChangeResponce listYarnInterChangeResponce = new YarnInterChangeResponce();

            List<YarnMaterialMaster> listYarnMaterialMaster = new List<YarnMaterialMaster>();
            List<YarnColorMaster> listYarnColorMaster = new List<YarnColorMaster>();
            List<YarnPOMaster> listYarnPOMaster = new List<YarnPOMaster>();
            List<YarnPODetails> listYarnPODetails = new List<YarnPODetails>();
            List<YarnInwardDetail> listYarnInwardDetail = new List<YarnInwardDetail>();
            YarnInterChangeResponce ilist = new YarnInterChangeResponce();
            ilist.GodownID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownID"]);
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                //yarn materail
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;

                cmd.CommandText = @"
                                  SELECT DISTINCT YarnMaterialID, YarnMaterial
                                FROM
                                (
                                    -- Records which are never interchanged
                                    SELECT
                                        YID.YarnInwardDetailID,
                                        YID.DateAndTime,
                                        YID.BoxNo,
                                        YID.NetWeight,
                                        YID.GodownLocationID,
                                        YID.YarnInwardID,
                                        YID.UserAccountId,
                                        GLM.LocationTitle,
                                        YIM.YarnMaterialID,
                                        YIM.YarnColorID,
                                        YCM.YarnColor,
                                        YIM.GodownID,
                                        YIM.YarnPOID,
                                        YIM.TotalWeight,
                                        YMM.YarnMaterial,
                                        GM.GodownTitle,
                                        YPM.PONo,

                                        CASE
                                            WHEN PM.SundryParty = 3 THEN JM.PartyName
                                            ELSE PM.PartyName
                                        END AS PartyName,

                                        YPD.YarnPODetailID,
                                        YPD.CompanyCode,
                                        YIM.CompanyId

                                    FROM YarnInwardDetail YID

                                    LEFT JOIN GodownLocationMaster GLM
                                        ON YID.GodownLocationID = GLM.GodownLocationID

                                    LEFT JOIN YarnInwardMaster YIM
                                        ON YID.YarnInwardID = YIM.YarnInwardID

                                    LEFT JOIN YarnMaterialMaster YMM
                                        ON YIM.YarnMaterialID = YMM.YarnMaterialID

                                    LEFT JOIN YarnColorMaster YCM
                                        ON YIM.YarnColorID = YCM.YarnColorID

                                    LEFT JOIN GodownMaster GM
                                        ON YIM.GodownID = GM.GodownID

                                    LEFT JOIN YarnPOMaster YPM
                                        ON YIM.YarnPOID = YPM.YarnPOID

                                    LEFT JOIN PartyMaster PM
                                        ON YPM.BillToPartyID = PM.PartyId
                                        AND ISNULL(PM.SundryParty, 0) <> 3

                                    LEFT JOIN JobberMaster JM
                                        ON YPM.BillToPartyID = JM.Id
                                        AND PM.SundryParty = 3

                                    LEFT JOIN YarnPODetails YPD
                                        ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID

                                    WHERE YID.YarnInwardDetailID NOT IN
                                    (
                                        SELECT YarnInwardDetailID
                                        FROM YarnInterchangeMaster
                                        WHERE YarnInwardDetailID IS NOT NULL
                                    )

                                    UNION ALL

                                    -- Latest interchange record
                                    SELECT
                                        T.YarnInwardDetailID,
                                        T.DateAndTime,
                                        YID.BoxNo,
                                        YID.NetWeight,
                                        T.GodownLocationID,
                                        YID.YarnInwardID,
                                        T.UserAccountId,
                                        GLM.LocationTitle,
                                        T.YarnMaterialID,
                                        T.YarnColorID,
                                        YCM.YarnColor,
                                        T.GodownID,
                                        T.YarnPOID,
                                        YIM.TotalWeight,
                                        YMM.YarnMaterial,
                                        GM.GodownTitle,
                                        YPM.PONo,

                                        CASE
                                            WHEN PM.SundryParty = 3 THEN JM.PartyName
                                            ELSE PM.PartyName
                                        END AS PartyName,

                                        YPD.YarnPODetailID,
                                        YPD.CompanyCode,
                                        YIM.CompanyId

                                    FROM
                                    (
                                        SELECT *,
                                            ROW_NUMBER() OVER
                                            (
                                                PARTITION BY YarnInwardDetailID
                                                ORDER BY YarnInterchangeID DESC
                                            ) AS rn
                                        FROM YarnInterchangeMaster
                                    ) T

                                    LEFT JOIN YarnInwardDetail YID
                                        ON T.YarnInwardDetailID = YID.YarnInwardDetailID

                                    LEFT JOIN GodownLocationMaster GLM
                                        ON T.GodownLocationID = GLM.GodownLocationID

                                    LEFT JOIN YarnInwardMaster YIM
                                        ON YID.YarnInwardID = YIM.YarnInwardID

                                    LEFT JOIN YarnMaterialMaster YMM
                                        ON T.YarnMaterialID = YMM.YarnMaterialID

                                    LEFT JOIN YarnColorMaster YCM
                                        ON T.YarnColorID = YCM.YarnColorID

                                    LEFT JOIN GodownMaster GM
                                        ON T.GodownID = GM.GodownID

                                    LEFT JOIN YarnPOMaster YPM
                                        ON T.YarnPOID = YPM.YarnPOID

                                    LEFT JOIN PartyMaster PM
                                        ON YPM.BillToPartyID = PM.PartyId
                                        AND ISNULL(PM.SundryParty, 0) <> 3

                                    LEFT JOIN JobberMaster JM
                                        ON YPM.BillToPartyID = JM.Id
                                        AND PM.SundryParty = 3

                                    LEFT JOIN YarnPODetails YPD
                                        ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID

                                    WHERE T.rn = 1

                                ) AS T1

                                WHERE T1.GodownID = " + ilist.GodownID + @"
                                AND T1.UserAccountId = "
                                + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + @"
                                AND T1.CompanyId =
                                (
                                    SELECT CompanyId
                                    FROM CompanyMaster
                                    WHERE is_default = 1
                                )
                                   ";


