    FROM YarnInwardDetail YID

    LEFT JOIN GodownLocationMaster GLM
        ON YID.GodownLocationID = GLM.GodownLocationID

    LEFT JOIN YarnInwardMaster YIM
        ON YID.YarnInwardID = YIM.YarnInwardID

    LEFT JOIN YarnMaterialMaster YMM
        ON YIM.YarnMaterialID = YMM.YarnMaterialID

    LEFT JOIN YarnColorMaster YCM
        ON YIM.YarnColorID = YCM.YarnColorID

    LEFT JOIN GodownMaster GM
        ON YIM.GodownID = GM.GodownID

    LEFT JOIN YarnPOMaster YPM
        ON YIM.YarnPOID = YPM.YarnPOID

    LEFT JOIN PartyMaster PM
        ON YPM.BillToPartyID = PM.PartyId
        AND ISNULL(PM.SundryParty, 0) <> 3

    LEFT JOIN JobberMaster JM
        ON YPM.BillToPartyID = JM.Id
        AND PM.SundryParty = 3

    LEFT JOIN YarnPODetails YPD
        ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID

    WHERE YID.YarnInwardDetailID NOT IN
    (
        SELECT YarnInwardDetailID
        FROM YarnInterchangeMaster
        WHERE YarnInwardDetailID IS NOT NULL
    )

    UNION

    -- Latest interchange record
    SELECT
        T.YarnInwardDetailID,
        T.DateAndTime,
        YID.BoxNo,
        YID.NetWeight,
        T.GodownLocationID,
        YID.YarnInwardID,
        T.UserAccountId,
        GLM.LocationTitle,
        T.YarnMaterialID,
        T.YarnColorID,
        YCM.YarnColor,
        T.GodownID,
        T.YarnPOID,
        YIM.TotalWeight,
        YMM.YarnMaterial,
        GM.GodownTitle,
        YPM.PONo,

        CASE
            WHEN PM.SundryParty = 3 THEN JM.PartyName
            ELSE PM.PartyName
        END AS PartyName,

        YPD.YarnPODetailID,
        YPD.CompanyCode,
        YIM.CompanyId

    FROM
    (
        SELECT *,
            ROW_NUMBER() OVER
            (
                PARTITION BY YarnInwardDetailID
                ORDER BY YarnInterchangeID DESC
            ) AS rn
        FROM YarnInterchangeMaster
    ) T

    LEFT JOIN YarnInwardDetail YID
        ON T.YarnInwardDetailID = YID.YarnInwardDetailID

    LEFT JOIN GodownLocationMaster GLM
        ON T.GodownLocationID = GLM.GodownLocationID

    LEFT JOIN YarnInwardMaster YIM
        ON YID.YarnInwardID = YIM.YarnInwardID

    LEFT JOIN YarnMaterialMaster YMM
        ON T.YarnMaterialID = YMM.YarnMaterialID

    LEFT JOIN YarnColorMaster YCM
        ON T.YarnColorID = YCM.YarnColorID

    LEFT JOIN GodownMaster GM
        ON T.GodownID = GM.GodownID

    LEFT JOIN YarnPOMaster YPM
        ON T.YarnPOID = YPM.YarnPOID

    LEFT JOIN PartyMaster PM
        ON YPM.BillToPartyID = PM.PartyId
        AND ISNULL(PM.SundryParty, 0) <> 3

    LEFT JOIN JobberMaster JM
        ON YPM.BillToPartyID = JM.Id
        AND PM.SundryParty = 3

    LEFT JOIN YarnPODetails YPD
        ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID

    WHERE T.rn = 1

) AS T1

WHERE T1.GodownID = " + ilist.GodownID + @"

AND T1.UserAccountId = "
+ Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + @"

AND T1.CompanyId =
(
    SELECT CompanyId
    FROM CompanyMaster
    WHERE is_default = 1
)
                                ";

                SqlDataReader rdr4 = cmd4.ExecuteReader();


                if (rdr4.HasRows)
                {
                    while (rdr4.Read())
                    {
                        YarnPODetails condition = new YarnPODetails();
                        condition.YarnPODetailID = Convert.ToInt32(rdr4["YarnPODetailID"].ToString());
                        condition.CompanyCode = rdr4["CompanyCode"].ToString().ToUpper();

                        listYarnPODetails.Add(condition);

                        //listYarnPOMaster.Add(condition);
                    }
                }
                //BOX NO
                SqlCommand cmd5 = new SqlCommand();
                cmd5.Connection = con;
                cmd5.CommandType = System.Data.CommandType.Text;
                cmd5.CommandText = @"
                                   SELECT DISTINCT YarnInwardDetailID, BoxNo
                            FROM
                            (
                                -- Records which are never interchanged
                                SELECT
                                    YID.YarnInwardDetailID,
                                    YID.DateAndTime,
                                    YID.BoxNo,
                                    YID.NetWeight,
                                    YID.GodownLocationID,
                                    YID.YarnInwardID,
                                    YID.UserAccountId,
                                    GLM.LocationTitle,
                                    YIM.YarnMaterialID,
                                    YIM.YarnColorID,
                                    YCM.YarnColor,
                                    YIM.GodownID,
                                    YIM.YarnPOID,
                                    YIM.TotalWeight,
                                    YMM.YarnMaterial,
                                    GM.GodownTitle,
                                    YPM.PONo,

                                    CASE
                                        WHEN PM.SundryParty = 3 THEN JM.PartyName
                                        ELSE PM.PartyName
                                    END AS PartyName,

                                    YPD.YarnPODetailID,
                                    YPD.CompanyCode,
                                    YIM.CompanyId

                                FROM YarnInwardDetail YID

                                LEFT JOIN GodownLocationMaster GLM
                                    ON YID.GodownLocationID = GLM.GodownLocationID

                                LEFT JOIN YarnInwardMaster YIM
                                    ON YID.YarnInwardID = YIM.YarnInwardID

                                LEFT JOIN YarnMaterialMaster YMM
                                    ON YIM.YarnMaterialID = YMM.YarnMaterialID

                                LEFT JOIN YarnColorMaster YCM
                                    ON YIM.YarnColorID = YCM.YarnColorID

                                LEFT JOIN GodownMaster GM
                                    ON YIM.GodownID = GM.GodownID

                                LEFT JOIN YarnPOMaster YPM
                                    ON YIM.YarnPOID = YPM.YarnPOID

                                LEFT JOIN PartyMaster PM
                                    ON YPM.BillToPartyID = PM.PartyId
                                    AND ISNULL(PM.SundryParty, 0) <> 3

                                LEFT JOIN JobberMaster JM
                                    ON YPM.BillToPartyID = JM.Id
                                    AND PM.SundryParty = 3

                                LEFT JOIN YarnPODetails YPD
                                    ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID

                                WHERE YID.YarnInwardDetailID NOT IN
                                (
                                    SELECT YarnInwardDetailID
                                    FROM YarnInterchangeMaster
                                    WHERE YarnInwardDetailID IS NOT NULL
                                )

                                UNION

                                -- Latest interchange record
                                SELECT
                                    T.YarnInwardDetailID,
                                    T.DateAndTime,
                                    YID.BoxNo,
                                    YID.NetWeight,
                                    T.GodownLocationID,
                                    YID.YarnInwardID,
                                    T.UserAccountId,
                                    GLM.LocationTitle,
                                    YIM.YarnMaterialID,
                                    YIM.YarnColorID,
                                    YCM.YarnColor,
                                    T.GodownID,
                                    T.YarnPOID,
                                    YIM.TotalWeight,
                                    YMM.YarnMaterial,
                                    GM.GodownTitle,
                                    YPM.PONo,

                                    CASE
                                        WHEN PM.SundryParty = 3 THEN JM.PartyName
                                        ELSE PM.PartyName
                                    END AS PartyName,

                                    YPD.YarnPODetailID,
                                    YPD.CompanyCode,
                                    YIM.CompanyId

                                FROM
                                (
                                    SELECT *,
                                        ROW_NUMBER() OVER
                                        (
                                            PARTITION BY YarnInwardDetailID
                                            ORDER BY YarnInterchangeID DESC
                                        ) AS rn
                                    FROM YarnInterchangeMaster
                                ) T

                                LEFT JOIN YarnInwardDetail YID
                                    ON T.YarnInwardDetailID = YID.YarnInwardDetailID

                                LEFT JOIN GodownLocationMaster GLM
                                    ON T.GodownLocationID = GLM.GodownLocationID

                                LEFT JOIN YarnInwardMaster YIM
                                    ON YID.YarnInwardID = YIM.YarnInwardID

                                LEFT JOIN YarnMaterialMaster YMM
                                    ON T.YarnMaterialID = YMM.YarnMaterialID

                                LEFT JOIN YarnColorMaster YCM
                                    ON T.YarnColorID = YCM.YarnColorID

                                LEFT JOIN GodownMaster GM
                                    ON T.GodownID = GM.GodownID

                                LEFT JOIN YarnPOMaster YPM
                                    ON T.YarnPOID = YPM.YarnPOID

                                LEFT JOIN PartyMaster PM
                                    ON YPM.BillToPartyID = PM.PartyId
                                    AND ISNULL(PM.SundryParty, 0) <> 3

                                LEFT JOIN JobberMaster JM
                                    ON YPM.BillToPartyID = JM.Id
                                    AND PM.SundryParty = 3

                                LEFT JOIN YarnPODetails YPD
                                    ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID

                                WHERE T.rn = 1

                            ) AS T1

                            WHERE T1.GodownID = " + ilist.GodownID + @"

                            AND T1.UserAccountId = "
                            + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + @"

                            AND T1.CompanyId =
                            (
                                SELECT CompanyId
                                FROM CompanyMaster
                                WHERE is_default = 1
                            )
                                ";

                SqlDataReader rdr5 = cmd5.ExecuteReader();


                if (rdr5.HasRows)
                {
                    while (rdr5.Read())
                    {
                        YarnInwardDetail condition = new YarnInwardDetail();
                        condition.YarnInwardDetailID = Convert.ToInt32(rdr5["YarnInwardDetailID"].ToString());
                        condition.BoxNo = rdr5["BoxNo"].ToString().ToUpper();

                        listYarnInwardDetail.Add(condition);
                    }
                }



                listYarnInterChangeResponce.Code = 200;
                listYarnInterChangeResponce.Message = "Success";
                listYarnInterChangeResponce.listYarnMaterialMaster = listYarnMaterialMaster;
                listYarnInterChangeResponce.listYarnColorMaster = listYarnColorMaster;
                listYarnInterChangeResponce.listYarnPOMaster = listYarnPOMaster;
                listYarnInterChangeResponce.listYarnPODetails = listYarnPODetails;
                listYarnInterChangeResponce.listYarnInwardDetail = listYarnInwardDetail;
                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnInterChangeResponce));
            return;
