        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnInterChangeMaterial()
        {

            var request = HttpContext.Current.Request;
            YarnInterChangeResponce listYarnInterChangeResponce = new YarnInterChangeResponce();

            List<YarnColorMaster> listYarnColorMaster = new List<YarnColorMaster>();
            //SalesOrderResponseClass salesOrderResponseData = new SalesOrderResponseClass();

            YarnInterChangeResponce ilist = new YarnInterChangeResponce();
            ilist.GodownLocationID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownLocationID"]);
            ilist.YarnMaterialID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnMaterialID"]);


            //Upload Cate Master
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                //yarn materail
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText =
                    " SELECT * FROM YarnColorMaster WHERE YarnColorID IN  " +
                    " (" +
                    "	select DISTINCT(YarnColorID) from YarnInwardMaster YIM" +
                    "	where YIM.YarnInwardID in (select YarnInwardID from YarnInwardDetail where GodownLocationID = " + ilist.GodownLocationID + ")" +
                    "   AND YarnMaterialID = " + ilist.YarnMaterialID + " " +
                    "   and YIM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " " +
                    "   and YIM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1) " +
                    " 	and YIM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)" +
                    " )";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();


                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnColorMaster condition = new YarnColorMaster();
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();

                        listYarnColorMaster.Add(condition);
                    }

                }

                listYarnInterChangeResponce.Code = 200;
                listYarnInterChangeResponce.Message = "Success";
                listYarnInterChangeResponce.listYarnColorMaster = listYarnColorMaster;

                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnInterChangeResponce));
            return;


        }

