    -- Records which are never interchanged
    -----------------------------------------------------------------------
    SELECT YID.YarnInwardDetailID,YID.DateAndTime,YID.BoxNo,YID.NetWeight,
        YID.BarcodeNo,YID.GodownLocationID,YID.YarnInwardID,YID.UserAccountId,
        GLM.LocationTitle,YIM.YarnMaterialID, YIM.YarnColorID,
        YCM.YarnColor,YIM.GodownID,YIM.YarnPOID,YIM.TotalWeight,
        YMM.YarnMaterial,
        GM.GodownTitle,
        YPM.PONo,
		CASE
            WHEN PM.SundryParty = 3 THEN JM.PartyName
            ELSE PM.PartyName
        END AS PartyName,
        YPD.YarnPODetailID,
        YPD.CompanyCode

    FROM YarnInwardDetail YID
    LEFT JOIN GodownLocationMaster GLM  ON YID.GodownLocationID = GLM.GodownLocationID
    LEFT JOIN YarnInwardMaster YIM ON YID.YarnInwardID = YIM.YarnInwardID
    LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID
    LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID = YCM.YarnColorID
    LEFT JOIN GodownMaster GM ON YIM.GodownID = GM.GodownID
    LEFT JOIN YarnPOMaster YPM ON YIM.YarnPOID = YPM.YarnPOID
    LEFT JOIN PartyMaster PM ON YPM.CompanyPartyID = PM.PartyId AND ISNULL(PM.SundryParty, 0) <> 3
    LEFT JOIN JobberMaster JM ON YPM.CompanyPartyID = JM.Id AND PM.SundryParty = 3
    LEFT JOIN YarnPODetails YPD  ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID
    WHERE YID.YarnInwardDetailID NOT IN (SELECT YarnInwardDetailID FROM YarnInterchangeMaster WHERE YarnInwardDetailID IS NOT NULL)
    UNION ALL
    -----------------------------------------------------------------------
    -- Latest Interchange Record
    -----------------------------------------------------------------------
    SELECT
        T.YarnInwardDetailID,
        T.DateAndTime,
        YID.BoxNo,
        YID.NetWeight,
        YID.BarcodeNo,
        T.GodownLocationID,
        YID.YarnInwardID,
        T.UserAccountId,
        GLM.LocationTitle,
        T.YarnMaterialID,
        T.YarnColorID,
        YCM.YarnColor,
        T.GodownID,
        T.YarnPOID,
        YIM.TotalWeight,
        YMM.YarnMaterial,
        GM.GodownTitle,
        YPM.PONo,

        CASE
            WHEN PM.SundryParty = 3 THEN JM.PartyName
            ELSE PM.PartyName
        END AS PartyName,

        YPD.YarnPODetailID,
        YPD.CompanyCode

    FROM
    (
        SELECT *,
               ROW_NUMBER() OVER
               (
                   PARTITION BY YarnInwardDetailID
                   ORDER BY YarnInterchangeID DESC
               ) AS rn
        FROM YarnInterchangeMaster
    ) T

    LEFT JOIN YarnInwardDetail YID  ON T.YarnInwardDetailID = YID.YarnInwardDetailID

    LEFT JOIN GodownLocationMaster GLM  ON T.GodownLocationID = GLM.GodownLocationID
    LEFT JOIN YarnInwardMaster YIM  ON YID.YarnInwardID = YIM.YarnInwardID

    LEFT JOIN YarnMaterialMaster YMM
        ON T.YarnMaterialID = YMM.YarnMaterialID

    LEFT JOIN YarnColorMaster YCM
        ON T.YarnColorID = YCM.YarnColorID

    LEFT JOIN GodownMaster GM
        ON T.GodownID = GM.GodownID

    LEFT JOIN YarnPOMaster YPM
        ON T.YarnPOID = YPM.YarnPOID

    LEFT JOIN PartyMaster PM
        ON YPM.BillToPartyID = PM.PartyId
        AND ISNULL(PM.SundryParty, 0) <> 3

    LEFT JOIN JobberMaster JM
        ON YPM.BillToPartyID = JM.Id
        AND PM.SundryParty = 3

    LEFT JOIN YarnPODetails YPD
        ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID

    WHERE T.rn = 1

) T1

LEFT JOIN
(
    SELECT DISTINCT YarnInwardDetailID
    FROM YarnInterchangeMaster
) YTCM
    ON T1.YarnInwardDetailID = YTCM.YarnInwardDetailID

WHERE
    T1.GodownID = " + ilist.GodownID + @"
    " + strGodownLocationID + @"
    " + strYarnInwardDetail + @"
    " + strYarnMaterialID + @"
    " + strYarnColorID + @"
    " + strYarnPOID + @"
    " + strYarnPODetailID + @"
    " + SIFTYarnInwardDetail + @"

    AND ISNULL(T1.BoxNo, '') <> ''
    AND ISNULL(T1.BarcodeNo, '') <> ''

    AND NOT EXISTS
    (
        SELECT 1
        FROM YARNOUTWARDScanMasterDetails YOS
        WHERE YOS.BarcodeNo = T1.BarcodeNo
    )

ORDER BY T1.YarnInwardDetailID DESC;";

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();


                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnInterChangeMaster condition = new YarnInterChangeMaster();

                        condition.YarnInwardID = rdr["YarnInwardID"] != DBNull.Value ? Convert.ToInt32(rdr["YarnInwardID"]) : 0;
                        condition.YarnPOID = rdr["YarnPOID"] != DBNull.Value ? Convert.ToInt32(rdr["YarnPOID"]) : 0;
                        condition.YarnMaterialID = rdr["YarnMaterialID"] != DBNull.Value ? Convert.ToInt32(rdr["YarnMaterialID"]) : 0;
                        condition.YarnColorID = rdr["YarnColorID"] != DBNull.Value ? Convert.ToInt32(rdr["YarnColorID"]) : 0;
                        condition.YarnInwardDetailID = rdr["YarnInwardDetailID"] != DBNull.Value ? Convert.ToInt32(rdr["YarnInwardDetailID"]) : 0;
                        condition.GodownLocationID = rdr["GodownLocationID"] != DBNull.Value ? Convert.ToInt32(rdr["GodownLocationID"]) : 0;
                        condition.YarnPODetailID = rdr["YarnPODetailID"] != DBNull.Value ? Convert.ToInt32(rdr["YarnPODetailID"]) : 0;
                        condition.NetWeight = rdr["NetWeight"] != DBNull.Value ? Convert.ToDecimal(rdr["NetWeight"]) : 0;

                        condition.PartyName = rdr["PartyName"]?.ToString().ToUpper() ?? "";
                        condition.YarnMaterial = rdr["YarnMaterial"]?.ToString().ToUpper() ?? "";
                        condition.YarnColor = rdr["YarnColor"]?.ToString().ToUpper() ?? "";
                        condition.BoxNo = rdr["BoxNo"]?.ToString().ToUpper() ?? "";
                        condition.CompanyCode = rdr["CompanyCode"]?.ToString().ToUpper() ?? "";
                        condition.MOVEBOXORNOT = rdr["MOVEBOXORNOT"]?.ToString().ToUpper() ?? "";

                        listYarnInterChangeMaster.Add(condition);
                    }

                }


                listYarnInterChangeResponce.Code = 200;
                listYarnInterChangeResponce.Message = "Success";
                listYarnInterChangeResponce.listYarnInterChangeMaster = listYarnInterChangeMaster;


                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnInterChangeResponce));
            return;


        }

