        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertYarnInterChangeTable()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            CommanResponse comman = new CommanResponse();
            YarnInterChangeResponce ilist = new YarnInterChangeResponce();
            ilist.YarnInwardDetailIDs = HttpContext.Current.Request.Params["YarnInwardDetailIDs"];
            string godownLocStr = HttpContext.Current.Request.Params["GodownLocationID"] ?? "0";
            ilist.GodownLocationID = Convert.ToInt32(godownLocStr);

            string userAccountIdStr = Context.Request.Cookies["UserIDs"] != null ? Context.Request.Cookies["UserIDs"].Value.Split('=')[1] : "0";
            int userAccountId = Convert.ToInt32(userAccountIdStr);

            if (userAccountId <= 0)
            {
                comman.Code = 500;
                comman.Message = "Please Re-Login your Account.";
                AuditLogHelper.LogValidationError("Yarn Interchange", "YarnInterchangeMaster", null, "Validation failed: Session cookie missing.", errorMessage: comman.Message);
                WriteJsonResponse(comman);
                return;
            }

            if (string.IsNullOrWhiteSpace(ilist.YarnInwardDetailIDs))
            {
                comman.Code = 400;
                comman.Message = "YarnInwardDetailIDs parameter is required.";
                AuditLogHelper.LogValidationError("Yarn Interchange", "YarnInterchangeMaster", null, "Validation failed: YarnInwardDetailIDs missing.", errorMessage: comman.Message);
                WriteJsonResponse(comman);
                return;
            }

            if (ilist.GodownLocationID <= 0)
            {
                comman.Code = 400;
                comman.Message = "GodownLocationID is required.";
                AuditLogHelper.LogValidationError("Yarn Interchange", "YarnInterchangeMaster", null, "Validation failed: Invalid GodownLocationID.", errorMessage: comman.Message);
                WriteJsonResponse(comman);
                return;
            }

            List<int> cleanIds = new List<int>();
            foreach (var sId in ilist.YarnInwardDetailIDs.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries))
            {
                if (int.TryParse(sId.Trim(), out int parsedId) && parsedId > 0)
                    cleanIds.Add(parsedId);
            }

            if (cleanIds.Count == 0)
            {
                comman.Code = 400;
                comman.Message = "No valid YarnInwardDetailIDs provided.";
                AuditLogHelper.LogValidationError("Yarn Interchange", "YarnInterchangeMaster", null, "Validation failed: Empty parsed YarnInwardDetailIDs list.", errorMessage: comman.Message);
                WriteJsonResponse(comman);
                return;
            }

            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();
                    using (SqlTransaction trans = con.BeginTransaction())
                    {
                        try
                        {
                            string idListParam = string.Join(",", cleanIds);
                            string selectSql = $@"
                                SELECT YID.YarnInwardDetailID, YID.GodownLocationID, YIM.YarnMaterialID, YIM.YarnColorID, YIM.YarnPOID, YIM.GodownID, YPD.YarnPODetailID
                                FROM YarnInwardDetail YID
                                LEFT JOIN YarnInwardMaster YIM ON YID.YarnInwardID = YIM.YarnInwardID
                                LEFT JOIN YarnPODetails YPD ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID
                                WHERE YID.YarnInwardDetailID IN ({idListParam})";

                            List<Dictionary<string, object>> itemsToProcess = new List<Dictionary<string, object>>();
                            using (SqlCommand cmdSelect = new SqlCommand(selectSql, con, trans))
                            {
                                using (SqlDataReader rdr = cmdSelect.ExecuteReader())
                                {
                                    while (rdr.Read())
                                    {
                                        var dict = new Dictionary<string, object>();
                                        dict["YarnInwardDetailID"] = rdr["YarnInwardDetailID"];
                                        dict["GodownLocationID"] = rdr["GodownLocationID"];
                                        dict["YarnMaterialID"] = rdr["YarnMaterialID"];
                                        dict["YarnColorID"] = rdr["YarnColorID"];
                                        dict["YarnPOID"] = rdr["YarnPOID"];
                                        dict["YarnPODetailID"] = rdr["YarnPODetailID"];
                                        dict["GodownID"] = rdr["GodownID"];
                                        itemsToProcess.Add(dict);
                                    }
                                }
                            }

                            foreach (var item in itemsToProcess)
                            {
                                object yDetailId = item["YarnInwardDetailID"];
                                object oldGodownLocId = item["GodownLocationID"];
                                object yMatId = item["YarnMaterialID"];
                                object yColorId = item["YarnColorID"];
                                object yPoId = item["YarnPOID"];
                                object yPoDetailId = item["YarnPODetailID"];
                                object godownId = item["GodownID"];

                                bool exists = false;
                                using (SqlCommand cmdCheck = new SqlCommand("SELECT TOP 1 1 FROM YarnInterchangeMaster WHERE YarnInwardDetailID = @YID", con, trans))
                                {
                                    cmdCheck.Parameters.AddWithValue("@YID", yDetailId);
                                    object chkRes = cmdCheck.ExecuteScalar();
                                    if (chkRes != null && chkRes != DBNull.Value) exists = true;
                                }

                                if (!exists)
                                {
                                    string sqlInsertOld = @"INSERT INTO YarnInterchangeMaster
                                        (DateAndTime, YarnInwardDetailID, YarnMaterialID, YarnColorID, YarnPOID, YarnPODetailID, GodownID, GodownLocationID, UserAccountId)
                                        VALUES (@DateAndTime, @YID, @YMID, @YCID, @YPOID, @YPDID, @GID, @GLID, @UID)";
                                    using (SqlCommand cmdInsOld = new SqlCommand(sqlInsertOld, con, trans))
                                    {
                                        cmdInsOld.Parameters.AddWithValue("@DateAndTime", dateTime_Indian);
                                        cmdInsOld.Parameters.AddWithValue("@YID", yDetailId ?? DBNull.Value);
                                        cmdInsOld.Parameters.AddWithValue("@YMID", yMatId ?? DBNull.Value);
                                        cmdInsOld.Parameters.AddWithValue("@YCID", yColorId ?? DBNull.Value);
                                        cmdInsOld.Parameters.AddWithValue("@YPOID", yPoId ?? DBNull.Value);
                                        cmdInsOld.Parameters.AddWithValue("@YPDID", yPoDetailId ?? DBNull.Value);
                                        cmdInsOld.Parameters.AddWithValue("@GID", godownId ?? DBNull.Value);
                                        cmdInsOld.Parameters.AddWithValue("@GLID", oldGodownLocId ?? DBNull.Value);
                                        cmdInsOld.Parameters.AddWithValue("@UID", userAccountId);
                                        cmdInsOld.ExecuteNonQuery();
                                    }
                                }

                                string sqlInsertNew = @"INSERT INTO YarnInterchangeMaster
                                    (DateAndTime, YarnInwardDetailID, YarnMaterialID, YarnColorID, YarnPOID, YarnPODetailID, GodownID, GodownLocationID, UserAccountId)
                                    VALUES (@DateAndTime, @YID, @YMID, @YCID, @YPOID, @YPDID, @GID, @GLID, @UID)";
                                using (SqlCommand cmdInsNew = new SqlCommand(sqlInsertNew, con, trans))
                                {
                                    cmdInsNew.Parameters.AddWithValue("@DateAndTime", dateTime_Indian);
                                    cmdInsNew.Parameters.AddWithValue("@YID", yDetailId ?? DBNull.Value);
                                    cmdInsNew.Parameters.AddWithValue("@YMID", yMatId ?? DBNull.Value);
                                    cmdInsNew.Parameters.AddWithValue("@YCID", yColorId ?? DBNull.Value);
                                    cmdInsNew.Parameters.AddWithValue("@YPOID", yPoId ?? DBNull.Value);
                                    cmdInsNew.Parameters.AddWithValue("@YPDID", yPoDetailId ?? DBNull.Value);
                                    cmdInsNew.Parameters.AddWithValue("@GID", godownId ?? DBNull.Value);
                                    cmdInsNew.Parameters.AddWithValue("@GLID", ilist.GodownLocationID);
                                    cmdInsNew.Parameters.AddWithValue("@UID", userAccountId);
                                    cmdInsNew.ExecuteNonQuery();
                                }

                                string sqlUpdate = "UPDATE YarnInwardDetail SET YarnInterchangeID = @GodownLocationID WHERE YarnInwardDetailID = @YarnInwardDetailID";
                                using (SqlCommand cmdUpd = new SqlCommand(sqlUpdate, con, trans))
                                {
                                    cmdUpd.Parameters.AddWithValue("@GodownLocationID", ilist.GodownLocationID);
                                    cmdUpd.Parameters.AddWithValue("@YarnInwardDetailID", yDetailId);
                                    cmdUpd.ExecuteNonQuery();
                                }

                                AuditLogHelper.LogCreate(
                                    module: "Yarn Interchange",
                                    tableName: "YarnInterchangeMaster",
                                    recordId: yDetailId.ToString(),
                                    description: $"Yarn Interchange: InwardDetail #{yDetailId} shifted to GodownLocation #{ilist.GodownLocationID}",
                                    newValue: item,
                                    conn: con,
                                    tran: trans
                                );
                            }

                            trans.Commit();
                            comman.Code = 201;
                            comman.Message = "Record has been saved successfully.";
                            WriteJsonResponse(comman);
                            return;
                        }
                        catch
                        {
                            try { trans.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values.";
                    AuditLogHelper.LogDuplicateError("Yarn Interchange", "YarnInterchangeMaster", null, "SQL duplicate error on interchange", errorMessage: ex.Message);
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has occurred while submitting your data: " + ex.Message;
                    AuditLogHelper.LogError("Yarn Interchange", "insertYarnInterChangeTable", ex, ilist.YarnInwardDetailIDs);
                }
                WriteJsonResponse(comman);
            }
            catch (Exception ex)
            {
                comman.Code = 500;
                comman.Message = "An unexpected error occurred: " + ex.Message;
                AuditLogHelper.LogError("Yarn Interchange", "insertYarnInterChangeTable", ex, ilist.YarnInwardDetailIDs);
                WriteJsonResponse(comman);
            }
        }
