        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getUpdateYarnOutWardArraysData()
        {

            var request = HttpContext.Current.Request;
            YarnOutwardMasterResponce listYarnOutwardMasterResponce = new YarnOutwardMasterResponce();
            List<TotalInwardStockArray> listTotalInwardStockArray = new List<TotalInwardStockArray>();
            List<TotalOutwardStockArray> listTotalOutwardStockArray = new List<TotalOutwardStockArray>();
            List<TotalExistingOutwardStockArray> listTotalExistingOutwardStockArray = new List<TotalExistingOutwardStockArray>();
            List<YarnOutwardMaster> YarnOutwardcondition = new List<YarnOutwardMaster>();
            List<PartyMaster> listPartyMaster = new List<PartyMaster>();
            YarnOutwardMasterResponce ilist = new YarnOutwardMasterResponce();
            //ilist.YarnOutwardID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnOutwardID"]);
            ilist.GodownID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownID"]);

            string abc = HttpContext.Current.Request.Params["YarnOutwardID"];
            string lastCharacter = abc.Substring(abc.Length - 6);

            if (lastCharacter != "%3d%3d")
            {
                string InvoiceId = HttpContext.Current.Request.Params["YarnOutwardID"].Replace("==", "") + "%3d%3d";
                ilist.YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                ilist.YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(HttpContext.Current.Request.Params["YarnOutwardID"])));
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            int partyId = 0;

            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = CommandType.Text;

                cmd.CommandText = @"SELECT * FROM YarnOutwardMaster WITH (NOLOCK) WHERE YarnOutwardID = @YarnOutwardID";

                cmd.Parameters.AddWithValue("@YarnOutwardID", ilist.YarnOutwardID);

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.Read())
                {
                    YarnOutwardMaster yarnOutward = new YarnOutwardMaster();

                    yarnOutward.YarnOutwardID = Convert.ToInt32(rdr["YarnOutwardID"]);
                    yarnOutward.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"]);
                    yarnOutward.PartyId = Convert.ToInt32(rdr["PartyId"]);
                    yarnOutward.OutwardListNo = rdr["OutwardListNo"].ToString();
                    yarnOutward.OutwardListDate = Convert.ToDateTime(rdr["OutwardListDate"]);
                    yarnOutward.GodownManagerUserAccountId = Convert.ToInt32(rdr["GodownManagerUserAccountId"]);
                    yarnOutward.UserAccountId = Convert.ToInt32(rdr["UserAccountId"]);
                    yarnOutward.FinancialYearID = Convert.ToInt32(rdr["FinancialYearID"]);
                    yarnOutward.CompanyId = Convert.ToInt32(rdr["CompanyId"]);
                    yarnOutward.GodownID = Convert.ToInt32(rdr["GodownID"]);

                    partyId = yarnOutward.PartyId;   // ✅ Store PartyId here

                    YarnOutwardcondition.Add(yarnOutward);
                }
            }
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = CommandType.Text;
                cmd.CommandText = @"SELECT SundryParty, PartyName, PartyId FROM PartyMaster  WHERE PartyId = @PartyId";
                cmd.Parameters.AddWithValue("@PartyId", partyId);
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                while (rdr.Read())
                {
                    PartyMaster partyMasters = new PartyMaster();
                    partyMasters.PartyId = Convert.ToInt32(rdr["PartyId"]);
                    partyMasters.SundryParty = rdr["SundryParty"].ToString();
                    partyMasters.PartyName = rdr["PartyName"].ToString();

                    listPartyMaster.Add(partyMasters);
                }
            }

            using (SqlConnection con = new SqlConnection(cs))
            {
                //aLL sTOCK
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;

                cmd.CommandText = @"select ISNULL(SUM(Stock),0) as Stock, t1.BillToPartyID, t1.CompanyName,
                                    t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode from
                                    (
	                                    select  YIM.YarnInwardID, YIM.YarnPOID, YPM.BillToPartyID, YPM.PartyName as 'CompanyName',
	                                    YIM.YarnMaterialID, YMM.YarnMaterial, YIM.YarnColorID, YCM.YarnColor, YCM.YarnColorCode , YIDD.Stock
	                                    from YarnInwardMaster YIM
	                                    LEFT JOIN 
	                                    (
		                                    select YPM.YarnPOID, YPM.BillToPartyID, PM.PartyName from YarnPOMaster YPM
		                                    LEFT JOIN PartyMaster PM ON YPM.BillToPartyID = PM.PartyId
	                                    )YPM ON YIM.YarnPOID = YPM.YarnPOID
	                                    LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID
	                                    LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID = YCM.YarnColorID
	                                    LEFT JOIN 
	                                    (
		                                    select COUNT(*) as Stock, YarnInwardID from YarnInwardDetail 
				                                    where GodownLocationID in (select GodownLocationID from GodownLocationMaster where GodownID =  '" + ilist.GodownID + @"')
				                                    group by YarnInwardID
	                                    ) YIDD ON YIM.YarnInwardID = YIDD.YarnInwardID
                                    ) as t1
                                    where (1=1) and Stock > 0 
                                    group by t1.BillToPartyID, t1.CompanyName,
                                    t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode";



                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();
                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        TotalInwardStockArray condition = new TotalInwardStockArray();
                        condition.BillToPartyID = Convert.ToInt32(rdr["BillToPartyID"].ToString());
                        condition.CompanyName = rdr["CompanyName"].ToString().ToUpper();
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr["YarnColorCode"].ToString().ToUpper();
                        condition.Stock = Convert.ToInt32(rdr["Stock"].ToString());
                        listTotalInwardStockArray.Add(condition);
                    }

                }

                rdr.Close();


                //aLL OUTWARD STOCK 
                cmd.CommandText = @"
                                   select t1.Stock,
                                    t1.BillToPartyID, PM.PartyName, T1.YarnMaterialID, YMM.YarnMaterial,
                                    T1.YarnColorID, YCM.YarnColor, YCM.YarnColorCode, t1.GodownLocationID, GLM.LocationTitle
                                    from(
	                                    select SUM(YOD.NoOfBox) as Stock, YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID, YOD.GodownLocationID, YOM.YarnOutwardID
	                                    from YarnOutwardDetail YOD
	                                    LEFT JOIN YarnOutwardMaster YOM ON YOD.YarnOutwardID = YOM.YarnOutwardID
	                                    where YOM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)
	                                    and YOM.YarnOutwardID != " + ilist.YarnOutwardID + @"
	                                    group by YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID, YOM.YarnOutwardID , YOD.GodownLocationID
                                    ) as t1
                                    LEFT JOIN PartyMaster PM ON t1.BillToPartyID =  PM.PartyId
                                    LEFT JOIN YarnMaterialMaster YMM ON t1.YarnMaterialID = YMM.YarnMaterialID
                                    LEFT JOIN YarnColorMaster YCM ON t1.YarnColorID = YCM.YarnColorID
                                    LEFT JOIN GodownLocationMaster GLM ON t1.GodownLocationID = GLM.GodownLocationID
                                   ";


                SqlDataReader rdr2 = cmd.ExecuteReader();
                if (rdr2.HasRows)
                {
                    while (rdr2.Read())
                    {
                        TotalOutwardStockArray condition = new TotalOutwardStockArray();
                        condition.BillToPartyID = Convert.ToInt32(rdr2["BillToPartyID"].ToString());
                        condition.CompanyName = rdr2["PartyName"].ToString().ToUpper();
                        condition.YarnMaterialID = Convert.ToInt32(rdr2["YarnMaterialID"].ToString());
                        condition.YarnMaterial = rdr2["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColorID = Convert.ToInt32(rdr2["YarnColorID"].ToString());
                        condition.YarnColor = rdr2["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr2["YarnColorCode"].ToString().ToUpper();
                        condition.Stock = Convert.ToInt32(rdr2["Stock"].ToString());
                        condition.GodownLocationID = Convert.ToInt32(rdr2["GodownLocationID"].ToString());
                        condition.LocationTitle = rdr2["LocationTitle"].ToString();
                        listTotalOutwardStockArray.Add(condition);
                    }

                }
                rdr2.Close();


                //aLL eXISTING OUTWARD STOCK 
                cmd.CommandText = @"
                                    select t1.Stock,
                                    t1.BillToPartyID, PM.PartyName, t1.GodownID,T1.YarnMaterialID, YMM.YarnMaterial,
                                    T1.YarnColorID, YCM.YarnColor, YCM.YarnColorCode, t1.GodownLocationID, GLM.LocationTitle
                                    from(
	                                    select SUM(YOD.NoOfBox) as Stock,YOM.GodownID, YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID, YOD.GodownLocationID, YOM.YarnOutwardID
	                                    from YarnOutwardDetail YOD
	                                    LEFT JOIN YarnOutwardMaster YOM ON YOD.YarnOutwardID = YOM.YarnOutwardID
	                                    where YOM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)
	                                    and YOM.YarnOutwardID = " + ilist.YarnOutwardID + @"
	                                    group by YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID, YOM.YarnOutwardID,YOM.GodownID, YOD.GodownLocationID
                                    ) as t1
                                    LEFT JOIN PartyMaster PM ON t1.BillToPartyID =  PM.PartyId
                                    LEFT JOIN YarnMaterialMaster YMM ON t1.YarnMaterialID = YMM.YarnMaterialID
                                    LEFT JOIN YarnColorMaster YCM ON t1.YarnColorID = YCM.YarnColorID
                                    LEFT JOIN GodownLocationMaster GLM ON t1.GodownLocationID = GLM.GodownLocationID
                                   ";

                SqlDataReader rdr3 = cmd.ExecuteReader();
                if (rdr3.HasRows)
                {
                    while (rdr3.Read())
                    {
                        TotalExistingOutwardStockArray condition = new TotalExistingOutwardStockArray();
                        condition.BillToPartyID = Convert.ToInt32(rdr3["BillToPartyID"].ToString());
                        condition.CompanyName = rdr3["PartyName"].ToString().ToUpper();
                        condition.YarnMaterialID = Convert.ToInt32(rdr3["YarnMaterialID"].ToString());
                        condition.YarnMaterial = rdr3["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColorID = Convert.ToInt32(rdr3["YarnColorID"].ToString());
                        condition.YarnColor = rdr3["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr3["YarnColorCode"].ToString().ToUpper();
                        condition.Stock = Convert.ToInt32(rdr3["Stock"].ToString());
                        condition.GodownLocationID = Convert.ToInt32(rdr3["GodownLocationID"].ToString());
                        condition.LocationTitle = rdr3["LocationTitle"].ToString();
                        condition.GodownID = Convert.ToInt32(rdr3["GodownID"].ToString());
                        listTotalExistingOutwardStockArray.Add(condition);
                    }

                }

                rdr3.Close();

                listYarnOutwardMasterResponce.Code = 200;
                listYarnOutwardMasterResponce.Message = "Success";
                listYarnOutwardMasterResponce.listTotalInwardStockArray = listTotalInwardStockArray;
                listYarnOutwardMasterResponce.listTotalOutwardStockArray = listTotalOutwardStockArray;
                listYarnOutwardMasterResponce.listTotalExistingOutwardStockArray = listTotalExistingOutwardStockArray;
                //listYarnOutwardMasterResponce.YarnOutwardcondition = YarnOutwardcondition;
                listYarnOutwardMasterResponce.listPartyMaster = listPartyMaster;
                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnOutwardMasterResponce));
            return;


        }
        [WebMethod]
        public string GetYarnOutwardForEdit(string YarnOutwardID)
        {
            try
            {
                YarnOutwardEditResponse result = new YarnOutwardEditResponse
                {
                    Master = new YarnOutwardMasterModel(),
                    Detail = new List<YarnOutwardDetailModel>()
                };

                // 🔥 Decode + Decrypt
                int id = 0;
                if (!int.TryParse(YarnOutwardID, out id))
                {
                    string decoded = HttpUtility.UrlDecode(YarnOutwardID);
                    if (!decoded.EndsWith("==")) decoded += "==";
                    id = Convert.ToInt32(Decrypt(decoded));
                }
                using (SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
                {
                    con.Open();
                    // ============================
                    // ✅ MASTER
                    // ============================
                    SqlCommand cmd = new SqlCommand(@"
                        SELECT YOM.*, 
                               ISNULL(CASE WHEN YOM.SundryPartyID = 3 THEN JM.PartyName ELSE PM.PartyName END, '') AS PartyName
                        FROM YarnOutwardMaster YOM WITH (NOLOCK)
                        LEFT JOIN PartyMaster PM WITH (NOLOCK) ON YOM.PartyId = PM.PartyId
                        LEFT JOIN JobberMaster JM WITH (NOLOCK) ON YOM.PartyId = JM.Id
                        WHERE YOM.YarnOutwardID = @ID", con);
                    cmd.CommandTimeout = 180;
                    cmd.Parameters.AddWithValue("@ID", id);
                    SqlDataReader dr = cmd.ExecuteReader();
                    if (dr.Read())
                    {
                        result.Master = new YarnOutwardMasterModel
                        {
                            YarnOutwardID = Convert.ToInt32(dr["YarnOutwardID"]),
                            PartyId = Convert.ToInt32(dr["PartyId"]),
                            GodownID = Convert.ToInt32(dr["GodownID"]),
                            OutwardListDate = Convert.ToDateTime(dr["OutwardListDate"]),
                            GodownManagerUserAccountId = Convert.ToInt32(dr["GodownManagerUserAccountId"]),
                            OutwardListNo = Convert.ToInt32(dr["OutwardListNo"]),
                            SundryPartyId = Convert.ToInt32(dr["SundryPartyID"]),
                            PartyName = dr["PartyName"]?.ToString() ?? ""
                        };
                    }
                    dr.Close();

                    // ============================
                    // ✅ DETAIL
                    // ============================
                    cmd = new SqlCommand(@"SELECT 
                                            YOD.YarnOutwardDetailID,
                                            YOD.YarnCompanyID,
                                            YOD.YarnMaterialID,
                                            YOD.YarnColorID,
                                            COALESCE(
                                                (SELECT TOP 1 YRD.CompanyColourCode 
                                                 FROM YarnRequirementDetail YRD WITH (NOLOCK)
                                                 WHERE (YRD.YarnRequirementDetailID = YOD.YarnRequirementDetailID OR YRD.YarnRequirementID = YOD.YarnRequirementDetailID) 
                                                   AND YRD.YarnColorID = YOD.YarnColorID 
                                                   AND ISNULL(YRD.CompanyColourCode, '') <> ''),
                                                (SELECT TOP 1 YPD.CompanyCode 
                                                 FROM YarnPODetails YPD WITH (NOLOCK)
                                                 WHERE YPD.YarnMaterialID = YOD.YarnMaterialID 
                                                   AND YPD.YarnColorID = YOD.YarnColorID 
                                                   AND ISNULL(YPD.CompanyCode, '') <> ''),
                                                YCM.YarnColorCode,
                                                ''
                                            ) AS YarnColorCode,
                                            YOD.GodownLocationID, 
                                            YOD.NoOfBox,
                                            YOD.YarnRequirementDetailID
                                        FROM YarnOutwardDetail YOD WITH (NOLOCK)
                                        LEFT JOIN YarnColorMaster YCM WITH (NOLOCK) ON YCM.YarnColorID = YOD.YarnColorID
                                        WHERE YOD.YarnOutwardID = @ID", con);
                    cmd.CommandTimeout = 180;
                    cmd.Parameters.AddWithValue("@ID", id);

                    dr = cmd.ExecuteReader();

                    while (dr.Read())
                    {
                        result.Detail.Add(new YarnOutwardDetailModel
                        {
                            YarnCompanyID = Convert.ToInt32(dr["YarnCompanyID"]),
                            YarnMaterialID = Convert.ToInt32(dr["YarnMaterialID"]),
                            YarnColorID = Convert.ToInt32(dr["YarnColorID"]),
                            YarnColorCode = (dr["YarnColorCode"]?.ToString().ToUpper() ?? ""),
                            GodownLocationID = Convert.ToInt32(dr["GodownLocationID"]),
                            NoOfBox = Convert.ToInt32(dr["NoOfBox"]),
                            YarnRequirementDetailID = Convert.ToInt32(dr["YarnRequirementDetailID"])
                        });
                    }
                    dr.Close();
                    List<int> requirementIds = new List<int>();
                    cmd = new SqlCommand(@" SELECT DISTINCT 
                                            ISNULL(YRD.YarnRequirementID, YOD.YarnRequirementDetailID) AS YarnRequirementID  
                                        FROM YarnOutwardDetail YOD WITH (NOLOCK)
                                        LEFT JOIN YarnRequirementDetail YRD WITH (NOLOCK) ON (YOD.YarnRequirementDetailID = YRD.YarnRequirementDetailID OR YOD.YarnRequirementDetailID = YRD.YarnRequirementID)
                                        WHERE YOD.YarnOutwardID = @ID AND YOD.YarnRequirementDetailID > 0", con);
                    cmd.CommandTimeout = 180;
                    cmd.Parameters.AddWithValue("@ID", id);
                    dr = cmd.ExecuteReader();
                    while (dr.Read())
                    {
                        requirementIds.Add(Convert.ToInt32(dr["YarnRequirementID"]));
                    }
                    dr.Close();
                    return new JavaScriptSerializer().Serialize(new
                    {
                        Status = 1,
                        Data = result,
                        YarnRequirementIDs = requirementIds
                    });
                }
            }
            catch (Exception ex)
            {
                return new JavaScriptSerializer().Serialize(new
                {
                    Status = 0,
                    Message = ex.Message
                });
            }
        }
        // View Yarn Out Ward
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getUpdateYarnOutwardMaster()
        {
            JavaScriptSerializer js;
            List<YarnOutwardMaster> listUser = new List<YarnOutwardMaster>();
            YarnOutwardMasterResponce response = new YarnOutwardMasterResponce();

            var request = HttpContext.Current.Request;
            YarnOutwardMaster ilist = new YarnOutwardMaster();


            ilist.GodownID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownID"]);
            ilist.BillToPartyID = Convert.ToInt32(HttpContext.Current.Request.Params["BillToPartyID"]);
            ilist.YarnMaterialID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnMaterialID"]);
            ilist.YarnColorID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnColorID"]);
            ilist.YarnInwardDetailIDss = HttpContext.Current.Request.Params["YarnInwardDetailIDss"];
            ilist.SiftGodownLocationId = HttpContext.Current.Request.Params["SiftGodownLocationId"];


            ilist.updatesiftGodownInputBox = HttpContext.Current.Request.Params["updatesiftGodownInputBox"];
            //ilist.strBillToPartyID = HttpContext.Current.Request.Params["strBillToPartyID"];
            //ilist.strYarnMaterialID = HttpContext.Current.Request.Params["strYarnMaterialID"];
            //ilist.strYarnColorID = HttpContext.Current.Request.Params["strYarnColorID"];

            string CompanyName = "";
            if (ilist.BillToPartyID != 0)
            {
                CompanyName = " and t1.BillToPartyID = " + ilist.BillToPartyID + " ";
            }

            string YarnMaterial = "";
            if (ilist.YarnMaterialID != 0)
            {
                YarnMaterial = " and t1.YarnMaterialID = " + ilist.YarnMaterialID + " ";
            }

            string YarnColor = "";
            if (ilist.YarnColorID != 0)
            {
                YarnColor = " and t1.YarnColorID = " + ilist.YarnColorID + " ";
            }


            string YarnInwardDetails = "";
            //if (ilist.YarnInwardDetailIDss != "")
            //{
            //    YarnInwardDetails = " and YarnInwardDetailID not in (" + ilist.YarnInwardDetailIDss + ") ";
            //}

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandTimeout = 180;
                cmd.CommandType = System.Data.CommandType.Text;

                if (ilist.SiftGodownLocationId != "")
                {
                    cmd.CommandText = @"	select  
                                        (t2.Stock - ISNULL(YOD.Stock, 0)) AS Stock, 
                                        t2.BillToPartyID, t2.CompanyName, t2.YarnMaterialID,
                                        t2.YarnMaterial, t2.YarnColorID, t2.YarnColor,
                                        t2.YarnColorCode from(
                                        select CASE 
		                                        WHEN (t1.Stock + ISNULL(t2.Stock,0)) < 0 THEN 0
		                                        ELSE (t1.Stock + ISNULL(t2.Stock,0))
	                                        END AS Stock, t1.BillToPartyID, t1.CompanyName, t1.YarnMaterialID, t1.YarnMaterial, 
	                                        t1.YarnColorID, t1.YarnColor,
	                                        t1.YarnColorCode from (
	                                        select ISNULL(SUM(Stock),0) as Stock, t1.BillToPartyID, t1.CompanyName,
	                                        t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode from
	                                        (
		                                        select  YIM.YarnInwardID, YIM.YarnPOID, YPM.BillToPartyID, YPM.PartyName as 'CompanyName',
		                                        YIM.YarnMaterialID, YMM.YarnMaterial, YIM.YarnColorID, YCM.YarnColor, YCM.YarnColorCode , YIDD.Stock
		                                        from YarnInwardMaster YIM
		                                        LEFT JOIN 
		                                        (
			                                        select YPM.YarnPOID, YPM.BillToPartyID, PM.PartyName from YarnPOMaster YPM
			                                        LEFT JOIN PartyMaster PM ON YPM.BillToPartyID = PM.PartyId
		                                        )YPM ON YIM.YarnPOID = YPM.YarnPOID
		                                        LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID
		                                        LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID = YCM.YarnColorID
		                                        LEFT JOIN (select COUNT(*) as Stock, YarnInwardID from YarnInwardDetail 
					                                        where GodownLocationID in (select GodownLocationID from GodownLocationMaster where GodownID = '" + ilist.GodownID + @"')
					                                        group by YarnInwardID
					                                        ) YIDD ON YIM.YarnInwardID = YIDD.YarnInwardID
	                                        ) as t1
	                                        where (1=1)    " + CompanyName + @" " + YarnMaterial + @" " + YarnColor + @"
	                                        group by t1.BillToPartyID, t1.CompanyName,
	                                        t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode  
                                        ) as t1 
                                        LEFT JOIN 
                                        (
	                                        select SUM(t1.InputNoOfBox) as Stock,
	                                        t1.BillToPartyID, t1.YarnMaterialID, t1.YarnColorID
	                                        from(
		                                        SELECT
			                                        GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID,  ISNULL(SUM(InputNoOfBox),0) as InputNoOfBox
		                                        FROM (
			                                        SELECT * FROM (VALUES
				                                       " + ilist.SiftGodownLocationId + @"
			                                        ) AS V ( GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID, InputNoOfBox)
		                                        ) X 
		                                        GROUP BY GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID
	                                        ) as t1
	                                        group by t1.BillToPartyID, t1.YarnMaterialID, t1.YarnColorID
                                        ) as t2
                                        ON  t1.BillToPartyID = t2.BillToPartyID
                                        AND t1.YarnMaterialID = t2.YarnMaterialID
                                        AND t1.YarnColorID = t2.YarnColorID
                                        ) as t2
                                        LEFT JOIN 
                                        (
                                        select SUM(YOD.NoOfBox) as Stock, YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID from YarnOutwardDetail YOD
                                        LEFT JOIN YarnOutwardMaster YOM ON YOD.YarnOutwardID = YOM.YarnOutwardID
                                        where YOM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)
                                        group by YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID 
                                        ) YOD ON  t2.BillToPartyID = YOD.BillToPartyID
                                        AND t2.YarnMaterialID = YOD.YarnMaterialID
                                        AND t2.YarnColorID = YOD.YarnColorID
                                        WHERE t2.Stock > 0";
                }
                else
                {
                    cmd.CommandText = @"select (t2.Stock - ISNULL(YOD.Stock, 0)) AS Stock, 
	                            t2.BillToPartyID, t2.CompanyName, t2.YarnMaterialID,
                                t2.YarnMaterial, t2.YarnColorID, t2.YarnColor,
                                t2.YarnColorCode 
	                            from(
                                select ISNULL(SUM(Stock),0) as Stock, t1.BillToPartyID, t1.CompanyName,
                                t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode from
                                (
	                                select  YIM.YarnInwardID, YIM.YarnPOID, YPM.BillToPartyID, YPM.PartyName as 'CompanyName',
	                                YIM.YarnMaterialID, YMM.YarnMaterial, YIM.YarnColorID, YCM.YarnColor, YCM.YarnColorCode , YIDD.Stock
	                                from YarnInwardMaster YIM
	                                LEFT JOIN 
	                                (
		                                select YPM.YarnPOID, YPM.BillToPartyID, PM.PartyName from YarnPOMaster YPM
		                                LEFT JOIN PartyMaster PM ON YPM.BillToPartyID = PM.PartyId
	                                )YPM ON YIM.YarnPOID = YPM.YarnPOID
	                                LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID
	                                LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID = YCM.YarnColorID
	                                LEFT JOIN (select COUNT(*) as Stock, YarnInwardID from YarnInwardDetail 
                                                where GodownLocationID in (select GodownLocationID from GodownLocationMaster where GodownID = '" + ilist.GodownID + @"')
                                                " + YarnInwardDetails + @" 
                                                 group by YarnInwardID
                                              ) YIDD ON YIM.YarnInwardID = YIDD.YarnInwardID
                                ) as t1
                                where (1=1) " + CompanyName + @" " + YarnMaterial + @" " + YarnColor + @"
                                group by t1.BillToPartyID, t1.CompanyName,
                                t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode  
                            ) as t2 
                            LEFT JOIN 
                            (

	                            SELECT SUM(YOD.NoOfBox) AS Stock, YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID
	                            FROM YarnOutwardDetail YOD
	                            LEFT JOIN YarnOutwardMaster YOM  ON YOD.YarnOutwardID = YOM.YarnOutwardID
	                            WHERE YOM.CompanyId = (SELECT CompanyId FROM CompanyMaster WHERE is_default = 1)
	                            AND NOT EXISTS
	                            (
		                            SELECT 1 FROM (
						                            VALUES " + ilist.updatesiftGodownInputBox + @"
					                                ) AS V (GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID, InputNoOfBox)
		                            WHERE 
			                            V.GodownLocationID = YOD.GodownLocationID
			                            AND V.BillToPartyID = YOD.BillToPartyID
			                            AND V.YarnMaterialID = YOD.YarnMaterialID
			                            AND V.YarnColorID = YOD.YarnColorID
			                            AND V.InputNoOfBox = YOD.NoOfBox
	                            )
	                            GROUP BY  YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID
                                    
                            ) YOD ON  t2.BillToPartyID = YOD.BillToPartyID
                            AND t2.YarnMaterialID = YOD.YarnMaterialID
                            AND t2.YarnColorID = YOD.YarnColorID
                            where (t2.Stock - ISNULL(YOD.Stock, 0)) > 0;
                            ";
                }

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnOutwardMaster condition = new YarnOutwardMaster();
                        condition.BillToPartyID = Convert.ToInt32(rdr["BillToPartyID"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr["YarnColorCode"].ToString().ToUpper();
                        condition.CompanyName = rdr["CompanyName"].ToString().ToUpper();
                        condition.Stock = Convert.ToInt32(rdr["Stock"].ToString());
                        listUser.Add(condition);
                    }
                }
                rdr.Close();
                cmd.Dispose();
                con.Close();
            }
            response.Code = 200;
            response.Message = "Success";
            response.listYarnOutwardMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
