            ilist.siftGodownInputBox = HttpContext.Current.Request.Params["siftGodownInputBox"];


            string abc = HttpContext.Current.Request.Params["YarnOutwardID"];
            string lastCharacter = abc.Substring(abc.Length - 6);

            if (lastCharacter != "%3d%3d")
            {
                string InvoiceId = HttpContext.Current.Request.Params["YarnOutwardID"].Replace("==", "") + "%3d%3d";
                ilist.YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                ilist.YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(HttpContext.Current.Request.Params["YarnOutwardID"])));
            }

            string CompanyName = "";
            if (ilist.BillToPartyID != 0)
            {
                CompanyName = " and YPM.BillToPartyID = " + ilist.BillToPartyID + " ";
            }

            string YarnMaterial = "";
            if (ilist.YarnMaterialID != 0)
            {
                YarnMaterial = " and YarnMaterialID = " + ilist.YarnMaterialID + " ";
            }

            string YarnColor = "";
            if (ilist.YarnColorID != 0)
            {
                YarnColor = " and YarnColorID = " + ilist.YarnColorID + " ";
            }
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = @"SELECT   (t2.NoOfBox - ISNULL(YOD.UsedStock,0)) AS NoOfBox,t2.GodownLocationID,t2.GodownTitle,t2.LocationTitle,t2.BillToPartyID,t2.YarnMaterialID, t2.YarnColorID, GM.GodownTitle AS GodownName,
        GLM.LocationTitle AS GodownLocationName,PM.PartyName AS CompanyName,YMM.YarnMaterial,YCM.YarnColor,YCM.YarnColorCode
          FROM ( SELECT  t3.GodownLocationID,COUNT(t3.GodownLocationID) AS NoOfBox,GM.GodownTitle,GLM.LocationTitle,
                '" + ilist.BillToPartyID + @"' AS BillToPartyID, '" + ilist.YarnMaterialID + @"' AS YarnMaterialID,'" + ilist.YarnColorID + @"' AS YarnColorID
              FROM (SELECT T2.* FROM (SELECT YID.* FROM
                (SELECT ROW_NUMBER() OVER ( PARTITION BY YarnInwardDetailID ORDER BY YarnInterchangeID DESC ) AS rn,* FROM YarnInterchangeMaster ) AS t1
                LEFT JOIN YarnInwardDetail YID ON t1.YarnInwardDetailID = YID.YarnInwardDetailID
                WHERE t1.rn = 1 AND t1.YarnInwardDetailID IN 
                (  SELECT YarnInwardDetailID FROM YarnInwardDetail WHERE YarnInwardID IN (  SELECT YIM.YarnInwardID   FROM YarnInwardMaster YIM
                    LEFT JOIN YarnPOMaster YPM ON YIM.YarnPOID = YPM.YarnPOID
                    WHERE YPM.BillToPartyID = '" + ilist.BillToPartyID + @"' AND YarnMaterialID =  '" + ilist.YarnMaterialID + @"'  AND YarnColorID = '" + ilist.YarnColorID + @"' )
                )
                UNION ALL  SELECT *  FROM YarnInwardDetail
                    WHERE YarnInwardID IN (SELECT YIM.YarnInwardID FROM YarnInwardMaster YIM
                            LEFT JOIN YarnPOMaster YPM ON YIM.YarnPOID = YPM.YarnPOID
                        WHERE YPM.BillToPartyID = '" + ilist.BillToPartyID + @"'
                          AND YarnMaterialID = '" + ilist.YarnMaterialID + @"'
                          AND YarnColorID = '" + ilist.YarnColorID + @"'
                    )
                  AND YarnInwardDetailID NOT IN ( SELECT DISTINCT YarnInwardDetailID FROM YarnInterchangeMaster ) ) AS T2 ) AS t3
                                LEFT JOIN GodownLocationMaster GLM 
                                    ON t3.GodownLocationID = GLM.GodownLocationID
                                LEFT JOIN GodownMaster GM 
                                    ON GLM.GodownID = GM.GodownID
                                WHERE t3.GodownLocationID IN (
                                    SELECT GodownLocationID 
                                    FROM GodownLocationMaster 
                                    WHERE GodownID = '" + ilist.GodownID + @"'
                                )
                                GROUP BY 
                                    t3.GodownLocationID, 
                                    GM.GodownTitle, 
                                    GLM.LocationTitle
                            ) AS t2
                            LEFT JOIN GodownLocationMaster GLM 
                                ON t2.GodownLocationID = GLM.GodownLocationID
                            LEFT JOIN GodownMaster GM 
                                ON GLM.GodownID = GM.GodownID
                            LEFT JOIN PartyMaster PM 
                                ON t2.BillToPartyID = PM.PartyId
                            LEFT JOIN YarnMaterialMaster YMM 
                                ON t2.YarnMaterialID = YMM.YarnMaterialID
                            LEFT JOIN YarnColorMaster YCM 
                                ON t2.YarnColorID = YCM.YarnColorID
                           LEFT JOIN
								(
									SELECT 
										YOD.GodownLocationID,
										YOD.BillToPartyID,
										YOD.YarnMaterialID,
										YOD.YarnColorID,
										SUM(YOD.NoOfBox) AS UsedStock
									FROM YarnOutwardDetail YOD
									INNER JOIN YarnOutwardMaster YOM 
										ON YOD.YarnOutwardID = YOM.YarnOutwardID
									WHERE YOM.CompanyId =
										  (SELECT CompanyId FROM CompanyMaster WHERE is_default = 1)
									  AND YOD.YarnOutwardID <> '" + ilist.YarnOutwardID + @"'                            
									GROUP BY
										YOD.GodownLocationID,
										YOD.BillToPartyID,
										YOD.YarnMaterialID,
										YOD.YarnColorID
								) YOD
								ON  t2.BillToPartyID = YOD.BillToPartyID
								AND t2.YarnMaterialID = YOD.YarnMaterialID
								AND t2.YarnColorID = YOD.YarnColorID
								AND t2.GodownLocationID = YOD.GodownLocationID
                                   where (t2.NoOfBox - ISNULL(YOD.UsedStock,0)) > 0";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnOutwardMaster condition = new YarnOutwardMaster();
                        condition.BillToPartyID = Convert.ToInt32(rdr["BillToPartyID"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.NoOfBox = Convert.ToInt32(rdr["NoOfBox"].ToString());
                        condition.GodownLocationID = Convert.ToInt32(rdr["GodownLocationID"].ToString());
                        condition.GodownTitle = rdr["GodownTitle"].ToString().ToUpper();
                        condition.LocationTitle = rdr["LocationTitle"].ToString().ToUpper();
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr["YarnColorCode"].ToString().ToUpper();
                        condition.CompanyName = rdr["CompanyName"].ToString().ToUpper();
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }



            response.Code = 200;
            response.Message = "Success";
            response.listYarnOutwardMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }

        // View Yarn Out Ward
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getSiftYarnOutwardMaster()
        {
            JavaScriptSerializer js;
            List<YarnOutwardMaster> listUser = new List<YarnOutwardMaster>();
            YarnOutwardMasterResponce response = new YarnOutwardMasterResponce();

            var request = HttpContext.Current.Request;
            YarnOutwardMaster ilist = new YarnOutwardMaster();


            ilist.GodownInputBoxss = HttpContext.Current.Request.Params["GodownInputBoxss"];


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = @"select t1.*, GM.GodownTitle, GLM.LocationTitle, PM.PartyName as 'CompanyName', 
                                    YMM.YarnMaterial, YCM.YarnColor, YCM.YarnColorCode
                                    from(
	                                    SELECT
		                                    GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID,  ISNULL(SUM(InputNoOfBox),0) as InputNoOfBox
	                                    FROM (
		                                    SELECT * FROM (VALUES
			                                    " + ilist.GodownInputBoxss + @"
		                                    ) AS V ( GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID, InputNoOfBox)
	                                    ) X 
                                        GROUP BY GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID
                                    ) as t1
                                    LEFT JOIN GodownLocationMaster GLM ON t1.GodownLocationID = GLM.GodownLocationID
                                    LEFT JOIN GodownMaster GM ON GLM.GodownID = GM.GodownID
                                    LEFT JOIN PartyMaster PM ON t1.BillToPartyID = PM.PartyId
                                    LEFT JOIN YarnMaterialMaster YMM ON t1.YarnMaterialID = YMM.YarnMaterialID
                                    LEFT JOIN YarnColorMaster YCM ON t1.YarnColorID = YCM.YarnColorID
                                    ORDER BY t1.BillToPartyID, t1.YarnMaterialID, t1.YarnColorID, t1.GodownLocationID;
                                    ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnOutwardMaster condition = new YarnOutwardMaster();
                        condition.GodownLocationID = Convert.ToInt32(rdr["GodownLocationID"].ToString());
                        condition.BillToPartyID = Convert.ToInt32(rdr["BillToPartyID"].ToString());
                        //condition.YarnInwardID = Convert.ToInt32(rdr["YarnInwardID"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.NoOfBox = Convert.ToInt32(rdr["InputNoOfBox"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr["YarnColorCode"].ToString().ToUpper();
                        condition.CompanyName = rdr["CompanyName"].ToString().ToUpper();
                        condition.LocationTitle = rdr["LocationTitle"].ToString().ToUpper();
                        //condition.NetWeight = Convert.ToDecimal(rdr["NetWeight"].ToString());
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }



            response.Code = 200;
            response.Message = "Success";
            response.listYarnOutwardMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateSiftYarnOutwardMaster()
        {
            JavaScriptSerializer js;
            List<YarnOutwardMaster> listUser = new List<YarnOutwardMaster>();
            YarnOutwardMasterResponce response = new YarnOutwardMasterResponce();

            var request = HttpContext.Current.Request;
            YarnOutwardMaster ilist = new YarnOutwardMaster();


            ilist.GodownInputBoxss = HttpContext.Current.Request.Params["GodownInputBoxss"];
            ilist.GodownID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownID"]);

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = @"SELECT 
                                    (t1.Stock - ISNULL(YOD.Stock, 0) + ISNULL(V.InputNoOfBox,0)) AS Stock, 
                                    t1.BillToPartyID,  
                                    t1.CompanyName,  
                                    t1.YarnMaterialID, 
                                    t1.YarnMaterial,  
                                    t1.YarnColorID,  
                                    t1.YarnColor, 
                                    t1.YarnColorCode
                                FROM 
                                (
                                    SELECT 
                                        ISNULL(SUM(t1.Stock),0) as Stock,  
                                        t1.BillToPartyID,  
                                        t1.CompanyName, 
                                        t1.YarnMaterialID, 
                                        t1.YarnMaterial,  
                                        t1.YarnColorID,  
                                        t1.YarnColor,  
                                        t1.YarnColorCode 
                                    FROM
                                    (
                                        SELECT  
                                            YIM.YarnInwardID,  
                                            YIM.YarnPOID,  
                                            YPM.BillToPartyID,  
                                            YPM.PartyName AS CompanyName,
                                            YIM.YarnMaterialID,  
                                            YMM.YarnMaterial,  
                                            YIM.YarnColorID,  
                                            YCM.YarnColor,  
                                            YCM.YarnColorCode, 
                                            YIDD.Stock
                                        FROM YarnInwardMaster YIM

                                        LEFT JOIN 
                                        (
                                            SELECT 
                                                YPM.YarnPOID, 
                                                YPM.BillToPartyID, 
                                                PM.PartyName 
                                            FROM YarnPOMaster YPM
                                            LEFT JOIN PartyMaster PM 
                                                ON YPM.BillToPartyID = PM.PartyId
                                        ) YPM 
                                            ON YIM.YarnPOID = YPM.YarnPOID

                                        LEFT JOIN YarnMaterialMaster YMM 
                                            ON YIM.YarnMaterialID = YMM.YarnMaterialID

                                        LEFT JOIN YarnColorMaster YCM 
                                            ON YIM.YarnColorID = YCM.YarnColorID

                                        LEFT JOIN 
                                        (
                                            SELECT 
                                                COUNT(*) AS Stock, 
                                                YarnInwardID 
                                            FROM YarnInwardDetail 
                                            WHERE GodownLocationID IN 
                                            (
                                                SELECT GodownLocationID 
                                                FROM GodownLocationMaster 
                                                WHERE GodownID = '" + ilist.GodownID + @"'
                                            )
                                            GROUP BY YarnInwardID
                                        ) YIDD 
                                            ON YIM.YarnInwardID = YIDD.YarnInwardID

                                    ) AS t1

                                    WHERE (1=1)

                                    GROUP BY  
                                        t1.BillToPartyID,  
                                        t1.CompanyName, 
                                        t1.YarnMaterialID,  
                                        t1.YarnMaterial, 
                                        t1.YarnColorID,  
                                        t1.YarnColor,  
                                        t1.YarnColorCode  

                                ) AS t1


                                LEFT JOIN 
                                (
                                    SELECT 
                                        SUM(YOD.NoOfBox) as Stock, 
                                        YOD.BillToPartyID, 
                                        YOD.YarnMaterialID, 
                                        YOD.YarnColorID 
                                    FROM YarnOutwardDetail YOD
                                    LEFT JOIN YarnOutwardMaster YOM 
                                        ON YOD.YarnOutwardID = YOM.YarnOutwardID
                                    WHERE YOM.CompanyId = 
                                        (SELECT CompanyId FROM CompanyMaster WHERE is_default = 1)
                                    GROUP BY 
                                        YOD.BillToPartyID, 
                                        YOD.YarnMaterialID, 
                                        YOD.YarnColorID 
                                ) YOD 
                                    ON  t1.BillToPartyID = YOD.BillToPartyID
                                    AND t1.YarnMaterialID = YOD.YarnMaterialID
                                    AND t1.YarnColorID = YOD.YarnColorID


                                LEFT JOIN 
                                (
                                    SELECT * FROM (VALUES
                                          " + ilist.GodownInputBoxss + @"
                                    ) AS V (GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID, InputNoOfBox)
                                ) V
                                    ON  t1.BillToPartyID = V.BillToPartyID
                                    AND t1.YarnMaterialID = V.YarnMaterialID
                                    AND t1.YarnColorID = V.YarnColorID


                                WHERE (t1.Stock - ISNULL(YOD.Stock, 0) + ISNULL(V.InputNoOfBox,0)) > 0;
                                    ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnOutwardMaster condition = new YarnOutwardMaster();
                        condition.BillToPartyID = Convert.ToInt32(rdr["BillToPartyID"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr["YarnColorCode"].ToString().ToUpper();
                        condition.CompanyName = rdr["CompanyName"].ToString().ToUpper();
                        condition.Stock = Convert.ToInt32(rdr["Stock"].ToString());
                        listUser.Add(condition);
                    }
                }
                rdr.Close();
                cmd.Dispose();
                con.Close();
            }
            response.Code = 200;
            response.Message = "Success";
            response.listYarnOutwardMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }

        // View Yarn Out Ward
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getSundryPartyMaster()
        {
            JavaScriptSerializer js;
            List<PartyMaster> listUser = new List<PartyMaster>();
            PartyMasterResponse response = new PartyMasterResponse();

            var request = HttpContext.Current.Request;
            PartyMaster ilist = new PartyMaster();


            ilist.SundryParty = HttpContext.Current.Request.Params["SundryParty"];


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                con.Open();

                if (ilist.SundryParty == "3")
                {
                    cmd.CommandText = @"SELECT Id AS PartyId, PartyName 
                                        FROM JobberMaster 
                                        WHERE ISNULL(IsActiveParty, 1) = 1 
                                        ORDER BY PartyName ASC";
                }
                else if (ilist.SundryParty == "1" || ilist.SundryParty == "2")
                {
                    cmd.CommandText = @"SELECT PartyId, PartyName 
                                        FROM PartyMaster 
                                        WHERE SundryParty = @SundryParty 
                                        AND IsActiveParty = 1 
                                        AND CompanyId = (SELECT TOP 1 CompanyId FROM CompanyMaster WHERE is_default = 1) 
                                        ORDER BY PartyName ASC";
                    cmd.Parameters.AddWithValue("@SundryParty", ilist.SundryParty);
                }
                else
                {
                    cmd.CommandText = @"SELECT PartyId, PartyName 
                                        FROM PartyMaster 
                                        WHERE IsActiveParty = 1 
                                        AND CompanyId = (SELECT TOP 1 CompanyId FROM CompanyMaster WHERE is_default = 1) 
                                        ORDER BY PartyName ASC";
                }

                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        PartyMaster condition = new PartyMaster();
                        condition.PartyId = Convert.ToInt32(rdr["PartyId"].ToString());
                        condition.PartyName = rdr["PartyName"].ToString().ToUpper();
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }



            response.Code = 200;
            response.Message = "Success";
            response.listPartyMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertYarnOutwardMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            var request = HttpContext.Current.Request;

            CommanResponse comman = new CommanResponse();
            YarnOutwardMaster ilist = new YarnOutwardMaster();

            //ilist.GodownID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownID"]);
            ilist.PartyId = Convert.ToInt32(HttpContext.Current.Request.Params["PartyId"]);
            ilist.OutwardListNo = HttpContext.Current.Request.Params["OutwardListNo"];
            ilist.GodownManagerUserAccountId = Convert.ToInt32(HttpContext.Current.Request.Params["GodownManagerUserAccountId"]);
            ilist.OutwardListDates = HttpContext.Current.Request.Params["OutwardListDate"];
            //ilist.siftYarnInwardDetailID = HttpContext.Current.Request.Params["siftYarnInwardDetailID"];
            ilist.siftGodownInputBox = HttpContext.Current.Request.Params["siftGodownInputBox"];
            ilist.UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
            ilist.CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);
            ilist.GodownID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownID"]);

            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction trans = con.BeginTransaction())
                    {
                        try
                        {
                            // ✅ MASTER INSERT
                            SqlCommand cmd = new SqlCommand(@"
                    INSERT INTO YarnOutwardMaster
                    (DateAndTime, PartyId, OutwardListNo, OutwardListDate,
                     GodownManagerUserAccountId, UserAccountId,
                     FinancialYearID, CompanyId, GodownID)
                    OUTPUT INSERTED.YarnOutwardID
                    VALUES
                    (@DateAndTime, @PartyId, @OutwardListNo, @OutwardListDate,
                     @GodownManagerUserAccountId, @UserAccountId,
                     (SELECT FinancialYearID FROM FinancialYearMaster WHERE IsDefault = 1),
                     (SELECT CompanyId FROM CompanyMaster WHERE is_default = 1),
                     @GodownID)", con, trans);

                            cmd.Parameters.AddWithValue("@DateAndTime", dateTime_Indian);
                            cmd.Parameters.AddWithValue("@PartyId", ilist.PartyId);
                            cmd.Parameters.AddWithValue("@OutwardListNo", ilist.OutwardListNo);
                            cmd.Parameters.AddWithValue("@OutwardListDate",
                                DateTime.ParseExact(ilist.OutwardListDates, "dd/MM/yyyy", CultureInfo.InvariantCulture));
                            cmd.Parameters.AddWithValue("@GodownManagerUserAccountId", ilist.GodownManagerUserAccountId);
                            cmd.Parameters.AddWithValue("@UserAccountId", ilist.UserAccountId);
                            cmd.Parameters.AddWithValue("@GodownID", ilist.GodownID);

                            long YarnOutwardID = Convert.ToInt64(cmd.ExecuteScalar());

                            if (YarnOutwardID <= 0)
                            {
                                trans.Rollback();
                                comman.Code = 410;
                                comman.Message = "This Yarn Outward already exists.";
                                return;
                            }

                            // ✅ DETAIL INSERT
                            string[] siftGodownInputBox = ilist.siftGodownInputBox.Split('|');

                            foreach (var item in siftGodownInputBox)
                            {
                                if (string.IsNullOrWhiteSpace(item)) continue;

                                string clean = item.Replace("(", "").Replace(")", "");
                                var parts = clean.Split(',');

                                if (parts.Length < 5)
                                    continue;

                                // ✅ Safe parsing (no crash)
                                int GodownLocationID = int.TryParse(parts[0], out var g) ? g : 0;
                                int BillToPartyID = int.TryParse(parts[1], out var b) ? b : 0;
                                int YarnMaterialID = int.TryParse(parts[2], out var m) ? m : 0;
                                int YarnColorID = int.TryParse(parts[3], out var c) ? c : 0;
                                int InpuNoOfBox = int.TryParse(parts[4], out var q) ? q : 0;

                                // ✅ Optional field (6th value)
                                int YarnRequirementDetailID = (parts.Length > 5 && int.TryParse(parts[5], out var y)) ? y : 0;

                                // 🔥

                                SqlCommand cmd2 = new SqlCommand(@"
                        INSERT INTO YarnOutwardDetail
                        (DateAndTime, YarnOutwardID, BillToPartyID, YarnMaterialID,
                         YarnColorID, GodownLocationID, NoOfBox, UserAccountId,
                         YarnRequirementDetailID, YarnRequirementDateTime)
                        VALUES
                        (@DateAndTime, @YarnOutwardID, @BillToPartyID, @YarnMaterialID,
                         @YarnColorID, @GodownLocationID, @NoOfBox, @UserAccountId,
                         @YarnRequirementDetailID, GETDATE())", con, trans);

                                cmd2.Parameters.AddWithValue("@DateAndTime", dateTime_Indian);
                                cmd2.Parameters.AddWithValue("@YarnOutwardID", YarnOutwardID);
                                cmd2.Parameters.AddWithValue("@BillToPartyID", BillToPartyID);
                                cmd2.Parameters.AddWithValue("@YarnMaterialID", YarnMaterialID);
                                cmd2.Parameters.AddWithValue("@YarnColorID", YarnColorID);
                                cmd2.Parameters.AddWithValue("@GodownLocationID", GodownLocationID);
                                cmd2.Parameters.AddWithValue("@NoOfBox", InpuNoOfBox);
                                cmd2.Parameters.AddWithValue("@UserAccountId", ilist.UserAccountId);
                                cmd2.Parameters.AddWithValue("@YarnRequirementDetailID", YarnRequirementDetailID);

                                cmd2.ExecuteNonQuery();
                            }

                            // ✅ COMMIT
                            trans.Commit();

                            comman.Code = 201;
                            comman.Message = "Yarn Outward has been saved successfully.";
                        }
                        catch (Exception ex)
                        {
                            trans.Rollback();
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";

                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateYarnOutwardMaster()
        {
            DateTime indianTime = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            CommanResponse comman = new CommanResponse();
            YarnOutwardMaster ilist = new YarnOutwardMaster();

            try
            {
                var request = HttpContext.Current.Request;

                if (Context.Request.Cookies["UserIDs"] == null || string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
                {
                    AuditLogHelper.LogValidationError("Yarn Outward", "YarnOutwardMaster", null, "User session expired. Please log in again.", "UserIDs cookie missing");
                    comman.Code = 401;
                    comman.Message = "User session expired. Please log in again.";
                    WriteResponse(comman);
                    return;
                }

                // ===== Decrypt ID =====
                string encryptedId = request.Params["YarnOutwardID"];
                if (string.IsNullOrEmpty(encryptedId))
                {
                    AuditLogHelper.LogValidationError("Yarn Outward", "YarnOutwardMaster", null, "YarnOutwardID is required.", "encryptedId is null/empty");
                    comman.Code = 400;
                    comman.Message = "Invalid ID specified.";
                    WriteResponse(comman);
                    return;
                }

                string lastCharacter = encryptedId.Substring(encryptedId.Length - 6);

                if (lastCharacter != "%3d%3d")
                {
                    encryptedId = encryptedId.Replace("==", "") + "%3d%3d";
                }

                ilist.YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(encryptedId)));

                // ===== Assign Parameters =====
                ilist.PartyId = Convert.ToInt32(request.Params["PartyId"]);
                ilist.OutwardListNo = request.Params["OutwardListNo"];
                ilist.GodownManagerUserAccountId = Convert.ToInt32(request.Params["GodownManagerUserAccountId"]);
                ilist.OutwardListDates = request.Params["OutwardListDate"];
                ilist.siftGodownInputBox = request.Params["siftGodownInputBox"];
                ilist.UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
                ilist.CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["CompanyID"].Value) ? Context.Request.Cookies["CompanyID"].Value.Split('=')[1] : "0");
                ilist.GodownID = Convert.ToInt32(request.Params["GodownID"]);
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();
                    SqlTransaction tran = con.BeginTransaction();
                    try
                    {
                        // Capture Old Value Snapshot
                        object oldYarnOutward = null;
                        try
                        {
                            using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM YarnOutwardMaster WHERE YarnOutwardID = @ID", con, tran))
                            {
                                cmdOld.Parameters.AddWithValue("@ID", ilist.YarnOutwardID);
                                using (SqlDataReader rdrOld = cmdOld.ExecuteReader())
                                {
                                    if (rdrOld.Read())
                                    {
                                        oldYarnOutward = new
                                        {
                                            YarnOutwardID = rdrOld["YarnOutwardID"],
                                            PartyId = rdrOld["PartyId"],
                                            OutwardListNo = rdrOld["OutwardListNo"],
                                            OutwardListDate = rdrOld["OutwardListDate"],
                                            GodownManagerUserAccountId = rdrOld["GodownManagerUserAccountId"],
                                            GodownID = rdrOld["GodownID"]
                                        };
                                    }
                                }
                            }
                        }
                        catch { }

                        #region UPDATE MASTER
                        SqlCommand cmd = new SqlCommand(@"
                    UPDATE YarnOutwardMaster
                    SET DateAndTime = @DateAndTime,
                        PartyId = @PartyId,
                        OutwardListNo = @OutwardListNo,
                        OutwardListDate = @OutwardListDate,
                        GodownManagerUserAccountId = @ManagerId,
                        UserAccountId = @UserId,
                        CompanyId = @CompanyId,
                        GodownID=@GodownID

                    WHERE YarnOutwardID = @YarnOutwardID", con, tran);

                        cmd.Parameters.AddWithValue("@DateAndTime", indianTime);
                        cmd.Parameters.AddWithValue("@PartyId", ilist.PartyId);
                        cmd.Parameters.AddWithValue("@OutwardListNo", ilist.OutwardListNo);
                        DateTime parsedOutwardDate;
                        if (!DateTime.TryParseExact(ilist.OutwardListDates, new[] { "dd/MM/yyyy", "dd-MM-yyyy", "yyyy-MM-dd", "MM/dd/yyyy", "d/M/yyyy", "d-M-yyyy" }, CultureInfo.InvariantCulture, DateTimeStyles.None, out parsedOutwardDate))
                        {
                            if (!DateTime.TryParse(ilist.OutwardListDates, out parsedOutwardDate))
                            {
                                parsedOutwardDate = DateTime.Now;
                            }
                        }
                        cmd.Parameters.AddWithValue("@OutwardListDate", parsedOutwardDate);
                        cmd.Parameters.AddWithValue("@ManagerId", ilist.GodownManagerUserAccountId);
                        cmd.Parameters.AddWithValue("@UserId", ilist.UserAccountId);
                        cmd.Parameters.AddWithValue("@CompanyId", ilist.CompanyId);
                        cmd.Parameters.AddWithValue("@YarnOutwardID", ilist.YarnOutwardID);
                        cmd.Parameters.AddWithValue("@GodownID", ilist.GodownID);

                        int masterUpdated = cmd.ExecuteNonQuery();

                        if (masterUpdated <= 0)
                        {
                            tran.Rollback();
                            AuditLogHelper.LogValidationError("Yarn Outward", "YarnOutwardMaster", ilist.YarnOutwardID.ToString(), "Yarn Outward not found.", "masterUpdated <= 0", ilist);
                            comman.Code = 404;
                            comman.Message = "Yarn Outward not found.";
                            WriteResponse(comman);
                            return;
                        }

                        #endregion


                        #region DELETE OLD DETAILS

                        SqlCommand deleteOld = new SqlCommand(@"
                    DELETE FROM YarnOutwardDetail 
                    WHERE YarnOutwardID = @YarnOutwardID", con, tran);

                        deleteOld.Parameters.AddWithValue("@YarnOutwardID", ilist.YarnOutwardID);
                        deleteOld.ExecuteNonQuery();

                        #endregion


                        #region INSERT NEW DETAILS

                        if (!string.IsNullOrEmpty(ilist.siftGodownInputBox))
                        {
                            string[] details = ilist.siftGodownInputBox.Split('|');

                            foreach (string item in details)
                            {
                                string clean = item.Replace("(", "").Replace(")", "");
                                var parts = clean.Split(',');

                                if (parts.Length < 5)
                                    continue;

                                // ✅ Safe parsing (no crash)
                                int GodownLocationID = int.TryParse(parts[0], out var g) ? g : 0;
                                int BillToPartyID = int.TryParse(parts[1], out var b) ? b : 0;
                                int YarnMaterialID = int.TryParse(parts[2], out var m) ? m : 0;
                                int YarnColorID = int.TryParse(parts[3], out var c) ? c : 0;
                                int InpuNoOfBox = int.TryParse(parts[4], out var q) ? q : 0;

                                // ✅ Optional field (6th value)
                                int YarnRequirementDetailID = (parts.Length > 5 && int.TryParse(parts[5], out var y)) ? y : 0;

                                // 🔥

                                SqlCommand cmd2 = new SqlCommand(@"
                                    INSERT INTO YarnOutwardDetail
                                    (DateAndTime, YarnOutwardID, BillToPartyID, YarnMaterialID,
                                     YarnColorID, GodownLocationID, NoOfBox, UserAccountId,
                                     YarnRequirementDetailID, YarnRequirementDateTime)
                                    VALUES
                                    (@DateAndTime, @YarnOutwardID, @BillToPartyID, @YarnMaterialID,
                                     @YarnColorID, @GodownLocationID, @NoOfBox, @UserAccountId,
                                     @YarnRequirementDetailID, GETDATE())", con, tran);

                                cmd2.Parameters.AddWithValue("@DateAndTime", indianTime);
                                cmd2.Parameters.AddWithValue("@YarnOutwardID", ilist.YarnOutwardID);
                                cmd2.Parameters.AddWithValue("@BillToPartyID", BillToPartyID);
                                cmd2.Parameters.AddWithValue("@YarnMaterialID", YarnMaterialID);
                                cmd2.Parameters.AddWithValue("@YarnColorID", YarnColorID);
                                cmd2.Parameters.AddWithValue("@GodownLocationID", GodownLocationID);
                                cmd2.Parameters.AddWithValue("@NoOfBox", InpuNoOfBox);
                                cmd2.Parameters.AddWithValue("@UserAccountId", ilist.UserAccountId);
                                cmd2.Parameters.AddWithValue("@YarnRequirementDetailID", YarnRequirementDetailID);

                                cmd2.ExecuteNonQuery();
                            }

                        #endregion

                            AuditLogHelper.Log(
                                module: "Yarn Outward",
                                action: "UPDATE",
                                tableName: "YarnOutwardMaster",
                                recordId: ilist.YarnOutwardID.ToString(),
                                description: $"Updated Yarn Outward ID #{ilist.YarnOutwardID} for Party ID #{ilist.PartyId}.",
                                oldValue: oldYarnOutward,
                                newValue: ilist,
                                existingConn: con,
                                existingTran: tran
                            );

                            tran.Commit();
                        }
                        comman.Code = 201;
                        comman.Message = "Yarn Outward updated successfully.";
                    }
                    catch (Exception)
                    {
                        tran.Rollback();
                        throw;
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Yarn Outward", "UpdateYarnOutwardMaster", ex, $"YarnOutwardID={ilist.YarnOutwardID}");
                comman.Code = 500;
                comman.Message = "Error while updating data.";
            }

            WriteResponse(comman);
        }

        // View Yarn Outward
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDisplayYarnOutwardMaster()
        {
            JavaScriptSerializer js;
            List<YarnOutwardMaster> listUser = new List<YarnOutwardMaster>();
            YarnOutwardMasterResponce response = new YarnOutwardMasterResponce();

            var request = HttpContext.Current.Request;
            YarnOutwardMaster ilist = new YarnOutwardMaster();

            ilist.SearchRequirementNo = HttpContext.Current.Request.Params["SearchRequirementNo"];
            ilist.startFrom = HttpContext.Current.Request.Params["startFrom"];

            if (ilist.SearchRequirementNo != "")
            {
                ilist.SearchRequirementNo = " and (UAM.UserAccountName LIKE '%" + ilist.SearchRequirementNo + "%' OR UAM.UserAccountMobileNo LIKE '%" + ilist.SearchRequirementNo + "%' or YOM.OutwardListNo LIKE '%" + ilist.SearchRequirementNo + "%' OR PM.PartyName LIKE '%" + ilist.SearchRequirementNo + "%' or PM.MobileNo LIKE '%" + ilist.SearchRequirementNo + "%' or JM.PartyName LIKE '%" + ilist.SearchRequirementNo + "%' or JM.MobileNumber LIKE '%" + ilist.SearchRequirementNo + "%' ) ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;

                cmd.CommandText = @"select * from (
	                                select ROW_NUMBER() OVER (ORDER BY YOM.YarnOutwardID desc ) row_num, 
	                                YOM.*, UAM.UserAccountName, UAM.UserAccountMobileNo, 
                                    ISNULL(JM.PartyName, PM.PartyName) AS PartyName, 
                                    ISNULL(JM.MobileNumber, PM.MobileNo) AS MobileNo, 
                                    ISNULL(NULLIF(YOM.SundryPartyID, 0), ISNULL(PM.SundryParty, '3')) AS SundryParty,
                                    GM.GodownTitle
                                    from YarnOutwardMaster YOM
	                                LEFT JOIN UserAccountMaster UAM ON YOM.GodownManagerUserAccountId = UAM.UserAccountId
                                    LEFT JOIN PartyMaster PM ON YOM.PartyId = PM.PartyId
                                    LEFT JOIN JobberMaster JM ON YOM.PartyId = JM.Id
                                    LEFT JOIN GodownMaster GM ON YOM.GodownID = GM.GodownID 
	                                where YOM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)
		                                and YOM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)
		                                " + ilist.SearchRequirementNo + @"
                                        AND YOM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + @" 
                                ) as t1  WHERE t1.row_num between " + (Convert.ToInt32(ilist.startFrom) + 1) + @" and " + (Convert.ToInt32(ilist.startFrom) + 30) + @"
                                order by t1.YarnOutwardID desc";

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnOutwardMaster condition = new YarnOutwardMaster();
                        condition.YarnOutwardID = Convert.ToInt32(rdr["YarnOutwardID"].ToString());
                        condition.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"].ToString());
                        condition.OutwardListDate = Convert.ToDateTime(rdr["OutwardListDate"].ToString());
                        condition.DateAndTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                        condition.OutwardListDates = Convert.ToDateTime(rdr["OutwardListDate"].ToString()).ToString("dd-MM-yyyy");
                        condition.OutwardListNo = rdr["OutwardListNo"].ToString();
                        condition.GodownManagerUserAccountId = Convert.ToInt32(rdr["GodownManagerUserAccountId"].ToString());
                        condition.PartyName = rdr["PartyName"]?.ToString().ToUpper() ?? "";
                        condition.MobileNo = rdr["MobileNo"]?.ToString().ToUpper() ?? "";
                        condition.UserAccountName = rdr["UserAccountName"]?.ToString().ToUpper() ?? "";
                        condition.UserAccountMobileNo = rdr["UserAccountMobileNo"]?.ToString() ?? "";
                        condition.SundryParty = rdr["SundryParty"]?.ToString() ?? "";
                        condition.GodownTitle = rdr["GodownTitle"]?.ToString() ?? "";
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }


            response.Code = 200;
            response.Message = "Success";
            response.listYarnOutwardMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnOutwardMasterPaggination()
        {
            JavaScriptSerializer js;
            List<PagginationMaster> listUser = new List<PagginationMaster>();
            PagginationMasterResponse response = new PagginationMasterResponse();

            var request = HttpContext.Current.Request;
            PagginationMaster ilist = new PagginationMaster();

            ilist.SearchString = HttpContext.Current.Request.Params["SearchRequirementNo"];


            string SearchString = "";
            if (ilist.SearchString != "")
            {
                SearchString = " and (UAM.UserAccountName LIKE '%" + ilist.SearchString + "%' OR UAM.UserAccountMobileNo LIKE '%" + ilist.SearchString + "%' or YOM.OutwardListNo LIKE '%" + ilist.SearchString + "%') ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;

                cmd.CommandText = @"    
                                    select COUNT(*) as Total, CAST(ceiling(CAST(COUNT(*) AS DECIMAL(7,2) ) / CAST(30 AS DECIMAL(7,2) )) AS DECIMAL(7,0)) as Paggination from (
	                                select ROW_NUMBER() OVER (ORDER BY YOM.YarnOutwardID desc ) row_num, 
	                                YOM.*, UAM.UserAccountName, UAM.UserAccountMobileNo from YarnOutwardMaster YOM
	                                LEFT JOIN UserAccountMaster UAM ON YOM.GodownManagerUserAccountId = UAM.UserAccountId
	                                where YOM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)
		                                and YOM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)
                                            AND YOM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + @" 

                                        " + SearchString + @"
                                ) as t1 
                                ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        PagginationMaster condition = new PagginationMaster();
                        condition.Total = Convert.ToInt32(rdr["Total"].ToString());
                        condition.Paggination = Convert.ToInt32(rdr["Paggination"].ToString());
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listPagginationMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnOutwardDetails()
        {
            YarnOutwardMasterResponce listYarnOutwardMasterR = new YarnOutwardMasterResponce();
            List<YarnOutwardMaster> listYarnOutwardMaster = new List<YarnOutwardMaster>();

            try
            {
                string rawId = HttpContext.Current.Request.Params["YarnOutwardID"];
                int outwardId = 0;

                if (!string.IsNullOrWhiteSpace(rawId))
                {
                    rawId = rawId.Trim();
                    // 1. Direct integer parse
                    if (int.TryParse(rawId, out int parsedInt))
                    {
                        outwardId = parsedInt;
                    }
                    else
                    {
                        // 2. Encrypted string parse
                        try
                        {
                            string decoded = HttpUtility.UrlDecode(rawId);
                            if (!decoded.EndsWith("==")) decoded += "==";
                            string decrypted = Decrypt(decoded);
                            int.TryParse(decrypted, out outwardId);
                        }
                        catch
                        {
                            try
                            {
                                string decrypted = Decrypt(HttpUtility.UrlDecode(rawId));
                                int.TryParse(decrypted, out outwardId);
                            }
                            catch { }
                        }
                    }
                }

                if (outwardId <= 0)
                {
                    listYarnOutwardMasterR.Code = 105;
                    listYarnOutwardMasterR.Message = "Invalid or missing Yarn Outward ID.";
                    listYarnOutwardMasterR.listYarnOutwardMaster = listYarnOutwardMaster;
                    JavaScriptSerializer jsErr = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue };
                    Context.Response.Write(jsErr.Serialize(listYarnOutwardMasterR));
                    return;
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.CommandTimeout = 180;
                    cmd.CommandType = System.Data.CommandType.Text;
                    cmd.CommandText = @"SELECT 
                                        YOM.*, UAM.UserAccountName, UAM.UserAccountMobileNo, 
                                        ISNULL(JM.PartyName, PM.PartyName) AS PartyName, 
                                        ISNULL(JM.MobileNumber, PM.MobileNo) AS MobileNo, 
                                        ISNULL(NULLIF(YOM.SundryPartyID, 0), ISNULL(PM.SundryParty, '3')) AS SundryParty 
                                        FROM YarnOutwardMaster YOM WITH (NOLOCK)
                                        LEFT JOIN UserAccountMaster UAM WITH (NOLOCK) ON YOM.GodownManagerUserAccountId = UAM.UserAccountId
                                        LEFT JOIN PartyMaster PM WITH (NOLOCK) ON YOM.PartyId = PM.PartyId
                                        LEFT JOIN JobberMaster JM WITH (NOLOCK) ON YOM.PartyId = JM.Id
                                        WHERE YOM.YarnOutwardID = @YarnOutwardID";
                    cmd.Parameters.Add("@YarnOutwardID", SqlDbType.Int).Value = outwardId;

                    con.Open();
                    SqlDataReader rdr = cmd.ExecuteReader();

                    if (rdr.HasRows)
                    {
                        while (rdr.Read())
                        {
                            YarnOutwardMaster condition = new YarnOutwardMaster();
                            condition.YarnOutwardID = Convert.ToInt32(rdr["YarnOutwardID"].ToString());
                            condition.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"].ToString());
                            condition.OutwardListDate = Convert.ToDateTime(rdr["OutwardListDate"].ToString());
                            condition.DateAndTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd/MM/yyyy");
                            condition.OutwardListDates = Convert.ToDateTime(rdr["OutwardListDate"].ToString()).ToString("dd/MM/yyyy");
                            condition.OutwardListNo = rdr["OutwardListNo"].ToString();
                            condition.GodownManagerUserAccountId = Convert.ToInt32(rdr["GodownManagerUserAccountId"].ToString());
                            condition.PartyId = Convert.ToInt32(rdr["PartyId"].ToString());
                            condition.PartyName = rdr["PartyName"]?.ToString().ToUpper() ?? "";
                            condition.MobileNo = rdr["MobileNo"]?.ToString() ?? "";
                            condition.UserAccountName = rdr["UserAccountName"]?.ToString().ToUpper() ?? "";
                            condition.UserAccountMobileNo = rdr["UserAccountMobileNo"]?.ToString() ?? "";
                            condition.SundryParty = rdr["SundryParty"]?.ToString() ?? "";

                            SqlCommand cmd1 = new SqlCommand();
                            cmd1.Connection = con;
                            cmd1.CommandTimeout = 180;
                            cmd1.CommandType = System.Data.CommandType.Text;
                            cmd1.CommandText = @"SELECT
    YOD.*,

    -- COMPANY DETAILS
    PM.PartyName AS CompanyName,
    PM.MobileNo AS CompanyMobileNo,

    -- YARN DETAILS
    YMM.YarnMaterial,
    YCM.YarnColor,
    YPM.CompanyCode AS YarnColorCode,

    -- GODOWN DETAILS
    GLM.GodownID,
    GM.GodownTitle,
    GM.GodownAddress,
    GLM.LocationTitle,

    -- INWARD DETAILS
    YID.TotalBoxes,
    YID.TotalNetWeight

FROM YarnOutwardDetail YOD

OUTER APPLY
(
    SELECT
        STRING_AGG(X.CompanyCode, ', ') AS CompanyCode
    FROM
    (
        SELECT DISTINCT
            PD.CompanyCode
        FROM YarnPOMaster PO
        INNER JOIN YarnPODetails PD
            ON PD.YarnPOID = PO.YarnPOID
        WHERE
            PO.CompanyPartyID = YOD.YarnCompanyID
            AND PD.YarnMaterialID = YOD.YarnMaterialID
            AND PD.YarnColorID = YOD.YarnColorID
    ) X
) YPM

OUTER APPLY
(
    SELECT
        SUM(ISNULL(YID.NetWeight, 0)) AS TotalNetWeight,
        COUNT_BIG(*) AS TotalBoxes

    FROM YarnInwardMaster YIM

    INNER JOIN YarnInwardDetail YID
        ON YID.YarnInwardID = YIM.YarnInwardID

    INNER JOIN YarnPOMaster PO
        ON PO.YarnPOID = YIM.YarnPOID

    WHERE
        PO.CompanyPartyID = YOD.YarnCompanyID
        AND YIM.YarnMaterialID = YOD.YarnMaterialID
        AND YIM.YarnColorID = YOD.YarnColorID
        AND YID.GodownLocationID = YOD.GodownLocationID

) YID

-- COMPANY
LEFT JOIN PartyMaster PM
    ON PM.PartyID = YOD.YarnCompanyID
-- MATERIAL
LEFT JOIN YarnMaterialMaster YMM
    ON YMM.YarnMaterialID = YOD.YarnMaterialID
-- COLOR
LEFT JOIN YarnColorMaster YCM
    ON YCM.YarnColorID = YOD.YarnColorID
-- GODOWN LOCATION
LEFT JOIN GodownLocationMaster GLM
    ON GLM.GodownLocationID = YOD.GodownLocationID
-- GODOWN
LEFT JOIN GodownMaster GM ON GM.GodownID = GLM.GodownID
 WHERE YOD.YarnOutwardID = @YarnOutwardID ORDER BY  YOD.YarnOutwardDetailID ASC";
                            cmd1.Parameters.Add("@YarnOutwardID", SqlDbType.Int).Value = condition.YarnOutwardID;
                            SqlDataReader rdr1 = cmd1.ExecuteReader();

                            if (rdr1.HasRows)
                            {
                                List<YarnOutwardDetail> listYarnOutwardDetail = new List<YarnOutwardDetail>();
                                while (rdr1.Read())
                                {
                                    YarnOutwardDetail YarnPOD = new YarnOutwardDetail();
                                    YarnPOD.YarnOutwardDetailID = Convert.ToInt32(rdr1["YarnOutwardDetailID"]);
                                    YarnPOD.DateAndTime = Convert.ToDateTime(rdr1["DateAndTime"].ToString());
                                    YarnPOD.DateAndTimes = Convert.ToDateTime(rdr1["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                                    YarnPOD.BillToPartyID = Convert.ToInt32(rdr1["YarnCompanyID"].ToString());
                                    YarnPOD.GodownLocationID = Convert.ToInt32(rdr1["GodownLocationID"].ToString());
                                    YarnPOD.YarnMaterialID = Convert.ToInt32(rdr1["YarnMaterialID"].ToString());
                                    YarnPOD.YarnColorID = Convert.ToInt32(rdr1["YarnColorID"].ToString());
                                    YarnPOD.YarnMaterial = rdr1["YarnMaterial"].ToString().ToUpper();
                                    YarnPOD.YarnColor = rdr1["YarnColor"].ToString().ToUpper();
                                    YarnPOD.YarnColorCode = rdr1["YarnColorCode"].ToString().ToUpper();
                                    YarnPOD.CompanyName = rdr1["CompanyName"].ToString().ToUpper();
                                    YarnPOD.CompanyMobileNo = rdr1["CompanyMobileNo"].ToString().ToUpper();
                                    YarnPOD.GodownTitle = rdr1["GodownTitle"].ToString().ToUpper();
                                    YarnPOD.GodownAddress = rdr1["GodownAddress"].ToString().ToUpper();
                                    YarnPOD.LocationTitle = rdr1["LocationTitle"].ToString().ToUpper();
                                    YarnPOD.NoOfBox = Convert.ToDecimal(rdr1["NoOfBox"].ToString());

                                    listYarnOutwardDetail.Add(YarnPOD);
                                }
                                condition.listYarnOutwardDetail = listYarnOutwardDetail;
                            }

                            rdr1.Close();
                            cmd1.Dispose();

                            listYarnOutwardMaster.Add(condition);
                        }

                        listYarnOutwardMasterR.Code = 200;
                        listYarnOutwardMasterR.Message = "Success";
                        listYarnOutwardMasterR.listYarnOutwardMaster = listYarnOutwardMaster;
                    }
                    else
                    {
                        listYarnOutwardMasterR.Code = 105;
                        listYarnOutwardMasterR.Message = "Opps! Yarn Outward Not Exist.";
                        listYarnOutwardMasterR.listYarnOutwardMaster = listYarnOutwardMaster;
                    }
                    rdr.Close();
                    cmd.Dispose();
                    con.Close();
                }
            }
            catch (Exception ex)
            {
                listYarnOutwardMasterR.Code = 500;
                listYarnOutwardMasterR.Message = ex.Message;
                listYarnOutwardMasterR.listYarnOutwardMaster = listYarnOutwardMaster;
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnOutwardMasterR));
            return;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteYarnOutwardMaster()
        {
            JavaScriptSerializer js;
            CommanResponse comman = new CommanResponse();
            int yarnOutwardID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnOutwardID"]);

            if (yarnOutwardID <= 0)
            {
                AuditLogHelper.LogValidationError("Yarn Outward", "YarnOutwardMaster", "0", "Invalid YarnOutwardID specified for deletion.", "yarnOutwardID <= 0");
                comman.Code = 400;
                comman.Message = "Invalid ID specified.";
                js = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue };
                Context.Response.Write(js.Serialize(comman));
                return;
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;

                try
                {
                    con.Open();

                    // Capture Old Value Snapshot
                    object oldYarnOutward = null;
                    try
                    {
                        using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM YarnOutwardMaster WHERE YarnOutwardID = @ID", con))
                        {
                            cmdOld.Parameters.AddWithValue("@ID", yarnOutwardID);
                            using (SqlDataReader rdrOld = cmdOld.ExecuteReader())
                            {
                                if (rdrOld.Read())
                                {
                                    oldYarnOutward = new
                                    {
                                        YarnOutwardID = rdrOld["YarnOutwardID"],
                                        PartyId = rdrOld["PartyId"],
                                        OutwardListNo = rdrOld["OutwardListNo"],
                                        OutwardListDate = rdrOld["OutwardListDate"],
                                        GodownManagerUserAccountId = rdrOld["GodownManagerUserAccountId"],
                                        GodownID = rdrOld["GodownID"]
                                    };
                                }
                            }
                        }
                    }
                    catch { }

                    cmd.CommandText = "DELETE FROM YarnOutwardDetail WHERE YarnOutwardID = @YarnOutwardID";
                    cmd.Parameters.AddWithValue("@YarnOutwardID", yarnOutwardID);
                    int i = cmd.ExecuteNonQuery();

                    cmd.CommandText = "DELETE FROM YarnOutwardMaster WHERE YarnOutwardID = @YarnOutwardID";
                    int j = cmd.ExecuteNonQuery();
                    con.Close();

                    if (j > 0)
                    {
                        AuditLogHelper.Log(
                            module: "Yarn Outward",
                            action: "DELETE",
                            tableName: "YarnOutwardMaster",
                            recordId: yarnOutwardID.ToString(),
                            description: $"Deleted Yarn Outward record ID #{yarnOutwardID}.",
                            oldValue: oldYarnOutward
                        );
                        comman.Code = 200;
                        comman.Message = "Record Deleted Successfully.";
                    }
                    else
                    {
                        AuditLogHelper.LogValidationError("Yarn Outward", "YarnOutwardMaster", yarnOutwardID.ToString(), $"Failed to delete Yarn Outward record ID #{yarnOutwardID}. Record not found.", "master rows affected == 0");
                        comman.Code = 410;
                        comman.Message = "Failed to delete record.";
                    }
                    js = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue };
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }
                catch (SqlException ex)
                {
                    con.Close();
                    if (ex.Number == 547)
                    {
                        AuditLogHelper.LogDependencyError("Yarn Outward", "YarnOutwardMaster", yarnOutwardID.ToString(), $"Cannot delete Yarn Outward record ID #{yarnOutwardID} due to foreign key constraints.");
                        comman.Code = 547;
                        comman.Message = "Cannot delete this record, It's somewhere use.";
                    }
                    else
                    {
                        AuditLogHelper.LogError("Yarn Outward", "DELETE", ex, $"YarnOutwardID={yarnOutwardID}");
                        comman.Code = 405;
                        comman.Message = "Problem has been occurred while deleting your data";
                    }
                    js = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue };
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }
                catch (Exception ex)
                {
                    con.Close();
                    AuditLogHelper.LogError("Yarn Outward", "DELETE", ex, $"YarnOutwardID={yarnOutwardID}");
                    comman.Code = 500;
                    comman.Message = ex.Message;
                    js = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue };
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }
            }
        }


        [WebMethod]
        public string GetPendingYarn(int partyId, int? yarnMaterialID, List<int> yarnColorID)
        {
            DataTable dt = new DataTable();

            List<int> yarnColorList = (yarnColorID ?? new List<int>())
                .Where(x => x > 0)
                .Distinct()
                .ToList();

            int materialId = yarnMaterialID.GetValueOrDefault() > 0
                ? yarnMaterialID.Value
                : 0;

            string query = @"
        SELECT
            YRD.YarnRequirementID,
            YMM.YarnMaterialID,
            YMM.YarnMaterial,
            YCM.YarnColorID,
            YCM.YarnColor,
            ISNULL(JM.PartyName, PM.PartyName) AS PartyName,
            YRM.PartyId,
            PM.PartyName AS CompanyName,
            YRD.CompanyColourCode,

            CASE
                WHEN YRD.NoofBoxes - ISNULL(O.OutwardBoxes, 0) > 0
                THEN YRD.NoofBoxes - ISNULL(O.OutwardBoxes, 0)
                ELSE 0
            END AS NoofBoxes,

            YRD.YarnRequirementDetailID

        FROM YarnRequirementDetail AS YRD WITH (NOLOCK)

        INNER JOIN YarnRequirementMaster AS YRM WITH (NOLOCK)
            ON YRM.YarnRequirementID = YRD.YarnRequirementID

        INNER JOIN YarnColorMaster AS YCM WITH (NOLOCK)
            ON YCM.YarnColorID = YRD.YarnColorID

        INNER JOIN YarnMaterialMaster AS YMM WITH (NOLOCK)
            ON YMM.YarnMaterialID = YRD.YarnMaterialID

        LEFT JOIN PartyMaster AS PM WITH (NOLOCK)
            ON PM.PartyId = YRD.CompanyName

        LEFT JOIN JobberMaster AS JM WITH (NOLOCK)
            ON JM.Id = YRM.PartyId

        LEFT JOIN
        (
            SELECT
                YOD.YarnRequirementDetailID,
                YOD.YarnMaterialID,
                YOD.YarnColorID,
                SUM(ISNULL(YOD.NoOfBox, 0)) AS OutwardBoxes
            FROM YarnOutwardDetail AS YOD WITH (NOLOCK)
            WHERE YOD.YarnRequirementDetailID > 0
            GROUP BY
                YOD.YarnRequirementDetailID,
                YOD.YarnMaterialID,
                YOD.YarnColorID
        ) AS O
            ON O.YarnRequirementDetailID = YRD.YarnRequirementDetailID
           AND O.YarnMaterialID = YRD.YarnMaterialID
           AND O.YarnColorID = YRD.YarnColorID

        WHERE
            (@PartyId <= 0 OR YRM.PartyId = @PartyId)
            AND (@YarnMaterialID <= 0
                 OR YRD.YarnMaterialID = @YarnMaterialID)
            AND YRD.NoofBoxes > ISNULL(O.OutwardBoxes, 0)";

            if (yarnColorList.Count > 0)
            {
                List<string> paramNames = new List<string>();

                for (int i = 0; i < yarnColorList.Count; i++)
                {
                    paramNames.Add("@Color" + i);
                }

                query += " AND YRD.YarnColorID IN ("
                       + string.Join(",", paramNames)
                       + ")";
            }

            query += " ORDER BY YRD.YarnRequirementID DESC;";

            string connectionString =
                ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(connectionString))
            using (SqlCommand cmd = new SqlCommand(query, con))
            {
                cmd.CommandTimeout = 180;
                cmd.Parameters.Add("@PartyId", SqlDbType.Int).Value = partyId;
                cmd.Parameters.Add("@YarnMaterialID", SqlDbType.Int).Value = materialId;

                foreach (int colorId in yarnColorList)
                {
                    cmd.Parameters.Add("@Color" + yarnColorList.IndexOf(colorId),
                        SqlDbType.Int).Value = colorId;
                }

                using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                {
                    da.Fill(dt);
                }
            }

            var data = DataTableToList(dt);
            return new JavaScriptSerializer().Serialize(data);
        }

        [WebMethod]
        public string GetPendingYarnDetails(int partyId, int? yarnMaterialID, int? yarnColorID)
        {
            DataTable dt = new DataTable();

            string query = @"
               SELECT YRD.YarnRequirementID,YMM.YarnMaterialID,YMM.YarnMaterial,YCM.YarnColorID,YCM.YarnColor,PM.PartyName,PM.PartyId,YRD.CompanyColourCode,    
                            (YRD.NoofBoxes - ISNULL(SUM(YOD.NoOfBox), 0)) AS NoofBoxes,YRD.YarnRequirementDetailID FROM YarnRequirementDetail YRD WITH (NOLOCK)
                                JOIN YarnRequirementMaster YRM WITH (NOLOCK) ON YRD.YarnRequirementID = YRM.YarnRequirementID
                                JOIN YarnColorMaster YCM WITH (NOLOCK) ON YCM.YarnColorID = YRD.YarnColorID
                                JOIN PartyMaster PM WITH (NOLOCK) ON PM.PartyId = YRM.PartyId
                                JOIN YarnMaterialMaster YMM WITH (NOLOCK) ON YMM.YarnMaterialID = YRD.YarnMaterialID                         
	                            WHERE YRM.PartyId = @PartyId AND (@YarnColorID IS NULL OR @YarnColorID = 0 OR YRD.YarnColorID = @YarnColorID) AND (@YarnMaterialID IS NULL OR @YarnMaterialID = 0 OR YRD.YarnMaterialID = @YarnMaterialID)
                                GROUP BY YRD.YarnRequirementID,PM.PartyName,YRM.RequirementNo,YRM.RequirementDate,YRD.YarnRequirementID,YMM.YarnMaterialID,YMM.YarnMaterial,YCM.YarnColorID,YCM.YarnColor,PM.PartyName,PM.PartyId,YRD.CompanyColourCode,
                            YRD.NoofBoxes,YRD.YarnRequirementDetailID HAVING (YRD.NoofBoxes - ISNULL(SUM(YOD.NoOfBox), 0)) > 0";

            using (SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
            {
                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.CommandTimeout = 180;
                    //cmd.Parameters.AddWithValue("@YarnRequirementID", YarnRequirementID);
                    SqlDataAdapter da = new SqlDataAdapter(cmd);
                    da.Fill(dt);
                }
            }
            var data = DataTableToList(dt);
            return new JavaScriptSerializer().Serialize(data);
        }

        [WebMethod]
        public string GetUpdatePendingYarnDetails(
            int partyId,
            List<int> yarnColorID,
            int yarnMaterialID,
            int? yarnOutwardID)
        {
            DataTable dt = new DataTable();

            List<int> yarnColorList = (yarnColorID ?? new List<int>())
                .Where(x => x > 0)
                .Distinct()
                .ToList();

            int materialId = yarnMaterialID > 0 ? yarnMaterialID : 0;
            int outwardId = yarnOutwardID.GetValueOrDefault() > 0
                ? yarnOutwardID.Value
                : 0;

            string query = @"
        SELECT
            YRD.YarnRequirementID,
            YMM.YarnMaterialID,
            YMM.YarnMaterial,
            YCM.YarnColorID,
            YCM.YarnColor,
            ISNULL(JM.PartyName, PM.PartyName) AS PartyName,
            YRM.PartyId,
            PM.PartyName AS CompanyName,
            YRD.CompanyColourCode,

            YRD.NoofBoxes - ISNULL(O.OutwardBoxes, 0) AS NoofBoxes,

            YRD.YarnRequirementDetailID

        FROM YarnRequirementDetail AS YRD WITH (NOLOCK)

        INNER JOIN YarnRequirementMaster AS YRM WITH (NOLOCK)
            ON YRM.YarnRequirementID = YRD.YarnRequirementID

        INNER JOIN YarnColorMaster AS YCM WITH (NOLOCK)
            ON YCM.YarnColorID = YRD.YarnColorID

        INNER JOIN YarnMaterialMaster AS YMM WITH (NOLOCK)
            ON YMM.YarnMaterialID = YRD.YarnMaterialID

        LEFT JOIN PartyMaster AS PM WITH (NOLOCK)
            ON PM.PartyId = YRD.CompanyName

        LEFT JOIN JobberMaster AS JM WITH (NOLOCK)
            ON JM.Id = YRM.PartyId

        LEFT JOIN
        (
            SELECT
                YOD.YarnRequirementDetailID,
                YOD.YarnMaterialID,
                YOD.YarnColorID,
                SUM(ISNULL(YOD.NoOfBox, 0)) AS OutwardBoxes
            FROM YarnOutwardDetail AS YOD WITH (NOLOCK)
            WHERE YOD.YarnRequirementDetailID > 0
              AND (
                    @YarnOutwardID <= 0
                    OR YOD.YarnOutwardID <> @YarnOutwardID
                  )
            GROUP BY
                YOD.YarnRequirementDetailID,
                YOD.YarnMaterialID,
                YOD.YarnColorID
        ) AS O
            ON O.YarnRequirementDetailID = YRD.YarnRequirementDetailID
           AND O.YarnMaterialID = YRD.YarnMaterialID
           AND O.YarnColorID = YRD.YarnColorID

        WHERE
            (@PartyId <= 0 OR YRM.PartyId = @PartyId)
            AND (
                @YarnMaterialID <= 0
                OR YRD.YarnMaterialID = @YarnMaterialID
            )";

            if (yarnColorList.Count > 0)
            {
                List<string> paramNames = new List<string>();

                for (int i = 0; i < yarnColorList.Count; i++)
                {
                    paramNames.Add("@Color" + i);
                }

                query += " AND YRD.YarnColorID IN ("
                       + string.Join(",", paramNames)
                       + ")";
            }

            query += @"
        AND YRD.NoofBoxes > ISNULL(O.OutwardBoxes, 0)
        ORDER BY YRD.YarnRequirementID DESC;";

            string connectionString =
                ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(connectionString))
            using (SqlCommand cmd = new SqlCommand(query, con))
            {
                cmd.CommandTimeout = 180;
                cmd.Parameters.Add("@PartyId", SqlDbType.Int).Value = partyId;

                cmd.Parameters.Add("@YarnMaterialID", SqlDbType.Int).Value =
                    materialId;

                cmd.Parameters.Add("@YarnOutwardID", SqlDbType.Int).Value =
                    outwardId;

                for (int i = 0; i < yarnColorList.Count; i++)
                {
                    cmd.Parameters.Add("@Color" + i, SqlDbType.Int).Value =
                        yarnColorList[i];
                }

                using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                {
                    da.Fill(dt);
                }
            }

            var data = DataTableToList(dt);

            return new JavaScriptSerializer().Serialize(data);
        }

        // New Method SaveYarnOutward
        [WebMethod]
        public string SavedataYarnOutward(YarnOutwardMasterModel master, List<YarnOutwardDetailModel> detail)
        {
            int userAccountId = GetCookieValue();
            try
            {
                if (master == null || master.PartyId <= 0)
                {
                    AuditLogHelper.LogValidationError("Yarn Outward", "YarnOutwardMaster", "0", "Party ID is required for Yarn Outward.", "master == null || master.PartyId <= 0", master);
                    return new JavaScriptSerializer().Serialize(new { Status = 0, Message = "Party is required." });
                }

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                DataTable dt = new DataTable();
                using (SqlConnection con = new SqlConnection(cs))
                {
                    var (FinancialYearID, CompanyId) = GetDefaultIds();
                    SqlCommand cmd = new SqlCommand("sp_SaveYarnOutward_JSON", con);
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.CommandTimeout = 180;
                    cmd.Parameters.AddWithValue("@GodownID", master.GodownID);
                    cmd.Parameters.AddWithValue("@PartyId", master.PartyId);
                    cmd.Parameters.AddWithValue("@SundryPartyID", master.SundryPartyId);
                    cmd.Parameters.Add("@OutwardListDate", SqlDbType.Date).Value = Convert.ToDateTime(master.OutwardListDate);
                    cmd.Parameters.AddWithValue("@GodownManagerUserAccountId", master.GodownManagerUserAccountId);
                    cmd.Parameters.AddWithValue("@UserAccountId", userAccountId);
                    cmd.Parameters.AddWithValue("@FinancialYearID", FinancialYearID);
                    cmd.Parameters.AddWithValue("@CompanyId", CompanyId);
                    string jsonData = new JavaScriptSerializer().Serialize(detail);
                    cmd.Parameters.AddWithValue("@DetailJSON", jsonData);
                    con.Open();
                    SqlDataAdapter da = new SqlDataAdapter(cmd);
                    da.Fill(dt);
                    var data = DataTableToList(dt);

                    int insertedId = 0;
                    if (dt.Rows.Count > 0 && dt.Columns.Contains("YarnOutwardID") && dt.Rows[0]["YarnOutwardID"] != DBNull.Value)
                    {
                        insertedId = Convert.ToInt32(dt.Rows[0]["YarnOutwardID"]);
                    }
                    else if (dt.Rows.Count > 0 && dt.Columns.Contains("id") && dt.Rows[0]["id"] != DBNull.Value)
                    {
                        insertedId = Convert.ToInt32(dt.Rows[0]["id"]);
                    }

                    AuditLogHelper.Log(
                        module: "Yarn Outward",
                        action: "CREATE",
                        tableName: "YarnOutwardMaster",
                        recordId: insertedId.ToString(),
                        description: $"Created Yarn Outward record for Party ID #{master.PartyId} with {detail?.Count ?? 0} item(s).",
                        newValue: new { Master = master, Detail = detail }
                    );
                    return new JavaScriptSerializer().Serialize(data);
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Yarn Outward", "SavedataYarnOutward", ex, JsonConvert.SerializeObject(new { Master = master, ItemCount = detail?.Count ?? 0 }));
                return new JavaScriptSerializer().Serialize(new { Status = 0, Message = ex.Message });
            }
        }

