                            condition.PartyName = rdr["PartyName"].ToString().ToUpper();
                            condition.MobileNo = rdr["MobileNo"].ToString();
                            condition.BoxNo = rdr["TotalNoOfBox"].ToString();
                            condition.GeneratedLink = GetEncryptedLink(rdr["GeneratedLink"].ToString());
                            listUser.Add(condition);
                        }
                    }

                    rdr.Close();
                    cmd.Dispose();
                    con.Close();
                }
            }
            else
            {
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.CommandType = System.Data.CommandType.Text;

                    cmd.CommandText = @"
                     SELECT *
FROM
(
    SELECT
        ROW_NUMBER() OVER (
            ORDER BY YSM.YarnOutwardScanID DESC
        ) AS row_num,

        YOM.YarnOutwardID,
        YSM.YarnOutwardScanID,
        YOM.OutwardListNo,
        YSM.ChallanNo,
        ISNULL(YSM.ChallanDate, YSM.DateAndTime) AS DateAndTime,

        CASE
            WHEN YOM.SundryPartyID = 3 THEN JM.PartyName
            ELSE PM.PartyName
        END AS PartyName,

        CASE
            WHEN YOM.SundryPartyID = 3 THEN JM.MobileNumber
            ELSE PM.MobileNo
        END AS MobileNo,

        ISNULL(YSM.TotalBox, 0) AS TotalNoOfBox,

        CAST(ISNULL(UM.UserAccountId, 0) AS VARCHAR(20))
        + '|'
        + CAST(ISNULL(YOM.YarnOutwardID, 0) AS VARCHAR(20))
        + '|'
        + CAST(
            ISNULL(
                CASE
                    WHEN YOM.SundryPartyID = 3 THEN JM.Id
                    ELSE PM.PartyId
