        [WebMethod]
        public string GetLocation()
        {
            Context.Response.Clear();
            Context.Response.ContentType = "application/json";

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            DataTable dt = new DataTable();

            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand("SELECT DISTINCT GLM.GodownLocationID, GLM.LocationTitle FROM YarnInwardMaster YIM " +
                    "INNER JOIN YarnInwardDetail YID    ON YID.YarnInwardID = YIM.YarnInwardID " +
                    "INNER JOIN GodownLocationMaster GLM  ON GLM.GodownLocationID =  ISNULL(NULLIF(YID.YarnInterchangeID, 0), YID.GodownLocationID) " +
                    "WHERE ISNULL(YID.IsScanStutas, 0) <> 1    AND ISNULL(YID.BoxNo, '') <> ''    AND NOT EXISTS ( SELECT 1 FROM YARNOUTWARDScanMasterDetails YOSD "+
                    "WHERE YOSD.YarnInwardDetailID = YID.YarnInwardDetailID    )ORDER BY GLM.LocationTitle;", con);

                SqlDataAdapter da = new SqlDataAdapter(cmd);
