        [WebMethod]
        public string GetYarnColorCode()
            {
                Context.Response.Clear();
                Context.Response.ContentType = "application/json";

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                DataTable dt = new DataTable();

                string query = @"
            SELECT DISTINCT
                COALESCE(
                    NULLIF(YPD.CompanyCode, ''),
                    YCM.YarnColorCode,
                    ''
                ) AS YarnColorCode

            FROM YarnInwardMaster YIM

            INNER JOIN YarnPOMaster YPM
                ON YPM.YarnPOID = YIM.YarnPOID

            INNER JOIN YarnInwardDetail YID
                ON YID.YarnInwardID = YIM.YarnInwardID

            INNER JOIN GodownLocationMaster GLM
                ON GLM.GodownLocationID =
                   ISNULL(NULLIF(YID.YarnInterchangeID, 0), YID.GodownLocationID)

            LEFT JOIN YarnColorMaster YCM
                ON YCM.YarnColorID = YIM.YarnColorID

            LEFT JOIN YarnPODetails YPD
                ON YPD.YarnPODetailID = YIM.YarnPODetailIDCompanyCode

            WHERE
                ISNULL(YID.IsScanStutas, 0) <> 1
                AND ISNULL(YID.BoxNo, '') <> ''

                AND NOT EXISTS
                (
                    SELECT 1
                    FROM YARNOUTWARDScanMasterDetails YOSD
                    WHERE YOSD.YarnInwardDetailID = YID.YarnInwardDetailID
                )

                AND COALESCE(
                    NULLIF(YPD.CompanyCode, ''),
                    YCM.YarnColorCode,
                    ''
                ) <> ''

            ORDER BY YarnColorCode;
        ";

                using (SqlConnection con = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            da.Fill(dt);
                        }
                    }
                }

                var data = DataTableToList(dt);

                return new JavaScriptSerializer().Serialize(data);
            }
