        [WebMethod]
        public string GetNextBrokerCode()
        {

            string result = "";
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {

                string query = @"SELECT ISNULL(MAX(CAST(SUBSTRING(BrokerCode, 3, LEN(BrokerCode)) AS INT)),0) FROM BrokerMaster";



                SqlCommand cmd = new SqlCommand(query, con);

                con.Open();



                int maxCode = Convert.ToInt32(cmd.ExecuteScalar());

                int nextCode = maxCode + 1;



                result = "BR" + nextCode.ToString("D3"); // BR001

            }



            return result;

        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string SaveBroker(BrokerMaster obj)
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            try
            {
                if (obj == null)
                    return "Invalid broker data.";

                obj.BrokerName = (obj.BrokerName ?? "").Trim();
                obj.MobileNo = (obj.MobileNo ?? "").Trim();

                if (string.IsNullOrWhiteSpace(obj.BrokerName))
                    return "Please enter Broker Name.";

                if (string.IsNullOrWhiteSpace(obj.MobileNo))
                    return "Please enter Mobile Number.";

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            int userId = GetCookieValue();
                            int financialYearId = 0;
                            int companyId = 0;

                            using (SqlCommand cmdDefault = new SqlCommand(@"
                        SELECT
                            (SELECT TOP 1 FinancialYearID
                             FROM FinancialYearMaster
                             WHERE IsDefault = 1),
                            (SELECT TOP 1 CompanyId
                             FROM CompanyMaster
                             WHERE is_default = 1)",
                                con, tran))
                            {
                                using (SqlDataReader dr = cmdDefault.ExecuteReader())
                                {
                                    if (dr.Read())
                                    {
                                        financialYearId = dr[0] != DBNull.Value
                                            ? Convert.ToInt32(dr[0]) : 0;

                                        companyId = dr[1] != DBNull.Value
                                            ? Convert.ToInt32(dr[1]) : 0;
                                    }
                                }
                            }

                            if (userId <= 0 || companyId <= 0)
                            {
                                tran.Rollback();
                                return "Please Re-Login your Account.";
                            }

                            // Duplicate Mobile Number Check
                            using (SqlCommand checkCmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM BrokerMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE MobileNo = @MobileNo
                          AND BrokerId <> @BrokerId",
                                con, tran))
                            {
                                checkCmd.Parameters.Add("@MobileNo", SqlDbType.VarChar)
                                    .Value = obj.MobileNo;

                                checkCmd.Parameters.Add("@BrokerId", SqlDbType.Int)
                                    .Value = obj.BrokerId > 0 ? obj.BrokerId : 0;

                                if (Convert.ToInt32(checkCmd.ExecuteScalar()) > 0)
                                {
                                    AuditLogHelper.LogDuplicateError(
                                        module: "Broker Master",
                                        tableName: "BrokerMaster",
                                        recordId: obj.BrokerId > 0 ? obj.BrokerId.ToString() : null,
                                        description: "Duplicate Broker Mobile Number: " + obj.MobileNo,
                                        errorMessage: "Mobile number already exists.",
                                        requestData: obj,
                                        conn: con,
                                        tran: tran
                                    );

                                    tran.Commit();
                                    return "Mobile number already exists.";
                                }
                            }

                            if (obj.BrokerId <= 0)
                            {
                                // Generate Broker Code
                                int max;

                                using (SqlCommand cmdCode = new SqlCommand(@"
                            SELECT ISNULL(
                                MAX(CAST(SUBSTRING(BrokerCode, 3, LEN(BrokerCode)) AS INT)), 0)
                            FROM BrokerMaster",
                                    con, tran))
                                {
                                    max = Convert.ToInt32(cmdCode.ExecuteScalar());
                                }

                                string newCode = "BR" + (max + 1).ToString("D3");

                                int insertedId;

                                using (SqlCommand cmd = new SqlCommand(@"
                            INSERT INTO BrokerMaster
                            (
                                BrokerCode, BrokerName, FirmName, Email,
                                MobileNo, Address, CityName, PANCard, GSTNo,
                                CommissionRate, IsActive, UserAccountId,
                                FinancialYearID, CompanyId, DateAndTime
                            )
                            OUTPUT INSERTED.BrokerId
                            VALUES
                            (
                                @Code, @Name, @Firm, @Email,
                                @Mobile, @Address, @City, @PAN, @GST,
                                @Commission, @Active, @UserId,
                                @FY, @Company, GETDATE()
                            )",
                                    con, tran))
                                {
                                    cmd.Parameters.Add("@Code", SqlDbType.VarChar).Value = newCode;
                                    cmd.Parameters.Add("@Name", SqlDbType.NVarChar).Value = obj.BrokerName;
                                    cmd.Parameters.Add("@Firm", SqlDbType.NVarChar).Value = (object)obj.FirmName ?? "";
                                    cmd.Parameters.Add("@Email", SqlDbType.VarChar).Value = (object)obj.Email ?? "";
                                    cmd.Parameters.Add("@Mobile", SqlDbType.VarChar).Value = obj.MobileNo;
                                    cmd.Parameters.Add("@Address", SqlDbType.NVarChar).Value = (object)obj.Address ?? "";
                                    cmd.Parameters.Add("@City", SqlDbType.NVarChar).Value = (object)obj.CityName ?? "";
                                    cmd.Parameters.Add("@PAN", SqlDbType.VarChar).Value = (object)obj.PANCard ?? "";
                                    cmd.Parameters.Add("@GST", SqlDbType.VarChar).Value = (object)obj.GSTNo ?? "";

                                    SqlParameter commissionParam =
                                        cmd.Parameters.Add("@Commission", SqlDbType.Decimal);
                                    commissionParam.Precision = 18;
                                    commissionParam.Scale = 2;
                                    commissionParam.Value = obj.CommissionRate;

                                    cmd.Parameters.Add("@Active", SqlDbType.Bit).Value = obj.IsActive;
                                    cmd.Parameters.Add("@UserId", SqlDbType.Int).Value = userId;
                                    cmd.Parameters.Add("@FY", SqlDbType.Int).Value = financialYearId;
                                    cmd.Parameters.Add("@Company", SqlDbType.Int).Value = companyId;

                                    insertedId = Convert.ToInt32(cmd.ExecuteScalar());
                                }

                                obj.BrokerId = insertedId;
                                obj.BrokerCode = newCode;

                                AuditLogHelper.Log(
                                    module: "Broker Master",
                                    action: "CREATE",
                                    tableName: "BrokerMaster",
                                    recordId: insertedId.ToString(),
                                    description: "Created Broker: " + obj.BrokerName + " (" + newCode + ")",
                                    newValue: obj,
                                    existingConn: con,
                                    existingTran: tran
                                );

                                tran.Commit();
                                return "success";
                            }
                            else
                            {
                                // Fetch Old Broker Data
                                object oldBroker = null;

                                using (SqlCommand cmdOld = new SqlCommand(
                                    "SELECT * FROM BrokerMaster WITH (UPDLOCK, HOLDLOCK) WHERE BrokerId = @Id",
                                    con, tran))
                                {
                                    cmdOld.Parameters.Add("@Id", SqlDbType.Int).Value = obj.BrokerId;

                                    using (SqlDataReader rdrOld = cmdOld.ExecuteReader())
                                    {
                                        if (rdrOld.Read())
                                        {
                                            Dictionary<string, object> oldData =
                                                new Dictionary<string, object>();

                                            for (int i = 0; i < rdrOld.FieldCount; i++)
                                            {
                                                oldData[rdrOld.GetName(i)] =
                                                    rdrOld.IsDBNull(i) ? null : rdrOld.GetValue(i);
                                            }

                                            oldBroker = oldData;
                                        }
                                    }
                                }

                                if (oldBroker == null)
                                {
                                    tran.Rollback();
                                    return "Broker record not found.";
                                }

                                // Update Broker
                                using (SqlCommand cmd = new SqlCommand(@"
                            UPDATE BrokerMaster SET
                                BrokerName = @Name,
                                FirmName = @Firm,
                                Email = @Email,
                                MobileNo = @Mobile,
                                Address = @Address,
                                CityName = @City,
                                PANCard = @PAN,
                                GSTNo = @GST,
                                CommissionRate = @Commission,
                                IsActive = @Active
                            WHERE BrokerId = @Id",
                                    con, tran))
                                {
                                    cmd.Parameters.Add("@Id", SqlDbType.Int).Value = obj.BrokerId;
                                    cmd.Parameters.Add("@Name", SqlDbType.NVarChar).Value = obj.BrokerName;
                                    cmd.Parameters.Add("@Firm", SqlDbType.NVarChar).Value = (object)obj.FirmName ?? "";
                                    cmd.Parameters.Add("@Email", SqlDbType.VarChar).Value = (object)obj.Email ?? "";
                                    cmd.Parameters.Add("@Mobile", SqlDbType.VarChar).Value = obj.MobileNo;
                                    cmd.Parameters.Add("@Address", SqlDbType.NVarChar).Value = (object)obj.Address ?? "";
                                    cmd.Parameters.Add("@City", SqlDbType.NVarChar).Value = (object)obj.CityName ?? "";
                                    cmd.Parameters.Add("@PAN", SqlDbType.VarChar).Value = (object)obj.PANCard ?? "";
                                    cmd.Parameters.Add("@GST", SqlDbType.VarChar).Value = (object)obj.GSTNo ?? "";

                                    SqlParameter commissionParam =
                                        cmd.Parameters.Add("@Commission", SqlDbType.Decimal);
                                    commissionParam.Precision = 18;
                                    commissionParam.Scale = 2;
                                    commissionParam.Value = obj.CommissionRate;

                                    cmd.Parameters.Add("@Active", SqlDbType.Bit).Value = obj.IsActive;

                                    if (cmd.ExecuteNonQuery() <= 0)
                                    {
                                        tran.Rollback();
                                        return "Broker record not found.";
                                    }
                                }

                                AuditLogHelper.Log(
                                    module: "Broker Master",
                                    action: "UPDATE",
                                    tableName: "BrokerMaster",
                                    recordId: obj.BrokerId.ToString(),
                                    description: "Updated Broker: " + obj.BrokerName,
                                    oldValue: oldBroker,
                                    newValue: obj,
                                    existingConn: con,
                                    existingTran: tran
                                );

                                tran.Commit();
                                return "success";
                            }
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Broker Master", "SaveBroker", ex);
                return "Error while saving broker details.";
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string DeleteBroker(int BrokerId)
        {
            try
            {
                if (BrokerId <= 0)
                    return "Invalid Broker ID.";

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            // Verify Broker Exists and Lock Record
                            object oldBroker = null;

                            using (SqlCommand cmdOld = new SqlCommand(@"
                        SELECT *
                        FROM BrokerMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE BrokerId = @BrokerId",
                                con, tran))
                            {
                                cmdOld.Parameters.Add("@BrokerId", SqlDbType.Int).Value = BrokerId;

                                using (SqlDataReader rdr = cmdOld.ExecuteReader())
                                {
                                    if (rdr.Read())
                                    {
                                        Dictionary<string, object> oldData =
                                            new Dictionary<string, object>();

                                        for (int i = 0; i < rdr.FieldCount; i++)
                                        {
                                            oldData[rdr.GetName(i)] =
                                                rdr.IsDBNull(i) ? null : rdr.GetValue(i);
                                        }

                                        oldBroker = oldData;
                                    }
                                }
                            }

                            if (oldBroker == null)
                            {
                                tran.Rollback();
                                return "Broker record not found.";
                            }

                            // Dependency Check: SaleOrder
                            int dependencyCount;

                            using (SqlCommand checkCmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM SaleOrder WITH (UPDLOCK, HOLDLOCK)
                        WHERE BrokerID = @BrokerId",
                                con, tran))
                            {
                                checkCmd.Parameters.Add("@BrokerId", SqlDbType.Int).Value = BrokerId;

                                dependencyCount = Convert.ToInt32(checkCmd.ExecuteScalar());
                            }

                            if (dependencyCount > 0)
                            {
                                AuditLogHelper.LogDuplicateError(
                                    module: "Broker Master",
                                    tableName: "BrokerMaster",
                                    recordId: BrokerId.ToString(),
                                    description: "Broker deletion prevented because it is linked with SaleOrder.",
                                    errorMessage: "This Broker cannot be deleted because it is already used in Sale Orders.",
                                    requestData: new { BrokerId = BrokerId },
                                    conn: con,
                                    tran: tran
                                );

                                tran.Commit();

                                return "This Broker cannot be deleted because it is already used in Sale Orders.";
                            }

                            // Delete Broker
                            using (SqlCommand cmd = new SqlCommand(@"
                        DELETE FROM BrokerMaster
                        WHERE BrokerId = @BrokerId",
                                con, tran))
                            {
                                cmd.Parameters.Add("@BrokerId", SqlDbType.Int).Value = BrokerId;

                                int rowsAffected = cmd.ExecuteNonQuery();

                                if (rowsAffected <= 0)
                                {
                                    tran.Rollback();
                                    return "Broker record not found.";
                                }
                            }

                            // Audit Log
                            AuditLogHelper.Log(
                                module: "Broker Master",
                                action: "DELETE",
                                tableName: "BrokerMaster",
                                recordId: BrokerId.ToString(),
                                description: "Deleted Broker ID #" + BrokerId,
                                oldValue: oldBroker,
                                existingConn: con,
                                existingTran: tran
                            );

                            tran.Commit();

                            return "success";
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError("Broker Master", "DeleteBroker", ex);

                if (ex.Number == 547)
                    return "This Broker cannot be deleted because it is linked with other records.";

                return "Error while deleting Broker.";
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Broker Master", "DeleteBroker", ex);
                return "Error while deleting Broker.";
            }
        }
