        public string GetNextTransportCode()
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();

                string query = @"SELECT ISNULL(MAX(CAST(SUBSTRING(TransportCode,3,LEN(TransportCode)) AS INT)),0) FROM TransportMaster";

                SqlCommand cmd = new SqlCommand(query, con);

                int maxCode = Convert.ToInt32(cmd.ExecuteScalar());
                int nextCode = maxCode + 1;

                string newCode = "TR" + nextCode.ToString("D3"); // TR001

                return newCode;
            }
        }
        [WebMethod]
        public string SaveTransport(TransportMaster obj)
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            try
            {
                if (obj == null)
                    return "Invalid transport information.";

                obj.TransportName = (obj.TransportName ?? "").Trim();
                obj.MobileNo = (obj.MobileNo ?? "").Trim();

                if (string.IsNullOrWhiteSpace(obj.TransportName))
                    return "Please enter Transport Name.";

                if (string.IsNullOrWhiteSpace(obj.MobileNo))
                    return "Please enter Mobile Number.";

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            int userId = GetCookieValue();
                            var (fyId, compId) = GetDefaultIds();

                            // Duplicate Mobile Number Check
                            string duplicateQuery = @"
                        SELECT COUNT(1)
                        FROM TransportMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE MobileNo = @MobileNo
                          AND ISNULL(TransportId, 0) <> @TransportId";

                            using (SqlCommand checkCmd = new SqlCommand(duplicateQuery, con, tran))
                            {
                                checkCmd.Parameters.Add("@MobileNo", SqlDbType.VarChar).Value = obj.MobileNo;
                                checkCmd.Parameters.Add("@TransportId", SqlDbType.Int).Value =
                                   obj.TransportId;

                                if (Convert.ToInt32(checkCmd.ExecuteScalar()) > 0)
                                {
                                    tran.Rollback();

                                    return "Mobile number already exists.";
                                }
                            }

                            if (obj.TransportId <= 0)
                            {
                                // Generate Transport Code
                                string codeQuery = @"
                            SELECT ISNULL(
                                MAX(TRY_CAST(SUBSTRING(TransportCode, 3, LEN(TransportCode)) AS INT)),
                                0
                            )
                            FROM TransportMaster WITH (UPDLOCK, HOLDLOCK)";

                                int max;

                                using (SqlCommand cmdCode = new SqlCommand(codeQuery, con, tran))
                                {
                                    max = Convert.ToInt32(cmdCode.ExecuteScalar());
                                }

                                string code = "TR" + (max + 1).ToString("D3");

                                string insertQuery = @"
                            INSERT INTO TransportMaster
                            (
                                TransportCode, TransportName, FirmName,
                                ContactPerson, Email, MobileNo,
                                AlternateMobileNo, Address, CityName,
                                PANCard, GSTNo, VehicleType, IsActive,
                                UserAccountId, FinancialYearID, CompanyId,
                                DateAndTime
                            )
                            OUTPUT INSERTED.TransportId
                            VALUES
                            (
                                @Code, @Name, @Firm,
                                @Contact, @Email, @Mobile,
                                @AltMobile, @Address, @City,
                                @PAN, @GST, @Vehicle, @Active,
                                @UserId, @FY, @Comp,
                                GETDATE()
                            )";

                                int insertedId;

                                using (SqlCommand cmd = new SqlCommand(insertQuery, con, tran))
                                {
                                    cmd.Parameters.Add("@Code", SqlDbType.VarChar).Value = code;
                                    cmd.Parameters.Add("@Name", SqlDbType.NVarChar).Value = obj.TransportName;
                                    cmd.Parameters.Add("@Firm", SqlDbType.NVarChar).Value = (object)obj.FirmName ?? DBNull.Value;
                                    cmd.Parameters.Add("@Contact", SqlDbType.NVarChar).Value = (object)obj.ContactPerson ?? DBNull.Value;
                                    cmd.Parameters.Add("@Email", SqlDbType.VarChar).Value = (object)obj.Email ?? DBNull.Value;
                                    cmd.Parameters.Add("@Mobile", SqlDbType.VarChar).Value = obj.MobileNo;
                                    cmd.Parameters.Add("@AltMobile", SqlDbType.VarChar).Value = (object)obj.AlternateMobileNo ?? DBNull.Value;
                                    cmd.Parameters.Add("@Address", SqlDbType.NVarChar).Value = (object)obj.Address ?? DBNull.Value;
                                    cmd.Parameters.Add("@City", SqlDbType.VarChar).Value = (object)obj.CityName ?? DBNull.Value;
                                    cmd.Parameters.Add("@PAN", SqlDbType.VarChar).Value = (object)obj.PANCard ?? DBNull.Value;
                                    cmd.Parameters.Add("@GST", SqlDbType.VarChar).Value = (object)obj.GSTNo ?? DBNull.Value;
                                    cmd.Parameters.Add("@Vehicle", SqlDbType.NVarChar).Value = (object)obj.VehicleType ?? DBNull.Value;
                                    cmd.Parameters.Add("@Active", SqlDbType.Bit).Value = obj.IsActive;
                                    cmd.Parameters.Add("@UserId", SqlDbType.Int).Value = userId;
                                    cmd.Parameters.Add("@FY", SqlDbType.Int).Value = fyId;
                                    cmd.Parameters.Add("@Comp", SqlDbType.Int).Value = compId;

                                    insertedId = Convert.ToInt32(cmd.ExecuteScalar());
                                }

                                obj.TransportId = insertedId;
                                obj.TransportCode = code;

                                AuditLogHelper.Log(
                                    module: "Transport Master",
                                    action: "CREATE",
                                    tableName: "TransportMaster",
                                    recordId: insertedId.ToString(),
                                    description: $"Created Transport: {obj.TransportName} ({code})",
                                    newValue: obj,
                                    existingConn: con,
                                    existingTran: tran
                                );
                            }
                            else
                            {
                                // Verify record exists
                                object oldTransport = null;

                                using (SqlCommand cmdOld = new SqlCommand(
                                    "SELECT * FROM TransportMaster WHERE TransportId = @Id",
                                    con, tran))
                                {
                                    cmdOld.Parameters.Add("@Id", SqlDbType.Int).Value = obj.TransportId;

                                    using (SqlDataReader rdr = cmdOld.ExecuteReader())
                                    {
                                        if (rdr.Read())
                                        {
                                            Dictionary<string, object> oldData =
                                                new Dictionary<string, object>();

                                            for (int i = 0; i < rdr.FieldCount; i++)
                                            {
                                                oldData[rdr.GetName(i)] =
                                                    rdr.IsDBNull(i) ? null : rdr.GetValue(i);
                                            }

                                            oldTransport = oldData;
                                        }
                                    }
                                }

                                if (oldTransport == null)
                                {
                                    tran.Rollback();
                                    return "Transport record not found.";
                                }

                                string updateQuery = @"
                            UPDATE TransportMaster
                            SET
                                TransportName = @Name,
                                FirmName = @Firm,
                                ContactPerson = @Contact,
                                Email = @Email,
                                MobileNo = @Mobile,
                                AlternateMobileNo = @AltMobile,
                                Address = @Address,
                                CityName = @City,
                                PANCard = @PAN,
                                GSTNo = @GST,
                                VehicleType = @Vehicle,
                                IsActive = @Active
                            WHERE TransportId = @Id";

                                using (SqlCommand cmd = new SqlCommand(updateQuery, con, tran))
                                {
                                    cmd.Parameters.Add("@Id", SqlDbType.Int).Value = obj.TransportId;
                                    cmd.Parameters.Add("@Name", SqlDbType.NVarChar).Value = obj.TransportName;
                                    cmd.Parameters.Add("@Firm", SqlDbType.NVarChar).Value = (object)obj.FirmName ?? DBNull.Value;
                                    cmd.Parameters.Add("@Contact", SqlDbType.NVarChar).Value = (object)obj.ContactPerson ?? DBNull.Value;
                                    cmd.Parameters.Add("@Email", SqlDbType.VarChar).Value = (object)obj.Email ?? DBNull.Value;
                                    cmd.Parameters.Add("@Mobile", SqlDbType.VarChar).Value = obj.MobileNo;
                                    cmd.Parameters.Add("@AltMobile", SqlDbType.VarChar).Value = (object)obj.AlternateMobileNo ?? DBNull.Value;
                                    cmd.Parameters.Add("@Address", SqlDbType.NVarChar).Value = (object)obj.Address ?? DBNull.Value;
                                    cmd.Parameters.Add("@City", SqlDbType.VarChar).Value = (object)obj.CityName ?? DBNull.Value;
                                    cmd.Parameters.Add("@PAN", SqlDbType.VarChar).Value = (object)obj.PANCard ?? DBNull.Value;
                                    cmd.Parameters.Add("@GST", SqlDbType.VarChar).Value = (object)obj.GSTNo ?? DBNull.Value;
                                    cmd.Parameters.Add("@Vehicle", SqlDbType.NVarChar).Value = (object)obj.VehicleType ?? DBNull.Value;
                                    cmd.Parameters.Add("@Active", SqlDbType.Bit).Value = obj.IsActive;

                                    if (cmd.ExecuteNonQuery() <= 0)
                                    {
                                        tran.Rollback();
                                        return "Transport record not found.";
                                    }
                                }

                                AuditLogHelper.Log(
                                    module: "Transport Master",
                                    action: "UPDATE",
                                    tableName: "TransportMaster",
                                    recordId: obj.TransportId.ToString(),
                                    description: $"Updated Transport: {obj.TransportName}",
                                    oldValue: oldTransport,
                                    newValue: obj,
                                    existingConn: con,
                                    existingTran: tran
                                );
                            }

                            tran.Commit();
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }

                return "success";
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError("Transport Master", "SaveTransport", ex);

                if (ex.Number == 2601 || ex.Number == 2627)
                    return "Duplicate Transport record already exists.";

                return "Problem occurred while saving Transport.";
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Transport Master", "SaveTransport", ex);
                return "Problem occurred while saving Transport.";
            }
        }
        [WebMethod]
        public string DeleteTransport(int TransportId)
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            try
            {
                if (TransportId <= 0)
                    return "Invalid Transport ID.";

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.Serializable))
                    {
                        try
                        {
                            object oldTransport = null;
                            string transportCode = "";

                            // Check Transport and capture old value
                            using (SqlCommand cmdOld = new SqlCommand(@"
                        SELECT *
                        FROM TransportMaster WITH (UPDLOCK, HOLDLOCK)
                        WHERE TransportId = @Id",
                                con, tran))
                            {
                                cmdOld.Parameters.Add("@Id", SqlDbType.Int).Value = TransportId;

                                using (SqlDataReader rdr = cmdOld.ExecuteReader())
                                {
                                    if (rdr.Read())
                                    {
                                        Dictionary<string, object> oldData =
                                            new Dictionary<string, object>();

                                        for (int i = 0; i < rdr.FieldCount; i++)
                                        {
                                            oldData[rdr.GetName(i)] =
                                                rdr.IsDBNull(i) ? null : rdr.GetValue(i);
                                        }

                                        oldTransport = oldData;
                                        transportCode = Convert.ToString(rdr["TransportCode"]);
                                    }
                                }
                            }

                            if (oldTransport == null)
                            {
                                tran.Rollback();
                                return "Transport record not found.";
                            }

                            // Dependency Check: SaleOrder.TransportID stores TransportCode
                            int dependencyCount;

                            using (SqlCommand checkCmd = new SqlCommand(@"
                        SELECT COUNT(1)
                        FROM SaleOrder WITH (UPDLOCK, HOLDLOCK)
                        WHERE TransportID = @TransportCode",
                                con, tran))
                            {
                                checkCmd.Parameters.Add("@TransportCode", SqlDbType.VarChar)
                                    .Value = transportCode;

                                dependencyCount = Convert.ToInt32(checkCmd.ExecuteScalar());
                            }

                            if (dependencyCount > 0)
                            {
                                tran.Rollback();

                                AuditLogHelper.Log(
                                    module: "Transport Master",
                                    action: "DELETE_BLOCKED",
                                    tableName: "TransportMaster",
                                    recordId: TransportId.ToString(),
                                    description: $"Delete prevented. Transport {transportCode} is linked with {dependencyCount} Sale Order record(s).",
                                    oldValue: oldTransport,
                                    errorMessage: "Transport is already used in SaleOrder."
                                );

                                return "This Transport cannot be deleted because it is already used in Sale Orders.";
                            }

                            // Delete Transport
                            using (SqlCommand cmd = new SqlCommand(@"
                        DELETE FROM TransportMaster
                        WHERE TransportId = @Id",
                                con, tran))
                            {
                                cmd.Parameters.Add("@Id", SqlDbType.Int).Value = TransportId;

                                if (cmd.ExecuteNonQuery() <= 0)
                                {
                                    tran.Rollback();
                                    return "Failed to delete Transport record.";
                                }
                            }

                            AuditLogHelper.Log(
                                module: "Transport Master",
                                action: "DELETE",
                                tableName: "TransportMaster",
                                recordId: TransportId.ToString(),
                                description: $"Deleted Transport ID #{TransportId} ({transportCode})",
                                oldValue: oldTransport,
                                existingConn: con,
                                existingTran: tran
                            );

                            tran.Commit();
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }

                return "success";
            }
            catch (SqlException ex)
            {
                AuditLogHelper.LogError("Transport Master", "DeleteTransport", ex);

                if (ex.Number == 547)
                    return "This Transport cannot be deleted because it is linked with other records.";

                return "Problem occurred while deleting Transport.";
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Transport Master", "DeleteTransport", ex);
                return "Problem occurred while deleting Transport.";
            }
        }
