        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object GetDynamicMenu()
        {
            string userId = "";

            HttpCookie cookie = HttpContext.Current.Request.Cookies["UserIDs"];

            if (cookie != null && !string.IsNullOrWhiteSpace(cookie.Value))
            {
                string cookieValue = HttpUtility.UrlDecode(cookie.Value).Trim();

                // Cookie value: UserIDs=17
                if (cookieValue.StartsWith("UserIDs=", StringComparison.OrdinalIgnoreCase))
                {
                    userId = cookieValue.Substring("UserIDs=".Length).Trim();
                }
                else
                {
                    // Cookie value: 17
                    userId = cookieValue;
                }
            }

            if (!int.TryParse(userId, out int userIdValue))
            {
                return new
                {
                    Success = false,
                    Message = "Invalid User ID: " + userId,
                    Data = new object[0]
                };
            }
            DataTable dt = new DataTable();

            using (SqlConnection con = new SqlConnection(
                ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
            {
                con.Open();
                //EnsureProcessManagementModuleSetup(con);

                SqlDataAdapter da = new SqlDataAdapter(@"
            SELECT 
                MM.Menu_Id,
                MM.Menu_Name,
                MM.Menu_Icon,
                MM.Menu_OrderNo,
                SM.SubMenu_Id,
                SM.SubMenu_Name,
                SM.SubMenu_Icon,
                SM.SubMenu_OrderNo,
                SM.Controller,
                SM.Action,

                CASE 
                    WHEN UAM.UserRole = 'Admin'
                         AND SM.SubMenu_Name = 'User Permission'
                    THEN 1
                    ELSE ISNULL(UMP.[View], 0)
                END AS [View],

                ISNULL(UMP.[Add], 0) AS [Add],
                ISNULL(UMP.[Edit], 0) AS [Edit],
                ISNULL(UMP.[Delete], 0) AS [Delete]

            FROM MenuMaster MM

            INNER JOIN SubMenuMaster SM 
                ON MM.Menu_Id = SM.Menu_Id

            LEFT JOIN UserMenuPermission UMP 
                ON MM.Menu_Id = UMP.Menu_Id
                AND SM.SubMenu_Id = UMP.SubMenu_Id
                AND UMP.User_Id = @UserId

            INNER JOIN UserAccountMaster UAM 
                ON UAM.UserAccountId = @UserId

            WHERE 
                ISNULL(UMP.[View], 0) = 1
                OR (
                    UAM.UserRole = 'Admin'
                    AND SM.SubMenu_Name = 'User Permission'
                )

            ORDER BY 
                MM.Menu_OrderNo,
                SM.SubMenu_OrderNo
        ", con);

                da.SelectCommand.Parameters.Add("@UserId", SqlDbType.Int).Value = userIdValue;

                da.Fill(dt);
            }

            var result = dt.AsEnumerable()
                .GroupBy(x => new
                {
                    Menu_Id = x["Menu_Id"].ToString(),
                    Menu_Name = x["Menu_Name"].ToString(),
                    Menu_Icon = x["Menu_Icon"].ToString()
                })
                .Select(menu =>
                {
                    var subMenusList = new List<object>();

                    foreach (var sub in menu)
                    {
                        subMenusList.Add(new
                        {
                            SubMenu_Id = sub["SubMenu_Id"].ToString(),
                            SubMenu_Name = sub["SubMenu_Name"].ToString(),
                            SubMenu_Icon = sub["SubMenu_Icon"].ToString(),
                            Controller = sub["Controller"].ToString(),
                            Action = sub["Action"].ToString(),

                            View = Convert.ToBoolean(sub["View"]),
                            Add = Convert.ToBoolean(sub["Add"]),
                            Edit = Convert.ToBoolean(sub["Edit"]),
                            Delete = Convert.ToBoolean(sub["Delete"])
                        });                    
                    }

                    return new
                    {
                        Menu_Id = menu.Key.Menu_Id,
                        Menu_Name = menu.Key.Menu_Name,
                        Menu_Icon = menu.Key.Menu_Icon,
                        SubMenus = subMenusList
                    };
                }).ToList();

            return result;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public bool CheckPagePermission(string controller, string action)
        {
            if (string.Equals(controller, "YarnOutWardSundryParty", StringComparison.OrdinalIgnoreCase))
            {
                controller = "YarnOutWardChallannew";
                action = "YarnOutWardChallannew";
            }

            string userId = "";
            HttpCookie cookie = HttpContext.Current.Request.Cookies["UserIDs"];
            if (cookie != null && !string.IsNullOrEmpty(cookie.Value))
            {
                userId = cookie.Value.Split('=')[1];
            }
            int count = 0;
            using (SqlConnection con = new SqlConnection(
                ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
            {
                SqlCommand cmd = new SqlCommand(@"SELECT COUNT(*) FROM UserMenuPermission UMP INNER JOIN SubMenuMaster SM ON SM.SubMenu_Id = UMP.SubMenu_Id
                    WHERE  UMP.User_Id = @UserId AND SM.Controller = @Controller AND SM.Action = @Action AND UMP.[View] = 1 ", con);
                cmd.Parameters.AddWithValue("@UserId", userId);
                cmd.Parameters.AddWithValue("@Controller", controller);
                cmd.Parameters.AddWithValue("@Action", action);
                con.Open();
                count = Convert.ToInt32(cmd.ExecuteScalar());
                con.Close();
            }
            return count > 0;
        }
        [WebMethod]
        public string SavePermission(List<PermissionModel> permissions)
        {
            if (permissions == null || permissions.Count == 0)
            {
                return "No Data";
            }

            using (SqlConnection con = new SqlConnection(
                ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
            {
                con.Open();

                int userId = permissions[0].User_Id;
                int menuId = permissions[0].Menu_Id;

                // =========================
                // DELETE OLD DATA
                // =========================
                SqlCommand del = new SqlCommand(@"
            DELETE FROM UserMenuPermission
            WHERE User_Id = @UserId
            AND Menu_Id = @MenuId
        ", con);
                del.Parameters.AddWithValue("@UserId", userId);
                del.Parameters.AddWithValue("@MenuId", menuId);

                del.ExecuteNonQuery();

                // =========================
                // INSERT ONLY TRUE VALUE
                // =========================
                foreach (var p in permissions)
                {
                    // CHECK ANY PERMISSION TRUE
                    bool hasPermission =
                           p.CanView
                        || p.CanAdd
                        || p.CanEdit
                        || p.CanDelete;

                    if (!hasPermission)
                    {
                        continue;
                    }

                    SqlCommand cmd = new SqlCommand(@"
                INSERT INTO UserMenuPermission
                (
                    User_Id,
                    Menu_Id,
                    SubMenu_Id,
                    [View],
                    [Add],
                    [Edit],
                    [Delete]
                )
                VALUES
                (
                    @User_Id,
                    @Menu_Id,
                    @SubMenu_Id,
                    @CanView,
                    @CanAdd,
                    @CanEdit,
                    @CanDelete
                )
            ", con);

                    cmd.Parameters.AddWithValue("@User_Id", p.User_Id);
                    cmd.Parameters.AddWithValue("@Menu_Id", p.Menu_Id);
                    cmd.Parameters.AddWithValue("@SubMenu_Id", p.SubMenu_Id);

                    cmd.Parameters.AddWithValue("@CanView", p.CanView);
                    cmd.Parameters.AddWithValue("@CanAdd", p.CanAdd);
                    cmd.Parameters.AddWithValue("@CanEdit", p.CanEdit);
                    cmd.Parameters.AddWithValue("@CanDelete", p.CanDelete);

                    cmd.ExecuteNonQuery();
                }
            }

            return "Success";
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string GetAllMobileMenus()
        {
            DataTable dtMenu = new DataTable();
            DataTable dtSub = new DataTable();

            using (SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
            {
                con.Open();

                SqlDataAdapter da1 = new SqlDataAdapter("SELECT * FROM MobileMenuMaster WHERE IsActive = 1 ORDER BY Menu_OrderNo", con);
                da1.Fill(dtMenu);

                SqlDataAdapter da2 = new SqlDataAdapter("SELECT * FROM MobileSubMenuMaster WHERE IsActive = 1 ORDER BY SubMenu_OrderNo", con);
