        #region ProductionSleep
        [WebMethod]
        public List<JobberMasterClass> GetJobberMaster()
        {
            List<JobberMasterClass> list =
                new List<JobberMasterClass>();

            string connectionString =
                ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;

            using (SqlConnection con =
                   new SqlConnection(connectionString))
            {
                using (SqlCommand cmd =
                       new SqlCommand())
                {
                    cmd.Connection = con;

                    cmd.CommandType =
                        CommandType.Text;

                    cmd.CommandText = @"
             SELECT
                Id AS JobberMasterID,
                PartyName AS JobberName,
                Rpm,
                PanaRepeat,
                PanaWidth,
                NoOfMachines
            FROM JobberMaster
            WHERE ISNULL(IsActiveParty, 1) = 1
            ORDER BY PartyName
            ";

                    con.Open();

                    using (SqlDataReader rdr =
                           cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            JobberMasterClass item =
                                new JobberMasterClass();

                            item.JobberMasterID =
                                rdr["JobberMasterID"] ==
                                DBNull.Value
                                    ? 0
                                    : Convert.ToInt32(
                                        rdr["JobberMasterID"]
                                    );

                            item.JobberName =
                                rdr["JobberName"] ==
                                DBNull.Value
                                    ? ""
                                    : rdr["JobberName"]
                                        .ToString();

                            item.Rpm =
                                rdr["Rpm"] ==
                                DBNull.Value
                                    ? "0"
                                    : rdr["Rpm"]
                                        .ToString();

                            item.PanaRepeat =
                                rdr["PanaRepeat"] ==
                                DBNull.Value
                                    ? "0"
                                    : rdr["PanaRepeat"]
                                        .ToString();

                            item.PanaWidth =
                                rdr["PanaWidth"] ==
                                DBNull.Value
                                    ? "0"
                                    : rdr["PanaWidth"]
                                        .ToString();

                            item.NoOfMachines =
                                rdr["NoOfMachines"] ==
                                DBNull.Value
                                    ? "0"
                                    : rdr["NoOfMachines"]
                                        .ToString();

                            list.Add(item);
                        }
                    }
                }
            }

            return list;
        }
        /// <summary>
        /// GetProductionOrderList
        /// </summary>
        /// <returns></returns>
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public List<ProductionOrderListItem> GetProductionOrderList()
        {
            var list = new List<ProductionOrderListItem>();

            string connectionString =
                ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;

            using (SqlConnection con =
                   new SqlConnection(connectionString))
            {
                con.Open();

                int loggedInUserAccountId = 0;
                int currentUserPartyId = 0;
                string currentUserRole = "";

                var httpContext = HttpContext.Current ?? Context;
                if (httpContext != null && httpContext.Request.Cookies["UserIDs"] != null)
                {
                    var cookie = httpContext.Request.Cookies["UserIDs"];
                    string val = cookie["UserIDs"] ?? cookie.Value;
                    if (!string.IsNullOrEmpty(val))
                    {
                        if (val.Contains("=")) val = val.Split('=')[1];
                        int.TryParse(val, out loggedInUserAccountId);
                    }
                }

                if (loggedInUserAccountId > 0)
                {
                    string userQuery = @"
                            SELECT 
                                ISNULL(UserRole, '') AS UserRole,
                                ISNULL(PartyId, 0) AS PartyId
                            FROM UserAccountMaster
                            WHERE UserAccountId = @UserAccountId";

                    using (SqlCommand userCmd = new SqlCommand(userQuery, con))
                    {
                        userCmd.Parameters.AddWithValue("@UserAccountId", loggedInUserAccountId);
                        using (SqlDataReader userReader = userCmd.ExecuteReader())
                        {
                            if (userReader.Read())
                            {
                                currentUserRole = Convert.ToString(userReader["UserRole"]).Trim();
                                currentUserPartyId = Convert.ToInt32(userReader["PartyId"]);
                            }
                        }
                    }

                    if (currentUserPartyId <= 0 && !string.Equals(currentUserRole, "Admin", StringComparison.OrdinalIgnoreCase))
                    {
                        using (SqlCommand cmdP = new SqlCommand("SELECT TOP 1 PartyId FROM PartyMaster WHERE UserAccountId = @UID AND SundryParty = 3", con))
                        {
                            cmdP.Parameters.AddWithValue("@UID", loggedInUserAccountId);
                            object objP = cmdP.ExecuteScalar();
                            if (objP != null && objP != DBNull.Value)
                            {
                                currentUserPartyId = Convert.ToInt32(objP);
                            }
                        }
                    }
                }

                bool isAdmin = string.Equals(currentUserRole, "Admin", StringComparison.OrdinalIgnoreCase);

                string sql = @"
SELECT
    POM.ProductionOrderID,
    POM.ProductionOrderNo,
    POM.ProductionOrderDate,
    POM.JobWorkerID,

    CASE
        WHEN ISNULL(PM.SundryParty, 0) = 3
            THEN ISNULL(JM.PartyName, POM.JobWorkerName)
        ELSE ISNULL(PM.PartyName, POM.JobWorkerName)
    END AS JobWorkerName,

    POM.PanaRepeat,
    POM.JobRate,
    POM.Traders,
    POM.TotalPcs,
    POM.TotalProductionPcs,
    POM.TotalPendingPcs,
    POM.TotalAmount,
    POM.Status,
    POM.CompanyId,
    POM.UserAccountId,
    ISNULL(D.DetailCount, 0) AS DetailCount

FROM ProductionOrderMaster POM

LEFT JOIN PartyMaster PM
    ON PM.PartyId = POM.JobWorkerID

LEFT JOIN JobberMaster JM
    ON JM.Id = POM.JobWorkerID
   AND PM.SundryParty = 3

OUTER APPLY
(
    SELECT COUNT(1) AS DetailCount
    FROM ProductionOrderDetail POD
    WHERE POD.ProductionOrderID = POM.ProductionOrderID
      AND POD.IsActive = 1
) D

WHERE POM.IsActive = 1";

                if (!isAdmin && currentUserPartyId > 0)
                {
                    sql += " AND POM.JobWorkerID = @PartyID";
                }

                sql += " ORDER BY POM.ProductionOrderID DESC;";

                using (SqlCommand cmd =
                       new SqlCommand(sql, con))
                {
                    if (!isAdmin && currentUserPartyId > 0)
                    {
                        cmd.Parameters.AddWithValue("@PartyID", currentUserPartyId);
                    }

                    using (SqlDataReader dr =
                           cmd.ExecuteReader())
                    {
                        while (dr.Read())
                        {
                            var item =
                                new ProductionOrderListItem();

                            item.ProductionOrderID =
                                ToLong(dr["ProductionOrderID"]);

                            item.ProductionOrderNo =
                                ToStringValue(
                                    dr["ProductionOrderNo"]);

                            item.ProductionOrderDate =
                                ToDateValue(
                                    dr["ProductionOrderDate"]);

                            item.JobWorkerID =
                                ToNullableLong(
                                    dr["JobWorkerID"]);

                            item.JobWorkerName =
                                ToStringValue(
                                    dr["JobWorkerName"]);

                            item.PanaRepeat =
                                ToDecimalValue(
                                    dr["PanaRepeat"]);

                            item.JobRate =
                                ToDecimalValue(
                                    dr["JobRate"]);

                            item.Traders =
                                ToStringValue(
                                    dr["Traders"]);

                            item.TotalPcs =
                                ToDecimalValue(
                                    dr["TotalPcs"]);

                            item.TotalProductionPcs =
                                ToDecimalValue(
                                    dr["TotalProductionPcs"]);

                            item.TotalPendingPcs =
                                ToDecimalValue(
                                    dr["TotalPendingPcs"]);

                            item.TotalAmount =
                                ToDecimalValue(
                                    dr["TotalAmount"]);

                            item.Status =
                                ToIntValue(
                                    dr["Status"]);

                            item.CompanyId =
                                ToNullableLong(
                                    dr["CompanyId"]);

                            item.UserAccountId =
                                ToNullableLong(
                                    dr["UserAccountId"]);

                            item.DetailCount =
                                ToIntValue(
                                    dr["DetailCount"]);

                            list.Add(item);
                        }
                    }
                }
            }

            return list;
        }


        /*
         * ================================================================
         * PRODUCTION ORDER BY ID
         * ================================================================
         *
         * Used for:
         * Edit / View Production Order
         *
         * URL:
         * WebServiceNikunjTextile.asmx/GetProductionOrderByID
         */
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ProductionOrderByIDResponse GetProductionOrderByID(
            long ProductionOrderID)
        {
            var result =
                new ProductionOrderByIDResponse
                {
                    Success = false,
                    Message = "",
                    Master = null,
                    Details =
                        new List<ProductionOrderDetailListItem>()
                };

            if (ProductionOrderID <= 0)
            {
                result.Message =
                    "Invalid Production Order ID.";

                return result;
            }

            string connectionString =
                ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;

            using (SqlConnection con =
                   new SqlConnection(connectionString))
            {
                con.Open();

                const string masterSql = @"
SELECT TOP 1
    ProductionOrderID,
    ProductionOrderNo,
    ProductionOrderDate,
    JobWorkerID,
    JobWorkerName,
    PanaRepeat,
    JobRate,
    Traders,
    TotalPcs,
    TotalProductionPcs,
    TotalPendingPcs,
    TotalAmount,
    Status,
    CompanyId,
    UserAccountId,
    (
        SELECT COUNT(1)
        FROM ProductionOrderDetail D
        WHERE D.ProductionOrderID =
              P.ProductionOrderID
          AND D.IsActive = 1
    ) AS DetailCount
FROM ProductionOrderMaster P
WHERE ProductionOrderID = @ProductionOrderID
  AND IsActive = 1;";

                using (SqlCommand cmd =
                       new SqlCommand(
                           masterSql,
                           con))
                {
                    cmd.Parameters.Add(
                        "@ProductionOrderID",
                        SqlDbType.BigInt
                    ).Value =
                        ProductionOrderID;

                    using (SqlDataReader dr =
                           cmd.ExecuteReader())
                    {
                        if (!dr.Read())
                        {
                            result.Message =
                                "Production Order not found.";

                            return result;
                        }

                        result.Master =
                            new ProductionOrderListItem
                            {
                                ProductionOrderID =
                                    ToLong(
                                        dr["ProductionOrderID"]),

                                ProductionOrderNo =
                                    ToStringValue(
                                        dr["ProductionOrderNo"]),

                                ProductionOrderDate =
                                    ToDateValue(
                                        dr["ProductionOrderDate"]),

                                JobWorkerID =
                                    ToNullableLong(
                                        dr["JobWorkerID"]),

                                JobWorkerName =
                                    ToStringValue(
                                        dr["JobWorkerName"]),

                                PanaRepeat =
                                    ToDecimalValue(
                                        dr["PanaRepeat"]),

                                JobRate =
                                    ToDecimalValue(
                                        dr["JobRate"]),

                                Traders =
                                    ToStringValue(
                                        dr["Traders"]),

                                TotalPcs =
                                    ToDecimalValue(
                                        dr["TotalPcs"]),

                                TotalProductionPcs =
                                    ToDecimalValue(
                                        dr["TotalProductionPcs"]),

                                TotalPendingPcs =
                                    ToDecimalValue(
                                        dr["TotalPendingPcs"]),

                                TotalShortPcs =
                                    HasColumn(dr, "TotalShortPCS")
                                        ? ToDecimalValue(dr["TotalShortPCS"])
                                        : 0m,

                                TotalAmount =
                                    ToDecimalValue(
                                        dr["TotalAmount"]),

                                Status =
                                    ToIntValue(
                                        dr["Status"]),

                                CompanyId =
                                    ToNullableLong(
                                        dr["CompanyId"]),

                                UserAccountId =
                                    ToNullableLong(
                                        dr["UserAccountId"]),

                                DetailCount =
                                    ToIntValue(
                                        dr["DetailCount"])
                            };
                    }
                }


                const string detailSql = @"
SELECT *
FROM ProductionOrderDetail
WHERE ProductionOrderID = @ProductionOrderID
  AND IsActive = 1
ORDER BY ProductionOrderDetailID ASC;";

                using (SqlCommand cmd =
                       new SqlCommand(
                           detailSql,
                           con))
                {
                    cmd.Parameters.Add(
                        "@ProductionOrderID",
                        SqlDbType.BigInt
                    ).Value =
                        ProductionOrderID;

                    using (SqlDataReader dr =
                           cmd.ExecuteReader())
                    {
                        while (dr.Read())
                        {
                            result.Details.Add(
                                new ProductionOrderDetailListItem
                                {
                                    ProductionOrderDetailID =
                                        ToLong(
                                            dr["ProductionOrderDetailID"]),

                                    ProductionOrderID =
                                        ToLong(
                                            dr["ProductionOrderID"]),

                                    SalesOrderID =
                                        ToNullableLong(
                                            dr["SalesOrderID"]),

                                    SalesOrderDetailID =
                                        ToNullableLong(
                                            dr["SalesOrderDetailID"]),

                                    SubDetailID =
                                        ToNullableLong(
                                            dr["SubDetailID"]),

                                    SalesOrderNo =
                                        ToStringValue(
                                            dr["SalesOrderNo"]),

                                    SlipNo =
                                        ToStringValue(
                                            dr["SlipNo"]),

                                    Barcode =
                                        ToStringValue(
                                            dr["Barcode"]),

                                    OrderDate =
                                        ToDateString(
                                            dr["OrderDate"]),

                                    PartyID =
                                        ToNullableLong(
                                            dr["PartyID"]),

                                    PartyName =
                                        ToStringValue(
                                            dr["PartyName"]),

                                    DesignEntryFormID =
                                        ToNullableLong(
                                            dr["DesignEntryFormID"]),

                                    DesignNo =
                                        ToStringValue(
                                            dr["DesignNo"]),

                                    ColourMatchingID =
                                        ToNullableLong(
                                            dr["ColourMatchingID"]),

                                    ColourMatchingName =
                                        ToStringValue(
                                            dr["ColourMatchingName"]),

                                    WarpQuality =
                                        ToStringValue(
                                            dr["WarpQuality"]),

                                    WeftQuality =
                                        ToStringValue(
                                            dr["WeftQuality"]),

                                    PCS =
                                        ToDecimalValue(
                                            dr["PCS"]),

                                    ProductionPCS =
                                        ToDecimalValue(
                                            dr["ProductionPCS"]),

                                    PendingPCS =
                                        ToDecimalValue(
                                            dr["PendingPCS"]),

                                    ShortPCS =
                                        HasColumn(dr, "ShortPCS")
                                            ? ToDecimalValue(dr["ShortPCS"])
                                            : 0m,

                                    IsClosed =
                                        HasColumn(dr, "ShortPCS") && ToDecimalValue(dr["ShortPCS"]) > 0m,

                                    SalesRate =
                                        ToDecimalValue(
                                            dr["SalesRate"]),

                                    JobRate =
                                        ToDecimalValue(
                                            dr["JobRate"]),

                                    Amount =
                                        ToDecimalValue(
                                            dr["Amount"]),

                                    Rpm =
                                        HasColumn(dr, "Rpm") ? ToDecimalValue(dr["Rpm"]) : 0m,

                                    PanaRepeat =
                                        HasColumn(dr, "PanaRepeat") ? ToDecimalValue(dr["PanaRepeat"]) : 0m,

                                    PanaWidth =
                                        HasColumn(dr, "PanaWidth") ? ToDecimalValue(dr["PanaWidth"]) : 0m,

                                    NoOfMachines =
                                        HasColumn(dr, "NoOfMachines") ? ToDecimalValue(dr["NoOfMachines"]) : 0m,

                                    RepPCS =
                                        HasColumn(dr, "RepPCS") ? ToDecimalValue(dr["RepPCS"]) : 0m,

                                    RepRate =
                                        HasColumn(dr, "RepRate") ? ToDecimalValue(dr["RepRate"]) : 0m,

                                    RepAmt =
                                        HasColumn(dr, "RepAmt") ? ToDecimalValue(dr["RepAmt"]) : 0m,

                                    JobberAccept =
                                        HasColumn(dr, "JobberAccept") ? ToIntValue(dr["JobberAccept"]) : 0,

                                    CompanyId =
                                        ToNullableLong(
                                            dr["CompanyId"]),

                                    UserAccountId =
                                        ToNullableLong(
                                            dr["UserAccountId"])
                                }
                            );
                        }
                    }
                }
            }

            result.Success = true;
            result.Message =
                "Production Order loaded successfully.";

            return result;
        }


        /*
         * ================================================================
         * PRODUCTION ORDER BY ENCRYPTED ID
         * ================================================================
         *
         * Used by:
         * ProductionSleep.cshtml
         *
         * URL:
         * /ProductionSleep?ProductionOrderID=<ENCRYPTED>
         *
         * The existing getEncryptID WebMethod returns the encrypted ID.
         * This method decrypts that value on the server and then uses the
         * existing GetProductionOrderByID method.
         *
         * The browser therefore never needs to put the numeric ID in the
         * URL or send the numeric ID directly for the edit/view page.
         */
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ProductionOrderByIDResponse GetProductionOrderByEncryptedID(
            string EncryptedID)
        {
            var result =
                new ProductionOrderByIDResponse
                {
                    Success = false,
                    Message = "",
                    Master = null,
                    Details =
                        new List<ProductionOrderDetailListItem>()
                };

            if (string.IsNullOrWhiteSpace(EncryptedID))
            {
                result.Message =
                    "Encrypted Production Order ID is required.";

                return result;
            }

            try
            {
                /*
                 * IMPORTANT:
                 *
                 * ProductionOrderList uses the existing project
                 * getEncryptID WebMethod. That value is NOT plain Base64.
                 *
                 * Example URL:
                 *
                 * ProductionOrderID=
                 * rq5q6i50XyKd...Vw%253d%253d
                 *
                 * Browser URLSearchParams may already decode one layer.
                 * Still remove any remaining URL encoding here so both
                 * %3D and %253D style values are supported.
                 */
                string encryptedValue =
                    EncryptedID.Trim();

                for (int i = 0; i < 3; i++)
                {
                    string decoded =
                        System.Web.HttpUtility.UrlDecode(
                            encryptedValue
                        );

                    if (decoded == encryptedValue)
                    {
                        break;
                    }

                    encryptedValue = decoded;
                }

                if (string.IsNullOrWhiteSpace(encryptedValue))
                {
                    result.Message =
                        "Encrypted Production Order ID is required.";

                    return result;
                }

                long directID;
                if (long.TryParse(encryptedValue, out directID) && directID > 0)
                {
                    return GetProductionOrderByID(directID);
                }

                string decryptedValue = Decrypt(encryptedValue);

                if (string.IsNullOrWhiteSpace(decryptedValue))
                {
                    result.Message =
                        "Invalid encrypted Production Order ID.";

                    return result;
                }

                decryptedValue =
                    decryptedValue.Trim();

                /*
                 * Some existing encrypted values may contain:
                 *
                 * 17|Edit
                 * 17|View
                 *
                 * In that case the first part is the ProductionOrderID.
                 */
                if (decryptedValue.Contains("|"))
                {
                    decryptedValue =
                        decryptedValue.Split('|')[0];
                }

                long productionOrderID;

                if (!long.TryParse(
                        decryptedValue,
                        out productionOrderID) ||
                    productionOrderID <= 0)
                {
                    result.Message =
                        "Invalid encrypted Production Order ID.";

                    return result;
                }

                /*
                 * Reuse the existing DB binding method.
                 */
                return GetProductionOrderByID(
                    productionOrderID
                );
            }
            catch (Exception ex)
            {
                /*
                 * Do not expose Base64/FormatException-specific errors.
                 * Return one clean message to the frontend.
                 */
                result.Message =
                    string.IsNullOrWhiteSpace(ex.Message)
                        ? "Invalid encrypted Production Order ID."
                        : ex.Message;

                return result;
            }
        }

        /*
         * ================================================================
         * DELETE PRODUCTION ORDER (PROTECTED SOFT-DELETE)
         * ================================================================
         *
         * Soft delete:
         * Sets IsActive = 0 on Master, Detail, and SubDetail.
         * Blocked if active machine allotments or downstream transactions exist.
         * Protected by transaction-bound application lock sp_getapplock.
         * Atomically logs to AuditLog inside the same transaction.
         */
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ProductionOrderDeleteResponse DeleteProductionOrder(long ProductionOrderID)
        {
            var result = new ProductionOrderDeleteResponse
            {
                Success = false,
                Message = "",
                ProductionOrderID = ProductionOrderID
            };

            if (ProductionOrderID <= 0)
            {
                result.Message = "Invalid Production Order ID.";
                return result;
            }

            string connectionString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(connectionString))
            {
                con.Open();

                using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.ReadCommitted))
                {
                    try
                    {
                        // 1. Acquire transaction-bound exclusive application lock
                        ProductionOrderLockHelper.AcquireOrderLock(con, tran, ProductionOrderID);

                        // 2. Check master existence and current active status
                        string prodOrderNo = "";
                        bool isMasterActive = false;
                        const string checkMasterSql = @"
                            SELECT ProductionOrderNo, IsActive
                            FROM dbo.ProductionOrderMaster WITH (UPDLOCK, HOLDLOCK)
                            WHERE ProductionOrderID = @ProductionOrderID;";

                        using (SqlCommand cmdMaster = new SqlCommand(checkMasterSql, con, tran))
                        {
                            cmdMaster.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = ProductionOrderID;
                            using (SqlDataReader dr = cmdMaster.ExecuteReader())
                            {
                                if (dr.Read())
                                {
                                    prodOrderNo = dr["ProductionOrderNo"] != DBNull.Value ? dr["ProductionOrderNo"].ToString().Trim() : "";
                                    isMasterActive = dr["IsActive"] != DBNull.Value && Convert.ToBoolean(dr["IsActive"]);
                                }
                                else
                                {
                                    tran.Rollback();
                                    result.Message = "Production Order not found or already deleted.";
                                    return result;
                                }
                            }
                        }

                        if (!isMasterActive)
                        {
                            tran.Rollback();
                            result.Message = "Production Order is already inactive.";
                            return result;
                        }

                        // 3. Check for active machine allotments in ProductionOrderSubDetail
                        int activeSubCount = 0;
                        const string checkActiveSubSql = @"
                            SELECT COUNT(1)
                            FROM dbo.ProductionOrderSubDetail WITH (UPDLOCK, HOLDLOCK)
                            WHERE (ProductionOrderID = @ProductionOrderID 
                                   OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID))
                              AND ISNULL(IsActive, 1) = 1;";

                        using (SqlCommand cmdSub = new SqlCommand(checkActiveSubSql, con, tran))
                        {
                            cmdSub.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = ProductionOrderID;
                            activeSubCount = Convert.ToInt32(cmdSub.ExecuteScalar());
                        }

                        if (activeSubCount > 0)
                        {
                            tran.Rollback();
                            result.Success = false;
                            result.Message = string.Format("Cannot delete Production Order '{0}' because it has {1} active machine allotment(s) in ProductionOrderSubDetail.", prodOrderNo, activeSubCount);
                            return result;
                        }

                        // 4. Check downstream dependencies across all 3 paths in all 5 downstream tables
                        int ptdCount = 0;
                        int pthCount = 0;
                        int pdCount = 0;
                        int pcdCount = 0;
                        int pslCount = 0;

                        const string checkDownstreamSql = @"
                            SELECT 
                                (SELECT COUNT(1) FROM dbo.ProcessTransactionDetail 
                                 WHERE ProductionOrderID = @ProductionOrderID 
                                    OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID)
                                    OR ProductionOrderSubDetailID IN (SELECT ProductionOrderSubDetailID FROM dbo.ProductionOrderSubDetail WHERE ProductionOrderID = @ProductionOrderID OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID))) AS PTD_Count,
                                (SELECT COUNT(1) FROM dbo.ProcessTransactionHistory 
                                 WHERE ProductionOrderID = @ProductionOrderID 
                                    OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID)
                                    OR ProductionOrderSubDetailID IN (SELECT ProductionOrderSubDetailID FROM dbo.ProductionOrderSubDetail WHERE ProductionOrderID = @ProductionOrderID OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID))) AS PTH_Count,
                                (SELECT COUNT(1) FROM ProductionData 
                                 WHERE ProductionOrderID = @ProductionOrderID 
                                    OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID)
                                    OR ProductionOrderSubDetailID IN (SELECT ProductionOrderSubDetailID FROM dbo.ProductionOrderSubDetail WHERE ProductionOrderID = @ProductionOrderID OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID))) AS PD_Count,
                                (SELECT COUNT(1) FROM ProcessChallanDetail 
                                 WHERE ProductionOrderID = @ProductionOrderID 
                                    OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID)
                                    OR ProductionOrderSubDetailID IN (SELECT ProductionOrderSubDetailID FROM dbo.ProductionOrderSubDetail WHERE ProductionOrderID = @ProductionOrderID OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID))) AS PCD_Count,
                                (SELECT COUNT(1) FROM ProcessStockLedger 
                                 WHERE ProductionOrderID = @ProductionOrderID 
                                    OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID)
                                    OR ProductionOrderSubDetailID IN (SELECT ProductionOrderSubDetailID FROM dbo.ProductionOrderSubDetail WHERE ProductionOrderID = @ProductionOrderID OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM dbo.ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID))) AS PSL_Count;";

                        using (SqlCommand cmdDown = new SqlCommand(checkDownstreamSql, con, tran))
                        {
                            cmdDown.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = ProductionOrderID;
                            using (SqlDataReader drDown = cmdDown.ExecuteReader())
                            {
                                if (drDown.Read())
                                {
                                    ptdCount = Convert.ToInt32(drDown["PTD_Count"]);
                                    pthCount = Convert.ToInt32(drDown["PTH_Count"]);
                                    pdCount = Convert.ToInt32(drDown["PD_Count"]);
                                    pcdCount = Convert.ToInt32(drDown["PCD_Count"]);
                                    pslCount = Convert.ToInt32(drDown["PSL_Count"]);
                                }
                            }
                        }

                        int totalDownstream = ptdCount + pthCount + pdCount + pcdCount + pslCount;
                        if (totalDownstream > 0)
                        {
                            tran.Rollback();
                            List<string> depReasons = new List<string>();
                            if (ptdCount > 0) depReasons.Add(string.Format("{0} Process Transaction Detail(s)", ptdCount));
                            if (pthCount > 0) depReasons.Add(string.Format("{0} Process Transaction History record(s)", pthCount));
                            if (pdCount > 0) depReasons.Add(string.Format("{0} Production Data entry/entries", pdCount));
                            if (pcdCount > 0) depReasons.Add(string.Format("{0} Process Challan Detail(s)", pcdCount));
                            if (pslCount > 0) depReasons.Add(string.Format("{0} Process Stock Ledger record(s)", pslCount));

                            result.Success = false;
                            result.Message = string.Format("Cannot delete Production Order '{0}' because dependent records exist: {1}.", prodOrderNo, string.Join(", ", depReasons));
                            return result;
                        }

                        // 5. Soft-deactivate Details
                        const string softDeleteDetailSql = @"
                            UPDATE dbo.ProductionOrderDetail 
                            SET IsActive = 0, DateandTime = GETDATE()
                            WHERE ProductionOrderID = @ProductionOrderID AND IsActive = 1;";

                        using (SqlCommand cmdSoftDetail = new SqlCommand(softDeleteDetailSql, con, tran))
                        {
                            cmdSoftDetail.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = ProductionOrderID;
                            cmdSoftDetail.ExecuteNonQuery();
                        }

                        // 6. Soft-deactivate Master
                        const string softDeleteMasterSql = @"
                            UPDATE dbo.ProductionOrderMaster 
                            SET IsActive = 0, DateandTime = GETDATE()
                            WHERE ProductionOrderID = @ProductionOrderID AND IsActive = 1;";

                        int affectedMaster = 0;
                        using (SqlCommand cmdSoftMaster = new SqlCommand(softDeleteMasterSql, con, tran))
                        {
                            cmdSoftMaster.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = ProductionOrderID;
                            affectedMaster = cmdSoftMaster.ExecuteNonQuery();
                        }

                        if (affectedMaster <= 0)
                        {
                            tran.Rollback();
                            result.Message = "Production Order could not be deactivated.";
                            return result;
                        }

                        // 8. Transaction-bound AuditLog
                        AuditLogHelper.LogTransactional(
                            conn: con,
                            tran: tran,
                            module: "Production Order",
                            action: "DELETE",
                            tableName: "ProductionOrderMaster",
                            recordId: ProductionOrderID.ToString(),
                            description: string.Format("Soft-deleted Production Order #{0} (ID: {1})", prodOrderNo, ProductionOrderID)
                        );

                        tran.Commit();

                        result.Success = true;
                        result.Message = "Production Order deleted successfully.";
                        return result;
                    }
                    catch (Exception ex)
                    {
                        try
                        {
                            tran.Rollback();
                        }
                        catch { }

                        try
                        {
                            AuditLogHelper.LogError("Production Order", "DeleteProductionOrder", ex, "ProductionOrderID=" + ProductionOrderID);
                        }
                        catch { }

                        result.Success = false;
                        result.Message = "Error deleting Production Order: " + ex.Message;
                        return result;
                    }
                }
            }
        }


        /*
         * ================================================================
         * DEFAULT COMPANY - LIST
         * ================================================================
         */
        private static long? GetDefaultCompanyIdForList(
            SqlConnection con)
        {
            const string sql = @"
SELECT TOP 1 CompanyId
FROM CompanyMaster
WHERE is_default = 1
ORDER BY CompanyId;";

            using (SqlCommand cmd =
                   new SqlCommand(sql, con))
            {
                object value =
                    cmd.ExecuteScalar();

                if (value != null &&
                    value != DBNull.Value)
                {
                    return Convert.ToInt64(value);
                }
            }

            return null;
        }


        /*
         * ================================================================
         * SAFE CONVERSION HELPERS
         * ================================================================
         */
        private static string ToStringValue(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return "";
            }

            return Convert.ToString(value).Trim();
        }

        private static long ToLong(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return 0;
            }

            return Convert.ToInt64(value);
        }

        private static long? ToNullableLong(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return null;
            }

            return Convert.ToInt64(value);
        }

        private static int ToIntValue(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return 0;
            }

            return Convert.ToInt32(value);
        }

        private static decimal ToDecimalValue(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return 0m;
            }

            return Convert.ToDecimal(value);
        }

        private static DateTime ToDateValue(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return DateTime.MinValue;
            }

            return Convert.ToDateTime(value);
        }

        private static string ToDateString(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return "";
            }

            return Convert
                .ToDateTime(value)
                .ToString("yyyy-MM-dd");
        }



        /// <summary>
        /// SaveProductionOrder
        /// </summary>
        /// <param name="request"></param>
        /// <returns></returns>
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ProductionOrderSaveResponse SaveProductionOrder(ProductionOrderRequest request)
        {
            var result = new ProductionOrderSaveResponse
            {
                Success = false,
                ProductionOrderID = 0,
                InsertedDetails = 0,
                UpdatedDetails = 0,
                DeletedDetails = 0
            };

            if (request == null)
            {
                result.Message = "Production Order data is required.";
                return result;
            }

            if (request.listProductionOrderDetail == null ||
                request.listProductionOrderDetail.Count == 0)
            {
                result.Message = "Please select at least one Production Order detail.";
                return result;
            }

            DateTime productionDate;

            if (!TryParseDate(request.ProductionOrderDate, out productionDate))
            {
                result.Message = "Production Order Date is invalid.";
                return result;
            }

            string connectionString = ConfigurationManager
                .ConnectionStrings["sqlconnstr"]
                .ConnectionString;

            using (SqlConnection con = new SqlConnection(connectionString))
            {
                con.Open();

                using (SqlTransaction tran =
                       con.BeginTransaction(IsolationLevel.ReadCommitted))
                {
                    try
                    {
                        long? currentUserAccountId = GetCurrentUserAccountId();
                        long? currentCompanyId = GetDefaultCompanyId(con, tran);

                        if (!currentUserAccountId.HasValue)
                        {
                            tran.Rollback();
                            result.Message ="UserAccountId could not be found from UserIDs cookie.";
                            return result;
                        }

                        if (!currentCompanyId.HasValue)
                        {
                            tran.Rollback();
                            result.Message = "Default CompanyId could not be found from CompanyMaster.";
                            return result;
                        }

                        long productionOrderID = request.ProductionOrderID;
                        bool isInsert = productionOrderID <= 0;
                        decimal totalPcs = 0m;
                        decimal totalProductionPcs = 0m;
                        decimal totalPendingPcs = 0m;
                        decimal totalAmount = 0m;

                        // NORMALIZE DETAILS AND CALCULATE TOTALS
                        decimal totalShortPcs = 0m;
                        foreach (ProductionOrderDetailRequest d
                                 in request.listProductionOrderDetail)
                        {
                            if (d == null)
                                continue;

                            d.PCS = Math.Max(0m, d.PCS);

                            d.ProductionPCS = Math.Max(
                                0m,
                                Math.Min(d.ProductionPCS, d.PCS)
                            );

                            if (d.IsClosed && d.ProductionPCS < d.PCS)
                            {
                                d.ShortPCS = Math.Max(0m, d.PCS - d.ProductionPCS);
                                d.PendingPCS = 0m;
                            }
                            else
                            {
                                d.ShortPCS = Math.Max(0m, d.ShortPCS);
                                if (d.ShortPCS > 0m)
                                {
                                    d.PendingPCS = Math.Max(0m, d.PCS - d.ProductionPCS - d.ShortPCS);
                                }
                                else
                                {
                                    d.PendingPCS = Math.Max(0m, d.PCS - d.ProductionPCS);
                                }
                            }

                            d.JobRate = request.JobRate;

                            d.Amount = Math.Round(
                                d.ProductionPCS * request.JobRate,
                                2,
                                MidpointRounding.AwayFromZero
                            );

                            totalPcs += d.PCS;
                            totalProductionPcs += d.ProductionPCS;
                            totalPendingPcs += d.PendingPCS;
                            totalShortPcs += d.ShortPCS;
                            totalAmount += d.Amount;
                        }

                        if (totalProductionPcs <= 0m)
                        {
                            tran.Rollback();
                            result.Message = "Production PCS must be greater than 0.";
                            return result;
                        }

                        // PRODUCTION ORDER NUMBER
                        string productionOrderNo =
                            (request.ProductionOrderNo ?? "").Trim();

                        if (productionOrderNo == "")
                        {
                            productionOrderNo =
                                GetNextProductionOrderNo(con, tran);
                        }

                        // CHECK OPTIONAL COLUMNS
                        bool hasRpmM = DoesColumnExist(
                            con, tran, "ProductionOrderMaster", "Rpm");

                        bool hasPanaWidthM = DoesColumnExist(
                            con, tran, "ProductionOrderMaster", "PanaWidth");

                        bool hasNoOfMachinesM = DoesColumnExist(
                            con, tran, "ProductionOrderMaster", "NoOfMachines");

                        bool hasRpmD = DoesColumnExist(
                            con, tran, "ProductionOrderDetail", "Rpm");

                        bool hasPanaRepeatD = DoesColumnExist(
                            con, tran, "ProductionOrderDetail", "PanaRepeat");

                        bool hasPanaWidthD = DoesColumnExist(
                            con, tran, "ProductionOrderDetail", "PanaWidth");

                        bool hasNoOfMachinesD = DoesColumnExist(
                            con, tran, "ProductionOrderDetail", "NoOfMachines");

                        bool hasRepPcsD = DoesColumnExist(
                            con, tran, "ProductionOrderDetail", "RepPCS");

                        bool hasRepRateD = DoesColumnExist(
                            con, tran, "ProductionOrderDetail", "RepRate");

                        bool hasRepAmtD = DoesColumnExist(
                            con, tran, "ProductionOrderDetail", "RepAmt");

                        bool hasJobberAcceptD = DoesColumnExist(
                            con, tran, "ProductionOrderDetail", "JobberAccept");

                        bool hasShortPcsD = DoesColumnExist(
                            con, tran, "ProductionOrderDetail", "ShortPCS");

                        // INSERT / UPDATE MASTER
                        if (isInsert)
                        {
                            string insertMasterSql = @"
INSERT INTO ProductionOrderMaster
(
    ProductionOrderNo,
    ProductionOrderDate,
    JobWorkerID,
    JobWorkerName,
    PanaRepeat,
    " + (hasRpmM ? "Rpm, " : "") + @"
    " + (hasPanaWidthM ? "PanaWidth, " : "") + @"
    " + (hasNoOfMachinesM ? "NoOfMachines, " : "") + @"
    JobRate,
    Traders,
    TotalPcs,
    TotalProductionPcs,
    TotalPendingPcs,
    TotalAmount,
    Status,
    CompanyId,
    UserAccountId,
    DateandTime,
    IsActive
)
VALUES
(
    @ProductionOrderNo,
    @ProductionOrderDate,
    @JobWorkerID,
    @JobWorkerName,
    @PanaRepeat,
    " + (hasRpmM ? "@Rpm, " : "") + @"
    " + (hasPanaWidthM ? "@PanaWidth, " : "") + @"
    " + (hasNoOfMachinesM ? "@NoOfMachines, " : "") + @"
    @JobRate,
    @Traders,
    @TotalPcs,
    @TotalProductionPcs,
    @TotalPendingPcs,
    @TotalAmount,
    @Status,
    @CompanyId,
    @UserAccountId,
    GETDATE(),
    1
);

SELECT CAST(SCOPE_IDENTITY() AS BIGINT);";

                            using (SqlCommand cmd =
                                   new SqlCommand(insertMasterSql, con, tran))
                            {
                                AddMasterParameters(
                                    cmd,
                                    request,
                                    productionOrderNo,
                                    productionDate,
                                    totalPcs,
                                    totalProductionPcs,
                                    totalPendingPcs,
                                    totalAmount,
                                    currentCompanyId,
                                    currentUserAccountId
                                );

                                productionOrderID =
                                    Convert.ToInt64(cmd.ExecuteScalar());
                            }

                            if (productionOrderID <= 0)
                            {
                                throw new Exception(
                                    "Production Order Master could not be inserted.");
                            }
                        }
                        else
                        {
                            const string checkMasterSql = @"
SELECT COUNT(1)
FROM ProductionOrderMaster
WHERE ProductionOrderID = @ProductionOrderID
  AND IsActive = 1;";

                            using (SqlCommand check =
                                   new SqlCommand(checkMasterSql, con, tran))
                            {
                                check.Parameters.Add(
                                    "@ProductionOrderID",
                                    SqlDbType.BigInt
                                ).Value = productionOrderID;

                                if (Convert.ToInt32(check.ExecuteScalar()) == 0)
                                {
                                    tran.Rollback();
                                    result.Message =
                                        "Production Order not found or inactive.";
                                    return result;
                                }
                            }

                            string updateMasterSql = @"
UPDATE ProductionOrderMaster
SET
    ProductionOrderNo = @ProductionOrderNo,
    ProductionOrderDate = @ProductionOrderDate,
    JobWorkerID = @JobWorkerID,
    JobWorkerName = @JobWorkerName,
    PanaRepeat = @PanaRepeat,
    " + (hasRpmM ? "Rpm = @Rpm, " : "") + @"
    " + (hasPanaWidthM ? "PanaWidth = @PanaWidth, " : "") + @"
    " + (hasNoOfMachinesM ? "NoOfMachines = @NoOfMachines, " : "") + @"
    JobRate = @JobRate,
    Traders = @Traders,
    TotalPcs = @TotalPcs,
    TotalProductionPcs = @TotalProductionPcs,
    TotalPendingPcs = @TotalPendingPcs,
    TotalAmount = @TotalAmount,
    Status = @Status,
    CompanyId = @CompanyId,
    UserAccountId = @UserAccountId,
    DateandTime = GETDATE()
WHERE ProductionOrderID = @ProductionOrderID
  AND IsActive = 1;";

                            using (SqlCommand cmd =
                                   new SqlCommand(updateMasterSql, con, tran))
                            {
                                AddMasterParameters(
                                    cmd,
                                    request,
                                    productionOrderNo,
                                    productionDate,
                                    totalPcs,
                                    totalProductionPcs,
                                    totalPendingPcs,
                                    totalAmount,
                                    currentCompanyId,
                                    currentUserAccountId
                                );

                                cmd.Parameters.Add(
                                    "@ProductionOrderID",
                                    SqlDbType.BigInt
                                ).Value = productionOrderID;

                                if (cmd.ExecuteNonQuery() <= 0)
                                {
                                    throw new Exception(
                                        "Production Order Master update failed.");
                                }
                            }
                        }

                        // DETAILS INSERT / UPDATE
                        var incomingDetailIds = new HashSet<long>();

                        foreach (ProductionOrderDetailRequest d
                                 in request.listProductionOrderDetail)
                        {
                            if (d == null)
                                continue;

                            ResolveSalesOrderValues(con, tran, d);

                            long detailID = d.ProductionOrderDetailID;

                            // RECOVER EXISTING DETAIL ID ONLY DURING EDIT
                            if (detailID <= 0 &&
                                !isInsert &&
                                d.SalesOrderDetailID.HasValue &&
                                d.SalesOrderDetailID.Value > 0)
                            {
                                detailID = GetExistingProductionOrderDetailID(
                                    con,
                                    tran,
                                    productionOrderID,
                                    d.SalesOrderDetailID.Value,
                                    d.SubDetailID,
                                    d.ColourMatchingID
                                );

                                if (detailID > 0)
                                {
                                    d.ProductionOrderDetailID = detailID;
                                }
                            }

                            /*
                             * IMPORTANT:
                             * Existing SlipNo lookup is allowed only in EDIT mode.
                             * For a NEW Production Order, always insert a new detail.
                             */
                            if (detailID <= 0 &&
                                !isInsert &&
                                !string.IsNullOrWhiteSpace(d.SlipNo) &&
                                currentCompanyId.HasValue)
                            {
                                long slipDetailID =
                                    GetProductionOrderDetailIDByCompanyAndSlipNo(
                                        con,
                                        tran,
                                        currentCompanyId.Value,
                                        d.SlipNo
                                    );

                                if (slipDetailID > 0)
                                {
                                    detailID = slipDetailID;
                                    d.ProductionOrderDetailID = detailID;
                                }
                            }

                            // PRESERVE EXISTING SLIP NO DURING UPDATE
                            if (detailID > 0)
                            {
                                string existingSlipNo = GetExistingSlipNo(
                                    con,
                                    tran,
                                    detailID,
                                    productionOrderID
                                );

                                if (!string.IsNullOrWhiteSpace(existingSlipNo))
                                {
                                    d.SlipNo = existingSlipNo;
                                }
                            }

                            // BARCODE HANDLING
                            if (detailID > 0)
                            {
                                string existingBarcode = GetExistingBarcode(
                                    con,
                                    tran,
                                    detailID,
                                    productionOrderID
                                );

                                if (!string.IsNullOrWhiteSpace(existingBarcode))
                                {
                                    d.Barcode = existingBarcode;
                                }
                                else
                                {
                                    d.Barcode = GenerateUniqueBarcode(con, tran);
                                }
                            }
                            else
                            {
                                d.Barcode = GenerateUniqueBarcode(con, tran);
                            }

                            // PREVENT PRODUCTION PCS CHANGE WHEN MACHINE SUBDETAIL EXISTS
                            if (!isInsert && detailID > 0)
                            {
                                const string checkProductionSql = @"
                                    SELECT
                                        ISNULL(D.ProductionPCS, 0) AS ExistingProductionPCS,
                                        CASE WHEN EXISTS
                                        (
                                            SELECT 1
                                            FROM dbo.ProductionOrderSubDetail S WITH (UPDLOCK, HOLDLOCK)
                                            WHERE S.ProductionOrderDetailID = D.ProductionOrderDetailID
                                              AND S.ProductionOrderID = D.ProductionOrderID
                                              AND ISNULL(S.IsActive, 1) = 1
                                        )
                                        THEN 1 ELSE 0 END AS HasSubDetail
                                    FROM dbo.ProductionOrderDetail D WITH (UPDLOCK, HOLDLOCK)
                                    WHERE D.ProductionOrderDetailID = @ProductionOrderDetailID
                                      AND D.ProductionOrderID = @ProductionOrderID
                                      AND D.IsActive = 1;";

                                using (SqlCommand checkProduction =
                                       new SqlCommand(checkProductionSql, con, tran))
                                {
                                    checkProduction.Parameters.Add("@ProductionOrderDetailID", SqlDbType.BigInt)
                                        .Value = detailID;

                                    checkProduction.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt)
                                        .Value = productionOrderID;

                                    using (SqlDataReader dr = checkProduction.ExecuteReader())
                                    {
                                        if (dr.Read())
                                        {
                                            decimal existingProductionPCS =
                                                Convert.ToDecimal(dr["ExistingProductionPCS"]);

                                            bool hasSubDetail =
                                                Convert.ToInt32(dr["HasSubDetail"]) == 1;

                                            if (hasSubDetail &&
                                                existingProductionPCS != d.ProductionPCS)
                                            {
                                                dr.Close();
                                                tran.Rollback();

                                                result.Success = false;
                                                result.Message =
                                                    "Production PCS cannot be changed because machine production details already exist.";

                                                return result;
                                            }
                                        }
                                    }
                                }
                            }

                            // UPDATE EXISTING DETAIL
                            if (detailID > 0)
                            {
                                const string checkDetailSql = @"
SELECT COUNT(1)
FROM ProductionOrderDetail
WHERE ProductionOrderDetailID = @ProductionOrderDetailID
  AND ProductionOrderID = @ProductionOrderID
  AND IsActive = 1;";

                                using (SqlCommand check =
                                       new SqlCommand(checkDetailSql, con, tran))
                                {
                                    check.Parameters.Add(
                                        "@ProductionOrderDetailID",
                                        SqlDbType.BigInt
                                    ).Value = detailID;

                                    check.Parameters.Add(
                                        "@ProductionOrderID",
                                        SqlDbType.BigInt
                                    ).Value = productionOrderID;

                                    if (Convert.ToInt32(check.ExecuteScalar()) > 0)
                                    {
                                        string updateDetailSql = @"
UPDATE ProductionOrderDetail
SET
    ProductionOrderID = @ProductionOrderID,
    SalesOrderID = @SalesOrderID,
    SalesOrderDetailID = @SalesOrderDetailID,
    SubDetailID = @SubDetailID,
    SalesOrderNo = @SalesOrderNo,
    OrderDate = @OrderDate,
    PartyID = @PartyID,
    PartyName = @PartyName,
    SlipNo = @SlipNo,
    Barcode = @Barcode,
    DesignEntryFormID = @DesignEntryFormID,
    DesignNo = @DesignNo,
    ColourMatchingID = @ColourMatchingID,
    ColourMatchingName = @ColourMatchingName,
    WarpQuality = @WarpQuality,
    WeftQuality = @WeftQuality,
    PCS = @PCS,
    ProductionPCS = @ProductionPCS,
    PendingPCS = @PendingPCS,
    " + (hasShortPcsD ? "ShortPCS = @ShortPCS, " : "") + @"
    SalesRate = @SalesRate,
    JobRate = @JobRate,
    Amount = @Amount,
    " + (hasRpmD ? "Rpm = @Rpm, " : "") + @"
    " + (hasPanaRepeatD ? "PanaRepeat = @PanaRepeat, " : "") + @"
    " + (hasPanaWidthD ? "PanaWidth = @PanaWidth, " : "") + @"
    " + (hasNoOfMachinesD ? "NoOfMachines = @NoOfMachines, " : "") + @"
    " + (hasRepPcsD ? "RepPCS = @RepPCS, " : "") + @"
    " + (hasRepRateD ? "RepRate = @RepRate, " : "") + @"
    " + (hasRepAmtD ? "RepAmt = @RepAmt, " : "") + @"
    " + (hasJobberAcceptD ? "JobberAccept = @JobberAccept, " : "") + @"
    CompanyId = @CompanyId,
    UserAccountId = @UserAccountId,
    DateandTime = GETDATE(),
    IsActive = 1
WHERE ProductionOrderDetailID = @ProductionOrderDetailID
  AND ProductionOrderID = @ProductionOrderID
  AND IsActive = 1;";

                                        using (SqlCommand cmd =
                                               new SqlCommand(updateDetailSql, con, tran))
                                        {
                                            AddDetailParameters(
                                                cmd,
                                                d,
                                                productionOrderID,
                                                request,
                                                currentCompanyId,
                                                currentUserAccountId
                                            );

                                            cmd.Parameters.Add(
                                                "@ProductionOrderDetailID",
                                                SqlDbType.BigInt
                                            ).Value = detailID;

                                            int affectedRows = cmd.ExecuteNonQuery();

                                            if (affectedRows > 0)
                                            {
                                                incomingDetailIds.Add(detailID);
                                                result.UpdatedDetails++;
                                                continue;
                                            }
                                        }
                                    }
                                }
                            }

                            // INSERT NEW DETAIL
                            if (detailID <= 0)
                            {
                                if (string.IsNullOrWhiteSpace(d.SlipNo))
                                {
                                    tran.Rollback();
                                    result.Message =
                                        "Slip No is required for Production Order detail.";
                                    return result;
                                }

                                decimal remainingPending =
                                    GetRemainingPendingPcsForSlip(
                                        con,
                                        tran,
                                        d.SubDetailID,
                                        d.SalesOrderDetailID,
                                        d.SlipNo,
                                        currentCompanyId,
                                        productionOrderID
                                    );

                                if (remainingPending <= 0)
                                {
                                    tran.Rollback();
                                    result.Message =
                                        "Slip No " + d.SlipNo +
                                        " has no pending pcs remaining (0 pending). " +
                                        "Cannot create further production orders.";
                                    return result;
                                }
                            }

                            string insertDetailSql = @"
INSERT INTO ProductionOrderDetail
(
    ProductionOrderID,
    SalesOrderID,
    SalesOrderDetailID,
    SubDetailID,
    SalesOrderNo,
    OrderDate,
    PartyID,
    PartyName,
    SlipNo,
    Barcode,
    DesignEntryFormID,
    DesignNo,
    ColourMatchingID,
    ColourMatchingName,
    WarpQuality,
    WeftQuality,
    PCS,
    ProductionPCS,
    PendingPCS,
    " + (hasShortPcsD ? "ShortPCS, " : "") + @"
    SalesRate,
    JobRate,
    Amount,
    " + (hasRpmD ? "Rpm, " : "") + @"
    " + (hasPanaRepeatD ? "PanaRepeat, " : "") + @"
    " + (hasPanaWidthD ? "PanaWidth, " : "") + @"
    " + (hasNoOfMachinesD ? "NoOfMachines, " : "") + @"
    " + (hasRepPcsD ? "RepPCS, " : "") + @"
    " + (hasRepRateD ? "RepRate, " : "") + @"
    " + (hasRepAmtD ? "RepAmt, " : "") + @"
    " + (hasJobberAcceptD ? "JobberAccept, " : "") + @"
    CompanyId,
    UserAccountId,
    DateandTime,
    IsActive
)
VALUES
(
    @ProductionOrderID,
    @SalesOrderID,
    @SalesOrderDetailID,
    @SubDetailID,
    @SalesOrderNo,
    @OrderDate,
    @PartyID,
    @PartyName,
    @SlipNo,
    @Barcode,
    @DesignEntryFormID,
    @DesignNo,
    @ColourMatchingID,
    @ColourMatchingName,
    @WarpQuality,
    @WeftQuality,
    @PCS,
    @ProductionPCS,
    @PendingPCS,
    " + (hasShortPcsD ? "@ShortPCS, " : "") + @"
    @SalesRate,
    @JobRate,
    @Amount,
    " + (hasRpmD ? "@Rpm, " : "") + @"
    " + (hasPanaRepeatD ? "@PanaRepeat, " : "") + @"
    " + (hasPanaWidthD ? "@PanaWidth, " : "") + @"
    " + (hasNoOfMachinesD ? "@NoOfMachines, " : "") + @"
    " + (hasRepPcsD ? "@RepPCS, " : "") + @"
    " + (hasRepRateD ? "@RepRate, " : "") + @"
    " + (hasRepAmtD ? "@RepAmt, " : "") + @"
    " + (hasJobberAcceptD ? "@JobberAccept, " : "") + @"
    @CompanyId,
    @UserAccountId,
    GETDATE(),
    1
);

SELECT CAST(SCOPE_IDENTITY() AS BIGINT);";

                            using (SqlCommand cmd =
                                   new SqlCommand(insertDetailSql, con, tran))
                            {
                                AddDetailParameters(
                                    cmd,
                                    d,
                                    productionOrderID,
                                    request,
                                    currentCompanyId,
                                    currentUserAccountId
                                );

                                long newDetailID =
                                    Convert.ToInt64(cmd.ExecuteScalar());

                                if (newDetailID <= 0)
                                {
                                    throw new Exception(
                                        "Production Order Detail could not be inserted.");
                                }

                                incomingDetailIds.Add(newDetailID);
                                result.InsertedDetails++;
                            }
                        }

                        // EDIT MODE: SOFT DELETE REMOVED DETAILS
                        if (!isInsert)
                        {
                            const string oldDetailsSql = @"
SELECT ProductionOrderDetailID
FROM ProductionOrderDetail
WHERE ProductionOrderID = @ProductionOrderID
  AND IsActive = 1;";

                            var oldDetailIds = new List<long>();

                            using (SqlCommand cmd =
                                   new SqlCommand(oldDetailsSql, con, tran))
                            {
                                cmd.Parameters.Add(
                                    "@ProductionOrderID",
                                    SqlDbType.BigInt
                                ).Value = productionOrderID;

                                using (SqlDataReader dr = cmd.ExecuteReader())
                                {
                                    while (dr.Read())
                                    {
                                        oldDetailIds.Add(Convert.ToInt64(dr[0]));
                                    }
                                }
                            }

                            foreach (long oldID in oldDetailIds)
                            {
                                if (incomingDetailIds.Contains(oldID))
                                    continue;

                                const string deactivateSql = @"
UPDATE ProductionOrderDetail
SET
    IsActive = 0,
    DateandTime = GETDATE()
WHERE ProductionOrderDetailID = @ProductionOrderDetailID
  AND ProductionOrderID = @ProductionOrderID;";

                                using (SqlCommand cmd =
                                       new SqlCommand(deactivateSql, con, tran))
                                {
                                    cmd.Parameters.Add(
                                        "@ProductionOrderDetailID",
                                        SqlDbType.BigInt
                                    ).Value = oldID;

                                    cmd.Parameters.Add(
                                        "@ProductionOrderID",
                                        SqlDbType.BigInt
                                    ).Value = productionOrderID;

                                    int affectedRows = cmd.ExecuteNonQuery();

                                    if (affectedRows > 0)
                                    {
                                        result.DeletedDetails++;
                                    }
                                }

                                const string deactivateSubSql = @"
UPDATE ProductionOrderSubDetail
SET
    IsActive = 0,
    DateandTime = GETDATE()
WHERE ProductionOrderDetailID = @ProductionOrderDetailID
  AND ProductionOrderID = @ProductionOrderID;";

                                using (SqlCommand cmdSub =
                                       new SqlCommand(deactivateSubSql, con, tran))
                                {
                                    cmdSub.Parameters.Add(
                                        "@ProductionOrderDetailID",
                                        SqlDbType.BigInt
                                    ).Value = oldID;

                                    cmdSub.Parameters.Add(
                                        "@ProductionOrderID",
                                        SqlDbType.BigInt
                                    ).Value = productionOrderID;

                                    cmdSub.ExecuteNonQuery();
                                }
                            }
                        }

                        // NEW MASTER MUST HAVE AT LEAST ONE NEW DETAIL
                        if (isInsert && result.InsertedDetails <= 0)
                        {
                            tran.Rollback();

                            result.Success = false;
                            result.ProductionOrderID = 0;
                            result.Message =
                                "Production Order cannot be saved because no detail record was inserted.";

                            return result;
                        }

                        // COMMIT MASTER + DETAILS TOGETHER
                        tran.Commit();               

                        result.Success = true;
                        result.ProductionOrderID = productionOrderID;
                        result.ProductionOrderNo = productionOrderNo;

                        result.Message = isInsert
                            ? "Production Order saved successfully."
                            : "Production Order updated successfully.";

                        return result;
                    }
                    catch (Exception ex)
                    {
                        try
                        {
                            tran.Rollback();
                        }
                        catch
                        {
                        }

                        result.Success = false;
                        result.ProductionOrderID = 0;
                        result.Message = ex.Message;

                        // Keep your existing project error logging here if required.
                        return result;
                    }
                }
            }
        }
        /*
         * ================================================================
         * RESOLVE SALES ORDER VALUES
         * ================================================================
         *
         * Mapping:
         *
         * ProductionOrderDetail.SalesOrderDetailID
         *          =
         * SalesOrderDetails.DetailID
         *
         * SalesOrderDetails.DetailID 13 -> SalesOrderID 5
         * SalesOrderDetails.DetailID 11 -> SalesOrderID 6
         *
         * Then:
         *
         * SaleOrder.SalesOrderID -> PartyID
         *
         * Also gets DesignColorMatchingID when ColourMatchingID
         * was not supplied by the frontend.
         */
        private static void ResolveSalesOrderValues(SqlConnection con, SqlTransaction tran, ProductionOrderDetailRequest d)
        {
            if (!d.SalesOrderDetailID.HasValue || d.SalesOrderDetailID.Value <= 0)
            {
                return;
            }

            const string sql = @" SELECT TOP 1  SOD.SaleOrderID, SO.PartyID, SOD.DesignColorMatchingID  FROM SaleOrderDetails SOD
                                        LEFT JOIN SaleOrder SO  ON SO.SaleOrderID = SOD.SaleOrderID WHERE SOD.DetailID = @DetailID;";

            using (SqlCommand cmd = new SqlCommand(sql, con, tran))
            {
                cmd.Parameters.Add("@DetailID", SqlDbType.BigInt).Value = d.SalesOrderDetailID.Value;

                using (SqlDataReader dr =
                       cmd.ExecuteReader())
                {
                    if (!dr.Read())
                        return;

                    /*
                     * SalesOrderID
                     */
                    if (dr["SaleOrderID"] != DBNull.Value)
                    {
                        d.SalesOrderID =
                            Convert.ToInt64(
                                dr["SaleOrderID"]
                            );
                    }

                    /*
                     * PartyID
                     */
                    if (dr["PartyID"] != DBNull.Value)
                    {
                        d.PartyID =
                            Convert.ToInt64(
                                dr["PartyID"]
                            );
                    }

                    /*
                     * ColourMatchingID
                     *
                     * SalesOrderDetails screenshot shows:
                     * DesignColorMatchingID
                     *
                     * Use it only if frontend has not supplied
                     * ColourMatchingID.
                     */
                    if ((!d.ColourMatchingID.HasValue ||
                         d.ColourMatchingID.Value <= 0) &&
                        dr["DesignColorMatchingID"] != DBNull.Value)
                    {
                        d.ColourMatchingID =
                            Convert.ToInt64(
                                dr["DesignColorMatchingID"]
                            );
                    }
                }
            }
        }
        /*
         * ================================================================
         * CURRENT USER ID
         * ================================================================
         *
         * Required source:
         *
         * Context.Request.Cookies["UserIDs"].Value.Split('=')[1]
         *
         * Handles both:
         *
         * UserIDs=17
         * and
         * 17
         */
        private long? GetCurrentUserAccountId()
        {
            try
            {
                if (Context == null ||
                    Context.Request == null)
                {
                    return null;
                }

                HttpCookie cookie =
                    Context.Request.Cookies["UserIDs"];

                if (cookie == null)
                    return null;

                string cookieValue =
                    cookie.Value;

                if (string.IsNullOrWhiteSpace(cookieValue))
                    return null;

                string[] parts =
                    cookieValue.Split('=');

                string userIdText =
                    parts.Length > 1
                        ? parts[1]
                        : parts[0];

                long userId;

                if (long.TryParse(
                        userIdText,
                        out userId))
                {
                    return userId;
                }
            }
            catch
            {
            }

            return null;
        }
