        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ProductionOrderNoResponse GetNextProductionOrderNo()
        {
            var result = new ProductionOrderNoResponse();

            string connectionString =
                ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(connectionString))
            {
                con.Open();

                const string sql = @"
            SELECT ISNULL(MAX(ProductionOrderID), 0) + 1
            FROM ProductionOrderMaster;";

                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    long nextID = Convert.ToInt64(cmd.ExecuteScalar());

                    result.Success = true;
                    result.ProductionOrderID = nextID;
                    result.ProductionOrderNo =
                        "PRO" + nextID.ToString("0000");
                }
            }

            return result;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object GetJobProductionOrderFilterDropdowns()
        {
            var partyList = new List<string>();
            var jobberList = new List<string>();
            var soList = new List<string>();
            var slipList = new List<string>();
            var designList = new List<string>();
            var colourList = new List<string>();

            string connectionString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(connectionString))
            {
                con.Open();

                int userAccountId = 0;
                int partyId = 0;
                string userRole = "";

                if (Context.Request.Cookies["UserIDs"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
                {
                    string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                    if (cookieVal.Contains("="))
                    {
                        int.TryParse(cookieVal.Split('=')[1], out userAccountId);
                    }
                    else
                    {
                        int.TryParse(cookieVal, out userAccountId);
                    }
                }

                if (userAccountId > 0)
                {
                    using (SqlCommand cmdUser = new SqlCommand(@"
                        SELECT ISNULL(PartyId, 0) AS PartyId, ISNULL(UserRole, '') AS UserRole
                        FROM UserAccountMaster WHERE UserAccountId = @UserAccountId", con))
                    {
                        cmdUser.Parameters.AddWithValue("@UserAccountId", userAccountId);
                        using (SqlDataReader drUser = cmdUser.ExecuteReader())
                        {
                            if (drUser.Read())
                            {
                                partyId = Convert.ToInt32(drUser["PartyId"]);
                                userRole = drUser["UserRole"].ToString().Trim();
                            }
                        }
                    }
                }

                bool isJobWork = string.Equals(userRole, "Job Work", StringComparison.OrdinalIgnoreCase);
                string filterClause = (isJobWork && partyId > 0) ? " AND (POD.PartyID = @PartyId OR POM.JobWorkerID = @PartyId) " : "";

                string sql = @"
                    SELECT DISTINCT LTRIM(RTRIM(POD.PartyName)) AS Val
                    FROM ProductionOrderDetail POD
                    LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                    WHERE ISNULL(POD.IsActive, 1) = 1 AND POD.PartyName IS NOT NULL AND LTRIM(RTRIM(POD.PartyName)) <> '' " + filterClause + @"
                    ORDER BY Val;

                    SELECT DISTINCT LTRIM(RTRIM(POM.JobWorkerName)) AS Val
                    FROM ProductionOrderMaster POM
                    LEFT JOIN ProductionOrderDetail POD ON POD.ProductionOrderID = POM.ProductionOrderID
                    WHERE POM.JobWorkerName IS NOT NULL AND LTRIM(RTRIM(POM.JobWorkerName)) <> '' " + filterClause + @"
                    ORDER BY Val;

                    SELECT DISTINCT LTRIM(RTRIM(POD.SalesOrderNo)) AS Val
                    FROM ProductionOrderDetail POD
                    LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                    WHERE ISNULL(POD.IsActive, 1) = 1 AND POD.SalesOrderNo IS NOT NULL AND LTRIM(RTRIM(POD.SalesOrderNo)) <> '' " + filterClause + @"
                    ORDER BY Val;

                    SELECT DISTINCT LTRIM(RTRIM(POD.SlipNo)) AS Val
                    FROM ProductionOrderDetail POD
                    LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                    WHERE ISNULL(POD.IsActive, 1) = 1 AND POD.SlipNo IS NOT NULL AND LTRIM(RTRIM(POD.SlipNo)) <> '' " + filterClause + @"
                    ORDER BY Val;

                    SELECT DISTINCT LTRIM(RTRIM(POD.DesignNo)) AS Val
                    FROM ProductionOrderDetail POD
                    LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                    WHERE ISNULL(POD.IsActive, 1) = 1 AND POD.DesignNo IS NOT NULL AND LTRIM(RTRIM(POD.DesignNo)) <> '' " + filterClause + @"
                    ORDER BY Val;

                    SELECT DISTINCT LTRIM(RTRIM(POD.ColourMatchingName)) AS Val
                    FROM ProductionOrderDetail POD
                    LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                    WHERE ISNULL(POD.IsActive, 1) = 1 AND POD.ColourMatchingName IS NOT NULL AND LTRIM(RTRIM(POD.ColourMatchingName)) <> '' " + filterClause + @"
                    ORDER BY Val;
                ";

                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    if (isJobWork && partyId > 0)
                    {
                        cmd.Parameters.AddWithValue("@PartyId", partyId);
                    }

                    using (SqlDataReader dr = cmd.ExecuteReader())
                    {
                        while (dr.Read()) partyList.Add(dr["Val"].ToString());
                        if (dr.NextResult()) while (dr.Read()) jobberList.Add(dr["Val"].ToString());
                        if (dr.NextResult()) while (dr.Read()) soList.Add(dr["Val"].ToString());
                        if (dr.NextResult()) while (dr.Read()) slipList.Add(dr["Val"].ToString());
                        if (dr.NextResult()) while (dr.Read()) designList.Add(dr["Val"].ToString());
                        if (dr.NextResult()) while (dr.Read()) colourList.Add(dr["Val"].ToString());
                    }
                }
            }

            return new
            {
                PartyList = partyList,
                JobberList = jobberList,
                SOList = soList,
                SlipList = slipList,
                DesignList = designList,
                ColourList = colourList
            };
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object jobproductionorderList(
            string tab = "pending",
            int pageIndex = 1,
            int pageSize = 30,
            string party = "",
            string jobber = "",
            string so = "",
            string slipNo = "",
            string designNo = "",
            string colour = "",
            string filterDate = "")
        {
            if (string.IsNullOrEmpty(tab)) tab = "pending";
            tab = tab.Trim().ToLower();
            if (pageIndex < 1) pageIndex = 1;
            if (pageSize < 1) pageSize = 30;
            int offset = (pageIndex - 1) * pageSize;

            var dataList = new List<object>();
            int filteredTotal = 0;
            decimal filteredTotalPcs = 0;
            int pendingCount = 0;
            int allottedCount = 0;
            int completedCount = 0;

            string connectionString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(connectionString))
            {
                con.Open();

                int userAccountId = 0;
                int partyId = 0;
                string userRole = "";

                if (Context.Request.Cookies["UserIDs"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
                {
                    string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                    if (cookieVal.Contains("="))
                    {
                        int.TryParse(cookieVal.Split('=')[1], out userAccountId);
                    }
                    else
                    {
                        int.TryParse(cookieVal, out userAccountId);
                    }
                }

                if (userAccountId > 0)
                {
                    using (SqlCommand cmdUser = new SqlCommand(@"
                        SELECT 
                            ISNULL(PartyId, 0) AS PartyId,
                            ISNULL(UserRole, '') AS UserRole
                        FROM UserAccountMaster
                        WHERE UserAccountId = @UserAccountId", con))
                    {
                        cmdUser.Parameters.AddWithValue("@UserAccountId", userAccountId);
                        using (SqlDataReader drUser = cmdUser.ExecuteReader())
                        {
                            if (drUser.Read())
                            {
                                partyId = Convert.ToInt32(drUser["PartyId"]);
                                userRole = drUser["UserRole"].ToString().Trim();
                            }
                        }
                    }
                }

                bool isJobWork = string.Equals(userRole, "Job Work", StringComparison.OrdinalIgnoreCase);

                // 1) Fast Badges Count Query
                string sqlBadgeCounts = @"
                    SELECT 
                        COUNT(CASE WHEN ISNULL(Sub.TotPCS, 0) < ISNULL(POD.ProductionPCS, POD.PCS) OR ISNULL(POD.ProductionPCS, POD.PCS) = 0 THEN 1 END) AS PendingCount,
                        COUNT(CASE WHEN ISNULL(Sub.TotPCS, 0) >= ISNULL(POD.ProductionPCS, POD.PCS) AND ISNULL(POD.ProductionPCS, POD.PCS) > 0 THEN 1 END) AS CompletedCount
                    FROM ProductionOrderDetail POD
                    LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                    OUTER APPLY (
                        SELECT SUM(POSD.PCS) AS TotPCS
                        FROM ProductionOrderSubDetail POSD
                        WHERE POSD.ProductionOrderDetailID = POD.ProductionOrderDetailID AND ISNULL(POSD.IsActive, 1) = 1
                    ) Sub
                    WHERE ISNULL(POD.IsActive, 1) = 1 " + (isJobWork && partyId > 0 ? " AND (POD.PartyID = @PartyId OR POM.JobWorkerID = @PartyId) " : "") + @";

                    SELECT COUNT(1) AS AllottedCount
                    FROM ProductionOrderSubDetail POSD
                    LEFT JOIN ProductionOrderDetail POD ON POSD.ProductionOrderDetailID = POD.ProductionOrderDetailID
                    LEFT JOIN ProductionOrderMaster POM ON (POSD.ProductionOrderID = POM.ProductionOrderID OR POD.ProductionOrderID = POM.ProductionOrderID)
                    WHERE ISNULL(POSD.IsActive, 1) = 1 " + (isJobWork && partyId > 0 ? " AND (POD.PartyID = @PartyId OR POM.JobWorkerID = @PartyId) " : "") + @";
                ";

                using (SqlCommand cmdBadges = new SqlCommand(sqlBadgeCounts, con))
                {
                    if (isJobWork && partyId > 0)
                    {
                        cmdBadges.Parameters.AddWithValue("@PartyId", partyId);
                    }
                    using (SqlDataReader drBadges = cmdBadges.ExecuteReader())
                    {
                        if (drBadges.Read())
                        {
                            pendingCount = drBadges["PendingCount"] != DBNull.Value ? Convert.ToInt32(drBadges["PendingCount"]) : 0;
                            completedCount = drBadges["CompletedCount"] != DBNull.Value ? Convert.ToInt32(drBadges["CompletedCount"]) : 0;
                        }
                        if (drBadges.NextResult() && drBadges.Read())
                        {
                            allottedCount = drBadges["AllottedCount"] != DBNull.Value ? Convert.ToInt32(drBadges["AllottedCount"]) : 0;
                        }
                    }
                }

                Action<SqlCommand> attachFilterParams = (cmd) =>
                {
                    if (isJobWork && partyId > 0) cmd.Parameters.AddWithValue("@PartyId", partyId);
                    if (!string.IsNullOrEmpty(party)) cmd.Parameters.AddWithValue("@Party", "%" + party.Trim() + "%");
                    if (!string.IsNullOrEmpty(jobber)) cmd.Parameters.AddWithValue("@Jobber", "%" + jobber.Trim() + "%");
                    if (!string.IsNullOrEmpty(so)) cmd.Parameters.AddWithValue("@SO", "%" + so.Trim() + "%");
                    if (!string.IsNullOrEmpty(slipNo)) cmd.Parameters.AddWithValue("@SlipNo", "%" + slipNo.Trim() + "%");
                    if (!string.IsNullOrEmpty(designNo)) cmd.Parameters.AddWithValue("@DesignNo", "%" + designNo.Trim() + "%");
                    if (!string.IsNullOrEmpty(colour)) cmd.Parameters.AddWithValue("@Colour", "%" + colour.Trim() + "%");
                    if (!string.IsNullOrEmpty(filterDate)) cmd.Parameters.AddWithValue("@FilterDate", filterDate.Trim());
                    cmd.Parameters.AddWithValue("@Offset", offset);
                    cmd.Parameters.AddWithValue("@PageSize", pageSize);
                };

                // 2) Query Current Tab Data (thoda-thoda / paginated)
                if (tab == "allotted")
                {
                    string whereAllotted = " WHERE ISNULL(POSD.IsActive, 1) = 1 ";
                    if (isJobWork && partyId > 0) whereAllotted += " AND (POD.PartyID = @PartyId OR POM.JobWorkerID = @PartyId) ";
                    if (!string.IsNullOrEmpty(party)) whereAllotted += " AND (POD.PartyName LIKE @Party OR POM.Traders LIKE @Party) ";
                    if (!string.IsNullOrEmpty(jobber)) whereAllotted += " AND (POM.JobWorkerName LIKE @Jobber OR POD.PartyName LIKE @Jobber) ";
                    if (!string.IsNullOrEmpty(so)) whereAllotted += " AND (POD.SalesOrderNo LIKE @SO OR REPLACE(POD.SalesOrderNo, 'SO', '') LIKE @SO) ";
                    if (!string.IsNullOrEmpty(slipNo)) whereAllotted += " AND POD.SlipNo LIKE @SlipNo ";
                    if (!string.IsNullOrEmpty(designNo)) whereAllotted += " AND POD.DesignNo LIKE @DesignNo ";
                    if (!string.IsNullOrEmpty(colour)) whereAllotted += " AND POD.ColourMatchingName LIKE @Colour ";
                    if (!string.IsNullOrEmpty(filterDate))
                    {
                        whereAllotted += " AND (CONVERT(varchar(10), POSD.ProductionDate, 120) = @FilterDate OR CONVERT(varchar(10), POSD.ProductionDate, 103) = @FilterDate OR CONVERT(varchar(10), ISNULL(POD.OrderDate, POM.ProductionOrderDate), 120) = @FilterDate OR CONVERT(varchar(10), ISNULL(POD.OrderDate, POM.ProductionOrderDate), 103) = @FilterDate) ";
                    }

                    string sqlAllottedCount = @"
                        SELECT COUNT(1) AS FilteredTotal, ISNULL(SUM(POSD.PCS), 0) AS TotalPcs
                        FROM ProductionOrderSubDetail POSD
                        LEFT JOIN ProductionOrderDetail POD ON (POSD.ProductionOrderDetailID = POD.ProductionOrderDetailID OR (ISNULL(POSD.ProductionOrderDetailID,0)=0 AND POSD.ProductionOrderID = POD.ProductionOrderID))
                        LEFT JOIN ProductionOrderMaster POM ON (POSD.ProductionOrderID = POM.ProductionOrderID OR POD.ProductionOrderID = POM.ProductionOrderID)
                        " + whereAllotted;

                    using (SqlCommand cmdCount = new SqlCommand(sqlAllottedCount, con))
                    {
                        attachFilterParams(cmdCount);
                        using (SqlDataReader drCount = cmdCount.ExecuteReader())
                        {
                            if (drCount.Read())
                            {
                                filteredTotal = drCount["FilteredTotal"] != DBNull.Value ? Convert.ToInt32(drCount["FilteredTotal"]) : 0;
                                filteredTotalPcs = drCount["TotalPcs"] != DBNull.Value ? Convert.ToDecimal(drCount["TotalPcs"]) : 0;
                            }
                        }
                    }

                    string sqlAllottedData = @"
                        SELECT 
                            POSD.ProductionOrderSubDetailID,
                            ISNULL(POSD.ProductionOrderDetailID, ISNULL(POD.ProductionOrderDetailID, 0)) AS ProductionOrderDetailID,
                            ISNULL(POSD.ProductionOrderID, ISNULL(POD.ProductionOrderID, 0)) AS ProductionOrderID,
                            ISNULL(POM.ProductionOrderNo, '') AS ProductionOrderNo,
                            CONVERT(varchar(10), ISNULL(POD.OrderDate, POM.ProductionOrderDate), 103) AS OrderDate,
                            CONVERT(varchar(10), POSD.ProductionDate, 103) AS ProductionDate,
                            ISNULL(POSD.MachineNumber, 0) AS MachineNumber,
                            ISNULL(POD.PartyName, ISNULL(POM.Traders, '')) AS PartyName,
                            ISNULL(POD.SalesOrderNo, '') AS SalesOrderNo,
                            ISNULL(POD.SlipNo, '') AS SlipNo,
                            ISNULL(POD.DesignNo, '') AS DesignNo,
                            ISNULL(POD.ColourMatchingName, '') AS ColourMatchingName,
                            ISNULL(
                                (SELECT TOP 1 DCMD.ColorMatchingPhoto 
                                 FROM DesignColorMatchingFormMaster DCMFM 
                                 INNER JOIN DesignColorMatchingDetails DCMD ON DCMD.DesignColorMatchingFormID = DCMFM.DesignColorMatchingFormID
                                 INNER JOIN SaleOrderDetails SOD ON SOD.DesignColorMatchingID = DCMFM.DesignColorMatchingFormID
                                 INNER JOIN ProductionOrderDetail P ON P.SalesOrderDetailID = SOD.DetailID
                                 WHERE P.ProductionOrderDetailID = POD.ProductionOrderDetailID
                                   AND (
                                       UPPER(LTRIM(RTRIM(DCMD.FeederMatchingID))) = UPPER(LTRIM(RTRIM(  
                                           CASE   
                                               WHEN CHARINDEX(' - ', CONVERT(VARCHAR(500), POD.ColourMatchingName)) > 0   
                                                    THEN SUBSTRING(CONVERT(VARCHAR(500), POD.ColourMatchingName), CHARINDEX(' - ', CONVERT(VARCHAR(500), POD.ColourMatchingName)) + 3, LEN(CONVERT(VARCHAR(500), POD.ColourMatchingName)))  
                                               ELSE CONVERT(VARCHAR(200), POD.ColourMatchingName)  
                                          END  
                                       )))
                                       OR DCMD.MatchingNo = 1
                                   )
                                 ORDER BY CASE WHEN UPPER(LTRIM(RTRIM(DCMD.FeederMatchingID))) = UPPER(LTRIM(RTRIM(POD.ColourMatchingName))) THEN 0 ELSE 1 END), 
                                ISNULL(DEFM.PhotoOfDesign, '')
                            ) AS PhotoPath,
                            ISNULL(POD.ProductionPCS, ISNULL(POD.PCS, 0)) AS OrderPCS,
                            ISNULL(POSD.PCS, 0) AS SubDetailPCS,
                            ISNULL((
                                SELECT SUM(P.PCS) 
                                FROM ProductionOrderSubDetail P 
                                WHERE P.ProductionOrderDetailID = POSD.ProductionOrderDetailID 
                                  AND ISNULL(P.IsActive, 1) = 1
                            ), 0) AS TotalCompletedPCS,
                            ISNULL(POD.JobRate, ISNULL(POM.JobRate, 0)) AS JobRate,
                            ISNULL(POM.PanaRepeat, 0) AS PanaRepeat,
                            ISNULL(POM.JobWorkerName, '') AS JobWorkerName,
                            ISNULL(POD.Barcode, '') AS Barcode,
                            ISNULL(POD.WarpQuality, '') AS WarpQuality,
                            ISNULL(POD.WeftQuality, '') AS WeftQuality,
                            ISNULL(JM.NoOfMachines, ISNULL(JM2.NoOfMachines, 0)) AS NoOfMachines
                        FROM ProductionOrderSubDetail POSD
                        LEFT JOIN ProductionOrderDetail POD ON (POSD.ProductionOrderDetailID = POD.ProductionOrderDetailID OR (ISNULL(POSD.ProductionOrderDetailID,0)=0 AND POSD.ProductionOrderID = POD.ProductionOrderID))
                        LEFT JOIN ProductionOrderMaster POM ON (POSD.ProductionOrderID = POM.ProductionOrderID OR POD.ProductionOrderID = POM.ProductionOrderID)
                        LEFT JOIN JobberMaster JM ON ((POM.JobWorkerID IS NOT NULL AND POM.JobWorkerID > 0 AND JM.Id = POM.JobWorkerID) OR (POM.JobWorkerName IS NOT NULL AND POM.JobWorkerName <> '' AND LTRIM(RTRIM(JM.PartyName)) = LTRIM(RTRIM(POM.JobWorkerName))))
                        LEFT JOIN JobberMaster JM2 ON ((POD.PartyID IS NOT NULL AND POD.PartyID > 0 AND JM2.Id = POD.PartyID) OR (POD.PartyName IS NOT NULL AND POD.PartyName <> '' AND LTRIM(RTRIM(JM2.PartyName)) = LTRIM(RTRIM(POD.PartyName))))
                        LEFT JOIN DesignEntryFormMaster DEFM ON LTRIM(RTRIM(REPLACE(REPLACE(POD.DesignNo, ' ', ''), '-', ''))) = LTRIM(RTRIM(REPLACE(REPLACE(DEFM.DesignNo, ' ', ''), '-', '')))
                        " + whereAllotted + @"
                        ORDER BY POSD.ProductionOrderSubDetailID DESC
                        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY";

                    using (SqlCommand cmdData = new SqlCommand(sqlAllottedData, con))
                    {
                        attachFilterParams(cmdData);
                        using (SqlDataReader dr = cmdData.ExecuteReader())
                        {
                            while (dr.Read())
                            {
                                decimal orderPcs = dr["OrderPCS"] != DBNull.Value ? Convert.ToDecimal(dr["OrderPCS"]) : 0;
                                decimal subPcs = dr["SubDetailPCS"] != DBNull.Value ? Convert.ToDecimal(dr["SubDetailPCS"]) : 0;
                                decimal totCompletedPcs = dr["TotalCompletedPCS"] != DBNull.Value ? Convert.ToDecimal(dr["TotalCompletedPCS"]) : 0;
                                decimal remainingPcs = Math.Max(0, orderPcs - totCompletedPcs);

                                decimal panaRepeatVal = dr["PanaRepeat"] != DBNull.Value ? Convert.ToDecimal(dr["PanaRepeat"]) : 0;
                                decimal calcRepeat = panaRepeatVal > 0 ? (orderPcs / panaRepeatVal) : 0;
                                object repeatObj = calcRepeat > 0 ? (calcRepeat % 1 == 0 ? (object)(int)calcRepeat : (object)Math.Round(calcRepeat, 2)) : (object)panaRepeatVal;

                                string rawPhoto = dr["PhotoPath"] != DBNull.Value ? dr["PhotoPath"].ToString().Trim() : "";
                                string normalizedPhoto = "";
                                if (!string.IsNullOrEmpty(rawPhoto))
                                {
                                    string clean = rawPhoto.Replace("\\", "/");
                                    if (clean.StartsWith("~/")) clean = clean.Substring(2);
                                    if (!clean.StartsWith("/")) clean = "/" + clean;
                                    normalizedPhoto = clean;
                                }

                                dataList.Add(new
                                {
                                    ProductionOrderSubDetailID = Convert.ToInt64(dr["ProductionOrderSubDetailID"]),
                                    ProductionOrderDetailID = Convert.ToInt64(dr["ProductionOrderDetailID"]),
                                    ProductionOrderID = Convert.ToInt64(dr["ProductionOrderID"]),
                                    ProductionOrderNo = dr["ProductionOrderNo"].ToString(),
                                    OrderDate = dr["OrderDate"].ToString(),
                                    ProductionDate = dr["ProductionDate"].ToString(),
                                    MachineNumber = Convert.ToInt32(dr["MachineNumber"]),
                                    PartyName = dr["PartyName"].ToString(),
                                    SalesOrderNo = dr["SalesOrderNo"].ToString(),
                                    SlipNo = dr["SlipNo"].ToString(),
                                    DesignNo = dr["DesignNo"].ToString(),
                                    ColourMatchingName = dr["ColourMatchingName"].ToString(),
                                    PCS = orderPcs,
                                    SubDetailPCS = subPcs,
                                    CompletedPCS = subPcs,
                                    RemainingPCS = remainingPcs,
                                    IsCompleted = true,
                                    JobRate = dr["JobRate"] != DBNull.Value ? Convert.ToDecimal(dr["JobRate"]) : 0,
                                    PanaRepeat = panaRepeatVal,
                                    Repeat = repeatObj,
                                    JobWorkerName = dr["JobWorkerName"].ToString(),
                                    Barcode = dr["Barcode"].ToString(),
                                    WarpQuality = dr["WarpQuality"].ToString(),
                                    WeftQuality = dr["WeftQuality"].ToString(),
                                    NoOfMachines = dr["NoOfMachines"] != DBNull.Value ? Convert.ToInt32(dr["NoOfMachines"]) : 0,
                                    PhotoPath = normalizedPhoto,
                                    ColorMatchingPhoto = normalizedPhoto
                                });
                            }
                        }
                    }
                }
                else
                {
                    // Pending or Completed
                    bool isCompletedTab = (tab == "completed");
                    string statusCondition = isCompletedTab
                        ? " AND (ISNULL(Sub.TotPCS, 0) >= ISNULL(POD.ProductionPCS, POD.PCS) AND ISNULL(POD.ProductionPCS, POD.PCS) > 0) "
                        : " AND (ISNULL(Sub.TotPCS, 0) < ISNULL(POD.ProductionPCS, POD.PCS) OR ISNULL(POD.ProductionPCS, POD.PCS) = 0) ";

                    string wherePOD = " WHERE ISNULL(POD.IsActive, 1) = 1 " + statusCondition;

                    if (isJobWork && partyId > 0) wherePOD += " AND (POD.PartyID = @PartyId OR POM.JobWorkerID = @PartyId) ";
                    if (!string.IsNullOrEmpty(party)) wherePOD += " AND (POD.PartyName LIKE @Party OR POM.Traders LIKE @Party) ";
                    if (!string.IsNullOrEmpty(jobber)) wherePOD += " AND (POM.JobWorkerName LIKE @Jobber OR POD.PartyName LIKE @Jobber) ";
                    if (!string.IsNullOrEmpty(so)) wherePOD += " AND (POD.SalesOrderNo LIKE @SO OR REPLACE(POD.SalesOrderNo, 'SO', '') LIKE @SO) ";
                    if (!string.IsNullOrEmpty(slipNo)) wherePOD += " AND POD.SlipNo LIKE @SlipNo ";
                    if (!string.IsNullOrEmpty(designNo)) wherePOD += " AND POD.DesignNo LIKE @DesignNo ";
                    if (!string.IsNullOrEmpty(colour)) wherePOD += " AND POD.ColourMatchingName LIKE @Colour ";
                    if (!string.IsNullOrEmpty(filterDate))
                    {
                        wherePOD += " AND (CONVERT(varchar(10), ISNULL(POD.OrderDate, POM.ProductionOrderDate), 120) = @FilterDate OR CONVERT(varchar(10), ISNULL(POD.OrderDate, POM.ProductionOrderDate), 103) = @FilterDate) ";
                    }

                    string sqlPODCount = @"
                        SELECT 
                            COUNT(1) AS FilteredTotal, 
                            ISNULL(SUM(ISNULL(POD.ProductionPCS, POD.PCS)), 0) AS TotalPcs
                        FROM ProductionOrderDetail POD
                        LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                        OUTER APPLY (
                            SELECT SUM(POSD.PCS) AS TotPCS
                            FROM ProductionOrderSubDetail POSD
                            WHERE POSD.ProductionOrderDetailID = POD.ProductionOrderDetailID AND ISNULL(POSD.IsActive, 1) = 1
                        ) Sub
                        " + wherePOD;

                    using (SqlCommand cmdCount = new SqlCommand(sqlPODCount, con))
                    {
                        attachFilterParams(cmdCount);
                        using (SqlDataReader drCount = cmdCount.ExecuteReader())
                        {
                            if (drCount.Read())
                            {
                                filteredTotal = drCount["FilteredTotal"] != DBNull.Value ? Convert.ToInt32(drCount["FilteredTotal"]) : 0;
                                filteredTotalPcs = drCount["TotalPcs"] != DBNull.Value ? Convert.ToDecimal(drCount["TotalPcs"]) : 0;
                            }
                        }
                    }

                    string sqlPODData = @"
                        SELECT 
                            POD.ProductionOrderDetailID,
                            POD.ProductionOrderID,
                            ISNULL(POM.ProductionOrderNo, '') AS ProductionOrderNo,
                            CONVERT(varchar(10), ISNULL(POD.OrderDate, POM.ProductionOrderDate), 103) AS OrderDate,
                            ISNULL(POD.PartyName, ISNULL(POM.Traders, '')) AS PartyName,
                            ISNULL(POD.SalesOrderNo, '') AS SalesOrderNo,
                            ISNULL(POD.SlipNo, '') AS SlipNo,
                            ISNULL(POD.DesignNo, '') AS DesignNo,
                            ISNULL(POD.ColourMatchingName, '') AS ColourMatchingName,
                            ISNULL(
                                (SELECT TOP 1 DCMD.ColorMatchingPhoto 
                                 FROM DesignColorMatchingFormMaster DCMFM 
                                 INNER JOIN DesignColorMatchingDetails DCMD ON DCMD.DesignColorMatchingFormID = DCMFM.DesignColorMatchingFormID
                                 INNER JOIN SaleOrderDetails SOD ON SOD.DesignColorMatchingID = DCMFM.DesignColorMatchingFormID
                                 INNER JOIN ProductionOrderDetail P ON P.SalesOrderDetailID = SOD.DetailID
                                 WHERE P.ProductionOrderDetailID = POD.ProductionOrderDetailID
                                   AND (
                                       UPPER(LTRIM(RTRIM(DCMD.FeederMatchingID))) = UPPER(LTRIM(RTRIM(  
                                           CASE   
                                               WHEN CHARINDEX(' - ', CONVERT(VARCHAR(500), POD.ColourMatchingName)) > 0   
                                                    THEN SUBSTRING(CONVERT(VARCHAR(500), POD.ColourMatchingName), CHARINDEX(' - ', CONVERT(VARCHAR(500), POD.ColourMatchingName)) + 3, LEN(CONVERT(VARCHAR(500), POD.ColourMatchingName)))  
                                               ELSE CONVERT(VARCHAR(200), POD.ColourMatchingName)  
                                          END  
                                       )))
                                       OR DCMD.MatchingNo = 1
                                   )
                                 ORDER BY CASE WHEN UPPER(LTRIM(RTRIM(DCMD.FeederMatchingID))) = UPPER(LTRIM(RTRIM(POD.ColourMatchingName))) THEN 0 ELSE 1 END), 
                                ISNULL(DEFM.PhotoOfDesign, '')
                            ) AS PhotoPath,
                            ISNULL(POD.ProductionPCS, POD.PCS) AS PCS,
                            ISNULL(Sub.TotPCS, 0) AS CompletedPCS,
                            ISNULL(
                                STUFF((
                                    SELECT ',' + CAST(POSD.ProductionOrderSubDetailID AS VARCHAR(20))
                                    FROM ProductionOrderSubDetail POSD
                                    WHERE POSD.ProductionOrderDetailID = POD.ProductionOrderDetailID
                                      AND ISNULL(POSD.IsActive, 1) = 1
                                    FOR XML PATH('')
                                ), 1, 1, ''), 
                            '') AS SubDetailIDs,
                            ISNULL(POD.RepRate, 0) AS JobRate,
                            ISNULL(POM.PanaRepeat, 0) AS PanaRepeat,
                            ISNULL(POM.JobWorkerName, '') AS JobWorkerName,
                            ISNULL(POD.Barcode, '') AS Barcode,
                            ISNULL(POD.WarpQuality, '') AS WarpQuality,
                            ISNULL(POD.WeftQuality, '') AS WeftQuality,
                            ISNULL(JM.NoOfMachines, ISNULL(JM2.NoOfMachines, 0)) AS NoOfMachines
                        FROM ProductionOrderDetail POD
                        LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                        LEFT JOIN JobberMaster JM ON ((POM.JobWorkerID IS NOT NULL AND POM.JobWorkerID > 0 AND JM.Id = POM.JobWorkerID) OR (POM.JobWorkerName IS NOT NULL AND POM.JobWorkerName <> '' AND LTRIM(RTRIM(JM.PartyName)) = LTRIM(RTRIM(POM.JobWorkerName))))
                        LEFT JOIN JobberMaster JM2 ON ((POD.PartyID IS NOT NULL AND POD.PartyID > 0 AND JM2.Id = POD.PartyID) OR (POD.PartyName IS NOT NULL AND POD.PartyName <> '' AND LTRIM(RTRIM(JM2.PartyName)) = LTRIM(RTRIM(POD.PartyName))))
                        LEFT JOIN DesignEntryFormMaster DEFM ON LTRIM(RTRIM(REPLACE(REPLACE(POD.DesignNo, ' ', ''), '-', ''))) = LTRIM(RTRIM(REPLACE(REPLACE(DEFM.DesignNo, ' ', ''), '-', '')))
                        OUTER APPLY (
                            SELECT SUM(POSD.PCS) AS TotPCS
                            FROM ProductionOrderSubDetail POSD
                            WHERE POSD.ProductionOrderDetailID = POD.ProductionOrderDetailID AND ISNULL(POSD.IsActive, 1) = 1
                        ) Sub
                        " + wherePOD + @"
                        ORDER BY POD.ProductionOrderDetailID DESC
                        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY";

                    using (SqlCommand cmdData = new SqlCommand(sqlPODData, con))
                    {
                        attachFilterParams(cmdData);
                        using (SqlDataReader dr = cmdData.ExecuteReader())
                        {
                            while (dr.Read())
                            {
                                decimal pcsVal = dr["PCS"] != DBNull.Value ? Convert.ToDecimal(dr["PCS"]) : 0;
                                decimal completedPcsVal = dr["CompletedPCS"] != DBNull.Value ? Convert.ToDecimal(dr["CompletedPCS"]) : 0;
                                decimal remainingPcsVal = Math.Max(0, pcsVal - completedPcsVal);

                                decimal panaRepeatVal = dr["PanaRepeat"] != DBNull.Value ? Convert.ToDecimal(dr["PanaRepeat"]) : 0;
                                decimal calcRepeat = panaRepeatVal > 0 ? (pcsVal / panaRepeatVal) : 0;
                                object repeatObj = calcRepeat > 0 ? (calcRepeat % 1 == 0 ? (object)(int)calcRepeat : (object)Math.Round(calcRepeat, 2)) : (object)panaRepeatVal;

                                bool isCompleted = (completedPcsVal >= pcsVal && pcsVal > 0);

                                string rawPhoto = dr["PhotoPath"] != DBNull.Value ? dr["PhotoPath"].ToString().Trim() : "";
                                string normalizedPhoto = "";
                                if (!string.IsNullOrEmpty(rawPhoto))
                                {
                                    string clean = rawPhoto.Replace("\\", "/");
                                    if (clean.StartsWith("~/")) clean = clean.Substring(2);
                                    if (!clean.StartsWith("/")) clean = "/" + clean;
                                    normalizedPhoto = clean;
                                }

                                dataList.Add(new
                                {
                                    ProductionOrderDetailID = Convert.ToInt64(dr["ProductionOrderDetailID"]),
                                    ProductionOrderID = Convert.ToInt64(dr["ProductionOrderID"]),
                                    ProductionOrderNo = dr["ProductionOrderNo"].ToString(),
                                    OrderDate = dr["OrderDate"].ToString(),
                                    PartyName = dr["PartyName"].ToString(),
                                    SalesOrderNo = dr["SalesOrderNo"].ToString(),
                                    SlipNo = dr["SlipNo"].ToString(),
                                    DesignNo = dr["DesignNo"].ToString(),
                                    ColourMatchingName = dr["ColourMatchingName"].ToString(),
                                    PCS = pcsVal,
                                    CompletedPCS = completedPcsVal,
                                    RemainingPCS = remainingPcsVal,
                                    IsCompleted = isCompleted,
                                    SubDetailIDs = dr["SubDetailIDs"] != DBNull.Value ? dr["SubDetailIDs"].ToString() : "",
                                    JobRate = dr["JobRate"] != DBNull.Value ? Convert.ToDecimal(dr["JobRate"]) : 0,
                                    PanaRepeat = panaRepeatVal,
                                    Repeat = repeatObj,
                                    JobWorkerName = dr["JobWorkerName"].ToString(),
                                    Barcode = dr["Barcode"].ToString(),
                                    WarpQuality = dr["WarpQuality"].ToString(),
                                    WeftQuality = dr["WeftQuality"].ToString(),
                                    NoOfMachines = dr["NoOfMachines"] != DBNull.Value ? Convert.ToInt32(dr["NoOfMachines"]) : 0,
                                    PhotoPath = normalizedPhoto,
                                    ColorMatchingPhoto = normalizedPhoto
                                });
                            }
                        }
                    }
                }
            }

            return new
            {
                Tab = tab,
                PageIndex = pageIndex,
                PageSize = pageSize,
                TotalRecords = filteredTotal,
                TotalPcs = filteredTotalPcs,
                PendingCount = pendingCount,
                AllottedCount = allottedCount,
                CompletedCount = completedCount,
                DataList = dataList,
                PendingList = (tab == "pending" ? dataList : new List<object>()),
                AllottedList = (tab == "allotted" ? dataList : new List<object>()),
                CompletedList = (tab == "completed" ? dataList : new List<object>())
            };
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string GetPendingOrdersForProductionsleep()
        {
            try
            {
                List<Dictionary<string, object>> rows =
                    new List<Dictionary<string, object>>();

                string sql = @"
;WITH OrderData AS
(
    SELECT
        SOD.DesignNo,
        SOD.DesignColorMatchingID,
        SOSD.ColourID,
        SOSD.ColourName,
        COALESCE(
            DCMFM.DesignColorMatchingFormID,
            SOD.DesignColorMatchingID
        ) AS DesignColorMatchingFormID,
        COALESCE(
            DCMFM.DesignEntryFormID,
            DEFM.DesignEntryFormID
        ) AS DesignEntryFormID

    FROM SaleOrderDetails SOD

    INNER JOIN SaleOrderSubDetails SOSD
        ON SOSD.DetailID = SOD.DetailID

    LEFT JOIN DesignColorMatchingFormMaster DCMFM
        ON DCMFM.DesignColorMatchingFormID =
           SOD.DesignColorMatchingID

    LEFT JOIN DesignEntryFormMaster DEFM
        ON DEFM.DesignerCode = SOD.DesignNo
),

QualityData AS
(
    /* WARP QUALITY */
    SELECT
        'WARP QUALITY' AS QualityType,
        OD.ColourID,
        OD.ColourName,
        OD.DesignColorMatchingID,
        OD.DesignColorMatchingFormID,
        OD.DesignEntryFormID,

        COALESCE(DEFM.DesignerCode, OD.DesignNo) AS DesignerCode,

        DCM.MatchingNo,

        'WARP-1' AS Position,
        0 AS PositionNo,

        YCM.YarnColor,
        YCM.YarnColorCode,
        YQM.YarnMaterial,
        WQM.WarpQuality,

        CAST(NULL AS VARCHAR(200)) AS DesignSpecification

    FROM OrderData OD

    LEFT JOIN DesignEntryFormMaster DEFM
        ON DEFM.DesignEntryFormID = OD.DesignEntryFormID

    LEFT JOIN DesignColorMatchingDetails DCM
        ON DCM.DesignColorMatchingFormID =
           OD.DesignColorMatchingFormID

    LEFT JOIN WarpQualityMaster WQM
        ON WQM.WarpQualityID = DEFM.WarpQualityID

    LEFT JOIN YarnColorMaster YCM
        ON YCM.YarnColorID = DCM.Warp1

    LEFT JOIN DesignFormWarpData DFWD
        ON DFWD.DesignEntryFormID = DEFM.DesignEntryFormID
       AND ISNULL(DFWD.DesignEntryWarpID, 1) = 1

    LEFT JOIN YarnMaterialMaster YQM
        ON YQM.YarnMaterialID = DFWD.YarnQualityMaterialID

    WHERE
        ISNULL(DEFM.DesignEntryFormID, 0) <> 0
        OR ISNULL(DCM.Warp1, 0) <> 0

    UNION ALL

    /* WEFT QUALITY */
    SELECT
        'WEFT QUALITY' AS QualityType,
        OD.ColourID,
        OD.ColourName,
        OD.DesignColorMatchingID,
        OD.DesignColorMatchingFormID,
        OD.DesignEntryFormID,

        COALESCE(DEFM.DesignerCode, OD.DesignNo) AS DesignerCode,

        DCM.MatchingNo,

        'FEEDER-' + CAST(F.FeederNo AS VARCHAR(10)) AS Position,
        F.FeederNo AS PositionNo,

        YCM.YarnColor,
        YCM.YarnColorCode,
        YMM.YarnMaterial,

        CAST(NULL AS VARCHAR(200)) AS WarpQuality,

        DSM.DesignSpecification

    FROM OrderData OD

    LEFT JOIN DesignEntryFormMaster DEFM
        ON DEFM.DesignEntryFormID = OD.DesignEntryFormID

    LEFT JOIN DesignColorMatchingDetails DCM
        ON DCM.DesignColorMatchingFormID =
           OD.DesignColorMatchingFormID

    CROSS APPLY
    (
        VALUES
            (1,  DCM.Feeder1),
            (2,  DCM.Feeder2),
            (3,  DCM.Feeder3),
            (4,  DCM.Feeder4),
            (5,  DCM.Feeder5),
            (6,  DCM.Feeder6),
            (7,  DCM.Feeder7),
            (8,  DCM.Feeder8),
            (9,  DCM.Feeder9),
            (10, DCM.Feeder10),
            (11, DCM.Feeder11),
            (12, DCM.Feeder12),
            (13, DCM.Feeder13),
            (14, DCM.Feeder14),
            (15, DCM.Feeder15),
            (16, DCM.Feeder16),
            (17, DCM.Feeder17),
            (18, DCM.Feeder18),
            (19, DCM.Feeder19),
            (20, DCM.Feeder20),
            (21, DCM.Feeder21),
            (22, DCM.Feeder22),
            (23, DCM.Feeder23),
            (24, DCM.Feeder24),
            (25, DCM.Feeder25),
            (26, DCM.Feeder26),
            (27, DCM.Feeder27),
            (28, DCM.Feeder28),
            (29, DCM.Feeder29),
            (30, DCM.Feeder30)
    ) F(FeederNo, YarnColorID)

    LEFT JOIN YarnColorMaster YCM
        ON YCM.YarnColorID = F.YarnColorID

    LEFT JOIN
    (
        SELECT
            DEWD.*,
            ROW_NUMBER() OVER
            (
                PARTITION BY DEWD.DesignEntryFormID
                ORDER BY DEWD.DesignEntryWeftID
            ) AS WeftNo

        FROM DesignEntryWeftData DEWD
    ) DEWD
        ON DEWD.DesignEntryFormID = DEFM.DesignEntryFormID
       AND DEWD.WeftNo = F.FeederNo

    LEFT JOIN YarnMaterialMaster YMM
        ON YMM.YarnMaterialID = DEWD.YarnMaterialID

    LEFT JOIN DesignSpecificationMaster DSM
        ON DSM.DesignSpecificationID = DEWD.DesignSpecificationID

    WHERE
        ISNULL(DEFM.DesignEntryFormID, 0) <> 0
        OR ISNULL(F.YarnColorID, 0) <> 0
)

SELECT
    QualityType,
    ColourID,
    ColourName,
    DesignColorMatchingID,
    DesignColorMatchingFormID,
    DesignEntryFormID,
    DesignerCode,
    MatchingNo,
    Position,
    PositionNo,
    YarnColor,
    YarnColorCode,
    YarnMaterial,
    WarpQuality,
    DesignSpecification

FROM QualityData

ORDER BY
    MatchingNo,
    CASE
        WHEN QualityType = 'WARP QUALITY' THEN 0
        ELSE 1
    END,
    PositionNo;
";

                using (SqlConnection con = new SqlConnection(connString))
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.CommandTimeout = 120;

                    con.Open();

                    using (SqlDataReader reader = cmd.ExecuteReader(
                        CommandBehavior.SequentialAccess))
                    {
                        while (reader.Read())
                        {
                            Dictionary<string, object> row =
                                new Dictionary<string, object>();

                            for (int i = 0; i < reader.FieldCount; i++)
                            {
                                row[reader.GetName(i)] =
                                    reader.IsDBNull(i) ? null : reader.GetValue(i);
                            }

                            rows.Add(row);
                        }
                    }
                }

                return JsonConvert.SerializeObject(rows);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine(
                    "GetPendingOrdersForProductionsleep Error: " + ex.ToString()
                );

                return JsonConvert.SerializeObject(new
                {
                    Success = false,
                    Message = ex.Message,
                    Data = new List<object>()
                });
            }
        }
        #endregion

        #region ProductionOrderSubDetail WebMethods
        private void EnsureProductionOrderSubDetailTableExists(SqlConnection con, SqlTransaction tran = null)
        {
            string checkSql = @"
                IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = 'ProductionOrderSubDetail')
                BEGIN
                    CREATE TABLE ProductionOrderSubDetail
                    (
                        ProductionOrderSubDetailID BIGINT IDENTITY(1,1) PRIMARY KEY,
                        ProductionOrderID BIGINT NOT NULL,
                        ProductionOrderDetailID BIGINT NOT NULL,
                        ProductionDate DATETIME NOT NULL DEFAULT GETDATE(),
                        MachineNumber INT NOT NULL,
                        PCS DECIMAL(18,2) NOT NULL DEFAULT 0,
                        CreatedByUserID BIGINT NULL,
                        CompanyId BIGINT NULL,
                        DateandTime DATETIME NOT NULL DEFAULT GETDATE(),
                        IsActive TINYINT NOT NULL DEFAULT 1,
                        CONSTRAINT FK_ProductionOrderSubDetail_ProductionOrder
                            FOREIGN KEY (ProductionOrderID)
                            REFERENCES ProductionOrderMaster(ProductionOrderID),
                        CONSTRAINT FK_ProductionOrderSubDetail_ProductionOrderDetail
                            FOREIGN KEY (ProductionOrderDetailID)
                            REFERENCES ProductionOrderDetail(ProductionOrderDetailID)
                    );
                END";

            using (SqlCommand cmd = new SqlCommand(checkSql, con, tran))
            {
                cmd.ExecuteNonQuery();
            }
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object SaveProductionOrderSubDetail(long productionOrderID, long productionOrderDetailID, string productionDate, int machineNumber, decimal pcs)
        {
            try
            {
                string connectionString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                long createdByUserID = 0;
                long companyId = 0;

                if (Context.Request.Cookies["UserIDs"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
                {
                    string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                    if (cookieVal.Contains("="))
                    {
                        long.TryParse(cookieVal.Split('=')[1], out createdByUserID);
                    }
                    else
                    {
                        long.TryParse(cookieVal, out createdByUserID);
                    }
                }

                using (SqlConnection con = new SqlConnection(connectionString))
                {
                    con.Open();
                    EnsureProductionOrderSubDetailTableExists(con);

                    using (SqlTransaction tran = con.BeginTransaction(IsolationLevel.ReadCommitted))
                    {
                        try
                        {
                            // Acquire application lock on ProductionOrder and validate active status
                            ProductionOrderLockHelper.AcquireOrderLock(con, tran, productionOrderID);
                            ProductionOrderLockHelper.ValidateOrderAndDetailActive(con, tran, productionOrderID, productionOrderDetailID);

                            if (createdByUserID > 0)
                            {
                                using (SqlCommand cmdUser = new SqlCommand("SELECT TOP 1 CompanyId FROM UserAccountMaster WHERE UserAccountId = @UserAccountId", con, tran))
                                {
                                    cmdUser.Parameters.AddWithValue("@UserAccountId", createdByUserID);
                                    object resComp = cmdUser.ExecuteScalar();
                                    if (resComp != null && resComp != DBNull.Value)
                                    {
                                        long.TryParse(resComp.ToString(), out companyId);
                                    }
                                }
                            }

                            DateTime parsedDate = DateTime.Now;
                            if (!string.IsNullOrEmpty(productionDate))
                            {
                                DateTime.TryParse(productionDate, out parsedDate);
                            }

                            // Check total order PCS for validation
                            decimal maxOrderPCS = 0;
                            using (SqlCommand cmdMax = new SqlCommand("SELECT TOP 1 ISNULL(ProductionPCS, PCS) FROM ProductionOrderDetail WHERE ProductionOrderDetailID = @DetailID", con, tran))
                            {
                                cmdMax.Parameters.AddWithValue("@DetailID", productionOrderDetailID);
                                object resMax = cmdMax.ExecuteScalar();
                                if (resMax != null && resMax != DBNull.Value)
                                {
                                    decimal.TryParse(resMax.ToString(), out maxOrderPCS);
                                }
                            }

                            // Check existing total assigned PCS for this detail
                            decimal existingPCS = 0;
                            using (SqlCommand cmdSum = new SqlCommand("SELECT ISNULL(SUM(PCS), 0) FROM ProductionOrderSubDetail WHERE ProductionOrderDetailID = @DetailID AND ISNULL(IsActive, 1) = 1", con, tran))
                            {
                                cmdSum.Parameters.AddWithValue("@DetailID", productionOrderDetailID);
                                object resSum = cmdSum.ExecuteScalar();
                                if (resSum != null && resSum != DBNull.Value)
                                {
                                    decimal.TryParse(resSum.ToString(), out existingPCS);
                                }
                            }

                            // Check maximum allowed machine number for Jobber
                            int maxJobberMachines = 0;
                            using (SqlCommand cmdJobber = new SqlCommand(@"
                                SELECT TOP 1 ISNULL(JM.NoOfMachines, ISNULL(JM2.NoOfMachines, 0)) AS NoOfMachines
                                FROM ProductionOrderDetail POD
                                LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                                LEFT JOIN JobberMaster JM ON ((POM.JobWorkerID IS NOT NULL AND POM.JobWorkerID > 0 AND JM.Id = POM.JobWorkerID) OR (POM.JobWorkerName IS NOT NULL AND POM.JobWorkerName <> '' AND LTRIM(RTRIM(JM.PartyName)) = LTRIM(RTRIM(POM.JobWorkerName))))
                                LEFT JOIN JobberMaster JM2 ON ((POD.PartyID IS NOT NULL AND POD.PartyID > 0 AND JM2.Id = POD.PartyID) OR (POD.PartyName IS NOT NULL AND POD.PartyName <> '' AND LTRIM(RTRIM(JM2.PartyName)) = LTRIM(RTRIM(POD.PartyName))))
                                WHERE POD.ProductionOrderDetailID = @DetailID OR POM.ProductionOrderID = @OrderID", con, tran))
                            {
                                cmdJobber.Parameters.AddWithValue("@DetailID", productionOrderDetailID);
                                cmdJobber.Parameters.AddWithValue("@OrderID", productionOrderID);
                                object resJ = cmdJobber.ExecuteScalar();
                                if (resJ != null && resJ != DBNull.Value)
                                {
                                    int.TryParse(resJ.ToString(), out maxJobberMachines);
                                }
                            }

                            int finalMachineNumber = machineNumber > 0 ? machineNumber : 1;
                            if (maxJobberMachines > 0 && finalMachineNumber > maxJobberMachines)
                            {
                                finalMachineNumber = 1;
                            }

                            // Check if an active SubDetail already exists for this detail
                            long existingSubDetailId = 0;
                            using (SqlCommand cmdExist = new SqlCommand("SELECT TOP 1 ProductionOrderSubDetailID FROM ProductionOrderSubDetail WHERE ProductionOrderDetailID = @DetailID AND ISNULL(IsActive, 1) = 1 ORDER BY ProductionOrderSubDetailID ASC", con, tran))
                            {
                                cmdExist.Parameters.AddWithValue("@DetailID", productionOrderDetailID);
                                object resExist = cmdExist.ExecuteScalar();
                                if (resExist != null && resExist != DBNull.Value)
                                {
                                    long.TryParse(resExist.ToString(), out existingSubDetailId);
                                }
                            }

                            if (existingSubDetailId > 0)
                            {
                                // Check other assigned PCS (excluding current sub detail)
                                decimal otherPCS = 0;
                                using (SqlCommand cmdSum = new SqlCommand("SELECT ISNULL(SUM(PCS), 0) FROM ProductionOrderSubDetail WHERE ProductionOrderDetailID = @DetailID AND ProductionOrderSubDetailID <> @SubID AND ISNULL(IsActive, 1) = 1", con, tran))
                                {
                                    cmdSum.Parameters.AddWithValue("@DetailID", productionOrderDetailID);
                                    cmdSum.Parameters.AddWithValue("@SubID", existingSubDetailId);
                                    object resSum = cmdSum.ExecuteScalar();
                                    if (resSum != null && resSum != DBNull.Value)
                                    {
                                        decimal.TryParse(resSum.ToString(), out otherPCS);
                                    }
                                }

                                if (maxOrderPCS > 0 && (otherPCS + pcs) > maxOrderPCS)
                                {
                                    tran.Rollback();
                                    decimal remainingPCS = Math.Max(0, maxOrderPCS - otherPCS);
                                    return new
                                    {
                                        Status = false,
                                        Message = string.Format("Total Machine PCS ({0:0.00}) cannot exceed Order PCS ({1:0.00}). Maximum remaining allowed PCS is {2:0.00}.", (otherPCS + pcs), maxOrderPCS, remainingPCS)
                                    };
                                }

                                string updateSql = @"
                                    UPDATE ProductionOrderSubDetail
                                    SET
                                        ProductionOrderID = @ProductionOrderID,
                                        ProductionDate = @ProductionDate,
                                        MachineNumber = @MachineNumber,
                                        PCS = @PCS,
                                        DateandTime = GETDATE()
                                    WHERE ProductionOrderSubDetailID = @SubDetailID;";

                                using (SqlCommand cmd = new SqlCommand(updateSql, con, tran))
                                {
                                    cmd.Parameters.AddWithValue("@ProductionOrderID", productionOrderID);
                                    cmd.Parameters.AddWithValue("@ProductionDate", parsedDate);
                                    cmd.Parameters.AddWithValue("@MachineNumber", finalMachineNumber);
                                    cmd.Parameters.AddWithValue("@PCS", pcs);
                                    cmd.Parameters.AddWithValue("@SubDetailID", existingSubDetailId);
                                    cmd.ExecuteNonQuery();
                                    tran.Commit();

                                    return new
                                    {
                                        Status = true,
                                        Message = "Machine Details updated successfully!",
                                        ProductionOrderSubDetailID = existingSubDetailId
                                    };
                                }
                            }
                            else
                            {
                                if (maxOrderPCS > 0 && (existingPCS + pcs) > maxOrderPCS)
                                {
                                    tran.Rollback();
                                    decimal remainingPCS = Math.Max(0, maxOrderPCS - existingPCS);
                                    return new
                                    {
                                        Status = false,
                                        Message = string.Format("Total Machine PCS ({0:0.00}) cannot exceed Order PCS ({1:0.00}). Maximum remaining allowed PCS is {2:0.00}.", (existingPCS + pcs), maxOrderPCS, remainingPCS)
                                    };
                                }

                                string insertSql = @"
                                    INSERT INTO ProductionOrderSubDetail
                                    (
                                        ProductionOrderID,
                                        ProductionOrderDetailID,
                                        ProductionDate,
                                        MachineNumber,
                                        PCS,
                                        CreatedByUserID,
                                        CompanyId,
                                        DateandTime,
                                        IsActive
                                    )
                                    VALUES
                                    (
                                        @ProductionOrderID,
                                        @ProductionOrderDetailID,
                                        @ProductionDate,
                                        @MachineNumber,
                                        @PCS,
                                        @CreatedByUserID,
                                        @CompanyId,
                                        GETDATE(),
                                        1
                                    );
                                    SELECT SCOPE_IDENTITY();";

                                using (SqlCommand cmd = new SqlCommand(insertSql, con, tran))
                                {
                                    cmd.Parameters.AddWithValue("@ProductionOrderID", productionOrderID);
                                    cmd.Parameters.AddWithValue("@ProductionOrderDetailID", productionOrderDetailID);
                                    cmd.Parameters.AddWithValue("@ProductionDate", parsedDate);
                                    cmd.Parameters.AddWithValue("@MachineNumber", finalMachineNumber);
                                    cmd.Parameters.AddWithValue("@PCS", pcs);
                                    cmd.Parameters.AddWithValue("@CreatedByUserID", createdByUserID > 0 ? (object)createdByUserID : DBNull.Value);
                                    cmd.Parameters.AddWithValue("@CompanyId", companyId > 0 ? (object)companyId : DBNull.Value);
                                    object newIdObj = cmd.ExecuteScalar();
                                    long newId = Convert.ToInt64(newIdObj);
                                    tran.Commit();

                                    return new
                                    {
                                        Status = true,
                                        Message = "Machine Details saved successfully!",
                                        ProductionOrderSubDetailID = newId
                                    };
                                }
                            }
                        }
                        catch
                        {
                            try { tran.Rollback(); } catch { }
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                return new
                {
                    Status = false,
                    Message = "Error saving Machine Details: " + ex.Message
                };
            }
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object SaveBulkProductionOrderSubDetails(List<ProductionOrderSubDetailBatchItem> items)
        {
            try
            {
                if (items == null || items.Count == 0)
                {
                    return new { Status = false, Message = "No items selected for saving." };
                }

                int successCount = 0;
                List<string> errorMessages = new List<string>();

                foreach (var item in items)
                {
                    var resObj = SaveProductionOrderSubDetail(item.productionOrderID, item.productionOrderDetailID, item.productionDate, item.machineNumber, item.pcs);
                    if (resObj != null)
                    {
                        Type t = resObj.GetType();
                        var propStatus = t.GetProperty("Status");
                        bool status = propStatus != null && Convert.ToBoolean(propStatus.GetValue(resObj, null));
                        if (status)
                        {
                            successCount++;
                        }
                        else
                        {
                            var propMsg = t.GetProperty("Message");
                            string msg = propMsg != null ? Convert.ToString(propMsg.GetValue(resObj, null)) : "Error saving item.";
                            errorMessages.Add(msg);
                        }
                    }
                }

                if (successCount > 0 && errorMessages.Count == 0)
                {
                    return new
                    {
                        Status = true,
                        Message = string.Format("Successfully saved {0} machine allotment slip(s)!", successCount)
                    };
                }
                else if (successCount > 0)
                {
                    return new
                    {
                        Status = true,
                        Message = string.Format("Saved {0} slip(s), but encountered issues: {1}", successCount, string.Join("; ", errorMessages))
                    };
                }
                else
                {
                    return new
                    {
                        Status = false,
                        Message = "Failed to save slips: " + string.Join("; ", errorMessages)
                    };
                }
            }
            catch (Exception ex)
            {
                return new { Status = false, Message = "Error saving bulk machine details: " + ex.Message };
            }
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object GetProductionOrderSubDetails(long productionOrderDetailID)
        {
            try
            {
                var list = new List<object>();
                string connectionString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(connectionString))
                {
                    con.Open();
                    EnsureProductionOrderSubDetailTableExists(con);

                    string sql = @"
                        SELECT 
                            ProductionOrderSubDetailID,
                            ProductionOrderID,
                            ProductionOrderDetailID,
                            CONVERT(varchar(10), ProductionDate, 103) AS ProductionDate,
                            MachineNumber,
                            PCS,
                            CreatedByUserID,
                            CompanyId,
                            CONVERT(varchar(16), DateandTime, 120) AS DateandTime
                        FROM ProductionOrderSubDetail
                        WHERE ProductionOrderDetailID = @ProductionOrderDetailID
                          AND ISNULL(IsActive, 1) = 1
                        ORDER BY ProductionOrderSubDetailID DESC";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.AddWithValue("@ProductionOrderDetailID", productionOrderDetailID);

                        using (SqlDataReader dr = cmd.ExecuteReader())
                        {
                            while (dr.Read())
                            {
                                list.Add(new
                                {
                                    ProductionOrderSubDetailID = Convert.ToInt64(dr["ProductionOrderSubDetailID"]),
                                    ProductionOrderID = Convert.ToInt64(dr["ProductionOrderID"]),
                                    ProductionOrderDetailID = Convert.ToInt64(dr["ProductionOrderDetailID"]),
                                    ProductionDate = dr["ProductionDate"].ToString(),
                                    MachineNumber = Convert.ToInt32(dr["MachineNumber"]),
                                    PCS = Convert.ToDecimal(dr["PCS"]),
                                    CreatedByUserID = dr["CreatedByUserID"] != DBNull.Value ? Convert.ToInt64(dr["CreatedByUserID"]) : (long?)null,
                                    CompanyId = dr["CompanyId"] != DBNull.Value ? Convert.ToInt64(dr["CompanyId"]) : (long?)null,
                                    DateandTime = dr["DateandTime"].ToString()
                                });
                            }
                        }
                    }
                }

                return new { Status = true, Data = list };
            }
            catch (Exception ex)
            {
                return new { Status = false, Message = ex.Message, Data = new List<object>() };
            }
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object DeleteProductionOrderSubDetail(long productionOrderSubDetailID)
        {
            try
            {
                string connectionString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(connectionString))
                {
                    con.Open();
                    EnsureProductionOrderSubDetailTableExists(con);

                    // Pre-flight dependency check against Jobber Outward or Process Transaction Details
                    int depCount = 0;
                    try
                    {
                        using (SqlCommand cmdCheck = new SqlCommand(@"
                            SELECT 
                                (SELECT COUNT(1) FROM JobberOutwardDetail WHERE ProductionOrderSubDetailID = @SubDetailID) +
                                (SELECT COUNT(1) FROM ProcessTransactionDetail WHERE ProductionOrderSubDetailID = @SubDetailID)
                        ", con))
                        {
                            cmdCheck.Parameters.AddWithValue("@SubDetailID", productionOrderSubDetailID);
                            depCount = Convert.ToInt32(cmdCheck.ExecuteScalar());
                        }
                    }
                    catch { }

                    if (depCount > 0)
                    {
                        return new { Status = false, Message = "This record cannot be deleted because it is already associated with existing transactions or related records." };
                    }

                    string sql = "UPDATE ProductionOrderSubDetail SET IsActive = 0 WHERE ProductionOrderSubDetailID = @SubDetailID";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.AddWithValue("@SubDetailID", productionOrderSubDetailID);
                        cmd.ExecuteNonQuery();
                    }
                }

                return new { Status = true, Message = "Record deleted successfully!" };
            }
            catch (Exception ex)
            {
                return new { Status = false, Message = ex.Message };
            }
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object GetSaleOrderJobberReport(string dateFrom, string dateTo, string jobberId, string statusFilter)
        {
            try
            {
                var listOrders = new List<object>();
                var listJobbers = new List<object>();
                var listParties = new List<object>();

                int userAccountId = 0;
                int partyId = 0;
                string userRole = "";
                bool isJobWork = false;

                string connectionString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(connectionString))
                {
                    con.Open();

                    // Retrieve Logged-in User Info & Role
                    if (Context.Request.Cookies["UserIDs"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
                    {
                        string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                        if (cookieVal.Contains("="))
                        {
                            int.TryParse(cookieVal.Split('=')[1], out userAccountId);
                        }
                        else
                        {
                            int.TryParse(cookieVal, out userAccountId);
                        }
                    }

                    if (userAccountId > 0)
                    {
                        using (SqlCommand cmdUser = new SqlCommand(@"
                            SELECT 
                                ISNULL(PartyId, 0) AS PartyId,
                                ISNULL(UserRole, '') AS UserRole
                            FROM UserAccountMaster
                            WHERE UserAccountId = @UserAccountId", con))
                        {
                            cmdUser.Parameters.AddWithValue("@UserAccountId", userAccountId);
                            using (SqlDataReader drUser = cmdUser.ExecuteReader())
                            {
                                if (drUser.Read())
                                {
                                    partyId = Convert.ToInt32(drUser["PartyId"]);
                                    userRole = drUser["UserRole"].ToString().Trim();
                                }
                            }
                        }
                    }

                    isJobWork = string.Equals(userRole, "Job Work", StringComparison.OrdinalIgnoreCase);

                    // 1. Get Jobber Dropdown List
                    try
                    {
                        string sqlJobbers = @"
                            SELECT DISTINCT 
                                Id AS JobberID, 
                                PartyName AS JobberName 
                            FROM JobberMaster 
                            WHERE PartyName IS NOT NULL AND PartyName <> ''";

                        if (isJobWork && partyId > 0)
                        {
                            sqlJobbers += " AND Id = @UserPartyId";
                        }
                        sqlJobbers += " ORDER BY PartyName";

                        using (SqlCommand cmdJ = new SqlCommand(sqlJobbers, con))
                        {
                            if (isJobWork && partyId > 0)
                            {
                                cmdJ.Parameters.AddWithValue("@UserPartyId", partyId);
                            }
                            using (SqlDataReader drJ = cmdJ.ExecuteReader())
                            {
                                while (drJ.Read())
                                {
                                    listJobbers.Add(new
                                    {
                                        JobberID = Convert.ToInt64(drJ["JobberID"]),
                                        JobberName = drJ["JobberName"].ToString()
                                    });
                                }
                            }
                        }
                    }
                    catch (Exception exJ) { }

                    // 2. Get Party Dropdown List
                    try
                    {
                        string sqlParties = @"
                            SELECT DISTINCT 
                                PartyID, 
                                PartyName 
                            FROM PartyMaster 
                            WHERE PartyName IS NOT NULL AND PartyName <> ''
                            ORDER BY PartyName";
                        using (SqlCommand cmdP = new SqlCommand(sqlParties, con))
                        {
                            using (SqlDataReader drP = cmdP.ExecuteReader())
                            {
                                while (drP.Read())
                                {
                                    listParties.Add(new
                                    {
                                        PartyID = Convert.ToInt64(drP["PartyID"]),
                                        PartyName = drP["PartyName"].ToString()
                                    });
                                }
                            }
                        }
                    }
                    catch (Exception exP) { }

                    // 3. Main Query for Sale Orders & Jobber Assignment (Itemized sub-details)
                    string sql = @"
                        WITH SOD_Seq AS (
                            SELECT 
                                sod.*,
                                DENSE_RANK() OVER (PARTITION BY sod.SaleOrderID ORDER BY sod.DetailID) AS DesignSeq
                            FROM SaleOrderDetails sod
                        ),
                        SOSD_Seq AS (
                            SELECT 
                                sods.*,
                                ROW_NUMBER() OVER (PARTITION BY sods.DetailID ORDER BY sods.SubDetailID) AS ColourSeq
                            FROM SaleOrderSubDetails sods
                        ),
                        BaseItems AS (
                            SELECT 
                                so.SaleOrderID,
                                ISNULL(so.OrderNo, CAST(so.SaleOrderID AS VARCHAR(50))) AS OrderNo,
                                so.OrderDate,
                                CONVERT(VARCHAR(10), so.OrderDate, 103) AS OrderDateFormatted,
                                so.PartyID,
                                ISNULL(pm.PartyName, '') AS PartyName,
                                sod.DetailID,
                                ISNULL(sods.SubDetailID, 0) AS SubDetailID,
                                ISNULL(sod.DesignNo, '') AS DesignNo,
                                ISNULL(sods.ColourID, sod.DesignColorMatchingID) AS ColourMatchingID,
                                ISNULL(sods.ColourName, '') AS ColourName,
                                ISNULL(sods.Qty, ISNULL(sod.Qty, 0)) AS TotalItemQty,
                                ISNULL(sod.Rate, 0) AS Rate,
                                ISNULL(sod.DesignSeq, 1) AS DesignSeq,
                                ISNULL(sods.ColourSeq, 1) AS ColourSeq
                            FROM SaleOrder so
                            LEFT JOIN PartyMaster pm ON so.PartyID = pm.PartyID
                            INNER JOIN SOD_Seq sod ON so.SaleOrderID = sod.SaleOrderID
                            LEFT JOIN SOSD_Seq sods ON sod.DetailID = sods.DetailID
                        ),
                        AllottedRows AS (
                            SELECT 
                                b.SaleOrderID,
                                b.OrderNo,
                                b.OrderDate,
                                b.OrderDateFormatted,
                                b.PartyID,
                                b.PartyName,
                                b.DetailID,
                                b.SubDetailID,
                                b.DesignNo,
                                b.ColourMatchingID,
                                b.ColourName,
                                ISNULL(pod.ProductionPCS, 0) AS TotalOrderPcs,
                                ISNULL(pod.ProductionPCS, 0) AS AlreadyProducedPcs,
                                CAST(0 AS DECIMAL(18,2)) AS PendingPcs,
                                b.Rate,
                                b.DesignSeq,
                                b.ColourSeq,
                                ISNULL(pom.JobWorkerID, 0) AS JobWorkerID,
                                ISNULL(jm.PartyName, ISNULL(pom.JobWorkerName, 'Not Assigned')) AS JobWorkerName,
                                ISNULL(pom.ProductionOrderNo, '') AS ProductionOrderNo,
                                ISNULL(CONVERT(VARCHAR(10), pom.ProductionOrderDate, 103), '') AS AssignmentDateFormatted,
                                'ALLOTTED' AS AssignmentStatus,
                                1 AS RowType
                            FROM BaseItems b
                            INNER JOIN ProductionOrderDetail pod ON (
                                (b.SubDetailID > 0 AND pod.SubDetailID = b.SubDetailID)
                                OR ((b.SubDetailID IS NULL OR b.SubDetailID = 0) AND pod.SalesOrderDetailID = b.DetailID)
                            )
                            INNER JOIN ProductionOrderMaster pom ON pod.ProductionOrderID = pom.ProductionOrderID
                            LEFT JOIN JobberMaster jm ON pom.JobWorkerID = jm.Id
                            WHERE ISNULL(pod.IsActive, 1) = 1 AND ISNULL(pom.IsActive, 1) = 1
                        ),
                        PendingSummary AS (
                            SELECT 
                                DetailID,
                                SubDetailID,
                                SUM(TotalOrderPcs) AS SumAllottedPcs
                            FROM AllottedRows
                            GROUP BY DetailID, SubDetailID
                        ),
                        PendingRows AS (
                            SELECT 
                                b.SaleOrderID,
                                b.OrderNo,
                                b.OrderDate,
                                b.OrderDateFormatted,
                                b.PartyID,
                                b.PartyName,
                                b.DetailID,
                                b.SubDetailID,
                                b.DesignNo,
                                b.ColourMatchingID,
                                b.ColourName,
                                (b.TotalItemQty - ISNULL(ps.SumAllottedPcs, 0)) AS TotalOrderPcs,
                                CAST(0 AS DECIMAL(18,2)) AS AlreadyProducedPcs,
                                (b.TotalItemQty - ISNULL(ps.SumAllottedPcs, 0)) AS PendingPcs,
                                b.Rate,
                                b.DesignSeq,
                                b.ColourSeq,
                                CAST(0 AS BIGINT) AS JobWorkerID,
                                'Not Assigned' AS JobWorkerName,
                                '' AS ProductionOrderNo,
                                '' AS AssignmentDateFormatted,
                                'PENDING' AS AssignmentStatus,
                                2 AS RowType
                            FROM BaseItems b
                            LEFT JOIN PendingSummary ps ON b.DetailID = ps.DetailID AND b.SubDetailID = ps.SubDetailID
                            WHERE (b.TotalItemQty - ISNULL(ps.SumAllottedPcs, 0)) > 0
                        ),
                        CombinedData AS (
                            SELECT * FROM AllottedRows
                            UNION ALL
                            SELECT * FROM PendingRows
                        )
                        SELECT * FROM CombinedData WHERE 1=1";

                    // Handle Jobber Role default vs Explicit Jobber Filter
                    if (isJobWork && partyId > 0 && (string.IsNullOrEmpty(jobberId) || jobberId == "ALL"))
                    {
                        sql += " AND JobWorkerID = @LoggedInPartyId";
                    }
                    else if (!string.IsNullOrEmpty(jobberId) && jobberId != "ALL")
                    {
                        if (jobberId.Equals("UNASSIGNED", StringComparison.OrdinalIgnoreCase) || jobberId.Equals("PENDING", StringComparison.OrdinalIgnoreCase))
                        {
                            sql += " AND (JobWorkerID IS NULL OR JobWorkerID = 0) AND (ProductionOrderNo IS NULL OR LEN(ProductionOrderNo) = 0)";
                        }
                        else
                        {
                            long reqJid;
                            if (long.TryParse(jobberId, out reqJid))
                            {
                                sql += " AND JobWorkerID = @ReqJobberId";
                            }
                        }
                    }

                    // Handle Status Filter
                    if (!string.IsNullOrEmpty(statusFilter) && statusFilter != "ALL")
                    {
                        if (statusFilter.Equals("ALLOTTED", StringComparison.OrdinalIgnoreCase) || statusFilter.Equals("Assigned", StringComparison.OrdinalIgnoreCase))
                        {
                            sql += " AND AssignmentStatus = 'ALLOTTED'";
                        }
                        else if (statusFilter.Equals("PENDING", StringComparison.OrdinalIgnoreCase) || statusFilter.Equals("Unassigned", StringComparison.OrdinalIgnoreCase))
                        {
                            sql += " AND AssignmentStatus = 'PENDING'";
                        }
                    }

                    if (!string.IsNullOrEmpty(dateFrom))
                    {
                        DateTime dtFrom;
                        if (DateTime.TryParse(dateFrom, out dtFrom))
                        {
                            sql += " AND OrderDate >= @DateFrom";
                        }
                    }
                    if (!string.IsNullOrEmpty(dateTo))
                    {
                        DateTime dtTo;
                        if (DateTime.TryParse(dateTo, out dtTo))
                        {
                            sql += " AND OrderDate <= @DateTo";
                        }
                    }

                    sql += " ORDER BY SaleOrderID DESC, DetailID ASC, SubDetailID ASC, RowType ASC";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        if (isJobWork && partyId > 0 && (string.IsNullOrEmpty(jobberId) || jobberId == "ALL"))
                        {
                            cmd.Parameters.AddWithValue("@LoggedInPartyId", partyId);
                        }
                        else if (!string.IsNullOrEmpty(jobberId) && jobberId != "ALL" && !jobberId.Equals("UNASSIGNED", StringComparison.OrdinalIgnoreCase))
                        {
                            long reqJid;
                            if (long.TryParse(jobberId, out reqJid))
                            {
                                cmd.Parameters.AddWithValue("@ReqJobberId", reqJid);
                            }
                        }

                        if (!string.IsNullOrEmpty(dateFrom))
                        {
                            DateTime dtFrom;
                            if (DateTime.TryParse(dateFrom, out dtFrom))
                            {
                                cmd.Parameters.AddWithValue("@DateFrom", dtFrom.Date);
                            }
                        }
                        if (!string.IsNullOrEmpty(dateTo))
                        {
                            DateTime dtTo;
                            if (DateTime.TryParse(dateTo, out dtTo))
                            {
                                cmd.Parameters.AddWithValue("@DateTo", dtTo.Date.AddDays(1).AddTicks(-1));
                            }
                        }

                        using (SqlDataReader dr = cmd.ExecuteReader())
                        {
                            while (dr.Read())
                            {
                                string jobWorkerName = dr["JobWorkerName"].ToString();
                                long jobWorkerId = Convert.ToInt64(dr["JobWorkerID"]);
                                string status = dr["AssignmentStatus"].ToString();

                                listOrders.Add(new
                                {
                                    SaleOrderID = Convert.ToInt64(dr["SaleOrderID"]),
                                    OrderNo = dr["OrderNo"].ToString(),
                                    OrderDate = dr["OrderDateFormatted"].ToString(),
                                    PartyID = dr["PartyID"] != DBNull.Value ? Convert.ToInt64(dr["PartyID"]) : 0,
                                    PartyName = dr["PartyName"].ToString(),
                                    DetailID = Convert.ToInt64(dr["DetailID"]),
                                    SubDetailID = dr["SubDetailID"] != DBNull.Value ? Convert.ToInt64(dr["SubDetailID"]) : 0,
                                    DesignNo = dr["DesignNo"].ToString(),
                                    ColourMatchingID = dr["ColourMatchingID"] != DBNull.Value ? Convert.ToInt64(dr["ColourMatchingID"]) : 0,
                                    ColourName = dr["ColourName"].ToString(),
                                    TotalOrderPcs = Convert.ToDecimal(dr["TotalOrderPcs"]),
                                    AlreadyProducedPcs = Convert.ToDecimal(dr["AlreadyProducedPcs"]),
                                    PendingPcs = Convert.ToDecimal(dr["PendingPcs"]),
                                    Rate = Convert.ToDecimal(dr["Rate"]),
                                    DesignSeq = Convert.ToInt32(dr["DesignSeq"]),
                                    ColourSeq = Convert.ToInt32(dr["ColourSeq"]),
                                    JobWorkerID = jobWorkerId,
                                    JobWorkerName = string.IsNullOrEmpty(jobWorkerName) ? "Not Assigned" : jobWorkerName,
                                    ProductionOrderNo = dr["ProductionOrderNo"].ToString(),
                                    AssignmentDate = dr["AssignmentDateFormatted"].ToString(),
                                    AssignmentStatus = status
                                });
                            }
                        }
                    }
                }

                return new
                {
                    Status = true,
                    Data = listOrders,
                    Jobbers = listJobbers,
                    Parties = listParties
                };
            }
            catch (Exception ex)
            {
                return new { Status = false, Message = ex.Message };
            }
        }

