        #region Audit Log Web Method
        [WebMethod(EnableSession = true)]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void GetAuditLogs(string fromDate, string toDate, int? userId, string module, string action, string tableName, string recordId, string search, int pageNumber, int pageSize)
        {
            AuditLogHelper.EnsureAuditTablesExist();
            DataTable dt = new DataTable();
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection conn = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand("sp_GetAuditLogs", conn))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    DateTime? parsedFrom = null;
                    if (!string.IsNullOrEmpty(fromDate))
                    {
                        if (DateTime.TryParse(fromDate, CultureInfo.InvariantCulture, DateTimeStyles.None, out DateTime dtFrom))
                            parsedFrom = dtFrom;
                        else if (DateTime.TryParse(fromDate, out dtFrom))
                            parsedFrom = dtFrom;
                    }

                    DateTime? parsedTo = null;
                    if (!string.IsNullOrEmpty(toDate))
                    {
                        if (DateTime.TryParse(toDate, CultureInfo.InvariantCulture, DateTimeStyles.None, out DateTime dtTo))
                            parsedTo = dtTo;
                        else if (DateTime.TryParse(toDate, out dtTo))
                            parsedTo = dtTo;
                    }

                    cmd.Parameters.AddWithValue("@FromDate", (object)parsedFrom ?? DBNull.Value);
                    cmd.Parameters.AddWithValue("@ToDate", (object)parsedTo ?? DBNull.Value);
                    cmd.Parameters.AddWithValue("@UserAccountID", userId.HasValue && userId > 0 ? (object)userId.Value : DBNull.Value);
                    cmd.Parameters.AddWithValue("@ModuleName", string.IsNullOrEmpty(module) ? (object)DBNull.Value : module);
                    cmd.Parameters.AddWithValue("@ActionName", string.IsNullOrEmpty(action) ? (object)DBNull.Value : action);
                    cmd.Parameters.AddWithValue("@TableName", string.IsNullOrEmpty(tableName) ? (object)DBNull.Value : tableName);
                    cmd.Parameters.AddWithValue("@RecordID", string.IsNullOrEmpty(recordId) ? (object)DBNull.Value : recordId);
                    cmd.Parameters.AddWithValue("@SearchKeyword", string.IsNullOrEmpty(search) ? (object)DBNull.Value : search);
                    cmd.Parameters.AddWithValue("@PageNumber", pageNumber < 1 ? 1 : pageNumber);
                    cmd.Parameters.AddWithValue("@PageSize", pageSize < 1 ? 50 : pageSize);

                    SqlDataAdapter da = new SqlDataAdapter(cmd);
                    da.Fill(dt);
                }


                List<Dictionary<string, object>> rows = new List<Dictionary<string, object>>();
                foreach (DataRow dr in dt.Rows)
                {
                    Dictionary<string, object> row = new Dictionary<string, object>();
                    foreach (DataColumn col in dt.Columns)
                    {
                        row.Add(col.ColumnName, dr[col] == DBNull.Value ? null : dr[col]);
                    }
                    rows.Add(row);
                }

                Context.Response.ContentType = "application/json";
                Context.Response.Write(JsonConvert.SerializeObject(rows));
            }
        }

        [WebMethod(EnableSession = true)]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string LogErrorRecord(string moduleName, string methodName, string errorMessage, string stackTrace)
        {
            try
            {
                Exception dummyEx = !string.IsNullOrEmpty(stackTrace) ? new Exception(errorMessage) : null;
                AuditLogHelper.LogError(moduleName ?? "Web App", methodName ?? "Client Request", dummyEx ?? new Exception(errorMessage ?? "Client Error"), stackTrace);
                return "logged";
            }
            catch
            {
                return "error";
            }
        }

