                            if (master != null)
                            {
                                YarnPODetails detail =
                                    new YarnPODetails();

                                detail.YarnPODetailID =
                                    rdr["YarnPODetailID"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["YarnPODetailID"])
                                    : 0;

                                detail.YarnPOID =
                                    rdr["YarnPOID"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["YarnPOID"])
                                    : 0;

                                detail.YarnMaterialID =
                                    rdr["YarnMaterialID"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["YarnMaterialID"])
                                    : 0;

                                detail.YarnMaterial =
                                    rdr["YarnMaterial"]?.ToString().ToUpper() ?? "";

                                detail.YarnColorID =
                                    rdr["YarnColorID"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["YarnColorID"])
                                    : 0;

                                detail.YarnColor =
                                    rdr["YarnColor"]?.ToString().ToUpper() ?? "";

                                detail.YarnColorCode =
                                    rdr["YarnColorCode"]?.ToString().ToUpper() ?? "";

                                detail.CompanyCode =
                                    rdr["CompanyCode"]?.ToString().ToUpper() ?? "";

                                detail.Qty =
                                    rdr["Qty"] != DBNull.Value
                                    ? Convert.ToDecimal(rdr["Qty"])
                                    : 0;

                                detail.Rate =
                                    rdr["Rate"] != DBNull.Value
                                    ? Convert.ToDecimal(rdr["Rate"])
                                    : 0;

                                detail.GSTSLABId =
                                    rdr["GSTSLABId"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["GSTSLABId"])
                                    : 0;

                                detail.GSTSLABName =
                                    rdr["GSTSLABName"]?.ToString().ToUpper() ?? "";

                                detail.Amount =
                                    rdr["Amount"] != DBNull.Value
                                    ? Convert.ToDecimal(rdr["Amount"])
                                    : 0;

                                master.listYarnPODetails.Add(detail);
                            }
                        }
                    }
                }
            }

            return list;
        }
        private Cell BodyCell(string text, TextAlignment align)
        {
            iText.Layout.Element.Paragraph p = new iText.Layout.Element.Paragraph(text ?? "")
                .SetFontSize(8)
                .SetMargin(0)
                .SetPadding(0)
                .SetMultipliedLeading(1);

            return new Cell()
                .Add(p)
                .SetPaddingTop(3)
                .SetPaddingBottom(3)
                .SetPaddingLeft(3)
                .SetPaddingRight(3)
                .SetTextAlignment(align)
                .SetVerticalAlignment(VerticalAlignment.MIDDLE)
                .SetBorderLeft(new SolidBorder(0.8f))
                .SetBorderRight(new SolidBorder(0.8f))
                .SetBorderBottom(iText.Layout.Borders.Border.NO_BORDER)
                .SetBorderTop(iText.Layout.Borders.Border.NO_BORDER);
        }
        public string CreatePDF(List<YarnPOMaster> data)
        {
            string dir =
                HttpContext.Current.Server.MapPath("~/GeneratedPDF/");

            if (!Directory.Exists(dir))
                Directory.CreateDirectory(dir);

            string fileName =
                $"YarnPO_{DateTime.Now:yyyyMMddHHmmss}.pdf";

            string filePath =
                System.IO.Path.Combine(dir, fileName);
            iText.Kernel.Pdf.PdfWriter writer = new iText.Kernel.Pdf.PdfWriter(filePath);

            iText.Kernel.Pdf.PdfDocument pdf =
                new iText.Kernel.Pdf.PdfDocument(writer);

            pdf.SetDefaultPageSize(iText.Kernel.Geom.PageSize.A4);

            iText.Layout.Document document =
                new iText.Layout.Document(pdf);

            document.SetMargins(10, 10, 10, 10);

            iText.Kernel.Font.PdfFont normalFont;
            iText.Kernel.Font.PdfFont boldFont;

            // =====================================================
            // FONT
            // =====================================================

            try
            {
                string f1 =
                    HttpContext.Current.Server.MapPath(
                        "~/fonts/arial.ttf"
                    );

                string f2 =
                    HttpContext.Current.Server.MapPath(
                        "~/fonts/arialbd.ttf"
                    );

                if (File.Exists(f1) && File.Exists(f2))
                {
                    normalFont = PdfFontFactory.CreateFont(f1, iText.IO.Font.PdfEncodings.IDENTITY_H);
                    boldFont = PdfFontFactory.CreateFont(f2, iText.IO.Font.PdfEncodings.IDENTITY_H);
                }
                else
                {
                    normalFont =
                        PdfFontFactory.CreateFont(
                            StandardFonts.HELVETICA
                        );

                    boldFont =
                        PdfFontFactory.CreateFont(
                            StandardFonts.HELVETICA_BOLD
                        );
                }
            }
            catch
            {
                normalFont =
                    PdfFontFactory.CreateFont(
                        StandardFonts.HELVETICA
                    );

                boldFont =
                PdfFontFactory.CreateFont(
                        StandardFonts.HELVETICA_BOLD
                    );
            }

            document.SetFont(normalFont);
            document.SetFontSize(9);

            string Safe(string s)
            {
                return s ?? "";
            }

            foreach (var item in data)
            {
                // =====================================================
                // HEADER
                // =====================================================

                iText.Layout.Element.Table header =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 1 }
                        )
                    ).UseAllAvailableWidth();

                Cell headCell = new Cell();

                headCell.Add(
                    new iText.Layout.Element.Paragraph("PURCHASE ORDER")
                    .SetFont(boldFont)
                    .SetFontSize(10)
                    .SetTextAlignment(TextAlignment.LEFT)
                );

                headCell.Add(
                    new iText.Layout.Element.Paragraph(Safe(item.BillToPartyName))
                    .SetFont(boldFont)
                    .SetFontSize(15)
                    .SetTextAlignment(TextAlignment.CENTER)
                );

                headCell.Add(
                    new iText.Layout.Element.Paragraph(Safe(item.BillToBillingAddress))
                    .SetTextAlignment(TextAlignment.CENTER)
                );

                headCell.Add(
                    new iText.Layout.Element.Paragraph("M - " + Safe(item.BillToMobileNo))
                    .SetFont(boldFont)
                    .SetTextAlignment(TextAlignment.CENTER)
                );

                headCell.Add(
                    new iText.Layout.Element.Paragraph("GST - " + Safe(item.BillToGSTIN))
                    .SetFont(boldFont)
                    .SetTextAlignment(TextAlignment.CENTER)
                );

                headCell.SetBorder(new SolidBorder(1));

                header.AddCell(headCell);

                document.Add(header);

                // =====================================================
                // SHIP + ORDER
                // =====================================================

                iText.Layout.Element.Table ship =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 50, 50 }
                        )
                    ).UseAllAvailableWidth();

                Cell shipLeft = new Cell();

                shipLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Shipped To Name : ").SetFont(boldFont))
                    .Add(Safe(item.GodownTitle))
                );

                shipLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Shipped To GST : ").SetFont(boldFont))
                    .Add(Safe(item.GodownGST))
                );

                shipLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Shipped To Address : ").SetFont(boldFont))
                    .Add(Safe(item.GodownAddress))
                );

                ship.AddCell(shipLeft);

                iText.Layout.Element.Table order =
                    new iText.Layout.Element.Table(1)
                    .UseAllAvailableWidth();

                order.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph()
                        .Add(new Text("ORDER DATE : ").SetFont(boldFont))
                        .Add(Safe(item.PODates))
                    )
                    .SetBorder(iText.Layout.Borders.Border.NO_BORDER)
                );

                order.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph()
                        .Add(new Text("ORDER NUMBER : ").SetFont(boldFont))
                        .Add(item.PONo.ToString())
                    )
                    .SetBorder(iText.Layout.Borders.Border.NO_BORDER)
                );

                ship.AddCell(new Cell().Add(order));

                document.Add(ship);

                // =====================================================
                // VENDOR
                // =====================================================

                iText.Layout.Element.Table vendor =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 50, 50 }
                        )
                    ).UseAllAvailableWidth();

                Cell vendorLeft = new Cell();

                vendorLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Vendor : ").SetFont(boldFont))
                    .Add(Safe(item.SupplierPartyName))
                );

                vendorLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("GST : ").SetFont(boldFont))
                    .Add(Safe(item.SupplierGSTIN))
                );

                vendorLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Address : ").SetFont(boldFont))
                    .Add(Safe(item.SupplierBillingAddress))
                );

                vendorLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Mobile : ").SetFont(boldFont))
                    .Add(Safe(item.SupplierMobileNo))
                );

                vendor.AddCell(vendorLeft);

                Cell vendorRight = new Cell();

                vendorRight.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Company Name : ").SetFont(boldFont))
                    .Add(Safe(item.CompanyPartyName))
                );

                vendorRight.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Company GST : ").SetFont(boldFont))
                    .Add(Safe(item.CompanyGSTIN))
                );

                vendorRight.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Company Address : ").SetFont(boldFont))
                    .Add(Safe(item.CompanyBillingAddress))
                );

                vendor.AddCell(vendorRight);

                document.Add(vendor);

                // =====================================================
                // ITEM TABLE
                // =====================================================

                float[] cols = { 8, 25, 18, 15, 10, 12, 12, 15 };

                iText.Layout.Element.Table table =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(cols)
                    )
                    .UseAllAvailableWidth();

                table.SetFixedLayout();
                table.SetFontSize(8);
                table.SetMinHeight(300);

                // =====================================================
                // HEADER
                // =====================================================

                string[] headers =
                {
            "SR",
            "Quality",
            "Colour",
            "Code",
            "Qty",
            "Rate",
            "GST %",
            "Amount"
        };

                foreach (var h in headers)
                {
                    table.AddHeaderCell(
                        new Cell()
                        .Add(
                            new iText.Layout.Element.Paragraph(h)
                            .SetFont(boldFont)
                            .SetFontSize(8)
                            .SetMargin(0)
                        )
                        .SetPadding(2)
                        .SetTextAlignment(TextAlignment.CENTER)
                        .SetVerticalAlignment(VerticalAlignment.MIDDLE)
                        .SetBackgroundColor(ColorConstants.LIGHT_GRAY)
                        .SetBorder(new SolidBorder(1))
                    );
                }

                // =====================================================
                // DATA ROWS
                // =====================================================

                decimal total = 0;
                decimal gstAmount = 0;

                int currentRows = 0;

                if (item.listYarnPODetails != null)
                {
                    int Row = 1;

                    foreach (var d in item.listYarnPODetails)
                    {
                        decimal gstPer = 0;

                        string gstText = d.GSTSLABName ?? "";

                        // KEEP ONLY NUMBERS + DOT
                        gstText = new string(
                            gstText
                            .Where(c => char.IsDigit(c) || c == '.')
                            .ToArray()
                        );

                        decimal.TryParse(gstText, out gstPer);

                        decimal rowGST =
                            (d.Amount * gstPer) / 100;

                        gstAmount += rowGST;

                        table.AddCell(
                            BodyCell(Row.ToString(), TextAlignment.CENTER)
                        );

                        table.AddCell(
                            BodyCell(Safe(d.YarnMaterial), TextAlignment.LEFT)
                        );

                        table.AddCell(
                            BodyCell(Safe(d.YarnColor), TextAlignment.LEFT)
                        );

                        table.AddCell(
                            BodyCell(Safe(d.CompanyCode), TextAlignment.LEFT)
                        );

                        table.AddCell(
                            BodyCell(
                                d.Qty.ToString("N2"),
                                TextAlignment.CENTER
                            )
                        );

                        table.AddCell(
                            BodyCell(
                                d.Rate.ToString("N2"),
                                TextAlignment.RIGHT
                            )
                        );

                        table.AddCell(
                            BodyCell(
                                gstPer.ToString("0.##") + "%",
                                TextAlignment.CENTER
                            )
                        );

                        table.AddCell(
                            BodyCell(
                                d.Amount.ToString("N2"),
                                TextAlignment.RIGHT
                            )
                        );

                        total += d.Amount;

                        Row++;
                        currentRows++;
                    }
                }

                // =====================================================
                // EMPTY ROWS
                // =====================================================

                int maxRows = 23;

                for (int i = currentRows; i < maxRows; i++)
                {
                    bool isLastRow = (i == maxRows - 1);

                    for (int c = 0; c < 8; c++)
                    {
                        table.AddCell(
                            new Cell()
                            .Add(
                                new iText.Layout.Element.Paragraph(" ")
                                .SetFontSize(8)
                                .SetMargin(0)
                            )
                            .SetHeight(16)
                            .SetPadding(0)
                            .SetBorderLeft(new SolidBorder(1))
                            .SetBorderRight(new SolidBorder(1))
                            .SetBorderTop(iText.Layout.Borders.Border.NO_BORDER)
                            .SetBorderBottom(
                                isLastRow
                                ? new SolidBorder(1)
                                : iText.Layout.Borders.Border.NO_BORDER
                            )
                        );
                    }
                }

                document.Add(table);

                // =====================================================
                // TOTAL
                // =====================================================

                decimal grandTotal = total + gstAmount;
                iText.Layout.Element.Table totalOuter =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 100 }
                        )
                    ).UseAllAvailableWidth();

                iText.Layout.Element.Table right =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 60, 40 }
                        )
                    ).UseAllAvailableWidth();

                right.AddCell(new Cell().Add(new iText.Layout.Element.Paragraph("Total Taxable Amount :").SetFont(boldFont)).SetBorder(iText.Layout.Borders.Border.NO_BORDER));
                right.AddCell(new Cell().Add(new iText.Layout.Element.Paragraph(total.ToString("N2")).SetTextAlignment(TextAlignment.RIGHT)).SetBorder(iText.Layout.Borders.Border.NO_BORDER));

                right.AddCell(new Cell().Add(
                        new iText.Layout.Element.Paragraph("GST Amount :")
                        .SetFont(boldFont)
                    )
                    .SetBorder(iText.Layout.Borders.Border.NO_BORDER)
                );

                right.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph(gstAmount.ToString("N2"))
                        .SetTextAlignment(TextAlignment.RIGHT)
                    )
                    .SetBorder(iText.Layout.Borders.Border.NO_BORDER)
                );

                right.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph("Grand Total :")
                        .SetFont(boldFont)
                    )
                    .SetBorder(iText.Layout.Borders.Border.NO_BORDER)
                );

                right.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph(grandTotal.ToString("N2"))
                        .SetFont(boldFont)
                        .SetTextAlignment(TextAlignment.RIGHT)
                    )
                    .SetBorder(iText.Layout.Borders.Border.NO_BORDER)
                );

                totalOuter.AddCell(
                    new Cell()
                    .Add(right)
                    .SetBorder(new SolidBorder(1))
                );

                document.Add(totalOuter);

                // =====================================================
                // PAGE BREAK
                // =====================================================

                if (!item.Equals(data.Last()))
                {
                    document.Add(
                        new AreaBreak(AreaBreakType.NEXT_PAGE)
                    );
                }
            }

            document.Close();

            return "/GeneratedPDF/" + fileName;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void YarnPendingPOReport()
        {
            JavaScriptSerializer js;
            List<YarnPOMaster> listUser = new List<YarnPOMaster>();
            YarnPOMasterResponse response = new YarnPOMasterResponse();

            var request = HttpContext.Current.Request;
            YarnPOMaster ilist = new YarnPOMaster();
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                //cmd.CommandText = "select PM.* from PartyMaster PM LEFT JOIN CompanyMaster CM ON PM.CompanyId = CM.CompanyId where CM.is_default = '1' and PM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " and PM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1) order by PM.PartyId desc OFFSET " + ilist.startFrom.ToString() + " ROWS FETCH NEXT 10 ROWS ONLY";
                cmd.CommandText = "SELECT YPM.PONo, YPM.PODate, " +
                    " YPM.SupplierPartyName, YPM.SupplierMobileNo, YPM.SupplierAlterMobileNo, " +
                    " YPM.BillToPartyName, YPM.BillToMobileNo, YPM.BillToAlterMobileNo, YPM.BillToEmail, " +
                    " YPM.CompanyPartyName, YPM.CompanyMobileNo, YPM.CompanyAlterMobileNo, YPM.CompanyEmail, " +
                    " YPM.ShippedToPartyName, YPM.ShippedToMobileNo, YPM.ShippedToAlterMobileNo, YPM.ShippedToEmail," +
                    " YPM.GodownTitle, YPM.GodownAddress, YMM.YarnMaterial, YCM.YarnColor, temp.* " +
                    " FROM " +
                    " ( " +
                    " 	SELECT ypd.*, ISNULL(yim.Received,0) as Received, " +
                    " 	ypd.Qty - ISNULL(yim.Received,0) as PendingQty" +
                    "  	FROM YarnPODetails ypd " +
                    " 	LEFT JOIN " +
                    " 	(" +
                    " 		SELECT SUM(TotalWeight) as Received, YarnMaterialID , YarnPODetailIDCompanyCode, IsComplete" +
                    " 		FROM YarnInwardMaster " +
                    " 		where CompanyId = (select CompanyId from CompanyMaster where is_default = 1)" +
                    " 		and FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1) " +
                    " 		and UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + "" +
                    " 		GROUP BY YarnMaterialID, YarnPODetailIDCompanyCode, IsComplete" +
                    " 	) as yim ON ypd.YarnPODetailID = yim.YarnPODetailIDCompanyCode" +
                    " ) as temp" +
                    " LEFT JOIN " +
                    " (" +
                    " 	select YPM.*," +
                    " 	SPM.PartyName as SupplierPartyName, SPM.MobileNo as SupplierMobileNo, SPM.AlterMobileNo as SupplierAlterMobileNo, " +
                    " 	BPM.PartyName as BillToPartyName, BPM.MobileNo as BillToMobileNo, BPM.AlterMobileNo as BillToAlterMobileNo, BPM.Email as BillToEmail," +
                    " 	CPM.PartyName as CompanyPartyName, CPM.MobileNo as CompanyMobileNo, CPM.AlterMobileNo as CompanyAlterMobileNo, CPM.Email as CompanyEmail," +
                    " 	SPPM.PartyName as ShippedToPartyName, SPPM.MobileNo as ShippedToMobileNo, SPPM.AlterMobileNo as ShippedToAlterMobileNo, SPPM.Email as ShippedToEmail," +
                    " 	GM.GodownTitle, GM.GodownAddress " +
                    " 	from YarnPOMaster YPM" +
                    " 	LEFT JOIN PartyMaster SPM ON YPM.SupplierPartyID = SPM.PartyId " +
                    " 	LEFT JOIN PartyMaster BPM ON YPM.BillToPartyID = BPM.PartyId " +
                    " 	LEFT JOIN PartyMaster CPM ON YPM.CompanyPartyID = CPM.PartyId" +
                    " 	LEFT JOIN PartyMaster SPPM ON YPM.ShippedToPartyID = SPPM.PartyId" +
                    " 	LEFT JOIN GodownMaster GM ON GM.GodownID = YPM.GodownID" +
                    " 	where YPM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)" +
                    " 		and YPM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)" +
                    " 		and YPM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " " +
                    " )as YPM ON YPM.YarnPOID = temp.YarnPOID" +
                    " LEFT JOIN YarnMaterialMaster YMM ON YMM.YarnMaterialID = temp.YarnMaterialID" +
                    " LEFT JOIN YarnColorMaster YCM ON YCM.YarnColorID = temp.YarnColorID";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnPOMaster condition = new YarnPOMaster();

                        condition.YarnPOID = rdr["YarnPOID"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["YarnPOID"]);
                        condition.YarnPODetailID = rdr["YarnPODetailID"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["YarnPODetailID"]);

                        if (rdr["PODate"] != DBNull.Value)
                        {
                            condition.PODate = Convert.ToDateTime(rdr["PODate"]);
                            condition.PODates = condition.PODate.ToString("dd-MM-yyyy");
                        }
                        else
                        {
                            condition.PODates = "";
                        }

                        condition.PONo = rdr["PONo"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["PONo"]);

                        condition.SupplierPartyName = rdr["SupplierPartyName"] == DBNull.Value
                            ? "" : rdr["SupplierPartyName"].ToString().ToUpper();

                        condition.SupplierMobileNo = rdr["SupplierMobileNo"] == DBNull.Value
                            ? "" : rdr["SupplierMobileNo"].ToString().ToUpper();

                        condition.SupplierAlterMobileNo = rdr["SupplierAlterMobileNo"] == DBNull.Value
                            ? "" : rdr["SupplierAlterMobileNo"].ToString().ToUpper();

                        condition.BillToPartyName = rdr["BillToPartyName"] == DBNull.Value
                            ? "" : rdr["BillToPartyName"].ToString().ToUpper();

                        condition.BillToMobileNo = rdr["BillToMobileNo"] == DBNull.Value
                            ? "" : rdr["BillToMobileNo"].ToString().ToUpper();

                        condition.BillToAlterMobileNo = rdr["BillToAlterMobileNo"] == DBNull.Value
                            ? "" : rdr["BillToAlterMobileNo"].ToString().ToUpper();

                        condition.CompanyPartyName = rdr["CompanyPartyName"] == DBNull.Value
                            ? "" : rdr["CompanyPartyName"].ToString().ToUpper();

                        condition.CompanyMobileNo = rdr["CompanyMobileNo"] == DBNull.Value
                            ? "" : rdr["CompanyMobileNo"].ToString().ToUpper();

                        condition.CompanyAlterMobileNo = rdr["CompanyAlterMobileNo"] == DBNull.Value
                            ? "" : rdr["CompanyAlterMobileNo"].ToString().ToUpper();

                        condition.ShippedToPartyName = rdr["ShippedToPartyName"] == DBNull.Value
                            ? "" : rdr["ShippedToPartyName"].ToString().ToUpper();

                        condition.ShippedToMobileNo = rdr["ShippedToMobileNo"] == DBNull.Value
                            ? "" : rdr["ShippedToMobileNo"].ToString().ToUpper();

                        condition.ShippedToAlterMobileNo = rdr["ShippedToAlterMobileNo"] == DBNull.Value
                            ? "" : rdr["ShippedToAlterMobileNo"].ToString().ToUpper();

                        condition.GodownTitle = rdr["GodownTitle"] == DBNull.Value
                            ? "" : rdr["GodownTitle"].ToString().ToUpper();

                        condition.GodownAddress = rdr["GodownAddress"] == DBNull.Value
                            ? "" : rdr["GodownAddress"].ToString().ToUpper();

                        condition.YarnMaterialID = rdr["YarnMaterialID"] == DBNull.Value
                            ? 0 : Convert.ToInt32(rdr["YarnMaterialID"]);

                        condition.YarnMaterial = rdr["YarnMaterial"] == DBNull.Value
                            ? "" : rdr["YarnMaterial"].ToString().ToUpper();

                        condition.YarnColorID = rdr["YarnColorID"] == DBNull.Value
                            ? 0 : Convert.ToInt32(rdr["YarnColorID"]);

                        condition.YarnColor = rdr["YarnColor"] == DBNull.Value
                            ? "" : rdr["YarnColor"].ToString().ToUpper();

                        condition.CompanyCode = rdr["CompanyCode"] == DBNull.Value
                            ? "" : rdr["CompanyCode"].ToString().ToUpper();

                        condition.Qty = rdr["Qty"] == DBNull.Value
                            ? 0 : Convert.ToDecimal(rdr["Qty"]);

                        condition.PendingQty = rdr["PendingQty"] == DBNull.Value
                            ? 0 : Convert.ToDecimal(rdr["PendingQty"]);

                        condition.IsComplete = rdr["IsClose"] == DBNull.Value
                            ? false : Convert.ToBoolean(rdr["IsClose"]);

                        listUser.Add(condition);
                    }
                }
                rdr.Close();
                cmd.Dispose();
                con.Close();
            }


            System.Web.HttpCookie nameCookie = new System.Web.HttpCookie("DesignColorMatchingFormIDs");
            nameCookie.Expires = DateTime.Now.AddDays(-1);
            Context.Response.Cookies.Add(nameCookie);

            response.Code = 200;
            response.Message = "Success";
            response.listYarnPOMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
        [WebMethod]
        public string EmptyLocationReport()
        {
            List<object> list = new List<object>();
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                string query = @"SELECT GL.GodownLocationID,GL.LocationTitle,GL.GodownID, 
                                GM.GodownTitle,GM.GodownAddress
                         FROM GodownLocationMaster GL
                         INNER JOIN GodownMaster GM 
                            ON GL.GodownID = GM.GodownID
                         WHERE NOT EXISTS (
                            SELECT 1 
                            FROM YarnInwardDetail YI 
                            WHERE YI.GodownLocationID = GL.GodownLocationID
                         )";

                SqlCommand cmd = new SqlCommand(query, con);
                con.Open();
                SqlDataReader dr = cmd.ExecuteReader();

                while (dr.Read())
                {
                    list.Add(new
                    {
                        GodownLocationID = dr["GodownLocationID"],
                        LocationTitle = dr["LocationTitle"].ToString(),
                        GodownID = dr["GodownID"],
                        GodownTitle = dr["GodownTitle"].ToString(),
                        GodownAddress = dr["GodownAddress"].ToString()
                    });
                }
            }

            var result = new
            {
                result = "1",
                message = "Success",
                data = list
            };

            return new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(result);
        }
        [WebMethod]
        public string YarnInterChangeReport()
        {
            try
            {
                string query = @"WITH InterchangeHistory AS (SELECT T.YarnInterchangeID,T.DateAndTime,T.YarnInwardDetailID,T.YarnMaterialID,T.YarnColorID,
        T.YarnPOID,T.GodownID,T.GodownLocationID,T.UserAccountId,YID.BoxNo,YID.NetWeight,YID.YarnInwardID,        
        LAG(T.GodownLocationID) OVER ( PARTITION BY T.YarnInwardDetailID,YID.BoxNo,T.YarnMaterialID,T.YarnColorID  ORDER BY T.YarnInterchangeID
        ) AS OldLocationID FROM YarnInterchangeMaster T
    INNER JOIN YarnInwardDetail YID ON T.YarnInwardDetailID = YID.YarnInwardDetailID)
SELECT T.YarnInterchangeID,T.DateAndTime, UA.UserAccountName AS [User],T.BoxNo AS Box,YMM.YarnMaterial AS Material,YCM.YarnColor AS Color, PM.PartyName AS Party,
    YPM.PONo AS PO,GM.GodownTitle AS Godown,GLM_OLD.LocationTitle AS [From],GLM_NEW.LocationTitle AS [To],T.NetWeight AS Wt,'YES' AS Move
FROM InterchangeHistory T
LEFT JOIN YarnMaterialMaster YMM ON T.YarnMaterialID = YMM.YarnMaterialID
LEFT JOIN YarnColorMaster YCM ON T.YarnColorID = YCM.YarnColorID
LEFT JOIN YarnInwardMaster YIM ON T.YarnInwardID = YIM.YarnInwardID
LEFT JOIN YarnPOMaster YPM ON T.YarnPOID = YPM.YarnPOID
LEFT JOIN PartyMaster PM ON YPM.BillToPartyID = PM.PartyId
LEFT JOIN GodownMaster GM ON T.GodownID = GM.GodownID
LEFT JOIN GodownLocationMaster GLM_NEW ON T.GodownLocationID = GLM_NEW.GodownLocationID
LEFT JOIN GodownLocationMaster GLM_OLD ON T.OldLocationID = GLM_OLD.GodownLocationID
LEFT JOIN UserAccountMaster UA ON T.UserAccountId = UA.UserAccountId
WHERE T.OldLocationID IS NOT NULL
ORDER BY T.BoxNo,T.DateAndTime,T.YarnInterchangeID;";

                DataTable dt = new DataTable();

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.CommandTimeout = 0;

                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            da.Fill(dt);
                        }
                    }
                }

                return JsonConvert.SerializeObject(dt);
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(new
                {
                    Status = "Error",
                    Message = ex.Message
                });
            }
        }
        [WebMethod]
        public string GetMovementHistory(int yarnDetailId)
        {
            string query = @"
    SELECT 
        YT.DateAndTime,
        LAG(GLM.LocationTitle) OVER (ORDER BY YT.YarnInterchangeID) AS FromLocation,
        GLM.LocationTitle AS ToLocation,
        YT.UserAccountId
    FROM YarnInterchangeMaster YT
    LEFT JOIN GodownLocationMaster GLM 
        ON YT.GodownLocationID = GLM.GodownLocationID
    WHERE YT.YarnInwardDetailID = @Id
    ORDER BY YT.YarnInterchangeID
    ";

            DataTable dt = new DataTable();

            using (SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
            {
                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.AddWithValue("@Id", yarnDetailId);

                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        da.Fill(dt);
                    }
                }
            }

            return JsonConvert.SerializeObject(dt);
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object GetColorMatchingReport(int pageNumber, int pageSize, string validationStatus = "", string searchText = "")
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            try
            {
                using (SqlConnection con = new SqlConnection(cs))
                {
                    int offset = (pageNumber - 1) * pageSize;

                    // =========================
                    // 🔹 MAIN QUERY
                    // =========================
                    string query = @"
WITH FormStatus AS (
    SELECT 
        DCMFM.DesignColorMatchingFormID,
        DCMFM.DesignEntryFormID,
        CASE 
            WHEN COUNT(d.DesignColorMatchingDetailsID) > 0 THEN 'Validated'
            ELSE 'Not Validated'
        END AS ValidationStatus
    FROM DesignColorMatchingFormMaster DCMFM
    LEFT JOIN DesignColorMatchingDetails d 
        ON d.DesignColorMatchingFormID = DCMFM.DesignColorMatchingFormID
        AND ISNULL(d.ColorMatchingPhoto,'') <> ''
    GROUP BY DCMFM.DesignColorMatchingFormID, DCMFM.DesignEntryFormID
),

Filtered AS (
    SELECT FS.*
    FROM FormStatus FS
    LEFT JOIN DesignEntryFormMaster DEFM 
        ON DEFM.DesignEntryFormID = FS.DesignEntryFormID

    WHERE 
        (@validationStatus = '' OR FS.ValidationStatus = @validationStatus)
        AND (
            @searchText = '' OR
            LOWER(ISNULL(DEFM.DesignNo,'')) LIKE '%' + LOWER(@searchText) + '%' OR
            LOWER(ISNULL(DEFM.DesignerCode,'')) LIKE '%' + LOWER(@searchText) + '%' OR
            LOWER(ISNULL(DEFM.DesignNo,'') + ISNULL(DEFM.DesignerCode,'')) LIKE '%' + LOWER(@searchText) + '%'
        )
),

Paginated AS (
    SELECT *
    FROM Filtered
    ORDER BY DesignColorMatchingFormID DESC
    OFFSET @offset ROWS FETCH NEXT @pageSize ROWS ONLY
)

SELECT DCMFM.*,DEFM.DesignerCode,DEFM.DesignNo,DEFM.TotalCard,DEFM.PickOnLoom,WQ.WarpQuality,DCM.DesignCategory,DCMD.MatchingNo,
    DCMD.MatchingID,
    DCMD.Warp1,DCMD.Warp2,DCMD.Warp3,DCMD.Warp4,DCMD.Warp5,DCMD.Warp6,DCMD.Warp7,DCMD.Warp8,DCMD.Warp9,DCMD.Warp10,
    DCMD.Feeder1,DCMD.Feeder2,DCMD.Feeder3,DCMD.Feeder4,DCMD.Feeder5,DCMD.Feeder6,DCMD.Feeder7,DCMD.Feeder8,DCMD.Feeder9,DCMD.Feeder10,
    DCMD.Feeder11,DCMD.Feeder12,DCMD.Feeder13,DCMD.Feeder14,DCMD.Feeder15,DCMD.Feeder16,DCMD.Feeder17,DCMD.Feeder18,DCMD.Feeder19,DCMD.Feeder20,
    DCMD.Feeder21,DCMD.Feeder22,DCMD.Feeder23,DCMD.Feeder24,DCMD.Feeder25,DCMD.Feeder26,DCMD.Feeder27,DCMD.Feeder28,DCMD.Feeder29,DCMD.Feeder30,
    P.ValidationStatus

FROM Paginated P
JOIN DesignColorMatchingFormMaster DCMFM 
    ON DCMFM.DesignColorMatchingFormID = P.DesignColorMatchingFormID

LEFT JOIN DesignColorMatchingDetails DCMD
    ON DCMFM.DesignColorMatchingFormID = DCMD.DesignColorMatchingFormID

LEFT JOIN DesignEntryFormMaster DEFM 
    ON DEFM.DesignEntryFormID = DCMFM.DesignEntryFormID

LEFT JOIN WarpQualityMaster WQ 
    ON WQ.WarpQualityID = DEFM.WarpQualityID

LEFT JOIN DesignCategoryMaster DCM 
    ON DCM.DesignCategoryID = DEFM.DesignCategoryID
";

                    SqlCommand cmd = new SqlCommand(query, con);
                    cmd.Parameters.Add("@offset", SqlDbType.Int).Value = offset;
                    cmd.Parameters.Add("@pageSize", SqlDbType.Int).Value = pageSize;
                    cmd.Parameters.Add("@validationStatus", SqlDbType.VarChar).Value = validationStatus ?? "";
                    cmd.Parameters.Add("@searchText", SqlDbType.VarChar).Value = searchText ?? "";

                    SqlDataAdapter da = new SqlDataAdapter(cmd);
                    DataTable dt = new DataTable();
                    da.Fill(dt);

                    Dictionary<int, string> yarnColorMap = new Dictionary<int, string>();
                    try
                    {
                        using (SqlCommand cmdY = new SqlCommand("SELECT YarnColorID, YarnColor FROM YarnColorMaster", con))
                        {
                            if (con.State != ConnectionState.Open) con.Open();
                            using (SqlDataReader rdr = cmdY.ExecuteReader())
                            {
                                while (rdr.Read())
                                {
                                    if (rdr["YarnColorID"] != DBNull.Value && rdr["YarnColor"] != DBNull.Value)
                                    {
                                        int cid = Convert.ToInt32(rdr["YarnColorID"]);
                                        string cname = rdr["YarnColor"].ToString().Trim();
                                        if (!string.IsNullOrEmpty(cname))
                                        {
                                            yarnColorMap[cid] = cname;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    catch { }
                    finally
                    {
                        if (con.State == ConnectionState.Open) con.Close();
                    }

                    var list = new List<Dictionary<string, object>>();

                    foreach (DataRow row in dt.Rows)
                    {
                        var dict = new Dictionary<string, object>();
                        foreach (DataColumn col in dt.Columns)
                        {
                            dict[col.ColumnName] = row[col];
                        }

                        List<string> warpNameList = new List<string>();
                        for (int w = 1; w <= 10; w++)
                        {
                            string colKey = "Warp" + w;
                            if (dict.ContainsKey(colKey) && dict[colKey] != null && dict[colKey] != DBNull.Value)
                            {
                                int cid = 0;
                                string rawVal = dict[colKey].ToString().Trim();
                                if (int.TryParse(rawVal, out cid) && cid > 0)
                                {
                                    string colorName = yarnColorMap.ContainsKey(cid) ? yarnColorMap[cid] : rawVal;
                                    dict[colKey] = colorName;
                                    if (!string.IsNullOrEmpty(colorName) && colorName != "0")
                                    {
                                        warpNameList.Add(colorName);
                                    }
                                }
                                else if (!string.IsNullOrEmpty(rawVal) && rawVal != "0")
                                {
                                    warpNameList.Add(rawVal);
                                }
                            }
                        }
                        dict["WarpValues"] = string.Join(", ", warpNameList);

                        List<string> feederNameList = new List<string>();
                        for (int f = 1; f <= 30; f++)
                        {
                            string colKey = "Feeder" + f;
                            if (dict.ContainsKey(colKey) && dict[colKey] != null && dict[colKey] != DBNull.Value)
                            {
                                int cid = 0;
                                string rawVal = dict[colKey].ToString().Trim();
                                if (int.TryParse(rawVal, out cid) && cid > 0)
                                {
                                    string colorName = yarnColorMap.ContainsKey(cid) ? yarnColorMap[cid] : rawVal;
                                    dict[colKey] = colorName;
                                    if (!string.IsNullOrEmpty(colorName) && colorName != "0")
                                    {
                                        feederNameList.Add(colorName);
                                    }
                                }
                                else if (!string.IsNullOrEmpty(rawVal) && rawVal != "0")
                                {
                                    feederNameList.Add(rawVal);
                                }
                            }
                        }
                        dict["FeederValues"] = string.Join(", ", feederNameList);

                        list.Add(dict);
                    }

                    // =========================
                    // 🔹 COUNT QUERY
                    // =========================
                    string countQuery = @"
WITH FormStatus AS (
    SELECT 
        DCMFM.DesignColorMatchingFormID,
        DCMFM.DesignEntryFormID,
        CASE 
            WHEN COUNT(d.DesignColorMatchingDetailsID) > 0 THEN 'Validated'
            ELSE 'Not Validated'
        END AS ValidationStatus
    FROM DesignColorMatchingFormMaster DCMFM
    LEFT JOIN DesignColorMatchingDetails d 
        ON d.DesignColorMatchingFormID = DCMFM.DesignColorMatchingFormID
        AND ISNULL(d.ColorMatchingPhoto,'') <> ''
    GROUP BY DCMFM.DesignColorMatchingFormID, DCMFM.DesignEntryFormID
),

Filtered AS (
    SELECT FS.*
    FROM FormStatus FS
    LEFT JOIN DesignEntryFormMaster DEFM 
        ON DEFM.DesignEntryFormID = FS.DesignEntryFormID

    WHERE 
        (@validationStatus = '' OR FS.ValidationStatus = @validationStatus)
        AND (
            @searchText = '' OR
            LOWER(ISNULL(DEFM.DesignNo,'')) LIKE '%' + LOWER(@searchText) + '%' OR
            LOWER(ISNULL(DEFM.DesignerCode,'')) LIKE '%' + LOWER(@searchText) + '%' OR
            LOWER(ISNULL(DEFM.DesignNo,'') + ISNULL(DEFM.DesignerCode,'')) LIKE '%' + LOWER(@searchText) + '%'
        )
)

SELECT 
    COUNT(*) AS TotalRecords,
    SUM(CASE WHEN ValidationStatus = 'Validated' THEN 1 ELSE 0 END) AS ValidatedCount,
    SUM(CASE WHEN ValidationStatus = 'Not Validated' THEN 1 ELSE 0 END) AS NotValidatedCount
FROM Filtered
";

                    SqlCommand countCmd = new SqlCommand(countQuery, con);
                    countCmd.Parameters.Add("@validationStatus", SqlDbType.VarChar).Value = validationStatus ?? "";
                    countCmd.Parameters.Add("@searchText", SqlDbType.VarChar).Value = searchText ?? "";

                    if (con.State != ConnectionState.Open) con.Open();
                    SqlDataReader reader = countCmd.ExecuteReader();

                    int total = 0, validated = 0, notValidated = 0;

                    if (reader.Read())
                    {
                        total = Convert.ToInt32(reader["TotalRecords"]);
                        validated = Convert.ToInt32(reader["ValidatedCount"]);
                        notValidated = Convert.ToInt32(reader["NotValidatedCount"]);
                    }

                    con.Close();

                    return new
                    {
                        Success = true,
                        Message = "Data loaded successfully",
                        Data = list,
                        TotalRecords = total,
                        ValidatedCount = validated,
                        NotValidatedCount = notValidated
                    };
                }
            }
            catch (Exception ex)
            {
                return new
                {
                    Success = false,
                    Message = ex.Message
                };
            }
        }
        [WebMethod]
        public void ClosePO(int id)
        {
            string UserAccountId = Context.Request.Cookies["UserIDs"].Value.Split('=')[1];
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();

                SqlTransaction trans = con.BeginTransaction();

                try
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.Transaction = trans;
                    // ✅ 1. Update Inward Master
                    cmd.CommandText = @"UPDATE YarnInwardMaster SET IsComplete = 1 WHERE YarnPODetailIDCompanyCode = @Code";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@Code", id);
                    cmd.ExecuteNonQuery();

                    // ✅ 2. Update PO Details (Close)
                    cmd.CommandText = @"UPDATE YarnPODetails SET IsClose = 1,IsCloseDateTime = GETDATE(),IsCloseUserID = @UserID  WHERE YarnPODetailID = @Code";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@Code", id);
                    cmd.Parameters.AddWithValue("@UserID", UserAccountId);
                    cmd.ExecuteNonQuery();
                    trans.Commit();
                }
                catch (Exception ex)
                {
                    // ❌ Rollback if error
                    trans.Rollback();
                    throw;
                }
            }
        }
        [WebMethod]
        public void ReopenPO(int id)
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();
                SqlTransaction tran = con.BeginTransaction();
                try
                {
                    // Update YarnPODetails
                    SqlCommand cmd = new SqlCommand(@"             UPDATE YarnPODetails
                SET IsClose = 0,
                    IsCloseDateTime = NULL,
                    IsCloseUserID = NULL
                WHERE YarnPODetailID = @id", con, tran);

                    cmd.Parameters.AddWithValue("@id", id);
                    cmd.ExecuteNonQuery();

                    // Update YarnInwardMaster
                    SqlCommand cmd2 = new SqlCommand(@"
                UPDATE YarnInwardMaster
                SET IsComplete = 0
                WHERE YarnPODetailIDCompanyCode = @id", con, tran);

                    cmd2.Parameters.AddWithValue("@id", id);
                    cmd2.ExecuteNonQuery();

                    tran.Commit();
                }
                catch
                {
                    tran.Rollback();
                    throw;
                }
            }
        }
        [WebMethod]
        public object ExportPDF(List<int> yarnPOIds)
        {
            if (yarnPOIds == null || yarnPOIds.Count == 0)
            {
                AuditLogHelper.LogValidationError("Yarn PO PDF", "YarnPOMaster", null, "No Yarn PO IDs provided for PDF export.");
                return new
                {
                    Status = false,
                    Message = "No Yarn PO IDs selected for PDF generation.",
                    FilePath = ""
                };
            }

            try
            {
                string folderPath = HttpContext.Current.Server.MapPath("~/GeneratedPDF/");

                if (!Directory.Exists(folderPath))
                {
                    Directory.CreateDirectory(folderPath);
                }

                string fileName = "PurchaseOrder_" + DateTime.Now.ToString("yyyyMMddHHmmss") + ".pdf";
                string fullPath = System.IO.Path.Combine(folderPath, fileName);

                List<byte[]> pdfBytesList = new List<byte[]>();

                foreach (int poId in yarnPOIds)
                {
                    try
                    {
                        var data = GetYarnPODataForPDF_DB(poId);
                        if (data == null || data.Count == 0)
                        {
                            continue;
                        }

                        Microsoft.Reporting.WebForms.LocalReport report = new Microsoft.Reporting.WebForms.LocalReport();
                        string reportPath = HttpContext.Current.Server.MapPath("~/Reports/PurchaseOrder.rdlc");
                        if (!File.Exists(reportPath))
                        {
                            AuditLogHelper.LogError("Yarn PO PDF", "ExportPDF", new FileNotFoundException($"RDLC report not found: {reportPath}"), poId.ToString());
                            continue;
                        }

                        report.ReportPath = reportPath;
                        report.EnableExternalImages = true;
                        report.DataSources.Clear();

                        Microsoft.Reporting.WebForms.ReportDataSource dsMaster = new Microsoft.Reporting.WebForms.ReportDataSource("Master", data);
                        report.DataSources.Add(dsMaster);

                        var detailData = data.SelectMany(x => x.listYarnPODetails).ToList();
                        Microsoft.Reporting.WebForms.ReportDataSource dsDetail = new Microsoft.Reporting.WebForms.ReportDataSource("OrderDetails", detailData);
                        report.DataSources.Add(dsDetail);
                        report.Refresh();

                        string mimeType, encoding, extension;
                        string[] streamids;
                        Microsoft.Reporting.WebForms.Warning[] warnings;
                        byte[] bytes = report.Render("PDF", null, out mimeType, out encoding, out extension, out streamids, out warnings);
                        if (bytes != null && bytes.Length > 0)
                        {
                            pdfBytesList.Add(bytes);
                        }
                    }
                    catch (Exception exInner)
                    {
                        AuditLogHelper.LogError("Yarn PO PDF", "ExportPDF_SingleItem", exInner, poId.ToString());
                    }
                }

                if (pdfBytesList.Count == 0)
                {
                    AuditLogHelper.LogValidationError("Yarn PO PDF", "YarnPOMaster", string.Join(",", yarnPOIds), "No valid PDF data could be rendered for the selected PO IDs.");
                    return new
                    {
                        Status = false,
                        Message = "No valid data available to generate PDF for the selected PO(s).",
                        FilePath = ""
                    };
                }

                using (FileStream stream = new FileStream(fullPath, FileMode.Create))
                {
                    using (Document document = new Document())
                    {
                        PdfCopy pdfCopy = new PdfCopy(document, stream);
                        document.Open();

                        foreach (byte[] pdfBytes in pdfBytesList)
                        {
                            if (pdfBytes != null && pdfBytes.Length > 0)
                            {
                                PdfReader reader = new PdfReader(pdfBytes);
                                for (int i = 1; i <= reader.NumberOfPages; i++)
                                {
                                    PdfImportedPage page = pdfCopy.GetImportedPage(reader, i);
                                    pdfCopy.AddPage(page);
                                }
                                reader.Close();
                            }
                        }

                        document.Close();
                    }
                }

                string filePath = HttpContext.Current.Request.Url.GetLeftPart(UriPartial.Authority) + "/GeneratedPDF/" + fileName;
                return new
                {
                    Status = true,
                    Message = "PDF Generated Successfully",
                    FilePath = filePath
                };
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Yarn PO PDF", "ExportPDF", ex, string.Join(",", yarnPOIds));
                return new
                {
                    Status = false,
                    Message = "Error generating PDF: " + ex.Message,
                    FilePath = ""
                };
            }
        }
        [WebMethod]
        public object SaleOrderReport(List<int> saleOrderID)
        {
            List<string> individualPdfFiles = new List<string>();

            try
            {
                // ============================================================
                // 1. VALIDATE SALE ORDER IDS
                // ============================================================

                if (saleOrderID == null || saleOrderID.Count == 0)
                {
                    return new
                    {
                        Status = false,
                        Message = "No Sale Order Selected.",
                        FilePath = ""
                    };
                }


                // ============================================================
                // 2. GENERATED PDF FOLDER
                // ============================================================

                string generatedFolder =
                    HttpContext.Current.Server.MapPath("~/GeneratedPDF/");

                if (!Directory.Exists(generatedFolder))
                {
                    Directory.CreateDirectory(generatedFolder);
                }


                // ============================================================
                // 3. FINAL MERGED PDF NAME
                // ============================================================

                string fileName =
                    "SaleOrder_Merged_" +
                    DateTime.Now.ToString("yyyyMMddHHmmss") +
                    "_" +
                    Guid.NewGuid().ToString("N") +
                    ".pdf";

                string pdfPath =
                    Path.Combine(generatedFolder, fileName);


                // ============================================================
                // 4. CRYSTAL REPORT PATH
                // ============================================================

                string reportPath =
                    HttpContext.Current.Server.MapPath(
                        "~/Reports/SaleOrder(17-08-2026).rpt"
                    );

                if (!File.Exists(reportPath))
                {
                    throw new Exception(
                        "SaleOrder Report not found : " + reportPath
                    );
                }


                // ============================================================
                // 5. CONNECTION STRING
                // ============================================================

                string connectionString =
                    ConfigurationManager
                        .ConnectionStrings["sqlconnstr"]
                        .ConnectionString;


                // ============================================================
                // 6. SQL CONNECTION
                // ============================================================

                using (SqlConnection con =
                       new SqlConnection(connectionString))
                {
                    con.Open();


                    // ========================================================
                    // 7. EACH SALE ORDER
                    // ========================================================

                    foreach (int orderId in saleOrderID)
                    {
                        DataSet ds = new DataSet();


                        // ====================================================
                        // 7.1 MASTER
                        // ====================================================

                        using (SqlCommand cmd =
                               new SqlCommand(
                                   "SPR_GetSaleOrder",
                                   con))
                        {
                            cmd.CommandType =
                                CommandType.StoredProcedure;

                            cmd.Parameters.Add(
                                "@SaleOrderID",
                                SqlDbType.Int
                            ).Value = orderId;

                            using (SqlDataAdapter da =
                                   new SqlDataAdapter(cmd))
                            {
                                da.Fill(
                                    ds,
                                    "SaleOrderMaster"
                                );
                            }
                        }


                        // ====================================================
                        // 7.2 DETAILS
                        // ====================================================

                        using (SqlCommand cmd =
                               new SqlCommand(
                                   "SPR_GetSaleOrderDetails",
                                   con))
                        {
                            cmd.CommandType =
                                CommandType.StoredProcedure;

                            cmd.Parameters.Add(
                                "@SaleOrderID",
                                SqlDbType.Int
                            ).Value = orderId;

                            using (SqlDataAdapter da =
                                   new SqlDataAdapter(cmd))
                            {
                                da.Fill(
                                    ds,
                                    "SaleOrderDetails"
                                );
                            }
                        }


                        // ====================================================
                        // 7.3 ADDITIONAL CHARGES
                        // ====================================================

                        using (SqlCommand cmd =
                               new SqlCommand(
                                   "SPR_GetSaleOrderAdditionalCharges",
                                   con))
                        {
                            cmd.CommandType =
                                CommandType.StoredProcedure;

                            cmd.Parameters.Add(
                                "@SaleOrderID",
                                SqlDbType.Int
                            ).Value = orderId;

                            using (SqlDataAdapter da =
                                   new SqlDataAdapter(cmd))
                            {
                                da.Fill(
                                    ds,
                                    "SaleOrderAdditionalCharges"
                                );
                            }
                        }


                        // ====================================================
                        // 8. VALIDATE TABLES
                        // ====================================================

                        if (!ds.Tables.Contains(
                                "SaleOrderMaster") ||
                            ds.Tables["SaleOrderMaster"].Rows.Count == 0)
                        {
                            continue;
                        }


                        if (!ds.Tables.Contains(
                                "SaleOrderDetails") ||
                            ds.Tables["SaleOrderDetails"].Rows.Count == 0)
                        {
                            continue;
                        }


                        if (!ds.Tables.Contains(
                                "SaleOrderAdditionalCharges"))
                        {
                            ds.Tables.Add(
                                new DataTable(
                                    "SaleOrderAdditionalCharges"
                                )
                            );
                        }


                        // ====================================================
                        // 9. AMOUNT IN WORDS
                        // ====================================================

                        DataTable master =
                            ds.Tables["SaleOrderMaster"];

                        if (!master.Columns.Contains(
                                "AmountInWords"))
                        {
                            master.Columns.Add(
                                "AmountInWords",
                                typeof(string)
                            );
                        }


                        decimal netAmount = 0;

                        if (master.Rows[0]["NetAmount"] != DBNull.Value)
                        {
                            netAmount =
                                Convert.ToDecimal(
                                    master.Rows[0]["NetAmount"]
                                );
                        }


                        master.Rows[0]["AmountInWords"] =
                            NumberToWordsHelper.ConvertAmount(
                                netAmount
                            );


                        // ====================================================
                        // 10. DETAILS & IMAGE PATH RESOLUTION
                        // ====================================================

                        DataTable details =
                            ds.Tables["SaleOrderDetails"];


                        if (!details.Columns.Contains(
                                "PhotoOfDesign"))
                        {
                            throw new Exception(
                                "PhotoOfDesign column is missing in " +
                                "SPR_GetSaleOrderDetails."
                            );
                        }


                        if (!details.Columns.Contains(
                                "ImagePath"))
                        {
                            throw new Exception(
                                "ImagePath column is missing in " +
                                "SPR_GetSaleOrderDetails."
                            );
                        }


                        foreach (DataRow row in details.Rows)
                        {
                            try
                            {
                                string photoPath = "";

                                if (row["PhotoOfDesign"] != DBNull.Value)
                                {
                                    photoPath =
                                        Convert.ToString(
                                            row["PhotoOfDesign"]
                                        ).Trim();
                                }


                                if (string.IsNullOrWhiteSpace(photoPath))
                                {
                                    row["ImagePath"] = "";
                                    continue;
                                }


                                string fileNameOnly =
                                    Path.GetFileName(
                                        photoPath.Replace(
                                            "/",
                                            "\\"
                                        )
                                    );


                                if (string.IsNullOrWhiteSpace(
                                        fileNameOnly))
                                {
                                    row["ImagePath"] = "";
                                    continue;
                                }


                                // =================================================
                                // LOCAL PHYSICAL IMAGE PATH
                                // =================================================

                                string physicalPath =
                                    Path.Combine(
                                        @"E:\DesktopSoftwares\NikunjTextile\NikunjTextile",
                                        photoPath
                                    );


                                row["ImagePath"] =
                                    physicalPath;
                            }
                            catch
                            {
                                row["ImagePath"] = "";
                            }
                        }


                        // ====================================================
                        // 11. CRYSTAL REPORT GENERATION
                        // ====================================================

                        ReportDocument report =
                            new ReportDocument();


                        try
                        {
                            // =================================================
                            // 11.1 LOAD MAIN REPORT
                            // =================================================

                            report.Load(
                                reportPath,
                                OpenReportMethod.OpenReportByTempCopy
                            );


                            // =================================================
                            // 11.2 SET DATABASE LOGIN
                            // Main report + subreports
                            // =================================================

                            SetCrystalDatabaseLogin(
                                report,
                                connectionString
                            );


                            // =================================================
                            // 11.3 MAIN REPORT DATA
                            // =================================================

                            report.SetDataSource(ds);


                            // =================================================
                            // 11.4 FIND ALL SUBREPORTS
                            // =================================================

                            for (
                                int sectionIndex = 0;
                                sectionIndex <
                                    report.ReportDefinition.Sections.Count;
                                sectionIndex++)
                            {
                                CrystalDecisions
                                    .CrystalReports
                                    .Engine.Section section =
                                        report.ReportDefinition
                                              .Sections[sectionIndex];


                                if (section == null)
                                {
                                    continue;
                                }


                                for (
                                    int objectIndex = 0;
                                    objectIndex <
                                        section.ReportObjects.Count;
                                    objectIndex++)
                                {
                                    ReportObject obj = null;


                                    try
                                    {
                                        obj =
                                            section.ReportObjects[
                                                objectIndex
                                            ];
                                    }
                                    catch
                                    {
                                        continue;
                                    }


                                    if (!(obj is SubreportObject))
                                    {
                                        continue;
                                    }


                                    SubreportObject subReportObj =
                                        (SubreportObject)obj;


                                    string subReportName =
                                        subReportObj.SubreportName ?? "";


                                    try
                                    {
                                        // =============================================
                                        // OPEN SUBREPORT
                                        // =============================================

                                        ReportDocument subReport =
                                            report.OpenSubreport(
                                                subReportName
                                            );


                                        // =============================================
                                        // SET DATABASE LOGIN
                                        // =============================================

                                        SetCrystalDatabaseLogin(
                                            subReport,
                                            connectionString
                                        );


                                        // =================================================
                                        // COLORS SUBREPORT
                                        //
                                        // IMPORTANT:
                                        //
                                        // Do NOT use:
                                        //
                                        // subReport.SetDataSource(ds);
                                        //
                                        // because COLORS subreport is connected to:
                                        //
                                        // SPR_GetSaleOrderColors
                                        //
                                        // Parameter:
                                        //
                                        // @DetailID
                                        //
                                        // Crystal Subreport Link will pass:
                                        //
                                        // Main Report DetailID
                                        //          ↓
                                        //       @DetailID
                                        // =================================================

                                        if (
                                            subReportName.IndexOf(
                                                "COLORS",
                                                StringComparison
                                                    .OrdinalIgnoreCase
                                            ) >= 0
                                        )
                                        {
                                            // Nothing else required here.
                                            //
                                            // Crystal will use:
                                            //
                                            // SPR_GetSaleOrderColors(@DetailID)
                                            //
                                            // based on Subreport Link.

                                            continue;
                                        }


                                        // =================================================
                                        // DETAILS SUBREPORT
                                        // =================================================

                                        if (
                                            subReportName.IndexOf(
                                                "Detail",
                                                StringComparison
                                                    .OrdinalIgnoreCase
                                            ) >= 0
                                        )
                                        {
                                            if (
                                                ds.Tables.Contains(
                                                    "SaleOrderDetails")
                                            )
                                            {
                                                subReport.SetDataSource(
                                                    ds.Tables[
                                                        "SaleOrderDetails"
                                                    ]
                                                );
                                            }

                                            continue;
                                        }


                                        // =================================================
                                        // ADDITIONAL CHARGES SUBREPORT
                                        // =================================================

                                        if (
                                            subReportName.IndexOf(
                                                "Charge",
                                                StringComparison
                                                    .OrdinalIgnoreCase
                                            ) >= 0
                                        )
                                        {
                                            if (
                                                ds.Tables.Contains(
                                                    "SaleOrderAdditionalCharges")
                                            )
                                            {
                                                subReport.SetDataSource(
                                                    ds.Tables[
                                                        "SaleOrderAdditionalCharges"
                                                    ]
                                                );
                                            }

                                            continue;
                                        }


                                        // =================================================
                                        // OTHER SUBREPORT
                                        // =================================================

                                        if (
                                            ds.Tables.Contains(
                                                "SaleOrderMaster")
                                        )
                                        {
                                            subReport.SetDataSource(
                                                ds.Tables[
                                                    "SaleOrderMaster"
                                                ]
                                            );
                                        }
                                    }
                                    catch (Exception subEx)
                                    {
                                        throw new Exception(
                                            "Subreport binding failed. " +
                                            "Subreport : " +
                                            subReportName +
                                            " | SaleOrderID : " +
                                            orderId +
                                            " | Error : " +
                                            subEx.Message,
                                            subEx
                                        );
                                    }
                                }
                            }


                            // ====================================================
                            // 12. MAIN REPORT PARAMETER
                            //
                            // ONLY SaleOrderID IS SET FROM C#
                            //
                            // @DetailID IS NOT SET HERE.
                            //
                            // Crystal Subreport Link handles DetailID.
                            // ====================================================

                            try
                            {
                                report.SetParameterValue(
                                    "@SaleOrderID",
                                    orderId
                                );
                            }
                            catch
                            {
                                try
                                {
                                    report.SetParameterValue(
                                        "SaleOrderID",
                                        orderId
                                    );
                                }
                                catch
                                {
                                    // Ignore if parameter is not available
                                }
                            }


                            // ====================================================
                            // IMPORTANT
                            //
                            // DO NOT CALL:
                            //
                            // report.Refresh();
                            //
                            // because Refresh can ask again for parameters
                            // and can break the subreport link behaviour.
                            // ====================================================


                            // ====================================================
                            // 13. EXPORT PDF
                            // ====================================================

                            string singlePdfName =
                                "SaleOrder_" +
                                orderId +
                                "_" +
                                Guid.NewGuid().ToString("N") +
                                ".pdf";


                            string singlePdfPath =
                                Path.Combine(
                                    generatedFolder,
                                    singlePdfName
                                );


                            report.ExportToDisk(
                                ExportFormatType.PortableDocFormat,
                                singlePdfPath
                            );


                            // ====================================================
                            // 14. CHECK PDF
                            // ====================================================

                            if (!File.Exists(singlePdfPath))
                            {
                                throw new Exception(
                                    "PDF was not generated for " +
                                    "SaleOrderID : " +
                                    orderId
                                );
                            }


                            individualPdfFiles.Add(
                                singlePdfPath
                            );
                        }
                        finally
                        {
                            // ====================================================
                            // CLOSE REPORT
                            // ====================================================

                            try
                            {
                                report.Close();
                            }
                            catch
                            {
                            }


                            try
                            {
                                report.Dispose();
                            }
                            catch
                            {
                            }


                            GC.Collect();
                            GC.WaitForPendingFinalizers();
                        }
                    }
                }


                // ============================================================
                // 15. CHECK GENERATED FILES
                // ============================================================

                if (individualPdfFiles.Count == 0)
                {
                    return new
                    {
                        Status = false,
                        Message =
                            "No PDF generated for selected Sale Orders.",
                        FilePath = ""
                    };
                }


                // ============================================================
                // 16. MERGE ALL PDFs
                // ============================================================

                using (Document document = new Document())
                {
                    using (
                        FileStream fs =
                            new FileStream(
                                pdfPath,
                                FileMode.Create
                            )
                    )
                    {
                        using (
                            PdfCopy copy =
                                new PdfCopy(
                                    document,
                                    fs
                                )
                        )
                        {
                            document.Open();


                            foreach (
                                string file
                                in individualPdfFiles
                            )
                            {
                                using (
                                    PdfReader reader =
                                        new PdfReader(file)
                                )
                                {
                                    copy.AddDocument(
                                        reader
                                    );
                                }
                            }


                            document.Close();
                        }
                    }
                }


                // ============================================================
                // 17. DELETE INDIVIDUAL TEMPORARY PDFs
                // ============================================================

                foreach (
                    string file
                    in individualPdfFiles
                )
                {
                    try
                    {
                        if (File.Exists(file))
                        {
                            File.Delete(file);
                        }
                    }
                    catch
                    {
                    }
                }


                // ============================================================
                // 18. FINAL SUCCESS RESPONSE
                // ============================================================

                string filePath =
                    HttpContext.Current
                        .Request
                        .Url
                        .GetLeftPart(
                            UriPartial.Authority
                        )
                    + "/GeneratedPDF/"
                    + fileName
                    + "?v="
                    + DateTime.Now.Ticks;


                return new
                {
                    Status = true,
                    Message =
                        "Sale Order PDF Generated Successfully.",
                    FilePath = filePath
                };
            }
            catch (Exception ex)
            {
                // ============================================================
                // ERROR CLEANUP
                // ============================================================

                foreach (
                    string file
                    in individualPdfFiles
                )
                {
                    try
                    {
                        if (File.Exists(file))
                        {
                            File.Delete(file);
                        }
                    }
                    catch
                    {
                    }
                }


                return new
                {
                    Status = false,
                    Message = ex.ToString(),
                    FilePath = ""
                };
            }
        }
        private DataSet FetchProductionOrderDataSet(SqlConnection con, long orderId)
        {
            DataSet ds = new DataSet();

            // 1. Stored Procedure: GetProductionOrderQuality
            try
            {
                using (SqlCommand cmd = new SqlCommand("GetProductionOrderQuality", con))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = orderId;
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        DataTable dt1 = new DataTable("GetProductionOrderQuality");
                        da.Fill(dt1);
                        ds.Tables.Add(dt1);

                        DataTable dt1_1 = dt1.Copy();
                        dt1_1.TableName = "GetProductionOrderQuality;1";
                        ds.Tables.Add(dt1_1);
                    }
                }
            }
            catch (Exception exSp1)
            {
                System.Diagnostics.Debug.WriteLine("GetProductionOrderQuality SP error: " + exSp1.Message);
            }

            // 2. Stored Procedure: GetProductionOrderQualityDetails
            try
            {
                using (SqlCommand cmd = new SqlCommand("GetProductionOrderQualityDetails", con))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = orderId;
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        DataTable dt2 = new DataTable("GetProductionOrderQualityDetails");
                        da.Fill(dt2);
                        ds.Tables.Add(dt2);

                        DataTable dt2_1 = dt2.Copy();
                        dt2_1.TableName = "GetProductionOrderQualityDetails;1";
                        ds.Tables.Add(dt2_1);
                    }
                }
            }
            catch (Exception exSp2)
            {
                System.Diagnostics.Debug.WriteLine("GetProductionOrderQualityDetails SP error: " + exSp2.Message);
            }

            // 3. Fallback / Direct Table Data
            try
            {
                using (SqlCommand cmd = new SqlCommand("SELECT * FROM ProductionOrderMaster WHERE ProductionOrderID = @ProductionOrderID AND IsActive = 1", con))
                {
                    cmd.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = orderId;
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        DataTable dtM = new DataTable("ProductionOrderMaster");
                        da.Fill(dtM);
                        ds.Tables.Add(dtM);
                    }
                }

                DataTable dtD = new DataTable("ProductionOrderDetail");
                using (SqlCommand cmd = new SqlCommand("SELECT * FROM ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID AND ISNULL(IsActive, 1) = 1 ORDER BY ProductionOrderDetailID ASC", con))
                {
                    cmd.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = orderId;
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        da.Fill(dtD);
                        if (ds.Tables.Contains("ProductionOrderDetail"))
                            ds.Tables.Remove("ProductionOrderDetail");
                        ds.Tables.Add(dtD);
                    }
                }

                int spDetailRowCount = ds.Tables.Contains("GetProductionOrderQualityDetails") ? ds.Tables["GetProductionOrderQualityDetails"].Rows.Count : 0;
                if (spDetailRowCount < dtD.Rows.Count)
                {
                    string directDetailQuery = @"
                        SELECT 
                            pod.ProductionOrderDetailID,
                            pod.ProductionOrderID,
                            pod.SalesOrderID,
                            pod.SalesOrderDetailID,
                            pod.SubDetailID,
                            ISNULL(pod.SalesOrderNo, '') AS SalesOrderNo,
                            ISNULL(pod.SlipNo, '') AS SlipNo,
                            ISNULL(pod.Barcode, '') AS Barcode,
                            pod.OrderDate,
                            pod.PartyID,
                            ISNULL(pod.PartyName, pom.PartyName) AS PartyName,
                            pod.DesignEntryFormID,
                            ISNULL(pod.DesignNo, '') AS DesignNo,
                            pod.ColourMatchingID,
                            ISNULL(pod.ColourMatchingName, CAST(pod.ColourMatchingID AS NVARCHAR)) AS ColourMatchingName,
                            ISNULL(pod.WarpQuality, '') AS WarpQuality,
                            ISNULL(pod.WeftQuality, '') AS WeftQuality,
                            ISNULL(pod.PCS, 0) AS PCS,
                            ISNULL(pod.ProductionPCS, 0) AS ProductionPCS,
                            ISNULL(pod.PendingPCS, 0) AS PendingPCS,
                            ISNULL(pod.ShortPCS, 0) AS ShortPCS,
                            CASE WHEN ISNULL(pod.ShortPCS, 0) > 0 THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END AS IsClosed,
                            ISNULL(pod.SalesRate, 0) AS SalesRate,
                            ISNULL(pom.JobRate, 0) AS JobRate,
                            ISNULL(pom.PanaRepeat, 0) AS PanaRepeat,
                            ISNULL(pom.ProductionOrderNo, '') AS ProductionOrderNo,
                            pom.ProductionOrderDate,
                            ISNULL(pom.JobWorkerID, 0) AS JobWorkerID,
                            ISNULL(pom.JobWorkerName, '') AS JobWorkerName
                        FROM ProductionOrderDetail pod
                        LEFT JOIN ProductionOrderMaster pom ON pod.ProductionOrderID = pom.ProductionOrderID
                        WHERE pod.ProductionOrderID = @ProductionOrderID 
                          AND ISNULL(pod.IsActive, 1) = 1
                        ORDER BY pod.ProductionOrderDetailID ASC";

                    using (SqlCommand cmdDirect = new SqlCommand(directDetailQuery, con))
                    {
                        cmdDirect.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = orderId;
                        using (SqlDataAdapter daDirect = new SqlDataAdapter(cmdDirect))
                        {
                            DataTable dtDirect = new DataTable("GetProductionOrderQualityDetails");
                            daDirect.Fill(dtDirect);

                            if (ds.Tables.Contains("GetProductionOrderQualityDetails"))
                                ds.Tables.Remove("GetProductionOrderQualityDetails");
                            ds.Tables.Add(dtDirect);

                            DataTable dtDirect_1 = dtDirect.Copy();
                            dtDirect_1.TableName = "GetProductionOrderQualityDetails;1";
                            if (ds.Tables.Contains("GetProductionOrderQualityDetails;1"))
                                ds.Tables.Remove("GetProductionOrderQualityDetails;1");
                            ds.Tables.Add(dtDirect_1);
                        }
                    }
                }
            }
            catch (Exception exYarnSp)
            {
                System.Diagnostics.Debug.WriteLine("GetProductionOrderQualityDetails SP error: " + exYarnSp.Message);
            }
            // 4. Stored Procedure / Fallback: GetProductionOrderQualityYarn
            try
            {
                using (SqlCommand cmd = new SqlCommand("GetProductionOrderQualityYarn", con))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = orderId;
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        DataTable dtYarn = new DataTable("GetProductionOrderQualityYarn");
                        da.Fill(dtYarn);

                        if (dtYarn.Rows.Count > 0)
                        {
                            ds.Tables.Add(dtYarn);

                            DataTable dtYarn1 = dtYarn.Copy();
                            dtYarn1.TableName = "GetProductionOrderQualityYarn;1";
                            ds.Tables.Add(dtYarn1);

                            DataTable dtYarnOld = dtYarn.Copy();
                            dtYarnOld.TableName = "GetProductionOrderYarnTotal";
                            ds.Tables.Add(dtYarnOld);

                            DataTable dtYarnOld1 = dtYarn.Copy();
                            dtYarnOld1.TableName = "GetProductionOrderYarnTotal;1";
                            ds.Tables.Add(dtYarnOld1);
                        }
                    }
                }
            }
            catch (Exception exYarnSp)
            {
                System.Diagnostics.Debug.WriteLine("GetProductionOrderQualityYarn SP error: " + exYarnSp.Message);
            }

            if (!ds.Tables.Contains("GetProductionOrderYarnTotal") || ds.Tables["GetProductionOrderYarnTotal"].Rows.Count == 0)
            {
                string yarnTotalFallbackSql = @"
                    SELECT 
                        POD.ProductionOrderID,
                        POD.ProductionOrderDetailID,
                        POD.DesignNo,
                        DEWD.YarnMaterialID,
                        YMM.YarnMaterial,
                        SUM(ISNULL(POD.PCS, 0)) AS TotalPCS,
                        SUM(ISNULL(DEWD.Pick, 0)) AS TotalPicks
                    FROM ProductionOrderDetail POD
                    LEFT JOIN DesignEntryFormMaster DEFM ON POD.DesignNo = DEFM.DesignerCode
                    LEFT JOIN DesignEntryWeftData DEWD ON DEFM.DesignEntryFormID = DEWD.DesignEntryFormID
                    LEFT JOIN YarnMaterialMaster YMM ON DEWD.YarnMaterialID = YMM.YarnMaterialID
                    WHERE POD.ProductionOrderID = @ProductionOrderID
                      AND ISNULL(POD.IsActive, 1) = 1
                    GROUP BY POD.ProductionOrderID, POD.ProductionOrderDetailID, POD.DesignNo, DEWD.YarnMaterialID, YMM.YarnMaterial;";

                try
                {
                    using (SqlCommand cmdYarnFallback = new SqlCommand(yarnTotalFallbackSql, con))
                    {
                        cmdYarnFallback.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = orderId;
                        using (SqlDataAdapter daYarn = new SqlDataAdapter(cmdYarnFallback))
                        {
                            DataTable dtYarnFb = new DataTable("GetProductionOrderYarnTotal");
                            daYarn.Fill(dtYarnFb);

                            if (ds.Tables.Contains("GetProductionOrderYarnTotal"))
                                ds.Tables.Remove("GetProductionOrderYarnTotal");
                            ds.Tables.Add(dtYarnFb);

                            DataTable dtYarnFb1 = dtYarnFb.Copy();
                            dtYarnFb1.TableName = "GetProductionOrderYarnTotal;1";
                            if (ds.Tables.Contains("GetProductionOrderYarnTotal;1"))
                                ds.Tables.Remove("GetProductionOrderYarnTotal;1");
                            ds.Tables.Add(dtYarnFb1);
                        }
                    }
                }
                catch (Exception exYarnFb)
                {
                    System.Diagnostics.Debug.WriteLine("GetProductionOrderYarnTotal fallback query error: " + exYarnFb.Message);
                }
            }

            return ds;
        }
        private void EnsureYarnColorColumn(DataTable dt)
        {
            if (dt == null) return;

            if (dt.Columns.Contains("YarnColor1") && !dt.Columns.Contains("YarnColor"))
            {
                try { dt.Columns["YarnColor1"].ColumnName = "YarnColor"; } catch { }
            }

            if (!dt.Columns.Contains("YarnColor"))
            {
                dt.Columns.Add("YarnColor", typeof(string));
            }

            foreach (DataRow r in dt.Rows)
            {
                if (r["YarnColor"] == DBNull.Value || string.IsNullOrWhiteSpace(r["YarnColor"].ToString()))
                {
                    if (dt.Columns.Contains("ColourMatchingName") && r["ColourMatchingName"] != DBNull.Value)
                    {
                        r["YarnColor"] = r["ColourMatchingName"].ToString();
                    }
                }
            }
        }
        private DataSet FetchProductionSlipDataSet(SqlConnection con, long reqId)
        {
            DataSet ds = new DataSet();
            long detailId = reqId;
            int subMachineNo = 0;
            decimal subPcs = 0;
            string subProdDate = "";

            try
            {
                using (SqlCommand cmdCheck = new SqlCommand(@"
                    SELECT ISNULL(POSD.ProductionOrderDetailID, 0) AS ProductionOrderDetailID, 
                           ISNULL(POSD.MachineNumber, 0) AS MachineNumber, 
                           ISNULL(POSD.PCS, 0) AS PCS, 
                           CONVERT(varchar(10), POSD.ProductionDate, 103) AS ProductionDate
                    FROM ProductionOrderSubDetail POSD
                    WHERE POSD.ProductionOrderSubDetailID = @ReqID AND ISNULL(POSD.IsActive, 1) = 1", con))
                {
                    cmdCheck.Parameters.AddWithValue("@ReqID", reqId);
                    using (SqlDataReader drCheck = cmdCheck.ExecuteReader())
                    {
                        if (drCheck.Read())
                        {
                            long pDetailId = Convert.ToInt64(drCheck["ProductionOrderDetailID"]);
                            if (pDetailId > 0)
                            {
                                detailId = pDetailId;
                                subMachineNo = Convert.ToInt32(drCheck["MachineNumber"]);
                                subPcs = Convert.ToDecimal(drCheck["PCS"]);
                                subProdDate = drCheck["ProductionDate"].ToString();
                            }
                        }
                    }
                }
            }
            catch (Exception exSubCheck)
            {
                System.Diagnostics.Debug.WriteLine("FetchProductionSlipDataSet subdetail check error: " + exSubCheck.Message);
            }

            // 1. Stored Procedure: GetProductionOrderWeaverSlip
            try
            {
                using (SqlCommand cmd = new SqlCommand("GetProductionOrderWeaverSlip", con))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.Parameters.Add("@ProductionOrderSubDetailID", SqlDbType.BigInt).Value = reqId;


                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        DataTable dtW = new DataTable("GetProductionOrderWeaverSlip");
                        da.Fill(dtW);

                        EnsureYarnColorColumn(dtW);

                        if (dtW.Rows.Count > 0)
                        {
                            ds.Tables.Add(dtW);
                            DataTable dtW1 = dtW.Copy();
                            dtW1.TableName = "GetProductionOrderWeaverSlip;1";
                            ds.Tables.Add(dtW1);
                        }
                    }
                }
            }
            catch (Exception exW)
            {
                System.Diagnostics.Debug.WriteLine("GetProductionOrderWeaverSlip SP error: " + exW.Message);
            }

            // 1B. Fallback if empty
            if (!ds.Tables.Contains("GetProductionOrderWeaverSlip"))
            {
                string fallbackSql = @"
                    SELECT 
                        POD.ProductionOrderDetailID,
                        POD.ProductionOrderID,
                        POD.SlipNo,
                        POD.DesignNo,
                        POD.ColourMatchingName,
                        POD.PCS,
                        POD.ProductionPCS,
                        POD.RepRate,
                        POD.OrderDate,
                        POM.ProductionOrderNo,
                        POM.ProductionOrderDate,
                        ISNULL(POD.PartyName, ISNULL(POM.Traders, '')) AS Traders,
                        ISNULL(POD.ColourMatchingName, '') AS YarnColor,
                        POM.JobWorkerID,
                        POM.JobWorkerName
                    FROM ProductionOrderDetail POD
                    LEFT JOIN ProductionOrderMaster POM ON POD.ProductionOrderID = POM.ProductionOrderID
                    WHERE (POD.ProductionOrderDetailID = @ProductionOrderDetailID)
                      AND ISNULL(POD.IsActive,1) = 1;";

                using (SqlCommand cmd = new SqlCommand(fallbackSql, con))
                {
                    cmd.Parameters.Add("@ProductionOrderDetailID", SqlDbType.BigInt).Value = detailId;
                    cmd.Parameters.Add("@ReqID", SqlDbType.BigInt).Value = reqId;
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        DataTable dtF = new DataTable("GetProductionOrderWeaverSlip");
                        da.Fill(dtF);

                        EnsureYarnColorColumn(dtF);

                        ds.Tables.Add(dtF);

                        DataTable dtF1 = dtF.Copy();
                        dtF1.TableName = "GetProductionOrderWeaverSlip;1";
                        ds.Tables.Add(dtF1);
                    }
                }
            }

            // 2. Subreport Data: WeftDetails / GetProductionOrderWeftDetails / GetProductionOrderYarnTotal
            try
            {
                using (SqlCommand cmd = new SqlCommand("GetProductionOrderWeaverSlip", con))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.Parameters.Add("@ProductionOrderSubDetailID", SqlDbType.BigInt).Value = reqId;
                    //cmd.Parameters.Add("@ProductionOrderDetailID", SqlDbType.BigInt).Value = detailId;

                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        DataTable dtWeft = new DataTable("WeftDetails");
                        da.Fill(dtWeft);
                        if (dtWeft.Rows.Count > 0)
                        {
                            ds.Tables.Add(dtWeft);
                            DataTable dtWeft1 = dtWeft.Copy();
                            dtWeft1.TableName = "WeftDetails;1";
                            ds.Tables.Add(dtWeft1);

                            DataTable dtWeftSP = dtWeft.Copy();
                            dtWeftSP.TableName = "GetProductionOrderWeftDetails";
                            ds.Tables.Add(dtWeftSP);

                            DataTable dtWeftSP1 = dtWeft.Copy();
                            dtWeftSP1.TableName = "GetProductionOrderWeftDetails;1";
                            ds.Tables.Add(dtWeftSP1);
                        }
                    }
                }
            }
            catch (Exception exW1)
            {
                System.Diagnostics.Debug.WriteLine("GetProductionOrderYarnTotal SP error: " + exW1.Message);
            }

            try
            {
                if (!ds.Tables.Contains("WeftDetails"))
                {
                    using (SqlCommand cmd = new SqlCommand("GetProductionOrderYarnTotal", con))
                    {
                        cmd.CommandType = CommandType.StoredProcedure;
                        cmd.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt).Value = reqId;

                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            DataTable dtYarn = new DataTable("GetProductionOrderYarnTotal");
                            da.Fill(dtYarn);
                            if (dtYarn.Rows.Count > 0)
                            {
                                ds.Tables.Add(dtYarn);
                                DataTable dtYarn1 = dtYarn.Copy();
                                dtYarn1.TableName = "GetProductionOrderYarnTotal;1";
                                ds.Tables.Add(dtYarn1);

                                DataTable dtWeft = dtYarn.Copy();
                                dtWeft.TableName = "WeftDetails";
                                ds.Tables.Add(dtWeft);

                                DataTable dtWeft1 = dtYarn.Copy();
                                dtWeft1.TableName = "WeftDetails;1";
                                ds.Tables.Add(dtWeft1);
                            }
                        }
                    }
                }
            }
            catch (Exception exW2)
            {
                System.Diagnostics.Debug.WriteLine("GetProductionOrderYarnTotal SP error: " + exW2.Message);
            }

            // Fallback SQL query for WeftDetails subreport
            if (!ds.Tables.Contains("WeftDetails") || ds.Tables["WeftDetails"].Rows.Count == 0)
            {
                string fallbackWeftSql = @"
                    SELECT 
                        DEWD.DesignEntryWeftID,
                        DEWD.DesignEntryFormID,
                        DEWD.Card,
                        DEWD.Pick,
                        DEWD.YarnMaterialID,
                        YMM.YarnMaterial,
                        DEWD.DesignSpecificationID,
                        DSM.DesignSpecification
                    FROM ProductionOrderDetail POD
                    LEFT JOIN DesignEntryFormMaster DEFM ON POD.DesignNo = DEFM.DesignerCode
                    LEFT JOIN DesignEntryWeftData DEWD ON DEFM.DesignEntryFormID = DEWD.DesignEntryFormID
                    LEFT JOIN YarnMaterialMaster YMM ON DEWD.YarnMaterialID = YMM.YarnMaterialID
                    LEFT JOIN DesignSpecificationMaster DSM ON DEWD.DesignSpecificationID = DSM.DesignSpecificationID
                    WHERE POD.ProductionOrderDetailID = @ProductionOrderDetailID
                      AND ISNULL(POD.IsActive, 1) = 1;";

                try
                {
                    using (SqlCommand cmd = new SqlCommand(fallbackWeftSql, con))
                    {
                        cmd.Parameters.Add("@ProductionOrderDetailID", SqlDbType.BigInt).Value = detailId;
                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            DataTable dtFallbackWeft = new DataTable("WeftDetails");
                            da.Fill(dtFallbackWeft);

                            if (ds.Tables.Contains("WeftDetails")) ds.Tables.Remove("WeftDetails");
                            ds.Tables.Add(dtFallbackWeft);

                            DataTable dtFallbackWeft1 = dtFallbackWeft.Copy();
                            dtFallbackWeft1.TableName = "WeftDetails;1";
                            if (ds.Tables.Contains("WeftDetails;1")) ds.Tables.Remove("WeftDetails;1");
                            ds.Tables.Add(dtFallbackWeft1);

                            DataTable dtFallbackWeftSP = dtFallbackWeft.Copy();
                            dtFallbackWeftSP.TableName = "GetProductionOrderWeftDetails";
                            if (ds.Tables.Contains("GetProductionOrderWeftDetails")) ds.Tables.Remove("GetProductionOrderWeftDetails");
                            ds.Tables.Add(dtFallbackWeftSP);

                            DataTable dtFallbackWeftSP1 = dtFallbackWeft.Copy();
                            dtFallbackWeftSP1.TableName = "GetProductionOrderWeftDetails;1";
                            if (ds.Tables.Contains("GetProductionOrderWeftDetails;1")) ds.Tables.Remove("GetProductionOrderWeftDetails;1");
                            ds.Tables.Add(dtFallbackWeftSP1);

                            DataTable dtFallbackYarn = dtFallbackWeft.Copy();
                            dtFallbackYarn.TableName = "GetProductionOrderYarnTotal";
                            if (ds.Tables.Contains("GetProductionOrderYarnTotal")) ds.Tables.Remove("GetProductionOrderYarnTotal");
                            ds.Tables.Add(dtFallbackYarn);

                            DataTable dtFallbackYarn1 = dtFallbackWeft.Copy();
                            dtFallbackYarn1.TableName = "GetProductionOrderYarnTotal;1";
                            if (ds.Tables.Contains("GetProductionOrderYarnTotal;1")) ds.Tables.Remove("GetProductionOrderYarnTotal;1");
                            ds.Tables.Add(dtFallbackYarn1);
                        }
                    }
                }
                catch (Exception exFallback)
                {
                    System.Diagnostics.Debug.WriteLine("WeftDetails fallback query error: " + exFallback.Message);
                }
            }

            // 3. ProductionOrderDetail
            using (SqlCommand cmd = new SqlCommand("SELECT * FROM ProductionOrderDetail WHERE ProductionOrderDetailID = @ProductionOrderDetailID AND IsActive = 1", con))
            {
                cmd.Parameters.Add("@ProductionOrderDetailID", SqlDbType.BigInt).Value = detailId;
                using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                {
                    DataTable dtD = new DataTable("ProductionOrderDetail");
                    da.Fill(dtD);
                    ds.Tables.Add(dtD);
                }
            }

            // 4. ProductionOrderMaster
            using (SqlCommand cmd = new SqlCommand(@"
                SELECT POM.*
                FROM ProductionOrderMaster POM
                INNER JOIN ProductionOrderDetail POD ON POM.ProductionOrderID = POD.ProductionOrderID
                WHERE POD.ProductionOrderDetailID = @ProductionOrderDetailID AND POD.IsActive = 1", con))
            {
                cmd.Parameters.Add("@ProductionOrderDetailID", SqlDbType.BigInt).Value = detailId;
                using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                {
                    DataTable dtM = new DataTable("ProductionOrderMaster");
                    da.Fill(dtM);
                    ds.Tables.Add(dtM);
                }
            }

            // If requested via ProductionOrderSubDetailID, override machine number and PCS in the slip data tables
            if (subMachineNo > 0)
            {
                foreach (DataTable dt in ds.Tables)
                {
                    foreach (DataRow row in dt.Rows)
                    {
                        if (dt.Columns.Contains("MachineNumber")) row["MachineNumber"] = subMachineNo;
                        if (dt.Columns.Contains("PCS")) row["PCS"] = subPcs;
                        if (dt.Columns.Contains("ProductionPCS")) row["ProductionPCS"] = subPcs;
                        if (!string.IsNullOrEmpty(subProdDate))
                        {
                            if (dt.Columns.Contains("ProductionDate")) row["ProductionDate"] = subProdDate;
                        }
                    }
                }
            }

            return ds;
        }
        private object GenerateCrystalPdfReportCommon<TId>(List<TId> idList, string rptRelativePath, string pdfPrefix, string parameterName, Func<SqlConnection, TId, DataSet> fetchDataSetFunc,
            Func<SqlConnection, TId, string> getReportPathFunc = null)
        {
            if (idList == null || idList.Count == 0)
            {
                return new { Status = false, Message = "No item selected.", FilePath = "" };
            }

            List<string> individualPdfFiles = new List<string>();

            try
            {
                string generatedFolder = HttpContext.Current.Server.MapPath("~/GeneratedPDF/");
                if (!Directory.Exists(generatedFolder))
                {
                    Directory.CreateDirectory(generatedFolder);
                }

                string fileName = $"{pdfPrefix}_Merged_{DateTime.Now:yyyyMMddHHmmss}_{Guid.NewGuid():N}.pdf";
                string pdfPath = Path.Combine(generatedFolder, fileName);
                string defaultReportPath = !string.IsNullOrEmpty(rptRelativePath) ? HttpContext.Current.Server.MapPath(rptRelativePath) : null;

                string connectionString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(connectionString))
                {
                    con.Open();

                    foreach (TId currentId in idList)
                    {
                        string currentRptRelative = getReportPathFunc != null ? getReportPathFunc(con, currentId) : rptRelativePath;
                        string reportPath = !string.IsNullOrEmpty(currentRptRelative) ? HttpContext.Current.Server.MapPath(currentRptRelative) : defaultReportPath;

                        if (!File.Exists(reportPath))
                        {
                            throw new Exception($"Report file not found : {reportPath}");
                        }

                        DataSet ds = fetchDataSetFunc(con, currentId);

                        if (ds == null || ds.Tables.Count == 0)
                        {
                            throw new Exception(
                                $"No DataSet data found for ID : {currentId}"
                            );
                        }

                        ReportDocument report = new ReportDocument();

                        try
                        {
                            // =====================================================
                            // 1. LOAD REPORT
                            // =====================================================

                            report.Load(
                                reportPath,
                                OpenReportMethod.OpenReportByTempCopy
                            );

                            // =====================================================
                            // 2. APPLY DATABASE LOGIN
                            // =====================================================

                            SetCrystalDatabaseLogin(
                                report,
                                connectionString
                            );

                            // =====================================================
                            // 3. MAIN REPORT DATA
                            // =====================================================

                            report.SetDataSource(ds);

                            // =====================================================
                            // 4. FIND SUBREPORTS
                            // IMPORTANT:
                            // Do NOT use foreach on section.ReportObjects
                            // =====================================================

                            for (
                                int sectionIndex = 0;
                                sectionIndex < report.ReportDefinition.Sections.Count;
                                sectionIndex++)
                            {
                                CrystalDecisions.CrystalReports.Engine.Section section =
                                    report.ReportDefinition.Sections[sectionIndex];

                                if (section == null)
                                    continue;

                                for (
                                    int objectIndex = 0;
                                    objectIndex < section.ReportObjects.Count;
                                    objectIndex++)
                                {
                                    ReportObject obj = null;

                                    try
                                    {
                                        obj = section.ReportObjects[objectIndex];
                                    }
                                    catch (Exception ex)
                                    {
                                        System.Diagnostics.Debug.WriteLine(
                                            "ReportObject read error [" +
                                            sectionIndex +
                                            "," +
                                            objectIndex +
                                            "] : " +
                                            ex.ToString()
                                        );

                                        continue;
                                    }

                                    if (!(obj is SubreportObject))
                                        continue;

                                    SubreportObject subObj =
                                        (SubreportObject)obj;

                                    try
                                    {
                                        // =================================================
                                        // OPEN SUBREPORT
                                        // =================================================

                                        ReportDocument subReport =
                                            report.OpenSubreport(
                                                subObj.SubreportName
                                            );

                                        // =================================================
                                        // APPLY DATABASE LOGIN
                                        // =================================================

                                        SetCrystalDatabaseLogin(
                                            subReport,
                                            connectionString
                                        );

                                        // =================================================
                                        // SET SUBREPORT DATA
                                        // =================================================

                                        subReport.SetDataSource(ds);

                                        // =================================================
                                        // SET SUBREPORT PARAMETER
                                        // =================================================

                                        if (!string.IsNullOrEmpty(parameterName))
                                        {
                                            SetReportParameterValues(
                                                subReport,
                                                parameterName,
                                                currentId
                                            );
                                        }
                                    }
                                    catch (Exception subEx)
                                    {
                                        throw new Exception(
                                            "Subreport binding failed. " +
                                            "Subreport : " +
                                            subObj.SubreportName +
                                            " | ID : " +
                                            currentId +
                                            " | Error : " +
                                            subEx.Message,
                                            subEx
                                        );
                                    }
                                }
                            }

                            // =====================================================
                            // 5. MAIN REPORT PARAMETER
                            // =====================================================

                            if (!string.IsNullOrEmpty(parameterName))
                            {
                                SetReportParameterValues(
                                    report,
                                    parameterName,
                                    currentId
                                );
                            }

                            // =====================================================
                            // IMPORTANT:
                            // DO NOT USE report.Refresh()
                            // =====================================================

                            // report.Refresh();   <-- REMOVE

                            // =====================================================
                            // 6. EXPORT PDF
                            // =====================================================

                            string singlePdfName =
                                $"{pdfPrefix}_{currentId}_{Guid.NewGuid():N}.pdf";

                            string singlePdfPath =
                                Path.Combine(
                                    generatedFolder,
                                    singlePdfName
                                );

                            report.ExportToDisk(
                                ExportFormatType.PortableDocFormat,
                                singlePdfPath
                            );

                            // =====================================================
                            // 7. CHECK PDF
                            // =====================================================

                            if (File.Exists(singlePdfPath))
                            {
                                individualPdfFiles.Add(
                                    singlePdfPath
                                );
                            }
                            else
                            {
                                throw new Exception(
                                    $"PDF was not generated for ID : {currentId}"
                                );
                            }

                            // If exporting ProductionOrder, also append GetProductionOrderYarnTotal.rpt report pages
                            if (pdfPrefix == "ProductionOrder")
                            {
                                try
                                {
                                    // 1. Export GetProductionOrderYarnTotal.rpt
                                    string yarnReportPath = HttpContext.Current.Server.MapPath("~/Reports/GetProductionOrderYarnTotal.rpt");
                                    if (File.Exists(yarnReportPath))
                                    {
                                        ReportDocument yarnRpt = new ReportDocument();
                                        try
                                        {
                                            yarnRpt.Load(yarnReportPath, OpenReportMethod.OpenReportByTempCopy);
                                            DataSet yarnDs = new DataSet();

                                            if (ds.Tables.Contains("GetProductionOrderQualityYarn"))
                                            {
                                                DataTable dtQYarn = ds.Tables["GetProductionOrderQualityYarn"].Copy();
                                                yarnDs.Tables.Add(dtQYarn);

                                                DataTable dtQYarn1 = dtQYarn.Copy();
                                                dtQYarn1.TableName = "GetProductionOrderQualityYarn;1";
                                                yarnDs.Tables.Add(dtQYarn1);
                                            }

                                            if (ds.Tables.Contains("GetProductionOrderYarnTotal"))
                                            {
                                                DataTable dtYarn = ds.Tables["GetProductionOrderYarnTotal"].Copy();
                                                yarnDs.Tables.Add(dtYarn);

                                                DataTable dtYarn1 = dtYarn.Copy();
                                                dtYarn1.TableName = "GetProductionOrderYarnTotal;1";
                                                yarnDs.Tables.Add(dtYarn1);
                                            }

                                            if (ds.Tables.Contains("GetProductionOrderQuality"))
                                            {
                                                DataTable dtM = ds.Tables["GetProductionOrderQuality"].Copy();
                                                yarnDs.Tables.Add(dtM);

                                                DataTable dtM1 = dtM.Copy();
                                                dtM1.TableName = "GetProductionOrderQuality;1";
                                                yarnDs.Tables.Add(dtM1);
                                            }

                                            if (ds.Tables.Contains("ProductionOrderMaster"))
                                            {
                                                DataTable dtPom = ds.Tables["ProductionOrderMaster"].Copy();
                                                yarnDs.Tables.Add(dtPom);
                                            }

                                            yarnRpt.SetDataSource(yarnDs);
                                            foreach (CrystalDecisions.CrystalReports.Engine.Table tbl in yarnRpt.Database.Tables)
                                            {
                                                if (yarnDs.Tables.Contains(tbl.Name))
                                                {
                                                    try { tbl.SetDataSource(yarnDs.Tables[tbl.Name]); } catch { }
                                                }
                                            }

                                            for (int sIdx = 0; sIdx < yarnRpt.ReportDefinition.Sections.Count; sIdx++)
                                            {
                                                CrystalDecisions.CrystalReports.Engine.Section sec = yarnRpt.ReportDefinition.Sections[sIdx];
                                                if (sec == null) continue;
                                                for (int oIdx = 0; oIdx < sec.ReportObjects.Count; oIdx++)
                                                {
                                                    ReportObject rObj = sec.ReportObjects[oIdx];
                                                    if (rObj is SubreportObject sObj)
                                                    {
                                                        try
                                                        {
                                                            ReportDocument subDoc = yarnRpt.OpenSubreport(sObj.SubreportName);
                                                            subDoc.SetDataSource(yarnDs);
                                                            foreach (CrystalDecisions.CrystalReports.Engine.Table sTbl in subDoc.Database.Tables)
                                                            {
                                                                if (yarnDs.Tables.Contains(sTbl.Name))
                                                                {
                                                                    try { sTbl.SetDataSource(yarnDs.Tables[sTbl.Name]); } catch { }
                                                                }
                                                            }
                                                            SetReportParameterValues(subDoc, "@ProductionOrderID", currentId);
                                                        }
                                                        catch { }
                                                    }
                                                }
                                            }

                                            SetReportParameterValues(yarnRpt, "@ProductionOrderID", currentId);

                                            string yarnPdfName = $"YarnTotal_{currentId}_{Guid.NewGuid():N}.pdf";
                                            string yarnPdfPath = Path.Combine(generatedFolder, yarnPdfName);
                                            yarnRpt.ExportToDisk(ExportFormatType.PortableDocFormat, yarnPdfPath);

                                            if (File.Exists(yarnPdfPath))
                                            {
                                                individualPdfFiles.Add(yarnPdfPath);
                                            }
                                        }
                                        catch (Exception exYarnRpt)
                                        {
                                            System.Diagnostics.Debug.WriteLine("GetProductionOrderYarnTotal.rpt export error: " + exYarnRpt.Message);
                                        }
                                        finally
                                        {
                                            try { yarnRpt.Close(); } catch { }
                                            try { yarnRpt.Dispose(); } catch { }
                                        }
                                    }
                                }
                                catch (Exception exYarnFetch)
                                {
                                    System.Diagnostics.Debug.WriteLine("GetProductionOrderYarnTotal export error: " + exYarnFetch.Message);
                                }
                            }
                        }
                        finally
                        {
                            try
                            {
                                report.Close();
                            }
                            catch
                            {
                            }

                            try
                            {
                                report.Dispose();
                            }
                            catch
                            {
                            }

                            GC.Collect();
                            GC.WaitForPendingFinalizers();
                        }
                    }
                }

                if (individualPdfFiles.Count == 0)
                {
                    return new { Status = false, Message = "No PDF generated.", FilePath = "" };
                }

                using (Document document = new Document())
                {
                    using (FileStream fs = new FileStream(pdfPath, FileMode.Create))
                    {
                        using (PdfCopy copy = new PdfCopy(document, fs))
                        {
                            document.Open();
                            foreach (string file in individualPdfFiles)
                            {
                                using (PdfReader reader = new PdfReader(file))
                                {
                                    copy.AddDocument(reader);
                                }
                            }
                            document.Close();
                        }
                    }
                }

                foreach (string file in individualPdfFiles)
                {
                    try { if (File.Exists(file)) File.Delete(file); } catch { }
                }

                string filePath = HttpContext.Current.Request.Url.GetLeftPart(UriPartial.Authority) + "/GeneratedPDF/" + fileName + "?v=" + DateTime.Now.Ticks;
                return new { Status = true, Message = $"{pdfPrefix} PDF Generated Successfully.", FilePath = filePath };
            }
            catch (Exception ex)
            {
                foreach (string file in individualPdfFiles)
                {
                    try { if (File.Exists(file)) File.Delete(file); } catch { }
                }
                return new { Status = false, Message = ex.ToString(), FilePath = "" };
            }
        }
        private void SetReportParameterValues(ReportDocument rpt, string paramName, object val)
        {
            if (rpt == null || string.IsNullOrWhiteSpace(paramName))
                return;

            string cleanName = paramName.StartsWith("@") ? paramName.Substring(1) : paramName;
            string atName = "@" + cleanName;
            try
            {
                rpt.SetParameterValue(paramName, val);
            }
            catch
            {
            }

            try
            {
                rpt.SetParameterValue(cleanName, val);
            }
            catch
            {
            }

            try
            {
                rpt.SetParameterValue(atName, val);
            }
            catch
            {
            }
            try
            {
                if (rpt.DataDefinition != null &&
                    rpt.DataDefinition.ParameterFields != null)
                {
                    foreach (ParameterFieldDefinition pfd
                             in rpt.DataDefinition.ParameterFields)
                    {
                        try
                        {
                            string name = pfd.Name;

                            bool isMatch =
                                name.Equals(
                                    paramName,
                                    StringComparison.OrdinalIgnoreCase)
                                ||
                                name.Equals(
                                    cleanName,
                                    StringComparison.OrdinalIgnoreCase)
                                ||
                                name.Equals(
                                    atName,
                                    StringComparison.OrdinalIgnoreCase)
                                ||
                                name.IndexOf(
                                    "ProductionOrderSubDetailID",
                                    StringComparison.OrdinalIgnoreCase) >= 0
                                ||
                                name.IndexOf(
                                    "SubDetailID",
                                    StringComparison.OrdinalIgnoreCase) >= 0
                                ||
                                name.IndexOf(
                                    "ProductionOrderDetailID",
                                    StringComparison.OrdinalIgnoreCase) >= 0
                                ||
                                name.IndexOf(
                                    "OrderDetailID",
                                    StringComparison.OrdinalIgnoreCase) >= 0;

                            if (isMatch)
                            {
                                rpt.SetParameterValue(name, val);
                            }
                        }
                        catch
                        {
                            // Ignore individual parameter errors
                        }
                    }
                }
            }
            catch
            {
                // Ignore parameter collection errors
            }
        }
