        private int GetPartyId()
        {
            string userId = "0";
            int partyId = 0;

            HttpCookie userCookie = HttpContext.Current.Request.Cookies["UserIDs"];

            if (userCookie != null && !string.IsNullOrWhiteSpace(userCookie.Value))
            {
                string cookieValue = userCookie.Value;

                if (cookieValue.Contains("="))
                    userId = cookieValue.Split('=')[1];
                else
                    userId = cookieValue;
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();

                string query = @"SELECT PartyId FROM UserAccountMaster WHERE UserAccountId = @UserAccountId";

                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.AddWithValue("@UserAccountId", userId);

                    object result = cmd.ExecuteScalar();

                    if (result != null && result != DBNull.Value)
                    {
                        partyId = Convert.ToInt32(result);
                    }
                }
            }

            return partyId;
        }
        private string GetEncryptedLink(string value)
        {
            string encrypted = Encrypt(value);

            // Convert to URL-safe Base64
            return encrypted
                .Replace("+", "-")
                .Replace("/", "_")
                .Replace("=", "");
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string GetJobberDecryptID(string id)
        {
            JavaScriptSerializer js = new JavaScriptSerializer();

            try
            {
                if (string.IsNullOrWhiteSpace(id))
                {
                    return js.Serialize(new
                    {
                        Code = 400,
                        Message = "Invalid ID"
                    });
                }

                // Convert URL-safe Base64 back to normal Base64
                string encrypted = id.Replace("-", "+").Replace("_", "/");

                // Restore Base64 padding
                switch (encrypted.Length % 4)
                {
                    case 2:
                        encrypted += "==";
                        break;

                    case 3:
                        encrypted += "=";
                        break;
                }

                string decryptValue = Decrypt(encrypted);

                string[] arr = decryptValue.Split('|');

                return js.Serialize(new
                {
                    Code = 200,
                    UserAccountId = arr.Length > 0 ? arr[0] : "",
                    OutwardListNo = arr.Length > 1 ? arr[1] : "",
                    PartyId = arr.Length > 2 ? arr[2] : "",
                    OriginalValue = decryptValue
                });
            }
            catch (Exception ex)
            {
                return js.Serialize(new
                {
                    Code = 500,
                    Message = ex.Message
                });
            }
        }
