            INNER JOIN ColorGroupMaster AS CGM
                ON CGM.ColorGroupID =
                   DCMD.ColorGroupID

            WHERE DCMFM.FinancialYearID = (
                SELECT FinancialYearID
                FROM FinancialYearMaster
                WHERE IsDefault = 1
            )

            AND DCMFM.CompanyId = (
                SELECT CompanyId
                FROM CompanyMaster
                WHERE is_default = 1
            )

            AND CGM.ColorGroup IS NOT NULL

            ORDER BY
                DEFM.DesignerCode,
                DEFM.DesignNo,
                DCMD.MatchingNo;";

                using (SqlDataAdapter da =
                    new SqlDataAdapter(query, con))
                {
                    da.Fill(dt);
                }
            }

            // =====================================================
            // CREATE EXCEL
            // =====================================================
            using (XLWorkbook wb = new XLWorkbook())
            {
                IXLWorksheet ws =
                    wb.Worksheets.Add("Design Master");

                // =================================================
                // HEADER
                // =================================================
                ws.Cell(1, 1).Value =
                    "DesignerCode-DesignNo";

                ws.Cell(1, 2).Value =
                    "MatchingID";

                ws.Cell(1, 3).Value =
                    "ColorGroup";

                ws.Cell(1, 4).Value =
                    "PhotoOfDesign";

                // Header formatting
                ws.Range(1, 1, 1, 4)
                    .Style.Font.Bold = true;

                ws.Range(1, 1, 1, 4)
                    .Style.Alignment.Horizontal =
                    XLAlignmentHorizontalValues.Center;

                ws.Range(1, 1, 1, 4)
                    .Style.Alignment.Vertical =
                    XLAlignmentVerticalValues.Center;

                ws.Row(1).Height = 25;

                // =================================================
                // DATA
                // =================================================
                int excelRow = 2;

                foreach (DataRow dr in dt.Rows)
                {
                    // =============================================
                    // DESIGNER CODE
                    // =============================================
                    string designerCode =
                        dr["DesignerCode"] == DBNull.Value
                            ? ""
                            : dr["DesignerCode"]
                                .ToString()
                                .Trim()
                                .ToUpper();

                    // =============================================
                    // DESIGN NO
                    // =============================================
                    string designNo =
                        dr["DesignNo"] == DBNull.Value
                            ? ""
                            : dr["DesignNo"]
                                .ToString()
                                .Trim()
                                .ToUpper();

                    // =============================================
                    // DESIGNER CODE - DESIGN NO
                    // =============================================
                    ws.Cell(excelRow, 1).Value =
                        designerCode + "-" + designNo;

                    // =============================================
                    // MATCHING ID
                    // =============================================
                    ws.Cell(excelRow, 2).Value =
                        dr["MatchingID"] == DBNull.Value
                            ? ""
                            : dr["MatchingID"]
                                .ToString()
                                .Trim()
                                .ToUpper();

                    // =============================================
                    // COLOR GROUP
                    // =============================================
                    ws.Cell(excelRow, 3).Value =
                        dr["ColorGroup"] == DBNull.Value
                            ? ""
                            : dr["ColorGroup"]
                                .ToString()
                                .Trim()
                                .ToUpper();

                    // =================================================
                    // DESIGN IMAGE
                    // =================================================
                    string photoPath = "";

                    if (dr["ColorMatchingPhoto"] != DBNull.Value)
                    {
                        photoPath =
                            dr["ColorMatchingPhoto"]
                                .ToString()
                                .Trim();
                    }

                    if (!string.IsNullOrWhiteSpace(photoPath))
                    {
                        try
                        {
                            // Example DB value:
                            //
                            // COLORMATCHINGPHOTO/YGRKBIRS025-5.BMP
                            //
                            // Get only:
                            //
                            // YGRKBIRS025-5.BMP

                            string fileName =
                                Path.GetFileName(
                                    photoPath.Replace("/", "\\")
                                );

                            // =========================================
                            // ACTUAL IMAGE PATH
                            // =========================================
                            //
                            // E:\Bharat\New folder\weavelanesoft\
                            // ColorMatchingPhoto\
                            //

                            string physicalImagePath =
                                Server.MapPath(
                                    "~/ColorMatchingPhoto/" +
                                    fileName
                                );

                            if (File.Exists(physicalImagePath))
                            {
                                // =====================================
                                // TEMP FOLDER
                                // =====================================
                                string tempFolder =
                                    Server.MapPath(
                                        "~/Uploads/TempDesignImages/"
                                    );

                                if (!Directory.Exists(tempFolder))
                                {
                                    Directory.CreateDirectory(
                                        tempFolder
                                    );
                                }

                                // =====================================
                                // UNIQUE TEMP IMAGE NAME
                                // =====================================
                                string tempFileName =
                                    Guid.NewGuid().ToString("N") +
                                    ".jpg";

                                string tempImagePath =
                                    Path.Combine(
                                        tempFolder,
                                        tempFileName
                                    );

                                // =====================================
                                // RESIZE + COMPRESS IMAGE
                                // =====================================
                                ResizeImageToJpeg(
                                    physicalImagePath,
                                    tempImagePath,
                                    80,
                                    80
                                );

                                // =====================================
                                // ADD SMALL JPEG TO EXCEL
                                // =====================================
                                if (File.Exists(tempImagePath))
                                {
                                    ws.AddPicture(tempImagePath)
                                        .MoveTo(
                                            ws.Cell(
                                                excelRow,
                                                4
                                            )
                                        )
                                        .WithSize(80, 80);

                                    ws.Row(excelRow).Height = 65;

                                    // =================================
                                    // DELETE TEMP FILE
                                    // =================================
                                    try
                                    {
                                        File.Delete(
                                            tempImagePath
                                        );
                                    }
                                    catch
                                    {
                                        // Ignore delete error
                                    }
                                }
                                else
                                {
                                    ws.Cell(
                                        excelRow,
                                        4
                                    ).Value =
                                        "Image Conversion Failed";
                                }
                            }
                            else
                            {
                                ws.Cell(
                                    excelRow,
                                    4
                                ).Value =
                                    "Image Not Found";
                            }
                        }
                        catch (OutOfMemoryException)
                        {
                            // =========================================
                            // BAD / VERY LARGE / CORRUPT IMAGE
                            // =========================================
                            ws.Cell(
                                excelRow,
                                4
                            ).Value =
                                "Image Too Large";
                        }
                        catch (Exception ex)
                        {
                            ws.Cell(
                                excelRow,
                                4
                            ).Value =
                                "Image Error";

                            // For debugging if required:
                            //
                            // ws.Cell(excelRow, 5).Value =
                            //     ex.Message;
                        }
                    }
                    else
                    {
                        ws.Cell(
                            excelRow,
                            4
                        ).Value =
                            "No Image";
                    }

                    excelRow++;
                }

                // =====================================================
                // FORMAT
                // =====================================================

                ws.Column(1).Width = 25;
                ws.Column(2).Width = 30;
                ws.Column(3).Width = 25;
                ws.Column(4).Width = 22;

                if (excelRow > 1)
                {
                    ws.Range(
                        1,
                        1,
                        excelRow - 1,
                        4
                    )
                    .Style
                    .Alignment
                    .Vertical =
                        XLAlignmentVerticalValues.Center;

                    ws.Range(
                        1,
                        1,
                        excelRow - 1,
                        4
                    )
                    .Style
                    .Alignment
                    .WrapText = true;
                }

                // =====================================================
                // FREEZE HEADER
                // =====================================================
                ws.SheetView.FreezeRows(1);

                // =====================================================
                // AUTO FILTER
                // =====================================================
                if (excelRow > 2)
                {
                    ws.Range(
                        1,
                        1,
                        excelRow - 1,
                        4
                    ).SetAutoFilter();
                }

                // =====================================================
                // SAVE EXCEL
                // =====================================================
                string uploadFolder =
                    Server.MapPath("~/Uploads/");

                if (!Directory.Exists(uploadFolder))
                {
                    Directory.CreateDirectory(
                        uploadFolder
                    );
                }

                string excelFileName =
                    "colormaching_" +
                    DateTime.Now.ToString(
                        "yyyyMMddHHmmss"
                    ) +
                    ".xlsx";

                string excelFilePath =
                    Path.Combine(
                        uploadFolder,
                        excelFileName
                    );

                wb.SaveAs(excelFilePath);

                // =====================================================
                // DOWNLOAD
                // =====================================================
                HttpResponse response =
                    HttpContext.Current.Response;

                response.Clear();
                response.ClearHeaders();
                response.ClearContent();

                response.ContentType =
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

                response.AddHeader(
                    "Content-Disposition",
                    "attachment; filename=\"" +
                    excelFileName +
                    "\""
                );

                response.TransmitFile(
                    excelFilePath
                );

                response.Flush();

                HttpContext.Current.ApplicationInstance
                    .CompleteRequest();
            }
        }

        // =============================================================
        // RESIZE + COMPRESS IMAGE
        // =============================================================
        private void ResizeImageToJpeg(string sourcePath, string destinationPath, int maxWidth, int maxHeight)
        {
            using (System.Drawing.Image originalImage =
                System.Drawing.Image.FromFile(sourcePath))
            {
                // =============================================
                // Calculate aspect ratio
                // =============================================
                double ratioX =
                    (double)maxWidth /
                    originalImage.Width;

                double ratioY =
                    (double)maxHeight /
                    originalImage.Height;

                double ratio =
                    Math.Min(
                        ratioX,
                        ratioY
                    );

                int newWidth =
                    Math.Max(
                        1,
                        (int)(
                            originalImage.Width *
                            ratio
                        )
                    );

                int newHeight =
                    Math.Max(
                        1,
                        (int)(
                            originalImage.Height *
                            ratio
                        )
                    );

                // =============================================
                // Create small bitmap
                // =============================================
                using (Bitmap bitmap =
                    new Bitmap(
                        newWidth,
                        newHeight
                    ))
                {
                    using (Graphics graphics =
                        Graphics.FromImage(bitmap))
                    {
                        graphics.CompositingQuality =
                            CompositingQuality.HighQuality;

                        graphics.InterpolationMode =
                            InterpolationMode.HighQualityBicubic;

                        graphics.SmoothingMode =
                            SmoothingMode.HighQuality;

                        graphics.PixelOffsetMode =
                            PixelOffsetMode.HighQuality;

                        graphics.DrawImage(
                            originalImage,
                            0,
                            0,
                            newWidth,
                            newHeight
                        );
                    }

                    // =============================================
                    // JPEG encoder
                    // =============================================
                    ImageCodecInfo jpegCodec = null;

                    ImageCodecInfo[] codecs =
                        ImageCodecInfo.GetImageEncoders();

                    foreach (ImageCodecInfo codec in codecs)
                    {
                        if (codec.FormatID ==
                            System.Drawing.Imaging.ImageFormat.Jpeg.Guid)
                        {
                            jpegCodec = codec;
                            break;
                        }
                    }

                    if (jpegCodec != null)
                    {
                        EncoderParameters encoderParameters =
                            new EncoderParameters(1);

                        encoderParameters.Param[0] =
                            new EncoderParameter(
                                System.Drawing.Imaging.Encoder.Quality,
                                75L
                            );

                        bitmap.Save(
                            destinationPath,
                            jpegCodec,
                            encoderParameters
                        );

                        encoderParameters.Dispose();
                    }
                    else
                    {
                        bitmap.Save(
                            destinationPath,
                            System.Drawing.Imaging.ImageFormat.Jpeg
                        );
                    }
                }
            }
        }
        [WebMethod]
        public string MoveJobberInwardToPending(int JobberInwardID)
        {
            if (JobberInwardID <= 0)
            {
                AuditLogHelper.LogValidationError("Jobber Inward", "JobberInwardMaster", null, "Invalid JobberInwardID.", "JobberInwardID <= 0");
                return "Error: Invalid JobberInwardID";
            }

            string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(connString))
            {
                con.Open();

                using (SqlTransaction transaction = con.BeginTransaction())
                {
                    try
                    {
                        // Capture Old Value Snapshot
                        object oldJobberInward = null;
                        try
                        {
                            using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM JobberInwardMaster WHERE JobberInwardID = @ID", con, transaction))
                            {
                                cmdOld.Parameters.AddWithValue("@ID", JobberInwardID);
                                using (SqlDataReader rdrOld = cmdOld.ExecuteReader())
                                {
                                    if (rdrOld.Read())
                                    {
                                        oldJobberInward = new
                                        {
                                            JobberInwardId = rdrOld["JobberInwardId"],
                                            JobberId = rdrOld["JobberId"],
                                            PartyId = rdrOld["PartyId"],
                                            JobWorkOutwardId = rdrOld["JobWorkOutwardId"],
                                            ChallanNo = rdrOld["ChallanNo"],
                                            TotalWeight = rdrOld["TotalWeight"]
                                        };
                                    }
                                }
                            }
                        }
                        catch { }

                        // 1. Delete Jobber Inward Details
                        using (SqlCommand cmdDetail = new SqlCommand(@"
                    DELETE FROM JobberInwardDetail
                    WHERE JobberInwardID = @JobberInwardID
                ", con, transaction))
                        {
                            cmdDetail.Parameters.AddWithValue("@JobberInwardID", JobberInwardID);
                            cmdDetail.ExecuteNonQuery();
                        }

                        // 2. Delete Jobber Inward Master
                        using (SqlCommand cmdMaster = new SqlCommand(@"
                    DELETE FROM JobberInwardMaster
                    WHERE JobberInwardID = @JobberInwardID
                ", con, transaction))
                        {
                            cmdMaster.Parameters.AddWithValue("@JobberInwardID", JobberInwardID);
                            cmdMaster.ExecuteNonQuery();
                        }

                        AuditLogHelper.Log(
                            module: "Jobber Inward",
                            action: "DELETE",
                            tableName: "JobberInwardMaster",
                            recordId: JobberInwardID.ToString(),
                            description: $"Deleted Jobber Inward ID #{JobberInwardID}",
                            oldValue: oldJobberInward,
                            existingConn: con,
                            existingTran: transaction
                        );

                        transaction.Commit();

                        return "success";
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();
                        AuditLogHelper.LogError("Jobber Inward", "MoveJobberInwardToPending", ex, $"JobberInwardID={JobberInwardID}");

                        return "Error: " + ex.Message;
                    }
                }
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string GetJobberInwardView(int JobberInwardID)
        {
            try
            {
                DataTable dtMaster = new DataTable();
                DataTable dtDetails = new DataTable();

                string connString =
                    ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(connString))
                {
                    con.Open();

                    // =========================================================
                    // MASTER
                    // =========================================================
                    // MASTER
                    // Sender: Outward Godown
                    // Receiver: Party / Jobber
                    // =========================================================

                    string masterQuery = @"
                SELECT
                    JIM.JobberInwardId,
                    JIM.DateAndTime,

                    JIM.JobberId,
                    JIM.PartyId,
                    JIM.JobWorkOutwardId,

                    -- Jobber Challan No
                    ISNULL(NULLIF(JIM.JobberId, ''), ISNULL(YOM.OutwardListNo, '')) AS JobberChallanNo,

                    -- Received Challan No
                    ISNULL(NULLIF(JIM.ChallanNo, ''), ISNULL(CAST(YOM.OutwardListNo AS VARCHAR(50)), '')) AS ReceivedChallanNo,

                    JIM.TotalWeight,
                    JIM.PendingWeight,
                    JIM.POPendingWeight,

                    JIM.GodownID,
                    JIM.PhotoOfInward,
                    JIM.CompanyId,
                    JIM.IsComplete,

                    -- Sender Name
                    ISNULL(OutwardGM.GodownTitle, '') AS SenderName,

                    -- Sender Address
                    CASE
                        WHEN YOM.SundryPartyID = 3
                            THEN ISNULL(JM.BillingAddress, ISNULL(OutwardGM.GodownAddress, ''))
                        WHEN ISNULL(PM.ShippingAddress, '') = ''
                            THEN ISNULL(PM.BillingAddress, ISNULL(OutwardGM.GodownAddress, ''))
                        ELSE ISNULL(PM.ShippingAddress, ISNULL(OutwardGM.GodownAddress, ''))
                    END AS SenderAddress,

                    CASE
                        WHEN YOM.SundryPartyID = 3
                            THEN ISNULL(JM.MobileNumber, '')
                        ELSE ISNULL(PM.MobileNo, '')
                    END AS SenderMobile,

                    -- Receiver Name
                    CASE
                        WHEN YOM.SundryPartyID = 3
                            THEN ISNULL(JM.PartyName, '')
                        ELSE ISNULL(PM.PartyName, '')
                    END AS ReceivedName,

                    -- Receiver Mobile
                    CASE
                        WHEN YOM.SundryPartyID = 3
                            THEN ISNULL(JM.MobileNumber, '')
                        ELSE ISNULL(PM.MobileNo, '')
                    END AS ReceivedMobile,

                    -- Destination Godown
                    ISNULL(InwardGM.GodownTitle, '') AS GodownName

                FROM JobberInwardMaster JIM

                LEFT JOIN YarnOutwardMaster YOM
                    ON YOM.YarnOutwardID = JIM.JobWorkOutwardId

                LEFT JOIN PartyMaster PM
                    ON PM.PartyId = JIM.PartyId
                   AND ISNULL(YOM.SundryPartyID, 0) <> 3

                LEFT JOIN JobberMaster JM
                    ON JM.Id = JIM.PartyId
                   AND YOM.SundryPartyID = 3

                LEFT JOIN CompanyMaster CM
                    ON CM.CompanyId = JIM.CompanyId

                LEFT JOIN GodownMaster OutwardGM
                    ON OutwardGM.GodownID = YOM.GodownID

                LEFT JOIN GodownMaster InwardGM
                    ON InwardGM.GodownID = JIM.GodownID

                WHERE JIM.JobberInwardId = @JobberInwardID;
            ";

                    using (SqlCommand cmd = new SqlCommand(masterQuery, con))
                    {
                        cmd.Parameters.Add("@JobberInwardID", SqlDbType.Int)
                            .Value = JobberInwardID;

                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            da.Fill(dtMaster);
                        }
                    }

                    // =========================================================
                    // DETAILS
                    // =========================================================

                    string detailQuery = @"
                SELECT
                    JID.JobberInwardDetailID,
                    JID.DateAndTime,
                    JID.BoxNo,
                    JID.NetWeight,
                    JID.BarcodeNo,
                    JID.GodownLocationID,
                    JID.JobberInwardID,
                    JID.UserAccountId,
                    JID.YarnInterchangeID,
                    JID.IsScanStutas,
                    JID.IsScanUpdateDateTime,

                    COALESCE(YOSD.YarnMaterial, YIM.YarnMaterialID, 0) AS YarnMaterialID,
                    ISNULL(YMM.YarnMaterial, '') AS YarnMaterial,

                    COALESCE(YOSD.YarnColour, YIM.YarnColorID, 0) AS YarnColorID,
                    ISNULL(YCM.YarnColor, '') AS YarnColor

                FROM JobberInwardDetail JID

                INNER JOIN JobberInwardMaster JIM
                    ON JIM.JobberInwardId = JID.JobberInwardID

                LEFT JOIN YarnOutwardScanMaster YOSM
                    ON YOSM.YarnOutwardID = JIM.JobWorkOutwardId

                LEFT JOIN YarnOutwardScanMasterDetails YOSD
                    ON YOSD.YarnOutwardScanID = YOSM.YarnOutwardScanID
                   AND YOSD.BarcodeNo = JID.BarcodeNo

                LEFT JOIN YarnInwardDetail YID
                    ON YID.BarcodeNo = JID.BarcodeNo

                LEFT JOIN YarnInwardMaster YIM
                    ON YIM.YarnInwardID = YID.YarnInwardID

                LEFT JOIN YarnMaterialMaster YMM
                    ON YMM.YarnMaterialID = COALESCE(YOSD.YarnMaterial, YIM.YarnMaterialID)

                LEFT JOIN YarnColorMaster YCM
                    ON YCM.YarnColorID = COALESCE(YOSD.YarnColour, YIM.YarnColorID)

                WHERE JID.JobberInwardID = @JobberInwardID

                ORDER BY JID.JobberInwardDetailID;
            ";

                    using (SqlCommand cmd = new SqlCommand(detailQuery, con))
                    {
                        cmd.Parameters.Add("@JobberInwardID", SqlDbType.Int)
                            .Value = JobberInwardID;

                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            da.Fill(dtDetails);
                        }
                    }
                }

                if (dtMaster.Rows.Count == 0)
                {
                    return JsonConvert.SerializeObject(new
                    {
                        Status = false,
                        Message = "Jobber Inward not found."
                    });
                }

                return JsonConvert.SerializeObject(new
                {
                    Status = true,
                    Master = dtMaster,
                    Details = dtDetails
                });
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(new
                {
                    Status = false,
                    Message = ex.Message
                });
            }
        }

