        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string GetJobberOutwardView(string JobberOutwardID)
        {
            try
            {
                // ==========================================
                // DECRYPT ID
                // ==========================================

                int outwardId = 0;

                if (!int.TryParse(JobberOutwardID, out outwardId))
                {
                    try
                    {
                        string decryptedId = Decrypt(HttpUtility.UrlDecode(JobberOutwardID));

                        // Split the composite string by '|' (e.g., "22|28|39")
                        string[] idParts = decryptedId.Split('|');

                        // Parse the correct segment (index 1 for YarnOutwardID / JobberOutwardID)
                        if (idParts.Length > 1 && int.TryParse(idParts[1], out outwardId))
                        {
                            // outwardId is successfully populated via the out parameter
                        }
                        else if (idParts.Length == 1 && int.TryParse(idParts[0], out outwardId))
                        {
                            // Fallback if it's just a single ID
                        }
                        else
                        {
                            return JsonConvert.SerializeObject(new
                            {
                                Code = 400,
                                Message = "Invalid Jobber Outward ID format."
                            });
                        }
                    }
                    catch
                    {
                        return JsonConvert.SerializeObject(new
                        {
                            Code = 400,
                            Message = "Invalid encrypted Jobber Outward ID."
                        });
                    }
                }

                string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                DataTable dtMaster = new DataTable();
                DataTable dtDetails = new DataTable();

                using (SqlConnection con = new SqlConnection(connString))
                {
                    con.Open();

                    // ==========================================
                    // MASTER
                    // ==========================================

                    string masterQuery = @"
                                SELECT
                                    JOM.JobberOutwardID,
                                    JOM.DateAndTime,
                                    JOM.GodownID,
                                    JOM.PartyId,
                                    JOM.OutwardListNo,
                                    JOM.OutwardListDate,                
                                    JOM.UserAccountId,
                                    JOM.FinancialYearID,
                                    JOM.CompanyId,
                                    JOM.SundryPartyID,
                                    JOM.TotalWeight,
                                    COALESCE(JM.PartyName, PM.PartyName, '') AS PartyName,
                                    COALESCE(JM.BillingAddress, PM.BillingAddress, '') AS BillingAddress,
                                    COALESCE(JM.MobileNumber, PM.MobileNo, '') AS MobileNo,
                                    COALESCE(NULLIF(CAST(JOM.SundryPartyID AS VARCHAR(10)), '0'), PM.SundryParty, CASE WHEN JM.Id IS NOT NULL THEN '3' ELSE '' END, '') AS SundryParty,
                                    ISNULL(UAM.UserAccountName, '') AS UserAccountName,
                                    ISNULL(UAM.UserAccountMobileNo, '') AS UserAccountMobileNo
                                FROM JobberOutwardMaster JOM
                                LEFT JOIN JobberMaster JM ON JM.Id = JOM.PartyId
                                LEFT JOIN PartyMaster PM ON PM.PartyId = JOM.PartyId
                                LEFT JOIN UserAccountMaster UAM ON UAM.UserAccountId = JOM.UserAccountId
                                WHERE JOM.JobberOutwardID = @JobberOutwardID";

                    using (SqlCommand cmd = new SqlCommand(masterQuery, con))
                    {
                        cmd.Parameters.Add("@JobberOutwardID", SqlDbType.Int).Value = outwardId;
                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            da.Fill(dtMaster);
                        }
                    }

                    // ==========================================
                    // DETAILS
                    // ==========================================

                    string detailQuery = @"
                                SELECT
                                    JOD.JobberOutwardDetailID,
                                    JOD.DateAndTime,
                                    JOD.JobberOutwardID,
                                    JOD.BillToPartyId,
                                    JOD.CompanyPartyId,  
                                    JOD.YarnMaterialID,
                                    JOD.YarnColorID,
                                    JOD.NoOfBox,
                                    JOD.UserAccountId,
                                    JOD.NetWeight,
                                    JOD.BarcodeNo,
                                    JOD.BoxNo,
                                    JOD.YarnPOID,
                                    JOD.DetailsJson, -- <--- ADDED THIS LINE TO SELECT THE JSON TRACKING DATA
                                    YM.YarnMaterial,
                                    YC.YarnColor,
                                    YC.YarnColorCode,
                                    PM.PartyName AS BillToPartyName,
                                    CPM.PartyName AS CompanyPartyName,
                                    ISNULL(JOM.GodownID, 0) AS GodownID
                                FROM JobberOutwardDetail JOD
                                LEFT JOIN JobberOutwardMaster JOM ON JOM.JobberOutwardID = JOD.JobberOutwardID
                                LEFT JOIN YarnMaterialMaster YM ON YM.YarnMaterialID = JOD.YarnMaterialID
                                LEFT JOIN YarnColorMaster YC ON YC.YarnColorID = JOD.YarnColorID
                                LEFT JOIN PartyMaster PM ON PM.PartyId = JOD.BillToPartyId
                                LEFT JOIN PartyMaster CPM ON CPM.PartyId = JOD.CompanyPartyId
                                WHERE JOD.JobberOutwardID = @JobberOutwardID
                                ORDER BY  JOD.JobberOutwardDetailID";

                    using (SqlCommand cmd = new SqlCommand(detailQuery, con))
                    {
                        cmd.Parameters.Add("@JobberOutwardID", SqlDbType.Int).Value = outwardId;
                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            da.Fill(dtDetails);
                        }
                    }
                }

                // ==========================================
                // RESULT
                // ==========================================

                var result = new
                {
                    Code = 200,
                    Message = "Success",

                    Master =
                        DataTableToList(dtMaster),

                    Details =
                        DataTableToList(dtDetails)
                };

                return JsonConvert.SerializeObject(result);
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(new
                {
                    Code = 500,
                    Message = ex.Message
                });
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ServiceResponse insertJobberOutwardMaster(JobberOutwardMasterDTO masterData)
        {
            ServiceResponse response = new ServiceResponse();
            string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            // 1. Initial Validation
            if (masterData == null || masterData.Details == null || masterData.Details.Count == 0)
            {
                AuditLogHelper.LogValidationError("Jobber Outward", "JobberOutwardMaster", null, "No items scanned to save.", "masterData or Details empty", masterData);
                response.Code = 400;
                response.Message = "No items scanned to save.";
                return response;
            }

            // 2. Safe Cookie Processing
            int userAccountId = 0;
            int companyId = 0;

            try
            {
                if (Context.Request.Cookies["UserIDs"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
                {
                    string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                    userAccountId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
                }
                else
                {
                    AuditLogHelper.LogValidationError("Jobber Outward", "JobberOutwardMaster", null, "User session expired. Please log in again.", "UserIDs cookie missing");
                    response.Code = 401;
                    response.Message = "User session expired. Please log in again.";
                    return response;
                }

                if (Context.Request.Cookies["CompanyID"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["CompanyID"].Value))
                {
                    string cookieVal = Context.Request.Cookies["CompanyID"].Value;
                    companyId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
                }
                else
                {
                    AuditLogHelper.LogValidationError("Jobber Outward", "JobberOutwardMaster", null, "Company profile context missing. Please re-login.", "CompanyID cookie missing");
                    response.Code = 401;
                    response.Message = "Company profile context missing. Please re-login.";
                    return response;
                }
            }
            catch (Exception ex)
            {
                AuditLogHelper.LogError("Jobber Outward", "insertJobberOutwardMaster", ex, "Cookie parsing error");
                response.Code = 400;
                response.Message = "Authentication format error: " + ex.Message;
                return response;
            }

            // 3. Database Operations
            using (SqlConnection conn = new SqlConnection(connString))
            {
                conn.Open();
                using (SqlTransaction transaction = conn.BeginTransaction())
                {
                    try
                    {
                        // A. Fetch PartyPrefix, PartyId, and SundryParty
                        string partyPrefix = "";
                        int PartyId = 0;
                        int SundryParty = 0;

                        string getPrefixQuery = "SELECT ISNULL(PM.PartyPrefix, ''), UM.PartyId, PM.SundryParty FROM UserAccountMaster UM LEFT JOIN PartyMaster PM ON PM.PartyId = UM.PartyId WHERE UM.UserAccountId = @PartyId";

                        using (SqlCommand cmdPrefix = new SqlCommand(getPrefixQuery, conn, transaction))
                        {
                            cmdPrefix.Parameters.AddWithValue("@PartyId", userAccountId);

                            using (SqlDataReader reader = cmdPrefix.ExecuteReader())
                            {
                                if (reader.Read())
                                {
                                    partyPrefix = reader.IsDBNull(0) ? "" : reader.GetString(0);
                                    PartyId = reader.IsDBNull(1) ? 0 : Convert.ToInt32(reader.GetValue(1));
                                    SundryParty = reader.IsDBNull(2) ? 0 : Convert.ToInt32(reader.GetValue(2));
                                }
                            }
                        }

                        // Fallback prefix if empty
                        if (string.IsNullOrEmpty(partyPrefix))
                        {
                            partyPrefix = "TR";
                        }

                        // Find the latest sequence number safely across the company context using the prefix block
                        string getMaxSeqQuery = @"SELECT ISNULL(MAX(TRY_CAST(SUBSTRING(OutwardListNo, LEN(@Prefix) + 1, LEN(OutwardListNo)) AS INT)), 0) 
                                        FROM JobberOutwardMaster 
                                        WHERE CompanyId = @CompanyId AND OutwardListNo LIKE @Prefix + '%'";

                        int nextSeq = 1;
                        using (SqlCommand cmdSeq = new SqlCommand(getMaxSeqQuery, conn, transaction))
                        {
                            cmdSeq.Parameters.AddWithValue("@CompanyId", companyId);
                            cmdSeq.Parameters.AddWithValue("@Prefix", partyPrefix);
                            object seqResult = cmdSeq.ExecuteScalar();
                            if (seqResult != null && seqResult != DBNull.Value)
                            {
                                nextSeq = Convert.ToInt32(seqResult) + 1;
                            }
                        }
                        string generatedOutwardListNo = partyPrefix + nextSeq.ToString();

                        // B. Insert into JobberOutwardMaster Table
                        string insertMasterQuery = @"
                    INSERT INTO JobberOutwardMaster 
                    (DateAndTime, GodownID, PartyId, OutwardListNo, OutwardListDate, IsScanStutas, UserAccountId, FinancialYearID, CompanyId, SundryPartyID, TotalWeight) 
                    VALUES 
                    (GETDATE(), @GodownID, @PartyId, @OutwardListNo, @OutwardListDate, 1, @UserAccountId, (SELECT TOP 1 FinancialYearID FROM FinancialYearMaster WHERE IsDefault = 1), @CompanyId, @SundryPartyID, @TotalWeight);
                    SELECT SCOPE_IDENTITY();";

                        int generatedMasterId = 0;
                        int initialGodownId = masterData.Details[0].GodownID;
                        int initialSundryPartyId = SundryParty;
                        DateTime outwardDate = DateTime.Now;
                        if (!string.IsNullOrEmpty(masterData.OutwardListDate))
                        {
                            // Try parsing standard formats safely
                            if (!DateTime.TryParse(masterData.OutwardListDate, out outwardDate))
                            {
                                // Fallback or explicit format check if needed
                                DateTime.TryParseExact(masterData.OutwardListDate, new string[] { "dd/MM/yyyy", "yyyy-MM-dd", "MM/dd/yyyy" }, CultureInfo.InvariantCulture, DateTimeStyles.None, out outwardDate);
                            }
                        }

                        using (SqlCommand cmd = new SqlCommand(insertMasterQuery, conn, transaction))
                        {
                            cmd.Parameters.AddWithValue("@GodownID", initialGodownId);
                            cmd.Parameters.AddWithValue("@PartyId", masterData.PartyId);
                            cmd.Parameters.AddWithValue("@OutwardListNo", generatedOutwardListNo);
                            cmd.Parameters.AddWithValue("@OutwardListDate", outwardDate);
                            cmd.Parameters.AddWithValue("@UserAccountId", userAccountId);
                            cmd.Parameters.AddWithValue("@CompanyId", companyId);
                            cmd.Parameters.AddWithValue("@SundryPartyID", initialSundryPartyId);
                            cmd.Parameters.AddWithValue("@TotalWeight", masterData.TotalWeight);
                            generatedMasterId = Convert.ToInt32(cmd.ExecuteScalar());
                        }

                        // C. Insert rows into JobberOutwardDetail Table
                        string insertDetailQuery = @"
                    INSERT INTO JobberOutwardDetail 
                    (DateAndTime, JobberOutwardID, BillToPartyID, YarnMaterialID, YarnColorID, NoOfBox, UserAccountId, NetWeight, BarcodeNo, BoxNo, CompanyPartyId, YarnPOID, DetailsJson) 
                    VALUES 
                    (GETDATE(), @JobberOutwardID, @BillToPartyID, @YarnMaterialID, @YarnColorID, @NoOfBox, @UserAccountId, @NetWeight, @BarcodeNo, @BoxNo, @CompanyPartyId, @YarnPOID, @DetailsJson);";

                        foreach (var item in masterData.Details)
                        {
                            using (SqlCommand cmdDetail = new SqlCommand(insertDetailQuery, conn, transaction))
                            {
                                cmdDetail.Parameters.AddWithValue("@JobberOutwardID", generatedMasterId);
                                cmdDetail.Parameters.AddWithValue("@BillToPartyID", item.BillToPartyId);
                                cmdDetail.Parameters.AddWithValue("@YarnMaterialID", item.YarnMaterialID);
                                cmdDetail.Parameters.AddWithValue("@YarnColorID", item.YarnColorID);
                                cmdDetail.Parameters.AddWithValue("@NoOfBox", item.NoOfBox > 0 ? item.NoOfBox : 1);
                                cmdDetail.Parameters.AddWithValue("@UserAccountId", userAccountId);
                                cmdDetail.Parameters.AddWithValue("@NetWeight", item.NetWeight);
                                cmdDetail.Parameters.AddWithValue("@BarcodeNo", item.BarcodeNo ?? "");
                                cmdDetail.Parameters.AddWithValue("@BoxNo", item.BoxNo ?? "");
                                cmdDetail.Parameters.AddWithValue("@CompanyPartyId", item.CompanyPartyId);
                                cmdDetail.Parameters.AddWithValue("@YarnPOID", item.YarnPOID);
                                cmdDetail.Parameters.AddWithValue("@DetailsJson", (object)item.DetailsJson ?? DBNull.Value);
                                cmdDetail.ExecuteNonQuery();
                            }
                        }

                        AuditLogHelper.Log(
                            module: "Jobber Outward",
                            action: "CREATE",
                            tableName: "JobberOutwardMaster",
                            recordId: generatedMasterId.ToString(),
                            description: $"Created Jobber Outward (List No: {generatedOutwardListNo})",
                            newValue: masterData,
                            existingConn: conn,
                            existingTran: transaction
                        );

                        transaction.Commit();
                        response.Code = 200;
                        response.Message = "Jobber Outward entry recorded successfully with List No: " + generatedOutwardListNo;
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();
                        AuditLogHelper.LogError("Jobber Outward", "insertJobberOutwardMaster", ex, JsonConvert.SerializeObject(masterData));
                        response.Code = 500;
                        response.Message = "Database Error: " + ex.Message;
                    }
                }
            }
            return response;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string updateJobberOutwardMaster(JobberOutwardMasterDTO masterData)
        {
            if (masterData == null)
            {
                AuditLogHelper.LogValidationError("Jobber Outward", "JobberOutwardMaster", null, "Master data is required.", "masterData is null");
                return JsonConvert.SerializeObject(new { Code = 400, Message = "Master data is required." });
            }

            SqlConnection con = null;
            SqlTransaction transaction = null;

            try
            {
                int userAccountId = 0;
                int companyId = 0;

                if (Context.Request.Cookies["UserIDs"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
                {
                    string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                    userAccountId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
                }
                else
                {
                    AuditLogHelper.LogValidationError("Jobber Outward", "JobberOutwardMaster", null, "User session expired. Please log in again.", "UserIDs cookie missing");
                    return JsonConvert.SerializeObject(new { Code = 401, Message = "User session expired. Please log in again." });
                }

                if (Context.Request.Cookies["CompanyID"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["CompanyID"].Value))
                {
                    string cookieVal = Context.Request.Cookies["CompanyID"].Value;
                    companyId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
                }

                int outwardId = 0;
                if (!string.IsNullOrEmpty(masterData.JobberOutwardEncryptedID))
                {
                    outwardId = Convert.ToInt32(Decrypt(masterData.JobberOutwardEncryptedID));
                }
                else
                {
                    outwardId = masterData.JobberOutwardID;
                }

                if (outwardId <= 0)
                {
                    AuditLogHelper.LogValidationError("Jobber Outward", "JobberOutwardMaster", null, "Invalid Outward ID.", "outwardId <= 0", masterData);
                    return JsonConvert.SerializeObject(new { Code = 400, Message = "Invalid Outward ID." });
                }

                string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                con = new SqlConnection(connString);
                con.Open();
                transaction = con.BeginTransaction();

                // Capture Old Value Snapshot
                object oldJobberOutward = null;
                try
                {
                    using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM JobberOutwardMaster WHERE JobberOutwardID = @ID", con, transaction))
                    {
                        cmdOld.Parameters.AddWithValue("@ID", outwardId);
                        using (SqlDataReader rdrOld = cmdOld.ExecuteReader())
                        {
                            if (rdrOld.Read())
                            {
                                oldJobberOutward = new
                                {
                                    JobberOutwardID = rdrOld["JobberOutwardID"],
                                    GodownID = rdrOld["GodownID"],
                                    PartyId = rdrOld["PartyId"],
                                    OutwardListNo = rdrOld["OutwardListNo"],
                                    OutwardListDate = rdrOld["OutwardListDate"],
                                    TotalWeight = rdrOld["TotalWeight"]
                                };
                            }
                        }
                    }
                }
                catch { }

                // 1. UPDATE MASTER
                string updateMasterQuery = @"
                                            UPDATE JobberOutwardMaster
                                            SET PartyId = @PartyId,
                                                OutwardListNo = @OutwardListNo,
                                                OutwardListDate = @OutwardListDate,
                                                TotalWeight = @TotalWeight,
                                                UserAccountId = @UserAccountId
                                            WHERE JobberOutwardID = @JobberOutwardID";

                using (SqlCommand cmd = new SqlCommand(updateMasterQuery, con, transaction))
                {
                    cmd.Parameters.AddWithValue("@JobberOutwardID", outwardId);
                    cmd.Parameters.AddWithValue("@PartyId", masterData.PartyId);
                    cmd.Parameters.AddWithValue("@OutwardListNo", masterData.OutwardListNo);
                    cmd.Parameters.AddWithValue("@OutwardListDate", Convert.ToDateTime(masterData.OutwardListDate));
                    cmd.Parameters.AddWithValue("@TotalWeight", masterData.TotalWeight);
                    cmd.Parameters.AddWithValue("@UserAccountId", userAccountId);
                    cmd.ExecuteNonQuery();
                }

                // 2. DELETE OLD DETAILS
                string deleteDetailQuery = "DELETE FROM JobberOutwardDetail WHERE JobberOutwardID = @JobberOutwardID";
                using (SqlCommand cmd = new SqlCommand(deleteDetailQuery, con, transaction))
                {
                    cmd.Parameters.AddWithValue("@JobberOutwardID", outwardId);
                    cmd.ExecuteNonQuery();
                }

                // 3. INSERT REVISED DETAILS (Matching exact columns including CompanyPartyId and DetailsJson)
                if (masterData.Details != null && masterData.Details.Count > 0)
                {
                    string insertDetailQuery = @"
            INSERT INTO JobberOutwardDetail
            (DateAndTime,JobberOutwardID, BillToPartyID, YarnMaterialID, YarnColorID, NoOfBox, NetWeight, BarcodeNo, BoxNo, CompanyPartyId, YarnPOID, UserAccountId, DetailsJson)
            VALUES
            (getdate(),@JobberOutwardID, @BillToPartyId, @YarnMaterialID, @YarnColorID, @NoOfBox, @NetWeight, @BarcodeNo, @BoxNo, @CompanyPartyId, @YarnPOID, @UserAccountId, @DetailsJson)";


                    foreach (var item in masterData.Details)
                    {
                        using (SqlCommand cmd = new SqlCommand(insertDetailQuery, con, transaction))
                        {
                            cmd.Parameters.AddWithValue("@JobberOutwardID", outwardId);
                            cmd.Parameters.AddWithValue("@BillToPartyId", item.BillToPartyId);
                            cmd.Parameters.AddWithValue("@YarnMaterialID", item.YarnMaterialID);
                            cmd.Parameters.AddWithValue("@YarnColorID", item.YarnColorID);
                            cmd.Parameters.AddWithValue("@NoOfBox", item.NoOfBox > 0 ? item.NoOfBox : 1);
                            cmd.Parameters.AddWithValue("@NetWeight", item.NetWeight);
                            cmd.Parameters.AddWithValue("@BarcodeNo", item.BarcodeNo ?? "");
                            cmd.Parameters.AddWithValue("@BoxNo", item.BoxNo ?? "");
                            cmd.Parameters.AddWithValue("@CompanyPartyId", item.CompanyPartyId); // Fix: Use item's specific CompanyPartyId instead of masterData.PartyId
                            cmd.Parameters.AddWithValue("@YarnPOID", item.YarnPOID);
                            cmd.Parameters.AddWithValue("@UserAccountId", userAccountId);
                            cmd.Parameters.AddWithValue("@DetailsJson", (object)item.DetailsJson ?? DBNull.Value);

                            cmd.ExecuteNonQuery();
                        }
                    }
                }

                AuditLogHelper.Log(
                    module: "Jobber Outward",
                    action: "UPDATE",
                    tableName: "JobberOutwardMaster",
                    recordId: outwardId.ToString(),
                    description: $"Updated Jobber Outward ID #{outwardId}",
                    oldValue: oldJobberOutward,
                    newValue: masterData,
                    existingConn: con,
                    existingTran: transaction
                );

                transaction.Commit();

                return JsonConvert.SerializeObject(new
                {
                    Code = 200,
                    Message = "Jobber Outward updated successfully."
                });
            }
            catch (Exception ex)
            {
                if (transaction != null)
                {
                    try { transaction.Rollback(); } catch { }
                }
                AuditLogHelper.LogError("Jobber Outward", "updateJobberOutwardMaster", ex, JsonConvert.SerializeObject(masterData));

                return JsonConvert.SerializeObject(new
                {
                    Code = 500,
                    Message = ex.Message
                });
            }
            finally
            {
                if (con != null)
                {
                    con.Close();
                    con.Dispose();
                }
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ServiceResponse DeleteJobberOutwardMaster(int YarnOutwardID)
        {
            ServiceResponse response = new ServiceResponse();

            if (YarnOutwardID <= 0)
            {
                AuditLogHelper.LogValidationError("Jobber Outward", "JobberOutwardMaster", null, "Invalid Jobber Outward ID.", "YarnOutwardID <= 0", YarnOutwardID);
                response.Code = 400;
                response.Message = "Invalid Jobber Outward ID.";
                return response;
            }

            string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection conn = new SqlConnection(connString))
            {
                conn.Open();
                using (SqlTransaction transaction = conn.BeginTransaction())
                {
                    try
                    {
                        // Fetch old record snapshot
                        object oldJobberOutward = null;
                        using (SqlCommand cmdOld = new SqlCommand("SELECT * FROM JobberOutwardMaster WHERE JobberOutwardID = @ID", conn, transaction))
                        {
                            cmdOld.Parameters.AddWithValue("@ID", YarnOutwardID);
                            using (SqlDataReader rdrOld = cmdOld.ExecuteReader())
                            {
                                if (rdrOld.Read())
                                {
                                    oldJobberOutward = new
                                    {
                                        JobberOutwardID = rdrOld["JobberOutwardID"],
                                        PartyId = rdrOld["PartyId"],
                                        OutwardListNo = rdrOld["OutwardListNo"],
                                        OutwardListDate = rdrOld["OutwardListDate"],
                                        TotalWeight = rdrOld["TotalWeight"]
                                    };
                                }
                            }
                        }

                        // 1. Delete child records first to avoid foreign key violation
                        string deleteDetailQuery = "DELETE FROM JobberOutwardDetail WHERE JobberOutwardID = @JobberOutwardID";
                        using (SqlCommand cmdDetail = new SqlCommand(deleteDetailQuery, conn, transaction))
                        {
                            cmdDetail.Parameters.AddWithValue("@JobberOutwardID", YarnOutwardID);
                            cmdDetail.ExecuteNonQuery();
                        }

                        // 2. Delete parent record from JobberOutwardMaster
                        string deleteMasterQuery = "DELETE FROM JobberOutwardMaster WHERE JobberOutwardID = @JobberOutwardID";
                        using (SqlCommand cmdMaster = new SqlCommand(deleteMasterQuery, conn, transaction))
                        {
                            cmdMaster.Parameters.AddWithValue("@JobberOutwardID", YarnOutwardID);
                            cmdMaster.ExecuteNonQuery();
                        }

                        AuditLogHelper.Log(
                            module: "Jobber Outward",
                            action: "DELETE",
                            tableName: "JobberOutwardMaster",
                            recordId: YarnOutwardID.ToString(),
                            description: $"Deleted Jobber Outward ID #{YarnOutwardID}",
                            oldValue: oldJobberOutward,
                            existingConn: conn,
                            existingTran: transaction
                        );

                        transaction.Commit();
                        response.Code = 200;
                        response.Message = "Jobber Outward deleted successfully.";
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();
                        AuditLogHelper.LogError("Jobber Outward", "DeleteJobberOutwardMaster", ex, $"YarnOutwardID={YarnOutwardID}");
                        response.Code = 500;
                        response.Message = "Database Error: " + ex.Message;
                    }
                }
            }
            return response;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object GetPendingOrdersForProduction()
        {
            var orderList = new List<object>();

            try
            {
                string connString =
                    ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                // New mode: 0
                // Edit mode: current ProductionOrderID
                int productionOrderId = 0;

                string productionOrderIdValue =
                    Convert.ToString(HttpContext.Current.Request.Params["ProductionOrderID"]);

                if (string.IsNullOrWhiteSpace(productionOrderIdValue))
                {
                    productionOrderIdValue =
                        Convert.ToString(HttpContext.Current.Request.Params["id"]);
                }

                if (!string.IsNullOrWhiteSpace(productionOrderIdValue))
                {
                    Int32.TryParse(productionOrderIdValue, out productionOrderId);
                }

                string query = @"
            WITH SOD_Seq AS
            (
                SELECT
                    sod.*,
                    DENSE_RANK() OVER
                    (
                        PARTITION BY sod.SaleOrderID
                        ORDER BY sod.DetailID
                    ) AS DesignSeq
                FROM SaleOrderDetails sod
            ),
            SOSD_Seq AS
            (
                SELECT
                    sods.*,
                    ROW_NUMBER() OVER
                    (
                        PARTITION BY sods.DetailID
                        ORDER BY sods.SubDetailID
                    ) AS ColourSeq
                FROM SaleOrderSubDetails sods
            )
            SELECT
                so.SaleOrderID AS SalesOrderID,
                so.OrderNo,
                CONVERT(varchar(10), so.OrderDate, 101) AS OrderDate,
                so.PartyId AS PartyID,
                pm.PartyName,
                sod.DesignNo,
                ISNULL(sods.ColourID, sod.DesignColorMatchingID) AS ColourMatchingID,
                sods.ColourName,

                ISNULL(
                    NULLIF(dcmd.ColorMatchingPhoto, ''),
                    ISNULL(defm.PhotoOfDesign, '')
                ) AS PhotoPath,

                sods.Qty AS TotalOrderPcs,

                ISNULL(prodSum.AlreadyProducedPcs, 0) AS AlreadyProducedPcs,
                ISNULL(prodSum.AlreadyShortPcs, 0) AS AlreadyShortPcs,

                CASE
                    WHEN
                        (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0) - ISNULL(prodSum.AlreadyShortPcs, 0)) < 0
                    THEN 0
                    ELSE
                        (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0) - ISNULL(prodSum.AlreadyShortPcs, 0))
                END AS Pcs,

                CASE
                    WHEN
                        (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0) - ISNULL(prodSum.AlreadyShortPcs, 0)) < 0
                    THEN 0
                    ELSE
                        (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0) - ISNULL(prodSum.AlreadyShortPcs, 0))
                END AS PendingPcs,

                sod.Rate,
                sod.DetailID,
                sods.SubDetailID,
                ISNULL(defm.TotalCard, 0) AS TotalCard,
                ISNULL(defm.PickOnLoom, 0) AS Pick,
                sod.DesignSeq,
                sods.ColourSeq

            FROM SaleOrder so

            INNER JOIN PartyMaster pm
                ON so.PartyId = pm.PartyId

            INNER JOIN SOD_Seq sod
                ON so.SaleOrderID = sod.SaleOrderID

            INNER JOIN SOSD_Seq sods
                ON sod.DetailID = sods.DetailID

            LEFT JOIN DesignColorMatchingDetails dcmd
                ON ISNULL(sods.ColourID, sod.DesignColorMatchingID)
                   = dcmd.DesignColorMatchingDetailsID

            LEFT JOIN
            (
                SELECT
                    ISNULL(pod.SubDetailID, 0) AS SubDetailID,
                    pod.SalesOrderDetailID,
                    ISNULL(SUM(pod.ProductionPCS), 0) AS AlreadyProducedPcs,
                    ISNULL(SUM(ISNULL(pod.ShortPCS, 0)), 0) AS AlreadyShortPcs

                FROM ProductionOrderDetail pod

                INNER JOIN ProductionOrderMaster pom
                    ON pod.ProductionOrderID = pom.ProductionOrderID

                WHERE
                    ISNULL(pod.IsActive, 1) = 1
                    AND ISNULL(pom.IsActive, 1) = 1

                    -- Edit mode: exclude current Production Order.
                    -- New mode: ProductionOrderID = 0, exclude nothing.
                    AND
                    (
                        @ProductionOrderID <= 0
                        OR pom.ProductionOrderID <> @ProductionOrderID
                    )

                GROUP BY
                    pod.SubDetailID,
                    pod.SalesOrderDetailID

            ) prodSum
                ON
                (
                    sods.SubDetailID > 0
                    AND prodSum.SubDetailID = sods.SubDetailID
                )
                OR
                (
                    sods.SubDetailID = 0
                    AND prodSum.SalesOrderDetailID = sod.DetailID
                )

            LEFT JOIN
            (
                SELECT
                    DesignerCode,
                    DesignNo,

                    MAX(
                        CASE
                            WHEN ISNUMERIC(TotalCard) = 1
                            THEN CONVERT(DECIMAL(18,2), TotalCard)
                            ELSE 0
                        END
                    ) AS TotalCard,

                    MAX(
                        CASE
                            WHEN ISNUMERIC(PickOnLoom) = 1
                            THEN CONVERT(DECIMAL(18,2), PickOnLoom)
                            ELSE 0
                        END
                    ) AS PickOnLoom,

                    MAX(ISNULL(PhotoOfDesign, '')) AS PhotoOfDesign

                FROM DesignEntryFormMaster

                GROUP BY DesignerCode, DesignNo

            ) defm
                ON
                LTRIM(RTRIM(
                    CASE
                        WHEN CHARINDEX(' - ', sod.DesignNo) > 0
                        THEN SUBSTRING(
                            sod.DesignNo,
                            1,
                            CHARINDEX(' - ', sod.DesignNo) - 1
                        )
                        ELSE sod.DesignNo
                    END
                )) =
                LTRIM(RTRIM(CONVERT(VARCHAR(100), defm.DesignerCode)))

                AND

                LTRIM(RTRIM(
                    CASE
                        WHEN CHARINDEX(' - ', sod.DesignNo) > 0
                        THEN SUBSTRING(
                            sod.DesignNo,
                            CHARINDEX(' - ', sod.DesignNo) + 3,
                            LEN(sod.DesignNo)
                        )
                        ELSE sod.DesignNo
                    END
                )) =
                LTRIM(RTRIM(CONVERT(VARCHAR(100), defm.DesignNo)))

            WHERE
                (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0) - ISNULL(prodSum.AlreadyShortPcs, 0)) > 0

            ORDER BY
                so.OrderNo,
                sod.DetailID,
                sods.SubDetailID;";

                using (SqlConnection conn = new SqlConnection(connString))
                using (SqlCommand cmd = new SqlCommand(query, conn))
                {
                    cmd.Parameters.Add("@ProductionOrderID", SqlDbType.Int)
                        .Value = productionOrderId;

                    conn.Open();

                    using (SqlDataReader reader = cmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string rawPhoto =
                                reader["PhotoPath"] != DBNull.Value
                                    ? reader["PhotoPath"].ToString().Trim()
                                    : "";

                            string normalizedPhoto = "";

                            if (!string.IsNullOrEmpty(rawPhoto))
                            {
                                string clean = rawPhoto.Replace("\\", "/");

                                if (clean.StartsWith("~/"))
                                    clean = clean.Substring(2);

                                if (!clean.StartsWith("/"))
                                    clean = "/" + clean;

                                normalizedPhoto = clean;
                            }

                            orderList.Add(new
                            {
                                SalesOrderID =
                                    reader["SalesOrderID"] != DBNull.Value
                                        ? reader["SalesOrderID"].ToString()
                                        : null,

                                SalesOrderDetailID =
                                    reader["DetailID"] != DBNull.Value
                                        ? reader["DetailID"].ToString()
                                        : "",

                                PartyID =
                                    reader["PartyID"] != DBNull.Value
                                        ? reader["PartyID"].ToString()
                                        : null,

                                ColourMatchingID =
                                    reader["ColourMatchingID"] != DBNull.Value
                                        ? reader["ColourMatchingID"].ToString()
                                        : null,

                                OrderNo =
                                    reader["OrderNo"] != DBNull.Value
                                        ? reader["OrderNo"].ToString()
                                        : "",

                                OrderDate =
                                    reader["OrderDate"] != DBNull.Value
                                        ? reader["OrderDate"].ToString()
                                        : "",

                                PartyName =
                                    reader["PartyName"] != DBNull.Value
                                        ? reader["PartyName"].ToString()
                                        : "",

                                DesignNo =
                                    reader["DesignNo"] != DBNull.Value
                                        ? reader["DesignNo"].ToString()
                                        : "",

                                ColourName =
                                    reader["ColourName"] != DBNull.Value
                                        ? reader["ColourName"].ToString()
                                        : "",

                                Qty =
                                    reader["Pcs"] != DBNull.Value
                                        ? Convert.ToDecimal(reader["Pcs"])
                                        : 0,

                                Pcs =
                                    reader["Pcs"] != DBNull.Value
                                        ? Convert.ToDecimal(reader["Pcs"])
                                        : 0,

                                TotalOrderPcs =
                                    reader["TotalOrderPcs"] != DBNull.Value
                                        ? Convert.ToDecimal(reader["TotalOrderPcs"])
                                        : 0,

                                AlreadyProducedPcs =
                                    reader["AlreadyProducedPcs"] != DBNull.Value
                                        ? Convert.ToDecimal(reader["AlreadyProducedPcs"])
                                        : 0,

                                PendingPcs =
                                    reader["PendingPcs"] != DBNull.Value
                                        ? Convert.ToDecimal(reader["PendingPcs"])
                                        : 0,

                                Rate =
                                    reader["Rate"] != DBNull.Value
                                        ? Convert.ToDecimal(reader["Rate"])
                                        : 0,

                                DetailID =
                                    reader["DetailID"] != DBNull.Value
                                        ? reader["DetailID"].ToString()
                                        : "",

                                SubDetailID =
                                    reader["SubDetailID"] != DBNull.Value
                                        ? reader["SubDetailID"].ToString()
                                        : "",

                                TotalCard =
                                    reader["TotalCard"] != DBNull.Value
                                        ? Convert.ToDecimal(reader["TotalCard"])
                                        : 0,

                                Pick =
                                    reader["Pick"] != DBNull.Value
                                        ? Convert.ToDecimal(reader["Pick"])
                                        : 0,

                                DesignSeq =
                                    reader["DesignSeq"] != DBNull.Value
                                        ? Convert.ToInt32(reader["DesignSeq"])
                                        : 0,

                                ColourSeq =
                                    reader["ColourSeq"] != DBNull.Value
                                        ? Convert.ToInt32(reader["ColourSeq"])
                                        : 0,

                                PhotoPath = normalizedPhoto,
                                ColorMatchingPhoto = normalizedPhoto
                            });
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine(
                    "GetPendingOrdersForProduction Error: " + ex
                );
            }

            return orderList;
        }
        #region Validation form

         [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object CheckDesignColorMatchingDetails(long id)
        {
            Dictionary<string, object> result = new Dictionary<string, object>();

            try
            {
                using (SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
                {
                    string query = @"
                SELECT
                    CASE
                        WHEN EXISTS
                        (
                            SELECT 1
                            FROM DesignColorMatchingFormMaster DCMFM
                            INNER JOIN DesignColorMatchingDetails DCMD
                                ON DCMD.DesignColorMatchingFormID =
                                   DCMFM.DesignColorMatchingFormID
                            WHERE DCMFM.DesignEntryFormID = @DesignEntryFormID
                              AND (
                                  DCMD.ColorMatchingPhoto IS NOT NULL
                                  OR DCMD.ColorGroupID IS NOT NULL
                                  OR DCMD.UserAccountId IS NOT NULL
                                  OR DCMD.UpdateDateandTime IS NOT NULL
                              )
                        )
                        THEN 0
                        ELSE 1
                    END";

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.Parameters.AddWithValue("@DesignEntryFormID", id);

                        con.Open();

                        bool canEditDelete = Convert.ToInt32(cmd.ExecuteScalar()) == 1;

                        result.Add("Code", 200);
                        result.Add("CanEditDelete", canEditDelete);
                    }
                }
            }
            catch (Exception ex)
            {
                result.Add("Code", 500);
                result.Add("CanEditDelete", false);
                result.Add("Message", ex.Message);
            }

            return result;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object GetProductionOrderSubDetailDetailIDs(long productionOrderID)
        {
            try
            {
                if (productionOrderID <= 0)
                    return new { Status = false, Message = "Invalid Production Order ID.", Data = new List<long>() };

                var ids = new List<long>();

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();
                    EnsureProductionOrderSubDetailTableExists(con);

                    const string sql = @"
                SELECT DISTINCT ProductionOrderDetailID
                FROM dbo.ProductionOrderSubDetail
                WHERE ProductionOrderID = @ProductionOrderID
                  AND ISNULL(IsActive, 1) = 1;";

                    using (SqlCommand cmd = new SqlCommand(sql, con))
                    {
                        cmd.Parameters.Add("@ProductionOrderID", SqlDbType.BigInt)
                            .Value = productionOrderID;

                        using (SqlDataReader dr = cmd.ExecuteReader())
                        {
                            while (dr.Read())
                                ids.Add(Convert.ToInt64(dr["ProductionOrderDetailID"]));
                        }
                    }
                }

                return new { Status = true, Data = ids };
            }
            catch (Exception ex)
            {
                return new { Status = false, Message = ex.Message, Data = new List<long>() };
            }
        }

        #endregion
    }
